The path $\mathcal{P'}_2^{(3)}$ is a specific instance of the path $\mathcal{P'}$ applied to the case when delay nodes are added from $\node{X}_1$ and $\node{X}_2$, and the state of these delay nodes is OFF. The system state is now given in the order $\node{X}_1$, $\node{d}_{1,2}$, $\node{d}_{1,3}$, $\node{X}_2$, $\node{d}_{2,3}$, $\node{X}_3$, $\node{X}_4$. In this case $\mathcal{P'}_2^{(3)}$ is $(000~00~0~0)\rightarrow (100~00~0~0) \rightarrow (000~00~0~0) \rightarrow (000~10~0~0) \rightarrow (000~00~0~0) \rightarrow (000~00~1~0) \rightarrow (000~00~0~0) \rightarrow (000~00~0~1) \rightarrow (000~00~0~0) \rightarrow (100~00~0~0)$. 

\begin{align}
\label{4star_variant2}
\node{X}_1,&~(\bneg \node{X}_1 \band \bneg \node{X}_2 \band \bneg \node{X}_3 \band \bneg \node{X}_4) \bor (\node{X}_1 \band \node{X}_2 \band \node{X}_3 \band \node{X}_4) \nonumber\\
\node{d}_{1,2},&~\node{X}_1 \nonumber\\
\node{X}_2,&~(\bneg \node{d}_{1,2} \band \bneg \node{X}_2 \band \bneg \node{X}_3 \band \bneg \node{X}_4) \bor (\node{d}_{1,2} \band \node{X}_2 \band \node{X}_3 \band \node{X}_4) \nonumber\\
