\begin{algorithm}[H]
\caption{Probability Generating Algorithm (for Case II)}
\begin{algorithmic}[1]
\REQUIRE Historical dataset $D$ (duration data of a parking spot is unoccupied), current number of detections $n$, detection interval $T$, and integer constant $w$ 
\ENSURE  P("1") \\
\STATE$\theta$ = mean($D$) \\
\STATE $y_{2}$ = $\frac{2n-1}{2}T$ 
\STATE$P$("1") = 1 - $P$("0") = $e^{-\frac{y_{2}}{\theta}}$\\
\STATE$\alpha_{0.95}$ = solve($\int^{\alpha_{0.95}}_{ 0 } 1-e^{-\frac{x}{\theta}}dx = 0.95$)
\IF{$y_{2} < \alpha_{0.95}$}
    \STATE $P$("1") = $e^{-\frac{y_{2}}{\theta}}$
    \STATE Output $P$("1")
\ENDIF
\IF{$y_{2} \geq \alpha_{0.95}$}
    \FOR{$(i=1, i\leq w, i=i+1)$}
        \STATE add $n\cdot T $ to $D$
    \ENDFOR
\STATE Algorithm2 (input)
\ENDIF
\end{algorithmic}
\end{algorithm}
