        \end{ytableau}};
        \node at (8, -1.75) {$T_{C_5}$};
    \end{tikzpicture}
\end{center}
Since all entries of $T_{C_3}, T_{C_4}$ and $T_{C_5}$ are greater than 6, we calculate the 6-fold promotion of these tableaux by subtracting 6 from each entry:
\begin{center}
    \begin{tikzpicture}
        \node at (0,0) {\begin{ytableau}
            3 \\
            4 \\
            5 \\
            6
        \end{ytableau}};
        \node at (0, -1.75) {$P^6(T_{C_3})$};
        \node at (2,0) {\ytableausetup{boxsize=0.6cm}\begin{ytableau}
            9 \\
            10 \\
            11 \\
            12
        \end{ytableau}};
        \node at (2,-1.75) {$P^6(T_{C_4})$};
        \node at (4,0) {\begin{ytableau}
            15 \\
            16 \\
            17 \\
            18 \\
        \end{ytableau}};
        \node at (4,-1.75) {$P^6(T_{C_5}).$};
    \end{tikzpicture}
\end{center}
So the equalities $P^6(T_{C_3}) = T_{C_2}, P^6(T_{C_4}) = T_{C_3},$ and $P^6(T_{C_5}) = T_{C_4}$ hold. We now calculate $P^6(T_{C_1})$ and $P^6(T_{C_2})$ using the arguments in Remark \ref{rem:k-fold-component}:
\begin{center}
\begin{tikzpicture}
    \node at (0,0) {\ytableausetup{boxsize=0.6cm}\begin{ytableau}
            1 & 2 \\
            7 & 8 \\
            13 & 14 \\
            19 & 20
        \end{ytableau}};
        \node at (0,-1.75) {$T_{C_1}$};
    \draw[->, dotted, thick](1,0) -- (2, 0);
    \node at (3,0) {\ytableausetup{boxsize=0.6cm}\begin{ytableau}
            5 & 6 \\
            11 & 12 \\
            17 & 28 \\
            23 & 24
        \end{ytableau}};
        \node at (3,-1.75) {$P^2(T_{C_1})$};
    \draw[->, dotted, thick](4,0) -- (5, 0);
    \node at (6,0) {\ytableausetup{boxsize=0.6cm}\begin{ytableau}
            1 & 2 \\
            7 & 8 \\
            13 & 14 \\
            19 & 20
        \end{ytableau}};
        \node at (6,-1.75) {$P^{6}(T_{C_1})$};

    \node at (0,-3.5) {\ytableausetup{boxsize=0.6cm}\begin{ytableau}
            3 \\
            4 \\
            5 \\
            6
        \end{ytableau}};
        \node at (0,-5.25) {$T_{C_1}$};
    \draw[->, dotted, thick](1,-3.5) -- (2, -3.5);
    \node at (3,-3.5) {\ytableausetup{boxsize=0.6cm}\begin{ytableau}
            1 \\
            2 \\
            3 \\
            4 \\
        \end{ytableau}};
        \node at (3,-5.25) {$P^2(T_{C_1})$};
    \draw[->, dotted, thick](4,-3.5) -- (5, -3.5);
    \node at (6,-3.5) {\ytableausetup{boxsize=0.6cm}\begin{ytableau}
            21 \\
            22 \\
            23 \\
            24
        \end{ytableau}};
        \node at (6,-5.25) {$P^{6}(T_{C_1}).$};
    \end{tikzpicture}
\end{center}
So we have that $P^6(T_{C_1})=T_{C_1}$ and $P^6(T_{C_2}) = T_{C_5}$ and thus $\cO(\psi(T)) = 6.$

Using the notation of Theorem \ref{thm:ssyt-alg}, we conclude $R=3$ and $|\cO(\psi(T))| = 6.$ Note that $\sum_{i=1}^R e_i = 6.$ Choosing $\ell$ to satisfy the equality
\begin{align*}
    \ell\sum_{i=1}^Re_i = \ell \cdot 6 = \lcm{6, |\cO(\psi(T))|} = \lcm{6, 6}
\end{align*}
we see that $\ell=1$ suffices. Thus the orbit length $|\cO(T)| = 1\cdot 3 = 3.$

\end{example}


