\newsection{Construction of a family of biunitary matrices}\label{Sec3}

Let $n$ be a natural number and consider the direct system $\{(\mathscr{A}_j,\phi_j):j\in\bbn\}$, where $\mathscr{A}_j:=M_n^{\otimes\,j}\cong M_{n^j}$, and for each $j\in\bbn,\,\phi_j:\mathscr{A}_j\hookrightarrow\mathscr{A}_{j+1}$ is given by the unital algebra embedding $x\mapsto 1_n\otimes x$ with $1_n$ being the identity matrix in $M_n$. Then, $\cup_j\mathscr{A}_j$ is naturally a unital algebra, and by abuse of notation, we denote it by $M_\infty$. Thus, in our context, $M_\infty:=\cup_{j=1}^\infty\,M_{n^j}$, where we omit the injective maps $\phi_j$ for obvious reason. An element $u\in M_\infty$ shall be called `unitary' if $u$ is a unitary matrix in some $M_{n^j}$. We denote $\mathcal{U}(M_\infty):=\cup_{j=1}^\infty\,U(n^j)$, where $U(n^j)$ is the group of unitary matrices of order $n^j$. Similarly, we denote by $\mathcal{BU}(M_\infty)$, the set of all biunitary matrices in $M_\infty$ (recall from \Cref{Sec2}). By definition, $\mathcal{BU}(M_\infty)\subseteq\mathcal{U}(M_\infty)$ and the inclusion is strict. Recall that $\mathbb{H}(M_n)$ denotes the set of all complex Hadamard matrices in $M_n$. For any element $u=(u_{ij})\in\mathbb{H}(M_n)$, consider the following element
\[
D_u = \sqrt{n} \sum_{i=1}^n \sum_{j=1}^n \overline{u}_{ij} (E_{ii} \otimes E_{jj})
\]
in $U(n^2)$ associated to $u$. Here, $E_{ij}$ denotes the matrix units in $M_n$. With the convention $u_0:=u$, it is easy to verify that the following recursive formula
\begin{eqnarray}\label{tower unitary}
u_{2k+1} &:=& (I_n \otimes u_{2k})(D_u \otimes I_n^{(k)}),\nonumber\\
u_{2k} &:=& u_{2k-1}(u \otimes I_n^{(k)}),
\end{eqnarray}
where $k$ varies over $\bbn\cup\{0\}$, induces a sequence of elements in $\mathcal{U}(M_\infty)$. Let $\prod_{j=1}^\infty\mathcal{U}(M_\infty)$ denote the product in the category of sets. Thus, any arbitrary element of $\prod_{j=1}^\infty\mathcal{U}(M_\infty)$ is a sequence in $\mathcal{U}(M_\infty)$. Therefore, for each $n\in\bbn$, \Cref{tower unitary} determines the following map
\begin{center}
$\Phi_n:\mathbb{H}(M_n)\longrightarrow\prod_{j=1}^\infty\mathcal{U}(M_\infty)$
\end{center}
given by
\begin{eqnarray}\label{the map}
u\mapsto\Phi_n(u):=u_1\oplus u_2\oplus\ldots
\end{eqnarray}
where the unitary matrices $u_j$'s are determined recursively starting with $u$.

\begin{rmrk}\rm
The unitary matrices $u_j$'s appear naturally in the context of Hadamard subfactors, see \cite{N} for instance. Note that, in particular, $u_{2k}\in M^{(k+1)}_n$ and $u_{2k+1}\in\Delta_n\otimes M^{(k+1)}_n\subseteq M^{(k+2)}_n$.
\end{rmrk}

Fix $n\in\bbn$ and take $u,w\in\mathbb{H}(M_n)$. We have the corresponding elements $\Phi_n(u)$ and $\Phi_n(w)$ in $\prod_{j=1}^\infty\mathcal{U}(M_\infty)$ obtained in \Cref{the map}. In other words, we have the following map
\begin{align*}
(\Phi_n,\Phi_n):\mathbb{H}(M_n)\times\mathbb{H}(M_n)\longrightarrow&\prod_{j=1}^\infty\mathcal{U}(M_\infty)\times\prod_{j=1}^\infty\mathcal{U}(M_\infty)\nonumber\\
(u,w)\longmapsto&(\Phi_n(u),\Phi_n(w))\,.
\end{align*}
Recall the set $\mathcal{BU}(M_\infty)$, the set of all biunitary matrices in $M_\infty$. We denote the $j$-fold tensor product $M_n^{\otimes j}$ of $M_n$'s by $M_n^{(j)}$ for notational clarity throughout the article. For each $\ell\in \bbn \cup \{0\}$, consider the unitary matrices $V_\ell:=\sum_{i,j}E_{ij} \ot E_{ji} \ot I^{(\ell)}_n$ in $M^{(\ell+2)}_n$, that is, $V_\ell\in\mathcal{U}(M_\infty)$ for each $\ell$, where $E_{ij}$ denotes the matrix units. Note that each $V_\ell$ flips the first two legs in $M_n\otimes M_n\otimes M_n^{(\ell)}$, and acts as identity on $M_n^{(\ell)}$.
\smallskip

The following theorem is the main goal of this section.

\begin{thm}\label{theorem1}
Fix $n\in\bbn$ and let $u,w\in\mathbb{H}(M_n)$ with $u\neq w$. Consider the unitary matrices $V_\ell:=\sum_{i,j}E_{ij} \ot E_{ji} \ot I^{(\ell)}_n\in M^{(\ell+2)}_n$. Then, the unitary matrices $\,BU(u,w;\ell):=u_{2\ell+2}w_{2\ell+1}V_\ell$ in $M_n^{(\ell+2)}$ defined in \Cref{tower unitary} are biunitary matrices for each $\ell\in\bbn\cup\{0\}$.
\end{thm}

In other words, we obtain the following map
\begin{align*}
\Phi:\mathbb{H}(M_n)\times\mathbb{H}(M_n)&\longrightarrow\prod_{j=1}^\infty\mathcal{BU}(M_\infty)\subseteq\prod_{j=1}^\infty\mathcal{U}(M_\infty)\\
(u,w)&\longmapsto BU(u,w;0)\oplus BU(u,w;1)\oplus\ldots\,.
\end{align*}
This says that starting with two fixed complex Hadamard matrices of the same order, one can obtain a sequence of biunitary matrices of distinct orders, and the order of each element of the sequence increases to infinity.
\smallskip

For transparency, we break the proof into a few lemmas. First, we fix some notations.
\begin{notation}\label{not}\rm
\begin{enumerate}[$(i)$]
\item For $k \in \mathbb{N} \cup \{0\}$ and $u\in\mathbb{H}(M_n)$, we let
\begin{align*}
A_{2k}:=M_n\otimes M^{(k)}_n\,,\quad& A_{2k+1}:=\Delta_n\otimes M_n \otimes M^{(k)}_n\,,\\
B^{u}_{2k}:=\mbox{Ad}_{u_{2k}}\big(\Delta_n\otimes M_n^{(k)}\big)\,,\quad& B^{u}_{2k+1}:=\mbox{Ad}_{u_{2k+1}}\big(M_n \otimes M_n^{(k)}\big)\,,
\end{align*}
with respect to the natural embedding $M^{(k)}_n\hookrightarrow\Delta_n\otimes M^{(k)}_n$ from the left, where `$\mbox{Ad}$' denotes the adjoint representation.
\item We fix the following projection matrices
\[
e_1:=\sum_{i,j=1}^nE_{ij}\quad,\quad e_2:=\sum_{i=1}^nE_{ii}\otimes E_{ii}
\]
in $M_n$ and $M_{n^2}$ respectively. We also define the following sequence of projections
\[
e_{2k+1}=e_1\otimes I^{(k)}_n\quad,\quad e_{2k+2}=e_2 \otimes I^{(k)}_n
\] for $k\in\bbn$. Note that $\{e_1,e_2,e_{2k+1},e_{2k+2}:k\in\bbn\}\subseteq M_\infty$.
\end{enumerate}
\end{notation}

\begin{lmma}\label{unitary projection relation}
Fix $n\in\bbn$ and let $u\in\mathbb{H}(M_n)$. Consider the element $\Phi_n(u)$ in $\prod_{j=1}^\infty\mathcal{U}(M_\infty)$ obtained in \Cref{the map}. Then, $u_ke_ku_k^*=e_{k+1}$ for all $k\in\bbn$, where the projections $e_k$'s are as defined in \Cref{not}.
\end{lmma}
\begin{prf}
For $k=1$, we have
\begin{IEEEeqnarray*}{lCl}
\mathrm{Ad}_{u_1}(I_n \otimes e_1) &=& \frac{1}{n} \text{Ad}_{(I_n \otimes u)} \text{Ad}_{D_u} \Big( I_n \otimes \sum_{i,j} E_{i,j} \Big)\\
&=& \mathrm{Ad}_{(I_n \otimes u)} \Big( \sum_{i,j,k} \overline{u_{k,i}} u_{j,k} \left( E_{k,k} \otimes E_{i,j} \right) \Big)\\
&=& \mathrm{Ad}_{(I_n \otimes u)} \left( \text{Ad}_{(I_n \otimes u^*)}(e_2) \right)\\
&=& e_2.
\end{IEEEeqnarray*}
The general case follows by induction on $k$, and we omit the details.\qed
\iffalse
Now, we prove the lemma for odd steps, i.e., for the $(2k+1)$-th steps, using \Cref{equality1}. From \Cref{unitaries}, we have
\[
u_{2k+1} = (I_n \otimes u_{2k})(D_u \otimes I_n^{(k)}), \quad u_{2k} = u_{2k-1}(u \otimes I_n^{(k)}), \quad u_1 = (I_n \otimes u) D_u.
\]
Hence, we get the following expression for \( u_{2k+1} \):
    \begin{eqnarray}
        u_{2k+1}&=&(I_n \otimes u_{2k-1}) (I_n \otimes u \otimes I_n^{(k)})(D_u \otimes I_n^{(k)}) \nonumber \\
        &=&(I_n \otimes u_{2k-1}) (u_1 \otimes I_n^{(k)}). \label{nextstep}
    \end{eqnarray}
Consider the following
    \begin{eqnarray}
        \text{Ad}_{u_{2k+1}}(e_{2k+1})&=&\text{Ad}_{u_{2k+1}}(I_n \otimes e_1 \otimes I_n^{(k)}) \nonumber \hspace{2mm} (\text{by \Cref{nextstep}})\\
        &=&\text{Ad}_{(I_n \otimes u_{2k-1})} \left\{ \text{Ad}_{(u_1 \otimes I_n^{(k)})}(I_n \otimes e_1 \otimes I_n^{(k)}) \right\} \nonumber \\
        &=&\text{Ad}_{(I_n \otimes u_{2k-1})} \left\{ (\text{Ad}_{u_1}(I_n \otimes e_1)) \otimes I_n^{(k)} \right\} \nonumber \hspace{2mm} (\text{by \Cref{equality1}})\\
        &=&\text{Ad}_{(I_n \otimes u_{2k-1})} \left( e_2 \otimes I_n^{(k)} \right). \label{projection1}
    \end{eqnarray}
Since $e_2 \in \Delta_{n^2}$ and from \Cref{unitaries}, we know that $u_{2k-1} \in \dt \otimes M_n^{(k)}$ is a unitary matrix, by using this fact we obtain the identity:
 \begin{eqnarray}
     \text{Ad}_{(I_n \otimes u_{2k-1})} \left( e_2 \otimes I_n^{(k)} \right)&=&e_2 \ot I_n^{(k)}  \nonumber \\
     &=&e_{2k+2}
 \end{eqnarray}   
Hence, from \Cref{projection1}, we conclude that
    \[
    \text{Ad}_{u_{2k+1}}(e_{2k+1}) = e_{2k+2}.
    \]
Therefore, \Cref{identities} is true for odd steps. Similarly, by using \Cref{equality2} and \Cref{unitaries}, one can prove the result for even steps of \Cref{identities}.\qed
\fi
\end{prf}

\begin{rmrk}\rm
The above lemma first appeared in \cite{N} in a different disguise.
\end{rmrk}

For each $k \in \bbn \cup \{0\}$, consider the following subalgebras of $M_\infty:$
\begin{IEEEeqnarray}{lCl}\label{notation two}
N^{u,w}_{2k} &:=& \text{Ad}_{u_{2k+1}(I_n \otimes w_{2k})}(I_n \otimes \dt \otimes I_n^{(k)}),\nonumber\\
N^{u,w}_{2k+1} &:=& \text{Ad}_{u_{2k+2}w_{2k+1}}(I_n \otimes M_n \otimes I_n^{(k)}).
\end{IEEEeqnarray}
\begin{lmma}
For each $k \in \bbn \cup \{0\}$, the following quadruple
\begin{equation}
\mathscr{I}_k:=
\begin{matrix}\label{infinite quadruples}
\mathbb{C} \otimes M_n^{(k+1)} & \subset & \dt \otimes M_n^{(k+1)} \\
\cup & & \cup \\
\mathbb{C} & \subset & N_{2k}
\end{matrix}
\end{equation}
is a non-degenerate commuting square.
\end{lmma}
\begin{prf}
From \Cref{tower unitary}, we know that the unitary matrix $w_{2k} \in M_n \otimes M_n^{(k)}$, and hence,
\[
N^{u,w}_{2k} = \text{Ad}_{u_{2k+1}(I_n \otimes w_{2k})}(I_n \otimes \dt \otimes I_n^{(k)}) \subset B_{2k+1}^u.
\]
Therefore, we have
\begin{equation}\label{conditional}
E_{N^{u,w}_{2k}}(\bbc \otimes M_n^{(k+1)}) = E_{N^{u,w}_{2k}} E_{B_{2k+1}^u}(\bbc \ot M^{(k+1)}_n).
\end{equation}
Since $u$ is a complex Hadamard matrix, the following quadruple
\begin{equation*}
\begin{matrix}
B^{u}_{2k+1} & \subset & \dt \otimes M_n^{(k+1)} \\
\cup & & \cup \\
B^{u}_{2k} & \subset &  \bbc \ot M^{(k+1)}_{n}
\end{matrix}
\end{equation*}
is a non-degenerate commuting square. Consequently, $E_{B_{2k+1}^u}(\bbc \otimes M_n^{(k+1)}) = B_{2k}^u$. Substituting in \Cref{conditional}, we obtain
\begin{equation}\label{commute exp}
 E_{N^{u,w}_{2k}} (\bbc \otimes M_n^{(k+1)}) = E_{N^{u,w}_{2k}}(B_{2k}^u)   
\end{equation}
From the definition of $B_{2k}^u$, we have
\begin{equation*}
B_{2k}^u = \text{Ad}_{(I_n \otimes u_{2k})}(\bbc \otimes \dt \otimes M_n^{(k)}),
\end{equation*}
Since $u_{2k+1} = (I_n \otimes u_{2k})(D_u \otimes I_n^{(k)})$ from \Cref{tower unitary}, we can rewrite the above as
\begin{equation}\label{k-th space}
B_{2k}^u = \text{Ad}_{u_{2k+1}}(\bbc \otimes \dt \otimes M_n^{(k)}).
\end{equation}
Therefore, substituting the definition of $N^{u,w}_{2k}$ from \Cref{notation two}, we get
\begin{eqnarray}\label{equation of n2k}
E_{N^{u,w}_{2k}}(B_{2k}^u) &= &\text{Ad}_{u_{2k+1}} \big\{E_{\mathscr{A}}(B^{2k}_u)\big\}  \hspace{2mm}(\text{by \Cref{k-th space}}) \nonumber\\
&=&\text{Ad}_{u_{2k+1}}\big(E_{\mathscr{A}}(I_n \otimes \dt \otimes M_n^{(k)})\big),
\end{eqnarray}
where we denote $\mathscr{A}:=\text{Ad}_{(I_n \otimes w_{2k})}(I_n \otimes \dt \otimes I_n^{(k)})$.
\smallskip

\noindent \textbf{Claim}:~ $E_{\mathscr{A}}(I_n \otimes \dt \otimes M_n^{(k)})=\bbc$.
\smallskip

\noindent To establish the claim, first observe that from \Cref{tower unitary}, we have $w_{2k} = w_{2k-1}(w \otimes I_n^{(k)})$, where $w_{2k-1} \in \dt \otimes M_n^{(k)}$. Therefore, it follows that
\begin{equation}\label{mid equation}
 \text{Ad}_{(I_n \otimes w_{2k}^*)}(I_n \otimes \dt \otimes M_n^{(k)})=(I_n \ot w^{*} \dt w \ot M^{(k)}_n)   
\end{equation}
where $w^{*}$ is the adjoint of $w$. Since $\mathscr{A} = \text{Ad}_{(I_n \otimes w_{2k})}(I_n \otimes \dt \otimes I_n^{(k)})$, using \Cref{mid equation} we establish our claim.

So from \Cref{equation of n2k}, it follows that $E_{N^{u,w}_{2k}}(B_{2k}^{u})=\bbc$, and therefore, by \Cref{commute exp} we conclude that  $E_{N^{u,w}_{2k}} (\bbc \otimes M_n^{(k+1)})=\bbc$. Thus the quadruple $\mathscr{I}_k$ is a commuting square. Since the norms of the inclusion matrices for both the vertical embeddings are the same, we conclude that $\mathscr{I}_k$ is a non-degenerate commuting square, which completes the proof.\qed
\end{prf}

\begin{lmma}\label{subset of algebra}
For $k\in\bbn\cup\{0\}$, consider the subalgebra $\langle N^{u,w}_{2k}, e_{2k+3}\rangle$ of $M_\infty$, generated by $N^{u,w}_{2k}$ and the projection $e_{2k+3}$ defined in \Cref{not}. Then, we have the following:
\[
N^{u,w}_{2k+1}=\langle N^{u,w}_{2k}, e_{2k+3} \rangle\qquad\mbox{and}\qquad N^{u,w}_{2k+2} \subseteq\langle N^{u,w}_{2k+1}, \,e_{2k+4}\rangle\,.
\]
\end{lmma}
\begin{prf}
From \Cref{tower unitary}, we have the following identities:
\[
u_{2k+2}=u_{2k+1} (u \ot I^{(k+1)}_n) \quad \text{and} \quad w_{2k+1}=(I_n \ot w_{2k})(D_w \ot I^{(k)}_n)
\]
where $D_w\in\Delta_n\ot\Delta_n$. Using this fact, we see the following
\[\text{Ad}_{u_{2k+2}}\text{Ad}_{(I_n \ot w_{2k})}(I_n \ot \dt \ot I^{(k)}_n)=\text{Ad}_{u_{2k+1}}(\text{Ad}_{(I_n \ot w_{2k})}(I_n \ot \dt \ot I^{(k)}_n))
\]
\[
\text{Ad}_{(I_n \ot w_{2k})}(I_n \ot \dt \ot I^{(k)}_n)=\text{Ad}_{w_{2k+1}}(I_n \ot \dt \ot I^{(k)}_n)\,.
\]
Therefore, it follows that
\begin{eqnarray}\label{rewrite one}
\text{Ad}_{u_{2k+2}w_{2k+1}}(I_n \ot \dt \ot I^{(k)}_n)&=&\text{Ad}_{u_{2k+1}}(\text{Ad}_{(I_n \ot w_{2k})}(I_n \ot \dt \ot I^{(k)}_n))=N_{2k}\,.
\end{eqnarray}
Along the same line, again by using \Cref{tower unitary}, one can prove the following:
\begin{eqnarray}\label{rewrite two}
\text{Ad}_{u_{2k+2}w_{2k+1}}(I_n \ot M_n \ot I^{(k)}_n)&=&\text{Ad}_{u_{2k+3}(I_n \ot w_{2k+2})}(I_n \ot M_n \ot I^{(k)}_n)=N_{2k+1}\,.
\end{eqnarray}
Now,
\begin{eqnarray}\label{prove one}
& & \langle N^{u,w}_{2k}, \,e_{2k+3}\rangle\nonumber\\
&=&N^{u,w}_{2k}e_{2k+3}N^{u,w}_{2k} \nonumber \hspace{2mm} (\text{by \, \Cref{rewrite one}})\\
&=&\text{Ad}_{u_{2k+2}w_{2k+1}}(I_n \ot \dt \ot I^{(k)}_n) e_{2k+3} \text{Ad}_{u_{2k+2}w_{2k+1}}(I_n \ot \dt \ot I^{(k)}_n)\nonumber\\
&=&\text{Ad}_{u_{2k+2}w_{2k+1}}\{(I_n \ot \dt \ot I^{(k)}_n)  \{\text{Ad}_{(u_{2k+2}w_{2k+1})^{*}}e_{2k+3}\}(I_n \ot \dt \ot I^{(k)}_n) \}\,.
\end{eqnarray}
Using \Cref{unitary projection relation}, one obtains $\text{Ad}_{(u_{2k+2}w_{2k+1})^{*}}e_{2k+3}=e_{2k+1}$, and therefore \Cref{prove one} becomes the following:
\begin{IEEEeqnarray*}{lCl}
& & \langle N^{u,w}_{2k}, \,e_{2k+3}\rangle\\
&=&\text{Ad}_{u_{2k+2}w_{2k+1}}\{(I_n \ot \dt \ot I^{(k)}_n) e_{2k+1}(I_n \ot \dt \ot I^{(k)}_n) \}\\
&=&\text{Ad}_{u_{2k+2}w_{2k+1}}\{(I_n \ot \dt \ot I^{(k)}_n)(I_n \ot e_1 \ot I^{(k)}_n)(I_n \ot \dt \ot I^{(k)}_n)\}\\
&=&\text{Ad}_{u_{2k+2}w_{2k+1}}(I_n \ot M_n \ot I^{(k)}_n) \hspace{4mm}(\text{by \Cref{notation two}})\\
&=&N^{u,w}_{2k+1}\,.
\end{IEEEeqnarray*}
This completes the first part of the proof.

Finally, along the similar lines, using \Cref{unitary projection relation} and \Cref{rewrite two}, one can prove the following\,:
\[
\langle N^{u,w}_{2k+1}, e_{2k+4}\rangle=\text{Ad}_{u_{2k+3} (I_n \ot w_{2k+2})}(I_n \ot \dt \ot M_n \ot I^{(k)}_n)\,,
\]
which proves that $N^{u,w}_{2k+3}\subseteq\langle N^{u,w}_{2k+1}, \,e_{2k+4}\rangle$.\qed
\end{prf}
\medskip

\noindent\textbf{Proof of the \Cref{theorem1}:}
First, we observe the following
\begin{eqnarray}\label{biunitary}
   \langle N^{u,w}_{2k}, e_{2k+3} \rangle &=&N^{u,w}_{2k+1}   \hspace{2mm} (\text{by \,\Cref{subset of algebra}})\nonumber \\
    &=& \text{Ad}_{u_{2k+2}w_{2k+1}}(I_n \otimes M_n \otimes I_n^{(k)}) \hspace{2mm} (\text{by \Cref{notation two}})\nonumber\\
    &=& \text{Ad}_{u_{2k+2}w_{2k+1}V_k}(M_n \otimes I_n \otimes I_n^{(k)})
\end{eqnarray}
where $V_k:=\sum_{i,j}E_{ij}\ot E_{ji} \ot I^{(k)}_n$ is a unitary matrix. The following quadruples
\begin{IEEEeqnarray*}{lCl}
\begin{matrix}
\bbc \ot M^{(k+1)}_{n} &\subset & \dt \otimes M^{(k+1)}_{n} & \subset^{\,e_{2k+3}} &  M_n \ot M^{(k+1)}_n\cr \cup &\ &\cup  & & \cup \cr \bbc &\subset & N^{u,w}_{2k} & \subset^{\,e_{2k+3}} &  \langle N^{u,w}_{2k}, \, e_{2k+3} \rangle
\end{matrix}
\end{IEEEeqnarray*}
is the basic construction of the non-degenerate commuting square $\mathscr{I}_k$ in \Cref{infinite quadruples} with the Jone's projection $e_{2k+3}=e_1 \ot I^{(k+1)}_n$. Since the following quadruple
\begin{eqnarray*}
\mathscr{L}_k&=& \begin{matrix}
\bbc \ot M^{(k+1)}_{n} &\subset & M_n \otimes M^{(k+1)}_{n} \cr \cup &\ &\cup\cr \bbc &\subset & \langle N^{u,w}_{2k}, e_{2k+3} \rangle
\end{matrix} 
\end{eqnarray*}
is a non-degenerate commuting square, the unitary matrix $u_{2k+2}w_{2k+1}V_k$ in \Cref{biunitary} must be a biunitary matrix by \Cref{biunitary thm}. This concludes the proof.\qed

