\newsection{Application to Subfactors}\label{Sec4}

Traversing from finite to infinite dimension, in this section we apply our investigations in \Cref{Sec3} to subfactor theory. Starting with an element $(u,w)$ in $\mathbb{H}(M_n)\times \mathbb{H}(M_n)$, we construct a nested sequence of vertex model subfactors with distinct Jones indices in the hyperfinite type $II_1$ factor $R$ such that the Hadamard/spin model subfactor $R_u\subset R$ is an intermediate subfactor to each of them. Moreover, this sequence of subfactors is not the tower of downward basic construction. Our construction is noncommutative; that is, subfactors arising from $(u,w)$ need not be isomorphic with that arising from $(w,u)$.

\subsection{A family of vertex model subfactors}\label{Sec4.1}

Let $u,w$ be two complex Hadamard matrices of the same order $n$. We have a sequence of biunitary matrices $\{BU(u,w;k)\}_{k=0}^\infty$ obtained to \Cref{theorem1}. Using itereated basic construction, we construct a nested sequence of vertex model subfactors from $\{BU(u,w;k)\}_{k=0}^\infty$. More precisely, we prove the following theorem.

\begin{thm}\label{theorem2}
Fix any $n\geq 2$. Let $u\in\mathbb{H}(M_n)$ be a complex Hadamard matrix and $R_u \subset R$ be the corresponding Hadamard/spin model subfactor. Choose any $w\in\mathbb{H}(M_n)$. For each $k\in\mathbb{N}\cup\{0\}$, there exists a vertex model subfactor $R^{u, w}_k \subset R$ such that
\begin{enumerate}[$(i)$]
\item $R^{u, w}_k\subset R_u$, and the Jones index is given by $[R:R^{u, w}_k]=n^{2(k+1)}$;
\item The subfactors $\{R^{u, w}_k\subset R:k\in\mathbb{N}\cup\{0\}\}$ satisfy the inclusion $R^{u, w}_{k+1} \subset R^{u, w}_k$ for each $k$.
\end{enumerate}
Therefore, we have a nested sequence of vertex model subfactors
\[
\cdots \subset R^{u, w}_{k+1}\subset R^{u, w}_k\subset\cdots\subset R^{u, w}_0\subset R
\]
each having the Hadamard/spin model subfactor $R_u\subset R$ as an intermediate subfactor.
\end{thm}
\begin{prf}
We divide the proof into three steps.

\noindent \textbf{Step 1:} $R^{u,w}_k\subset R$ is a vertex model subfactor with $[R : R_{k}^{u,w}] = n^{2(k+1)}$.

\noindent For each $k \in \mathbb{N} \cup \{0\}$, we have the following quadruple
\begin{eqnarray*}
\mathscr{I}_{k}&=& \quad \begin{matrix}
\bbc \ot M^{(k+1)}_{n} &\subset & \dt \otimes M^{(k+1)}_{n} \cr \cup &\ &\cup\cr \bbc &\subset{} & N^{u,w}_{2k}
\end{matrix} 
\end{eqnarray*}
which is a non-degenerate commuting square. Using the iterated basic construction to the above non-degenerate commuting square $\mathscr{I}_k$, we obtain the following grid of finite-dimensional algebras\,:
\begin{eqnarray}\label{construction middle vertex model}
\begin{matrix}
\bbc \ot M^{(k+1)}_n  &\subset & \Delta_n\otimes M^{(k+1)}_n &\subset^{\,e_{2k+3}}  & \subset M_n\otimes M^{(k+1)}_n &\subset^{e_{2k+4}}  \cdots &\subset R\cr
\cup & & \cup & & \cup &  & \,\, \, \cup \cr
\bbc  &\subset & N^{u,w}_{2k} &\subset^{\,e_{2k+3}}  & \subset \langle N^{u,w}_{2k} \, ,e_{2k+3}\rangle & \subset^{e_{2k+4}}  \cdots \cdots & \, \subset R_{k}^{u,w}.
\end{matrix}
\end{eqnarray}
Here, the projections $e_{2k+2i+1} = e_1 \otimes I_n^{(k+i)}$ and $e_{2k+2i+2} = e_2 \otimes I_n^{(k+i)}$, for all $i \in \mathbb{N}$, are the Jones' projections. Consider the following von Neumann algebra  
\begin{eqnarray}\label{middle vertex subfactor}
R_{k}^{u,w}:=\overline{\bigvee \{N^{u,w}_{2k}, \,e_{2k+2+i} \,: \, i\in \bbn\}}^{\,\text{sot}}. 
\end{eqnarray}
It follows that $R_{k}^{u,w}$ is a $II_1$-subfactor of the hyperfinite factor $R$. Finally, the inclusion matrix for the inclusion $\bbc \subset M_n^{(k+1)}$ is the $1\times 1$ matrix $[n^{(k+1)}]$, and hence by \Cref{prop}, $[R : R_{k}^{u,w}] = n^{2(k+1)}$. Now, from \Cref{construction middle vertex model} the following non-degenerate commuting square
\begin{eqnarray*}
\mathscr{L}_{k}&=& \quad \begin{matrix}
\bbc \ot M^{(k+1)}_{n} &\subset & M_n \otimes M^{(k+1)}_{n} \cr \cup &\ &\cup\cr \bbc &\subset & \langle N^{u,w}_{2k}, e_{2k+3} \rangle
\end{matrix} 
\end{eqnarray*}
is a basic construction of the nondegenerate commuting square $\mathscr{I}_k$. Here, $\langle N^{u,w}_{2k}, e_{2k+3}\rangle =N^{u,w}_{2k+1}=\mathrm{Ad}_{u_{2k+2}w_{2k+1}V_k}(M_n \otimes I_n \otimes I_n^{(k)})$ (see \Cref{biunitary}), and $BU(u,w;k):=u_{2k+2}w_{2k+1}V_k$ is a biunitary matrix of order $n^{k+1}$ (see \Cref{theorem1}). Thus, $R^{u,w}_k\subset R$ is a vertex model subfactor. This completes Step $1$.
\smallskip

\noindent \textbf{Step 2:} $R_{k+1}^{u,w}\subset R_{k}^{u,w}$ for all $k\in\mathbb{N} \cup \{0\}.$

\noindent Note that by \Cref{middle vertex subfactor}, we have
\begin{eqnarray}\label{next vertex}
R_{k+1}^{u,w}=\overline{\bigvee \{N^{u,w}_{2k+2}, \,e_{2k+4+i} \,: \, i\in \bbn\}}^{\,\text{sot}}. 
\end{eqnarray}
From \cref{subset of algebra}, we know that $N^{u,w}_{2k+2} \subseteq \langle N_{2k+1}, e_{2k+4} \rangle$, and since $N^{u,w}_{2k+1} = \langle N^{u,w}_{2k}, e_{2k+3} \rangle$, it follows that  
\begin{eqnarray*}
\{N^{u,w}_{2k+2}, \,e_{2k+4+i} : i \in \bbn\}\subseteq \{N^{u,w}_{2k}, \,e_{2k+2+i} : i \in \bbn\}
\end{eqnarray*}
Combining this with \Cref{middle vertex subfactor,next vertex}, we conclude the proof of this step.
\smallskip

\noindent \textbf{Step 3:} $R^{u,w}_{k} \subset R_u\,\,\mbox{for all }k\in\mathbb{N}\cup\{0\}$.

\noindent By Step $2$, it suffices to only show that $R^{u,w}_0 \subset R_u$. From \Cref{middle vertex subfactor}, we observe that
\begin{eqnarray*}
R^{u,w}_0 &=& \overline{\bigvee \{N^{u,w}_0, e_{2+i} : i \in \mathbb{N} \}}^{\,\text{sot}},
\end{eqnarray*}
where $N^{u,w}_0 = \text{Ad}_{u_1}(\mathbb{C} \otimes w \Delta_n w^*)$. Additionally, from \Cref{not}, recall that 
$R_u = \overline{\bigcup_{j} B^u_j}^{\text{sot}}$, where
$B^u_1 = \text{Ad}_{u_1}(\mathbb{C} \otimes M_n)$. This implies that 
$N^{u,w}_0 \subset B^u_1 \subset R_u$. Furthermore, we have
$e_i \in R_u$ for all $i \geq 2$. Consequently, we deduce that
\begin{eqnarray*}
 \bigvee \{N^{u,w}_0, e_{2+i} : i \in \mathbb{N} \} \subset R_u.
\end{eqnarray*}
This establishes the fact that $R^{u,w}_0\subset R_u$.\qed
\end{prf}

At this stage, the following natural questions arise.
\smallskip

\noindent\textbf{Question A:} Is the vertex model subfactor $R^{u, w}_0\subset R$ the downward basic construction of the Hadamard subfactor $R_u\subset R$?
\smallskip

\noindent\textbf{Question B:} Is the nested sequence of vertex model subfactors $\,\,\cdots\cdots\subset R^{u, w}_1\subset R^{u, w}_0\subset R$ a tower of downward basic construction of $R^{u, w}_0\subset R$?
\smallskip

If the answer to any of the above questions is always yes, then our construction would not be considered as new. Below, we show that this is not the case.
\smallskip

\noindent\textbf{Answer to Question A:} Let $n\geq 4$ be an even number and $\omega$ be a primitive $n$-th root of unity. Consider a permutation matrix $P\in M_n$ such that $\mathrm{Ad}_{PF_n}(\mathscr{D}_{\frac{n}{2}})\neq\alpha\,\mathrm{Ad}_{\mathscr{D}_1PF_n}(\mathscr{D}_{\frac{n}{2}})$ for any $\alpha\in\bbc$, where
\begin{eqnarray*}
\mathscr{D}_1&:=& \mathrm{diag}\{1, \omega, \omega^2, \cdots, \omega^{n-1}\},\nonumber\\
\mathscr{D}_k &:=& \mathscr{D}_1^k=\mathrm{diag}\{1, \omega^k, \omega^{2k}, \cdots, \omega^{(n-1)k}\}.
\end{eqnarray*}
Such a $P$ always exists, for example, choose $P:=E_{13}+E_{21}+E_{32}+\sum_{k=4}^{n} E_{kk}$, where $E_{ij}$'s are the matrix units. Take $u=F_n$ and $w=PF_n$. We show that the vertex model subfactor $R^{F_n,PF_n}_0 \subset R$ is irreducible, which immediately says that $R^{F_n, PF_n}_0\subset R_{F_n}$ can not be the downward basic construction of the spin model subfactor $R_{F_n}\subset R$.

From \Cref{construction middle vertex model}, we have the following non-degenerate commuting square (putting $k=0$)
\[
\begin{matrix}
\bbc \ot M_{n} &\subset & \dt \otimes M_{n} \cr \cup &\ &\cup\cr \bbc &\subset{} & N^{F_n,PF_n}_{0}
\end{matrix} 
\]
where $N^{F_n,PF_n}_0=\text{Ad}_{(F_n)_1(I_n \otimes PF_n)}(\bbc\otimes\Delta_n)$. By construction, the vertex model subfactor $R^{F_n,PF_n}_0 \subset R$ is obtained from the above non-degenerate commuting square using the iterated basic construction. Hence, using the fact that $(F_n)_1=\mbox{bl-diag}\{F_n,F_n\mathscr{D}_{n-1},\ldots,F_n\mathscr{D}_1\}$, by the Ocneanu compactness we have the following\,:
\begin{IEEEeqnarray}{lCl}\label{changed}
(R^{F_n,PF_n}_0)^\prime\cap R &=& (N^{F_n,PF_n}_0)^{'}\cap (\bbc \ot M_n)\nonumber\\
&=& \big(\mathrm{Ad}_{(F_n)_1(I_n \ot PF_n)}(\bbc \ot \Delta_n)\big)^\prime\cap (\bbc \ot M_n)\nonumber\\
&=& \mathrm{Ad}_{F_n}\Big(\bigcap_{k=1}^{n}\mathrm{Ad}_{\mathscr{D}_kPF_n}(\Delta_n)\Big).
\end{IEEEeqnarray}
We claim that $\bigcap_{k=1}^n\mathrm{Ad}_{\mathscr{D}_{k} PF_n}(\Delta_n)=\bbc$. On contrary, assume that $\cap_{k=1}^n\mathrm{Ad}_{\mathscr{D}_kPF_n} (\Delta_n)\neq\bbc$. Then, there exist non-trivial diagonal matrices $D_0, D_1$ such that  $\mathrm{Ad}_{PF_n} (D_0)=\mathrm{Ad}_{\mathscr{D}_1PF_n} (D_1)$. Consider $D_0=\sum_{i=0}^{n-1} r_i \mathscr{D}_i$ and $D_1=\sum_{i=0}^{n-1} s_i \mathscr{D}_i$, and deduce the following  
\begin{equation}\label{last eqn}
r_i \mathrm{Ad}_{PF_n}(\mathscr{D}_i)=s_i\mathrm{Ad}_{\mathscr{D}_1PF_n}(\mathscr{D}_i)\quad\text{for all }\,i.
\end{equation}
Since $D_0\notin\bbc I_n$, there exists some $i_0\in\{1,\ldots,n-1\}$ such that $r_{i_0}\neq 0\,\text{and}\,s_{i_0}\neq 0$. Therefore, it follows from \Cref{last eqn} that $\mathrm{Ad}_{PF_n}(\mathscr{D}_{i_0})=\frac{s_{i_0}}{r_{i_0}}\mathrm{Ad}_{\mathscr{D}_1PF_n}(\mathscr{D}_{i_0})$. Since there exists some $k\in\bbn$ such that $\mathscr{D}_{i_0}^k=\mathscr{D}_{\frac{n}{2}}$, and $n$ is even, we obtain the following\,:
\begin{IEEEeqnarray*}{lCl}
\mathrm{Ad}_{PF_n}(\mathscr{D}_{\frac{n}{2}}) &=& (\mathrm{Ad}_{PF_n}(\mathscr{D}_{i_0}))^{k}\nonumber\\
&=& \Big(\frac{s_{i_0}}{r_{i_0}}\Big)^k(\mathrm{Ad}_{\mathscr{D}_1PF_n}(\mathscr{D}_{i_0}))^{k}\nonumber\\
&=& \Big(\frac{s_{i_0}}{r_{i_0}}\Big)^k\mathrm{Ad}_{\mathscr{D}_1PF_n}(\mathscr{D}_{\frac{n}{2}}).
\end{IEEEeqnarray*}
This contradicts the choice of $P$ \big(with $\alpha=(s_{i_0}/r_{i_0})^k$ in equation $\mathrm{Ad}_{PF_n}(\mathscr{D}_{\frac{n}{2}})\neq\alpha\,\mathrm{Ad}_{\mathscr{D}_1PF_n}(\mathscr{D}_{\frac{n}{2}})$\big). Hence, from \Cref{changed} we conclude that
\begin{equation}\label{to be used next}
 (R^{F_n,PF_n}_0)^{'} \cap R=\bbc.
\end{equation}

\noindent\textbf{Answer to Question B:} Let $F_n$ denote the Fourier matrix of order $n$, and consider $u=w=F_n$. For any $m,k\in\bbn$, the following nested sequence
\[
\cdots\subset R_{(m+1)k-1}^{u,w}\subset R_{mk-1}^{u,w}\subset R_{(m-1)k-1}^{u,w}\subset\cdots\subset R_{2k-1}^{u,w}\subset R_{k-1}^{u,w}\subset R
\]
of vertex model subfactors cannot be obtained as the downward basic construction of the subfactor $R_{k-1}^{u,w}\subset R$. This is because there is no non-zero projection $p\in\big(R^{u,w}_{(m+1)k-1}\big)^\prime\cap R$ satisfying $pxp=E^{R_{mk-1}^{u,w}}_{R_{(m+1)k-1}^{u,w}}(x)p$ for all $x\in R_{mk-1}^{u,w}$. The proof of this fact is provided in the Appendix.

