\newsection{Appendix}\label{Sec7}

Here, we provide a proof of Question B in \Cref{Sec4.1}, as promised there.

Let $u$ and $w$ be complex Hadamard matrices of order $n$. We show that for any $k, m\in \bbn$, the following subfactors
\[
R^{u,w}_{(m+2)k-1}  \subset  R^{u,w}_{(m+1)k-1} \subset R^{u,w}_{mk-1} \quad  \text{and} \quad R^{u,w}_{2k-1} \subset R^{u,w}_{k-1} \subset R 
\] 
in the nested sequence of vertex model subfactors  
\begin{equation*}
\cdots  \subset R^{u,w}_{(m+2)k-1}  \subset  R^{u,w}_{(m+1)k-1} \subset R^{u,w}_{mk-1} \subset \cdots \subset R^{u,w}_{2k-1} \subset R^{u,w}_{k-1} \subset R 
\end{equation*} 
need not be a downward basic construction. From \Cref{construction middle vertex model}, observe that the following quadruple 
\[
\begin{matrix}
 \bbc \ot M^{(m+1)k}_n  &\subset & R \cr \cup &\ &\cup\cr \bbc
&\subset{} &  R^{u,w}_{(m+1)k-1}
\end{matrix} 
\]
is a commuting square. Hence, it follows that $E^{R}_{R^{u,w}_{mk-1}}(\bbc \ot M^{(m+1)k}_n)=\bbc$. In particular, for the case of $u=w= F_n$, we have
\begin{eqnarray}\label{image of ce}
E^{R}_{R^{F_n,F_n}_{(m+1)k-1}}(\bbc \ot M^{(m+1)k}_n)=\bbc.
\end{eqnarray}
Now, from \Cref{construction middle vertex model} we have $N^{F_n, F_n}_{2(mk-1)} \subseteq \dt \ot M^{(mk)}_n \subseteq  R^{F_n,F_n}_{mk-1}$. Therefore, from \Cref{image of ce} we conclude that  
\begin{eqnarray}\label{image of cf}
 E^{R^{F_n,F_n}_{mk-1}}_{R^{F_n,F_n}_{(m+1)k-1}}(N^{F_n,F_n}_{2(mk-1))} )=\bbc.
\end{eqnarray}
To conclude the proof, it is now sufficient to construct an element $x \in R^{F_n, F_n}_{mk-1}$ such that
\[
f x f \neq E^{R^{F_n,F_n}_{mk-1}}_{R^{F_n,F_n}_{(m+1)k-1}}(x) f
\]
for any non-zero projection $f \in (R^{F_n, F_n}_{(m+1)k-1)})^{'} \cap R$. Consider 
\[
x=\text{Ad}_{(F_n)_{2mk-1}}\text{Ad}_{(I_n \otimes (F_n)_{2mk-2})}(I_n \otimes \mathscr{D}_1 \otimes I_n^{(mk)}) \in N^{F_n,F_n}_{2(mk-1)} \subseteq R^{F_n, F_n}_{mk-1}.
\]
From \Cref{diagonal von Neumann algebra}, it follows that $x \in  N^{F_n,F_n}_{2(mk-1)}$ is a diagonal unitary matrix where diagonal entries are from the set $\{1,\omega, \omega^2, \dots, w^{n-1}\}$ and $tr(x)=0$. Here, $\omega$ is a primitive $n$-th root of unity, and  $tr$ is the unique trace on the hyperfinite type $II_1$ factor $R$. Since $x \in  N^{F_n,F_n}_{2(mk-1)}$, using  \Cref{image of cf} we conclude that
\begin{eqnarray}\label{last}
E^{R^{F_n,F_n}_{mk-1}}_{R^{F_n,F_n}_{(m+1)k-1}}(x)=tr(x)=0.
\end{eqnarray}
Now, from \Cref{at end} we have
\begin{eqnarray*}
\big(R^{F_n, F_n}_{(m+1)k-1}\big)^\prime\cap R &= &\Delta_{n^{(m+1)k}}.
\end{eqnarray*}
Therefore, for any non-zero diagonal projection $f \in (R^{F_n, F_n}_{(m+1)k-1)})^{'} \cap R$, since $x \in  N^{F_n,F_n}_{2((m+1)k-1)}$ is a diagonal unitary matrix, it follows that
\begin{eqnarray*}
f x f&=&xf \not = 0.
\end{eqnarray*}
Observe the following from \Cref{last}
\[
E^{R^{F_n,F_n}_{mk-1}}_{R^{F_n,F_n}_{(m+1)k-1}}(x)f=tr(x)f=0.
\]
Thus, we conclude that
\[
f x f \neq   E^{R^{F_n,F_n}_{mk-1}}_{R^{F_n,F_n}_{(m+1)k-1}}(x)f\quad\forall\,\,0\neq f\in (R^{F_n, F_n}_{(m+1)k-1})^\prime\cap R,
\]
which concludes the proof.

