\section{Preliminaries}
\noindent Detected affinities between vector fields for stable systems result from determining the infimum of the characteristic distances between pairs of system characteristics.\\

\vspace*{0.2cm}  

\begin{definition}\label{def:vector}{\bf (Vector).}\\
A {\bf vector} $v$ (denoted by $\vec{v}$) is a quantity that has magnitude and direction in the complex plane $\mathbb{C}$.
\qquad \textcolor{blue}{$\blacksquare$}
\end{definition}

\begin{figure}[!ht]
	\centering
\includegraphics[width=125mm]{nearVfs.png}
  \caption{Characteristically Near Vector Fields in Polar Complex Plane:
	\boxed{\mbox{[left]$\vec{V}f_1$},stable},\boxed{\mbox{[right]$\vec{V}f_2$},stable}}
	\label{fig:nearVfs}
\end{figure} 

\begin{definition}\label{def:Vf0}{\bf (Vector Field in the Complex Plane).}\\
Let $U = \left\{p\in \mathbb{C}\right\}$ be a bounded region in the complex plane containing points $p(x,jy)\in U$. A {\bf vector field} is a mapping $F:U\to 2^{\mathbb{C}}$ defined by\\ 

\vspace*{0.2cm}

\begin{center}
\boxed{\boldsymbol{
F(p(x,jy)) = \left\{\vec{v}\right\}\in 2^{\mathbb{C}}\ 
\mbox{\bf (denoted by\ $\vec{V}f$)}
\mbox{\qquad \textcolor{blue}{$\blacksquare$}}
}}
\end{center}
\end{definition}

\vspace*{0.2cm}

\begin{mdframed}[backgroundcolor=green!15]
\begin{axiom}\label{axiom: PhysSysRepresentation}{\bf (Physical System Representation Axiom).}\\
Every physical system has a represention as a vector field in the complex plane.
\qquad \textcolor{blue}{$\blacksquare$}
\end{axiom}
\end{mdframed}\mbox{}\\

\vspace*{0.2cm}

\begin{remark}{\bf (Practical Outcomes of Axiom~\ref{axiom: PhysSysRepresentation}).}\\
Axiom~\ref{axiom: PhysSysRepresentation} has a number of practical outcomes in the design and evaluation of systems.  Let $\vec{V}f(\mathcal{O})$ be a vector field representation of a system $\mathcal{O}$ (collection of objects in a system).  Then
\begin{compactenum}
\item Every object $x\in \mathcal{O}$ is represented by a vector 
\boxed{\boldsymbol{\vec{x}\in\vec{V}f(\mathcal{O})\in \mathcal{C}}}.
\item Every object $x\in \mathcal{O}$ is measurable in terms of a radius $r_{\vec{V}f(\mathcal{O})}$:\\

\vspace*{0.2cm}

\begin{center}
\boxed{\boldsymbol{
r_{\vec{V}f(\mathcal{O})} =\ \mbox{distance of the tip of}\ \vec{v}\ \ \mbox{from the origin}\ \vec{0}\in \vec{V}f(\mathcal{O}).
}}
\end{center}

\vspace*{0.5cm}

and angle $\theta_{\vec{v}f(\mathcal{O})} $:\\

\vspace*{0.2cm}

\begin{center}
\boxed{\boldsymbol{
\theta_{\vec{V}f(\mathcal{O})} =\ \mbox{direction of}\ \vec{v}\in \vec{V}f(\mathcal{O}).
}}\ \mbox{\qquad \textcolor{blue}{$\blacksquare$}}
\end{center}

\vspace*{0.2cm}

\end{compactenum} 
\end{remark}

\vspace*{0.2cm}

\begin{remark}{\bf (Polar Form of a Complex Number).}\\ 
Recall that a complex number $z$ in polar form (introduced by Euler~\cite[\S VIII, p. 112]{Euler1748}) is written \boxed{\boldsymbol{z=re^{j\theta}=cos\theta+jsin\theta}}. For the geometry of the polar complex plane plots of $re^{j\theta}$ like those in Fig.~\ref{fig:polarZ} and Fig.~\ref{fig:nearVfs}, see T. Needham~\cite{Needham1997}.
\qquad \textcolor{blue}{$\blacksquare$}
\end{remark}

\vspace*{0.2cm}

\begin{definition}\label{def:Krantz}{\bf (Krantz Vector Field Stability Condition~\cite{Krantz2010}).}\\
A vector field $\vec{V}f$ in the complex plane is stable, provided each $\vec{V}f$ lies either within or on the boundary of the unit circle centered at $\boldsymbol{0}$ in $\mathbb{C}$. \qquad \textcolor{blue}{$\blacksquare$}
\end{definition}

\vspace*{0.2cm}
\begin{example}
Two examples of stable vector fields in polar form are given in Fig.~\ref{fig:nearVfs}. In both cases, observe that all of the vectors in the fields in Fig.~\ref{fig:nearVfs} lie within the boundary of the unit circle in the complex plane.  Hence, from Def.~\ref{def:Krantz}, both vector fields are stable. 
\qquad \textcolor{blue}{$\blacksquare$}
\end{example}

