\begin{lemma}\label{lemma:charGroup}{\bf (Stein-Weiss Multiplicative Vector Field Group~\cite[\S IV.5, p. 173]{Stein1971}).}\\
The vector field $\vec{V}f(t) = e^{\pm jt}$ with multiplication $\cdot$ on its exponentials is an abelian Stein-Weiss group
\boxed{G(\left\{e^{\pm jt}\right\},\cdot)}.
\end{lemma}
\begin{proof}
Let $\vec{V}f = \left\{e^{\pm jt}\in\mathbb{C}\right\}$ be a vector field in the complex plane and observe
\begin{align*}
e^0 &= \vec{1}\in \vec{V}\ \mbox{\bf (multiplicative identity), since}\\
    & e^{\pm jt}e^0 = e^{\pm jt + 0} = e^{\pm jt}.\\
\vec{z}\in \vec{V}f  & = e^{jt}\\
                     &= cos t + jsin t\in \mathbb{C}.\\
\vec{z}^* &= e^{-jt}\ \mbox{\bf (conjugate of $\vec{z}$).}\\
          &= cos t - jsin t\in \mathbb{C}\ \mbox{\bf (multiplicative inverse of $e^{jt}$)}, i.e.,\\								
\vec{z}\cdot \vec{z}^* &= e^{jt}e^{-jt} = e^{j(t-t)} = e^0.  
\end{align*}
Hence, \boxed{G(\left\{e^{\pm jt}\right\},\cdot)} is a vector field group.  From 
\begin{center}
\boxed{\boldsymbol{
e^{jt}e^{jt'} = e^{jt+jt'} = e^{j(t+t')} = e^{j(t'+t)}
= e^{jt'}e^{jt},
}}
\end{center}
the Stein-Weiss group is abelian.
\end{proof}

\begin{theorem}\label{lemma:charGroup}{\bf (Stein-Weiss Additive Vector Field Group).}\\
Let the vector field $\vec{V}f:\mathbb{C}\to\mathbb{C}$ be defined by
$\vec{V}f(\pm z) = \pm z$. 
\boxed{G(\left\{\vec{V}f(\pm z)\right\},+)} is an additive abelian vector field group. 
\end{theorem}
\begin{proof}
Let $\vec{V}f = \left\{\vec{V}f(\pm z)\right\}$ be a vector field in the complex plane and observe
\begin{align*}
\vec{0}\in \vec{V} & = 0 + 0j\ \mbox{(zero) vector = additive identity)}.\\ 
\vec{z}\in \vec{V}f  & = a + bj,\ a,b\in \mathbb{R}.\\
\vec{-z}\in \vec{V}  & = -a - bj.\\
\vec{z} + \vec{0} &= a + bj + 0 + 0j = a + bj = \vec{z}.\\
\vec{z} + \vec{-z} &= a + bj + (-a - bj) = 0 + 0j = \vec{0}   
\end{align*}
Hence, \boxed{G(\left\{\vec{V}f(\pm z)\right\},+)} is a vector field group.
Also,   
\begin{center}
\boxed{\boldsymbol{
e^{jt}+e^{jt'} = e^{jt'}+e^{jt},
}}
\end{center}
Hence, $G$ is abelian.
\end{proof}

