\begin{definition}\label{def:charFn}{\bf (Characteristic Function in Complex Plane).}\\
A characteristic mapping $\varphi:\mathbb{C}\to \mathbb{C}$ is defined by
\begin{center}
\boxed{\boldsymbol{
\varphi(z\in \mathbb{C})=\varepsilon\in [-1,1]\in 2^{\mathbb{C}}.
}}
\end{center}
Every object $A$ has a set of characteristics $\Phi(A)$, i.e.,
\begin{center}
\boxed{\boldsymbol{
\Phi(A)=\left\{\varphi(a_i):i\geq 1,a_i\in A \right\}
\in 2^{\mathbb{C}}.\ 
\mbox{\qquad \textcolor{blue}{$\blacksquare$}}
}}
\end{center}

\end{definition}

\vspace*{0.2cm}

\begin{remark}{\bf (Characteristic Functions are Holomorphic).}\\
Let $z_0,h$ be complex numbers in $\mathbb{C}$ (complex plane), for $h\neq 0$. The function $f:\mathbb{C}\to\mathbb{C}$ is holomorphic~\cite[\S 2.1, p. 8]{Stein2003}, provided 
\begin{center}
\boxed{\boldsymbol{
f'(z_0\in\mathbb{C}) = 
\mathop{lim}\limits_{h\to 0} \frac{f(z_0+h) - f(z_0)}{h}\to 0,
}}
\end{center}

\vspace*{0.5cm}

\noindent i.e., the derivative of $f$ converges to 0 when $h\to 0$. 
For example, the characteristic function $\varphi(z)$ is holomorphic, since $\varphi(z)$ is a constant and the derivative \boxed{\varphi'(z_0)=0} for every fixed complex number $z_0$ in the complex plane (see, e.g., a similar observation by S. Krantz~\cite{Krantz2008}).
\qquad \textcolor{blue}{$\blacksquare$}
\end{remark}
%\end{mdframed}

\vspace*{0.2cm}

\begin{definition}\label{def:dnear0}{\bf (Characteristic Distance).}\\  
Let $X,Y\in 2^{\mathbb{C}}, A\in 2^X,B\in 2^Y$ be nonempty sets in the polar complex plane and $a\in A,b\in B$ and let $\varphi(a)\in\Phi(A),\varphi(b)\in\Phi(B)$ be characteristics of objects $a\in A$ and $b\in B$.  
The characteristic distance mapping $d^{\Phi}: 2^X\times 2^Y\to\mathbb{C}$ is defined by\\

\vspace*{0.2cm}

	\begin{center}
		\boxed{\boldsymbol{
		d^{\Phi}(A,B)=\inf_{\substack{a\in A \\ b\in B}} 
		\left\{(\varphi(a) - \varphi(b))mod 2\right\} = \varepsilon\in[-1,1]\in 2^{\mathbb{C}}.
\mbox{\qquad \textcolor{blue}{$\blacksquare$}}
	}}
	\end{center}

\end{definition}

\vspace*{0.2cm}

\begin{remark}
The original version of the characteristic distance (limited to distances in [0,1] for characteristically near sets) was introduced in~\cite[Def. 1]{peters2025indefinitedescriptiveproximitiesinherent}.\mbox{\qquad \textcolor{blue}{$\blacksquare$}}
\end{remark}

\vspace*{0.2cm}

\begin{example}\label{def:char}{\bf (Stein-Weiss Characteristic~\cite[\S 5.1, p. 173]{Stein1971})).}\\
The mapping $\varphi:\mathbb{C}\to\mathbb{C}$ defined by \boxed{\varphi(t)=e^{\pm jt}} is characteristic. 
\qquad \textcolor{blue}{$\blacksquare$}
\end{example} 

\vspace*{0.2cm}

\begin{remark}
In Def.~\ref{def:charFn}, the values of the characteristic function $\varphi(z)$ are in the interval [-1,1] in the polar complex plane, which dovetails with characteristics of pairs of nonempty sets that are either characteristically near or far apart (see, e.g.,~\cite{Naimpally2013}).  That is, pairs of sets $A$ and $B$ have a characteristic distance that is in one of the following intervals:

\begin{align*}
\boldsymbol{0}\ & \mbox{if $A$ and $B$ have matching characteristics.}\\
\boldsymbol{(0,1]}\ & \ \mbox{if $A$ and $B$ are characteristically close, i.e.,}\\
   &~\mbox{if $A$ and $B$ have numerically close characteristics.}\\
\vec{z}\in \vec{V}f  & = a + bj,\ a,b\in \mathbb{R}.\\
\boldsymbol{-1} &\ \mbox{if $A,B$ have no matching characteristics, i.e.,}\\
   &\ \mbox{if $A,B$ are characteristicall far apart}\\
\boldsymbol{(-1,0)} &\ \mbox{if $A,B$ have non-matching but numerically close characteristic values.}
%\vec{-z}\in \vec{V}  & = -a - bj.\\
%\vec{z} + \vec{0} &= a + bj + 0 + 0j = a + bj = \vec{z}.\\
%\vec{z} + \vec{-z} &= a + bj + (-a - bj) = 0 + 0j = \vec{0}   
\end{align*}

In other words, the interval \boxed{\boldsymbol{\ [-1,1]\ }} represents the spectrum of characteristics distances between pairs of objects that are either characteristically near each other in the interval \boxed{\boldsymbol{\ [0,1]\ }} or characteristically far apart in the interval \boxed{\boldsymbol{\ [-1,0)\ }}.
\qquad \textcolor{blue}{$\blacksquare$}
\end{remark}

