\section{Characteristic Nearness Approximation Spaces (cNAS)}
\noindent The basis for each cNAS built on a nonempty set of objects \boxed{\mathcal{O}=\left\{x_i\right\},1\leq i\leq \infty} is threefold, namely,\\ 

\vspace*{0.2cm}

\begin{compactenum}[{{\bf cNAS}-}1$^o$]
\item The identification of objects in a cNAS is guided by Axiom~\ref{axiom:cNASobject}.\\

\vspace*{0.2cm}

\begin{mdframed}[backgroundcolor=green!15]
\begin{axiom}\label{axiom:cNASobject}{\bf (Object Characteristic Axiom).}\\
The characteristic of every object is a complex number.
\qquad \textcolor{blue}{$\blacksquare$}
\end{axiom}
\end{mdframed}\mbox{}\\

\vspace*{0.2cm}

\item The identification of a characteristic mapping for each characteristic of an object in $x\in \mathcal{O}$, namely,\\
%
\vspace*{0.2cm}

\begin{center}
\boxed{\boldsymbol{
\varphi:\mathcal{O}\to \mathbb{C},\ \mbox{defined by}\ 
        \varphi(x)= a + bi\in \mathbb{C}, a,b\in\mathbb{R}.
}}
\end{center}

\vspace*{0.2cm}

\noindent from a set of objects to the complex plane
\item Identification of a vector of characteristics
%\\
%
%\vspace*{0.2cm}

\begin{center}
\boxed{\boldsymbol{
\vec{\Phi}(\mathcal{O}) =\left(\varphi_i(x),1\leq i\leq \infty\right)\in\mathbb{C}^n    
				\mbox{(vector of characteristics of $x\in\mathcal{O}$)}.
}}
\end{center}

\vspace*{0.2cm}

\noindent of objects in a set.  Each $\varphi_1(x)$ is a characteristic of $x\in\mathcal{O}$. \qquad \textcolor{blue}{$\blacksquare$}
\end{compactenum}\mbox{}\\

\vspace*{0.2cm}

\noindent A framework for the introduction of a cNAS is given in Def.~\ref{def:cNAS}.\\

\vspace*{0.2cm}

\begin{definition}\label{def:cNAS}{\bf (Framework for a Characteristic Nearness Approximation Space).}\\  
A Characteristic Nearness Approximation Space (cNAS) is a tuple\\ 
\begin{center} 
\boxed{\boldsymbol{
\left(\mathcal{O},\vec{\Phi}(\mathcal{O}),d^{\Phi}(A,B),x \ \widetilde{\ \Phi\ }\  y,\left[ x \right],N(\vec{\Phi}(\mathcal{O})),N_*(B),N^*(B)\right)
}}
\end{center}

\vspace*{0.2cm}

defined in the following table. 
\begin{equation*}
\begin{array}{c|l}
Symbol & Interpretation \\ \hline 
\mathcal{O} &=\left\{x_i\right\},1\leq i\leq \infty\ \mbox{(Set of objects)}.\\
A,B &\in 2^{\mathcal{O}}.\\
(x,y) &\in \mathcal{O}\times \mathcal{O}.\\
\varphi:\mathcal{O}\to \mathbb{C} &\mbox{defined by}\ 
        \varphi(x)= a + bi\in \mathbb{C}, a,b\in\mathbb{R}  
        \mbox{(characteristic mapping)}.\\
\vec{\Phi}(\mathcal{O}) &=\left(\varphi_i(x),1\leq i\leq \infty\right)\in\mathbb{C}^n\  \mbox{(vector of characteristics of $x\in\mathcal{O}$)}.\\
d^{\Phi}(A,B) &=\inf_{\substack{a\in A \\ b\in B}}\left\{ \varphi(a) - \varphi(b)\right\} = \varepsilon\in [-1,1]\in 2^{\mathbb{C}}\  \mbox{(characteristic distance)}\\ 
 A\ \widetilde{\ \Phi\ }\ B &= \left\{(a,b)\in A\times B:d^{\Phi}(A,B)=0\right\}.\ \mbox{(characteristic equivalence)}.\\
\left[x \right] &=\left\{y\in \mathcal{O}: y 
\ \widetilde{\ \Phi\ }\  x,\ 
x\in\mathcal{O} \right\}\ \mbox{(equivalence class)}.\\
N(\left[x\right]) &=\left\{[y]:y\ \widetilde{\ \Phi\ }\ x,\ 
x\in\mathcal{O}\right\} 
     \mbox{(set of neighboring partitions of $\mathcal{O}$)}.\\
N_*(B)X &=\mathop{\bigcup}\limits_{b\in B}\left\{\left[b\right]\in 2^B\right\}\subset \mathop{\bigcup}\limits_{x\in X}
          \left\{\left[x\right]\in 2^X\right\}\ \mbox{(lower approximation of $X\in 2^{\mathcal{O}}$)}.\\
N^*(B)X &=\mathop{\bigcup}\limits_{b\in B}\left\{\left[b\right]\in 2^B\right\}\cap \mathop{\bigcup}\limits_{b\in B}
          \left\{\left[x\right]\in X\right\}\ \mbox{(upper approximation of $X\in 2^{\mathcal{O}}$)}.\\ 
					\hline
\end{array}%
\end{equation*}
%\qquad \textcolor{blue}{$\blacksquare$}
\end{definition}

\begin{equation*}
\text{\textit{Table} }4\text{. Characteristic Nearness Approximation Space Framework}
\end{equation*}
\begin{flushleft}

\end{flushleft}
%\vspace*{0.2cm}

\begin{remark}{\bf (Characteristic Foundation of a cNAS).}\\
A cNAS is built on a nonempty set of objects with measurable characteristics.  Each characteristics an object $x$ is represented by a characteristic function \boxed{\varphi(x)} with values in the complex plane. The foundation of a cNAS i is Axiom~\ref{ax:cNASbasis}.
\qquad \textcolor{blue}{$\blacksquare$}
\end{remark}\mbox{}\\

