\begin{theorem}
Let $A,B\in 2^{\mathcal{O}}$.
$A \mathop{\sim}\limits_{\Phi}B \Leftrightarrow A\ \dnear\ B$.
\end{theorem}
\begin{proof}\mbox{}\\
$\Rightarrow$: From Table~\ref{table:VfChar}, we have
\begin{center}
\boxed{\boldsymbol{
A\mathop{\sim}\limits_{\Phi}B = \left\{(x,y)\in A\times B:d^{\Phi}(A,B)=0\right\}.
}}
\end{center}

Recall that $A$ is near $B$, provided $d^{\Phi}(A,B)=0$, i.e., the greatest lower bound of the set of differences $\abs{\varphi(a)-\varphi(b)}, a\in A,b\in B$, is zero.  In other words, for the relation between $A,B$ in $A\mathop{\sim}\limits_{\Phi}B$, the pairs of objects $(x,y)\in A\times B$ have at least on matching characteristic.\\
$\Leftarrow$: From Def.~\ref{def:dnear0} and the proof of $\Rightarrow$, we have
\begin{center}
\boxed{\boldsymbol{
A\ \dnear B \equiv \left\{(x,y)\in A\times B:d^{\Phi}(A,B)=0\right\}\ \Leftrightarrow A\mathop{\sim}\limits_{\Phi}B.
}}
\end{center}
\end{proof} 


\begin{definition}\label{def:nearness}{\bf (Characteristic Nearness of Systems~\cite{peters2025}).}\\
Let $X,Y$ be a pair of systems.  For nonempty subsets $A\in 2^X, B\in 2^Y$, the characteristic nearness of $A,B$ (denoted by $A\ \rnear\ B$) is defined by\\

\vspace*{0.2cm}

\begin{center}
\boxed{\boldsymbol{
A\ \dnear\ B \Leftrightarrow
d^{\boldsymbol{\Phi}}(A,B)=0.
\mbox{\qquad \textcolor{blue}{$\blacksquare$}}  
}}
\end{center}
\end{definition}

\vspace*{0.2cm}

\begin{theorem}\label{lemma:nearLowerApprox}{\bf (Charactistically Near Lower Approximations).}\\
\boxed{N(\vec{\Phi}(A))\ \dnear\ N(\vec{\Phi}\iota(B))\ \Leftrightarrow N_*(A)X\ \dnear\ 
N_*(B)X.}  
\end{theorem}
\begin{proof}
Let $\varphi(x)\in \vec{\Phi}(X):\varphi(x) = [x]$ and let $A,B\subset X$.  Then,
from Theorem~\ref{theorem:nearness},$N(\vec{\Phi}(A))\ \dnear\ (\vec{\Phi}(B))$ implies 
\begin{center}
\boxed{\boldsymbol{
\exists [a]\in N(\vec{\Phi}(A)), [b]\in N(\vec{\Phi}(B)):N_*(A)X\ \dnear\ 
N_*(B)X.
}}
\end{center}
\end{proof}

\vspace*{1.2cm}

\begin{mdframed}[backgroundcolor=green!15]
\begin{theorem}\label{theorem:nearness}{\bf (Fundamental Theorem of Near Systems)}.\\
Let $X,Y$ be a pair of systems with $A\in 2^X,B\in 2^Y$.

\begin{center}
\boxed{\boldsymbol{
A\ \dnear\ B\ \Leftrightarrow\ \exists a\in A,b\in B:
\abs{\varphi(a)-\varphi(b)} = 0.
}}
\end{center}
\end{theorem}
\begin{proof}$\mbox{}$\\
\boxed{\Rightarrow}: From Def.~\ref{def:dnear0}, $A\ \dnear\ B$ implies that there is at least one pair $a\in A, b\in B$ such that $d^{\Phi}(A,B)=\abs{\varphi(a) - \varphi(b)}  = 0$, i.e, when $a=b$.\\
\noindent \boxed{\Leftarrow}:
Given $d^{\Phi}(A,B) =0$, we know that $\inf_{\substack{a\in A \\ b\in B}} \abs{\varphi(a) - \varphi(b)} = 0\in\mathbb{C}$. Hence, from Def.~\ref{def:nearness}, $A\ \dnear\ B$, also.  
That is, sufficient nearness of at least one pair characteristics $\varphi(a\in A), \varphi(b\in B)\in [0,1]$ such that $a=b$ indicates the characteristic nearness of the sets, i.e., we conclude $A\ \dnear\ B$. 
\end{proof}
\end{mdframed}

