\section{Characteristically Near Stein-Weiss Vector Field Groups}

In this section, we introduce characteristically near vector field groups.   First, we consider a pair of groups inherent in Euler vector fields in the complex plane.

\begin{lemma}\label{lemma:symmetricFields}{\bf (Symmetric Euler Vector Field).}\\
Every Euler vector field \boxed{\vec{V}(t) = e^{jt},t\in [-k,+k]\in\mathbb{C},k\in\mathbb{R}} is symmetric about the origin in the complex plane.
\end{lemma}
\begin{proof}
Since $t\in [-k,+k]$ in $\mathbb{C}$, then $\vec{V}(t)$ is symmetric about the origin in the complex plane.
\end{proof}

\begin{lemma}\label{lemma:groupClasses}{\bf (Symmetric Vector Field Group Classes).}\\
Every Vector Field Group symmetric about the origin contains equivalence classes with real parts that differ only in terms of their sign.
\end{lemma}
\begin{proof}
From Theorem~\ref{lemma:charGroup}, a vector field in the complex plane is a group.
From Lemma~\ref{lemma:symmetricFields}, an Euler vector field
$\vec{V}(t) = e^{jt}$ defined on $t\in [-k,+k]$ in $\mathbb{C}$ is symmetric about the origin in $\mathbb{C}$. 
Hence, $\vec{V}(t)$ contains equivalence classes that differ only in terms of their sign.
\end{proof}

\begin{theorem}\label{theorem:symmetricVfgroups}{\bf (Characteristically Near Stein-Weiss Multiplicative Groups).}\\
Every pair of Stein-Weiss multiplicative groups symmetric about the origin are characteristically near groups.
\end{theorem}
\begin{proof}
From Lemma~\ref{lemma:charGroup}, 
\boxed{G_1(\left\{e^{jk_1\theta}\right\},\cdot),
       G_2(\left\{e^{jk_2\theta}\right\},\cdot)}
is a pair of Stein-Weiss multiplicative groups.  From Lemma~\ref{lemma:symmetricFields}, groups $G_1,G_2$ are symmetric about the origin.  And from Lemma~\ref{lemma:groupClasses}, groups $G_1,G_2$ contain identical classes stemming from the fact that each of the Stein-Weiss $G_1,G_2$ groups contain identical elements close to the origin in $\mathbb{C}$.  From what we have observed, we can define a pair of characteristic functions, namely,
\begin{center}
\boxed{\boldsymbol{\
\varphi(G_1) = [x],x\in\mathbb{C},\varphi(G_2) = [y],y\in\mathbb{C},\abs{\varphi(G_1)-\varphi(G_2)} = 0.
}}
\end{center}

\noindent From Theorem~\ref{theorem:nearness}, 
\boxed{\vec{\Phi}(G_1)\ \rnear\ \vec{Phi}(G_2)}.  Hence, from Lemma~\ref{lemma:nearLowerApprox}, we have a pair of neighborhoods
\boxed{N(\vec{\Phi}(G_1))\ \dnear\ N(\vec{\Phi}(G_2))\Leftrightarrow
N_*(G_1)X\ \dnear\ N_*(G_1)X}.
\end{proof}

\vspace*{0.2cm}

\begin{theorem}\label{theorem:symmetricVfgroups2}{\bf (Characteristically Near  Stein-Weiss Additive Groups).}\\
Every pair of Stein-Weiss additive groups $G_1(\left\{e^{jk_1\theta}\right\},+),
       G_2(\left\{e^{jk_2\theta}\right\},+)$ symmetric about the origin are characteristically near groups.
\end{theorem}
\begin{proof}
Symmetric with the proof of Theorem~\ref{theorem:symmetricVfgroups}.
\end{proof}

