	\title[Inhomogeneous biharmonic NLS system]{BLOW-UP RESULTS FOR INHOMOGENEOUS FOURTH-ORDER NONLINEAR SCHRÖDINGER EQUATION}




	\author[M. Hespanha]{Maicon Hespanha}
	\author[R. Scarpelli]{Renzo Scarpelli}\address{ICEx, Universidade Federal de Minas Gerais, Av. Antônio Carlos, 6627, Caixa Postal 702, 30123-970 Belo Horizonte, MG, Brazil}
