\section{Proof of \eqref{mom_post_2} and of the LLN \eqref{lln_post} \label{proof1}}
The proof of \eqref{mom_post_2} follows the same lines when $\alpha \in (0, 1)$ or $\alpha = 0$, relying on representations \eqref{bino_rap} and \eqref{bino_rap0} respectively; we split the two cases for the sake of clarity. The LLN \eqref{lln_post}  follows directly from \eqref{mom_post_2} and its proof is carried out at the end of the section.
\subsection{Proof of \eqref{mom_post_2} in the case $\alpha \in (0, 1)$} \label{sec:proof_asy_1}
We resort to representation \eqref{bino_rap} which, in the regime $\theta = \tau m ,\,  n = \nu m, \, j = \varrho m$, becomes
$$  K_m^{(n)} \stackrel{\text{d}}{ =} Q\left(K_m^*, \, B_{\left(\frac{\tau}{\alpha} + \varrho\right)\, m, \,  \left(\frac{\nu}{\alpha} - \varrho\right)\, m }\right)
$$
By the law of total expectation and recalling the expression for the mean of the beta-binomial distribution, the asymptotics for the mean of $K_m^*$ in \eqref{mom2} and the definitions of $\mathfrak{m}_{\alpha, \lambda}$  and $\mathscr{M}_{\alpha, \tau, \nu, \varrho}$ in the case $\alpha \in (0, 1)$, 
\begin{align*}
 %\mathbb{E} \left[ K_{m, n} \, \big| \, \mathbf{X}_n\right] = 
 \mathbb{E} \left[K_m^{(n)} \right] &= \mathbb{E} \left[ \mathbb{E} \left[Q\left(K_m^*, \, B_{\left(\frac{\tau}{\alpha} + \varrho\right)\, m, \,  \left(\frac{\nu}{\alpha} - \varrho\right)\, m }\right) \, \bigg| \, K_m^* \right] \right]\\
 &  = \mathbb{E} \left[ K_m^* \cdot \frac{\tau + \varrho \alpha}{\tau + \nu}\right]\\
 & = m \cdot \mathfrak{m}_{\alpha, \lambda} \,  \frac{\tau + \varrho \alpha}{\tau + \nu} + O(1)\\
 & = m \cdot \mathscr{M}_{\alpha, \tau, \nu, \varrho} + O(1)
\end{align*}
By the law of total variance, and recalling the expression for the moments of the beta-binomial distribution, the asymptotics in \eqref{mom2} and the definitions of $\mathfrak{m}_{\alpha, \lambda}, \mathfrak{s}_{\alpha, \lambda}$ and $\mathscr{S}_{\alpha, \tau, \nu, \varrho}$ in the case $\alpha \in (0, 1)$, 
\begin{align*}
 %\mathbb{E} \left[ K_{m, n} \, \big| \, \mathbf{X}_n\right] = 
 & \operatorname{Var}\left(K_m^{(n)} \right) \\
 &\quad = \mathbb{E} \left[ \operatorname{Var} \left(Q\left(K_m^*, \, B_{\left(\frac{\tau}{\alpha} + \varrho\right)\, m, \,  \left(\frac{\nu}{\alpha} - \varrho\right)\, m }\right) \, \bigg| \, K_m^* \right) \right] \\
 &\quad  \quad + \operatorname{Var} \left( \mathbb{E}\left[Q\left(K_m^*, \, B_{\left(\frac{\tau}{\alpha} + \varrho\right)\, m, \,  \left(\frac{\nu}{\alpha} - \varrho\right)\, m }\right) \, \bigg| \, K_m^* \right] \right)\\
 %
 & \quad  = \mathbb{E} \left[ K_m^* \, \frac{(\tau + \varrho \alpha)(\nu - \varrho \alpha)}{(\tau+ \nu)^2} \, \left(1 - \frac{\alpha}{(\tau + \nu)m+\alpha}\right)  
+ \frac{\left(K_m^*\right)^2}{m} \, \frac{(\tau + \varrho \alpha)(\nu - \varrho \alpha)}{(\tau+ \nu)^2 } \, \frac{\alpha m}{(\tau+\nu) m + \alpha} \right] \\
 &\quad  \quad +  \operatorname{Var} \left( K_m^* \cdot \frac{\tau + \varrho \alpha}{\tau + \nu}\right)\\
 %
 &\quad  =  \left[  m \cdot \mathfrak{m}_{\alpha, \lambda} + O(1)  \right] \cdot \frac{(\tau + \varrho \alpha)(\nu - \varrho \alpha)}{(\tau+ \nu)^2} \left[ 1 + O\left(\frac{1}{m}\right)\right] + m \cdot \mathfrak{s}_{\alpha, \lambda} \,  \frac{(\tau + \varrho \alpha)^2}{(\tau + \nu)^2} + O(1)\\
 & \quad \quad + \frac{ m^2\cdot \mathfrak{m}_{\alpha, \lambda}^2 +O(m)}{m} \cdot  \frac{(\tau + \varrho \alpha)(\nu - \varrho \alpha)}{(\tau+ \nu)^2 } \left[ \frac{\alpha}{(\tau + \nu)  } +  O \left(\frac{1}{m}\right)\right]\\
 %
 & \quad = m \left[ \mathfrak{m}_{\alpha, \lambda} \frac{(\tau+\varrho \alpha)(\nu - \varrho \alpha)}{(\tau + \nu)} + \mathfrak{s}_{\alpha, \lambda}\frac{(\tau+\varrho \alpha)^2}{(\tau + \nu)} + \mathfrak{m}^2_{\alpha, \lambda}\frac{ \alpha (\tau+\varrho \alpha)(\nu - \varrho \alpha)}{(\tau + \nu)^3} \right] +O(1)\\
  & \quad = m \cdot \mathscr{S}_{\alpha, \tau, \nu, \varrho} + O(1)
\end{align*}

\subsection{Proof of \eqref{mom_post_2} in the case $\alpha = 0$} \label{sec:proof_asy_2}
We resort to representation \eqref{bino_rap0} which, in the regime $\theta = \tau m ,\,  n = \nu m$, becomes
$$  K_m^{(n)} \stackrel{\text{d}}{ =} Q\left(K_m^*, \, \frac{\tau}{\lambda}\right)$$
%Note that in this case the distribution of $K_m^{(n)}$ does not depend on the number $j$ of distinct species in the sample of length $n$. 
By the law of total expectation, and recalling the expression for the mean of the binomial distribution, the asymptotics for the mean of $K_m^*$ in \eqref{mom2} and the definitions of $\mathfrak{m}_{0, \lambda}$  and $\mathscr{M}_{0, \tau, \nu, \varrho}$, 
\begin{align*}
 %\mathbb{E} \left[ K_{m, n} \, \big| \, \mathbf{X}_n\right] = 
 \mathbb{E} \left[K_m^{(n)} \right] &= \mathbb{E} \left[ \mathbb{E} \left[Q\left(K_m^*, \, \frac{\tau}{\lambda}\right) \, \bigg| \, K_m^* \right] \right]\\
 &= \mathbb{E} \left[ K_m^* \cdot \frac{\tau }{\lambda}\right]\\
 & = m \cdot \mathfrak{m}_{0, \lambda} \,  \frac{\tau }{\lambda} + O(1)\\
 & = m \cdot \mathscr{M}_{0, \tau, \nu, \varrho} + O(1)
\end{align*}
By the law of total variance, and recalling the expression for the moments of the binomial distribution, the asymptotics in \eqref{mom2} and the definitions of $\mathfrak{m}_{0, \lambda}, \mathfrak{s}_{0, \lambda}$ and $\mathscr{S}_{0, \tau, \nu, \varrho}$, 
\begin{align*}
 %\mathbb{E} \left[ K_{m, n} \, \big| \, \mathbf{X}_n\right] = 
 \operatorname{Var}\left(K_m^{(n)} \right) &= \mathbb{E} \left[ \operatorname{Var} \left(Q\left(K_m^*, \, \frac{\tau}{\lambda}\right) \, \bigg| \, K_m^* \right) \right] + \operatorname{Var} \left( \mathbb{E}\left[Q\left(K_m^*, \, \frac{\tau}{\lambda} \right) \, \bigg| \, K_m^* \right] \right)\\
 &  = \mathbb{E} \left[ K_m^* \cdot \frac{\tau \nu}{\lambda^2} \right]  +  \operatorname{Var} \left( K_m^* \cdot \frac{\tau}{\lambda }\right)\\
 & =   m \cdot \mathfrak{m}_{0, \lambda}  \cdot \frac{\tau \nu}{\lambda^2} + O(1)  + m \cdot \mathfrak{s}_{0, \lambda} \,  \frac{\tau^2}{\lambda^2} + O(1)\\
  & = m \cdot \mathscr{S}_{0, \tau, \nu, \varrho} + O(1)
\end{align*}

\subsection{Proof of the LLN \eqref{lln_post}} \label{sec:lln_proof}
To prove the LLN \eqref{lln_post}, we fix $\varepsilon >0$ and combine Chebychev inequality with the (variance) asymptotic expansion \eqref{mom_post_2}. In particular, we write
\begin{align*}
P\left[\left| \frac{K_m^{(n)} - \mathbb{E}\left[K_m^{(n)}\right]}{m} \right|> \varepsilon \right]& = P \left[\left| K_m^{(n)} - \mathbb{E}\left[K_m^{(n)}\right] \right| > m\varepsilon \right]\\
& \le \frac{\operatorname{Var}\left(K_m^{(n)}\right)}{m^2 \varepsilon^2}\\
&= O\left(\frac{1}{m}\right) \rightarrow 0
\end{align*}
as $m \rightarrow +\infty$. Since the asymptotic expansion \eqref{mom_post_1} of $\E\left[K_m^{(n)}\right]$ implies that $m^{-1}\mathbb{E}\left[K_m^{(n)}\right]\rightarrow \mathscr{M}_{\alpha, \tau, \nu, \varrho}$ as $m \rightarrow+\infty$, the proof is concluded by means of Slutsky's theorem.

\section{Proof of the CLT \eqref{clt_post}\label{proof2}}\label{sec:d}
We begin by providing some detail on the sketch of proof presented in section \ref{sec3}. Equality \eqref{F=I1+I2} follows from the chain of equalities
\begin{align*}
F_m(x) & =\int_0^{+\infty} P\left[Q_m(z) \le m\mathscr{M}_{\alpha, \tau, \nu, \varrho} + \sqrt{m} \mathscr{S}_{\alpha, \tau, \nu, \varrho} \, x \right] \ \mu_{\frac{K_m^*}{m}}(\mathrm{d} z) \\
& = \int_0^{+\infty} P\left[V_m(z) \le \frac{\sqrt{m}\, \left[\mathscr{M}_{\alpha, \tau, \nu, \varrho} - \mu(z)\right] + \mathscr{S}_{\alpha, \tau, \nu, \varrho} \, x}{\sigma(z)}\right] \ \mu_{\frac{K_m^*}{m}}(\mathrm{d} z) \\
& = \int_0^{+\infty}\Phi\left( \frac{\sqrt{m}\, \left[\mathscr{M}_{\alpha, \tau, \nu, \varrho} - \mu(z)\right] + \mathscr{S}_{\alpha, \tau, \nu, \varrho} \, x}{\sigma(z)} \right)\ \mu_{\frac{K_m^*}{m}}(\mathrm{d} z) \\
& \quad+ \int_0^{+\infty} \left\{F_{V_m(z)}\left( \frac{\sqrt{m}\, \left[\mathscr{M}_{\alpha, \tau, \nu, \varrho} - \mu(z)\right] + \mathscr{S}_{\alpha, \tau, \nu, \varrho} \, x}{\sigma(z)} \right) \right.\\
&\quad\quad\quad\quad\quad \left. - \Phi\left( \frac{\sqrt{m}\, \left[\mathscr{M}_{\alpha, \tau, \nu, \varrho} - \mu(z)\right] + \mathscr{S}_{\alpha, \tau, \nu, \varrho} \, x}{\sigma(z)} \right)\right\}\ \mu_{\frac{K_m^*}{m}}(\mathrm{d} z) \\
& = : \mathcal{I}^{(m)}_1(x) + \mathcal{I}^{(m)}_2(x).
\end{align*}

The following two lemmas make use Proposition \ref{p2} and the CLT for $K_m^*$,  i.e. \eqref{clt} of theorem \ref{thm_main}, and are instrumental to the proof of \eqref{rv_1} trough Proposition \ref{lem:lem3_ter}.

\begin{lem}
\label{lem:lem1_ter}
If $Y$ is a Gaussian random variable with mean $0$ and variance $\mathfrak{s}_{\alpha, \lambda}$, then
\begin{displaymath}
\mathbb{E} \left[\Phi\left(\frac{\mu'(\mathfrak{m}_{\alpha, \lambda}) Y + \mathscr{S}_{\alpha, \tau, \nu, \varrho} \, x}{\sigma\left(\mathfrak{m}_{\alpha, \lambda} \right)} \right)\right] = \Phi(x)
\end{displaymath}
for every $x\in \mathbb{R}$.
\end{lem}
\begin{proof}
We introduce a standard Gaussian random variable $Z$, with $Z$ independent from the random variable $Y$. By a standard property of conditional probability, 
\begin{displaymath}
\Phi\left(\frac{\mu'(\mathfrak{m}_{\alpha, \lambda}) Y + \mathscr{S}_{\alpha, \tau, \nu, \varrho} \, x}{\sigma\left(\mathfrak{m}_{\alpha, \lambda} \right)} \right) = P \left[ Z \le \frac{\mu'(\mathfrak{m}_{\alpha, \lambda}) Y + \mathscr{S}_{\alpha, \tau, \nu, \varrho} \, x}{\sigma\left(\mathfrak{m}_{\alpha, \lambda} \right)} \, \bigg| \,Y \right],
\end{displaymath}
which implies
\begin{displaymath}
\mathbb{E}\left[ \Phi\left(\frac{\mu'(\mathfrak{m}_{\alpha, \lambda}) Y + \mathscr{S}_{\alpha, \tau, \nu, \varrho} \, x}{\sigma\left(\mathfrak{m}_{\alpha, \lambda} \right)}\right)\right]= P \left[ \frac{\sigma(\mathfrak{m}_{\alpha, \lambda}) Z - \mu'(\mathfrak{s}_{\alpha, \lambda}) Y}{\mathscr{S}_{\alpha, \tau, \nu, \varrho} }\le x\right].
\end{displaymath}
To conclude, notice that $\frac{\sigma(\mathfrak{m}_{\alpha, \lambda}) Z - \mu'(\mathfrak{s}_{\alpha, \lambda}) Y}{\mathscr{S}_{\alpha, \tau, \nu, \varrho} }$ is a linear combination of independent Gaussian random variables, hence it is Gaussian with mean $0$ and variance
\begin{displaymath}
 \frac{ \sigma^2\left(\mathfrak{m}_{\alpha, \lambda}\right) + \mathfrak{s}_{\alpha, \lambda}^{2}\cdot \left(\mu'\left(\mathfrak{m}_{\alpha, \lambda}\right)\right)^2 }{\mathscr{S}_{\alpha, \tau, \nu, \varrho}^2} =1,
\end{displaymath}
where the last identity follows from Proposition \ref{p2}. This completes the proof. 
\end{proof}

\begin{lem}
\label{lem:lemma2_ter}
Let $\psi:[0, +\infty) \to \mathbb{R}$ be a continuous function such that $\psi \in C^1((0, +\infty))$. If the function $\psi$ has bounded (first) derivative, then as $n \to + \infty$
\begin{displaymath}
\sqrt{n} \left[\psi \left(\frac{K_m^*}{m}\right) - \psi(\mathfrak{m}_{\alpha, \lambda}) \right] \stackrel{\text{w}}{\longrightarrow}\mathcal{N}\left(0, (\psi'(\mathfrak{m}_{\alpha, \lambda}))^2 \mathfrak{s}_{\alpha, \lambda}^2\right)
\end{displaymath}
\end{lem}
\begin{proof}
By means of the fundamental theorem of calculus, we can write that
\begin{equation}\label{part21}
\sqrt{n} \left[\psi \left(\frac{K_m^*}{m}\right) - \psi(\mathfrak{m}_{\alpha, \lambda}) \right] = \sqrt{n} \left(\frac{K_m^*}{m} - \mathfrak{m}_{\alpha, \lambda}\right)\int_0^1 \psi'\left(\mathfrak{m}_{\alpha, \lambda} + t \left[ \frac{K_m^*}{m} - \mathfrak{m}_{\alpha, \lambda} \right]\right) \mathrm{d}t.
\end{equation}
By \eqref{lln}, we have that $m^{-1}K_m^*-\mathfrak{m}_{\alpha, \lambda} \stackrel{\text{p}}{\longrightarrow}0$, as $m\rightarrow+\infty$. Since $\psi'$ is bounded, as $m\rightarrow+\infty$
\begin{equation}\label{part22}
\int_0^1 \psi'\left(\mathfrak{m}_{\alpha, \lambda} + t \left[ \frac{K_m^*}{m} - \mathfrak{m}_{\alpha, \lambda} \right]\right) \mathrm{d}t \stackrel{\text{p}}{\longrightarrow} \psi'(\mathfrak{m}_{\alpha, \lambda})
\end{equation}
and, by \eqref{clt}, as $m\rightarrow+\infty$
\begin{equation}\label{part23}
\sqrt{n} \left(\frac{K_m^*}{m} - \mathfrak{m}_{\alpha, \lambda}\right) \stackrel{\text{w}}{\longrightarrow}\mathcal{N}\left(0,  \mathfrak{s}_{\alpha, \lambda}^2\right).
\end{equation}
From \eqref{part21}, with \eqref{part22} and \eqref{part23}, the proof completed by means of Slutsky's theorem.
\end{proof}


