\subsection{Proof of Proposition \ref{BE_Q} in the case $\alpha = 0$}\label{sec:d1}
\begin{proof}[\underline{Proof of \eqref{mean_Q} and \eqref{var_Q}}]
By a simple computation,
\begin{align*}
\mathbb{E}[Q_m(z)] &= \left\lfloor mz \right\rfloor  \cdot \frac{\tau}{\tau + \nu}\\
& = m z \cdot \frac{\tau}{\tau + \nu} - \left(m z - \left\lfloor mz \right\rfloor\right) \cdot\frac{\tau}{\tau + \nu}
\end{align*}
Since $m z - \left\lfloor mz \right\rfloor<1$ by definition, this proves the first equality. For the second equaility, 
\begin{align*}
 \operatorname {Var} \left(Q_m(z)\right)&= \left\lfloor mz \right\rfloor  \cdot \frac{\tau \nu}{(\tau + \nu)^2}\\
& = m z \cdot \frac{\tau \nu}{(\tau + \nu)^2}- \left(m z - \left\lfloor mz \right\rfloor\right) \cdot\frac{\tau \nu}{(\tau + \nu)^2}\\
& = m \sigma^2(z) + O(1)
\end{align*}
so that the $O(1)$ again accounts for the fact that we are discarding the floor function.
\end{proof}

\begin{proof}[\underline{Proof of \eqref{eq:be_Qm}}]
This is the standard Berry-Essen bound for the binomial distribution - see \citep[Chapter V, Theorem 4]{Pet(75)}.
\end{proof}

\subsection{Proof of Proposition \ref{BE_Q} in the case $\alpha \in (0, 1)$}	\label{sec:d2}
\begin{proof}[\underline{Proof of \eqref{mean_Q} and \eqref{var_Q}}]
By the law of total expectation, 
\begin{align*}
\mathbb{E}[Q_m(z)]&  = \mathbb{E} \left[\mathbb{E}\left[Q_m(z) \,  \bigg| \, B_{\left(\frac{\tau}{\alpha} + \varrho\right)\, m, \,  \left(\frac{\nu}{\alpha} - \varrho\right)\, m } \right]\right] \\
& = \left\lfloor mz \right\rfloor \mathbb{E}\left[ B_{\left(\frac{\tau}{\alpha} + \varrho\right)\, m, \,  \left(\frac{\nu}{\alpha} - \varrho\right)\, m } \right] \\
& = m z \cdot \frac{\tau + \varrho \alpha}{\tau + \nu} - \left(m z - \left\lfloor mz \right\rfloor\right) \cdot \frac{\tau + \varrho \alpha}{\tau + \nu}
\end{align*}
Since $m z - \left\lfloor mz \right\rfloor<1$ by definition, this proves the first equality. By the law of total variance,
\begin{align*}
 \operatorname {Var} \left(Q_m(z)\right)&=\mathbb{E} \left[\operatorname {Var} \left(Q_m(z) \, \bigg| \,  B_{\left(\frac{\tau}{\alpha} + \varrho\right)\, m, \,  \left(\frac{\nu}{\alpha} - \varrho\right)\, m }\right)\right]+\operatorname {Var} \left(\mathbb{E} \left[Q_m(z) \, \bigg| \,  B_{\left(\frac{\tau}{\alpha} + \varrho\right)\, m, \,  \left(\frac{\nu}{\alpha} - \varrho\right)\, m }\right]\right)   \\
 & = \left\lfloor mz \right\rfloor \mathbb{E}\left[ B_{\left(\frac{\tau}{\alpha} + \varrho\right)\, m, \,  \left(\frac{\nu}{\alpha} - \varrho\right)\, m } -  B^2_{\left(\frac{\tau}{\alpha} + \varrho\right)\, m, \,  \left(\frac{\nu}{\alpha} - \varrho\right)\, m } \right] + \left\lfloor mz \right\rfloor \operatorname{Var}\left( B_{\left(\frac{\tau}{\alpha} + \varrho\right)\, m, \,  \left(\frac{\nu}{\alpha} - \varrho\right)\, m }\right)\\
 & = m z \,\frac{\tau + \varrho \alpha}{\tau +\nu}   \left[  1 - \frac{\tau + \varrho \alpha}{\tau + \nu} + \alpha z\, \frac{ \nu - \varrho \alpha}{\left(\tau + \nu\right)^2}\right] + O(1)
\end{align*}
where the $O(1)$ accounts for the fact that we are discarding the floor function and that we are substituting the exact expression for the variance of $B_{\left(\frac{\tau}{\alpha} + \varrho\right)\, m, \,  \left(\frac{\nu}{\alpha} - \varrho\right)\, m }$  with its asymptotic principal part:
\begin{align*}
    m\, \operatorname{Var}\left(B_{\left(\frac{\tau}{\alpha} + \varrho\right)\, m, \,  \left(\frac{\nu}{\alpha} - \varrho\right)\, m }\right)  & = \frac{\alpha \, (\tau + \varrho \alpha)(\nu - \varrho \alpha)}{ (\tau + \nu)^2 (\tau + \nu + \alpha/m) } \\
    & = \frac{\alpha \, (\tau + \varrho \alpha)(\nu - \varrho \alpha)}{ (\tau + \nu)^3 \left[1 + \alpha/(\tau m + \nu m) \right] } \\
    & =  \frac{\alpha \, (\tau + \varrho \alpha)(\nu - \varrho \alpha)}{ (\tau + \nu)^3  } \, \left[1  + O\left(\frac{1}{m}\right)\right]
\end{align*}   
\end{proof}

\begin{proof}[\underline{Proof of \eqref{eq:be_Qm}}] The outline of the proof is as follows: fix $\delta \in (0, 1/4)$ and a constant $\mathcal{C}$ and start with the well-known inequality \citep[Chapter V, Theorem 2]{Pet(75)}
\begin{displaymath}
    \left\|F_{V_m(z)} - \Phi \right\|_\infty \le \int_{| \xi| \le \mathcal{C}\,\sigma(z) \, m^\delta} \left|\frac{\varphi_{V_m(z)} (\xi) - e^{- \frac{\xi^2}{2}}}{\xi} \right| \, \mathrm{d} \xi + \tilde{\mathcal{C}}{m^{-\delta}} 
    \end{displaymath}
    where $\varphi_{V_m(z)}$ denotes the characteristic function of $V_m(z)$ and $\tilde{\mathcal{C}} =\max_{z \in [\zeta_0, \zeta_1]} \sigma(z)\,  \mathcal{C}$. For notational convenience, let $B_m = B_{\left(\frac{\tau}{\alpha} + \varrho\right)\, m, \,  \left(\frac{\nu}{\alpha} - \varrho\right)\, m }$ and define, for $z \in [\zeta_0, \zeta_1]$,
 \begin{align*}
G_m(z) &= \sqrt{m} \left[\mu(z)  - z B_m \right] \\
S_m (z)&= \frac{z}{\sigma^2(z)} \left[B_m - B_m^2 \right] 
\end{align*}
and 
\begin{displaymath}
S(z) = \frac{z}{\sigma^2(z)} \cdot \frac{(\tau + \varrho \alpha)(\nu - \varrho \alpha)}{(\tau + \nu)^2}.
\end{displaymath}
Further, let $G(z)$ denote a Gaussian random variable with mean $0$ and variance 
$$s^2(z) = z^2 \cdot \frac{\alpha (\tau + \varrho \alpha)(\nu - \varrho \alpha)}{(\tau + \nu)^3}, $$ 
independent of $B_m$. In steps 1--3 we rewrite the right-end side of the inequality as 
\begin{align*}
   & \left\|F_{V_m(z)} - \Phi \right\|_\infty \\
   &  \quad \le \int_{| \xi| \le \mathcal{C}\,\sigma(z) \, m^\delta} \left|\frac{\mathbb{E}\left[ e^{ - i  \frac{\xi } {\sigma(z)} G_m(z)- \frac{\xi^2}{2} S_m(z)} \right] - \mathbb{E}\left[ e^{ - i  \frac{\xi } {\sigma(z)} G(z)- \frac{\xi^2}{2} S(z)} \right] }{\xi} \right| \, \mathrm{d} \xi \\
   & \quad \quad +  \tilde{C_2}{m^{2\delta - \frac{1}{2}}} +
 \tilde{\mathcal{C}}{m^{-\delta}} 
    \end{align*}
 Then, making use of the triangular inequality, we  further split the problem in two parts:
 \begin{align*}
   & \left\|F_{V_m(z)} - \Phi \right\|_\infty \\
   &  \quad \le \int_{| \xi| \le \mathcal{C}\,\sigma(z) \, m^\delta} \left|\frac{\mathbb{E}\left[ e^{ - i  \frac{\xi } {\sigma(z)} G_m(z)- \frac{\xi^2}{2} S_m(z)} \right] - \mathbb{E}\left[ e^{ - i  \frac{\xi } {\sigma(z)} G_m(z)- \frac{\xi^2}{2} S(z)} \right] }{\xi} \right| \, \mathrm{d} \xi \\
   & \quad 	\quad + \int_{| \xi| \le \mathcal{C}\,\sigma(z) \, m^\delta} \left|\frac{\mathbb{E}\left[ e^{ - i  \frac{\xi } {\sigma(z)} G_m(z)- \frac{\xi^2}{2} S(z)} \right] - \mathbb{E}\left[ e^{ - i  \frac{\xi } {\sigma(z)} G(z)- \frac{\xi^2}{2} S(z)} \right] }{\xi} \right| \, \mathrm{d} \xi\\
   & \quad \quad +  \tilde{C_2}{m^{2\delta - \frac{1}{2}}} +
 \tilde{\mathcal{C}}{m^{-\delta}} \\
 & \quad = \mathcal{I}_m^{(1)} (z) + \mathcal{I}_m^{(2)}(z) +  \tilde{C_2}{m^{2\delta - \frac{1}{2}}} +
 \tilde{\mathcal{C}}{m^{-\delta}} 
    \end{align*}
In steps 4 and 5 we bound $\mathcal{I}_m^{(1)}(z) $ and $\mathcal{I}_m^{(2)} (z)$ for every $z \in [\zeta_0, \zeta_1]$ respectively by
\begin{displaymath}
\mathcal{I}_m^{(1)}(z) \le c_1 \, m^{2\delta - \frac{1}{2}} + c m^{-3/2}
\end{displaymath}
for some suitable constants $c_1, c >0$ and 
\begin{displaymath}
\mathcal{I}_m^{(2)}(z) \le c_2 \, m^{-\gamma}
\end{displaymath}
for any $\gamma \in \left(0, \frac{1}{2}\right)$ and some constant $c_2>0$ depending only on $\gamma$. Thus,  
\begin{displaymath}
 \left\|F_{V_m(z)} - \Phi \right\|_\infty \le c_1 \, m^{2\delta - \frac{1}{2}} + c m^{-3/2}
 + c_2 \, m^{-\gamma}+ \tilde{C}_2{m^{2\delta - \frac{1}{2}}} +
 \tilde{\mathcal{C}}{m^{-\delta}}.
 \end{displaymath}
To conclude, it is easy to check that for every $\delta \in \left(0, \frac{1}{4}\right)$ and every $\gamma \in \left(\frac{1}{6}, \frac{1}{2}\right)$, 
\begin{displaymath}
\min\left(\frac{3}{2}, \delta,   -2\delta +\frac{1}{2} , \gamma \right) \ge \frac{1}{6}, 
\end{displaymath}
 whence for every $z \in [\zeta_0, \zeta_1]$ it holds 
\begin{displaymath}
 \left\|F_{V_m(z)} - \Phi \right\|_\infty \le  \bar{C} \, m^{-\frac{1}{6}}
\end{displaymath}
for some constant $\bar{C}>0$. This concludes the proof of \eqref{eq:be_Qm}. 

\noindent \underline{Step 1.} Let $f_{B_m}$ denote the density of $B_m$ and write
\begin{align*}
\varphi_{V_m(z)} (\xi) & = e^{- i \xi \sqrt{m} \frac{\mu(z)}{\sigma(z)}} \cdot \varphi_{Q_m(z)}\left(  \frac{ \xi }{\sqrt{m} \sigma(z)}\right) \\
& = e^{- i \xi \sqrt{m} \frac{\mu(z)}{\sigma(z)}} \cdot \mathbb{E} \left[\varphi_{Q\left(\lfloor mz \rfloor, B_m\right)}\left(  \frac{ \xi}{\sqrt{m} \sigma(z)}\right)\right]\\
& = \int_{0}^1 \exp \left\{ - i \xi \sqrt{m} \frac{\mu(z)}{\sigma(z)} +  \lfloor{mz}\rfloor  \log \left[ 1 + p \left(e^{ i \xi  \frac{1}{\sqrt{m} \sigma(z)}} -1 \right)\right]\right\} \, f_{B_m}(p) \, \mathrm{d}p
\end {align*}
If $\xi$ satisfies 
\begin{equation}
\label{eq: BE_xi_bound}
| \xi| \le \mathcal{C}\,\sigma(z) \, m^\delta, 
\end{equation}
then \citep[Chapter IV, Lemma 5]{Pet(75)} guarantees that, for every $p \in [0, 1]$, 
\begin{displaymath}
   \left|   p  \left(e^\frac{i \, \xi }{\sqrt{m} \sigma(z)}-1\right)\right| \le p \, \left| \frac{\xi }{\sqrt{m} \sigma(z)}\right| \le C \, m^{\delta - \frac{1}{2}}.
\end{displaymath} 
Then, we can apply Taylor's formula to $\log \left[ 1 + p \left(e^{  \frac{i \xi }{\sqrt{m}\sigma(z)}} -1 \right)\right]$ and then to $\left(e^\frac{i \, \xi }{\sqrt{m} \sigma(z)} - 1\right)$ to obtain
\begin{align*}
\varphi_{V_m(z)} (\xi)  &=  \int_0^1 \exp \left\{ - i  \frac{\xi } {\sigma(z)} \sqrt{m} \left[\mu(z)  - z p \right] - \frac{\xi^2}{2} \frac{z}{\sigma^2(z)} \left[p - p^2 \right]\right\}  \, \mathfrak{R}_m(p, z, \xi) \, f_{B_m}(p) \, \mathrm{d}p\\
& =  \mathbb{E} \left[ e^{ - i  \frac{\xi } {\sigma(z)} G_m(z)- \frac{\xi^2}{2} S_m(z)}  \cdot \mathfrak{R}_m\left( B_m, z, \xi\right) \right]
%& =  \mathbb{E} \left[ \exp \left\{ - i  \frac{\xi } {\sigma(z)} \sqrt{m} \left[\mu(z)  - z B_m \right] - \frac{\xi^2}{2} \frac{z}{\sigma(z)} \left[B_m - B_m^2 \right]\right\}  \cdot \mathfrak{R}_m\left( B_m, \xi\right) \right]
\end{align*}
where
\begin{align*}
\mathfrak{R}_m(p, z, \xi) &= \exp \left\{(mz - \lfloor mz \rfloor ) \, \log \left[ 1 + p \left(e^{ i \xi  \frac{1}{\sqrt{m} \sigma(z)}} -1 \right) \right]  \right.\\
& \quad\quad\quad  +mz p \left[\left(e^\frac{i \, \xi }{\sqrt{m} \sigma(z)} - 1\right) -\left(\frac{i \, \xi }{\sqrt{m} \sigma(z)} - \frac{\xi^2 }{2 m \sigma^2(z)}\right) \right]\\
& \quad\quad\quad + \frac{1}{2}\, mz  p^2 \left[ \left(e^\frac{i \, \xi }{\sqrt{m} \sigma(z)} - 1\right)^2 + \frac{\xi^2}{m \sigma^2(z)}\right]\\
   &\quad\quad\quad \left. + m z \, p^3  \left(e^\frac{i \, \xi }{\sqrt{m} \sigma(z)} - 1\right)^3 \int_0^1 \left(2 + tp \left(e^\frac{i \, \xi }{\sqrt{m} \sigma(z)} - 1\right)\right)^{-2} \, (1-t)^2 \, \mathrm{d} t\right\}.
\end{align*}
Making use of elementary properties of the exponential together with \citep[Chapter IV, Lemma 5]{Pet(75)}, we can prove that there exists a constant $\tilde{C}_1$ such that for every $z \in [\zeta_0, \zeta_1]$,  every $p \in [0, 1]$ and every $\xi$ satisfying \eqref{eq: BE_xi_bound}%\textcolor{red}{\eqref{eq: BE_xi_bound} - controllare che $\xi$ si possa tirare fuori a prezzo di un $\delta$ per davvero}, 
%\begin{displaymath}
%\left| \mathfrak{R}_m(p, z, \xi) \right|   \le \exp\left\{G(z)\,  p^3 \, \frac{ \xi^3 }{m^\frac{1}{2} \sigma(z)^3} \right\}
%\end{displaymath}
%for some continuous function $G:[\zeta_0, \zeta_1] \to \mathbb{C}$ not depending on $\xi$, $p$ and $m$.  To conclude, apply again \citet[Chapter IV, Lemma 5]{Pet(75)}   to obtain
$$
\left|  \mathfrak{R}_m(p, z, \xi) -1 \right|   \le \tilde{C}_1 \, %p^3 \, 
| \xi | \, m^{2\delta - \frac{1}{2}}.
$$
It follows that 
\begin{equation}
\label{char_Vm}
\varphi_{V_m(z)} (\xi)  =  \mathbb{E}\left[ e^{ - i  \frac{\xi } {\sigma(z)} G_m(z)- \frac{\xi^2}{2} S_m(z)} \right] + \mathcal{R}_1(m)
\end{equation}
 with 
\begin{align*}
\left|\mathcal{R}_1(m)\right| &= \left| \varphi_{V_m(z)} (\xi)  -  \mathbb{E}\left[ e^{ - i  \frac{\xi } {\sigma(z)} G_m(z)- \frac{\xi^2}{2} S_m(z)} \right] \right|  \\
&= \left|  \mathbb{E} \left[ e^{ - i  \frac{\xi } {\sigma(z)} G_m(z)- \frac{\xi^2}{2} S_m(z)}  \cdot \left[\mathfrak{R}_m\left( B_m, z, \xi\right) -1 \right]\right] \right| \\
& \le \int_0^1  \left| \exp \left\{ - i  \frac{\xi } {\sigma(z)} \sqrt{m} \left[\mu(z)  - z p \right] - \frac{\xi^2}{2} \frac{z}{\sigma^2(z)} \left[p - p^2 \right]\right\}  \right| \cdot \left|\mathfrak{R}_m\left( p, z, \xi\right) -1 \right|  \, f_{B_m}(p) \mathrm{d}p \\
& \le \int_0^1 \tilde{C}_1 \, |\xi| \, m^{2\delta - \frac{1}{2}} \, f_{B_m}(p) \mathrm{d}p  = \tilde{C}_1 \, |\xi| \, m^{2\delta - \frac{1}{2}} 
\end{align*}

\noindent \underline{Step 2.} Now note that
$$s^2(z) = \sigma^2(z) \cdot \frac{\alpha }{\alpha z + \tau + \nu } $$
and therefore
\begin{align}
\label{char_phi}
\nonumber\mathbb{E}\left[ e^{ - i  \frac{\xi } {\sigma(z)} G(z)- \frac{\xi^2}{2} S(z)} \right]& = \varphi_{G(z)} \left(\frac{\xi}{\sigma(z)}\right)  \cdot e^{\frac{\xi^2}{2} S(z)}\\
&= \nonumber  \exp\left\{-\frac{\xi^2}{2} \cdot \left[ \frac{\alpha z}{\alpha z + \tau + \nu} +\frac{\tau + \nu}{\alpha z + \tau + \nu }  \right]\right\}\\
&= e^{-\frac{\xi^2}{2}}
\end{align}

\noindent \underline{Step 3.} Using \eqref{char_Vm} and \eqref{char_phi}, write
\begin{align*}
     &\int_{| \xi| \le \mathcal{C}\,\sigma(z) \, m^\delta} \left|\frac{\varphi_{V_m(z)} (\xi) - e^{- \frac{\xi^2}{2}}}{\xi} \right| \, \mathrm{d} \xi   \\
    & \quad \quad = \int_{| \xi| \le \mathcal{C}\,\sigma(z) \, m^\delta} \left|\frac{\mathbb{E}\left[ e^{ - i  \frac{\xi } {\sigma(z)} G_m(z)- \frac{\xi^2}{2} S_m(z)} \right] + \mathcal{R}_1(m) - \mathbb{E}\left[ e^{ - i  \frac{\xi } {\sigma(z)} G(z)- \frac{\xi^2}{2} S(z)} \right] }{\xi} \right| \, \mathrm{d} \xi \\
    & \quad \quad \le \int_{| \xi| \le \mathcal{C}\,\sigma(z) \, m^\delta} \left|\frac{\mathbb{E}\left[ e^{ - i  \frac{\xi } {\sigma(z)} G_m(z)- \frac{\xi^2}{2} S_m(z)} \right] - \mathbb{E}\left[ e^{ - i  \frac{\xi } {\sigma(z)} G(z)- \frac{\xi^2}{2} S(z)} \right] }{\xi} \right| \, \mathrm{d} \xi %\\
    %& \quad \quad \quad 
    + \tilde{C}_2 \, m^{2\delta - \frac{1}{2}}
        \end{align*}
where $\tilde{C}_2 =2 \, \mathcal{C}\,  \tilde{C}_1\,  \max_{z \in [\zeta_0, \zeta_1]}  \sigma(z)$.

\noindent \underline{Step 4.} 
By definition of $\mathcal{I}_m^{(1)} (z)$,  Jensen's inequality and the triangular inequality,  
 \begin{align*}
 \label{Im1}  \mathcal{I}_m^{(1)} (z) &= \int_{- \mathcal{C}\sigma(z) m^\delta}^{\mathcal{C}\sigma(z)  m^\delta} \left|\frac{\mathbb{E}\left[ e^{ - i  \frac{\xi } {\sigma(z)} G_m(z)} \left(e^{- \frac{\xi^2}{2} S_m(z)}  - e^{- \frac{\xi^2}{2} S(z)}\right)  \right] }{\xi} \right| \, \mathrm{d} \xi \\
 &\le  \int_{- \mathcal{C}\sigma(z) m^\delta}^{\mathcal{C}\sigma(z)  m^\delta}  \frac{\mathbb{E}\left[  \left|e^{- \frac{\xi^2}{2} S_m(z)}  - e^{- \frac{\xi^2}{2} S(z)}\right|  \right] }{|\xi|}  \, \mathrm{d} \xi
 \end{align*}
Now note that, for every $z \in [\zeta_0, \zeta_1]$, $S_m(z) \ge 0 $ a.s., and $S(z) \ge 0$. Since the function $[0, +\infty) \to (0, 1]; \, x \mapsto e^{-x}$ is 1-Lipschitz, the last term of the above inequality can be bounded by
\begin{displaymath}
\int_{- \mathcal{C}\sigma(z) m^\delta}^{\mathcal{C}\sigma(z)  m^\delta}  \frac{\mathbb{E}\left[  \left|e^{- \frac{\xi^2}{2} S_m(z)}  - e^{- \frac{\xi^2}{2} S(z)}\right|  \right] }{|\xi|}  \, \mathrm{d} \xi\le   \int_{- \mathcal{C}\sigma(z) m^\delta}^{\mathcal{C}\sigma(z)  m^\delta} \frac{|\xi|}{2} \, \mathbb{E}\left[ \left|S_m(z) - S(z)\right|\right]  \, \mathrm{d} \xi,
\end{displaymath}
such that
\begin{equation}\label{number}
 \mathcal{I}_m^{(1)} (z)\le \sqrt{\mathbb{E}\left[ \left(S_m(z) - S(z)\right)^2\right]}  \cdot \mathcal{C}^2 \sigma^2(z) \, m^{2\delta}.
\end{equation}
A simple computation shows
\begin{displaymath}
%\mathbb{E}[S_m(z)] = S(z) \left[ 1 + r^{(1)}_m(z)\right]
\mathbb{E}[S_m(z)] = S(z) \left[ 1 + O \left(m^{-1}\right)\right], 
\end{displaymath}
%with $|r^{(1)}_m| \le c_1 \, m^{-1}$ for every $z \in [\zeta_0, \zeta1]$, for some suitable constant $c_1$. 
which in turn entails
\begin{displaymath}
%\mathbb{E}\left[ \left(S_m(z) - S(z)\right)^2\right] = \left[ \mathbb{E}\left[S_m^2(z)\right]- S^2(z)\right] \cdot \left[1 + r^{(2)}_m(z) \right]
\mathbb{E}\left[ \left(S_m(z) - S(z)\right)^2\right] = \left[ \mathbb{E}\left[S_m^2(z)\right]- S^2(z)\right] \cdot \left[1 + O \left(m^{-2}\right) \right].
\end{displaymath}
The second moment of $S_m(z)$ can be written as follows
\begin{displaymath}
 \mathbb{E}\left[S_m^2(z)\right] = \frac{z^2}{\sigma^4(z)} \cdot \left\{\mathbb{E}\left[B_m^2\right] -2 \mathbb{E}\left[B_m^3\right] + \mathbb{E}\left[B_m^4\right] \right\},
\end{displaymath}
reducing the problem to the study of the moments of $B_m$. By standard results regarding the beta distribution it is known that, for $k \in \mathbb{N}$, 
\begin{displaymath}
\mathbb{E} \left[B_m^k \right] = \frac{\Gamma \left(\frac{\tau + \varrho \alpha}{\alpha}\,  m  + k\right)\, \Gamma \left(\frac{\tau + \nu}{\alpha}\,  m \right)}{\Gamma \left(\frac{\tau + \varrho \alpha}{\alpha}\,  m  \right) \, \Gamma \left(\frac{\tau + \nu }{\alpha}\,  m  + k\right)},
\end{displaymath}
so that, for $m \to +\infty$, a straightforward application of \citep[formula (1)]{TE(51)} yields
\begin{align*}
\mathbb{E} \left[B_m^k \right] &  = \left(\frac{\tau + \varrho \alpha}{\alpha} \, m\right)^k \left[1+ \frac{k(k-1) \alpha}{2 (\tau + \varrho \alpha) \, m } + O \left(m^{-2}\right) \right]\\
& \quad + \left(\frac{\tau + \varrho \alpha}{\alpha} \, m\right)^k \left[1- \frac{k(k-1) \alpha}{2 (\tau + \nu) \, m } + O \left(m^{-2}\right) \right]\\
&= \left( \frac{\tau+ \varrho \alpha}{\tau + \nu} \right)^k \, \left[ 1 + \frac{k(k-1)}{m}  \, \eta%_{\tau, \nu, \varrho, \alpha} 
+ O \left(m^{-2}\right) \right]
\end{align*}
where $\eta = \eta (\tau, \nu, \varrho, \alpha) := \frac{ \alpha (\nu - \varrho \alpha) }{2 (\tau +\varrho \alpha) (\tau+\nu)}$ is a constant not depending on $k$ or $m$.
%with  $|r^{(2)}_m| \le c_2 \, m^{-2}$ for every $z \in [\zeta_0, \zeta1]$, for some suitable constant $c_2$. 
Then, 
\begin{align*}
 \mathbb{E}\left[S_m^2(z)\right] &= \frac{z^2}{\sigma^4(z)} \cdot  \left( \frac{\tau+ \varrho \alpha}{\tau + \nu} \right)^2 \cdot \left\{  \left[ 1 + \frac{2	\eta}{m} \right]  -2 \frac{\tau+ \varrho \alpha}{\tau + \nu} \left[ 1 + \frac{6\eta}{m}\right] \right.  \\
 & \quad \quad \quad \quad \quad \quad \quad \quad  \quad \quad \quad \left. +  \left( \frac{\tau+ \varrho \alpha}{\tau + \nu} \right)^2 \left[ 1 + \frac{12 \eta}{m}\right]+ O \left(m^{-2}\right)  \right\}\\
 & =  \frac{z^2}{\sigma^4(z)} \cdot  \left( \frac{\tau+ \varrho \alpha}{\tau + \nu} \right)^2 \cdot \left\{ \left(\frac{\nu - \varrho \alpha}{\tau + \nu}\right)^2 + \frac{1}{m} \cdot \left[ 2 \eta - 12 \eta \frac{\tau+\varrho \alpha}{\tau + \nu} + 12 \eta \left(\frac{\tau+\varrho \alpha}{\tau + \nu} \right)^2\right] \right.
 \\
 &\quad \quad \quad \quad \quad \quad \quad \quad  \quad \quad \quad  \left.+ O\left(m^{-2}\right)\right\}\\
 & = S^2(z) + \frac{1}{m} \, g(z, \tau, \nu, \varrho, \alpha) + O\left(m^{-2}\right), 
\end{align*}
with $g(z, \tau, \nu, \varrho, \alpha): =   \frac{z^2}{\sigma^4(z)} \cdot  \left( \frac{\tau+ \varrho \alpha}{\tau + \nu} \right)^2 \cdot \left[ 2 \eta - 12 \eta \frac{\tau+\varrho \alpha}{\tau + \nu} + 12 \eta \left(\frac{\tau+\varrho \alpha}{\tau + \nu} \right)^2\right]$. We can conclude that
\begin{displaymath}
\sqrt{\mathbb{E}\left[ \left(S_m(z) - S(z)\right)^2\right]}  = \frac{1}{\sqrt{m}} \, g(z, \tau, \nu, \varrho, \alpha) \left[1 +r_m\right]%  O\left(m^{-1}\right)\right].
\end{displaymath} 
with $r_m = O\left(m^{-1}\right)$. Since all the asymptotic expansions above hold uniformly on compact sets, in the sense of \citep[Definition A.9]{Con(24)}, and the function $z \to g(z, \tau, \nu, \varrho, \alpha)$ is continuous, one can resort to \citep[Lemma A.11]{Con(24)} to obtain
\begin{displaymath}
|R_m| : = \left| \sqrt{\mathbb{E}\left[ \left(S_m(z) - S(z)\right)^2\right]}  - \frac{1}{\sqrt{m}} \, g(z, \tau, \nu, \varrho, \alpha)\right| \le \frac{c}{m^{3/2}}
\end{displaymath}
fro some suitable positive constant $c$. To conclude, plug the above result in  \eqref{number} to obtain that for all $z \in [\zeta_0, \zeta_1]$, 
\begin{displaymath}
\mathcal{I}_m^{(1)}(z) \le c_1 \,  m^{2\delta - \frac{1}{2}} + \frac{c}{m^{3/2}}
\end{displaymath}
 for some suitable constant $c_1>0$. 

\noindent \underline{Step 5.} By definition, 
\begin{align*}
\mathcal{I}_m^{(2)}(z) &= \int_{-\mathcal{C} \sigma(z) m^\delta}^{\mathcal{C} \sigma(z) m^\delta} e^{-\frac{\xi^2 S(z)}{2}} \, \left| \int_{\R}   \frac{e^{i \xi x }-1}{\xi} \, \left[f_{G_m(z)}(x) - f_{G(z)}(x) \right] \, \mathrm{d} x\, \right| \, \mathrm{d} \xi \\
&\le  \int_{-\mathcal{C} \sigma(z) m^\delta}^{\mathcal{C} \sigma(z) m^\delta} e^{-\frac{\xi^2 S(z)}{2}} \, \int_{\R}  \left|  \frac{e^{i \xi x }-1}{\xi} \right|\, \left|f_{G_m(z)}(x) - f_{G(z)}(x) \right| \, \mathrm{d} x \, \mathrm{d} \xi \\
&=   \int_{\R} \left[ \int_{-\mathcal{C} \sigma(z) m^\delta}^{\mathcal{C} \sigma(z) m^\delta} e^{-\frac{\xi^2 S(z)}{2}} \,  \left|  \frac{e^{i \xi x }-1}{\xi} \right| \, \mathrm{d} \xi \right] \, \left|f_{G_m(z)}(x) - f_{G(z)}(x) \right| \, \mathrm{d} x 
\end{align*}
Making use of \citep[Chapter IV, Lemma 5]{Pet(75)} and of the elementary properties of the Gaussian density write the bound
\begin{align*}
 \int_{-\mathcal{C} \sigma(z) m^\delta}^{\mathcal{C} \sigma(z) m^\delta} e^{-\frac{\xi^2 S(z)}{2}} \,  \left|  \frac{e^{i \xi x }-1}{\xi} \right| \, \mathrm{d} \xi  & \le  \int_{-\mathcal{C} \sigma(z) m^\delta}^{\mathcal{C} \sigma(z) m^\delta} e^{-\frac{\xi^2 S(z)}{2}} \,  \left|  x \right| \, \mathrm{d} \xi\\
 & \le  |x| \,  \int_{\R} e^{-\frac{\xi^2 S(z)}{2}}  \, \mathrm{d} \xi \\
 & =  |x| \cdot \sqrt{\frac{2 \pi}{S(z)}}
\end{align*}
Hence, letting $c(z) =  \sqrt{\frac{2 \pi}{S(z)}}$, 
\begin{equation}
\label{bound_dens}
\mathcal{I}_m^{(2)} \le   c(z) \cdot  \int_{\R} |x| \cdot  \left|f_{G_m(z)}(x) - f_{G(z)}(x) \right| \, \mathrm{d} x 
\end{equation}
For $x \in \mathbb{R}$, 
\begin{displaymath}
f_{G_m(z)}(x) = \begin{cases} 0 \, \,  \quad  \quad \quad \quad \quad  \quad \quad \text{if } x \notin \left[- \sqrt{m} \mu(z) , \, \sqrt{m} (z- \mu(z) ) \right]& \\
\frac{1}{\sqrt{m} z} \, \frac{\Gamma \left( \frac{\tau + \nu}{\alpha} \, m\right)}{\Gamma \left( \frac{\tau + \varrho \alpha }{\alpha} \, m\right)\, \Gamma \left( \frac{\nu - \varrho \alpha }{\alpha} \, m\right)}\cdot  \left(\frac{\tau + \varrho \alpha}{\tau + \nu} - \frac{x}{\sqrt{m} z}\right)^{ \frac{\tau + \varrho \alpha }{\alpha} \, m -1} \cdot  \left(\frac{\nu - \varrho \alpha}{\tau + \nu} + \frac{x}{\sqrt{m} z}\right)^{ \frac{\nu - \varrho \alpha }{\alpha} \, m -1}  & \\
 \quad =: \psi_m(x)   \quad  \quad \quad \text{if } x \notin \left[- \sqrt{m} \mu(z) , \, \sqrt{m} (z- \mu(z) ) \right]& 
\end{cases}
\end{displaymath}
and 
\begin{displaymath}
f_{G(z)}(x) = \frac{1}{\sqrt{2 \pi s^2(z)}} \exp\left\{- \frac{x^2}{2 s^2(z)} \right\}.
\end{displaymath}
Introduce $\gamma \in (0, 1/2)$ and let $A_m = c \,  m^\gamma$, with $c$ a positive constant such that $-\mu(z) \sqrt{m}< -A_m < 0< A_m < (z- \mu(z)) \sqrt{m}$ for all $z \in [\zeta_0, \zeta_1]$, and write the integral in the RHS of \eqref{bound_dens} as
\begin{align*}
&  \int_{\R} |x| \cdot  \left|f_{G_m(z)}(x) - f_{G(z)}(x) \right| \, \mathrm{d} x   \\
  & \quad \quad =   \int_{-\infty}^{- \sqrt{m} \, \mu(z)}-x \, f_{G(z)}(x) \, \mathrm{d} x   +  \int^{-A_m}_{- \sqrt{m} \mu(z)} |x|  \cdot \left| \psi_m(x) -  f_{G(z)}(x)\right| \, \mathrm{d} x \\
&\quad \quad  \quad +  \int^{ -A_m}_{A_m} |x|  \cdot \left| \psi_m(x) -  f_{G(z)}(x)\right|  \, \mathrm{d} x \\
&\quad  \quad \quad+  \int^{ \sqrt{m}\, ( z-  \mu(z))}_{A_m}|x|  \cdot \left| \psi_m(x) -  f_{G(z)}(x)\right| \, \mathrm{d} x  +  \int_{ \sqrt{m}\, ( z-  \mu(z))}^{+\infty}x   \, f_{G(z)}(x) \, \mathrm{d} x \\
%
&\quad  \quad \le 		 \int_{-\infty}^{- A_m}-x \, f_{G(z)}(x) \, \mathrm{d} x   +  \int^{-A_m}_{- \sqrt{m} \, \mu(z)}|x| \, \psi_m(x) \, \mathrm{d} x \\
&\quad \quad \quad+  \int^{ -A_m}_{A_m} |x|  \cdot \left| \psi_m(x) -  f_{G(z)}(x)\right|  \, \mathrm{d} x \\
& \quad \quad \quad +  \int^{ \sqrt{m}\, ( z-  \mu(z))}_{A_m}|x |  \, \psi_m(x) \, \mathrm{d} x  +  \int_{ \sqrt{m}\, ( z-  \mu(z))}^{+\infty}x   \, f_{G(z)}(x) \, \mathrm{d} x \\
& \quad \quad = \mathrm{(I)} +\mathrm{(II)} +\mathrm{(III)} + \mathrm{(IV)} + \mathrm{(V)}
\end{align*}
The terms (I) and (V) vanish exponentially fast as $m \to +\infty$, in fact for any $\zeta>0$
\begin{displaymath}
 \int_{\zeta}^{+\infty}x   \, f_{G(z)}(x) \, \mathrm{d} x = \frac{s(z)}{\sqrt{2\pi}} \, e^{ -\frac{\zeta^2}{s^2(z) }}, 
\end{displaymath}
whence
\begin{displaymath}
 \mathrm{(I)} =  \frac{s(z)}{\sqrt{2\pi}} \, e^{ -\frac{c^2 \, m^{2\gamma}}{s^2(z) }}
\end{displaymath}
and 
\begin{displaymath}
 \mathrm{(V)} =  \frac{s(z)}{\sqrt{2\pi}} \, e^{ -\frac{c^2 \, m^{2\gamma}}{s^2(z) }}.
\end{displaymath}
We now study (II) and (IV). By a straightforward application of Cauchy-Schwartz inequality, 
\begin{align*}
\mathrm{(II)} &= \mathbb{E} \left[|G_m(z)| \cdot \mathds{1}_{\left\{G_m(z) \in [-\sqrt{m} \, \mu(z), -A_m ]\right\}}\right] \\
& \le \sqrt{\operatorname{Var}\left(G_m(z)\right)} \cdot \sqrt{P\left[G_m(z) \in [-\sqrt{m} \, \mu(z), -A_m ] \right]}.
\end{align*}
Now, 
\begin{displaymath}
\operatorname{Var}\left(G_m(z)\right) = mz^2 \operatorname{Var}\left(B_m\right) =  z^2\, \frac{ \alpha \, (\tau + \varrho \alpha)(\nu - \varrho \alpha)}{ (\tau + \nu)^3  } \, \left[1  + O\left(\frac{1}{m}\right)\right] \le  z^2 \, \tilde{c}_1 
\end{displaymath}
for some suitable constant $\tilde{c}_1$. By Chebichev's inequality
\begin{align*}
P\left(G_m(z) \in [-\sqrt{m} \, \mu(z), -A_m ] \right) & \le P\left(G_m(z) \le  -A_m  \right) + P\left(G_m(z)  \ge A_m  \right) \\
& \le \frac{\operatorname{Var}(G_m(z))}{A_m^2}\\
&  \le z^2 \, \tilde{c}_2 \, m^{-2\gamma}
 \end{align*}
for a suitable constant $\tilde{c}_2$. Combining these results we obtain
\begin{displaymath}
\mathrm{(II)} \le z^2 \, \tilde{c} \, m^{-\gamma}
\end{displaymath}
for $	\tilde{c} = \sqrt{\tilde{c}_1 \, \tilde{c}_2}$. The same argument allows to prove
\begin{displaymath}
\mathrm{(IV)} \le z^2 \, \tilde{c} \, m^{-\gamma}
\end{displaymath}
To assess the behavior of (III), use the well--known asymptotic expansion of the Gamma function for large argument \citep[Equation \href{https://dlmf.nist.gov/5.11.E10}{(5.11.3)}]{nist} and some simple algebraic rearrangements to write that, as $m \to +\infty$, 
\begin{align*}
& \psi_m(x)\\
%
& = \frac{1}{\sqrt{2\pi}} \, \sqrt{\frac{(\tau + \varrho \alpha)(\nu - \varrho \alpha)}{z^2 \alpha (\tau + \nu)}} \cdot \left(\frac{\tau+\varrho\alpha}{\tau + \nu} - \frac{x}{\sqrt{m} \, z}\right)^{-1} \cdot \left(\frac{\nu - \varrho\alpha}{\tau + \nu} + \frac{x}{\sqrt{m} \, z}\right)^{-1} \\
&\quad  \cdot \left\{\left(\frac{\tau + \nu}{\tau + \varrho \alpha}\right)^{\frac{\tau + \varrho \alpha}{\alpha}} \, \left(\frac{\tau + \nu}{\nu - \varrho \alpha}\right)^{\frac{\nu - \varrho \alpha}{\alpha}}  \cdot \left(\frac{\tau+\varrho\alpha}{\tau + \nu} - \frac{x}{\sqrt{m} \, z}\right)^{\frac{\tau + \varrho \alpha}{\alpha}} \cdot \left(\frac{\nu - \varrho\alpha}{\tau + \nu} + \frac{x}{\sqrt{m} \, z}\right)^{\frac{\nu -  \varrho \alpha}{\alpha}}\right\}^m \\
& \quad 	\cdot \mathfrak{R}_1^{(m)}\\
%
& =   \exp \left\{ m\cdot  \left[ \frac{\tau + \varrho \alpha}{\alpha} \log \left(1- \frac{x}{\sqrt{m}\, \mu(z)}\right)+ \frac{\nu - \varrho \alpha}{\alpha} \log \left(1+ \frac{x}{\sqrt{m}\, (z- \mu(z))}\right)\right] \right\} \\
& \quad \cdot \frac{1}{\sqrt{2\pi}} \, \Psi_m(z, x)\cdot \mathfrak{R}_1^{(m)} 
\end{align*}
where
\begin{displaymath}
\Psi_m(z, x) =\sqrt{\frac{(\tau + \varrho \alpha)(\nu - \varrho \alpha)}{ z^2 \, \alpha (\tau + \nu)}} \cdot \frac{1}{\left(\frac{\tau+\varrho\alpha}{\tau + \nu} - \frac{x}{\sqrt{m} \, z}\right) \cdot \left(\frac{\nu - \varrho\alpha}{\tau + \nu} + \frac{x}{\sqrt{m} \, z}\right)}
\end{displaymath}
and
\begin{displaymath}
\mathfrak{R}_1^{(m)} = \frac{\Gamma^* \left( \frac{\tau + \nu}{\alpha} \, m\right)}{\Gamma^* \left( \frac{\tau + \varrho \alpha }{\alpha} \, m\right)\, \Gamma^* \left( \frac{\nu - \varrho \alpha }{\alpha} \, m\right)}.
\end{displaymath}
We focus first on the behavior of these last two terms as $m \to +\infty$; simple algebraic rearrangements allow to write
\begin{align*}
\Psi_m(z, x) &=\sqrt{\frac{ \alpha(\tau + \nu)^3}{z^2 (\tau+\varrho\alpha)(\nu - \varrho\alpha)}}\,  \cdot \frac{1}{1 + \frac{x (\tau+\nu)}{\sqrt{m} \, z} \, \left(\frac{1}{\nu -  \varrho \alpha} - \frac{1}{\tau + \varrho \alpha} \right)- \frac{x^2 (\tau + \nu)^2}{m z (\tau + \varrho \alpha)(\nu - \varrho \alpha)} }\\
 %&=\sqrt{\frac{ \alpha(\tau + \nu)^3}{z^2 (\tau+\varrho\alpha)(\nu - \varrho\alpha)}}\,  \left[ 1+ \frac{x (\tau+\nu)}{\sqrt{m} \, z} \, \left(\frac{1}{\tau +  \varrho \alpha} - \frac{1}{\nu - \varrho \alpha} \right)  + r_m(x, z) \right]\\
%& = \frac{1}{s(z)} \,  \left[ 1+\frac{c_3 \, x}{\sqrt{m}} +  r_m(x, z)\right].
&= \frac{1}{s(z)} \,  \left[ 1+O \left(\frac{x}{m^{1/2}}\right)\right].
\end{align*}
%If $\gamma \in \left(0, \frac{1}{4}\right)$, then $2\gamma -1<-\frac{1}{2}$ and  
%\begin{displaymath}
%r_m (x, z)= O \left(m^{-2 \gamma+1}\right)
%\end{displaymath}
%uniformly for $x \in [-A_m, A_m]$ and 
uniformly for $z \in [\zeta_0, \zeta_1]$. Resorting again to \citep[Equations \href{https://dlmf.nist.gov/5.11.E10}{(5.11.3)} and \href{https://dlmf.nist.gov/5.11.E10}{(5.11.4)}]{nist}, we also obtain
\begin{displaymath}
\mathfrak{R}_1^{(m)}  = \frac{1+ \frac{\alpha}{12 \, (\tau+\nu) \, m } + O\left(m^{-2}\right)}{1+ \frac{\alpha \, (\tau+\nu)}{12 \, (\tau+\varrho \alpha)(\nu - \varrho \alpha) \, m } + O\left(m^{-2}\right)} = 1+  O\left(m^{-1}\right).
\end{displaymath}
%uniformly for $x \in [-A_m, A_m]$ and 
uniformly for $z \in [\zeta_0, \zeta_1]$. For the exponential term, %for $m$ large enough \textcolor{red}{scrivere meglio}, 
use Taylor's expansion of the logarithm around 1 to write
\begin{align*}
& \exp \left\{ m \cdot \left[\frac{\tau + \varrho \alpha}{\alpha} \log \left(1- \frac{x}{\sqrt{m}\, \mu(z)}\right)+ \frac{\nu - \varrho \alpha}{\alpha} \log \left(1+ \frac{x}{\sqrt{m}\, (z- \mu(z))}\right) \right]\right\} \\
& = \exp \left\{ m \cdot \left[ \frac{\tau + \varrho \alpha}{\alpha}  \left(- \frac{x}{\sqrt{m}\, \mu(z)} - \frac{x^2}{2m \, \mu^2(z)} \right)\right. \right.\\
& \left. \left.  \quad \quad \quad + \frac{\nu - \varrho \alpha}{\alpha}  \left( \frac{x}{\sqrt{m}\, (z- \mu(z))} - \frac{x^2}{2m\, (z- \mu(z))^2}\right)\right]\right\} \cdot \mathfrak{R}_2^{(m)}(x, z)\\
& = \exp \left\{ - \frac{x^2}{2} \cdot \frac{1}{s^2(z)}\right\} \cdot \mathfrak{R}_2^{(m)}(x, z)
\end{align*}
where
\begin{align*}
\mathfrak{R}_2^{(m)}(x, z)& = \exp \left\{ m \cdot \left[ \frac{\tau + \varrho \alpha}{\alpha}  \left(\log \left(1- \frac{x}{\sqrt{m}\, \mu(z)}\right) +\frac{x}{\sqrt{m}\, \mu(z)}  +\frac{x^2}{2m \, \mu^2(z)} \right)\right. \right.\\
& \left. \left.  \quad \quad \quad + \frac{\nu - \varrho \alpha}{\alpha}  \left( \log \left(1+ \frac{x}{\sqrt{m}\, (z- \mu(z))}\right)-\frac{x}{\sqrt{m}\, (z- \mu(z))} +\frac{x^2}{2m\, (z- \mu(z))^2}\right)\right]\right\} 
\end{align*}
As $m \to +\infty$,  %If $\gamma \in \left(0, \frac{3}{8}\right)$, then $4\gamma -2<-\frac{1}{2}$ and %Making use of \citet[Chapter IV, Lemma 5]{Pet(75)}, we can prove NO è per e^ix
\begin{displaymath}
%\textcolor{red}{
\mathfrak{R}_2^{(m)}(x, z) = 1+ O \left(\frac{x^3}{m^{1/2}}\right)%}%-  \frac{x^3}{3 \, m^{1/2} } \left(\frac{1}{\mu(z)^3} + \frac{1}{(z-\mu(z))^3}\right)+ O \left(m^{4\gamma-2}\right)}
\end{displaymath}
%uniformly for $x \in [-A_m, A_m]$ and 
uniformly for $z \in [\zeta_0, \zeta_1]$. Combining all the above results % and noting that for $\gamma \in \left(0, \frac{1}{4}\right)$ it holds $2 \gamma -1 > 4 \gamma -2$,  
we can write%Resorting to \citet[Lemma A.11]{Con(24)} we then obtain
\begin{displaymath}
\psi_m(x) = \frac{1}{\sqrt{2\pi}\, s(z)} \,\exp \left\{ - \frac{x^2}{2} \cdot \frac{1}{s^2(z)}\right\} \left[1 + \mathcal{R}_m(x, z)\right] = f_{G(z)}(x) \left[1 + \mathcal{R}_m(x, z)\right]
\end{displaymath}
with
\begin{displaymath}
\mathcal{R}_m(x, z) =  O \left(\frac{x^3}{m^{1/2}}\right)
 \end{displaymath}
uniformly for $z \in [\zeta_0, \zeta_1]$. Resorting again to \citep[Lemma A.11]{Con(24)}, this in turn implies
\begin{displaymath}
\left|\psi_m(x)- f_{G(z)}(x) \right| \le \frac{C\, x^3}{m^{1/2}}
\end{displaymath}
for every $x \in [-A_m, A_m]$ and $z \in [\zeta_0, \zeta_1]$, for some constant $C>0$, whence 
\begin{align*}
\mathrm{(III)} &=  \int^{ -A_m}_{A_m} |x|  \cdot \left| \psi_m(x) -  f_{G(z)}(x)\right|  \, \mathrm{d} x\\
& \le  \int^{ -A_m}_{A_m} |x|  \cdot\frac{C\, x^3}{m^{1/2}}  \, \mathrm{d} x \\
& \le   \frac{\mathcal{C} \, \mathbb{E} \left[ G(z)^4\right]}{m^{1/2}}\\
\end{align*}
In conclusion, 
\begin{align*}
\mathcal{I}_m^{(2)}(z) &\le \frac{s(z)}{\sqrt{2\pi}} \left[ e^{ -\frac{c^2 \, m^{2\gamma}}{s^2(z) }} + e^{ -\frac{c^2 \, m^{2\gamma}}{s^2(z) }} \right] + 2z^2 \, c \,  m^{- \gamma} +\mathcal{C} \, \mathbb{E} \left[ G(z)^4\right] \, m^{-1/2}
\end{align*}
Recalling that $\gamma \in \left(0, \frac{1}{2}\right)$, we conclude
\begin{align*}
\mathcal{I}_m^{(2)} (z)&\le C_2(z) \, m^{-\gamma} \le c_2 \, m^{-\gamma} 
\end{align*}
for some continuous function $C_2: [\zeta_0, \zeta_1] \to (0, +\infty)$ depending only on $\gamma$ and $c_2 = \max_{z \in [\zeta_0, \zeta_1]} C_2(z)$.
\end{proof}



