\section{ODE derivation for the expected number of malignant cells}
\label{section:MiDerivation}
Multiplying the Fokker-Plank equation in Equation~\eqref{eq:basicFokkerPlanck} and integrating over $m$ yields:
\begin{equation}
    \label{appeq:MEq1}
    \frac{\dd M_j}{\dd t} = \lambda_i M_i + \sum_{j=1}^n k_{ij}M_j + \int_0^1 m\frac{\partial}{\partial m} (b(m) p_i(m,t))+ m\frac{\partial}{\partial m}\left(\sigma(m)\frac{\partial p_i(m,t)}{\partial m}\right)\dd m.
\end{equation}
% \begin{equation}
%     \frac{\dd M_j}{\dd t} &= \int_0^1 m\frac{\partial p_i(m,t)}{\partial t}\dd m\\
%     &= \int_0^1 m \left(\lambda_i p_i(m,t)+ \frac{\partial}{\partial m}\left(\sigma(m)\frac{\partial p_i(m,t)}{\partial m}\right) + \sum_{j=1}^n k_{ij} \int_0^1 p_{j}(m,t) \zeta(m) \dd m \right),\\
%     &= \lambda_i M_i + \sum_{j=1}^n k_{ij}(T_j - M_j) + \int_0^1 m\frac{\partial}{\partial m}\left(\sigma(m)\frac{\partial p_i(m,t)}{\partial m}\right)\dd m.
% \end{equation}
Note that 
\begin{align*} 
    \int_0^1 m\frac{\partial}{\partial m} (b(m) p_i(m,t)) \dd m = mb(m)p_i(m,t)\vert_{m=0}^{m=1} -\int_0^1 b(m)p_i(m,t)\dd m.
\end{align*}
Given that we chose $b(m) = \gamma (1-m)$ with $\gamma > 0$, the integral becomes
\begin{equation}
    \label{appeq:IBP2}
    \int_0^1 b(m)p_i(m,t)\dd m = \gamma (T_i-M_i).
\end{equation}
Similarly, 
\begin{align*}
    \int_0^1 m\frac{\partial}{\partial m}\left(\sigma(m)\frac{\partial p_i(m,t)}{\partial m}\right)\dd m &= \left.m\sigma(m)\frac{\partial p_i(m,t)}{\partial m}  \right\vert_{m=0}^{m=1} - \int_0^1 \sigma(m)\frac{\partial p_i(m,t)}{\partial m}\dd m\\
    &= -\left( \left.\sigma(m) p_i(m,t)\right\vert_{m=0}^{m=1} - \int_0^1 \sigma'(m) p_i(m,t) \dd m\right).
\end{align*}
Since $\sigma(m) = \mu m(1-m)$, with $\mu > 0$, the above expression integrates to
\begin{equation}
    \label{appeq:IBP1}
    \int_0^1 \sigma'(m) p_i(m,t) \dd m = \mu \int_0^1 (1-2m)p_i(m,t) \dd m = \mu(T_i - 2Mi).
\end{equation}
Substituting Equations~\eqref{appeq:IBP2} and~\eqref{appeq:IBP1} into Equation~\eqref{appeq:MEq1} yields
% \begin{equation}
%     \frac{\dd M_j}{\dd t} = \lambda_i M_i +\gamma(T_i - M_i) +\mu(T_i - 2M_i) + \sum_{j=1}^n k_{ij}M_j
% \end{equation}
\begin{equation}
    \frac{\dd M_j}{\dd t} = (\lambda_i-\gamma - 2\mu) M_i +(\gamma+\mu)T_i  + \sum_{j=1}^n k_{ij}M_j.
\end{equation}

\newpage
\section{ODE derivation for the average malignancy}
\label{appendix:malignancy}
Define the mean malignancy, $\mathcal{M}_i$ as $\mathcal{M}_i = M_i/T_i$. We obtain
\begin{align*}
    \frac{\dd \mathcal{M}_i}{\dd t} &= \frac{T_i\cdot\left((\lambda_i-\gamma - 2\mu) M_i +(\gamma+\mu)T_i  + \sum_{j=1}^n k_{ij}M_j\right) - M_i\cdot\left(\lambda_i T_i + \sum_{j=1}^n k_{ij}T_j \right)}{T_i^2}\\
    &= (\gamma + \mu) - (\gamma + 2\mu)\mathcal{M}_i + \frac{T_i\sum_{j=1}^n k_{ij}M_j - M_i\sum_{j=1}^n k_{ij}T_j }{T_i^2} \\
    &= (\gamma + \mu) - (\gamma + 2\mu)\mathcal{M}_i + \frac{\sum_{j=1}^n k_{ij}\mathcal{M}_jT_j - \mathcal{M}_i\sum_{j=1}^n k_{ij}T_j }{T_i}.
\end{align*}
Rearranging,
\begin{equation*}
    \frac{\dd \mathcal{M}_i}{\dd t} = (\gamma + \mu) - (\gamma + 2\mu)\mathcal{M}_i + \sum_{j=1}^n \frac{T_j}{T_i} k_{ij} (\mathcal{M}_j - \mathcal{M}_i),
\end{equation*}
and noting that $T_j/T_i = R_j/R_i$, we finally obtain
\begin{equation}
    \frac{\dd \mathcal{M}_i}{\dd t} = (\gamma + \mu) - (\gamma + 2\mu)\mathcal{M}_i + \sum_{j=1}^n \frac{R_j}{R_i} k_{ij} (\mathcal{M}_j - \mathcal{M}_i).
\end{equation}

