\begin{remark}
When $f$ is linear and full row rank, the construction in Corollary \ref{corollary:generalized_svd} reduces to the linear SVD, since $\bar{\Sigma}$ and $\bar{V}^T$ do not vary with $x$.
The equality $v = V^T$ can be seen by equating the two representations of $F$ and recalling that $v$ is point-wise norm-preserving.
\begin{align}
F(x) = (\bar{U}^T \bar{U}) \bar{\Sigma} \bar{V^T} x &= (I_{p\times p}) \begin{bmatrix}\bar{\Sigma} & 0 \end{bmatrix} v(x) \implies \\
\bar{V}^T x &= v(x)
\end{align}
\end{remark}
\begin{remark}
Note that we make no attempt to derive $\Sigma$ from $f$, either in Lemma \ref{lemma:simpler_svd} or in Corollary \ref{corollary:generalized_svd}.
Unlike in linear SVD, where a construction exists for finding $\Sigma$, identifying the 2-induced norm of each coordinate functional of $f$, which is essentially a Lipschitz constant for $f$, can, at worst, be undecidable, suggesting that in many applications, a potentially conservative approximation may be necessary.
\end{remark}
Many functions with finite 2-induced norm are not members of $\mathrm{Linear}^+$, in which case $\Sigma_{1,1}$ no longer bounds the 2-induced norm of $f$.
The following observation considers how different the 2-induced norm of $f$ can be from $\Sigma_{1,1}$ for functions not in $\mathrm{Linear}^+$.
\begin{observation}
Let $f: \mathbb{R}^n \rightarrow \mathbb{R}^p$ be an arbitrary function satisfying
\begin{align}
\sup_{x \in \mathbb{R}^n \setminus \{0\}} \frac{\|f(x)\|_2}{\|x\|_2} < \infty,
\end{align}
and suppose that for each $i = 1, \dots, m$ there exists a constant \mbox{$c_i \in \mathbb{R}^+$} such that
\begin{align}
|f_i(x)| \le c_i \,\|x\|_2 \quad \forall x \in \mathbb{R}^n.
\end{align}
Then
\begin{align}
\|f\|_{2 \to 2} \;\le\; \sqrt{m}\,\max_{1\le i\le m} c_i.
\end{align}
In other words, the $2$-induced norm of $f$ is at most a factor of $\sqrt{m}$ larger than the largest $2$-induced norm among its coordinate functionals.
\end{observation}

\begin{proof}
For any $x \in \mathbb{R}^n$,
\begin{align}
\|f(x)\|_2 \;=\; \sqrt{\sum_{i=1}^m |f_i(x)|^2}.
\end{align}
Using $|f_i(x)| \le c_i \|x\|_2$ gives
\begin{align}
\|f(x)\|_2 \;\le\; \|x\|_2 \,\sqrt{\sum_{i=1}^m c_i^2}.
\end{align}
Since each $c_i^2 \le \bigl(\max_{1\le i\le m} c_i\bigr)^2$,
\begin{align}
\sqrt{\sum_{i=1}^m c_i^2} \;\le\; \sqrt{m}\,\max_{1\le i\le m} c_i.
\end{align}
Hence
\begin{align}
\|f(x)\|_2 \;\le\; \sqrt{m}\,\max_{1\le i\le m} c_i \,\|x\|_2,
\end{align}
and therefore
\begin{align}
\|f\|_{2 \to 2} \;=\; \sup_{x\neq 0} \frac{\|f(x)\|_2}{\|x\|_2}
\;\le\; \sqrt{m}\,\max_{1\le i\le m} c_i.
\end{align}

The estimate above is \emph{tight}.  Indeed, suppose $c_i=c_j$ for all $1\le i,j\le m$.  
If there exists a sequence $\{x_k\}_{k\in\mathbb N}\subset\mathbb R^{n}\setminus\{0\}$ satisfying 
\begin{align}
\frac{|f_i(x_k)|}{\|x_k\|_2}\;\longrightarrow\;c_i
\quad\text{for every }i=1,\dots,m,
\end{align}
then
\begin{align}
\frac{\|f(x_k)\|_2}{\|x_k\|_2}
=\sqrt{\sum_{i=1}^{m}\Bigl(\tfrac{|f_i(x_k)|}{\|x_k\|_2}\Bigr)^2}
\;\longrightarrow\;\sqrt{m}\,c_i.
\end{align}
Hence the induced gain of $f$ can be made arbitrarily close to the upper bound 
$\sqrt{m}\,c_i$, even though the supremum defining $\|f\|_{2\to2}$ need not be attained for a particular $x$.
\end{proof}
Before applying the preceding generalized SVD results to control systems, we will first need to develop a related decomposition for a function of two arguments.
\begin{lemma}[Norm preservation in the control argument]\label{lemma:one_argument}
Let \(f : \mathbb{R}^{n}\times\mathbb{R}^l\!\to\mathbb{R}^{p}\) satisfy
\begin{align}
\sup_{x \in \mathbb{R}^n, u \in \mathbb{R}^l \setminus \{0\}} \frac{\|f_u(x,u)\|_{2}}{\|u\|_{2}} \;<\; \infty .
\end{align}
Set \(m \triangleq l + p\).  Then there exist  
\begin{enumerate}
  \item a unitary matrix \(U \in \mathbb{R}^{p\times p}\),  
  \item a non–negative diagonal matrix \(\Sigma \in \mathbb{R}^{p\times m}\), and  
  \item a mapping \(v : \mathbb{R}^{n}\times\mathbb{R}^l\!\to\mathbb{R}^{m}\) that satisfies  
        \begin{align}
          \|v(x,u)\|_{2} \;=\; \|u\|_{2},
          \qquad \forall(x,u)\in\mathbb{R}^{n}\times\mathbb{R}^l,
        \end{align}
\end{enumerate}
such that  
\begin{align}
f(x,u) \;=\; U\Sigma\,v(x,u),
\qquad \forall(x,u)\in\mathbb{R}^{n}\times\mathbb{R}^l.
\end{align}
\end{lemma}
\begin{proof}
%

Choose a unitary permutation matrix \(U \in \mathbb{R}^{p\times p}\) that orders the coordinate
functionals of \(f\) by their 2-induced norms.
Let
\begin{align}
\Sigma = 
\begin{bmatrix}
\operatorname{diag}(\sigma_1,\dots,\sigma_p) & 0_{p\times l}
\end{bmatrix}
\in\mathbb{R}^{p\times m},
\qquad
\sigma_i>0.
\end{align}
The diagonal entries \(\sigma_i\) will be fixed momentarily.

Define
\begin{align}
v_{\mathrm{support}}(x,u) \triangleq \Sigma^\dagger U^{\!\top} f(x,u)
\quad\in\mathbb{R}^{m}.
\end{align}
Because the last \(l\) columns of \(\Sigma\) are zero,  
\mbox{\(\Sigma v_{\mathrm{support}} = U^{\!\top}f(x,u)\)}.

Introduce
\begin{align}
v_{\mathrm{kernel}}(x,u) \triangleq
\begin{bmatrix}
0_{p\times l}\\[2pt]
I_{l}
\end{bmatrix}
\,u\;
\sqrt{\frac{\|u\|_{2}^{2}-\|v_{\mathrm{support}}(x,u)\|_{2}^{2}}{\|u\|_{2}^{2}}}
\;\;\in\mathbb{R}^{m},
\end{align}
with the convention \(v_{\mathrm{kernel}}(x,0)=0\).
The stacked matrix is \((p+l)\times l = m \times l\), so the dimensions match.  
Moreover \(\Sigma v_{\mathrm{kernel}}=0\) by construction.
Set
\begin{align}
v(x,u)\triangleq v_{\mathrm{support}}(x,u)+v_{\mathrm{kernel}}(x,u).
\end{align}
For every \(x\) and \(u\neq0\),
\begin{align}
\|v(x,u)\|_{2}^{2}
      =\|v_{\mathrm{support}}\|_{2}^{2}
       +\|u\|_{2}^{2}\Bigl(1-\tfrac{\|v_{\mathrm{support}}\|_{2}^{2}}{\|u\|_{2}^{2}}\Bigr)
      =\|u\|_{2}^{2},
\end{align}
so \(v\) preserves the \(l\)-argument’s norm point-wise norm-preserving in $u$.
%Also note that if $x$ is fixed, the mapping $u \to v(x,u)$ is injective.
For $v_{\mathrm{kernel}}(x)$ to be real--valued we require
\begin{align}
  \|u\|_2^2 - \|v_{\mathrm{support}}(x, u)\|_2^2 > 0 \quad \forall x \in \mathbb{R}^n, u \in \mathbb{R}^l.
\end{align}
This holds if each $\sigma_i$ satisfies
\begin{align}
  \sum_{i=1}^p \frac{f_i(x, u)^2}{\|u\|_2^2 \sigma_i^2} < 1, \quad \forall x \in \mathbb{R}^n, u \in \mathbb{R}^l.
\end{align}
Finally, since \(\Sigma v_{\mathrm{kernel}}=0\),
\begin{equation}
\begin{aligned}
U\Sigma v(x,u) &= U\Sigma v_{\mathrm{support}}(x,u) \\
               &= UU^{\!\top}f(x,u) \\
               &= f(x,u).
\end{aligned}
\end{equation}
Thus \(f(x,u)=U\Sigma v(x,u)\) with \(v\) point-wise norm-preserving in \(u\), as claimed.
\end{proof}

