\begin{definition}[LTI Systems Associated with Nonlinear Systems]
\label{def:linear_in_v}
For some system $G \in \mathcal{J}$, with state space representation:
\begin{equation}
\begin{aligned}
\dot{\varphi}_0(x) &= A \varphi_0(x) + B v(x, u) \\
y &= C \varphi_0(x),
\end{aligned}
\end{equation}
let $G^L$ denote the associated LTI system that is linear in $v$.
\end{definition}
\begin{corollary}
For any $u(t) \in L^2$, $v(\cdot, u(t)) \in L^2$ since $v$ is point-wise norm-preserving in $u$, regardless of $x(t)$.
\end{corollary}
\begin{corollary}
If $G^L$ is a minimal realization, then $G^L$ has a balancing transform, $z = T \varphi_0(x)$, such that its controllability Gramians are equal and diagonal.
\end{corollary}
%All the remaining results in this subsection will be geared towards the development of error bounds for model reduction for control systems in $\mathcal{J}$, culminating in Theorem \ref{theorem:final_bound}.
%However, in the result immediately following this text, we briefly invoke the well-known existence of Gramians for LTI systems, and, noting that systems in $\mathcal{J}$ have an LTI representation with $v$ as their control input, develop a balanced representation of such systems \emph{in their nonlinear coordinates}.
\begin{corollary}[Nonlinear Representation in Balanced Coordinates]
\label{corollary:balanced_nonlinear}
For every system, $G \in \mathcal{J}$, there exists a nonlinear representation of the state space in balanced coordinates, i.e. a representation of the form:
\begin{equation}
\begin{aligned}
\dot{z} = F(z, u) \\
y =  H(z),
\end{aligned}
\end{equation}
that has the same input-output map as the original state space representation.
\end{corollary}
\begin{proof}
Assume without loss of generality that $G^L$ is a minimal realization, and then perform a balancing transform, with transformation matrix, $T$.
Let
\begin{align}
\label{eq:definition_of_R}
S \triangleq \begin{bmatrix} I_{n \times n} & 0 \end{bmatrix}, \quad
R \triangleq ST^{-1}.
\end{align}
Because $\varphi_0(x)$ is state inclusive, $R$ recovers the original state after inverting the balancing transform, such that
\begin{align}
x = R z.
\end{align}
By direct substitution into the original dynamics, we have
\begin{align}
R\dot{z} = f(Rz, u).
\end{align}
Define 
\begin{align}
F(z,u) \triangleq R^{\dagger}f(Rz, u).
\end{align}
We then have:
\begin{align}
\dot{z} = F(z, u).
\end{align}
Substitute $\varphi_0(x) = T^{-1}z$ for the system measurements of the representation found in Theorem \ref{theorem:norm_preserving}, and we have,
\begin{equation}
\begin{aligned}
\dot{z} &= F(z, u) \\
y &= CT^{-1}z.
\end{aligned}
\end{equation}
Let $H(z) = CT^{-1}z$.
This completes the proof.
\end{proof}
\begin{remark}
$F$ could be augmented to include dynamics that are in the null space of $R^{\dagger}$ and this would not impact the input-output equivalence with $f$.
Thus $F$, as defined here, represents a kind of minimal realization that is distinct from the minimal realization of LTI systems.
\end{remark}
\begin{remark}
The mapping, $h$, from state ($x$) to output ($y$), becomes linear in the balanced state coordinates; $H$ is linear in $z$.
When $C = \begin{bmatrix} I_{n\times n} & 0 \end{bmatrix}$, then $R=\tilde{C}$, though this is not generally the case for $C$.
\end{remark}

We will now use the balanced, nonlinear dynamics to derive an expression for $v$ that is purely in terms of the balanced coordinates, $z$.
A careful derivation of $v$ in terms of $z$ is required because $v$ is nominally a function of $x$ and $u$, and it must be shown that $v$ remains real-valued under this change of variables.
%This in turn, will be very helpful for separating the \emph{nonlinear error}, introduced in computing $v$ with a truncated $z$, from the \emph{linear error}, introduced from truncation of the LTI system, and which is agnostic to changes in $v$.
%The sum of these errors will be the final bound.
%The remaining results in this subsection show this formally.
\begin{lemma}[Preservation of State Space Matrices During Balancing]
\label{lemma:same_b}
Let $A, B$ and $C$ be the state-space matrices of some system $G^L$ associated with $G \in \mathcal{J}$, with balancing transform $T$.
Define $\tilde{A} = TAT^{-1}$, $\tilde{B} = TB$, $\tilde{C} = CT^{-1}$.
Then there exists a function, $\tilde{v}: \mathbb{R}^q \times \mathbb{R}^l \to \mathbb{R}^{l+q}$, satisfying:
\begin{align}
\|\tilde{v}(z, u)\|_2 = \|u\|_2, \quad \forall z \in \mathbb{R}^q, u \in \mathbb{R}^l,
\end{align}
such that the state space model
\begin{equation}
\begin{aligned}
\label{eq:linear_system_rep}
\dot{z} &= \tilde{A} z + \tilde{B} \tilde{v}(z, u) \\
y &= \tilde{C} z,
\end{aligned}
\end{equation}
has an identical input-output map to $G$.
%Every system $G \in \mathcal{J}$ has an LTI-like representation purely in terms of balanced coordinates, $z = Tx$, such that there exists a function:
%$\tilde{v}:\mathbb{R}^q\times\mathbb{R}^l \to \mathbb{R}^{l+q}$, satisfying;
%\begin{align}
%\|\tilde{v}(z, u)\|_2 = \|u\|_2, \quad \forall z \in \mathbb{R}^q, u \in \mathbb{R}^l,
%\end{align}
%and a finite-dimensional state-space:
%\begin{equation}
%\begin{aligned}
%\label{eq:linear_system_rep}
%\dot{z} &= \tilde{A} z + \tilde{B} \tilde{v}(z, u) \\
%y &= \tilde{C} z,
%\end{aligned}
%\end{equation}
%such that the controllability and observability Gramians, $\hat{X}_c$ and $\hat{Y}_o$, are equal and diagonal.
%
%with $\tilde{A} = TAT^{-1} \in \mathbb{R}^{q \times q}$ Hurwitz, $\tilde{B} = TB \in \mathbb{R}^{q \times (l+q)}$, and $\tilde{C} = CT^{-1} \in \mathbb{R}^{p \times q}$.
\end{lemma}
\begin{proof}
This proof will comprise a derivation of $\tilde{v}$ and a final step showing that $\tilde{B} = TB$ can still be used to satisfy representation of the system while keeping $\tilde{v}$ real-valued.
\newline \newline
Using the nonlinear representation derived in \mbox{Corollary \ref{corollary:balanced_nonlinear}}, we can define the control component and the autonomous dynamics solely as a function of $z$ and $u$:
\begin{equation}
\begin{aligned}
F_0(z) &\triangleq F(z,0) \\
F_u(z,u) &\triangleq F(z, u) - F_0(z).
\end{aligned}
\end{equation}
Recall that:
\begin{align}
\dot{z} = \tilde{A}z + \tilde{B}v(Rz,u),
\end{align}
and thus,
\begin{align}
\tilde{B}v(Rz,u) = \dot{z} - \tilde{A}z.
\end{align}
But also recall that:
\begin{align}
\label{eq:equality_in_z}
\tilde{A}z = F_0(z),
\end{align}
and thus by substitution,
\begin{align}
\tilde{B}v(Rz,u) = F(z,u) - F(z,0) = F_u(z,u).
\end{align}

We can define a point-wise $u$-norm-preserving mapping, $\tilde{v}:\mathbb{R}^q \times \mathbb{R}^l \to \mathbb{R}^{l+q}$, in a fashion similar to Lemma \ref{lemma:one_argument}.
Define $\tilde{v}_{\mathrm{support}}:\mathbb{R}^q \times \mathbb{R}^l \to \mathbb{R}^{l+q}$ as:
\begin{align}
\tilde{v}_{\mathrm{support}}(z,u) \triangleq \Sigma^{\dagger} U^T T^{-1} F_u(z,u),
\end{align}
such that, by construction, 
\begin{equation}
\begin{aligned}
TB\tilde{v}_{\mathrm{support}}(z,u) &=
T U \Sigma \Sigma^{\dagger} U^T T^{-1} F_u(z,u) \\ &= F_u(z,u).
\end{aligned}
\end{equation}
Define $\tilde{v}_{\mathrm{kernel}}:\mathbb{R}^q \times \mathbb{R}^l \to \mathbb{R}^{l+q}$ as:
\begin{align}
\tilde{v}_{\mathrm{kernel}}(z,u) = 
\begin{bmatrix}
0_{q\times l}\\[2pt]
I_{l}
\end{bmatrix}u \sqrt{\frac{\|u\|_2^2 - \|\tilde{v}_{\mathrm{support}}(z,u)\|_2^2}{\|u\|_2^2}},
\end{align}
and define $\tilde{v}$ as:
\begin{align}
\tilde{v}(z,u) \triangleq \tilde{v}_{\mathrm{support}}(z,u) + \tilde{v}_{\mathrm{kernel}}(z,u),
\end{align}
which is norm-preserving in $u$ and satisfies:
\begin{align}
TB\tilde{v}(z,u) = F_u(z,u).
\end{align}
It remains to show whether the gain in $\tilde{B}$ is sufficiently large such that $\tilde{v}$ is always real-valued.
Note that:
\begin{align}
TBv(Rz,u) = TB\tilde{v}(z,u),
\end{align}
Since $T$ is full rank and $B$ can always be chosen to be full row-rank when selecting $\Sigma$,
\begin{equation}
\begin{aligned}
v_{\mathrm{support}}(Rz,u) &= \tilde{v}_{\mathrm{support}}(z,u) \implies \\
\|v_{\mathrm{support}}(Rz,u)\|_2 &= \|\tilde{v}_{\mathrm{support}}(z,u)\|_2 
\end{aligned}
\end{equation}
If $\Sigma$ was chosen large enough such that
\begin{align}
\|u\|_2^2 - \|v_{\mathrm{support}}(Rz,u)\|_2^2 > 0,
\end{align}
then 
\begin{align}
\|u\|_2^2 - \|\tilde{v}_{\mathrm{support}}(Rz,u)\|_2^2 > 0,
\end{align}
meaning that $\tilde{v}(z,u)$ is always real valued.
\end{proof}
\begin{remark}
For a system $G \in \mathcal{J}$, the state space
\begin{equation}
\begin{aligned}
\dot{z} &= \tilde{A} z + \tilde{B} \tilde{v}(z, u) \\
y &= \tilde{C} z
\end{aligned}
\end{equation}
is a similarity transform of $G^L$ and we will therefore use $G^L$ to refer to either the balanced or original coordinates, with the meaning specified by context.
\end{remark}
