We now focus on the \emph{nonlinear error} introduced in computing $\tilde{v}$ with a truncated $z$.
This will require several steps.
\begin{lemma}[Point-wise Bound on the Error in Computing $\tilde{v}$ from Truncated States]
\label{lemma:nonlinear_error}
Let $\tilde{v}_{\mathrm{support}}$ be defined as in Lemma \ref{lemma:same_b}, $R$ defined as in Corollary \ref{corollary:balanced_nonlinear}, and let $L_u$ be the Lipschitz bound of $f$ in its $u$ argument.
Define
\begin{align}
\label{eq:zero_padded_truncation}
O \triangleq \begin{bmatrix} I_{r\times r} & 0 \\ 0 & 0\end{bmatrix}.
\end{align}
Then for every $G \in \mathcal{J}$,
\begin{equation}
\begin{aligned}
\|\tilde{v}_{\mathrm{support}}&(z,u) - \tilde{v}_{\mathrm{support}}(Oz,u)\|_2 \\ \quad\quad &\le 2 L_u \|\Sigma^{\dagger}U^TT^{-1}\|_2 \|R^{\dagger}\|_2 \| u \|_2, \\
&\forall \; z \in \mathbb{R}^q, u \in \mathbb{R}^l.
\end{aligned}
\end{equation}
%Consider a system $G \in \mathcal{J}$ such that its state space can be represented of the form in Lemma \ref{lemma:same_b}, namely
%\begin{equation}
