%\begin{align}
%\|\tilde{v}(z,u)\|_2 = \|u\|_2.
%\end{align}
%Also consider the matrix $O: \mathbb{R}^{q} \to \mathbb{R}^q$ defined as:
%\begin{align}
%\label{eq:zero_padded_truncation}
%O \triangleq \begin{bmatrix} I_{r\times r} & 0 \\ 0 & 0\end{bmatrix}.
%\end{align}
%Then the following holds:
