%\begin{aligned}
%\|\tilde{v}_{\mathrm{support}}&(z,u) - \tilde{v}_{\mathrm{support}}(Oz,u)\|_2 \\ \quad\quad &\le 2 L_u \|\Sigma^{\dagger}U^TT^{-1}\|_2 \|R^{\dagger}\|_2 \| u \|_2,
%\end{aligned}
%\end{equation}
\end{lemma}
\begin{proof}
Recall the definition of $\tilde{v}_{\mathrm{support}}$,
\begin{align}
\tilde{v}_{\mathrm{support}}(z,u) &\triangleq \Sigma^{\dagger}U^TT^{-1}F_u(z,u).
\end{align}
hence,
\begin{equation}
\begin{aligned}
\|&\tilde{v}_{\mathrm{support}}(z,u) - \tilde{v}_{\mathrm{support}}(Oz,u)\|_2 \\ 
&= \|\Sigma^{\dagger}U^TT^{-1}F_u(z,u) - \Sigma^{\dagger}U^TT^{-1}F_u(Oz,u)\|_2 \\
&= \|\Sigma^{\dagger}U^TT^{-1}(F_u(z,u) - F_u(Oz, u))\|_2 \\
&\le \|\Sigma^{\dagger}U^TT^{-1}\|_2 \|(F_u(z,u) - F_u(Oz, u))\|_2.
\end{aligned}
\end{equation}
Recall the definitions for $S$ and $R$ from Corollary \ref{corollary:balanced_nonlinear}:
\begin{align}
S \triangleq \begin{bmatrix} I_{n \times n} \quad 0 \end{bmatrix}, \quad
R \triangleq ST^{-1},
\end{align}
and thus
\begin{equation}
\begin{aligned}
F_u(z,u) &\triangleq F(z,u) - F(z,0)  \\
&= R^{\dagger}f(Rz, u) - R^{\dagger}f(Rz, 0).
\end{aligned}
\end{equation}
By substitution then,
\begin{equation}
\begin{aligned}
\|&(F_u(z,u) - F_u(Oz, u))\|_2  \\
&= \|R^{\dagger}f(Rz, u) - R^{\dagger}f(Rz, 0) \\
&\quad\quad - R^{\dagger}f(ROz, u) + R^{\dagger}f(ROz, 0)\|_2 \\
&= \|R^{\dagger} \big[(f(Rz, u) - f(ROz, u)) \\
&\quad\quad + (f(ROz, 0) - f(Rz, 0))\big] \|_2 \\
&\le \|R^{\dagger}\|_2 \| (f(Rz, u)  - f(Rz, 0)) \\
&\quad\quad + (f(ROz, 0) - f(ROz, u)) \|_2
\end{aligned}
\end{equation}
By the definition of a Lipschitz bound,
\begin{align}
\|f(\cdot, u) - f(\cdot, 0)\|_2 &\le L_u \|u\|_2.
\end{align}
Thus we have
\begin{align}
\|&(F_u(z,u) - F_u(Oz, u))\|_2 \le 2 L_u \|R^{\dagger}\|_2 \|u\|_2.
\end{align}
Thus the total bound on the error is:
\begin{equation}
\begin{aligned}
\|\tilde{v}_{\mathrm{support}}&(z,u) - \tilde{v}_{\mathrm{support}}(Oz,u)\|_2 \\ \quad\quad &\le 2 L_u \|\Sigma^{\dagger}U^TT^{-1}\|_2 \|R^{\dagger}\|_2 \| u \|_2
\end{aligned}
\end{equation}
\end{proof}
This bound will appear throughout the rest of the paper, so for convenience we will denote it per the following definition:
\begin{definition}
\label{def:def_of_beta}
Let $\beta \triangleq L_u \|\Sigma^{\dagger}U^TT^{-1}\|_2 \|R^{\dagger}\|_2 $, such that
\begin{equation}
\begin{aligned}
\|\tilde{v}_{\mathrm{support}}&(z,u) - \tilde{v}_{\mathrm{support}}(Oz,u)\|_2 &\le 2 \beta
\end{aligned}
\end{equation}
\end{definition}
\begin{remark}
For linear control systems, $\beta = 0$ since $F_u$ is not a function of $z$ for such systems.
\end{remark}
\begin{remark}
Recall from Corollary \ref{corollary:generalized_svd} that a function with bounded 2-induced norm must satisfy certain conditions for $\Sigma$ to tightly bound its 2-induced norm in its SVD-like representation, otherwise some scaling in $\Sigma$ is needed in order for $v$ to remain real-valued.
Note however that any uniform scaling of the diagonal of $\Sigma$  will not impact the balancing transform, $T$, and thus will not impact the tightness of the bound presented in Lemma \ref{lemma:nonlinear_error}.
\end{remark}
%\begin{remark}
%As noted before the lemma, the error introduced in Lemma \ref{lemma:nonlinear_error} is independent of the representation of $F_0$ and by extension any error in the representation of $F_0$.
%This is irrelevant for $G \in \mathcal{J}$, but worth noting for the more realistic scenario where there is error in the Koopman approximation step.
%\end{remark}
The above result bounds the point-wise change in the 2-norm of the control input ($\tilde{v}$) when the state is reduced, but it does not bound the $H_{\infty}$ error in the \emph{control system} when such a reduced control is used.
We now extend that bound.
%Before providing the full error bound (where we also consider the error when truncating $z$ in computing $F_0$), we first address the $H_{\infty}$ norm of the error introduced by truncating the state used to compute the compensating control.

%This definition is crucial as it will allow us to separate the error introduced by truncating the autonomous dynamics (which will appear linear and will be examined in Theorem \ref{theorem:final_bound}) from the error introduced in truncating the state used to compute the compensating control (Corollary \ref{corollary:bounds_nonlinear_portion}).
\begin{corollary}[Bounds on $H_{\infty}$ Error Introduced by $\tilde{v}$ During Truncation]
\label{corollary:bounds_nonlinear_portion}
Consider the system $G_1 \in \mathcal{J}$, represented as:
\begin{equation}
\begin{aligned}
\dot{z} &= \tilde{A} z + \tilde{B}\tilde{v}(z,u) \\
y &= \tilde{C} z.
\end{aligned}
\end{equation}
Also consider the matrix $O$ as defined in \eqref{eq:zero_padded_truncation}, and another system \mbox{$G_2 \in \mathcal{J}$}, represented as:
\begin{equation}
\begin{aligned}
\dot{z} &= \tilde{A} z + \tilde{B}\tilde{v}(Oz,u) \\
y &= \tilde{C} z.
\end{aligned}
\end{equation}
Then the following bound holds:
\begin{equation}
\begin{aligned}
\| G_1 - G_2 \|_{H_\infty} &\le 2 \|G_1^L\|_{H_\infty} \beta_1 %L_u \|\Sigma^{\dagger}U^TT^{-1}\|_2 \|R^{\dagger}\|_2.
\end{aligned}
\end{equation}
\end{corollary}
\begin{proof}
Since $G_1$ and $G_2$ have the same associated $G^L$ per Definition \ref{def:linear_in_v}, for any given $u(t) \in L_2$:
\begin{align}
\|(G_1 - G_2)(u)\|_{H_{\infty}} = \|(G_1^L)(\tilde{v}_1 - \tilde{v}_2)\|_{H_{\infty}}.
\end{align}
Since $\tilde{B}$ maps $\tilde{v}_{\mathrm{kernel}}$ to zero, any deviations between the $\tilde{v}_{\mathrm{kernel}}$ from $G_1$ and $G_2$ do not contribute to the error and thus need not be considered in what follows.
Remove $\tilde{v}_{\mathrm{kernel}}$ by defining
\begin{align}
v_1 \triangleq \tilde{v}_{\mathrm{support},G_1}, \quad
v_2 \triangleq \tilde{v}_{\mathrm{support},G_2}.
\end{align}
Recall that for that same given $u(t) \in L_2$, we have that, point-wise, 
\begin{equation}
\begin{aligned}
\|v_1&(t) - v_2(t)\|_2 &\le 2 \beta \|u(t)\|_2, \quad \forall t \in \mathbb{R}^+
\end{aligned}
\end{equation}
Thus,
\begin{equation}
\begin{aligned}
\|v_1 - v_2\|_{L_2} &= \big( \int_0^{\infty} \|v_1(t) - v_2(t)\|_2^2 dt \big)^{\frac{1}{2}} \\
&\le 2 \beta \big( \int_0^{\infty} \|u(t)\|_2^2 dt \big)^{\frac{1}{2}} \\
&= 2 \beta \|u\|_{L_2}.
\end{aligned}
\end{equation}
Therefore,
\begin{equation}
\begin{aligned}
\|(G_1 - G_2)(u)\|_{H_\infty} &= 
\|(G_1^L)(v_1 - v_2)\|_{H_\infty} \\
&\le \|v_1 - v_2\|_{L_2} \|G_1^L\|_{H_\infty} \\
&\le 2 \beta \|u\|_{L_2} \|G_1^L\|_{H_\infty}
\end{aligned}
\end{equation}
Finally, since this holds for all $u \in L_2 \setminus \{0\}$,
\begin{align}
\sup_{u \in L_2 \setminus \{0\}} \frac{\| (G_1 - G_2)(u) \|_{L_2}}{\|u\|_{L_2}} < 2 \beta \|G_1^L\|_{H_\infty}.
\end{align}
\end{proof}
\begin{remark}
Unlike Lemma \ref{lemma:nonlinear_error}, this error bound is impacted by the tightness of $\sigma_1$ (the choice of $\tilde{B}$) in bounding the 2-induced norm of $\bar{f}_u$.
If $\bar{f}_u$ does not meet the conditions in Corollary \ref{corollary:generalized_svd}, such that the diagonal elements of $\Sigma$ must be scaled in some way to make $\tilde{v}_{\mathrm{kernel}}$ real-valued for all $z$ and $u$, then $\|G_1^L\|_{H_{\infty}}$ will be scaled accordingly.
\end{remark}

We are now ready to place a final bound on the total error by considering both the error introduced from truncating $z$ in computing $\tilde{v}$ (already shown) in addition to truncating the associated linear dynamics, $G^L$.
\begin{theorem}[Error Bounds for Reduced Nonlinear Control Systems]
\label{theorem:final_bound}
For every system $G \in \mathcal{J}$, there exists a reduced-order model of $G_r$ such that:
\begin{align}
\label{eq:bounds}
\|G - G_r \|_{H_{\infty}} < 2 (\beta \|G^L\|_{H_\infty} + \sum_{r+1}^q \sigma_i)
\end{align}
where $r$ is the number of preserved states, $\sigma_i$ is the $i$-th Hankel singular value of $G^L$ as defined in Definition \ref{def:linear_in_v}, and $\beta$ is defined as in Definition \ref{def:def_of_beta}.
\end{theorem}
\begin{proof}
%We begin by evoking the result in Corollary \ref{corollary:bounds_nonlinear_portion}, where truncation of the balanced, lifted state was performed only when computing $\tilde{v}$.
Recall that in Corollary \ref{corollary:bounds_nonlinear_portion}, the state space of the nonlinear system, $G = G_1$, was expressed as
\begin{equation}
\begin{aligned}
\dot{z} &= \tilde{A} z + \tilde{B}\tilde{v}(z,u) \\
y &= \tilde{C} z,
\end{aligned}
\end{equation}
while the partially truncated system, $G_2$, was defined using the zero-padding truncation operator, $O$, as defined in \eqref{eq:zero_padded_truncation}:
\begin{equation}
\begin{aligned}
\dot{z} &= \tilde{A} z + \tilde{B}\tilde{v}(Oz,u) \\
y &= \tilde{C} z.
\end{aligned}
\end{equation}
In this framing, we had
\begin{equation}
\begin{aligned}
\|G_1 - G_2\|_{H_\infty} &= 
\|(G^L)(\tilde{v} - \tilde{v}_r)\|_{H_{\infty}} \\ 
&\le 2 \beta \|G^L\|_{H_\infty}.
\end{aligned}
\end{equation}
Let $G^L_r$ be the truncated system associated with $G^L$ according to the usual technique for linear balanced truncation.%, and recall that $G_2^L = G_1^L = G^L$.
We then have that
\begin{align}
G_r(u) = G^L_r(\tilde{v}_r).
\end{align}
We can now leverage the $u$-norm-preserving property of $\tilde{v}_r$ to show that the induced norm of the difference between $G_2$ (the nonlinear system achieved by replaced $\tilde{v}$ with $\tilde{v}_r$) and the fully reduced nonlinear system, $G_r$, is equivalent to the error between the full and reduced associated linear systems:
\begin{align}
\|G_2 - G_r \|_{H_{\infty}} &= \sup_{u \in L_2 \setminus \{0\}} \frac{\|(G_2 - G_r)(u)\|_{L_2}}{\|u\|_{L_2}} \\
&= \sup_{u \in L_2 \setminus \{0\}} \frac{\|(G_2^L - G_r^L)(\tilde{v}_r)\|_{L_2}}{\|u\|_{L_2}} \\
&= \sup_{u \in L_2 \setminus \{0\}} \frac{\|(G_2^L - G_r^L)(\tilde{v}_r)\|_{L_2}}{\|\tilde{v}_r\|_{L_2}} \\
&= \|G_2^L - G^L_r \|_{H_{\infty}},
\end{align}
Recalling that $G_1^L = G_2^L = G^L$, we simplify to $G^L$, such that we say $\|G_2 - G_r \|_{H_{\infty}} = \|G^L - G^L_r \|_{H_{\infty}}$.
From classic results in linear systems theory, this induced norm is bounded by the Hankel singular values of $G^L$:
\begin{align}
\|G^L - G^L_r \|_{H_{\infty}} < 2 \sum_{r+1}^q \sigma_i.
\end{align}
Since $\|G_1-G_2\|_{H_{\infty}}$ is bounded, and $\|G_2-G_r\|_{H_{\infty}}$ is bounded, we have that $\|G_1-G_r\|_{H_{\infty}}$, or equivalently \mbox{$\|G-G_r\|_{H_{\infty}}$}, is no more than the sum of these bounds, i.e.:
\begin{align}
\|G-G_r\|_{H_{\infty}} \le 2(\beta\|G^L\|_{H_{\infty}} + \sum_{r+1}^q \sigma_i)
\end{align}
\end{proof}
\begin{remark}
Similar to Corollary \ref{corollary:bounds_nonlinear_portion}, the tightness of this bound is impacted by the tightness of $\sigma_1$ in bounding the 2-induced norm of $\bar{f}_u$.
For almost all balancing transforms, any scaling of the $\Sigma$ used to represent $\bar{f}_u$ will be reflected in the portions of $\tilde{B}$ that are truncated and thus will increase the conservativeness of the truncated Hankel singular values of the balanced system.
\end{remark}
\begin{remark}
Recall that for linear systems, $\beta = 0$, and thus this bound reduces to the expected bound in the linear case.
\end{remark}
\begin{remark}
An important assumption in the aforementioned result was the existence of dynamics which admit a finite-dimensional Koopman representation whose eigenfunctions can be expressed as  functions that individually have finite 2-induced norm.
Commonly studied bases for function spaces do not usually have this property, and future work will involve exploring numeric results with bases that have this property.
%In the numeric results section we demonstrate examples of a modified Chebychev Polynomial basis and a neural network basis that both maintain this property.
\end{remark}

\subsection{Main Results Part 2: Extension to Systems with Approximate Koopman Representations}
We now proceed to expand the results from the previous section to a class of control systems that can only approximately be represented in finite dimensions with a Koopman generator and observables with finite 2-induced norm.
For clarity, this subsection will be broken into several steps.
\subsubsection{Balanced Coordinates for Nonlinear Systems with Error in the Koopman Representation}
\begin{definition}
Let $\mathcal{J}^+$ be the set of all control systems that satisfy the axioms of the set $\mathcal{J}$, with the relaxation that there exists a function, $\bar{f}_{\mathrm{error}}: \mathbb{R}^q \to \mathbb{R}^q$, with finite 2-induced norm, such that:
\begin{align}
\dot{\varphi}_0(x) = A \varphi_0(x) + \bar{f}_{\mathrm{error}}(x), \quad \forall x \in \mathbb{R}^n.
\end{align}
\end{definition}
\begin{observation}
By definition, $\bar{f}_{\mathrm{error}}$ is the difference of two functions of finite 2-induced norm, namely:
\begin{align}
\bar{f}_{\mathrm{error}} \triangleq D_{\varphi_0} f(x,0) - A \varphi_0(x).
\end{align}
Hence, $\bar{f}_{\mathrm{error}}$ has an SVD-like representation of the form:
\begin{align}
\bar{f}_{\mathrm{error}}(\varphi(x)) = U_{\mathrm{error}} \Sigma_{\mathrm{error}} v_{\mathrm{error}}(\varphi_0(x)),
\end{align}
with $v_{\mathrm{error}}: \mathbb{R}^{q} \to \mathbb{R}^{2q}$ satisfying:
\begin{align}
\|v_{\mathrm{error}}(\varphi_0(x))\|_2 = \|\varphi_0(x)\|_2, \quad \forall \varphi_0(x) \in \mathbb{R}^q,
\end{align}
and with $U_{\mathrm{error}} \in \mathbb{R}^{q \times q}$ unitary, and $\Sigma_{\mathrm{error}} \in \mathbb{R}^{q \times 2q}$ rectangular diagonal.

Furthermore, if we define $D_{\mathrm{error}} \in \mathbb{R}^{q \times 2q}$ as:
\begin{align}
D_{\mathrm{error}} \triangleq  U_{\mathrm{error}} \Sigma_{\mathrm{error}},
\end{align}
then we have that:
\begin{equation}
\begin{aligned}
\bar{f}_0(x) &= A \varphi_0(x) + \bar{f}_{\mathrm{error}}(\varphi_0(x)) \\
&= A \varphi_0(x) + D_{\mathrm{error}}v_{\mathrm{error}}(\varphi(x)).
\end{aligned}
\end{equation}
\end{observation}

\begin{corollary}[LTI-like Representation for Systems with Modeling Error in the Koopman Representation]
\label{theorem:norm_preserving_error}
For every system, $G \in \mathcal{J}^+$, there exists a function, $v:\mathbb{R}^n\times\mathbb{R}^l \to \mathbb{R}^{l+q}$, satisfying:
\begin{align}
\|v(x, u)\|_2 = \|u\|_2, \quad \forall x \in \mathbb{R}^n, u \in \mathbb{R}^l,
\end{align}
as well as a function, $v_{\mathrm{error}}: \mathbb{R}^q \to \mathbb{R}^{2q}$, satisfying:
\begin{align}
\|v_{\mathrm{error}}(\varphi_0(x))\|_2 = \|\varphi_0(x)\|_2, \quad \forall \varphi_0(x) \in \mathbb{R}^q,
\end{align}
such that $G$ has a finite-dimensional state-space representation,
\begin{equation}
\begin{aligned}
\label{eq:linear_system_rep_with_error}
\dot{\varphi}_0(x, u) &= A \varphi_0(x) + B (v(x, u) + B^{\dagger}D_{\mathrm{error}}v_{\mathrm{error}}(\varphi_0(x)) \\
y &= C \varphi_0(x),
\end{aligned}
\end{equation}
with $A \in \mathbb{R}^{q \times q}$ Hurwitz, $B \in \mathbb{R}^{q \times (l+q)}$, and $C \in \mathbb{R}^{p \times q}$, and $D_{\mathrm{error}} \in \mathbb{R}^{q \times 2q}$.
\end{corollary}
\begin{proof}
The proof follows directly from the equality:
\begin{align}
\bar{f}_0(x) = A \varphi_0(x) + D_{\mathrm{error}}v_{\mathrm{error}}(\varphi_0(x)),
\end{align}
Substituting this into the proof for Theorem 1, it is easily seen that the rest of the proof remains unchanged.
Finally, note that, since we have choice in $\Sigma$ when constructing $B$, $B$ can always have been chosen to be full row-rank, such that:
\begin{align}
\dot{\varphi}_0(x,u) &= A \varphi_0(x) + D_{\mathrm{error}}v_{\mathrm{error}}(\varphi_0(x)) + B v(x,u) \\
&= A \varphi_0(x) + B (v(x,u) + B^{\dagger} D_{\mathrm{error}}v_{\mathrm{error}}).
\end{align}
\end{proof}

\begin{corollary}[Nonlinear Representation in Balanced Coordinates for Systems with Error in their Koopman Representation]
\label{corollary:balanced_nonlinear_with_error}
For every system, $G \in \mathcal{J}^+$, there exists a nonlinear representation of the state space in balanced coordinates, i.e. a representation of the form:
\begin{equation}
\begin{aligned}
\dot{z} = F(z, u) \\
y =  H(z),
\end{aligned}
\end{equation}
that has the same input-output map as the original state space representation.
\end{corollary}
\begin{proof}
Define $v'(x,u): \mathbb{R}^n \times \mathbb{R}^l \to \mathbb{R}^{(l+q)}$ as follows:
\begin{align}
v'(x,u) \triangleq v(x,u) + B^{\dagger} D_{\mathrm{error}} v_{\mathrm{error}}(\varphi_0).
\end{align}
Substitute $v'$ for $v$ when constructing $G^L$, and the proof follows identically to the proof for Corollary \ref{corollary:balanced_nonlinear}.
\end{proof}

\begin{lemma}[Preservation of State Space Matrices During Balancing for Systems with Error in their Koompan Representation]
\label{lemma:same_b_with_error}
Recall that every system, $G \in \mathcal{J}^+$ ha a finite-dimensional state-space representation,
\begin{equation}
\begin{aligned}
\label{eq:linear_system_rep}
\dot{\varphi}_0(x,u) &= A \varphi_0(x) + B v'(x, u)\\
y &= C x,
\end{aligned}
\end{equation}
with $v'$ defined as:
\begin{align}
v'(x,u) \triangleq v(x,u) + B^{\dagger} D_{\mathrm{error}} v_{\mathrm{error}}(\varphi_0).
\end{align}
Also recall that any such system has a balancing transform, $T$, such that the controllability and observability Gramians of the balanced system, $\hat{X}_c$ and $\hat{Y}_o$, are equal and diagonal.
\newline \newline
\noindent For such systems, there also exists a representation of $G$ purely in terms of balanced coordinates, $z = Tx$, such that there exists a function
$\tilde{v}:\mathbb{R}^q\times\mathbb{R}^l \to \mathbb{R}^{l+q}$, satisfying;
\begin{align}
\|\tilde{v}(z, u)\|_2 = \|u\|_2, \quad \forall z \in \mathbb{R}^q, u \in \mathbb{R}^l,
\end{align}
and a function $\tilde{v}_{\mathrm{error}}: \mathbb{R}^q \to \mathbb{R}^{2q}$, satisfying
\begin{align}
\|\tilde{v}_{\mathrm{error}}(z)\|_2 = \|z\|_2, \quad \forall z \in \mathbb{R}^q,
\end{align}
as well as a function, $\tilde{v}': \mathbb{R}^q \times \mathbb{R}^l \to \mathbb{R}^{l+q}$, defined as:
\begin{align}
\tilde{v}'(z, u) \triangleq \tilde{v}(z, u) + \tilde{B}^{\dagger}\tilde{D}_{\mathrm{error}}\tilde{v}_{\mathrm{error}}(z),
\end{align}
and a finite-dimensional state-space:
\begin{equation}
\begin{aligned}
\label{eq:linear_system_rep}
\dot{z} &= \tilde{A} z + \tilde{B} \tilde{v}'(z,u) \\
y &= \tilde{C} z,
\end{aligned}
\end{equation}
with $\tilde{A} = TAT^{-1} \in \mathbb{R}^{q \times q}$ Hurwitz, $\tilde{B} = TB \in \mathbb{R}^{q \times (l+q)}$, and $\tilde{C} = CT^{-1} \in \mathbb{R}^{p \times q}$, and $\tilde{D}_{\mathrm{error}} \in \mathbb{R}^{q \times 2q}$.
\end{lemma}
\begin{proof}
Define $F_{\mathrm{error}}: \mathbb{R}^q \to \mathbb{R}^q$ as follows:
\begin{align}
F_{\mathrm{error}}(z) \triangleq F(z,0) - \tilde{A} z,
\end{align}
$F_{\mathrm{error}}$ is defined as the difference between two functions with finite 2-induced norm and hence is also a function with finite 2-induced norm.
Thus, there exist a unitary $\tilde{U}_{\mathrm{error}} \in \mathbb{R}^{q\times q}$, a rectangular diagonal $\tilde{\Sigma}_{\mathrm{error}} \in \mathbb{R}^{q \times 2q}$, and a function, $\tilde{v}_{\mathrm{error}}: \mathbb{R}^q \to \mathbb{R}^{2q}$, satisfying:
\begin{align}
\|\tilde{v}_{\mathrm{error}}(z)\|_2 = \|z\|_2, \quad \forall z \in \mathbb{R}^q,
\end{align}
such that:
\begin{align}
F_{\mathrm{error}} = \tilde{U}_{\mathrm{error}} \tilde{\Sigma}_{\mathrm{error}} \tilde{v}_{\mathrm{error}}(z).
\end{align}
Defining 
\begin{align}
\tilde{D}_{\mathrm{error}} \triangleq \tilde{U}_{\mathrm{error}} \tilde{\Sigma}_{\mathrm{error}},
\end{align}
we have that
\begin{align}
F_{\mathrm{error}} = \tilde{D}_{\mathrm{error}} \tilde{v}_{\mathrm{error}}(z),
\end{align}
hence
\begin{equation}
\begin{aligned}
F_0(z) &= F_{\mathrm{error}}(z) + \tilde{A}z \\
&= \tilde{D}_{\mathrm{error}} \tilde{v}_{\mathrm{error}}(z) + \tilde{A}z.
\end{aligned}
\end{equation}
Making this substitution, the proof follows identically to the proof for Lemma \ref{lemma:same_b}, such that we have
\begin{equation}
\begin{aligned}
\dot{z} &= \tilde{A}z + \tilde{D}_{\mathrm{error}} \tilde{v}_{\mathrm{error}}(z) + \tilde{B}\tilde{v}(z,u) \\
y &= \tilde{C} z
\end{aligned}
\end{equation}
Assuming $\tilde{B}$ is full row-rank, we have:
\begin{equation}
\begin{aligned}
\dot{z} &= \tilde{A}z + \tilde{B}(\tilde{v}(z,u) + \tilde{B}^{\dagger}\tilde{D}_{\mathrm{error}} \tilde{v}_{\mathrm{error}}(z)) \\
y &= \tilde{C} z.
\end{aligned}
\end{equation}
Finally, defining $\tilde{v}': \mathbb{R}^q \times \mathbb{R}^l \to \mathbb{R}^{q+l}$ as:
\begin{equation}
\begin{aligned}
\tilde{v}'(z,u) \triangleq \tilde{v}(z,u) + \tilde{B}^{\dagger}\tilde{D}_{\mathrm{error}} \tilde{v}_{\mathrm{error}}(z),
\end{aligned}
\end{equation}
we have:
\begin{equation}
\begin{aligned}
\dot{z} &= \tilde{A}z + \tilde{B}\tilde{v}'(z,u) \\
y &= \tilde{C} z.
\end{aligned}
\end{equation}
\end{proof}


\subsubsection{Modeling Error as Feedback}

The following results will develop a theory for dealing with modeling error in the Koopman representation of the autonomous dynamics via a robust-control perspective.
That is, modeling error will be represented as positive closed-loop feedback between a nominal plant (the Koopman model with the SVD-like representation of the control inputs), and a ``delta" ($\bar{f}_{\mathrm{error}}$).
These results rely heavily on the Small Gain Theorem, which informally we summarize as stating that for two nonlinear systems $G_1$ and $G_2$, a sufficient condition for the inverse
\begin{align}
(I - G_1 G_2)^{-1}
\end{align}
to exist is if 
\begin{align}
\|G_1 G_2\|_{H_\infty} < 1.
\end{align}
A related canonical result from linear systems theory bounds the norm of the difference of the full system with error entering as feedback, and the system with that feedback removed.
This will be used in later results, so we review it here.
\begin{observation}[Small-gain Gap Bound under Positive Feedback]
\label{observation:feedback_bound}
Let \(G_1(s)\) and \(G_2(s)\) be proper, stable LTI transfer functions with finite $H_\infty$-norms, such that
\begin{align}
    y_1 &= G_1(u_1), \\
    y_2 &= G_2(u_2),
\end{align}
such that the small-gain condition is met:
\begin{align}
      \bigl\|\,G_1 G_2\,\bigr\|_{H_\infty} < 1.
\end{align}
Close the loop \emph{positively} by setting:
\begin{align}
    u_1 &= y_2 , \\
    u_2 &= y_1 ,
\end{align}
and attach an external signal $r$ additively to $u_1$ (any other single-point entry works the same).  

The closed-loop transfer from $r$ to $y_1$ is:
\begin{align}
    M = \bigl(I - G_1\,G_2\bigr)^{-1}\,G_1.
\end{align}
Then
\begin{align}
\|M - G_1 \|_{H_\infty} \le \frac{\|G_1\|_{H_\infty}^2 \|G_2\|_{H_\infty}}{1 - \|G_1 G_2\|_{H_\infty}}
\end{align}
\end{observation}
\begin{proof}
Begin by noting that:
\begin{align}
M - G_1 &= ((I - G_1 G_2)^{-1} - I) G_1,
\end{align}
and then recall that, for any $A \in \mathbb{R}^{n \times n}$, \mbox{$A^{-1} - I = A^{-1}(I - A)$}, thus:
\begin{equation}
\begin{aligned}
M - G_1 &= ((I - G_1 G_2)^{-1} - I) G_1 \\
&= (I - G_1 G_2)^{-1}(I - (I - G_1 G_2)) G_1 \\
&= (I - G_1 G_2)^{-1} G_1 G_2 G_1.
\end{aligned}
\end{equation}
Given $\|G_1 G_2\|_{H_\infty} < 1$, we have by standard small-gain arguments:
\begin{align}
\|(I - G_1 G_2)^{-1}\|_{H_\infty} \le \frac{1}{1 - \|G_1 G_2\|_{H_\infty}},
\end{align}
and thus, by sub-multiplicativity of the $H_{\infty}$ norm,
\begin{align}
\|M - G_1\|_{H_\infty} \le \frac{\|G_1\|_{H_\infty}^2\|G_2\|_{H_\infty}}{1 - \|G_1 G_2\|_{H_\infty}}.
\end{align}
\end{proof}
The next result will involve representing error in the Koopman representation of the autonomous dynamics as feedback from a stateless LTI-like system.
We will then be able to use Observation \ref{observation:feedback_bound} to bound the error introduced via error in the Koopman modeling process.
In the following result the $C$ matrix is assumed to be the identity matrix.
This is helpful for framing the error as feedback, but will require some additional cleanup prior to the direct application of this result to systems where $C$ is not the identity matrix.
\begin{lemma}
\label{lemma:error_as_feedback}
For any system, $M \in \mathcal{J}^+$, that has a state space representation:
\begin{equation}
\begin{aligned}
\dot{z} &= \tilde{A} z + \tilde{B} \tilde{v}'(z,u) \\
y &= I z,
\end{aligned}
\end{equation}
with $\tilde{v}'(z,u)$ defined as:
\begin{equation}
\begin{aligned}
\tilde{v}'(z,u) \triangleq \tilde{v}(z,u) + \tilde{B}^{\dagger} \tilde{D}_{\mathrm{error}} \tilde{v}_{\mathrm{error}}(z),
\end{aligned}
\end{equation}
there exist systems $G_1$ and $G_2$, with the state space representation for $G_1$ defined as:
\begin{equation}
\begin{aligned}
\dot{z}_1 &= \tilde{A} z_1 + \tilde{B} \tilde{v}(z_1, u) \\
y_1 &= \tilde{I} z_1,
\end{aligned}
\end{equation}
and state-space representation for $G_2$ defined as:
\begin{align}
y_2 = \tilde{B}^{\dagger}\tilde{D}_{\mathrm{error}} \tilde{v}_{\mathrm{error}}(u_2),
\end{align}
such that $M$ is equivalent to the positive closed-loop feedback between $G_1$ and $G_2$.
\end{lemma}
\begin{proof}
Recall from Observation \ref{observation:feedback_bound} that we needed to attach an external signal, $r$, to one of the sub-systems in order to define a transfer function for $M$. 
Define the nonlinear control component, $\tilde{v}(z_1, u)$, as this external reference signal, and define $v_1$ as a place-holder for the feedback with $G_2$, giving the following state-space representation for $G_1$:
\begin{equation}
\begin{aligned}
\dot{z}_1 &= \tilde{A} z_1 + \tilde{B} (\tilde{v}(z_1, u) + v_1) \\
y_1 &= \tilde{I} z_1.
\end{aligned}
\end{equation}
Now place $G_1$ and $G_2$ in positive feedback by assigning:
\begin{equation}
\begin{aligned}
v_1 &= y_2 \\
u_2 &= y_1.
\end{aligned}
\end{equation}
This assignment yields the original state space representation for $M$, with $\tilde{v}(z,u)$ as the control input.
\end{proof}


\begin{corollary}
For any system $M \in \mathcal{J}^+$, expressed as the closed-loop feedback between two systems, $G_1$ and $G_2$ as defined in Lemma \ref{lemma:error_as_feedback}, if $G_1$ and $G_2$ satisfy the small-gain condition, namely
\begin{align}
\| G_1 G_2 \|_{H_\infty} < 1,
\end{align}
then the error between $M$ and $G_1$ is bounded as:
\begin{align}
\|M - G_1\|_{H_\infty} \le \frac{\|G_1\|_{H_\infty}^2\|G_2\|_{H_\infty}}{1 - \|G_1 G_2\|_{H_\infty}}.
\end{align}
\end{corollary}
\begin{proof}
This follows directly from Observation \ref{observation:feedback_bound}.
\end{proof}
\begin{definition}
\label{def:def_of_xi}
Let $\xi(\cdot, \cdot)$ be defined as the upper bound on $\| M - G_1 \|_{H_\infty}$, such that:
\begin{align}
\xi(G_1, G_2) \triangleq \frac{\|G_1\|_{H_\infty}^2\|G_2\|_{H_\infty}}{1 - \|G_1 G_2\|_{H_\infty}}
\end{align}
\end{definition}

\begin{remark}
If the nonlinear state-space representation of $M$ is given by
\begin{equation}
\begin{aligned}
\dot{z} &= F(z, u) = F_0(z) + F_u(z,u) \\
y &= I z,
\end{aligned}
\end{equation}
with $F_0(z) = \tilde{A}z + F_{\mathrm{error}}$, then the nonlinear state space for $G_1$ is
\begin{equation}
\begin{aligned}
\dot{z} &= F(z, u) - F_{\mathrm{error}} = \tilde{A} z + F_u(z,u) \\
y &= I z.
\end{aligned}
\end{equation}
Thus, the distance from $M$ to $G_1$ is determined by the change in $y$ that occurs when the error from the Koopman representation no longer enters the dynamics as feedback.
This is important enough to merit a definition.
\end{remark}
\begin{definition}
\label{def:embedded_systems}
For a control system $G \in \mathcal{J}^+$, with state space representation:
\begin{align}
\dot{z} &= \tilde{A} z + \tilde{B} \tilde{v}'(z,u) \\
y &= \tilde{C} z,
\end{align}
let $G^I$, $G^P$, and $G^E$ be related systems defined as follows.
Let the state space for $G^I$ be denoted as:
\begin{align}
\dot{z}_I &= \tilde{A} z_I + \tilde{B} \tilde{v}'(z_I,u) \\
y_I &= I z_I.
\end{align}
Let the state space for $G^P$ be denoted as:
\begin{align}
\dot{z}_P &= \tilde{A} z_P + \tilde{B}(\tilde{v}(z_P,u) + v_p) \\
y_P &= I z_P.
\end{align}
And finally, let the state space for $G^E$ be denoted as:
\begin{align}
y_E &= \tilde{B}^{\dagger} \tilde{D}_{\mathrm{error}} \tilde{v}_{\mathrm{error}}(z_E).
\end{align}
\end{definition}
\begin{remark}
Note, as in Lemma \ref{lemma:error_as_feedback}, that $G^P$ in positive closed-loop feedback with $G^E$ yields $G^I$.
The final bound derived in this section will separately bound $\|G - G^I\|_{H_\infty}$ and \mbox{$\|G^I - G^P\|_{H_\infty}$}.
\end{remark}

Before proceeding it is important to verify that  $\tilde{v}'$ can appropriately be considered a control input for $G^L$, the linear system associated with $G$, given that, in addition to the contribution from the control, it includes the contribution of Koopman modeling error to the dynamics, 
In particular, since the bounds that we derive consider $G^L$ to be an operator mapping $L^2 \to L^2$, we must verify that for every $u \in L^2$, $\tilde{v}' \in L^2$, regardless of the initial condition of the state.

\begin{corollary}[Conditions for $\tilde{v}'$ to be in $L^2$]
\label{corollary:error_as_feedback}
For system any $G \in \mathcal{J}^+$, if its related systems, $G^P$ and $G^E$ satisfy the small gain condition,
\begin{align}
\|G^P G^E\|_{H_{\infty}} \le 1,
\end{align}
then for any $u(t) \in L^2$, the resulting $\tilde{v}'(t)$ for $G$ will also be an element of $L^2$.
\end{corollary}
\begin{proof}
Consider the closed-loop feedback between $G^P$ and $G^E$ created by the following interconnection. Let:
\begin{equation}
\begin{aligned}
v_2 &= y_3 \\
u_3 &= y_2.
\end{aligned}
\end{equation}
This yields a new system, $G^I$, with state space representation fo the form:
\begin{equation}
\begin{aligned}
\dot{z} &= \tilde{A} z + \tilde{B}\tilde{v}'(z,u) \\
y_2 &= I z.
\end{aligned}
\end{equation}
with $\tilde{v}'(z,u) \triangleq \tilde{v}(z,u) + \tilde{B}^{\dagger}D_{\mathrm{error}}\tilde{v}_{\mathrm{error}}(z)$.
From the small-gain theorem, $G^I$ has finite $H_{\infty}$ norm if:
\begin{align}
\|G^P G^E\|_{H_{\infty}} < 1.
\end{align}
If $G^I$ has finite $H_{\infty}$ norm, and $G^I$ is a minimal in $v'$, then the solution of its state, $z(t)$, will be an element of $L^2$ provided that $u(t) \in L^2$.
Now note that, by the norm-preserving nature of $\tilde{v}_{\mathrm{error}}$,
\begin{align}
\tilde{B}^{\dagger} D_{\mathrm{error}} \tilde{v}_{\mathrm{error}}(z) < \sigma_1(\tilde{B}^{\dagger} D_{\mathrm{error}})\|z\|_2, \quad \forall z \in \mathbb{R}^q,
\end{align}
where $\sigma_1$ is the maximum singular value of the product of $\tilde{B}^{\dagger}$ and $D_{\mathrm{error}}$.
Thus, for any $z(t) \in L^2$, \mbox{$\tilde{B}^{\dagger} D_{\mathrm{error}} \tilde{v}_{\mathrm{error}}(z(t)) \in L^2$} as well.
Recall as well that $\|\tilde{v}(z,u)\|_2 = \|u\|_2$, and thus $\tilde{v}(z(t),u(t)) \in L^2$, provided $u(t) \in L^2$.
Therefore, since $\tilde{v}'(z,u)$ is the sum of two functions shown to be in $L^2$, $\tilde{v}'(z,u)$ must also be in $L^2$.
\end{proof}
\begin{remark}
This derivation shows that for any $G \in \mathcal{J}^+$ that satisfies the above small-gain condition, there exists an LTI-like state-space representation of $G$, which we call $G^L$, with $\tilde{v}' \in L^2$ that perfectly matches $G$'s input-output map.
In the derivations that follow, we will freely switch between viewing $G$ as a $G^L$ with $\tilde{v}'$ as a control input, and as a nonlinear system with $u \in L^2$ as its control input.
The justification for doing so is that $H_{\infty}$ bounds for LTI systems hold for any $\tilde{v}' \in L^2$, including the set of particular $\tilde{v}'$ functions that render $G^L$ an equivalent input-output map as the regular nonlinear representation of a system with $u$ as a control input.
\end{remark}


\subsubsection{Transitioning between $G$ and $G^I$}
In Definition \ref{def:embedded_systems} we introduced several sister system for every system $G \in \mathcal{J}^+$.
This included $G^I$, the system wherein $\tilde{C}$ is replaced with an identity matrix.
In the previous subsection we showed that this substitution was useful for framing the error in the Koopman representation of the autonomous dynamics as closed-loop feedback between two systems, $G^P$ and $G^E$, such that their feedback was equivalent to $G^I$.
We also mentioned that some ``cleaning up" would be necessary to fully track error introduced in transitioning between $G$ and $G^I$.
We now proceed with that process.
\begin{definition}
\label{def:def_of_phi}
Given an LTI system, $G^L$, with state space representation,
\begin{align}
\dot{x} = A x + B u \\
y = C x,
\end{align}
let
\begin{align}
\Phi(j \omega) \triangleq (j\omega I - A)^{-1} B,
\end{align}
such that
\begin{align}
\|\Phi\|_{H_\infty} = \sup_{\omega \in \mathbb{R}} \| \Phi(j \omega) \|_{2\to2}.
\end{align}
\end{definition}


\begin{observation}[Bounding the $H_{\infty}$–norm gap for identical $(A,B)$ pairs]
\label{observation:different_c}
Let two stable continuous-LTI systems
\begin{align}
G_1(s)=C_1\,(sI-A)^{-1}B,\qquad 
G_2(s)=C_2\,(sI-A)^{-1}B
\end{align}
share the same state matrix $A\in\mathbb R^{n\times n}$ and input matrix $B\in\mathbb R^{n\times l}$, 
and both have direct term $D=0$.  
Then
\begin{align*}
\|G_1 - G_2\|_{\mathcal H_\infty}
\;\le\;
\|C_1-C_2\|_{2\to2}\ \| \Phi \|_{H_\infty},
\end{align*}
%\begin{align*}
%\bigl|\|G_1\|_{\mathcal H_\infty}-\|G_2\|_{\mathcal H_\infty}\bigr|
%\;\le\;
%\|C_1-C_2\|_2\;
%\sup_{\omega\in\mathbb R}\bigl\|(j\omega I-A)^{-1}B\bigr\|_2,
%\end{align*}
\end{observation}
\begin{proof}
Pointwise in frequency,
\begin{align}
G_1(j\omega)-G_2(j\omega) \;=\;(C_1-C_2)\,\Phi(j\omega),
\end{align}
so by sub-multiplicativity of the spectral norm,
\begin{align}
\|G_1(j\omega)-G_2(j\omega)\|_{2\to2}
      \;\le\;\|C_1-C_2\|_{2\to2}\,\|\Phi(j\omega)\|_{2\to2}.
\end{align}
Taking the supremum over $\omega$ gives
\begin{align}
\|G_1-G_2\|_{H_\infty}\le\|C_1-C_2\|_{2\to2}\,\|\Phi\|_{H_\infty},
\end{align}
%Finally, the reverse triangle inequality for the $H_\infty$ norm yields
%\begin{align}
%\bigl|\|G_1\|_{H_\infty}-\|G_2\|_{H_\infty}\bigr|
%      \le\|G_1-G_2\|_{H_\infty},
%\end{align}
which proves the stated bound.
\end{proof}
\begin{corollary}
\label{corollary:embed_c}
If $C_1$ and $C_2$ have different output dimension, then the bound still holds provided the matrix with smaller output dimension is embedded into the larger dimension by appending rows of zeros.
\end{corollary}
It will be useful to have notation to refer to a $C$ matrix that is embedded to be square.
\begin{definition}
\label{def:embedded_c}
For a matrix, $\tilde{C} \in \mathbb{R}^{p \times q}$, define
\begin{align}
\tilde{C}_0 \triangleq \begin{bmatrix} \tilde{C} \\ \mathbf{0} \end{bmatrix},
\end{align}
such that $\tilde{C}_0 \in \mathbb{R}^{q \times q}$.
\end{definition}



\subsubsection{Reduced Nonlinear Systems}
The final bound we derive will involve transitioning between $G$ and and $G^P$ via $G^I$ and $G^E$.
Since $G^P$ no longer contains feedback introduced by modeling error in the Koopman representation, it is of a form that can be applied directly to Theorem \ref{theorem:final_bound}, meaning balanced truncation can be directly performed with bounded error.
However, the result from that truncation will be missing the feedback from the Koopman modeling error and will therefore not correspond to a direct truncation of the balanced nonlinear representation of the system.
To explicitly highlight what is missing and therefore what the final steps will be in the proof of the final bound, we carefully consider the nonlinear state space representation of the balanced, \emph{truncated} coordinates.

\begin{definition}[Reduced Nonlinear System]
\label{def:reduced_nonlinear}
Given $G \in \mathcal{J}^+$, with state space representation
\begin{equation}
\begin{aligned}
\dot{z} &= \tilde{A} z + \tilde{B} \tilde{v}'(z,u) \\
y &= \tilde{C} z,
\end{aligned}
\end{equation}
and balancing transform, $T$, such that $Tx \triangleq z$, let
\begin{align}
S \triangleq \begin{bmatrix} I_{n \times n} & \textbf{0} \end{bmatrix}, \quad 
T^{-1}_{r} \triangleq T^{-1} \begin{bmatrix} I_{r \times r} \\ \textbf{0} \end{bmatrix},
\end{align}
as well as
\begin{align}
R_r \triangleq S T^{-1}_r,
\end{align}
such that
\begin{align}
x \approx R_r z.
\end{align}
Similar to Corollary \ref{corollary:balanced_nonlinear}, we define a \emph{reduced} nonlinear system, $G_r$, which is an approximation of the original system, as follows:
\begin{equation}
\begin{aligned}
\dot{z}_r &\triangleq F_r(z_r, u) \triangleq R_r^{\dagger}f(R_r z_r, u) \\
y_r &\triangleq \tilde{C}_r z_r
\end{aligned}
\end{equation}
We can then define:
\begin{equation}
\begin{aligned}
F_{0,r}(z_r) &\triangleq F_r(z_r, 0), \\
F_{u,r}(z_r, u) &\triangleq F_r(z_r, u) - F_{0,r}(z_r),
\end{aligned}
\end{equation}
and finally:
\begin{align}
F_{r, \mathrm{error}}(z_r) \triangleq F_{0,r}(z_r) - \tilde{A}_r z_r.
\end{align}
\end{definition}
\begin{remark}
There are currently no bounds on the error between $R_rz$ and $x$.
Thus, $T$ might be any arbitrary invertible transform, and the definition would still be consistent.
However, when $T$ is the balancing transform for $G^L$, we will be able to place bounds on the error of the input-output map of $G$ and $G_r$.
\end{remark}
%From here we can see a road map to closing the gap between the truncation step mentioned prior to the above definition (i.e. the application of Theorem \ref{theorem:final_bound}), and an LTI-like state space representation for $G_r$ useful for bounding the distance from $G$ to $G_r$: re-introduce the feedback that accounts for the modeling error in the \emph{truncated} nonlinear state space, $F_{r, \mathrm{error}}$.
%Whereas previously we considered the transition from $G$ to $G^P$, this final step will consider the reverse direction in the truncated system: the transition from $G_r^P$ to $G_r$ via $G_r^E$ and $G_r^I$.
The final bound, given in the following theorem, will proceed by bounding the error introduced in each step below:
\begin{align}
G \to G^I \to G^P \to G_r^P \to G_r^I \to G_r.
\end{align}
For systems with no error in their Koopman representation, there is no feedback to remove and so it is possible go directly from $G$ to $G_r$, as in Theorem \ref{theorem:final_bound}.
%\begin{definition}
%For $G \in \mathcal{J}^+$, and its associated reduced system, $G_r \in \mathcal{J}^+$, with state space
%\begin{align}
%\dot{z}_r &= \tilde{A}_r z_r + \tilde{B}_r \tilde{v}'(z_r, u) \\
%y_r &= \tilde{C}_r z_r, 
%\end{align}
%let
%\begin{align}
%\Phi_r(j \omega) \triangleq (j \omega I_r - \tilde{A}_r)^{-1}\tilde{B}_r,
%\end{align}
%such that
%\begin{align}
%\|\Phi_r\|_{H_\infty} = \sup_{\omega \in \mathbb{R}} \| \Phi_r(j \omega) \|_2.
%\end{align}
%\end{definition}

\begin{theorem}
\label{theorem:bound_with_error}
For every system $G \in \mathcal{J}^+$ that statisfies the small gain condition for its sister systems, $G^p$ and $G^E$, as well as $G_r^P$ and $G_r^E$, such that:
\begin{align}
\|G^P G^E \|_{H_\infty} < 1, \quad \|G_r^P G_r^E \|_{H_\infty} < 1,
\end{align}
then the following bound holds:
\begin{equation}
\begin{aligned}
\|G - G_r\|_{H_\infty} \le\quad  &\big(\| \tilde{C}_0 - I \|_{2\to2} \| \Phi \|_{H_\infty} \\
&+ \xi(G^P, G^E) \\
&+ 2(\beta\|G^I\|_{H_{\infty}} + \sum_{r+1}^q \sigma_i) \\
&+ \xi(G_r^P, G_r^E) \\
&+ \| \tilde{C}_{r,0} - I_{r \times r} \|_{2\to2} \| \Phi_r \|_{H_\infty} \big).
\end{aligned}
\end{equation}

\end{theorem}
\begin{proof}
As previously mentioned, this proof will consist of successive bounds on the $H_{\infty}$ between various systems that connect $G$ and $G_r$.
These steps are labeled for clarity.

\noindent\textbf{Step 1: Replace $\tilde{C}$ with $I$}.
We first bound the error between $G$ and $G^I$.
Recall that $G$ has a state-space representation of the form:
\begin{equation}
\begin{aligned}
\dot{z} &= \tilde{A}z + \tilde{B} \tilde{v}'(z, u) \\
y_1 &= \tilde{C}z,
\end{aligned}
\end{equation}
and $G_I$ has the form:
\begin{equation}
\begin{aligned}
\dot{z} &= \tilde{A}z + \tilde{B} \tilde{v}'(z,u) \\
y_2 &= I z.
\end{aligned}
\end{equation}
Let $\tilde{C}_0 \in \mathbb{R}^{q \times q}$ be defined as in Definition \ref{def:embedded_c}, and $\Phi_{1}$ for $G_1$, per Definition \ref{def:def_of_phi}.

From Observation \ref{observation:different_c}, the difference in $H_{\infty}$ norm between $G$ and $G^I$ is given by:
\begin{align}
\|G - G^I \|_{H_\infty} \le \| \tilde{C}_0 - I \|_{2\to2} \| \Phi \|_{H_\infty}
\end{align}

\noindent\textbf{Step 2: Remove Feedback Error}.
Considering Lemma \ref{lemma:error_as_feedback}, we can say that there exists a system, $G^P$, with state space representation:
\begin{equation}
\begin{aligned}
\dot{z}_P &= \tilde{A} z_P + \tilde{B}(\tilde{v}(z_P,u) + v_P) \\
y_P &= I z_P,
\end{aligned}
\end{equation}
and a system $G^E$, with state space representation:
\begin{align}
y_E &= \tilde{B}^{\dagger} \tilde{D}_{\mathrm{error}} \tilde{v}_{\mathrm{error}}(z_E),
\end{align}
such that their positive closed-loop feedback, created by letting:
\begin{equation}
\begin{aligned}
v_P = y_E \\
z_E = y_P,
\end{aligned}
\end{equation}
is equivalent to $G^I$.
Furthermore, we have from Corollary \ref{corollary:error_as_feedback} that:
\begin{align}
\| G^I - G^P \|_{H_\infty} \le \xi(G^P, G^E),
\end{align}
where, per Definition \ref{def:def_of_xi},
\begin{align}
\xi(G^P, G^E) \triangleq \frac{\|G^P\|_{H_\infty}^2\|G^E\|_{H_\infty}}{1 - \|G^E G^P\|_{H_\infty}}.
\end{align}
\textbf{Step 3: Truncate the System}. Recalling that we defined $\tilde{v}(z_P, u)$ as the auxiliary control input, letting $v_P = 0$, we are now at a state space representation that meets all the criteria for Theorem \ref{theorem:final_bound} to apply.
We can therefore conclude that there exists a system $G_r^P$ with state space representation of the form:
\begin{equation}
\begin{aligned}
\dot{z}_r &= \tilde{A}_r z_r + \tilde{B}_r \tilde{v}_r(z_r, u) \\
y &= I_r z_r,
\end{aligned}
\end{equation}
such that
\begin{align}
\| G^P - G_r^P \|_{H_\infty} \le 2(\beta\|G^I\|_{H_{\infty}} + \sum_{r+1}^q \sigma_i).
\end{align}
As mentioned previously, since $F_{r, \mathrm{error}} \neq 0$, and since we are still using $I_r$ instead of $\tilde{C}_r$, we require several additional steps to bound the error between $G_r^P$ and $G_r$.

\textbf{Step 4: Reintroduce Feedback Error}.
We would like to arrive at a system, $G_r^I$, with state space representation:
\begin{equation}
\begin{aligned}
\dot{z}_r &= \tilde{A}_r z_r + \tilde{B}_r \tilde{v}_r'(z_r, u) \\
y &= I_r z_r,
\end{aligned}
\end{equation}
with $\tilde{v}_r'(z_r, u) \triangleq \tilde{v}_r(z_r, u) + \tilde{B}^{\dagger}_r \tilde{D}_{r, \mathrm{error}}\tilde{v}_{r, \mathrm{error}}(z,r)$.
Recalling Lemma \ref{lemma:error_as_feedback}, we can define $G_r^P$, with state space representation:
\begin{equation}
\begin{aligned}
\dot{z}_{r,P} &= \tilde{A}_r z_{r,P} + \tilde{B}_r (\tilde{v}_r(z_{r,P}, u) + v_{r,P}) \\
y_{r,P} &= I_r z_{r,P},
\end{aligned}
\end{equation}
and $G_r^E$, with state space representation:
\begin{equation}
\begin{aligned}
y_{r,E} = \tilde{B}^{\dagger}_r \tilde{D}_{r, \mathrm{error}} \tilde{v}_{r, \mathrm{error}}(u_{r_E}),
\end{aligned}
\end{equation}
and with the positive feedback assignment:
\begin{equation}
\begin{aligned}
v_{r,P} &= y_{r,E} \\
u_{r, E} &= y_{r,P},
\end{aligned}
\end{equation}
which results in a state space identical to $G_r^I$.
By Corollary \ref{corollary:error_as_feedback}, we can now bound the difference between $G_r^P$ and $G_r^I$:
\begin{align}
\| G_r^I - G_r^P \|_{H_\infty} \le \xi(G_r^P, G_r^E).
\end{align}

\textbf{Step 6: Replace $I$ with $\tilde{C}_r$}.

Finally, we consider the distance from $G_r^I$ to $G_r$, with the LTI-like state space equation for $G_r$ given by:
\begin{equation}
\begin{aligned}
\dot{z}_r &= \tilde{A}_r z_r + \tilde{B} \tilde{v}'(z_r, u) \\
y &= \tilde{C}_r z_r.
\end{aligned}
\end{equation}
Per Observation \ref{observation:different_c}, we have that:
\begin{equation}
\begin{aligned}
\| G_r^I - G_r \|_{H_\infty} \le \| \tilde{C}_{r,0} - I_{r \times r} \|_{2\to2} \| \Phi_r \|_{H_\infty},
\end{aligned}
\end{equation}
with $\tilde{C}_{r,0}$ defined according to Definition \ref{def:embedded_c} for $\tilde{C}_r$, and $\Phi_r$ defined according to Definition \ref{def:def_of_phi} for $G^L_r$.

Finally, note that
\begin{align*}
\dot{z}_r &= \tilde{A}_r z_r + \tilde{B} \tilde{v}'(z_r, u) \\
&= \tilde{A}_r z_r + \tilde{B} \tilde{v}(z_r, u) + \tilde{B}^{\dagger} \tilde{D}_{r, \mathrm{error}}\tilde{v}_{r, \mathrm{error}}(z_r) \\
&= (\tilde{A}_r z_r + \tilde{D}_{r, \mathrm{error}}\tilde{v}_{r, \mathrm{error}}(z_r)) + \tilde{B} \tilde{v}(z_r, u) \\
&= \tilde{A}_r z_r + F_{r, \mathrm{error}} + F_{r, u} \\
&= F_{r, 0} + F_{r, u} \\
&= F_r(z_r, u).
\end{align*}
Since we have recovered the nonlinear state space representation in the reduced coordinates, we can now conclude that the bound is the sum of the bounds computed in each of the above steps:
\begin{equation}
\begin{aligned}
\|G - G_r\|_{H_\infty} \le\quad  &\big(\| \tilde{C}_0 - I \|_{2\to2} \| \Phi \|_{H_\infty} \\
&+ \xi(G^P, G^E) \\
&+ 2(\beta\|G^I\|_{H_{\infty}} + \sum_{r+1}^q \sigma_i) \\
&+ \xi(G_r^P, G_r^E) \\
&+ \| \tilde{C}_{r,0} - I_{r \times r} \|_{2\to2} \| \Phi_r \|_{H_\infty} \big).
\end{aligned}
\end{equation}
\end{proof}

\begin{remark}
The $\| \tilde{C}_0 - I \|_{2\to2} \| \Phi \|_{H_\infty}$ and  $\| \tilde{C}_{r,0} - I_{r \times r} \|_{2\to2} \| \Phi_r \|_{H_\infty}$ are constant no matter the accuracy of the Koopman model of the autonomous dynamics.
However,
\begin{align}
\lim_{\|G^P G^E\|_{H_\infty} \to 1} \xi(G^P, G^E) = \infty,
\end{align}
hence the bound becomes arbitrarily loose as the feedback required to compensate for modeling error in the Koopman representation approaches the small gain limit.
\end{remark}
\begin{remark}
The small gain condition for nonlinear systems is a sufficient but non-necessary condition.
Thus, the bound on $\|G - G_r\|_{H_\infty}$ given by Theorem \ref{theorem:bound_with_error} may go to infinity, and yet the value may remain bounded.
\end{remark}

\begin{remark}
Any state-inclusive transformation of the state space, $\varphi_0(x)$, \emph{including an identity transformation such as in a Jacobian linearization}, would be sufficient for the above representation provided the appropriate small-gain conditions were met.
Thus the Koopman modeling step may potentially be avoided altogether.
\end{remark}


%One question that arises is which systems have autonomous transient dynamics that can be represented in finite dimensions using basis functions that are Lipschitz continuous.

\section{Conclusion}

In this work we have extended a rich history of previous work identifying nonlinear Controllability and Observability Gramians in control-affine systems to include nonlinear systems of the form:
\begin{equation}
\begin{aligned}
\dot{x} &= f(x, u) \\
y &= h(x),
\end{aligned}
\end{equation}
provided certain Lipschitz continuity and bounded induced-norm properties hold for $f$ and the system is hyperbolically stable around a single invariant set.
These Gramians guide the construction of a balancing transformation, $T$, wherewith model reduction can be performed with error bounds.
This is possible due to the integration of Koopman operator theory with a novel function decomposition reminiscent of singular value decomposition that, in tandem with an additional unconventional decomposition of the dynamics, isolates the contribution of the control to the dynamics in a pseudo-affine way.
When certain small-gain conditions are met, bounds on model reduction error can still be established even when the Koopman representation is only approximately accurate, indicating that in some cases, a Jacobian can be substituted for the Koopman approximation step while keeping the truncation error bounded.

