\begin{definition}\label{def:mu:star}
Given $\omega \in (0,1)$, define $H_{\omega}= \left\{\type \in T \mid \sens_{\type} \geq \omega \right\}$ and $L_{\omega} = \left\{\type \in T \mid \sens_{\type} < \omega \right\}$.
Define $\vec{\mu}^*(\omega) \in \mathbb{R}_{> 0}^{|T|}$ such that
\begin{align}
    \mu^*_{\type}(\omega) &=
    \begin{cases}
        \frac{\sens_{\type}}{-\ln\left(1-\omega\right)}, & \text{if } \type \in H_{\omega}, \\%[8pt]
        \frac{\sens_{\type}}{-\ln(1-\sens_{\type})}, & \text{if } \type \in L_{\omega} \text{ and } \sens_{\type}  >0, \\%[8pt]
        1, & \text{if $\type \in L_{\omega}$ and $\sens_{\type}=0$.}
    \end{cases}
   \label{eq:mu-star-params}
\end{align}
\end{definition}

The following corollary is easy to verify.
\begin{corollary}\label{cor:mu:feasible}
$\vec{\mu}^*(\omega)$ is a feasible solution of $\poarmp$.    
\end{corollary}

\begin{proof}{Proof}
Clearly, \eqref{eq:key-lemma-0-constraint} holds for all utility maximizing types $\type \in H_{\omega}$ with $\sens_{\type} = 1$. 
Also, \eqref{eq:key-lemma-1-constraint} 
is satisfied for each $\type \in H_{\omega}$ with $\sens_{\type} < 1$ because $\sens_{\type}  \geq \omega$ (as $\type \in H_{\omega}$) and because the function $f(z)=-\ln(1-z)$ is non-negative and non-decreasing on $(0,1)$.
Further, \eqref{eq:key-lemma-1-constraint} 
is satisfied with equality for all types $\type \in L_{\omega}$ with $\sens_{\type} > 0$.
Finally, \eqref{eq:key-lemma-2-constraint} holds for all value maximizing types $\type \in L_{\omega}$ with $\sens_{\type} = 0$. 
\end{proof}

We introduce some more notation. For a given set $T$ of agent types, we define $\sens_{\max} = \max_{\type \in T}\sens_{\type}$ and $\sens_{\min} = \min_{\type \in T}\sens_{\type}$. If $\sset{\type \in T}{\sens_{\type}>0} \neq \emptyset$, we define $\sens_{\min_{+}} = \min_{\type \in T: \sens_{\type}>0}\sens_{\type}$.
We also define $\lambda^*_{\type}(\omega) = \lambda_{\type}$ with $\lambda_{\type}$ as defined in \eqref{eq:key-lemma-0-constraint}--\eqref{eq:key-lemma-2-constraint} with $\mu_{\type} = \mu^*_{\type}(\omega)$ as in Definition~\ref{def:mu:star}.
For these definitions of $\lambda^*_{\type}(\omega)$ and $\mu^*_{\type}(\omega)$, we state several properties which will be useful in the proofs below. The proof of the properties can be found in Appendix~\ref{app:identities}.





\begin{lemma} \label{lemma:technical-lemma}
The following properties hold for every set of agent types $T$ with $\sens_{\max} > 0$ and every $\omega \in (0, \sens_{\max}] \cap (0,1)$:    
\begin{enumerate}[label=(\roman*)]
   \item
   $
   \lambda^*_{\type}(\omega) =
            \begin{cases} 
                \frac{\omega}{-\ln(1-\omega)}, & \text{if } \type \in H_{\omega}, \\
                \frac{\sens_{\type}}{-\ln(1-\sens_{\type})}, & \text{if } \type \in L_{\omega} \text{ and } \sens_{\type} >0, \\
                1, & \text{if $\type \in L_{\omega}$ and $\sens_{\type}=0$}.
            \end{cases} 
    $
    \item 
    $
    \min_{%\substack
    {\type \in T: \sens_{\type} > 0} }\lambda_{\type}^*(\omega) = \frac{\omega}{-\ln(1-\omega)}.
    $
    \item 
    $
    \max_{%\substack
    {\type \in T: \sens_{\type} > 0}} \frac{1-\sens_{\type} }{\lambda^*_{\type}(\omega)} =
    \begin{cases}
         \frac{-\ln(1-\omega)(1-\sens_{\min_{+}})}{\omega}, & \text{if } \sens_{\min_{+}} \ge \omega, \\
        \frac{-\ln(1-\sens_{\min_{+}})(1-\sens_{\min_{+}})}{\sens_{\min_{+}}}, & 
         \text{if } \sens_{\min_{+}} < \omega.  
    \end{cases}
    $
    \item 
    $
    \max_{%\substack
            {\type \in T: \sens_{\type}  > 0}} \frac{\mu^*_{\type}(\omega)}{\lambda^*_{\type}(\omega)}= \frac{\sens_{\max}}{\omega}.
    $
   \end{enumerate}
\end{lemma}

The following lemma will be useful when proving the bounds on the POA of Theorem~\ref{theorem:full-hybrid-no-reserve} below. The proof is given in Appendix~\ref{app:lowerbound-poarmp-general}. 

\begin{lemma} \label{lemma:general-omega-lb}
Let $T$ be a set of different agent types with sensitivities $\vec{\sigma} \in [0,1]^{|T|}$. 
If $\sens_{\max} > 0$, then for every $\omega \in (0 ,\sens_{\max}] \cap (0,1)$ the optimal value of $\poarmp$ is at least:
    \begin{equation*}
        \min \left\{\frac{\omega}{-\ln(1-\omega)}, \frac{\omega}{\omega + \sens_{\max}} \right\}.
    \end{equation*}  
\end{lemma}

With the help of Lemma~\ref{lemma:general-omega-lb}, it is not hard to derive the following bounds on the POA. Recall that $W_{0}(\cdot)$ is the principal branch of the Lambert function. 

\begin{theorem} \label{theorem:full-hybrid-no-reserve}
Consider the class of simultaneous first-price auctions with fractionally subadditive valuations $\vec{v} \in \mathcal{V}_{\xos}$. 
Then:
\begin{align*}
     \text{\cce-\poa}(\mathcal{V}_{\xos}) &\leq
    \begin{cases}
        1 + \frac{\sens_{\max} }{1+W_{0}\left(-e^{-\sens_{\max}-1}\right)}, & \text{if } \sens_{\max} > 1 + \frac{W_{0}(-2e^{-2})}{2}, \\
        2, & \text{otherwise.}
    \end{cases}
\end{align*}
\end{theorem}

Theorem \ref{theorem:full-hybrid-no-reserve} reveals an intriguing threshold phenomenon: the POA stays at $2$ for all $\sens_{\max} < 0.79$, and increases from $2$ to $2.18$ as $\sens_{\max}$ increases to 1. 
The following two mathematical claims will also be useful in the proof of Theorem \ref{theorem:full-hybrid-no-reserve}. The proofs of the claims can be found in Appendix~\ref{app:math-claims-theorem-no-reserve-sigma-max}.

\begin{claim} \label{claim:LW:prop0}
Consider the function $f(z) = 1 + W_{0}\left(-e^{-z-1} \right)$. For every $z \in \left(1+ \nicefrac{W_{0}\left(-2e^{-2} \right)}{2}, 1\right]$, it holds that $f(z)<z.$ 
\end{claim}

\begin{claim} \label{claim:LW:prop1}
Consider the function $f(z)= 1 + W_{0}\left(-e^{-z -1} \right)$. For every $z \in (1 +  \nicefrac{W_{0}\left(-2e^{-2}\right)}{2}, 1]$, it holds that $f(z)+z = -\ln(1-f(z))$. 
\end{claim}

We can now prove Theorem~\ref{theorem:full-hybrid-no-reserve}.
\medskip

\begin{proof}{Proof of Theorem~\ref{theorem:full-hybrid-no-reserve}}
If $\sens_{\max} = 0$, then all agents are value maximizers. Assume that the value maximizers are of type $\type$. Then, for every $\omega \in (0,1)$, using \eqref{eq:key-lemma-2-constraint} and \eqref{eq:mu-star-params} we get that the value of the objective of $\poarmp$ is at least:
\begin{equation*}
    \min \left\{ \lambda_{\type}, 
    \left( \frac{\mu_{\type}}{\lambda_{\type}} 
    + \frac{1}{\lambda_{\type}} 
    \right)^{-1} \right\} = \min\left\{1 , \left(1 + 1\right)^{-1}\right\}= \frac{1}{2}.
\end{equation*}

Now assume that $\sens_{\max} > 0$. We distinguish the following two cases.
\medskip

\noindent \underline{Case 1:}
$\sens_{\max} \leq 1 + \nicefrac{W_{0}(-2e^{-2})}{2}$.
Let $\omega = \sens_{\max}$. Then $\omega \in (0, \sens_{\max}] \cap (0,1)$ as $\sens_{\max} < 1$, and we can invoke Lemma \ref{lemma:general-omega-lb} with $\omega = \sens_{\max}$.
Hence, we obtain that the value of the objective function of $\poarmp$ is at least:
\begin{equation}\label{eq:2-bound-main-thm}
    \min \left\{\frac{\omega}{-\ln(1-\omega)}, \frac{\omega}{\omega + \sens_{\max}} \right\} = \min\left\{\frac{\sens_{\max}}{-\ln(1-\sens_{\max})}, \frac{1}{2}\right\}= \frac{1}{2}.
\end{equation}
Here, the first and second equality follow  by choice of $\omega = \sens_{\max}$ as $\frac{z}{-\ln(1-z)} \geq \frac{1}{2}$ for all $z \leq  1 + \nicefrac{W_{0}(-2e^{-2})}{2}$.
\medskip

\noindent \underline{Case 2:} $\sens_{\max} >  1 + \nicefrac{W_{0}(-2e^{-2})}{2}$. 
Let $\omega =  1 + W_{0}\left(-e^{-\sens_{\max} -1} \right)$. 
Using Claim ~\ref{claim:LW:prop0}, we get that $\omega = f(\sens_{\max}) < \sens_{\max}$ whenever $\sens_{\max} \in (1+ \nicefrac{W_{0}(-2e^{-2})}{2}, 1]$.     
Therefore, $\omega \in (0, \sens_{\max}] \cap (0,1)$ as $\sens_{\max} \le 1$ and we can invoke Lemma \ref{lemma:general-omega-lb} with $\omega =  1 + W_{0}\left(-e^{-\sens_{\max} -1} \right)$.
Hence, we obtain that the value of the objective function of $\poarmp$ is at least:
\begin{align}
    \min \left\{\frac{\omega}{-\ln(1-\omega)}, \frac{\omega}{\omega + \sens_{\max}} \right\} 
    = \frac{\omega}{\omega + \sens_{\max}}=\frac{ 1 + W_{0}\left(-e^{-\sens_{\max} -1} \right)}{ 1 + W_{0}\left(-e^{-\sens_{\max} -1} \right) + \sens_{\max}}.\label{eq:218-bound-main-thm}
\end{align}
Here, the first equality holds by Claim~\ref{claim:LW:prop1} and the second equality follows by the definition of $\omega$. 
\medskip

The proof follows by applying Theorem \ref{theorem:template} and Lemma \ref{lemma:optimal-xi}, together with the lower bounds on $\poarmp$ from \eqref{eq:2-bound-main-thm} or \eqref{eq:218-bound-main-thm}, depending on the above case distinction. 
\end{proof}

The bounds on the POA in Theorem ~\ref{theorem:full-hybrid-no-reserve} depend on the maximum sensitivity of the agents considered ($\sens_{\max}$), whereas the minimum sensitivity can be arbitrary. Contrarily, we can consider settings for which we derive bounds on the POA depending on the minimum sensitivity of the agents considered ($\sens_{\min}$), whereas the maximum sensitivity can be arbitrary. In this case, we derive bounds on the POA for $\sens_{\min} \ge 0.741$ in Theorem~\ref{theorem:not-so-hybrid} below. 
Note that for $\sens_{\min} =1$, we retrieve the bound of $e/(e-1)$.

\begin{theorem} \label{theorem:not-so-hybrid}
Let $\beta$ be the solution to the equation $\beta = 1 - e^{-\frac{1}{\beta}}$, i.e., $\beta \approx 0.741$. 
Consider the class of simultaneous first-price auctions with fractionally subadditive valuations $\vec{v} \in \mathcal{V}_{\xos}$. 
If $\sens_{\min} \geq \beta$, then:
\begin{align*}
     \text{\cce-\poa}\left(\mathcal{V}_{\xos} \right) &\leq \frac{e^{\frac{1}{\sens_{\min}}}}{\sens_{\min} \left(e^{\frac{1}{\sens_{\min}}}-1 \right)} {\in \left[\frac{e}{e-1}, 1.83\right]}.
\end{align*}
\end{theorem}

\begin{proof}{Proof}
Set $\omega = 1 - e^{-\nicefrac{1}{\sens_{\min}}}$. 
Note that $\omega \leq \sens_{\min}$.
Namely, consider $h(z) = z - 1 + e^{-\frac{1}{z}}$. For all $z \in [\beta, 1]$, it holds that $h(z) \geq 0$. To see this, note that $h(\beta) = \beta -1 +e ^{-\frac{1}{\beta}}=0$ by definition of $\beta$. Also, the function $h$ is non-decreasing for all $z \geq \beta$, as $h'(z)=1 +\frac{e^{-\frac{1}{z}}}{z^2}>0$ in this case. Therefore, $h(\sens_{\min}) = \sens_{\min} - \omega \ge 0$.

For $\vec{\mu} := \vec{\mu}^*(\omega)$ and $\vec{\lambda} := \vec{\lambda}^{*}(\omega)$ as defined in \eqref{eq:mu-star-params} and \textit{(i)} of Lemma \ref{lemma:technical-lemma}, respectively, it holds that: 
\begin{align}
\max_{\substack{\type \in T}} \frac{\mu_{\type}}{\lambda_{\type}} 
    + \max_{\substack{\type \in T}} \frac{1 - \sens_{\type} }{\lambda_{\type}} &=\max_{\substack{\type \in T:\\ \sens_{\type} > 0}} \frac{\mu_{\type} }{\lambda_{\type}} 
    + \max_{\substack{\type \in T:\\ \sens_{\type} > 0}} \frac{1 - \sens_{\type} }{\lambda_{\type}}= \frac{\sens_{\max}-\ln(1-\omega)(1-\sens_{\min})}{\omega} \nonumber\\
    &\leq \frac{1-\ln(1-\omega)(1-\sens_{\min})}{\omega} = \frac{-\ln(1-\omega)}{\omega} \nonumber \\
    &+ \frac{1+\ln(1-\omega)\sens_{\min}}{\omega} 
 =\frac{-\ln(1-\omega)}{\omega}. \label{eq:bound-second-part-O}
\end{align}
Here, the first equality holds as there are no value maximizers by assumption. 
The second equality follows from properties \textit{(iii)} and \textit{(iv)} of Lemma \ref{lemma:technical-lemma}, as $\omega \leq \sens_{\min}$. Finally, the last equality follows as $1 + \ln(1-\omega)\sens_{\min} = 0$ by definition of $\omega$. 
We conclude that:
\begin{align*}
    \poarmp &\geq \min \left\{ 
    \min_{\substack{\type \in T}} \lambda_{\type}, 
    \left( \max_{\substack{\type \in T}} \frac{\mu_{\type}}{\lambda_{\type}} 
    + \max_{\substack{\type \in T}} \frac{1 - \sens_{\type}}{\lambda_{\type}} 
        \right)^{-1} \right\}\\
    &=  \min \left\{ 
        \frac{\omega}{-\ln(1-\omega)}, 
        \left( 
            \max_{\substack{\type \in T}} \frac{\mu_{\type}}{\lambda_{\type}} 
            + \max_{\substack{\type \in T}} \frac{1 - \sens_{\type}}{\lambda_{\type}} 
        \right)^{-1}\right\}\\
         &\geq  \frac{\omega}{-\ln(1-\omega)} = \left(1 - e^{-\frac{1}{\sens_{\min}}}\right) \sens_{\min},
\end{align*}
where the first equality follows from property \textit{(ii)} of Lemma \ref{lemma:technical-lemma} and the second inequality follows from \eqref{eq:bound-second-part-O}. 
The proof follows by applying Theorem \ref{theorem:template} and Lemma \ref{lemma:optimal-xi}.
\end{proof}


\subsection{Improving Inefficiency Via Reserve Prices}

In this section, we show that our smoothness framework allows us to capture how inefficiency improves in simultaneous first-price auctions with feasible reserve prices. To that end, and similarly to the existing literature (see, e.g., \cite{balseiro2021robust}), we present the POA upper bounds as functions of the parameter $\eta$. 
Recall that $\eta$ measures the minimum relative gap between the reserve price and the value of the rightful winner of an auction. Naturally, our results show that the bound on the POA improves as $\eta$ increases.
We only focus on additive valuations in this section, as all correlated equilibria are well-supported in this case, which we later proof in Section \ref{sec:well-supported-eq}. 
Additionally, for reasons of analytical tractability, we focus on two specific compositions of agent types. 
First, we consider the mixed agent model. Recall that in this case agents are either value maximizers, i.e., agents of type $\type$ with $\sens_{\type}=0$, or utility maximizers, i.e., agents of type $\type$ with $\sens_{\type} =1$. 
This generalizes a result of \cite{deng2024} (Theorem 3) to well-supported coarse correlated equilibria. 
In the second setting, we consider the scenario of homogeneous agents, i.e., all agents share one common type $\type$. \\


As there are only two agent types in the mixed agent model, we naturally define $\mu_{\type}$ for each agent type. 

\begin{definition}\label{def:mu:bar}
Let $\zeta = 2- \eta + W_{0}\left(-\frac{(1-\eta)^2}{e^{2-\eta}}\right)$. Let $T$ be a set of different agent types containing value and utility maximizers, i.e., $|T| = 2$. Define $\bar{\vec{\mu}}(\eta) \in \mathbb{R}_{>0}^{|T|}$ such that:
\begin{align} \label{eq:mu-for-mixed-agents-with-reserve}
    \bar{\mu}_{\type}(\eta) &=
    \begin{cases}
        \frac{1}{1 - \eta}, & \text{if } \sens_{\type} =0, \\%[8pt] 
        \frac{1}{\zeta}, & \text{if } \sens_{\type} = 1. \\%[8pt]
    \end{cases}
\end{align}
\end{definition}

The following fact will be helpful when showing that $\bar{\vec{\mu}}(\eta)$ is a feasible solution.

\begin{fact} \label{claim:zeta-range}
Let $h(z)= 2- z + W_{0}\left(-\frac{(1-z)^2}{e^{2-z}}\right)$. Then, $h(z) >0$ for all $z \in [0,1)$.
\end{fact}

Note that Fact \ref{claim:zeta-range} holds as $-\frac{(1-z)^2}{e^{2-z}}$ is non-decreasing for $z \in [0,1)$, $W_{0}(\cdot)$ is non-decreasing and $W_{0}(-e^{-2}) \ge -0.16$.
The following corollary stating that $\bar{\vec{\mu}}(\eta)$ is a feasible solution is now easy to verify.

\begin{corollary}\label{cor:mu-bar:feasible}
$\bar{\vec{\mu}}(\eta)$ is a feasible solution of $\poarmp$.    
\end{corollary}

Namely, for agents of type $\type$ with $\sens_{\type} =0$, the constraint in \eqref{eq:key-lemma-2-constraint} is satisfied by construction. For agents of type $\type$ with $\sens_{\type} =1$, the constraint in \eqref{eq:key-lemma-0-constraint} holds as $\zeta > 0$ for all $\eta \in [0,1)$ by Fact \ref{claim:zeta-range}. 
We also define $\bar{\lambda}_{\type}(\eta) = \lambda_{\type}$ with $\lambda_{\type}$ as defined in \eqref{eq:key-lemma-0-constraint} and \eqref{eq:key-lemma-2-constraint} with $\mu_{\type} = \bar{\mu}_{\type}(\eta)$.
The following lemma will be useful when proving our bound on the POA for the mixed agent model. 

\begin{lemma} \label{claim:technical-claim-hybrid-reserves}
Let $\zeta = 2- \eta + W_{0}\left(-\frac{(1-\eta)^2}{e^{2-\eta}}\right)$. Let $T$ be a set of different agent types containing value and utility maximizers, i.e., $|T| = 2$. Then, the following properties hold: 
\begin{enumerate}[label=(\roman*)] 
    \item 
    $
    \min_{\type \in T}\bar{\lambda}_{\type}(\eta) \geq \frac{1-(1-\eta)e^{-\zeta}}{\zeta}.
    $
    \item 
    $
    \max_{\type \in T}\frac{\bar{\mu}_{\type}(\eta)}{\bar{\lambda}_{\type}(\eta)} \leq \frac{1}{1-(1-\eta)e^{-\zeta}}.
    $
    \item 
    $
    \max_{\type \in T}\frac{1 -\sens_{\type }}{\bar{\lambda}_{\type}(\eta)} \leq 1-\eta.
    $
    \item
    $
    \zeta = 2-\eta - (1-\eta)^2e^{-\zeta}.
    $
\end{enumerate}
\end{lemma}

The proof of Lemma \ref{claim:technical-claim-hybrid-reserves} can be found in Appendix~\ref{app:math-claims-theorem-reserve-hybrid}.
We can now prove Theorem~\ref{thm:hybrid-reserve-prices}. 

\begin{theorem} \label{thm:hybrid-reserve-prices}
Consider the class of simultaneous first-price auctions with feasible reserve prices with additive valuations $\vec{v} \in \mathcal{V}_{\add}$ in the mixed agent model, i.e., $|T| =2$ and for all $\type \in T$ it holds that $\sens_{\type} \in \{0,1\}$. Let:
\begin{equation*}
    Q(\eta) = \left(1-\eta\right) \cdot \frac{2-\eta + W_{0}\left(-(1-\eta)^2e^{\eta-2}\right)}{1-\eta + W_{0}\left(-(1-\eta)^2e^{\eta-2}\right)}.
\end{equation*}
Then, for well-supported coarse correlated equilibria, $\cce\textit{-}\poa(\mathcal{V}_{\add}) \leq Q(\eta)$. Furthermore, $Q(\eta)$ is non-increasing in $[0,1)$ with $\lim_{z \to 1}Q(z)=1$.
\end{theorem}


\begin{proof}{Proof of Theorem~\ref{thm:hybrid-reserve-prices}}
Let $\zeta = 2- \eta + W_{0}\left(-\frac{(1-\eta)^2}{e^{2-\eta}}\right)$ and define $\bar{\vec{\mu}} = \bar{\vec{\mu}}(\eta)$ as in \eqref{eq:mu-for-mixed-agents-with-reserve} and $\bar{\vec{\lambda}} = \bar{\vec{\lambda}}(\eta)$. Note that $\bar{\vec{\mu}}$ is a feasible solution by Corollary \ref{cor:mu-bar:feasible}. 
We proceed as in Section \ref{subsec:solving-poarmp} and use $\bar{\vec{\mu}}$ to obtain the following lower bound on the value of the objective function of $\poarmp$: 
\begin{align}
    &\min \left\{ 
    \min_{\substack{\type \in T}} \bar{\lambda}_{\type}, 
    \left( 
        \max_{\substack{\type \in T}} \frac{\bar{\mu}_{\type}}{\bar{\lambda}_{\type}} 
        + \max_{\substack{\type \in T}} \frac{1 - \sens_{\type} }{\bar{\lambda}_{\type}} 
    \right)^{-1} \right\} \nonumber \\
    &\geq \min \left\{\frac{1-(1-\eta)e^{-\zeta}}{\zeta}, \left(\frac{1}{1-(1-\eta)e^{-\zeta}} +1-\eta\right)^{-1} \right\} \nonumber \\
    &=\left(1-(1-\eta)e^{-\zeta} \right) \cdot \min\left\{\frac{1}{\zeta}, \frac{1}{2-\eta -(1-\eta)^2e^{-\zeta}} \right\} \nonumber \\
    &= \frac{1-(1-\eta)e^{-\zeta}}{\zeta}. \label{eq:hybrid-poa-reserves-analysis}
\end{align}
Here, the second inequality follows from properties \textit{(i)}--\textit{(iii)} of Lemma \ref{claim:technical-claim-hybrid-reserves}. 
The final equality holds due to property \textit{(iv)} of the same lemma. We conclude the proof with:
\begin{align*}
    \poa\textit{-}\cce\left(\mathcal{V}_{\add}\right)& \leq \frac{\zeta}{1-(1-\eta)e^{-\zeta}} 
    = (1-\eta) \cdot \frac{\zeta}{1-\eta -(1-\eta)^2e^{-\zeta}} \\
    &=(1-\eta) \cdot \frac{\zeta}{\zeta-1}=Q(\eta),
\end{align*}
where the inequality follows from Theorem \ref{theorem:template}, Lemma \ref{lemma:optimal-xi} and \eqref{eq:hybrid-poa-reserves-analysis}. The second equality holds by property \textit{(iv)} of Lemma \ref{claim:technical-claim-hybrid-reserves}.

Finally, we show that $\lim_{z \to 1} Q(z)  =1$. Let $h(z) = -(1-z)^{2}e^{z-2}$. Then by using l'H\^opital's rule and Fact \ref{fact:lambert-derivative}, it holds that:
\begin{align*}
\lim_{z \to 1} Q(z) &= \lim_{z \to 1} \frac{-2 + z - W_{0}(h(z)) + (1-z) \left(\frac{(1 - z^{2}) W_{0}(h(z)) }{-(1-z)^{2} (1 + W_{0}(h(z)))} -1 \right)}{  \frac{(1 - z^{2}) W_{0}(h(z))}{ -(1-z)^{2} (1 + W_{0}(h(z))) } -1} = \frac{-2 +1}{-1}, 
\end{align*}
as $W_{0}(h(1)) =0$. This concludes the proof.
\end{proof}

Finally, we consider the setting of homogeneous agents, i.e., all agents share one common type $\type$. 

\begin{theorem} \label{theorem:single-type}
Consider the class of simultaneous first-price auctions with feasible reserve prices and additive valuations $\vec{v} \in \mathcal{V}_{\add}$ in which all agents have a common type $\type$ with $\sens = \sens_{\type}$. Let:
\begin{equation*}
     P_{\sens}(\eta) = \begin{cases}
        \frac{e}{e-1 + \eta}, & \text{ if } \sens = 1, \\[2pt]        
        1 + \frac{1}{\sens} \left( \ln\left(\frac{1- \sens \eta}{1- \sens}\right)(1 -\sens) \right), 
        & \text{ if } \sens \in \left( 0, \frac{e-1}{e} \right),\\[2pt]
        2-\eta, &\text{ if } \sens = 0.
    \end{cases}
\end{equation*}
Then, for well-supported coarse correlated equilibria, $\cce\textit{-}\poa(\mathcal{V}_{\add}) \leq P_{\sens}(\eta)$. Furthermore, $P_{\sens}$ is non increasing in $[0,1)$ with $P_{\sens}(1)=1$ for all types $\type$. 
\end{theorem}

\begin{proof}{Proof}
As all agents have a common type $\type$ with $\sens = \sens_{\type}$, lower bounding the objective function of $\poarmp$ reduces to determining a scalar $\mu = \mu_{\type}$ that satisfies \eqref{eq:key-lemma-0-constraint}, \eqref{eq:key-lemma-1-constraint} or \eqref{eq:key-lemma-2-constraint}, depending on the type $\type$. 
Then, for every feasible choice of $\mu$ and corresponding $\lambda = \lambda(\mu)$, we get the following lower bound:
\begin{equation}\label{eq:single-type-objective}
\min \left\{ \lambda, \frac{\lambda}{\mu +1 - \sens}\right\}.
\end{equation}
We distinguish three cases.
\medskip

\noindent \underline{Case 1:} $\sens = 1$. We set $\mu = \sens$. Note that this choice of $\mu$ is feasible as the non-negativity constraint in \eqref{eq:key-lemma-0-constraint} is satisfied. Furthermore, the right hand side of \eqref{eq:single-type-objective} is equal to $\lambda = \mu \left(1- (1-\eta)e^{-\frac{1}{\mu}}\right)=1- (1-\eta)e^{-1}= (P_{\sens}(\eta))^{-1}$. 
\medskip

\noindent \underline{Case 2:} $\sens \in (0,\frac{e-1}{e})$. We set $\mu = \sens \left ( \ln\left(\frac{1- \sens \eta}{1- \sens}\right) \right )^{-1}$, satisfying the constraint in \eqref{eq:key-lemma-1-constraint} with equality. We have that:
\begin{equation}\label{eq:lambda-choice-reserve}
    \lambda = \frac{\mu}{\sens}\left(1-\frac{1- \sens \eta}{e^{\frac{\sens}{\mu}}} \right) = \sens \cdot \ln\left(\frac{1- \sens \eta}{1- \sens}\right)^{-1},
\end{equation}
and since $\eta \in [0,1)$ and $\sens < \frac{e-1}{e}$, this leads to:
\begin{equation}\label{eq:denominator-pos}
    \mu + 1 - \sens = 1 + \sens \left( \frac{1}{\ln\left(\frac{1- \sens \eta }{1- \sens }\right)} - 1 \right) > 1. 
\end{equation}
Therefore, using \eqref{eq:single-type-objective} we can lower bound the objective of $\poarmp$ with:
\begin{equation*}
    \min \left\{ \lambda, \frac{\lambda}{\mu  +1 - \sens }\right\} = \frac{\lambda}{\mu +1 - \sens } = \frac{\sens }{\sens+ \ln\left(\frac{1 - \sens  \eta}{1- \sens} \right)(1 - \sens )}= (P_{\sens }(\eta))^{-1},
\end{equation*}
where the first and second equality follow by \eqref{eq:denominator-pos} and \eqref{eq:lambda-choice-reserve}, respectively.
\medskip

\noindent \underline{Case 3:} $\sens = 0$. 
We set $\mu= (1-\eta)^{-1}$, which clearly satisfies the constraint in $\eqref{eq:key-lemma-2-constraint}$ and prescribes that $\lambda = (1- \eta)^{-1}$. We obtain:
\begin{align*}
    \min \left\{ \lambda, \frac{\lambda}{\mu  +1 - \sens}\right\} &= \min\left\{\frac{1}{1-\eta}, \frac{(1-\eta)^{-1}}{1+ (1-\eta)^{-1}} \right\} 
    = \min\left\{\frac{1}{1-\eta}, \frac{1}{2 -\eta} \right\} \\
    &= \frac{1}{2-\eta} = (P_{\sens}(\eta))^{-1}.
\end{align*}
As the lower bound on the objective value of \poarmp\ is greater than or equal to $(P_{\sens}(\eta))^{-1}$ for all three cases, it holds by Theorem \ref{theorem:template} and Lemma \ref{lemma:optimal-xi} that for well-supported coarse-correlated equilibria:
\[ 
\cce\textit{-}\poa(\mathcal{V}_{ADD}) \leq P_{\sens}(\eta),
\]  
concluding the proof.
\end{proof}


\section{Well-Supported Equilibria and Lower Bounds} \label{sec:well-supported-eq}

When deriving bounds on the POA for simultaneous first-price auctions with feasible reserve prices, we crucially only consider equilibria that are well-supported.
Recall that an equilibrium $\B$ is well-supported if for each auction $j \in M$ the item is always sold, i.e., for each auction $j \in M$ it holds that $\ppr [ x_j(\B) \neq \vec{0} ] = 1$. 
Even though we consider feasible reserve prices, not all equilibria are necessarily well-supported; this depends on the equilibrium notion and the type of valuation functions at hand. 
In this section, we first consider additive valuations and show that, up to correlated equilibria, all equilibria are well-supported. 
We then give three lower bounds on the POA for specific settings with additive valuations. 
We conclude this section by showing that for submodular valuations, there exist equilibria that are not well-supported. In the homogeneous case of utility maximizers, this leads to an unbounded POA.


\subsection{Additive Valuations} \label{subsec:LBaddtive}

In the case of additive valuations, it intuitively does not make sense for the rightful winner $i$ of an auction $j$ to bid below the reserve price $r_j$. As we consider feasible reserve prices, agent $i$ could potentially achieve some positive gain from winning auction $j$, unless some other agent wins the item at a price of $v_{ij}$.
We use this intuition in the proof below and show that, up to CE, all equilibria are well-supported.

\begin{lemma} \label{lem:CE-well-supported} 
Consider the class of simultaneous first-price auctions with additive valuations $\vec{v} \in \mathcal{V}_{\add}$ and feasible reserve prices. 
Then, every \ce\ is well-supported. 
\end{lemma}

\begin{proof}{Proof}
For contradiction, suppose that $\B$ is a CE that is not well-supported, i.e., there exists an auction $j \in M$ such that 
\begin{equation} \label{eq:PositivePrNotSold}
\ppr [ x_j(\B) \neq \vec{0} ] <1.    
\end{equation}
Let agent $i \in N$ be the rightful winner of auction $j$, i.e., $i = \rw(j)$. 
We define the deviation of agent $i$ as follows. For all auctions $k \neq j$, agent $i$ follows the recommendation. However, for auction $j$, agent $i$ follows the recommendation only if the recommendation is to bid above or equal to the reserve price $r_j$. Otherwise, agent $i$ ignores the recommendation and bids exactly the reserve price $r_j$ for auction $j$. More formally, for any $\b_{i}$ in the support of $\B$, we define
\begin{equation}
\swap(\b_i) = \b'_i = (b_{i1}, \dots, b_{i(j-1)}, \max \{b_{ij}, r_j\}, b_{i(j+1)}, \dots,  b_{im}).    \label{eq:deviation}
\end{equation}
Note that by \eqref{eq:PositivePrNotSold}, there exist recommendation(s) $\b_i$ in the support of $\B$ that recommend agent $i$ to bid below the reserve price $r_j$ for auction $j$. 

We first show that the deviation as defined in \eqref{eq:deviation} satisfies the ROI constraint for agent $i$. 
The conditional PDF of $\B_{-i}$ given $\B_{i} = \b_{i}$ is denoted as $f_{\B_{-i} \mid \B_{i}} (\b_{-i} \mid \b_{i})$.
Note that $\B \in {\mathcal{R}_i}$ as $\B$ is a correlated equilibrium, i.e., the ROI constraint is satisfied for agent $i$:
\begin{equation}
\pe \left [ \pe \left [ \sum_{ \ k \in M} p_{ik}(\b_{i}, \B_{-i}) \, \middle\vert \, \B_i = \b_i \right ] \right ]
\le \pe \left [ \pe \left [ \sum_{ \ k \in M} v_{ik}(x_{ik}(\b_{i}, \B_{-i})) \, \middle\vert \, \B_i = \b_i  \right ] \right ]. \label{eq:ROIforCE}
\end{equation}
Recall that the outer expectation is for $\B_i$ and the inner expectation is for $\B_{-i}$.
The ROI constraint for the deviation of agent $i$ is:
\begin{equation}
\pe \! \left [ \pe \! \left [ \! \sum_{ \ k \in M} \! p_{ik}(\swap(\b_{i}), \B_{-i}) \, \middle\vert \, \B_i = \b_i \right ] \right ]
\! \! \le \! \pe \! \left [ \pe \! \left [ \! \sum_{ \ k \in M} \! v_{ik}(x_{ik}(\swap(\b_{i}), \B_{-i})) \, \middle\vert \, \B_i = \b_i  \right ] \right ]. \label{eq:ROIforRecommendation}
\end{equation}
Note that for auctions $k \neq j$, agent $i$ always follows the recommendation, so the terms for these auctions $k$ on the left- and right-hand side of equations \eqref{eq:ROIforCE} and \eqref{eq:ROIforRecommendation} coincide. 
Agent $i$ also follows the recommendation for auction $j$ if $b_{ij} \ge r_j$, so in this case the terms also coincide. 
Finally, consider recommendations for auction $j$ with $b_{ij} < r_j$. In this case the terms for auction $j$ on the left- and right-hand side of equation \eqref{eq:ROIforCE} are equal to 0, as agent $i$ never wins auction $j$ when bidding below the reserve price $r_j$. For the deviation, the terms on the left- and right-hand side in \eqref{eq:ROIforRecommendation} satisfy:
\begin{align*}
&\pe \left [ \pe \left [ p_{ij}(\swap(\b_{i}), \B_{-i}) \mid \B_i = \b_i \wedge b_{ij} < r_j \right ] \right ] \\
&\le 
\pe \left [ \pe \left [ v_{ij}(x_{ij}(\swap(\b_{i}), \B_{-i})) \mid \B_i = \b_i \wedge b_{ij} < r_j  \right ] \right ],
\end{align*}
as $r_j < v_{ij}$ (reserve prices are feasible) and agent $i$ deviates to the reserve price $r_j$ for auction $j$ if $b_{ij} < r_j$.
Combining this with the reasoning above, it follows that the deviation of agent $i$ satisfies the ROI constraint in \eqref{eq:ROIforRecommendation}, i.e., $(\swap(\vec{B}_i), \vec{B}_{-i}) \in {\mathcal{R}_i}$.

We now show that agent $i$ is strictly better off with this deviation. %defined in \eqref{eq:deviation}.
First, note that we have:
\begin{align*}
\pe [ & \z_{i}(\b_{i}, \B_{-i}) \mid \B_{i} = \b_{i}] 
= \int \z_{i}(\b_{i},\b_{-i}) 
\cdot f_{\B_{-i} \mid \B_{i}} (\b_{-i} \mid \b_{i}) d \b_{-i} \\
&= \int \left[ \sum_{ \ k \in M; k \neq j} v_{ik} x_{ik}(\b_{i}, \b_{-i}) - \sens_{i} p_{ik}(\b_{i}, \b_{-i}) \right ] 
\cdot f_{\B_{-i} \mid \B_{i}} (\b_{-i} \mid \b_{i}) d \b_{-i} \\
&+ \int \left [ v_{ij} x_{ij}(\b_{i}, \b_{-i}) - \sens_{i} p_{ij}(\b_{i}, \b_{-i}) \right ] 
\cdot f_{\B_{-i} \mid \B_{i}} (\b_{-i} \mid \b_{i}) d \b_{-i}. 
\end{align*}
Next we have that:
\begin{align*}
\pe [ & \z_{i}(\swap(\b_{i}), \B_{-i}) \mid \B_{i} = \b_{i}] 
= \int \z_{i}(\swap(\b_{i}),\b_{-i}) 
\cdot f_{\B_{-i} \mid \B_{i}} (\b_{-i} \mid \b_{i}) d \b_{-i} \\
&=  \int  \left [   \sum_{\ k \in M; k \neq j}  v_{ik} x_{ik}(\b_{i}, \b_{-i}) - \sens_{i} p_{ik}(\b_{i}, \b_{-i}) \right ] 
\cdot   f_{\B_{-i} \mid \B_{i}} (\b_{-i} \mid \b_{i}) d \b_{-i}\\
&+ \int \left [ v_{ij} x_{ij}(\swap(\b_{i}), \b_{-i}) - \sens_{i} p_{ij}(\swap(\b_{i}), \b_{-i}) \right ] 
\cdot f_{\B_{-i} \mid \B_{i}} (\b_{-i} \mid \b_{i}) d \b_{-i},
\end{align*}
where the second equality follows by definition of the deviation. 
Subtracting the former conditional expectation from the latter leads to:
\begin{align}
\pe [ & \z_{i}(\swap(\b_{i}), \B_{-i}) \mid \B_{i} = \b_{i}] 
- \pe [\z_{i}(\b_{i}, \B_{-i}) \mid \B_{i} = \b_{i}]  \nonumber \\
= & \int \Big [ v_{ij} x_{ij}(\swap(\b_{i}), \b_{-i}) - \sens_{i} p_{ij}(\swap(\b_{i}), \b_{-i}) - v_{ij} x_{ij}(\b) + \sens_{i} p_{ij}(\b) \Big ] \nonumber \\
&\cdot f_{\B_{-i} \mid \B_{i}} (\b_{-i} \mid \b_{i}) d \vec{b}_{-i}. \label{eq:contradictionCE} 
\end{align}
Note that the expression in brackets in \eqref{eq:contradictionCE} evaluates to 0 for $\b_i$ with $b_{ij} \ge r_j$, as in that case $b'_{ij} = b_{ij}$.
Otherwise, if $b_{ij} < r_j$, then agent $i$ never wins auction $j$ under $\vec{b}_{i}$ and if agent $i$ wins auction $j$ under $(\swap(\b_{i}), \b_{-i})$, the expression evaluates to:
\[ 
v_{ij} x_{ij}(\swap(\b_{i}), \b_{-i}) - \sens_{i} p_{ij}(\swap(\b_{i}), \b_{-i}) 
= v_{ij} - \sens_{i} r_{j} > 0, 
\]
as $b'_{ij} = r_j < v_{ij}$ (reserve prices are feasible) and $\sigma_i \le 1$. 
Furthermore, it follows from \eqref{eq:PositivePrNotSold} that there is some positive probability that agent $i$ wins auction $j$ in this case. 
This leads to:
\begin{align*}
\pe [\z_{i}(\swap(\B_{i}), \B_{-i})] &= \pe \left [ \pe [\z_{i}(\swap(\b_{i}), \B_{-i}) \mid \B_{i} = \b_{i}] \right ] \\
&> \pe \left [ \pe [\z_{i}(\b_{i}, \B_{-i}) \mid \B_{i} = \b_{i}] \right ] = \pe [\z_{i}(\B)],
\end{align*}
contradicting that $\B$ is a CE. 
\end{proof}


It is no longer true that all equilibria are well-supported beyond correlated equilibria. 
Since we consider feasible reserve prices, this phenomenon is not due to reserve prices exceeding the agents' willingness to pay. 
Inspired by \cite{syrgkanis-thesis}, we show that already for a single first-price auction, there exist CCE for which the item is not always sold. 
Even though the rightful winner $i$ can ensure that the item is always sold, agent $i$ might have to pay more in some cases or even not win the item when deviating from the joint probability distribution, causing the gain of agent $i$ to not strictly improve.

\begin{lemma} \label{prop:CCEitemNotAlwaysSold}
Consider the class of simultaneous first-price auctions with additive valuations $\vec{v} \in \mathcal{V}_{\add}$ and feasible reserve prices. 
Then, there exist \cce\ that are not well-supported.
\end{lemma}

\begin{proof}{Proof}
Consider a single first-price auction with a feasible reserve price $r$ among 2 agents with values $v_1 =1$ and $v_2 =0$. Let $\sens_1 =1$. The type of agent 2 can be arbitrary.
Assume that ties are broken in favor of agent 1 and note that $r < 1$, as the reserve price is feasible. 
Let $X$ be a random variable with the following CDF and PDF:
\[
F_{X}(x) = \frac{1}{e} \cdot \frac{1- r}{1 - x}
\quad \text{and}\quad f_{X}(x) = \frac{1}{e} \cdot \frac{1- r}{(1 - x)^2}
\quad \text{with}\quad x \in \bigg[0, \frac{e - 1 + r}{e} \bigg].
\] 
Note that the domain is well-defined as $0 \le x < 1$, and it is easy to verify that $F_{X}(\cdot)$ is non-negative and increasing over the domain and $F_{X}( (e - 1 + r)/e ) = 1$.
Now consider the randomized bid profile $\B$ for which the agents always bid identically according to $X$, i.e., draw some value $x$ from $X$ and let both agents bid $x$. 
We prove that $\B$ is a CCE.

Since ties are broken in favor of agent 1, the expected gain of agent $2$ under $\B$ is $0$ and agent 2 satisfies the ROI constraint. Moreover, as $v_2 =0$, no unilateral deviation of agent 2 leads to a positive expected gain, and so agent 2 satisfies the equilibrium condition. 
Note that agent 1 satisfies the ROI constraint for $\B$ as $x \le (e -1 +r)/e < 1 = v_1$, so agent 1 never bids above $v_1$. 
As agent 1 does not win when bidding below the reserve price, the expected gain of agent $1$ is:
\[ \EX [ \z_1(\B)] = \int_{r}^{\frac{e - 1 + r}{e}}(1-x)f_{X}(x) d x = \frac{1- r }{e}\bigg[-\ln(1-x) \bigg]_{r}^{\frac{e - 1 + r}{e}} = \frac{1- r}{e}. \]
First, consider any deterministic unilateral deviation $\bsingle'_1$ of agent 1.
If $\bsingle'_1 \in [0, r)$, then agent 1 will never win the auction and always have a gain of $0$. 
Secondly, consider a bid $\bsingle'_1 \in [r, \frac{e - 1 + r}{e}]$. Let $B_{2} = \vec{B}_{-1}$, then:
\[ 
\EX [\z_1(\bsingle'_1,\Bsingle_{2})] = (1 - \bsingle'_1) F_{X}(\bsingle'_1) = (1 - \bsingle'_1) \frac{1- r }{e(1 - \bsingle'_1)} = \frac{1 - r }{e},
\]
where the first equality holds as agent $1$ wins and pays $\bsingle'_1$ if agent $2$ bids at most $b'_1$. Finally, if $\bsingle'_1 > \frac{e - 1 + r}{e}$, agent 1 always wins the auction but this leads to an expected gain of $1-b'_1$ that is strictly smaller than $\frac{1 - r}{e}$. Therefore, we can conclude that for any randomized unilateral deviation $Y$ with PDF $f_{Y}$ of agent 1 satisfying the ROI constraint, it holds that:
\[ \EX [ \z_1(Y, \Bsingle_2) ] = \int_{0}^{\infty} \EX [\z_1(y,\Bsingle_{2})] \cdot f_{Y}(y) d y  \le \int_{0}^{\infty} \frac{1 - r}{e} f_{Y}(y) d y = \frac{1 - r}{e}.
\]
Therefore, agent 1 also satisfies the equilibrium condition, proving that $\B$ is a CCE that is not well-supported.
Note that this holds for any feasible reserve price $r$. Additionally, for any reserve price $r>0$, the CCE $\B$ is not well-supported as in this case the probability that the item is not sold is greater than 0. 

Additionally, note that this can be extended to hold for any simultaneous first-price auction, i.e., $\fpar{m}{\vec{r}}$ with $m>1$, simply by considering $\B$ for an auction $j \in \{1, 2, \dots, m\}$ and letting the randomized bid profiles of the auctions $i\neq j$ be independent of $\B$.
\end{proof}


As the item is not always sold under the CCE $\B$ in the proof of Lemma \ref{prop:CCEitemNotAlwaysSold}, a lower bound on the POA can be implied. 
This results is stated below in Theorem \ref{lemma:LB-withReserve-not-all-items-sold} and shows that, for the homogeneous case of utility maximizers, the \cce-\poa\ of simultaneous first-price auctions \textit{with} feasible reserve prices is not better than that of simultaneous first-price auctions \textit{without} reserve prices.

\begin{theorem} \label{lemma:LB-withReserve-not-all-items-sold}
Consider the class of simultaneous first-price auctions with additive valuations $\vec{v} \in \mathcal{V}_{\add}$ and feasible reserve prices. 
Then, it holds that: 
\[\cce\text{-}\poa(\mathcal{V}_{\add}) \geq \frac{e}{e-1}.\]
\end{theorem}

\begin{proof}{Proof}
Consider the $\fpar{}{r}$ among two agents with feasible reserve price and the CCE $\B$ as in the proof of Lemma \ref{prop:CCEitemNotAlwaysSold}.
It is easy to see that the optimal liquid welfare in this instance is $1 = v_{\rw}$. 
The expected liquid welfare of $\B$ is $\pe[\sum_{i \in N} v_i(x_i(\B))] = \ppr[ X \ge r ] =  \frac{e-1}{e}$.
Therefore, $\cce\text{-}\poa \geq \frac{e}{e-1}$, concluding the proof.
\end{proof}

However, as shown in Theorem \ref{theorem:single-type}, the presence of feasible reserve prices does improve the POA when only considering well-supported CCE. The following result shows that this bound on the POA is even tight for all $\eta \in (0,1)$ in the case of homogeneous utility maximizers. 

\begin{theorem} \label{lemma:LB-BigTauSens-withReserve}
Consider the class of simultaneous first-price auctions with additive valuations $\vec{v} \in \mathcal{V}_{\add}$ and feasible reserve prices among a set of $N$ homogeneous agents with $\sens_i \geq \frac{e-1}{e - \eta}$ for all $ i\in N$.  
Then, for well-supported \cce, it holds that:
\[ \cce\text{-}\poa(\mathcal{V}_{\add}) \geq \frac{e}{e-1+\eta}.\]
\end{theorem}

\begin{proof}{Proof}
Consider a first-price auction with reserve price $r$ among $n = 2$ agents of the same type, i.e., $\sens := \sens_1 = \sens_2$.
Let $\vec{v} = (1, \eta)$, with $\eta \in [0,1)$, and let $\sens = \frac{e-1}{e - \eta}$. 
The feasible reserve price is $r = \eta < v_1$.
We assume that ties are broken in favor of agent $1$ for every bid profile $\vec{b} = (b, b)$ with $b > \eta$, and in favor of agent $2$ for $\vec{b} = (\eta, \eta)$.
Let $X$ be a random variable with the following CDF and PDF:
\[
F_X(x) = \frac{1}{e} \cdot \frac{1 - \sens \eta}{1-\sens x} \ \  \text{ and } \ \  f_X(x) = \frac{\sens}{e} \cdot \frac{1 - \sens \eta}{(1-\sens x)^{2}} \ \  \text{ with } \ \  x \in \left[\eta ,\frac{e-1 + \sens \eta}{e\sens}\right].
\]
Note that the domain is well-defined as $ x \ge 0$, and it is easy to verify that $F_{X}(\cdot)$ is non-negative and increasing over the domain and $F_{X}( (e - 1 + \sigma \eta)/ e \sigma ) = 1$.
Now consider the randomized bid profile $\B$ in which the agents always bid identically according to $X$, i.e., draw some value $x$ from $X$ and let both agents bid $x$. 
We prove that $\B$ is a CCE.

First, we verify that $\vec{B}$ satisfies the ROI constraints of the two agents. Note that this is trivially true for agent 2 as, by the tie-breaking rule, agent $2$ only wins the item for the bid profile $(\eta, \eta)$ and $\eta = v_2$.  
Note that $\vec{B} \in \mathcal{R}_1$ since:
\begin{equation*}
\EX [ p_1(\B)] \le \frac{e-1 + \sens \eta}{e\sens} \cdot \EX[x_1(\B)] \leq \EX [x_1(\B)] 
= \EX [v_1(x_1(\B))],
\end{equation*}
where the first inequality holds as agent 1 never bids above $\frac{e-1 + \sens\eta}{e\sens}$, while the second inequality holds by assumption.

Secondly, we show that no agent can improve by unilaterally deviating. 
First, note that under $\B$ agent 2 only wins when bidding bid $\eta$, and that the gain of agents 2 is non-negative in this case, i.e., $v_2 - \sens \eta = \eta(1- \sens) \ge 0$.
We consider deterministic deviations of agent 2.
Agent 2 would never win when bidding $b_2 < \eta = r$. 
If agent 2 wins when bidding $b_2 > \eta$, agent 2 violates their ROI constraint.
And if agents 2 wins when bidding $b_2 = \eta$, their ROI constraint is tight.
Therefore, agent 2 has no randomized unilateral deviation that is beneficial and satisfies the ROI constraint. 

As ties are broken in favor of agent $1$ for every bid profile $\vec{b} = (b, b)$ with $b > \eta$, the expected gain of agent $1$ under $\vec{B}$ is:
\begin{align*}
    \EX [\z_1(\B)] 
    &= \int_{\eta}^{\frac{e-1 + \sens \eta}{e \sens}} (1 - \sens x) f_{X}(x) d x
    = \int_{\eta}^{\frac{e-1 +\sens \eta}{e \sens}} \frac{\sens}{e} \frac{1 - \sens \eta}{1 - \sens x} d x \\
    &= \frac{1 - \sens \eta}{e} \bigg[ - \ln(1 - \sens x) \bigg]_{\eta }^{\frac{e-1 + \sens \eta}{e \sens}} = \frac{1 - \sens \eta}{e}.
\end{align*}
Consider a deterministic deviation $b_1'$ of agent $1$.
Clearly, $b_1' \le \eta$ leads to an expected gain of $\EX [\z_1(b'_1,X)] = 0$, as agent $2$ always wins the item at $(\eta,\eta)$. 
Moreover, note that bidding $b_1' > \frac{e-1 + \sens \eta}{e\sens}$ is not beneficial. In this case agent 1 would always win the item but:
\begin{equation*}
    \EX [\z_1(b'_1, X)] = 1 - \sens b'_1 < 1 - \sens \frac{e-1 + \sens \eta}{e\sens} = \frac{1 - \sens \eta}{e} = \EX [\z_1(\B) ].
\end{equation*}
Finally, consider $b_1' \in  (\eta, \frac{e-1 + \sens \eta}{e\sens}]$.
We obtain that:
\begin{equation*}
    \EX [\z_1(b'_1, X)] = \ppr [b'_1 \ge X] ( 1 - \sens b_1') = F_X(b'_1)(1-\sens b_1') = \frac{1 - \sens \eta}{e} = \EX [\z_1(\B)].
\end{equation*}
Therefore, we can conclude that for any randomized unilateral deviation $Y$ with PDF $f_{Y}$ of agent 1 satisfying the ROI constraint, it holds that:
\[ \EX [ \z_1(Y, X) ] = \int_{0}^{\infty} \EX [\z_1(y,X)] \cdot f_{Y}(y) d y  \le \int_{0}^{\infty} \frac{1 - \sens \eta}{e} f_{Y}(y) d y = \frac{1 - \sens \eta}{e},
\]
proving that $\vec{B}$ is a CCE.

We conclude the proof by showing how inefficient the CCE $\vec{B}$ is.
Clearly, the optimal liquid welfare is $v_1 = 1$, and therefore:
\begin{equation*}
    \cce\text{-}\poa \geq \frac{1}{\EX [v_1(x_1(\B)) + v_2(x_2(\B))]} = \frac{1}{1 - F_X(\eta) + \eta F_X(\eta) } = \frac{e}{e-1+ \eta}.
\end{equation*}
\end{proof}

Note that the lower bound on the POA for homogeneous agents in Theorem \ref{lemma:LB-BigTauSens-withReserve} holds for a certain range of $\eta$, depending on the sensitivity of the agents.
Given the sensitivity of the homogeneous agents, Figure \ref{fig:tradeoffOneType} shows the maximum value of $\eta$ for which the precondition of Theorem \ref{lemma:LB-BigTauSens-withReserve} is satisfied.
Note that Theorem \ref{lemma:LB-BigTauSens-withReserve} only holds for sensitivities greater than or equal to $\frac{e-1}{e}$.
If all agents are value maximizers, we can prove a lower bound on the POA of $2 - \eta$ for the whole range of $\eta$, matching the upper bound in Theorem \ref{theorem:single-type}.

