\subsubsection{Example: $G=S_3$ and $\TwoRep(\mathbb Z_{3}^{(1)}\rtimes \mathbb Z_{2}^{(0)})$ SSB Phases}
\label{sec:RepS3}

We now turn to the lattice construction of a particularly exotic gapped phase of matter. 
% 
In the landscape of gapped phases, one typically (almost always) encounters phases whose ground states are isomorphic to one another.
% 
At the most coarse level, this implies that each ground state has the same entanglement structure.
% 
In contrast, non-invertible symmetries\footnote{Specifically, non-condensation non-invertible 0-form symmetries.} can stabilize phases with qualitatively distinct vacua.
% 
The simplest such phase was studied in \cite{Bhardwaj:2025piv}.
% 
This phase is the fully spontaneously broken phase of the symmetry category corresponding to 2-representations of a 2-group $\mathbb G$ (i.e. $\TwoRep(\mathbb G)$) where
\begin{equation}
    \mathbb G=\mathbb Z_{3}^{(1)}\rtimes \mathbb Z_{2}^{(0)}\,.
\end{equation}
This symmetry category is related to the $S_3$ 0-form symmetry (i.e., $\TwoVec_{S_3}$) via gauging the non-normal subgroup $\Z_2< S_3$.
% 
We now briefly describe the $S_3$ model, focusing on a specific gapped phase that breaks the $\Z_3$ subgroup of $S_3$ spontaneously.
% 
We then perform a generalized gauging of the $S_3$ model to obtain the aforementioned gapped phase.
% 
Specifically, we perform both the minimal and non-minimal gauging of the $\Z_2 < S_3$.
% 



\paragraph{The $S_3$ Lattice Model.} Lattice models with $G$ 0-form symmetries and their associated gapped phases have been studied extensively in the literature.
% 
The most convenient construction is via $G$-qudits.
% 
This is equivalent to (an example of) the fusion surface model described in later sections.
% 
The state space is given by a tensor product of local Hilbert spaces $\mathbb C[S_3]$ assigned to each plaquette of the honeycomb lattice.
% 
A basis state in this Hilbert space is denoted by $|\{g_i\}\rangle$, where $g_i\in S_3$.
% 
We present $S_3$ as
\begin{equation}
    S_3=\langle a\,, b \ |\ a^3=b^2=1\,, bab=a^2 \rangle\,. 
\end{equation}
The $S_3$ symmetry acts as
\begin{equation}
U_g \ket{\{g_i\}} = \ket{\{gg_i\}}.
\end{equation}
%
Hamiltonians for various gapped phases with $\TwoVec_{G}$ symmetry will be constructed in Sec.~\ref{sec: Gapped phases with 2VecG symmetry}.
% 
We focus on the phase that breaks the $\Z_3$ subgroup of $S_3$, which corresponds to the choice
\begin{equation}
    B=\Vec_{\Z_2^b}\,,
\end{equation}
where $\mathbb{Z}_2^b = \{1, b\}$.
There are three ground states 
\begin{equation}
\begin{split}
    |{\rm GS}; \ell \rangle &= \frac{1}{2^{|P|/2}}\prod_{i}\sum_{g_i\in \mathsf M_\ell} |\{g_i\}\rangle\,,
\end{split}
\end{equation}
where $|P|$ is the number of plaquettes and $\mathsf M_0 =\{1,b\}$, 
{$\mathsf M_1 =\{a,ab\}$ and $\mathsf M_2 =\{a^2,a^2b\}$}.
% 
It can be readily checked that the $S_3$ symmetry acts on the ground state space as
\begin{equation}
\begin{split}
    U_{a}|{\rm GS};\ell \rangle &=    |{\rm GS};\ell +1 \ {\rm mod} \ 3 \rangle\,, \qquad 
   U_{b}|{\rm GS}; \{0,1,2\} \rangle=    |{\rm GS};\{0,2,1\} \rangle\,. \\ 
\end{split}
\label{eq: S3 action}
\end{equation}
In other words, the three ground states can be arranged on the corners of an equilateral triangle and $S_3$ acts naturally with $U_a$ implementing a $\Z_3$ rotation while $U_b$ implementing a reflection that leaves the vertex 0 fixed.

\paragraph{Gauging $\Z_2^b$ and the $\TwoRep(\mathbb Z_{3}^{(1)}\rtimes \mathbb Z_{2}^{(0)})$ Symmetric Model.} After gauging $\Z_2^b = \{1, b\}$, the degrees of freedom on the plaquettes are labelled as $g_i$ where $g_i \in S_{H \backslash G}$ is the representative of a right $H$-coset in $G$.
% 
For the present case, we have $G = S_3$ and $H = \mathbb{Z}_2^b$, and hence there are three right cosets {$\mathsf{M}^{\prime}_0 = \{1, b\}$, $\mathsf{M}^{\prime}_1 = \{a, ba\}$, and $\mathsf{M}^{\prime}_2 = \{a^2, ba^2\}$, for which we pick the representatives $S_{\mathbb{Z}_2^b \backslash S_3} = \{1, a, a^2\}$.} 
% 
The degrees of freedom on the plaquettes are unconstrained.
% 
On the other hand, as described in section~\ref{sec: Gapped Phases and Examples}, the degrees of freedom on the edges are labeled by elements in $\Z_2^b$. 
% 
% Next, we note that the vertical surface ending on the edge between two plaquettes with $a^{\ell_1}$ and $a^{\ell_2}$ as fixed representives need to be labeled by one of two group elements 
% \kinote{I thought we don't need to mention the ``vertical surfaces" because they do not appear in section~\ref{sec: Gapped Phases and Examples}. We could just say that the edge degrees of freedom are labeled by elements of $\mathbb{Z}_2^b$.}
% \begin{equation}
    % a^{\ell_2-\ell_1} \quad {\rm or} \quad a^{-\ell_1-\ell_2}b\,.
% \end{equation}
% Therefore there is a precisely two dimensional state space on each edge regardless of the coloring of plaquettes.
% 
The edge degrees of freedom should be interpreted as a $\Z_2$ gauge field
% , with the non-trivial field corresponding to the vertical surface $a^{-\ell_1-\ell_2}b$.
% 
which further needs to satisfy a flatness constraint on each vertex.
% 
The state space one thus obtains is naturally not tensor decomposable, however it admits a natural embedding into a larger Hilbert space 
\begin{equation}
    \cH_0 = \bigotimes_{i\in P}   \bC^3_i \otimes \bigotimes_{[kl]\in E} \bC^2_{[kl]} \,.
\end{equation}
One may define models on this state space that have non-topological 1-form symmetry \cite{Choi:2024rjm}.
In our model, however, we impose the flatness constraint kinematically at the level of the state space via the projector
\begin{equation}
    \cH_{\text{gauged}} = \widehat{\pi}_{\rm flat} \cH_0\,.
\end{equation}
As a result, the 1-form symmetry operators become topological.

Now, we write down the gauged Hamiltonian for the minimal gapped phase corresponding to $B = \Vec_{\mathbb{Z}_2^b}$.
% 
To this end, we define $\Z_3$ clock and shift operators $Z_{i}$ and $X_{i}$ on each plaquette that act on the computational basis as
\begin{equation}
    Z|a^{p}\rangle= \omega^{p} |a^{p}\rangle\,, \qquad 
X|a^{p}\rangle=  |a^{p+1 \bmod 3}\rangle\,,
\end{equation}
It will also be useful to define a ``charge conjugation" operator $\Gamma$ that acts as
\begin{equation}
    \Gamma |a^{p}\rangle = |a^{-p}\rangle\,.
\end{equation}
Similarly, on the two-dimensional state space associated to the edges of the lattice, we define the usual Pauli operators, which act as
\begin{equation}
\sigma^z \ket{b^q} = (-1)^q \ket{b^q}, \qquad 
\sigma^x \ket{b^q} = \ket{b^{q+1 \bmod 2}}.
\end{equation}
% 
The flatness constraint is then imposed via the projector 
\begin{equation}
    \widehat{\pi}_{\rm flat}=\prod_{[ijk]}\frac{1+\sigma^z_{ij}
    \sigma^z_{jk}\sigma^z_{ki}
    }{2}\,.
\end{equation}
The Hamiltonian on $\cH_{\text{gauged}}$ takes the form
\begin{equation}\label{eq: S3 gauged ham}
    H_{\text{gauged}}=-\sum_{[ij]}P_{ij}-\sum_{i}\frac{1+\Gamma_{i}B_{i}}{2}\,.
\end{equation}
Here $B_{i}$ is the operator that inserts a $\Z_2$ flux loop on the boundary of the plaquette labelled by $i$
\begin{equation}
    B_{i}=\prod_{j}\sigma_{ij}^x\,.
\end{equation}
%Meanwhile, $P_{ij}$ is the local projector that implements that the vertical surface in the fusion surface models attached to the edge $[ij]$ is valued in $\Z_2^{b}< S_3$.
Meanwhile, $P_{ij}$ is the local projector that implements the constraint that the qubit on $[ij]$ along with the qutrits on the two neighboring plaquettes $i$ and $j$ can only have one of the following six configurations:
\begin{equation}\label{eq: S3 constraint}
    (g_{i}\,, h_{ij}\,, g_{j}) \in \left\{(a^p,1,a^p)\,, (a^{p},b,a^{-p})\, \ | 
 \ p=0,1,2\right\}\,.
\end{equation}
% 
This projector has the concrete form
\begin{equation}
    P_{ij}=\sum_{t=\pm}\frac{1+t\sigma^z_{ij}}{2} \otimes \frac{1+Z_iZ_j^{-t}+Z^2_iZ_j^{-2t}}{3}\,.
\end{equation}

The Hamiltonian~\eqref{eq: S3 gauged ham} is a commuting projector Hamiltonian and therefore the ground states lie in the projected space.
The subspace projected by $P_{ij}$ for all edges $[ij]$ decomposes into the direct sum of two state spaces, which we will denote as $V_1$ and $V_{2}$.
% 
On $V_1$, we have $p=0$ in \eqref{eq: S3 constraint}, while on $V_2$, we have $p\neq 0$.
% 
Furthermore, since the dynamics generated by the term $\Gamma_{i}B_{i}$ do not mix $V_1$ and $V_2$, we may consider the Hamiltonians projected to these two spaces separately.
% 
On $V_1$, each plaquette degree of freedom is constrained to be $1$ on which $\Gamma_i$ acts trivially, therefore the Hamiltonian simply becomes
\begin{equation}\label{eq: H V1}
    H\Big|_{V_1}=-\sum_{i}\frac{1+B_i}{2}\,.
\end{equation}
This is nothing but the Toric Code Hamiltonian on a triangular lattice (dual to the honeycomb lattice).\footnote{Typically the Toric Code model is defined on an unconstrained Hilbert space on which the projector $\widehat{\pi}_{\rm flat}$ is imposed energetically. }
%Next, the plaquette state space on $V_2$ is two-dimensional spanned by states labeled as $a$ and $a^2$.
On the other hand, on $V_2$, the state space on each plaquette is two-dimensional, which is spanned by states labeled as $a$ and $a^2$.
% 
On this space, $\Gamma$ acts as the Pauli-$x$ operator exchanging $a$ and $a^2$.
% 
We denote the effective Pauli operators on the constrained space as $\widetilde{\sigma}^{\alpha}_i$.
% 
Therefore we obtain
\begin{equation}\label{eq: H V2}
    H\Big|_{V_2}=-\sum_{i}\frac{1+\widetilde{\sigma}^x_iB_i}{2}\,.
\end{equation}
This can be recognized as the symmetry enriched Levin Wen model which enriches the trivial topological order by a $\Z_2$ symmetry \cite{Heinrich:2016wld, Cheng:2016aag}.\footnote{More specifically, $H\Big|_{V_2}$ realizes the trivial SPT phase with $\mathbb{Z}_2$ symmetry.}
% 
At this point, stating this model as such seems an overkill but it makes the generalization to the non-minimal version of this phase manifest. 



\paragraph{Symmetry Action on the Ground States.}
The symmetry of the gauged model is described by $2\Rep(\mathbb Z_{3}^{(1)}\rtimes \mathbb Z_{2}^{(0)})$ \cite{Bhardwaj:2022maz}.
This symmetry 2-category has a unique non-condensation non-invertible object up to condensation.
The corresponding 0-form symmetry operator is given by $\mathsf{D}_{\mathbb{Z}_2^b} U_a \overline{\mathsf{D}}_{\mathbb{Z}_2^b}$, where $\mathsf{D}_{\mathbb{Z}_2^b}$ and $\overline{\mathsf{D}}_{\mathbb{Z}_2^b}$ are the gauging and ungauging operators defined by (cf. section~\ref{sec: Duality operators})
\begin{equation}
\mathsf{D}_{\mathbb{Z}_2^b} \ket{\{b^{n_i}a^{m_i}\}} = \ket{\{a^{m_i}, b^{-n_i + n_j}\}},
\end{equation}
\begin{equation}
\overline{\mathsf{D}}_{\mathbb{Z}_2^b} \ket{a^{m_i}, b^{n_{ij}}} = \sum_{\{n_i = 0, 1\}} \prod_{[ij] \in E} \delta_{n_{ij}, -n_i + n_j \bmod 2} \ket{\{b^{n_i} a^{m_i}\}}.
\end{equation}
See also \cite{Delcamp:2023kew} for the symmetry operators for $2\Rep(\mathbb Z_{3}^{(1)}\rtimes \mathbb Z_{2}^{(0)})$ symmetry.
In what follows, we will compute the action of this symmetry operator on the ground states.
In particular, we will see that the trivial and topologically ordered ground states of the gauged model are mixed by the action of the non-invertible symmetry.

To compute the symmetry action, let us first write down the ground states of the gauged model.
From \eqref{eq: GS min min}, we find that the ground states on an infinite plane are given, up to normalization, by
\begin{equation}
\ket{\text{GS}; 0}_{\text{gauged}} = \sum_{\{h_i \in \mathbb{Z}_2^b\}} \ket{\{1, h_i^{-1}h_j\}}, \qquad
\ket{\text{GS}; 1}_{\text{gauged}} = \sum_{\{h_i \in \mathbb{Z}_2^b\}} \ket{\{g(h_i), h_i^{-1} h_j\}}.
\end{equation}
Here, we defined
\begin{equation}
g(h_i) = 
\begin{cases}
a \qquad & \text{if $h_i = 1$}, \\
a^2 \qquad & \text{if $h_i = b$}.
\end{cases}
\end{equation}
We note that $\ket{\text{GS}; 0}_{\text{gauged}}$ is the ground state of the Toric Code Hamiltonian~\eqref{eq: H V1}, while $\ket{\text{GS}; 1}_{\text{gauged}}$ is the ground state of the trivial Hamiltonian~\eqref{eq: H V2}.
As such, we denote these ground states as
\begin{equation}
\ket{\text{GS}; 0}_{\text{gauged}} = \ket{\text{TC}}, \qquad \ket{\text{GS}; 1}_{\text{gauged}} = \ket{\text{triv}}.
\label{eq: TC triv}
\end{equation}
On the other hand, the ground states of the original $S_3$-symmetric model are given, up to normalization, by 
\begin{equation}
\ket{\text{GS}; \ell}_{\text{original}} = \sum_{\{g_i \in \mathsf{M}_{\ell}\}} \ket{\{g_i\}} \quad \text{for $\ell = 0, 1, 2$},
\end{equation}
where $\mathsf{M}_0 = \{1, b\}$, $\mathsf{M}_1 = \{a, ab\}$, and $\mathsf{M}_2 = \{a^2, a^2b\}$.
The $S_3$ symmetry acts on these ground states as in \eqref{eq: S3 action}.
We note that $\ket{\text{GS}; 0}_{\text{original}}$ preserves the $\mathbb{Z}_2^b$ symmetry, while the other two ground states spontaneously break the $\mathbb{Z}_2^b$ symmetry.

Now, we compute the action of the symmetry operator $\mathsf{D}_{\mathbb{Z}_2^b} U_a \overline{\mathsf{D}}_{\mathbb{Z}_2^b}$.
To this end, we note that gauging operator $\mathsf{D}_{\mathbb{Z}_2^b}$ acts on the ground states of the $S_3$-symmetric model as
\begin{equation}
\mathsf{D}_{\mathbb{Z}_2^b} \ket{\text{GS}; \ell}_{\text{original}} = 
\begin{cases}
\ket{\text{GS}; 0}_{\text{gauged}} \qquad \text{for $\ell = 0$}, \\
\ket{\text{GS}; 1}_{\text{gauged}} \qquad \text{for $\ell = 1, 2$}.
\end{cases}
\end{equation}
This means that the trivial $\Z_2^b$-invariant ground state is mapped to the Toric Code ground state, while the $\mathbb{Z}_2^b$-SSB ground states are mapped to the trivial ground state.
Similarly, the ungauging operator $\overline{\mathsf{D}}_{\mathbb{Z}_2^b}$ acts on the ground states of the gauged model as
\begin{equation}
\ba
\overline{\mathsf{D}}_{\mathbb{Z}_2^b} \ket{\text{GS}; 0}_{\text{gauged}} &= (1 + U_b) \ket{\text{GS}; 0}_{\text{original}} = 2 \ket{\text{GS}; 0}_{\text{original}} \cr 
\overline{\mathsf{D}}_{\mathbb{Z}_2^b} \ket{\text{GS}; 1}_{\text{gauged}} &= (1 + U_b) \ket{\text{GS}; 1}_{\text{original}} = \ket{\text{GS}; 1}_{\text{original}} + \ket{\text{GS}; 2}_{\text{original}}\,.
\ea
\end{equation}
That is, the Toric Code ground state is mapped to the trivial $\mathbb{Z}_2^b$-invariant ground state, while the trivial ground state is mapped to (the symmetric linear combination of) the $\mathbb{Z}_2^b$-SSB states.
Using the above equations, one can immediately compute the action of the non-invertible symmetry operator as
\begin{equation}
\ba
\mathsf{D}_{\mathbb{Z}_2^b} U_a \overline{\mathsf{D}}_{\mathbb{Z}_2^b} \ket{\text{GS}; 0}_{\text{gauged}} &= 2 \ket{\text{GS}; 1}_{\text{gauged}},
\cr 
\mathsf{D}_{\mathbb{Z}_2^b} U_a \overline{\mathsf{D}}_{\mathbb{Z}_2^b} \ket{\text{GS}; 1}_{\text{gauged}} &= \ket{\text{GS}; 0}_{\text{gauged}} + \ket{\text{GS}; 1}_{\text{gauged}}\,.
\ea\end{equation}
Recalling \eqref{eq: TC triv}, we find that the above non-invertible symmetry operator mixes the trivial ground state and the Toric Code ground state.


\paragraph{Non-Minimal Generalization.} Consider now a non-minimal gauging of the $S_3$ symmetric model.
% 
Specifically, we pick a fusion category $A=A_1\oplus A_b$ faithfully graded by $\Z_2^b<S_3$.
% 
Again, the degrees of freedom on the plaquettes are the representatives of right $\Z_2^b$-cosets in $S_3$, which we choose to be $\{1, a, a^2\}$.
% 
The degrees of freedom on the edges, however, are now upgraded from being $1$ or $b$, i.e., elements in $\Z_2^{b}$, to being objects in the graded components $A_1$ and $A_b$ respectively.
For simplicity, we assume that the fusion coefficients of $A$ are either zero or one.
% 
Then, there are no additional degrees of freedom on the vertices of the honeycomb lattice.
% 
However, there are constraints that impose the correct fusion rules on the vertices.
% 
The construction of the model is very analogous to the minimal case discussed above with the replacements 
\begin{equation}
    B_i \longrightarrow \sum_{x\in A_b^{\text{rev}}}\frac{d_{x}}{\mathcal{D}_{A_b}}\widehat{L}^{(x)}_i\,.
\end{equation}
Additionally, we need to impose the Levin-Wen constraint 
\begin{equation}\label{eq: S3 LW}
    \sum_{x\in A_1^{\text{rev}}}\frac{d_{x}}{\mathcal{D}_{A_1}}\widehat{L}^{(x)}_i =1 \quad \forall \ i\,.
\end{equation}
The Hamiltonian operators further impose that the low-energy state space only contains states with the following constrained structure:
any edge $[ij]$ along with its two neighboring plaquettes $i$ and $j$ can only have one of the following configurations
% \kinote{This constraint is imposed energetically in section~\ref{sec: Gapped Phases and Examples}, rather than exactly.}
\begin{equation}
    (g_{i}\,, x_{ij}\,, g_{j}) \in \left\{(a^p,x,a^p) \, \ | 
 \ x\in A_1\right\} 
 \ \sqcup \ 
 \left\{(a^p,x,a^{-p}) \, \ | 
 \ x\in A_b\right\}
 \,, \qquad
 p = 0, 1, 2.
\end{equation}
This low-energy state space decomposes into the direct sum of two state spaces, which we will denote as $V_1$ and $V_{2}$.
% 
Again, on $V_1$, $p=0$, while on $V_2$, $p\neq 0$.
% 
The Hamiltonian restricted to $V_1$ has the form
\begin{equation}
    H\Big|_{V_1}= - \frac{1}{2} \sum_{h\in \Z_2^{b}}\sum_{x\in A_h^{\text{rev}}}\frac{d_{x}}{\mathcal{D}_{A_h}}\widehat{L}^{(x)}_i\,.
\end{equation}
% \kinote{I thought it might be good to include $-\sum_{x \in A_1^{\text{rev}}} \frac{d_{x}}{\mathcal{D}_{A_1}}\widehat{L}^{(x)}_i$ on the RHS, although it's trivial, because otherwise the Hamiltonian does not look like the Levin-Wen Hamiltonian (superficially).}
This corresponds to the Levin-Wen model built from the fusion category $A^{\text{rev}}$ as input and describes the $\cZ(A^{\text{rev}})$ topological order.
% 
%It describes the $\Z_2$ gauging of the $\cZ(A_1)$ topological order.
% 
Meanwhile, the Hamiltonian restricted to $V_2$ has the form 
\begin{equation}
    H\Big|_{V_2}= - \frac{1}{2} \sum_{x\in A_1^{\text{rev}}}\frac{d_{x}}{\mathcal{D}_{A_1}}\widehat{L}^{(x)}_i - \frac{1}{2} \sum_{x\in A_b^{\text{rev}}}\frac{d_{x}}{\mathcal{D}_{A_b}}\widetilde{\sigma}^x_i\widehat{L}^{(x)}_i\,.
\end{equation}
This describes a $\Z_2$ enrichment of the topological order $\cZ(A_1^{\text{rev}})$ \cite{Heinrich:2016wld, Cheng:2016aag}. 
We note that the topological order realized by $H\Big|_{V_1}$ is the $\mathbb{Z}_2$-gauging of the topological order realized by $H\Big|_{V_2}$.


\subsection{Tensor Network Representation}
\label{sec: Summary of Tensor Network}

In this subsection, we provide tensor network representations of the generalized gauging operators and the gapped ground states discussed in the previous subsections.
We refer the reader to section~\ref{sec: Tensor network} for a brief review of tensor networks.
Throughout the paper, we will employ the following color convention for tensor networks:
\begin{itemize}
\item Physical legs are written in black, while virtual bonds are written in different colors:
\item A green virtual bond is labeled by an element of $H$.
\item A blue virtual bond is labeled by an element of $K$.
\item A red virtual bond is labeled by a simple object of $A^{\text{rev}}$.
\item An orange virtual bond is labeled by a simple object of $B$.
\end{itemize}
The labels of the physical legs depend on the case under consideration.
However, the following rules are common in all cases:
\begin{itemize}
\item The physical leg above each plaquette is labeled by an element of $S_{H \backslash G}$.
\item The physical leg below each plaquette is labeled by an element of $G$.
\end{itemize}
For simplicity, we will focus on the case where $G$ is non-anomalous for the moment.
See sections~\ref{sec: TN D omega}, \ref{sec: TN min GS}, and \ref{sec: TN non-min GS} for the case of anomalous $G$.

\subsubsection{Generalized Gauging Operators}
\paragraph{Minimal Gauging.}
As we discussed in section~\ref{sec: Generalized Gauging Operators summary}, the generalized gauging operator for the minimal gauging $A = \Vec_H^{\nu}$ is given by
\begin{equation}
\mathsf{D}_A \ket{\{h_ig_i\}} = \prod_{[ijk] \in V} \nu(h_i, h_i^{-1}h_j, h_j^{-1}h_k)^{-s_{ijk}} \ket{\{g_i, h_i^{-1}h_j\}},
\end{equation}
where $h_i \in H$ and $g_i \in S_{H \backslash G}$.
The above operator can be represented by the following tensor network:
\begin{equation}
\mathsf{D}_A = \adjincludegraphics[valign = c, width = 3cm]{fig/DA_min.pdf}.
\label{eq: DA minimal TN}
\end{equation}
Here, the physical leg on each edge is labeled by an element of $H$.
The non-zero components of the local tensors are defined by
\begin{equation}
\adjincludegraphics[valign = c, width = 1.75cm]{fig/DA_min_P.pdf} = 1, \qquad
\adjincludegraphics[valign = c, width = 1.5cm]{fig/DA_min_E.pdf} = 1,
\end{equation}
\begin{equation}
\adjincludegraphics[valign = c, width = 2.75cm]{fig/DA_min_VA.pdf} = \nu(h_i, h_i^{-1}h_j, h_j^{-1}h_k)^{-1}, \qquad
\adjincludegraphics[valign = c, width = 2.75cm]{fig/DA_min_VB.pdf} = \nu(h_i, h_i^{-1}h_j, h_j^{-1}h_k),
\label{eq: DA minimal TN vertex}
\end{equation}
where $h \in H$ and $g \in S_{H \backslash G}$.
A tensor network representation of the ungauging operator~\eqref{eq: min DA bar}
