\includegraphics[width = 4cm]{fig/morphisms_op2.pdf}
\caption{A 1-morphism from $M^{g_i} \vartriangleleft D_2^{g_{ij}^h}$ to $M^{g_j}$ is labeled by an object $a_{ij} \in A_{h^{ij}}^{\text{op}}$. A 2-morphism sitting at the junction of four 1-morphisms $a_{ij}$, $a_{jk}$, $a_{ik}$, and $1_{g_{ij}^h \cdot g_{jk}^h}$ is labeled by a morphism $\alpha_{ijk}^{\text{op}} \in \Hom_{A^{\text{op}}}(a_{jk} \otimes^{\text{op}} a_{ij}, a_{ik}) = \Hom_A(a_{ij} \otimes a_{jk}, a_{ik})$ or $\overline{\alpha}_{ijk}^{\text{op}} \in \Hom_{A^{\text{op}}}(a_{ik}, a_{jk} \otimes^{\text{op}} a_{ij}) = \Hom_A(a_{ik}, a_{ij} \otimes a_{jk})$. The dotted lines in the diagrams are labeled by the identity 1-morphism $1_{g_{ij}^h \cdot g_{jk}^h}$.}
