\paragraph{Module 10-j Symbols.}
The module 10-j symbols of the $2\Vec_G$-module 2-category ${}_A (2\Vec_G)$ are given by the $F$-symbols of $A^{\text{op}}$, i.e.,
\begin{equation}
\boxed{
\begin{aligned}
\adjincludegraphics[valign = c, width = 4cm]{fig/10j_op1.pdf} &= \sum_{a_{jl}} \sum_{\alpha_{jkl}^{\text{op}}} \sum_{\alpha_{ijl}^{\text{op}}} (F^{\text{op}})_{ijkl}^{a; \alpha} \adjincludegraphics[valign = c, width = 4cm]{fig/10j_op2.pdf}, \\[10pt]
\adjincludegraphics[valign = c, width = 4cm]{fig/10j_op3.pdf} &= \sum_{a_{jl}} \sum_{\alpha_{jkl}^{\text{op}}} \sum_{\alpha_{ijl}^{\text{op}}} (\overline{F}^{\text{op}})_{ijkl}^{a; \alpha} \adjincludegraphics[valign = c, width = 4cm]{fig/10j_op4.pdf},
\end{aligned}
}
\label{eq: module 10-j A2VecG 1}
\end{equation}
where $a_{ij} \in A^{\text{op}}$, $\alpha_{ijk}^{\text{op}} \in \Hom_{A^{\text{op}}}(a_{jk} \otimes^{\text{op}} a_{ij}, a_{ik})$, etc.
The $F$-symbol $F^{\text{op}}$ of the opposite category $A^{\text{op}}$ is related to the $F$-symbol of $A$ as follows:
\begin{equation}
(F^{\text{op}})_{ijkl}^{a; \alpha} := ((F^{\text{op}})^{a_{kl} a_{jk} a_{ij}}_{a_{il}})_{(a_{jl}; \alpha_{jkl}^{\text{op}}, \alpha_{ijl}^{\text{op}}), (a_{il}; \alpha_{jkl}^{\text{op}}, \alpha_{ijk}^{\text{op}})} = \overline{F}_{ijkl}^{a; \alpha}.
\end{equation}
Here, $\alpha_{ijk}^{\text{op}}$ is equal to $\alpha_{ijk}$ as an element of $\Hom_{A^{\text{op}}}(a_{jk} \otimes^{\text{op}} a_{ij}, a_{ik}) = \Hom_A(a_{ij} \otimes a_{jk}, a_{ik})$.

Similarly, we also have
\begin{equation}
\boxed{
\begin{aligned}
\adjincludegraphics[valign = c, width = 4cm]{fig/10j_rev1.pdf} &= \sum_{a_{jl}} \sum_{\alpha_{jkl}^{\text{rev}}} \sum_{\alpha_{ijl}^{\text{rev}}} (\overline{F}^{\text{rev}})_{ijkl}^{a; \alpha} \adjincludegraphics[valign = c, width = 4cm]{fig/10j_rev2.pdf}, \\[10pt]
\adjincludegraphics[valign = c, width = 4cm]{fig/10j_rev3.pdf} &= \sum_{a_{jl}} \sum_{\alpha_{jkl}^{\text{rev}}} \sum_{\alpha_{ijl}^{\text{rev}}} (F^{\text{rev}})_{ijkl}^{a; \alpha} \adjincludegraphics[valign = c, width = 4cm]{fig/10j_rev4.pdf}.
\end{aligned}
}
\label{eq: module 10-j A2VecG 3}
\end{equation}
where $a_{ij} \in A^{\text{rev}}$, $\alpha_{ijk}^{\text{rev}} \in \Hom_{A^{\text{rev}}}(a_{ij} \otimes a_{jk}, a_{ik})$, etc.
The $F$-symbols $F^{\text{rev}}$ of the reverse category $A^{\text{rev}}$ is related to the $F$-symbol of $A$ as follows:
\begin{equation}
(F^{\text{rev}})_{ijkl}^{a; \alpha} := ((F^{\text{rev}})^{a_{ij} a_{jk} a_{kl}}_{a_{il}})_{(a_{ik}; \alpha_{ijk}^{\text{rev}}, \alpha_{ikl}^{\text{rev}}), (a_{jl}; \alpha_{ijl}^{\text{rev}}, \alpha_{jkl}^{\text{rev}})} = \overline{F}_{ijkl}^{a; \alpha}.
\end{equation}
Here, $\alpha_{ijk}^{\text{rev}}$ is equal to $\overline{\alpha}_{ijk}$ as an element of $\Hom_{A^{\text{rev}}}(a_{ij} \otimes a_{jk}, a_{ik}) = \Hom_A(a_{ik}, a_{ij} \otimes a_{jk})$.


\paragraph{Underlying Objects and Morphisms.}
Since ${}_A (2\Vec_G)$ is a sub-2-category of $2\Vec_G$, objects and morphisms of ${}_A (2\Vec_G)$ have the underlying objects and morphisms in $2\Vec_G$.
The underlying object of $M^g \in {}_A (2\Vec_G)$ is given by
\begin{equation}
M^g = A \square D_2^g = \bigoplus_{h \in H} \bigoplus_{a_h \in A_h} D_2^h[a_h] \square D_2^g = \bigoplus_{h \in H} \bigoplus_{a_h \in A_h} D_2^{hg}[a_h].
\label{eq: underlying Mg}
\end{equation}
Here, we defined $D_2^{hg}[a_h] := D_2^h[a_h] \square D_2^g$, where $D_2^h[a_h]$ is the direct sum component of $A \in 2\Vec_G$ labeled by a simple object $a_h \in A_h$ (cf. section~\ref{sec: Separable algebras in 2VecG}).

The underlying 1-morphism of $a_{ij} \in \Hom_{{}_A (2\Vec_G)}(M^{g_i} \vartriangleleft D_2^{g_{ij}^h}, M^{g_j}) \cong A_{h_{ij}}^{\text{op}}$ is given by
\begin{equation}
\adjincludegraphics[valign = c, width = 5cm]{fig/under_1mor_op.pdf} = 1_{h_i g_i \cdot g_{ij}^h}^{\oplus n_{ij}},
\label{eq: underlying a op}
\end{equation}
where $n_{ij} := \dim(\Hom_{A^{\text{op}}}(a_j \otimes^{\text{op}} \overline{a_i}, a_{ij}))$, $a_i \in A_{h_i}$, and $a_j \in A_{h_j}$.
We note that $n_{ij} = 0$ unless $h_{ij} = h_i^{-1} h_j$.
The above equation implies that each component of the underlying 1-morphism is associated with a basis morphism $\alpha_{ij}^{\text{op}} \in \Hom_{A^{\text{op}}}(a_j \otimes^{\text{op}} \overline{a_i}, a_{ij})$.
Similarly, the underlying 1-morphism of $a_{ij} \in \Hom_{{}_A(2\Vec_G)}(M^{g_j}, M^{g_i} \vartriangleleft D_2^{g_{ij}^h}) \cong A_{h_{ij}}^{\text{rev}}$ is given by
\begin{equation}
\adjincludegraphics[valign = c, width = 5cm]{fig/under_1mor_rev.pdf} = \overline{1}_{h_i g_i \cdot g_{ij}^h}^{\oplus m_{ij}},
\label{eq: underlying a rev}
\end{equation}
where $m_{ij} := \dim(\Hom_{A^{\text{rev}}}(\overline{a_i} \otimes a_j, a_{ij}))$.
The above equation implies that each component of the underlying 1-morphism is associated with a basis morphism $\alpha_{ij}^{\text{rev}} \in \Hom_{A^{\text{rev}}}(\overline{a_i} \otimes a_j, a_{ij})$.

The underlying 2-morphisms of $\alpha_{ijk}^{\text{op}}$ and $\overline{\alpha}_{ijk}^{\text{op}}$ in figure~\ref{fig: 1-mor A2VecG 1} are given component-wise as
\begin{equation}
\begin{aligned}
\adjincludegraphics[valign = c, width = 5cm]{fig/under_2mor_op1.pdf} &= \left( \frac{d^a_{ij} d^a_{jk}}{d^a_{ik}} \right)^{\frac{1}{4}} F_{ijk}^{a; \alpha} ~ \adjincludegraphics[valign = c, width = 3.5cm]{fig/under_2mor_op2.pdf}, \\
\adjincludegraphics[valign = c, width = 5cm]{fig/under_2mor_op3.pdf} &= \left( \frac{d^a_{ij} d^a_{jk}}{d^a_{ik}} \right)^{\frac{1}{4}} \overline{F}_{ijk}^{a; \alpha} ~ \adjincludegraphics[valign = c, width = 3.5cm]{fig/under_2mor_op4.pdf},
\end{aligned}
\label{eq: underlying alpha op}
\end{equation}
where $F_{ijk}^{a; \alpha}$ is defined by
\begin{equation}
F_{ijk}^{a; \alpha} := (F^{a_i a_{ij} a_{jk}}_{a_k})_{(a_j; \alpha_{ij}, \alpha_{jk}), (a_{ik}; \alpha_{ik}, \alpha_{ijk})}.
\end{equation}
The 1-morphism labeled by $\alpha_{ij}^{\text{op}}$ in \eqref{eq: underlying alpha op} represents a component of the 1-morphism $a_{ij}$ in \eqref{eq: underlying a op}.
Similarly, the underlying 2-morphisms of $\alpha_{ijk}^{\text{rev}}$ and $\overline{\alpha}_{ijk}^{\text{rev}}$ in figure~\ref{fig: 1-mor A2VecG 2} are given by
\begin{equation}
\begin{aligned}
\adjincludegraphics[valign = c, width = 5.5cm]{fig/under_2mor_rev1.pdf} &= \left( \frac{d^a_{ij} d^a_{jk}}{d^a_{ik}} \right)^{\frac{1}{4}} \overline{F}_{ijk}^{a; \alpha} ~ \adjincludegraphics[valign = c, width = 3.5cm]{fig/under_2mor_rev2.pdf} \\
\adjincludegraphics[valign = c, width = 5.5cm]{fig/under_2mor_rev3.pdf} &= \left( \frac{d^a_{ij} d^a_{jk}}{d^a_{ik}} \right)^{\frac{1}{4}} F_{ijk}^{a; \alpha} ~ \adjincludegraphics[valign = c, width = 3.5cm]{fig/under_2mor_rev4.pdf}
\label{eq: underlying alpha rev}
\end{aligned}
\end{equation}
In the above equations, the factor of $(d^a_{ij} d^a_{jk} / d^a_{ik})^{\frac{1}{4}}$ is necessary so that \eqref{eq: normalization alpha} holds.
One can check that the above 2-morphisms are indeed 2-morphisms in ${}_A(2\Vec_G)$, i.e., they are compatible with the $A$-module structures, see appendix~\ref{sec: Underlying morphisms}.
Equations~\eqref{eq: underlying alpha op} and \eqref{eq: underlying alpha rev}, together with the pentagon equation, guarantee that the module 10-j symbols of ${}_A (2\Vec_G)$ are given by the $F$-symbols of $A$ as in \eqref{eq: module 10-j A2VecG 1} and \eqref{eq: module 10-j A2VecG 3}.



\subsection{Generalized Gauging on the Lattice}
\label{sec: Generalized gauging on the lattice 2VecG}
In this subsection, we discuss the generalized gauging of $2\Vec_G$ symmetry in the fusion surface model.
As discussed in section~\ref{sec: Generalized gauging}, the generalized gauging of symmetry $\mathcal{C}$ is specified by a right $\mathcal{C}$-module 2-category $\mathcal{M} \cong {}_A \mathcal{C}$, where $A$ is a separable algebra in $\mathcal{C}$.
When $\mathcal{C} = 2\Vec_G$, a separable algebra $A$ is a $G$-graded multifusion category, see section~\ref{sec: Separable algebras in 2VecG}.
In what follows, we will consider the generalized gauging of $2\Vec_G$ symmetry with $A$ being a $G$-graded unitary fusion category.


\subsubsection{$2\Vec_G$-Symmetric Model}
We begin with the fusion surface model with $2\Vec_G$ symmetry.
The input fusion 2-category $\mathcal{C}$ and the module 2-category $\mathcal{M}$ are
\begin{equation}
\mathcal{C} = \mathcal{M} = 2\Vec_G.
\end{equation}

\paragraph{State Space.}
To define the state space, we fix the input data $(\rho, \sigma, \lambda; f, g)$, cf. section~\ref{sec: Fusion surface model}.
For simplicity, we suppose
\begin{equation}
\rho = \sigma = \lambda, \quad f = g.
\label{eq: isotropic}
\end{equation}
Furthermore, for concreteness, we choose $\rho$ to be the direct sum of all simple objects with multiplicity one:
\begin{equation}
\rho = \bigoplus_{g \in G} D_2^g.
\label{eq: rho A2VecG}
\end{equation}
Similarly, we choose $f$ to be the direct sum of the identity 1-morphisms for all possible fusion channels, i.e., $f$ is given component-wise as
\begin{equation}
\adjincludegraphics[valign = c, width = 3.5cm]{fig/f.pdf} = \delta_{g_1g_2, g_3} 1_{g_1 \cdot g_2}.
\label{eq: f A2VecG}
\end{equation}
For the above choice of the input data, the dynamical variables of the model can be described as follows:
\begin{itemize}
\item The dynamical variables on the plaquettes are labeled by elements of $G$. The configurations of these dynamical variables can be arbitrary because $\rho$ contains all simple objects.
\item There are no dynamical variables on the edges and vertices.
\end{itemize}
The Levin-Wen plaquette operator~\eqref{eq: LW general} is the identity because $\End_{2\Vec_G}(D_2^g) \cong \Vec$ for all $g \in G$.
Therefore, the state space of the model is given by the space of all possible configurations of the dynamical variables, which we denote by
\begin{equation}
\mathcal{H}_{\text{original}} = \bigotimes_{i \in P} \mathbb{C}^{|G|}.
\end{equation}
Each state in $\mathcal{H}_{\text{original}}$ will be written as
\begin{equation}
\ket{\{g_i\}} = \Ket{\adjincludegraphics[valign = c, width = 2.5cm]{fig/original_state.pdf}}.
\end{equation}
The generalization to other choices of $\rho$ and $f$ is straightforward.\footnote{Some cases with a more general choice of $\rho$ and $f$ will be studied in section~\ref{sec: Gapped phases}.}

\paragraph{Hamiltonian.}
The Hamiltonian of the original model is given by
\begin{equation}
H_{\text{original}} = - \sum_{i \in P} \widehat{\mathsf{h}}_i,
\end{equation}
where the local term $\widehat{\mathsf{h}}_i$ is defined by the following fusion diagram:
\begin{equation}
\widehat{\mathsf{h}}_i ~\adjincludegraphics[valign = c, width = 6cm]{fig/original_ham.pdf} = \adjincludegraphics[valign = c, width = 6cm]{fig/gauged_ham2.pdf}.
\end{equation}
Here, $X_{45}$ is an object of $2\Vec_G$, $\{x_{145}, x_{245}, x_{345}, x_{456}, x_{457}, x_{458}\}$ are 1-morphisms of $2\Vec_G$, and $\{\chi_{1245}, \chi_{2456}, \chi_{4568}, \overline{\chi}_{1345}, \overline{\chi}_{3457}, \overline{\chi}_{4578}\}$ are 2-morphisms of $2\Vec_G$.
For simplicity, we choose $X_{45}$ to be the direct sum of all simple objects with multiplicity one, i.e.,
\begin{equation}
X_{45} = \bigoplus_{g \in G} D_2^g.
\label{eq: X45 A2VecG}
\end{equation}
Furthermore, we choose the 1-morphisms $x_{i45}: \rho \square X_{45} \to \rho$ and $x_{45j}: X_{45} \square \rho \to \rho$ to be the direct sum of the identity 1-morphisms, which is given component-wise as
\begin{equation}
\adjincludegraphics[valign = c, width = 4.25cm]{fig/x_i45_G.pdf} ~ = \delta_{g_{i4}g_{45}, g_{i5}} 1_{g_{i4} \cdot g_{45}}, 
\end{equation}
\begin{equation}
\adjincludegraphics[valign = c, width = 4cm]{fig/x_45j_G.pdf} ~ = \delta_{g_{45} g_{5j}, g_{4j}} 1_{g_{45} \cdot g_{5j}}.
\end{equation}
Finally, the 2-morphisms $\chi_{ijkl}$ and $\overline{\chi}_{ijkl}$ are defined component-wise as
\begin{equation}
\adjincludegraphics[valign = c, width = 3.5cm]{fig/chi_ijkl_G1.pdf} = \chi_{ijkl}(g_{ij}, g_{jk}, g_{kl}) \adjincludegraphics[valign = c, width = 3.5cm]{fig/chi_ijkl_G2.pdf},
\end{equation}
\begin{equation}
\adjincludegraphics[valign = c, width = 3.5cm]{fig/chi_bar_ijkl_G1.pdf} = \overline{\chi}_{ijkl}(g_{ij}, g_{jk}, g_{kl}) \adjincludegraphics[valign = c, width = 3.5cm]{fig/chi_bar_ijkl_G2.pdf},
\label{eq: chi A2VecG}
\end{equation}
where $\chi_{ijkl}(g_{ij}, g_{jk}, g_{kl})$ and $\overline{\chi}_{ijkl}(g_{ij}, g_{jk}, g_{kl})$ are arbitrary complex numbers.\footnote{We note that $\chi_{ijkl}$ and $\overline{\chi}_{ijkl}$ are independent functions.}
These complex numbers will be abbreviated as
\begin{equation}
\chi_{ijkl}^g := \chi_{ijkl}(g_{ij}, g_{jk}, g_{kl}), \quad \overline{\chi}_{ijkl}^g = \overline{\chi}_{ijkl}(g_{ij}, g_{jk}, g_{kl}).
\label{eq: chi chi bar}
\end{equation}
For the above choice of $(X, x, \chi)$, the action of $\widehat{\mathsf{h}}_i$ can be computed as
\begin{equation}
\widehat{\mathsf{h}}_i \Ket{\adjincludegraphics[valign = c, width = 2.5cm]{fig/initial_state_G.pdf}} = \sum_{g_{45} \in G} \chi_{1245}^g \chi_{2456}^g \chi_{4568}^g \overline{\chi}_{1345}^g \overline{\chi}_{3457}^g \overline{\chi}_{4578}^g \Ket{\adjincludegraphics[valign = c, width = 2.5cm]{fig/final_state_G.pdf}},
\label{eq: local Ham G}
\end{equation}
where $g_{ij}$ in $\chi_{ijkl}$ and $\overline{\chi}_{ijkl}$ is defiined by $g_{ij} := g_i^{-1} g_j$.
The generalization to a more general choice of $(X, x, \chi)$ is straightforward.

\paragraph{Symmetry.}
The above model has $2\Vec_G$ symmetry by construction.
The symmetry operator for $D_2^g \in 2\Vec_G$ is given by the left multiplication of $g \in G$:
\begin{equation}
U_g \ket{\{g_i\}} = \ket{\{gg_i\}}.
\end{equation}
It immediately follows from \eqref{eq: local Ham G} that $U_g$ commutes with the Hamiltonian $H_{\text{original}}$.



\subsubsection{Gauged Model}
\label{sec: non-minimal gauging of 2VecG}
We now describe the gauged fusion surface model.
The input fusion 2-category $\mathcal{C}$ and the module 2-category $\mathcal{M}$ are
\begin{equation}
\mathcal{C} = 2\Vec_G, \qquad \mathcal{M} = {}_A (2\Vec_G),
\end{equation}
where $A$ is a $G$-graded unitary fusion category faithfully graded by $H \subset G$.
The gauging procedure is called minimal gauging when $A = \Vec_H^{\nu}$, and non-minimal gauging otherwise.

\paragraph{State Space.}
We choose the input data $(\rho, \sigma, \lambda; f, g)$ to be the same as those in the original model, see \eqref{eq: isotropic}--\eqref{eq: f A2VecG}.
In this case, possible configurations of dynamical variables of the gauged model can be described as follows:
\begin{itemize}
\item The dynamical variables on the plaquettes are labeled by the representatives of connected components of ${}_A (2\Vec_G)$.
As discussed in section~\ref{sec: Module 2-categories over 2VecG}, the representative of each connected component is given by $M^{g_i} = A \square D_2^{g_i}$, where $g_i \in S_{H \backslash G}$ is the representative of a right $H$-coset in $G$.
A configuration of these dynamical variables is denoted by $\{g_i \mid i \in P\}$.\footnote{We recall that $P$ denotes the set of all plaquettes of the honeycomb lattice. Similarly, the set of all edges is denoted by $E$, while the set of all vertices is denoted by $V$.}
There is no constraint on this configuration because $\rho$ contains all simple objects.
\item For a given configuration $\{g_i \mid i \in P\}$, the vertical surface below edge $[ij]$ must be labeled by a group element of the form $g_{ij}^h = g_i^{-1}h_{ij}g_j$, where $h_{ij}$ is an arbitrary element of $H$. When the vertical surface is labeled by $g_{ij}^h$, the dynamical variable on edge $[ij]$ takes values in the set of simple objects of
\begin{equation}
\Hom_{2\Vec_G}(M^{g_i} \vartriangleleft D_2^{g_{ij}^h}, M^{g_j}) \cong A_{h_{ij}}^{\text{op}}.
\end{equation}
Since $h_{ij} \in H$ is arbitrary, this dynamical variable can actually take values in the set of all simple objects of $A^{\text{op}} = \bigoplus_{h \in H} A_h^{\text{op}}$ for any configuration $\{g_i \mid i \in P\}$. A configuration of the dynamical variables on the plaquettes and edges is denoted by $\{g_i, a_{ij} \mid i \in P,~ [ij] \in E\}$, where $a_{ij} \in A^{\text{op}}$.
\item For a given configuration $\{g_i, a_{ij} \mid i \in P,~ [ij] \in E\}$, the dynamical variable on vertex $[ijk]$ takes values in the vector space $\Hom_{A^{\text{op}}}(a_{jk} \otimes^{\text{op}} a_{ij}, a_{ik})$ or $\Hom_{A^{\text{op}}}(a_{ik}, a_{jk} \otimes^{\text{op}} a_{ij})$ depending on whether $[ijk]$ is in the $A$-sublattice or $B$-sublattice. A configuration of the dynamical variables on the plaquettes, edges, and vertices is denoted by
\begin{equation}
\{g_i, a_{ij}, \alpha_{ijk} \mid i \in P,~ [ij] \in E,~ [ijk] \in V\}.
\label{eq: gauged config}
\end{equation}
\end{itemize}
Pictorially, the state corresponding to the above configuration can be written as
\begin{equation}
\ket{\{g_i, a_{ij}, \alpha_{ijk}\}} := \Ket{\adjincludegraphics[valign = c, width = 3.5cm]{fig/gauged_state_op.pdf}},
\label{eq: state in A2VecG}
\end{equation}
where the vertices are labeled by $\alpha_{ijk}^{\text{op}}$, $\overline{\alpha}_{jkl}^{\text{op}}$, etc.
The labels on the vertices will often be omitted to avoid cluttering the diagram.

The state space of the gauged model is given by
\begin{equation}
\mathcal{H}_{\text{gauged}} = \widehat{\pi}_{\text{LW}} \mathcal{H}_{\text{gauged}}^{\prime},
\end{equation}
where $\mathcal{H}_{\text{gauged}}^{\prime}$ is the space of all possible configurations~\eqref{eq: gauged config} and $\widehat{\pi}_{\text{LW}} = \prod_{i \in P} \widehat{B}_i$ is the product of the Levin-Wen plaquette operators defined by
\begin{equation}
\widehat{B}_i ~ \Ket{\adjincludegraphics[valign = c, width = 3cm]{fig/gauged_LW1.pdf}} = \sum_{a \in A_e^{\text{op}}} \frac{\dim(a)}{\mathcal{D}_{A_e}} \Ket{\adjincludegraphics[valign = c, width = 3cm]{fig/gauged_LW2.pdf}}.
\label{eq: LW A2VecG}
\end{equation}
The inside and outside of the loop on the right-hand side are both labeled by $M^{g_i}$.

\paragraph{Hamiltonian.}
The Hamiltonian is given by the sum of local operators
\begin{equation}
H_{\text{gauged}} = - \sum_{i \in P} \widehat{\mathsf{h}}_i,
\end{equation}
where $\widehat{\mathsf{h}}_i$ is represented by the following fusion diagram:
\begin{equation}
\widehat{\mathsf{h}}_i ~\adjincludegraphics[valign = c, width = 6cm]{fig/gauged_ham1.pdf} = \adjincludegraphics[valign = c, width = 6cm]{fig/gauged_ham2.pdf}.
\label{eq: gauged ham def}
\end{equation}
The input data $(X, x, \chi)$ are chosen to be the same as those in the original model, see \eqref{eq: X45 A2VecG}--\eqref{eq: chi A2VecG}.

The action of the local Hamiltonian $\widehat{\mathsf{h}}_i$ can be computed as
\begin{equation}
\begin{aligned}
&\quad \widehat{\mathsf{h}}_i \Ket{\adjincludegraphics[valign = c, width = 3cm]{fig/gauged_state_initial.pdf}}
= \sum_{g_5 \in S_{H \backslash G}} \sum_{h_{45} \in H} \chi_{1245}^{g; h} \chi_{2456}^{g; h} \chi_{4568}^{g; h} \overline{\chi}_{1345}^{g; h} \overline{\chi}_{3457}^{g; h} \overline{\chi}_{4578}^{g; h} \adjincludegraphics[valign = c, width = 4cm]{fig/gauged_ham_loop1.pdf} \\
&= \sum_{g_5 \in S_{H \backslash G}} \sum_{h_{45} \in H} \chi_{1245}^{g; h} \chi_{2456}^{g; h} \chi_{4568}^{g; h} \overline{\chi}_{1345}^{g; h} \overline{\chi}_{3457}^{g; h} \overline{\chi}_{4578}^{g; h} \sum_{a_{45} \in A_{h_{45}}^{\text{op}}} \frac{d^a_{45}}{\mathcal{D}_{A_{h_{45}}}} \adjincludegraphics[valign = c, width = 4cm]{fig/gauged_ham_loop2.pdf},
\end{aligned}
\label{eq: gauged Ham A2VecG 0}
\end{equation}
where $\chi_{ijkl}^{g; h}$ and $\overline{\chi}_{ijkl}^{g; h}$ are defined by
\begin{equation}
\chi_{ijkl}^{g; h} := \chi_{ijkl}(g_{ij}^h, g_{jk}^h, g_{kl}^h), \quad \overline{\chi}_{ijkl}^{g; h} := \overline{\chi}_{ijkl}(g_{ij}^h, g_{jk}^h, g_{kl}^h).
\end{equation}
On the first line of \eqref{eq: gauged Ham A2VecG 0}, we used the identity $\sum_{g \in G} \mathcal{O}(g) = \sum_{g_5 \in S_{H \backslash G}} \sum_{h_{45} \in H} \mathcal{O}(g_4^{-1} h_{45} g_5)$ for any quantity $\mathcal{O}$.
The second line of \eqref{eq: gauged Ham A2VecG 0} goes back to the first line if we shrink the loop of $a_{45}$ into a point.
A straightforward computation shows that the diagram on the second line of \eqref{eq: gauged Ham A2VecG 0} can be evaluated explicitly as follows:
\begin{equation}
\begin{aligned}
&\quad \adjincludegraphics[valign = c, width = 4cm]{fig/gauged_ham_loop2.pdf} = \Ket{\adjincludegraphics[valign = c, width = 4.5cm]{fig/gauged_ham_loop_planar1.pdf}} \\
&= \sum_{a_{15}, \cdots, a_{58}} ~ \sum_{\alpha_{145}, \cdots, \alpha_{458}} \prod_{i = 1, 2, 3} \sqrt{\frac{d^a_{i5} d^a_{45}}{d^a_{i4}}} \prod_{j = 6, 7, 8} \sqrt{\frac{d^a_{5j} d^a_{45}}{d^a_{4j}}} \Ket{\adjincludegraphics[valign = c, width = 4.75cm]{fig/gauged_ham_loop_planar2.pdf}} \\
& = \sum_{a, \alpha} \overline{F}_{1245}^{a; \alpha} \overline{F}_{2456}^{a; \alpha} \overline{F}_{4568}^{a; \alpha} F_{1345}^{a; \alpha} F_{3457}^{a; \alpha} F_{4578}^{a; \alpha} \sqrt{\frac{d^a_{15} d^a_{56} d^a_{57}}{d^a_{14} d^a_{46} d^a_{47}}} \sqrt{\frac{d^a_{24} d^a_{34} d^a_{48}}{d^a_{25} d^a_{35} d^a_{58}}} \Ket{\adjincludegraphics[valign = c, width = 3cm]{fig/gauged_state_final.pdf}}.
\end{aligned}
\label{eq: gauged Ham loop}
\end{equation}
Here, we omitted to draw the surfaces below the honeycomb lattice.
The summation on the last line is taken over $\{a_{15}, a_{25}, a_{35}, a_{56}, a_{57}, a_{58}\}$, $\{\alpha_{145}, \alpha_{245}, \alpha_{345}, \alpha_{456}, \alpha_{457}, \alpha_{458}\}$, and $\{\alpha_{125}, \alpha_{256}, \alpha_{568}, \alpha_{135}, \alpha_{357}, \alpha_{578}\}$.
Combining \eqref{eq: gauged Ham A2VecG 0} and \eqref{eq: gauged Ham loop} leads us to
\begin{equation}
\begin{aligned}
\widehat{\mathsf{h}}_i ~ \Ket{\adjincludegraphics[valign = c, width = 3cm]{fig/gauged_state_initial.pdf}}
& = \sum_{g_5 \in S_{H \backslash G}} \sum_{h_{45} \in H} \chi_{1245}^{g; h} \chi_{2456}^{g; h} \chi_{4568}^{g; h} \overline{\chi}_{1345}^{g; h} \overline{\chi}_{3457}^{g; h} \overline{\chi}_{4578}^{g; h} \sum_{a_{45} \in A_{h_{45}}^{\text{op}}} \frac{d^a_{45}}{\mathcal{D}_{A_{h_{45}}}} \\
& \quad ~ \sum_{a_{15}, \cdots, a_{58}} ~ \sum_{\alpha_{145}, \cdots, \alpha_{458}} ~ \sum_{\alpha_{125}, \cdots, \alpha_{578}} \overline{F}_{1245}^{a; \alpha} \overline{F}_{2456}^{a; \alpha} \overline{F}_{4568}^{a; \alpha} F_{1345}^{a; \alpha} F_{3457}^{a; \alpha} F_{4578}^{a; \alpha} \\
& \quad ~ \sqrt{\frac{d^a_{15} d^a_{56} d^a_{57}}{d^a_{14} d^a_{46} d^a_{47}}} \sqrt{\frac{d^a_{24} d^a_{34} d^a_{48}}{d^a_{25} d^a_{35} d^a_{58}}} \Ket{\adjincludegraphics[valign = c, width = 3cm]{fig/gauged_state_final.pdf}}.
\end{aligned}
\label{eq: gauged Ham explicit}
\end{equation}
The above Hamiltonian is well-defined as an operator acting on the state space $\mathcal{H}_{\text{gauged}}$ because it satisfies
\begin{equation}
\widehat{\mathsf{h}}_i \widehat{B}_i = \widehat{B}_i \widehat{\mathsf{h}}_i = \widehat{h_i},
\label{eq: LW inv}
\end{equation}
where $\widehat{B}_i$ is the Levin-Wen plaquette operator~\eqref{eq: LW A2VecG}.

\paragraph{Gauged Model Written in terms of $A^{\text{rev}}$.}
The monoidal equivalence between $A^{\text{op}}$ and $A^{\text{rev}}$ implies that the gauged model can also be written in terms of $A^{\text{rev}}$ instead of $A^{\text{op}}$.
In the model written in terms of $A^{\text{rev}}$, the dynamical variables on the plaquettes, edges, and vertices are labeled by elements of $S_{H \backslash G}$, simple objects of $A^{\text{rev}}$, and basis morphisms of $A^{\text{rev}}$, respectively.
The state corresponding to a possible configuration of these dynamical variables can be written as
\begin{equation}
\ket{\{g_i, a_{ij}, \alpha_{ijk}\}} = \Ket{\adjincludegraphics[valign = c, width = 3.5cm]{fig/gauged_state_rev.pdf}},
\label{eq: gauged state rev}
\end{equation}
where the vertices are labeled by $\overline{\alpha}_{ijk}^{\text{rev}}$, $\alpha_{jkl}^{\text{rev}}$, etc.
We note that the orientations of the edges in \eqref{eq: gauged state rev} are opposite to those in \eqref{eq: state in A2VecG}.
The Hamiltonian is again given by
\begin{equation}
H_{\text{gauged}} = -\sum_{i \in P} \widehat{\mathsf{h}}_i,
\end{equation}
where $\widehat{\mathsf{h}}_i$ is defined by the same diagram as that in \eqref{eq: gauged ham def} except that the edges of the honeycomb lattice (written in black) are now oriented in the opposite direction.
The action of $\widehat{\mathsf{h}}_i$ on the state~\eqref{eq: gauged state rev} can be computed as
\begin{equation}
\begin{aligned}
\widehat{\mathsf{h}}_i ~ \Ket{\adjincludegraphics[valign = c, width = 3cm]{fig/gauged_state_initial_rev.pdf}}
& = \sum_{g_5 \in S_{H \backslash G}} \sum_{h_{45} \in H} \chi_{1245}^{g; h} \chi_{2456}^{g; h} \chi_{4568}^{g; h} \overline{\chi}_{1345}^{g; h} \overline{\chi}_{3457}^{g; h} \overline{\chi}_{4578}^{g; h} \sum_{a_{45} \in A_{h_{45}}^{\text{rev}}} \frac{d^a_{45}}{\mathcal{D}_{A_{h_{45}}}}\\
& \quad ~ \sum_{a_{15}, \cdots, a_{58}} ~ \sum_{\alpha_{145}, \cdots, \alpha_{458}} ~ \sum_{\alpha_{125}, \cdots, \alpha_{578}} \overline{F}_{1245}^{a; \alpha} \overline{F}_{2456}^{a; \alpha} \overline{F}_{4568}^{a; \alpha} F_{1345}^{a; \alpha} F_{3457}^{a; \alpha} F_{4578}^{a; \alpha} \\
& \quad ~ \sqrt{\frac{d^a_{15} d^a_{56} d^a_{57}}{d^a_{14} d^a_{46} d^a_{47}}} \sqrt{\frac{d^a_{24} d^a_{34} d^a_{48}}{d^a_{25} d^a_{35} d^a_{58}}} \Ket{\adjincludegraphics[valign = c, width = 3cm]{fig/gauged_state_final_rev.pdf}}.
\end{aligned}
\label{eq: gauged Ham explicit rev}
\end{equation}
The above Hamiltonian agrees with \eqref{eq: gauged Ham explicit} upon identifying the states defined by \eqref{eq: state in A2VecG} and \eqref{eq: gauged state rev}.

Since the two models written in terms of $A^{\text{op}}$ and $A^{\text{rev}}$ are equivalent, we can use whichever description we want.
In what follows, we will employ the description in terms of $A^{\text{rev}}$.
Namely, the state and the Hamiltonian of the gauged model are given by \eqref{eq: gauged state rev} and \eqref{eq: gauged Ham explicit rev}.


\paragraph{Ordinary Gauging as a Special Case.}
The generalized gauging described above includes ordinary (twisted) gauging of a finite group symmetry.
The ordinary gauging of non-anomalous finite group symmetries in 2+1d lattice models was studied in detail in \cite{Delcamp:2023kew}.

To recover the ordinary gauging, we choose the $G$-graded fusion category $A$ to be
\begin{equation}
A = \Vec_H^{\nu},
\end{equation}
where $H \subset G$ is a subgroup of $G$ and $\nu \in Z^3(H, \mathrm{U}(1))$ is a 3-cocycle on $H$.
For this choice of $A$, the dynamical variables of the gauged model are given as follows:
\begin{itemize}
\item The dynamical variables on the plaquettes take values in $S_{H \backslash G}$.
\item The dynamical variables on the edges take values in $H$.\footnote{As discussed in section~\ref{sec: non-minimal gauging of 2VecG}, the dynamical variables on the edges are generally labeled by simple objects of $A^{\text{rev}}$. When $A = \Vec_H^{\nu}$, (the isomorphism classes of) simple objects of $A^{\text{rev}}$ are in one-to-one correspondence with elements of $H$. Hence, the dynamical variables on the edges are labeled by elements of $H$.} These dynamical variables are subject to the constraint $h_{ik} = h_{ij} h_{jk}$ around each vertex $[ijk]$. Here, $h_{ij}$ denotes the dynamical variable on edge $[ij]$.
\item There are no dynamical variables on the vertices.
\end{itemize}
The Levin-Wen plaquette operator is trivial because $A_e$ is equivalent to $\Vec$.
Therefore, the state space $\mathcal{H}_{\text{gauged}}$ is given by the space of all possible configurations of the dynamical variables on the lattice.
The Hamiltonian~\eqref{eq: gauged Ham explicit rev} reduces to
\begin{equation}
\begin{aligned}
\widehat{\mathsf{h}}_i \Ket{\adjincludegraphics[valign = c, width = 3cm]{fig/gauged_state_initial_minimal.pdf}} & = \sum_{g_5 \in S_{H \backslash G}} \sum_{h_{45} \in H} \chi_{1245}^{g; h} \chi_{2456}^{g; h} \chi_{4568}^{g; h} \overline{\chi}_{1345}^{g; h} \overline{\chi}_{3457}^{g; h} \overline{\chi}_{4578}^{g; h} \\
& \quad ~ \frac{\nu(h_{13}, h_{34}, h_{45}) \nu(h_{34}, h_{45}, h_{57}) \nu(h_{45}, h_{57}, h_{78})}{\nu(h_{12}, h_{24}, h_{45}) \nu(h_{24}, h_{45}, h_{56}) \nu(h_{45}, h_{56}, h_{68})} \Ket{\adjincludegraphics[valign = c, width = 3cm]{fig/gauged_state_final_minimal.pdf}}.
\end{aligned}
\end{equation}
Physically, $h_{ij}$ represents an $H$-gauge field.
The constraint $h_{ik} = h_{ij} h_{jk}$ implies that this gauge field is flat.
The Gauss law constraint is imposed exactly (not energetically) on the state space $\mathcal{H}_{\text{gauged}}$.
We note that the Gauss law constraint is already solved explicitly, which is why the dynamical variables on the plaquettes are labeled by $H$-cosets in $G$ rather than elements of $G$.
The minimal coupling is implemented through $\chi^{g; h}_{ijkl}$ and $\overline{\chi}^{g; h}_{ijkl}$. 


\subsubsection{Generalized Gauging Operators}
\label{sec: Duality operators}
In this subsection, we write down the generalized gauging operators that implement the generalized gauging of $2\Vec_G$ symmetry.
We will also discuss the generalized gauging operators that map the gauged model back to the original model. 
The gauging operators for the minimal gauging were studied in \cite{Delcamp:2023kew}.\footnote{In 1+1d, the gauging operators for general fusion category symmetries are studied in \cite{Lootens:2021tet, Lootens:2022avn}. In 2+1d, some of the gauging operators for $2\Rep(G)$ symmetry are also studied in \cite{Vancraeynest-DeCuiper:2025wkh} in the context of abelian lattice gauge theories. In 3+1d, the gauging operator for $\mathbb{Z}_2$ 1-form symmetry is studied in \cite{Gorantla:2024ocs}. See also \cite{Vanhove:2024lmj} for sequential quantum circuit representations of some gauging operators.}

\paragraph{From the Original Model to the Gauged Model.}
Let us first consider the generalized gauging operator that maps the original model to the gauged model:
\begin{equation}
\mathsf{D}_A: \mathcal{H}_{\text{original}} \to \mathcal{H}_{\text{gauged}}.
\end{equation}
We recall that in the original model, the dynamical degrees of freedom are labeled by objects, 1-morphisms, and 2-morphisms of $2\Vec_G$.
On the other hand, in the gauged model, the dynamical degrees of freedom are labeled by objects, 1-morphisms, and 2-morphisms of ${}_A (2\Vec_G)$.
Thus, the generalized gauging operator maps objects, 1-morphisms, and 2-morphisms of $2\Vec_G$ to those of ${}_A (2\Vec_G)$.
Mathematically, this map is given by the free module functor
\begin{equation}
F_A: 2\Vec_G \to {}_A (2\Vec_G).
\label{eq: free module functor}
\end{equation}
The free module functor $F_A$ is a functor that maps an object $X \in 2\Vec_G$ to $A \square X \in {}_A (2\Vec_G)$, a 1-morphism $x \in \Hom_{2\Vec_G}(X, X^{\prime})$ to $1_A \square x \in \Hom_{{}_A (2\Vec_G)}(A \square X, A \square X^{\prime})$, and a 2-morphism $\chi \in \Hom_{2\Vec_G}(x, x^{\prime})$ to $\id_{1_A} \square \chi \in \Hom_{{}_A (2\Vec_G)}(1_A \square x, 1_A \square x^{\prime})$, where $1_A$ denotes the identity 1-morphism of $A \in {}_A(2\Vec_G)$.
Pictorially, the free module functor $F_A$ is represented by the stacking of the surface labeled by $A$:
\begin{equation}
\adjincludegraphics[valign = c, width = 2.5cm]{fig/FA1.pdf} \xmapsto{F_A} \adjincludegraphics[valign = c, width = 2.2cm]{fig/FA2.pdf}.
\label{eq: free module functor}
\end{equation}
Accordingly, the generalized gauging operator $\mathsf{D}_A$ is given by the fusion with the surface labeled $A$.

To write down the generalized gauging operator $\mathsf{D}_A$ on the lattice, we consider the action of $\mathsf{D}_A$ on a state $\ket{\{h_i g_i\}} \in \mathcal{H}_{\text{original}}$, where $h_i \in H$ and $g_i \in S_{H \backslash G}$.\footnote{The decomposition of an element of $G$ into the product of elements of $H$ and $S_{H \backslash G}$ is unique.} 
Based on the diagrammatic representation~\eqref{eq: free module functor}, one can compute the action of $\mathsf{D}_A$ as follows:
\begin{equation}
\boxed{
\begin{split}
\mathsf{D}_A \ket{\{h_ig_i\}} & = \sum_{\{a_i \in A_{h_i}^{\text{rev}}\}} \prod_{i \in P} \frac{d^a_i}{\mathcal{D}_{A_{h_i}}} \adjincludegraphics[valign = c, width = 4.5cm]{fig/DA1.pdf} \\
& = \sum_{\{a_i \in A_{h_i}^{\text{rev}}\}} \prod_{i \in P} \frac{d^a_i}{\mathcal{D}_{A_{h_i}}} \sum_{\{a_{ij}, \alpha_{ij}\}} \prod_{[ij] \in E} \sqrt{\frac{d^a_{ij}}{d^a_i d^a_j}} \adjincludegraphics[valign = c, width = 4.5cm]{fig/DA2.pdf} \\
& = \sum_{\{a_i \in A_{h_i}^{\text{rev}}\}} \prod_{i \in P} \frac{1}{\mathcal{D}_{A_{h_i}}} \sum_{\{a_{ij}, \alpha_{ij}, \alpha_{ijk}\}} \prod_{[ijk] \in V} \left(\frac{d^a_{ij} d^a_{jk}}{d^a_{ik}}\right)^{\frac{1}{4}} \prod_{[ijk] \in V} (\overline{F}_{ijk}^{a; \alpha})^{s_{ijk}} \ket{\{g_i, a_{ij}, \alpha_{ijk}\}}.
\end{split}
}
\label{eq: duality op}
\end{equation}
Here, $a_{ij} \in \overline{a_i} \otimes a_j$ is a simple object of $A_{h_i^{-1}h_j}^{\text{rev}}$, $\alpha_{ij}$ and $\alpha_{ijk}$ are the basis morphisms of $\Hom_A(\overline{a_i} \otimes a_j, a_{ij})$ and $\Hom_A(a_{ij} \otimes a_{jk}, a_{ik})$, and $s_{ijk}$ is defined by
\begin{equation}
s_{ijk} =
\begin{cases}
+1 \quad \text{if $[ijk]$ is in the $A$-sublattice}, \\
-1 \quad \text{if $[ijk]$ is in the $B$-sublattice}.
\end{cases}
\label{eq: sijk}
\end{equation}
See figure~\ref{fig: sublattice} for the definitions of the $A$- and $B$-sublattices.
\begin{figure}
\centering
\includegraphics[width = 3.5cm]{fig/honeycomb.pdf}
\caption{The black dots constitute the $A$-sublattice, while the white dots constitute the $B$-sublattice.}
\label{fig: sublattice}
\end{figure}
We note that the above generalized gauging operator satisfies $\widehat{B}_i \mathsf{D}_A = \mathsf{D}_A$ for all plaquettes $i$, meaning that the image of $\mathsf{D}_A$ is contained in the state space of the gauged model.
Thus, $\mathsf{D}_A$ is well-defined as a linear map from $\mathcal{H}_{\text{original}}$ to $\mathcal{H}_{\text{gauged}}$.
By construction, the generalized gauging operator $\mathsf{D}_A$ intertwines the Hamiltonians of the original and gauged models, i.e.,
\begin{equation}
\mathsf{D}_A H_{\text{original}} = H_{\text{gauged}} \mathsf{D}_A.
\end{equation}

\paragraph{From the Gauged Model to the Original Model.}
We can also consider a linear map that implements the ungauging from the gauged model to the original model:
\begin{equation}
\overline{\mathsf{D}}_A: \mathcal{H}_{\text{gauged}} \to \mathcal{H}_{\text{original}}.
\end{equation}
This operator maps the dynamical degrees of freedom of the gauged model to those of the original model.
Namely, it maps objects, 1-morphisms, and 2-morphisms of ${}_A (2\Vec_G)$ to those of $2\Vec_G$.
Mathematically, this map is described by the forgetful functor\footnote{We note that the forgetful functor $\text{Forg}$ is the right adjoint to the free module functor $F_A$.}
\begin{equation}
\text{Forg}: {}_A (2\Vec_G) \to 2\Vec_G,
\label{eq: forgetful functor}
\end{equation}
which maps objects, 1-morphisms, 2-morphisms of ${}_A (2\Vec_G)$ to their underlying objects~\eqref{eq: underlying Mg}, underlying 1-morphisms~\eqref{eq: underlying a op} \eqref{eq: underlying a rev}, and underlying 2-morphisms~\eqref{eq: underlying alpha op} \eqref{eq: underlying alpha rev}, respectively.
The corresponding generalized gauging operator $\overline{\mathsf{D}}_A$ thus acts on a state as
\begin{equation}
\boxed{
\begin{aligned}
\overline{\mathsf{D}}_A \ket{\{g_i, a_{ij}, \alpha_{ijk}\}} &= \sum_{\{h_i \in H\}} \sum_{\{a_i \in A_{h_i}^{\text{rev}}\}} \sum_{\{\alpha_{ij}\}} \prod_{[ijk]} \left( \frac{d^a_{ij} d^a_{jk}}{d^a_{ik}} \right)^{\frac{1}{4}} \prod_{[ijk]} (F_{ijk}^{a; \alpha})^{s_{ijk}} \ket{\{h_i g_i\}}.
\end{aligned}
}
\label{eq: duality op bar}
\end{equation}
We note that $\overline{\mathsf{D}}_A$ satisfies $\overline{\mathsf{D}}_A \widehat{B}_i = \overline{\mathsf{D}}_A$ for all plaquettes $i$.
Hence, $\overline{\mathsf{D}}_A$ is well-defined as a linear map from the state space of the gauged model to that of the original model.

The action of $\overline{\mathsf{D}}_A$ on a state $\ket{\{g_i, a_{ij}, \alpha_{ijk}\}}$ vanishes if the gauge field $\{h_{ij} \mid [ij] \in E\}$, defined by the grading of $a_{ij} \in A_{h_{ij}}$, has a non-trivial holonomy around a closed loop.
Indeed, when the gauge field has a non-trivial holonomy, there is no configuration $\{h_i \mid i \in P\}$ that satisfies $h_{ij} = h_i^{-1} h_j$, meaning that the summand on the right-hand side of \eqref{eq: duality op bar} is empty.
Thus, for any oriented loop $\gamma$ on the dual of the honeycomb lattice, we have
\begin{equation}
\prod_{[ij] \in E_{\gamma}} h_{ij}^{s_{ij}} \neq e ~ \Rightarrow ~ \overline{\mathsf{D}}_A \ket{\{g_i, a_{ij}, \alpha_{ijk}\}} = 0.
\label{eq: no holonomy}
\end{equation}
Here, $\prod_{[ij] \in E_{\gamma}}$ is the path-ordered product over all edges intersecting $\gamma$.
The sign $s_{ij}$ in \eqref{eq: no holonomy} is defined by
\begin{equation}
s_{ij} = 
\begin{cases}
+1 \quad & \text{if $\gamma$ intersects $[ij]$ from the right of $[ij]$}, \\
-1 \quad & \text{if $\gamma$ intersects $[ij]$ from the left of $[ij]$}.
\end{cases}
\label{eq: sij}
\end{equation}
The left and right are defined with respect to the orientation of edge $[ij]$.

As a sanity check, let us consider the product $\overline{\mathsf{D}}_A \mathsf{D}_A$ of the generalized gauging operators.
Since $\mathsf{D}_A$ and $\overline{\mathsf{D}}_A$ implement the free module functor~\eqref{eq: free module functor} and the forgetful functor~\eqref{eq: forgetful functor}, the product $\overline{\mathsf{D}}_A \mathsf{D}_A$ implements the composite functor $\text{Forg} \circ F_A: 2\Vec_G \to 2\Vec_G$, which maps $X \in 2\Vec_G$ to $A \square X \in 2\Vec_G$.
Recalling that the underlying object of $A$ is given by \eqref{eq: G-graded FC}, we find
\begin{equation}
\overline{\mathsf{D}}_A \mathsf{D}_A = \sum_{h \in H} \text{rank}(A_h) U_h.
\label{eq: DA bar DA 0}
\end{equation}
One can check the above equality by a direct computation using \eqref{eq: duality op} and \eqref{eq: duality op bar}, see appendix~\ref{sec: DA bar DA} for details.


\paragraph{Relation to Hermitian Conjugate.}
The generalized gauging operators $\mathsf{D}_A$ and $\overline{\mathsf{D}}_A$ are related to each other by the Hermitian conjugate (up to normalization).
To see this, we first define the Hermitian inner products on the state space of the original model and that of the gauged model as follows:\footnote{The second line of \eqref{eq: Hilb str} defines the Hermitian inner product on the vector space $\mathcal{H}_{\text{gauged}}^{\prime}$ spanned by all possible configurations of dynamical variables of the gauged model. This induces the Hermitian inner product on the state space $\mathcal{H}_{\text{gauged}} \subset \mathcal{H}_{\text{gauged}}^{\prime}$.}
\begin{equation}
\begin{aligned}
\braket{\{h_i^{\prime} g_i^{\prime}\} | \{h_i g_i\}} & = \prod_i \delta_{h_i, h_i^{\prime}} \delta_{g_i, g_i^{\prime}}, \\
\braket{\{g_i^{\prime}, a_{ij}^{\prime}, \alpha_{ijk}^{\prime}\} | \{g_i, a_{ij}, \alpha_{ijk}\}} & = \prod_i \delta_{g_i, g_i^{\prime}} \prod_{[ij]} \delta_{a_{ij}, a_{ij}^{\prime}} \prod_{[ijk]} \delta_{\alpha_{ijk}, \alpha_{ijk}^{\prime}}.
\end{aligned}
\label{eq: Hilb str}
\end{equation}
The Hermitian conjugate of $\mathsf{D}_A$ with respect to the above inner product is given by
\begin{equation}
\braket{\{h_i g_i^{\prime}\} | \mathsf{D}_A^{\dagger} | \{g_i, a_{ij}, \alpha_{ijk}\}}
= \prod_i \frac{\delta_{g_i, g_i^{\prime}}}{\mathcal{D}_{A_{h_i}}} \sum_{\{a_i\}} \sum_{\{\alpha_{ij}\}} \prod_{[ijk]} \left( \frac{d^a_{ij} d^a_{jk}}{d^a_{ik}} \right)^{\frac{1}{4}} \prod_{[ijk]} (F_{ijk}^{a; \alpha})^{s_{ijk}},
\label{eq: DA dagger mat}
\end{equation}
where $a_i$ is a simple object of $A_{h_i}^{\text{rev}}$, $\alpha_{ij}$ is a basis morphism of $\Hom_A(\overline{a_i} \otimes a_j,a_{ij})$, and we used the unitarity of the $F$-symbol, i.e., $(F^{abc}_d)_{(e; \mu, \nu), (f; \rho, \sigma)}^* = (\overline{F}^{abc}_d)_{(e; \mu, \nu), (f; \rho, \sigma)}$.
On the other hand, the matrix element of $\overline{\mathsf{D}}_A$ is given by
\begin{equation}
\braket{\{h_i g_i^{\prime}\} | \overline{\mathsf{D}}_A | \{g_i, a_{ij}, \alpha_{ijk}\}} = \prod_i \delta_{g_i, g_i^{\prime}} \sum_{\{a_i\}} \sum_{\{\alpha_{ij}\}} \prod_{[ijk]} \left( \frac{d^a_{ij} d^a_{jk}}{d^a_{ik}} \right)^{\frac{1}{4}} \prod_{[ijk]} (F_{ijk}^{a; \alpha})^{s_{ijk}}.
\label{eq: DA bar mat}
\end{equation}
By comparing \eqref{eq: DA dagger mat} and \eqref{eq: DA bar mat}, we find
\begin{equation}
\overline{\mathsf{D}}_A = \mathsf{D}_A^{\dagger} \prod_i \mathcal{D}_{A_e}.
\label{eq: DA dagger}
\end{equation}
Here, we used the identity $\mathcal{D}_{A_e} = \mathcal{D}_{A_h}$ for all $h \in H$ \cite{EGNO}.
Equation~\eqref{eq: DA dagger} shows that $\overline{\mathsf{D}}_A$ agrees with $\mathsf{D}_A^{\dagger}$ up to normalization.
In the case of the minimal gauging $A = \Vec_H^{\nu}$, we have $\overline{\mathsf{D}}_A = \mathsf{D}_A^{\dagger}$.


\paragraph{Generalized Gauging Operators for Twisted Sectors.}
One can also define the generalized gauging operators that map the $H$-twisted sectors of the original model to the untwisted sector of the gauged model.
We will use such generalized gauging operators in section~\ref{sec: Line operators on surface operators} to construct topological surface operators decorated by topological line operators.

We first define the twisted sectors of the original model.
Each state in the $g$-twisted sector for $g \in G$ is represented by the following fusion diagram:
\begin{equation}
\ket{\{h_i g_i\}} = \adjincludegraphics[valign = c, width =5cm]{fig/twisted1.pdf} = \adjincludegraphics[valign = c, width =3cm]{fig/twisted2.pdf}.
\label{eq: twisted sector state}
\end{equation}
The line on which the defect $D_2^g$ ends is denoted by $\gamma$, which we suppose to be straight for simplicity.\footnote{
It is straightforward to generalize the definition of the twisted sector to the case where $\gamma$ is more complicated.
More generally, one can also define the sector twisted by a general network of topological defects.
}
For later use, we define $\tilde{\gamma}$ as the set of edges located immediately to the left of $\gamma$.
The state space of the twisted sector is spanned by all the fusion diagrams of the above form with fixed $\gamma$.
The Hamiltonian acting on the state~\eqref{eq: twisted sector state} is defined by the same diagram as in the Hamiltonian of the untwisted sector.

A generalized gauging operator that maps the $h$-twisted sector for $h \in H$ to the untwisted sector of the gauged model is defined by the following fusion diagram:\footnote{The states in the $g$-twisted sector for $g \notin H$ are mapped to the twisted sector states of the gauged model.}
\begin{equation}
\mathsf{D}_A^a \ket{\{h_i g_i\}} = \adjincludegraphics[valign = c, width = 5cm]{fig/twisted_duality.pdf}.
\label{eq: twisted duality op}
\end{equation}
Here, the surface operator on the right-hand side is labeled by a left $A$-module $A \in {}_A (2\Vec_G)$.
At the junction of surfaces $A$ and $D_2^h$, we have a topological line $a$, which is a 1-morphism from $A$ to $A \vartriangleleft D_2^h$ in ${}_A(2\Vec_G)$:
\begin{equation}
a \in \Hom_{{}_A (2\Vec_G)}(A, A \vartriangleleft D_2^h) \cong A_h^{\text{rev}}.
\end{equation}
We note that a different choice of $a \in A_h^{\text{rev}}$ gives rise to a different generalized gauging operator for the $h$-twisted sector.
The operator $\mathsf{D}_A^a$ defined by \eqref{eq: twisted duality op} can be evaluated explicitly as follows:
\begin{equation}
\begin{aligned}
\mathsf{D}_A^a \ket{\{h_i g_i\}}
&= \sum_{\{a_i \in A_{h_i}^{\text{rev}}\}} \prod_{i} \frac{d^a_i}{\mathcal{D}_{A_{h_i}}} \adjincludegraphics[valign = c, width = 4.5cm]{fig/twisted_duality_loop1.pdf} \\
&= \sum_{\{a_i \in A_{h_i}^{\text{rev}}\}} \prod_{i} \frac{d^a_i}{\mathcal{D}_{A_{h_i}}} \sum_{\{a_i^{\prime} \in a \otimes a_i \mid i \in P_{\gamma}\}} \prod_{i \in P_{\gamma}} \sqrt{\frac{d^{a^{\prime}}_i}{d^a d^a_i}} \adjincludegraphics[valign = c, width = 4.5cm]{fig/twisted_duality_loop2.pdf}.
\end{aligned}
\end{equation}
Here, $P_{\gamma}$ is the set of plaquettes that intersect $\gamma$.
The diagram on the right-hand side can be evaluated by doing the partial fusion and the $F$-move as shown in figure~\ref{fig: twisted duality op}.
\begin{figure}
\centering
\adjincludegraphics[valign = c, width = 4cm]{fig/twisted_duality_ev1.pdf} $~ \xrightarrow{\text{(a)}} ~$
\adjincludegraphics[valign = c, width = 4.5cm]{fig/twisted_duality_ev2.pdf} $~ \xrightarrow{\text{(b)}} ~$
\adjincludegraphics[valign = c, width = 4cm]{fig/twisted_duality_ev3.pdf}
\caption{(a) The partial fusion of topological lines around all edges of the honeycomb lattice. (b) The $F$-move around all vertices of the honeycomb lattice and around the edges that intersect $\gamma$.}
\label{fig: twisted duality op}
\end{figure}
As a result, the matrix element of $\mathsf{D}_A^a$ can be expressed in terms of the $F$-symbols and the quantum dimensions.
We note that $\mathsf{D}_A^a$ reduces to $\mathsf{D}_A$ when $h$ is the unit element of $H$ and $a$ is the unit object of $A_e^{\text{rev}}$.

Let us write down the matrix element of $\mathsf{D}_A^a$ more explicitly in the case of the minimal gauging.\footnote{Even in the case of the non-minimal gauging, it is not difficult to compute the matrix element of $\mathsf{D}_A^a$. However, the explicit expression becomes highly complicated in general.}
For the minimal gauging $A = \Vec_H^{\nu}$, the simple topological line $a \in A_h^{\text{rev}}$ is unique because $A_h^{\text{rev}}$ has only one simple object.
Thus, the gauging operator for the $h$-twisted sector is unique and is denoted by $\mathsf{D}_A^h$.
The action of $\mathsf{D}_A^h$ on a state can be computed as
\begin{equation}
\mathsf{D}_A^h \ket{\{h_i g_i\}} = \prod_{[ijk]} \nu(h_i, \tilde{h}_{ij}, \tilde{h}_{jk})^{-s_{ijk}} \prod_{[ij] \in E_{\gamma}} \nu(h, h_i, \tilde{h}_{ij})^{-1} \ket{\{g_i, \tilde{h}_{ij}\}},
\label{eq: twisted duality op for minimal}
\end{equation}
where $\gamma$ is chosen as in \eqref{eq: twisted sector state}, $E_{\gamma}$ is the set of edges that intersect $\gamma$, and $\tilde{h}_{ij}$ is defined by
\begin{equation}
\tilde{h}_{ij} :=
\begin{cases}
h_i^{-1} h_j \quad & \text{for $[ij] \notin \tilde{\gamma}$},\\
h_i^{-1}hh_j \quad & \text{for $[ij] \in \tilde{\gamma}$}.
\end{cases}
\end{equation}


