\adjincludegraphics[valign = c, width = 2.5cm]{fig/DA_omega_v1.pdf} = \left( \frac{d^a_{ij} d^a_{jk}}{d^a_{ik}} \right)^{\frac{1}{4}} \overline{\Omega}^{g; h}_{ijk} \overline{F}^a_{ijk}, \qquad 
\adjincludegraphics[valign = c, width = 2.5cm]{fig/DA_omega_v2.pdf} = \left( \frac{d^a_{ij} d^a_{jk}}{d^a_{ik}} \right)^{\frac{1}{4}} \Omega^{g; h}_{ijk} F^a_{ijk},
\end{equation}
where $h \in H$, $g \in S_{H \backslash G}$, and $a \in A$.

Similarly, when $A$ is multiplicity-free, the generalized gauging operator $\overline{\mathsf{D}}_A$ can be represented by the following tensor network:
\begin{equation}
\overline{\mathsf{D}}_A = \adjincludegraphics[valign = c, width = 3cm]{fig/DA_bar_PEPO_omega.pdf}.
\label{eq: DA bar PEPO omega}
\end{equation}
The physical legs are flipped from those of \eqref{eq: DA PEPO omega}, while the virtual bonds remain the same.
The non-zero components of the local tensors in \eqref{eq: DA bar PEPO omega} are given as follows:
\begin{equation}
\adjincludegraphics[valign = c, width = 2cm]{fig/DA_bar_omega_p.pdf} = 1, \qquad 
\adjincludegraphics[valign = c, width = 1.5cm]{fig/PEPO_edge_bar.pdf} = 1, \qquad 
\adjincludegraphics[valign = c, width = 1.5cm]{fig/gauged_non_minimal_PEPS_evirt.pdf} = \delta_{a \in A_h},
\end{equation}
\begin{equation}
\adjincludegraphics[valign = c, width = 2.5cm]{fig/DA_bar_omega_v1.pdf} = \left( \frac{d^a_{ij} d^a_{jk}}{d^a_{ik}} \right)^{\frac{1}{4}} \Omega^{g; h}_{ijk} F^a_{ijk}, \qquad 
\adjincludegraphics[valign = c, width = 2.5cm]{fig/DA_bar_omega_v1.pdf} = \left( \frac{d^a_{ij} d^a_{jk}}{d^a_{ik}} \right)^{\frac{1}{4}} \overline{\Omega}^{g; h}_{ijk} \overline{F}^a_{ijk},
\end{equation}
where $h \in H$, $g \in S_{H \backslash G}$, and $a \in A$.


\subsection{Symmetries of the Gauged Model}
\label{sec: Symmetry of the gauged model omega}
The symmetry of the gauged model is described by the dual 2-category
\begin{equation}
\mathcal{C}_{\mathcal{M}}^* \cong {}_A (2\Vec_G^{\omega})_A,
\end{equation}
where $\mathcal{C} = 2\Vec_G^{\omega}$ and $\mathcal{M} = {}_A (2\Vec_G^{\omega})$.
The objects, 1-morphisms, and 2-morphisms of ${}_A (2\Vec_G^{\omega})_A$ are given by $(A, A)$-bimodules, $(A, A)$-bimodule 1-morphisms, and $(A, A)$-bimodule 2-morphisms in $2\Vec_G^{\omega}$.
We refer the reader to \cite[Section 2.3]{Decoppet:2023bay} for more details of this 2-category.
In this subsection, we will write down some of the symmetry operators labeled by objects and morphisms of ${}_A (2\Vec_G^{\omega})_A$.
As in the previous subsection, we suppose that $A$ is a $G$-graded $\omega$-twisted unitary fusion category faithfully graded by $H \subset G$.

\paragraph{0-Form Symmetry.}
The 0-form symmetry operators are labeled by objects of ${}_A (2\Vec_G^{\omega})_A$.
The connected components of ${}_A (2\Vec_G^{\omega})_A$ are in one-to-one correspondence with double $H$-cosets in $G$.
Hence, the symmetry operators up to condensation are in one-to-one correspondence with double $H$-cosets in $G$.
We choose $A \square D_2^g \square A$ as a representative of each connected component,\footnote{We note that $A \square D_2^g \square A$ is a simple object of ${}_A (2\Vec_G^{\omega})_A$ becasue the unit object of $A$ is supposed to be simple, cf. section~\ref{sec: 0-form symmetry A2VecGA}.} where $g \in G$ is a representative of the double $H$-coset $HgH$.

The symmetry operator labeled by $A \square D_2^g \square A$ is given by $\mathsf{D}_A U_g \overline{\mathsf{D}}_A$, where $\mathsf{D}_A$ and $\overline{\mathsf{D}}_A$ are the generalized gauging operators and $U_g$ is the symmetry operator of the original model.
By using \eqref{eq: sym op omega}, \eqref{eq: DA omega}, and \eqref{eq: DA bar omega}, we can compute the action of $\mathsf{D}_A U_g \overline{\mathsf{D}}_A$ as follows:
\begin{equation}
\boxed{
\begin{aligned}
 \mathsf{D}_A U_g \overline{\mathsf{D}}_A \ket{\{g_i, a_{ij}, \alpha_{ijk}\}} 
&= \sum_{\{h_i, a_i, \alpha_{ij}\}} \sum_{\{a_i^{\prime}, a_{ij}^{\prime}, \alpha_{ij}^{\prime}, \alpha_{ijk}^{\prime}\}} \prod_{i \in P} \frac{1}{\mathcal{D}_{A_{h_i^{\prime}}}} \prod_{[ijk]} \left( \frac{d^a_{ij} d^a_{jk}}{d^a_{ik}} \right)^{\frac{1}{4}} (\Omega^{g; h}_{ijk})^{s_{ijk}} (F_{ijk}^{a; \alpha})^{s_{ijk}} \\
& \quad ~ \omega(g, h_ig_i, g^h_{ij}, g^h_{jk})^{s_{ijk}} \left( \frac{d^{a^{\prime}}_{ij} d^{a^{\prime}}_{jk}}{d^{a^{\prime}}_{ik}} \right)^{\frac{1}{4}} (\overline{\Omega}^{g^{\prime}; h^{\prime}}_{ijk})^{s_{ijk}} (\overline{F}_{ijk}^{a^{\prime}; \alpha^{\prime}})^{s_{ijk}} \ket{\{g_i^{\prime}, a_{ij}^{\prime}, \alpha_{ijk}^{\prime}\}}.
\end{aligned}
}
\end{equation}
Here, $h_i^{\prime} \in H$ and $g_i^{\prime} \in S_{H \backslash G}$ are uniquely determined by $h_i^{\prime} g_i^{\prime} = g h_i g_i$, and we defined $h_{ij} := h_i^{-1} h_j$ and $h_{ij}^{\prime} := (h_i^{\prime})^{-1} h_j^{\prime}$.
The summations on the right-hand side are taken over $h_i \in H$, $a_i \in A_{h_i}^{\text{rev}}$, $\alpha_{ij} \in \Hom_A(\overline{a_i} \otimes a_j, a_{ij})$, $a_i^{\prime} \in A_{h_i^{\prime}}^{\text{rev}}$, $a_{ij}^{\prime} \in \overline{a_i^{\prime}} \otimes a_j^{\prime}$, $\alpha_{ij}^{\prime} \in \Hom_A(\overline{a_i^{\prime}} \otimes a_j^{\prime}, a_{ij}^{\prime})$, and $\alpha_{ijk}^{\prime} \in \Hom_A(a_{ij}^{\prime} \otimes a_{jk}^{\prime}, a_{ik}^{\prime})$.


\paragraph{1-Form Symmetry.}
The 1-form symmetry operators are labeled by 1-endomorphisms of $A \in {}_A (2\Vec_G^{\omega})_A$.
These 1-morphisms form a braided fusion 1-category $\End_{{}_A (2\Vec_G^{\omega})_A} (A)$.
This category is braided equivalent to 
\begin{equation}
\End_{{}_A (2\Vec_G^{\omega})_A} (A) \cong \mathcal{Z}(A)_0,
\label{eq: 1-form omega}
\end{equation}
where, by slight abuse of notation, $\mathcal{Z}(A)_0$ denotes the braided fusion category defined as follows:
\begin{itemize}
\item An object of $\mathcal{Z}(A)_0$ is a pair $(a, \Phi)$, where $a$ is an object of $A_e$ and $\Phi$ is a natural family of isomorphisms
\begin{equation}
\Phi_b: b \otimes a \to a \otimes b, \qquad \forall b \in A,
\end{equation}
that satisfies the usual coherence condition of the half-braiding.
\item A morphism $f: (a, \Phi) \to (a^{\prime}, \Phi^{\prime})$ in $\mathcal{Z}(A)_0$ is a morphism $f: a \to a^{\prime}$ in $A_e$ that is compatible with the half-braiding, i.e.,
\begin{equation}
\Phi^{\prime}_b \circ (\id_b \otimes f) = (f \otimes \id_b) \circ \Phi_b, \qquad \forall b \in A.
\end{equation}
\item The braided monoidal structure on $\mathcal{Z}(A)_0$ is defined as in the usual definition of the Drinfeld center.\footnote{When the twist $\omega$ is trivial, $\mathcal{Z}(A)_0$ reduces to the full subcategory of the Drinfeld center $\mathcal{Z}(A)$ consisting of objects whose underlying objects are in $A_e$.}
\end{itemize}
Under the equivalence~\eqref{eq: 1-form omega}, a functor $F \in \End_{{}_A (2\Vec_G^{\omega})_A}(A)$ is mapped to an object $(F(\mathds{1}_A), \Phi) \in \mathcal{Z}(A)_0$, where the half-braiding $\Phi$ is defined by \eqref{eq: half-braiding}.
On the other hand, an object $(a, \Psi) \in \mathcal{Z}(A)_0$ is mapped to a functor $F \in \End_{{}_A (2\Vec_G^{\omega})_A}(A)$ such that $F(b) = b \otimes a$ for all $b \in A$ and the associated natural isomorphisms are given by \eqref{eq: weak inverse}.

The 1-form symmetry operator $\widehat{D}^{\gamma}_{(a, \Phi)}$ labeled by $(a, \Phi) \in \mathcal{Z}(A)_0$ acts on a state as
\begin{equation}
\widehat{D}_{(a, \Phi)}^{\gamma} \Ket{\adjincludegraphics[valign = c, width = 3.5cm]{fig/one_form_initial.pdf}} ~ = ~ \Ket{\adjincludegraphics[valign = c, width = 4.5cm]{fig/one_form_final.pdf}}.
\end{equation}
The blue dots on the right-hand side represent the half-braiding.
The superscript $\gamma$ of $\widehat{D}^{\gamma}_{(a, \Phi)}$ denotes the path on which the symmetry operator is supported.




\section{Gapped Phases}
\label{sec: Gapped phases}
In this section, we construct commuting projector Hamiltonians for gapped phases with all-boson fusion 2-category symmetries.
These models are obtained by the generalized gauging of gapped phases with $2\Vec_G^{\omega}$ symmetry.
We will also write down the ground states of these models using tensor networks.

\subsection{Gapped Phases with $2\Vec_G$ Symmetry}
\label{sec: Gapped phases with 2VecG symmetry}
We begin with gapped phases with $2\Vec_G$ symmetry.
We choose
\begin{equation}
\mathcal{C} = 2\Vec_G, \quad \mathcal{M} = 2\Vec_G,
\end{equation}
and consider a gapped phase specified by a separable algebra $B \in 2\Vec_G$.

\subsubsection{Minimal Gapped Phases}
\label{sec: Minimal gapped phases with 2VecG symmetry}
We first focus on minimal gapped phases, which are $G$-symmetric gapped phases without topological orders.
These gapped phases are labeled by the pairs $(K, [\lambda])$, where $K \subset G$ is a subgroup of $G$ and $[\lambda] \in H^3(K, \mathrm{U}(1))$ is an element of the third group cohomology of $K$.
Physically, $K$ and $[\lambda]$ represent the unbroken symmetry and its SPT class, respectively.

The minimal gapped phase labeled by $(K, [\lambda])$ is realized in the fusion surface model by choosing the algebra object $B \in 2\Vec_G$ as
\begin{equation}
B = \Vec_K^{\lambda}.
\end{equation}
Here, $\Vec_K^{\lambda}$ is the 1-category of finite dimensional $K$-graded vector spaces with the associator twisted by $\lambda \in Z^3(K, \mathrm{U}(1))$.
The algebra structure on $\Vec_K^{\lambda}$ is given as follows:
\begin{itemize}
\item The underlying object of $\Vec_K^{\lambda} \in 2\Vec_G$ is the direct sum $\bigoplus_{k \in K} D_2^k$.
\item The multiplication 1-morphism $m: \Vec_K^{\lambda} \square \Vec_K^{\lambda} \rightarrow \Vec_K^{\lambda}$ is defined component-wise as
\begin{equation}
\adjincludegraphics[valign = c, width = 3.5cm]{fig/m_K_lambda.pdf} = \delta_{k_1k_2, k_3} 1_{k_1 \cdot k_2}.
\label{eq: K m}
\end{equation}
\item The associativity 2-isomorphism $\mu$ is defined component-wise as
\begin{equation}
\adjincludegraphics[valign = c, width = 4cm]{fig/mu_K_lambda1.pdf} = \lambda(k_1, k_2, k_3) \adjincludegraphics[valign = c, width = 3cm]{fig/mu_K_lambda2.pdf},
\label{eq: K mu}
\end{equation}
where the white dot on the right-hand side represents a basis 2-morphism.
The coherence condition on $\mu$ follows from the cocycle condition on $\lambda$.
\end{itemize}

For this choice of the algebra $B$, possible configurations of the dynamical variables on the lattice can be described as follows.
\begin{itemize}
\item The dynamical variables on the plaquettes are labeled by elements of $G$. These dynamical variables obey the constraint\footnote{This constraint was imposed energetically in section~\ref{sec: Gapped Phases and Examples}. Similar comments will also apply to the other lattice models that we will discuss later on.}
\begin{equation}
g_{i}^{-1} g_j \in K
\label{eq: gij in K}
\end{equation}
for any pair of adjacent plaquettes $i$ and $j$.
\item There are no dynamical variables on the edges and vertices.
\end{itemize}
The Levin-Wen plaquette operator is the identity operator because the endomorphism 1-category $\End_{2\Vec_G}(D_2^g)$ is monoidally equivalent to $\Vec$ for any $g \in G$.
Therefore, the state space of the model is given by the vector space spanned by all possible configurations of the dynamical variables.
A configuration of the dynamical variables is collectively denoted by
\begin{equation}
\{g_i \mid i \in P\},
\end{equation}
where $P$ is the set of all plaquettes on the honeycomb lattice.
The state corresponding to the above configuration is written as $\ket{\{g_i\}}$.
The symmetry operator $U_g$ acts on this state as
\begin{equation}
U_g \ket{\{g_i\}} = \ket{\{gg_i\}}.
\label{eq: non-anomalous G}
\end{equation}

The Hamiltonian of the model is given by the sum
\begin{equation}
H = - \sum_{i \in P} \widehat{\mathsf{h}}_i,
\end{equation}
where $\widehat{\mathsf{h}}_i$ is defined in terms of the algebra $\Vec_K^{\lambda}$ as in \eqref{eq: gapped Ham}.
Unpacking \eqref{eq: gapped Ham} leads to
\begin{equation}\label{eq:minimal Ham operator}
\widehat{\mathsf{h}}_i ~ \Ket{\adjincludegraphics[valign = c, width = 2cm]{fig/minimal_gapped_G1.pdf}} = \frac{1}{|K|} \sum_{g_5 \in G} \delta_{g_{45} \in K} \frac{\lambda^g_{1245} \lambda^g_{2456} \lambda^g_{4568}}{\lambda^g_{1345} \lambda^g_{3457} \lambda^g_{4578}} ~ \Ket{\adjincludegraphics[valign = c, width = 2cm]{fig/minimal_gapped_G2.pdf}},
\end{equation}
where $\lambda_{ijkl}^g := \lambda(g_{ij}, g_{jk}, g_{kl})$, $g_{ij} := g_i^{-1} g_j$, and $\delta_{g \in K}$ is defined by\footnote{We note that $\lambda(g_{ij}, g_{jk}, g_{kl})$ makes sense because $g_{ij}, g_{jk}, g_{kl} \in K$ due to the constraint~\eqref{eq: gij in K}.}
\begin{equation}
\delta_{g \in K} = 
\begin{cases}
1 \quad \text{if $g \in K$}, \\
0 \quad \text{if $g \notin K$}.
\end{cases}
\label{eq: g in K}
\end{equation}

Since the above Hamiltonian is the sum of commuting projectors, the ground states are given by the simultaneous eigenstates of $\widehat{\mathsf{h}}_i$'s with eigenvalue 1.
Such states can be obtained by applying $\prod_i \widehat{\mathsf{h}}_i$ to generic states.

Let us write down the ground states explicitly.
To this end, we first notice that the state space $\mathcal{H}$ can be decomposed into the direct sum % of distinct sectors labeled by left $K$-cosets in $G$:
\begin{equation}
\mathcal{H} = \bigoplus_{\mu = 1, 2, \cdots, |G/K|} \mathcal{H}^{(\mu)},
\label{eq: sectors}
\end{equation}
where $\mathcal{H}^{(\mu)}$ is the vector space spanned by the states such that all the plaquettes are labeled by elements of the same left $K$-coset $g^{(\mu)}K$, that is, we have\footnote{When the dynamical variable on some plaquette is labeled by an element of $g^{(\mu)} K$, the dynamical variables on all the other plaquettes must also be labeled by elements of the same coset due to the constraint~\eqref{eq: gij in K}.}
\begin{equation}
\mathcal{H}^{(\mu)} := \text{Span}\{\ket{\{g_i\}} \mid g_i \in g^{(\mu)}K\}.
\end{equation}
Here, $g^{(\mu)} \in G$ denotes a representative of the coset $g^{(\mu)}K$.
Each sector has its own ground states because the action of the Hamiltonian does not mix these sectors.
Furthermore, the ground state in each sector is unique on an infinite plane.\footnote{When restricted to the sector $\mathcal{H}^{(1)}$ labeled by the trivial left $K$-coset $K$, the model reduces to the group cohomology model of SPT phases with $K$ symmetry \cite{Chen:2011pg}. Hence, it has a unique ground state in $\mathcal{H}^{(1)}$. The other sectors have the same energy spectrum as $\mathcal{H}^{(1)}$ because any states in the other sectors are obtained by acting with the symmetry operators on the states in $\mathcal{H}^{(1)}$. Thus, the model has a unique ground state in every sector.}
Thus, there are as many ground states on an infinite plane as the number of left $K$-cosets, which is equal to $|G|/|K|$.
The ground state $\ket{\text{GS}; \mu}$ within each sector $\mathcal{H}^{(\mu)}$ is given by
\begin{equation}
\ket{\text{GS}; \mu} = \prod_{i \in P} \widehat{\mathsf{h}}_i \ket{\{g_i = g^{(\mu)}\}},
\end{equation}
where $\ket{\{g_i = g^{(\mu)}\}}$ denotes the state where all the plaquettes are labeled by $g^{(\mu)} \in G$.
A direct computation shows that the above ground state can be written more explicitly as follows:
\begin{equation}
\boxed{
\ket{\text{GS}; \mu} = \sum_{\{k_i \in K\}} \prod_{i \in P} \frac{1}{|K|} \prod_{[ijk] \in V} \lambda(k_i, k_{ij}, k_{jk})^{s_{ijk}} \ket{\{g^{(\mu)} k_i\}}.
}
\label{eq: minimal GS 2VecG}
\end{equation}
Here, $V$ denotes the set of all vertices on the honeycomb lattice, $k_{ij}$ is defined by $k_i^{-1} k_j$, and $s_{ijk}$ is defined by \eqref{eq: sijk}.
See \eqref{eq: non-minimal GS 2VecG} for a detailed computation of the ground states of more general gapped phases.
The symmetry operators act on the above ground states as
\begin{equation}
U_g \ket{\text{GS}; \mu} = \ket{\text{GS}; \nu},
\end{equation}
where $g \in g^{(\nu)} K (g^{(\mu)})^{-1} := \{ g^{(\nu)} k (g^{(\mu)})^{-1} \mid k \in K\}$.
The explicit form of the ground states~\eqref{eq: minimal GS 2VecG} implies that the above gapped phase spontaneously breaks the $G$ symmetry down to $K$ and realizes an SPT order labeled by $[\lambda] \in H^3(K, \mathrm{U}(1))$.
In particular, when $K = G$, our model agrees with the group cohomology model of SPT phases studied in \cite{Chen:2011pg}.

\paragraph{Embedding into Tensor Product State Space.}
The above model can be embedded into a tensor product state space without breaking the symmetry by imposing the constraint~\eqref{eq: gij in K} energetically.
Specifically, we define the state space of the new model as
\begin{equation}
\widetilde{\mathcal{H}} = \bigotimes_{i \in P} \mathbb{C}^{|G|}.
\end{equation}
The Hamiltonian acting on this state space is given by
\begin{equation}
H = - \sum_{i \in P} \widehat{\mathsf{h}}_i - \sum_{[ij] \in E} \widehat{\mathsf{h}}_{ij},
\label{eq: Ham tens prod}
\end{equation}
where $E$ is the set of all edges, and $\widehat{\mathsf{h}}_i$ and $\widehat{\mathsf{h}}_{ij}$ are defined as follows:
\begin{equation}
\widehat{\mathsf{h}}_i ~ \Ket{\adjincludegraphics[valign = c, width = 2cm]{fig/minimal_gapped_G1.pdf}} = \frac{1}{|K|} \sum_{g_5 \in G} \left(\prod_{j = 1, 2, \cdots, 8} \delta_{g_{4j} \in K}\right) \frac{\lambda^g_{1245} \lambda^g_{2456} \lambda^g_{4568}}{\lambda^g_{1345} \lambda^g_{3457} \lambda^g_{4578}} ~ \Ket{\adjincludegraphics[valign = c, width = 2cm]{fig/minimal_gapped_G2.pdf}},
\end{equation}
\begin{equation}
\widehat{\mathsf{h}}_{ij} \Ket{\adjincludegraphics[valign = c, width = 1cm]{fig/hij.pdf}} = \delta_{g_{ij} \in K} \Ket{\adjincludegraphics[valign = c, width = 1cm]{fig/hij.pdf}}.
\end{equation}
Here, we recall $g_{ij} := g_i^{-1} g_j$.
The first and second terms of the Hamiltonian~\eqref{eq: Ham tens prod} commute with each other.
Therefore, the ground states are the simultaneous eigenstates of both terms with the lowest eigenvalues.
The ground state subspace of the second term agrees with the state space~\eqref{eq: sectors} of the original model.
The first term acts on this subspace in the same way as the original Hamiltonian~\eqref{eq:minimal Ham operator}.
Thus, the ground states of the new model agree with those of the original model.
We emphasize that the new model still has $2\Vec_G$ symmetry whose action is given by \eqref{eq: non-anomalous G}.
This model is also an example of the fusion surface model with a specific choice of the input data $(X, x, \chi)$.


\subsubsection{Tensor Network Representation for Minimal Gapped Phases}
The ground state~\eqref{eq: minimal GS 2VecG} can be written in terms of a tensor network as follows:
\begin{equation}
\ket{\text{GS}; \mu} = \adjincludegraphics[valign = c, width = 2.5cm]{fig/minimal_G_PEPS.pdf}.
\label{eq: TN minimal 2VecG}
\end{equation}
Here, the physical leg on each plaquette takes values in $G$.
On the other hand, the virtual bond written in blue takes values in $K$.
The non-zero components of the local tensors in \eqref{eq: TN minimal 2VecG} are given by
\begin{equation}
\adjincludegraphics[valign = c, width = 2cm]{fig/minimal_G_PEPS_a.pdf} = \frac{1}{|K|} \delta_{k, (g^{(\mu)})^{-1}g},
\end{equation}
\begin{equation}
\adjincludegraphics[valign = c, width = 1.8cm]{fig/minimal_G_PEPS_Asub.pdf} = \lambda(k_i, k_{ij}, k_{jk}), \qquad
\adjincludegraphics[valign = c, width = 1.8cm]{fig/minimal_G_PEPS_Bsub.pdf} = \lambda(k_i, k_{ij}, k_{jk})^{-1}.
\end{equation}



\subsubsection{Non-minimal Gapped Phases}
\label{sec: G non-minimal phases}
A $G$-symmetric gapped phase is said to be non-minimal if it has a non-trivial topological order.
There are two types of such non-minimal gapped phases: one is chiral and the other is non-chiral.
In what follows, we will restrict our attention to non-chiral phases, i.e., gapped phases that admit gapped boundaries.

In the fusion surface model, a non-chiral gapped phase with $2\Vec_G$ symmetry is realized by choosing $B \in 2\Vec_G$ to be a general $G$-graded unitary fusion category:
\begin{equation}
B = \bigoplus_{g \in G} B_g.
\end{equation}
We suppose that $B$ is faithfully graded by a subgroup $K \subset G$, that is,
\begin{equation}
g \notin K ~ \Leftrightarrow ~ B_g = 0.
\end{equation}
The minimal gapped phase labeled by $(K, [\lambda])$ is included as a special case where $B = \Vec_K^{\lambda}$.

For the above choice of the algebra $B \in 2\Vec_G$, possible configurations of the dynamical variables of the model can be described as follows:
\begin{itemize}
\item The dynamical variables on the plaquettes are labeled by elements of $G$. These dynamical variables must satisfy the constraint
\begin{equation}
g_i^{-1} g_j \in K
\end{equation}
for any pair of adjacent plaquettes $i$ and $j$. A configuration of the dynamical variables on the plaquettes is denoted by $\{g_i \mid i \in P\}$.
\item For a given configuration $\{g_i \mid i \in P\}$, the dynamical variable on edge $[ij]$ takes values in the set of simple objects of $B_{g_{ij}}$, where $g_{ij} := g_i^{-1} g_j$. Each simple object $b_{ij} \in B_{g_{ij}}$ labels the vertical surface that ends on edge $[ij]$.\footnote{More precisely, the surface that ends on edge $[ij]$ is labeled by $D_2^{g_{ij}}[b_{ij}] \in 2\Vec_G$.} A configuration of the dynamical variables on the plaquettes and edges is denoted by $\{g_i, b_{ij} \mid i \in P,~ [ij] \in E\}$.
\item For a given configuration $\{g_i, b_{ij} \mid i \in P, ~ [ij] \in E\}$, the dynamical variable on vertex $[ijk]$ takes values in $\Hom_B(b_{ik}, b_{ij} \otimes b_{jk})$ or $\Hom_B(b_{ij} \otimes b_{jk}, b_{ik})$ depending on whether $[ijk]$ is in the $A$-sublattice or $B$-sublattice. A configuration of the dynamical variables on the plaquettes, edges, and vertices is denoted by
\begin{equation}
\{g_i, b_{ij}, \beta_{ijk} \mid i \in P, ~ [ij] \in E, ~ [ijk] \in V\}.
\label{eq: config non-minimal}
\end{equation}
\end{itemize} 
The Levin-Wen plaquette operator is trivial because $\End_{2\Vec_G}(D_2^g) \cong \Vec$ for all $g \in G$.
Thus, the state space is given by the vector space spanned by all possible configurations of the dynamical variables.
The state corresponding to the configuration~\eqref{eq: config non-minimal} is denoted by $\ket{\{g_i, b_{ij}, \beta_{ijk}\}}$.
Diagrammatically, this state can be written as
\begin{equation}
\ket{\{g_i, b_{ij}, \beta_{ijk}\}} = ~ \Ket{\adjincludegraphics[valign = c, width = 3.5cm]{fig/non_minimal_G_state.pdf}}.
\end{equation}
The labels on the vertices will often be omitted in order to avoid cluttering the diagram.
The symmetry operator $U_g$ acts on the above state as
\begin{equation}
U_g \ket{\{g_i, b_{ij}, \beta_{ijk}\}} = \ket{\{gg_i, b_{ij}, \beta_{ijk}\}}.
\end{equation}
As in the minimal gapped phases, the state space consists of multiple sectors labeled by left $K$-cosets in $G$:
\begin{equation}
\mathcal{H} = \bigoplus_{\mu = 1, 2, \cdots, |G/K|} \mathcal{H}^{(\mu)}.
\end{equation}
Here, each sector $\mathcal{H}^{(\mu)}$ is defined by
\begin{equation}
\mathcal{H}^{(\mu)} := \text{Span}\{\ket{g_i, b_{ij}, \beta_{ijk}} \mid g_i \in g^{(\mu)}K, ~ b_{ij} \in B_{g_{ij}}, ~ \beta_{ijk} \in \Hom_B(b_{ij} \otimes b_{jk}, b_{ik})\}.
\end{equation}
We note that the states in different sectors are related to each other by the symmetry action.

The Hamiltonian of the model is again given by the sum 
\begin{equation}
H = - \sum_{i \in P} \widehat{\mathsf{h}}_i,
\label{eq: Ham non-minimal}
\end{equation}
where $\widehat{\mathsf{h}}_i$ is defined by \eqref{eq: gapped Ham}.
Using the defining data of the separable algebra $B \in 2\Vec_G$ (cf. section~\ref{sec: Separable algebras in 2VecG}), we can write down the action of $\widehat{\mathsf{h}}_i$ explicitly as follows:
\begin{equation}
\begin{aligned}
\widehat{\mathsf{h}}_i \Ket{\adjincludegraphics[valign = c, width = 2.5cm]{fig/non_minimal_G_initial.pdf}} & = \sum_{g_5 \in G} \delta_{g_{45} \in K} \sum_{b_{45} \in B_{g_{45}}} \frac{d^b_{45}}{\mathcal{D}_B} \sum_{b_{15}, \cdots, b_{58}} \sum_{\beta_{145}, \cdots, \beta_{458}} \sum_{\beta_{125}, \cdots, \beta_{578}} \sqrt{\frac{d^b_{15} d^b_{56} d^b_{57}}{d^b_{14} d^b_{46} d^b_{47}}} \\
& ~\quad \sqrt{\frac{d^b_{24} d^b_{34} d^b_{48}}{d^b_{25} d^b_{35} d^b_{58}}} F_{1245}^{b; \beta} F_{2456}^{b; \beta} F_{4568}^{b; \beta} \overline{F}_{1345}^{b; \beta} \overline{F}_{3457}^{b; \beta} \overline{F}_{4578}^{b; \beta} \Ket{\adjincludegraphics[valign = c, width = 2.5cm]{fig/non_minimal_G_final.pdf}}.
\end{aligned}
\label{eq: local Ham non-minimal}
\end{equation}
The summations on the right-hand side are taken over all fusion channels $b_{i5} \in b_{i4} \otimes b_{45}$, $b_{5j} \in \overline{b_{45}} \otimes b_{4j}$, and all basis morphisms $\beta_{ijk} \in \Hom_{B}(b_{ij} \otimes b_{jk}, b_{ik})$.
More concisely, the above Hamiltonian can also be written as
\begin{equation}
\widehat{\mathsf{h}}_i = \sum_{k \in K} \sum_{b \in B_k} \frac{\dim(b)}{\mathcal{D}_B} \widehat{L}_i^{(b)},
\label{eq: hi_nom-min_loop}
\end{equation}
where the loop operator $\widehat{L}_i^{(b)}$ for $b \in B_k$ is defined by
\begin{equation}
\widehat{L}_i^{(b)} \Ket{\adjincludegraphics[valign = c, width = 2.75cm]{fig/non_minimal_G_initial.pdf}} = \Ket{\adjincludegraphics[valign = c, width = 3cm]{fig/non_minimal_G_loop.pdf}}.
\label{eq: loop operator}
\end{equation}
The loop on the right-hand side acts on the dynamical variables on the nearby edges by the fusion.
As in the minimal gapped phases, the above model can be embedded into a tensor product state space without breaking the symmetry.

The ground states of the Hamiltonian~\eqref{eq: Ham non-minimal} are obtained by applying the local commuting projectors~\eqref{eq: local Ham non-minimal} to generic states.
As in the case of the minimal gapped phases, we expect that each sector $\mathcal{H}^{(\mu)}$ has a unique ground state on an infinite plane.
Therefore, the model on an infinite plane has as many ground states as the number of left $K$-cosets in $G$.
The ground state in each sector $\mathcal{H}^{(\mu)}$ is given by
\begin{equation}
\ket{\text{GS}; \mu} = \prod_{i \in P} \widehat{\mathsf{h}}_i \ket{\{g_i = g^{(\mu)}, b_{ij} = \mathds{1}, \beta_{ijk} = \id\}},
\end{equation}
where $\ket{\{g_i = g^{(\mu)}, b_{ij} = \mathds{1}, \beta_{ijk} = \id\}}$ denotes the state where all plaquettes are labeled by the representative $g^{(\mu)} \in g^{(\mu)} K$, all edges are labeled by the unit object $\mathds{1} \in B$, and all vertices are labeled by the identity morphism $\id \in \Hom_B(\mathds{1}, \mathds{1}) \cong \Hom_B(\mathds{1} \otimes \mathds{1}, \mathds{1})$.
%A direct computation shows that the above ground state can be written explicitly as
The above ground state can be computed diagrammatically as
\begin{equation}
\begin{aligned}
\ket{\text{GS}; \mu} & = \sum_{\{k_i \in K\}} \sum_{\{b_i \in B_{k_i}\}} \prod_{i \in P} \frac{d^b_i}{\mathcal{D}_B} \adjincludegraphics[valign = c, width = 3.75cm]{fig/non_minimal_G_gs1.pdf}\\
& = \sum_{\{k_i \in K\}} \sum_{\{b_i \in B_{k_i}\}} \sum_{\{b_{ij} \in \overline{b_i} \otimes b_j\}}  \sum_{\{\beta_{ij}\}} \prod_{i \in P} \frac{d^b_i}{\mathcal{D}_B} \prod_{[ij] \in E} \sqrt{\frac{d^b_{ij}}{d^b_i d^b_j}} \adjincludegraphics[valign = c, width = 3.75cm]{fig/non_minimal_G_gs2.pdf}\,,
\end{aligned}
\end{equation}
where the dotted edges on the first line are labeled by $\mathds{1} \in B$, and $\beta_{ij} \in \Hom_B(\overline{b_i} \otimes b_j, b_{ij})$ on the second line are the morphisms at the vertices of the last diagram.
Removing the bubbles around the vertices via the $F$-move leads us to
\begin{equation}
\boxed{
\ket{\text{GS}; \mu} = \sum_{\{k_i \in K\}} \sum_{\{b_i \in B_{k_i}\}} \sum_{\{b_{ij}, \beta_{ij}, \beta_{ijk}\}} \prod_{i \in P} \frac{1}{\mathcal{D}_B} \prod_{[ijk]} \left(\frac{d^b_{ij} d^b_{jk}}{d^b_{ik}}\right)^{\frac{1}{4}} \prod_{[ijk]} (F_{ijk}^{b; \beta})^{s_{ijk}} \ket{\{g^{(\mu)}k_i, b_{ij}, \beta_{ijk}\}}.
}
\label{eq: non-minimal GS 2VecG}
\end{equation}
Here, the sign $s_{ijk}$ is defined by \eqref{eq: sijk}, and $F_{ijk}^{b; \beta}$ is defined by
\begin{equation}
F_{ijk}^{b; \beta} := (F^{b_i b_{ij} b_{jk}}_{b_k})_{(b_j; \beta_{ij}, \beta_{jk}), (b_{ik}; \beta_{ik}, \beta_{ijk})}.
\label{eq: Fijk}
\end{equation}
We note that \eqref{eq: non-minimal GS 2VecG} reduces to the ground states~\eqref{eq: minimal GS 2VecG} of the minimal gapped phase when $B = \Vec_K^{\lambda}$.
The symmetry operators act on the above ground states as
\begin{equation}
U_g \ket{\text{GS}; \mu} = \ket{\text{GS}; \nu},
\end{equation}
where $g \in g^{(\nu)}K(g^{(\mu)})^{-1}$.

When $B$ is faithfully graded by $G$ and is multiplicity-free, the above model agrees with the symmetry-enriched string-net model studied in \cite{Heinrich:2016wld, Cheng:2016aag}.
In particular, when $G$ is the trivial group, the above model reduces to the Levin-Wen model \cite{Levin:2004mi}.

\subsubsection{Tensor Network Representation for Non-minimal Gapped Phases}

The ground state~\eqref{eq: minimal GS 2VecG} can be written in terms of a tensor network.
In particular, when $B$ is multiplicity-free, the tensor network representation of the ground state~\eqref{eq: non-minimal GS 2VecG} is given by\footnote{When $B$ is not multiplicity-free, the model has the dynamical variables also on the vertices, which makes the tensor network representation slightly more complicated.}
\begin{equation}
\ket{\text{GS}; \mu} = \adjincludegraphics[valign = c, width = 3cm]{fig/non_minimal_G_PEPS.pdf}.
\label{eq: TN non-minimal 2VecG}
\end{equation}
Here, the physical leg on each plaquette takes values in $G$, while the physical leg on each edge takes values in the set of simple objects of $B$.
On the other hand, the virtual bond written in blue takes values in $K$, while the virtual bond written in orange takes values in the set of simple objects of $B$.
The non-zero components of the local tensors in \eqref{eq: TN non-minimal 2VecG} are given as follows:
\begin{equation}
\adjincludegraphics[valign = c, width = 1.75cm]{fig/non_minimal_G_PEPS_a.pdf} = \frac{1}{\mathcal{D}_B} \delta_{k, (g^{(\mu)})^{-1}g}, \qquad 
\adjincludegraphics[valign = c, width = 1.5cm]{fig/non_minimal_G_PEPS_ephys.pdf} = 1, \qquad
\adjincludegraphics[valign = c, width = 1.5cm]{fig/non_minimal_G_PEPS_evirt.pdf} = \delta_{b \in B_k},
\label{eq: non minimal PEPS edge}
\end{equation}
\begin{equation}
\adjincludegraphics[valign = c, width = 2cm]{fig/non_minimal_G_PEPS_Asub.pdf} = \left(\frac{d^b_{ij} d^b_{jk}}{d^b_{ik}}\right)^{\frac{1}{4}} F_{ijk}^b, \qquad
\adjincludegraphics[valign = c, width = 2cm]{fig/non_minimal_G_PEPS_Bsub.pdf} = \left(\frac{d^b_{ij} d^b_{jk}}{d^b_{ik}}\right)^{\frac{1}{4}} \overline{F}_{ijk}^b,
\end{equation}
where $\delta_{b \in B_k}$ in \eqref{eq: non minimal PEPS edge} is one if $b \in B_k$ and zero otherwise.
When $B = \Vec_K^{\lambda}$, \eqref{eq: TN non-minimal 2VecG} reduces to the tensor network representation~\eqref{eq: TN minimal 2VecG} of the ground states of the minimal gapped phase.
When $G$ is trivial, \eqref{eq: TN non-minimal 2VecG} reduces to the tensor network representation of the ground state of the Levin-Wen model based on $B$ \cite{Buerschaper:0809.2393, Gu:0809.2821}.
When $K = G$,  \eqref{eq: TN non-minimal 2VecG} reduces to the tensor network representation of the ground state of the $G$-enriched string-net model \cite{Williamson:2017uzx}.\footnote{Our tensors are slightly different from those in some references, e.g., \cite{Sahinoglu:2014upb, Williamson:2017uzx, Lootens:2020mso}, due to different conventions for the contraction of the tensors. The above references employ the convention that every closed loop in the tensor network involves the quantum dimension, while we use the standard convention that the closed loop of a virtual bond labeled by a fixed object evaluates to 1. \label{fn: tensor contraction}}



\subsection{Gapped Phases with $2\Vec_G^{\omega}$ Symmetry}
\label{sec: gapped phases with anomalous G symmetry}
Let us generalize the previous subsection to incorporate an anomaly $[\omega] \in H^4(G, \mathrm{U}(1))$.
We choose the input fusion 2-category $\mathcal{C}$ and the module 2-category $\mathcal{M}$ to be
\begin{equation}
\mathcal{C} = \mathcal{M} = 2\Vec_G^{\omega}.
\end{equation}
We consider the gapped phase specified by a $G$-graded $\omega$-twisted unitary fusion category $B \in 2\Vec_G^{\omega}$, which is faithfully graded by $K \subset G$.


\subsubsection{Minimal Gapped Phases}
A minimal gapped phase with $2\Vec_G^{\omega}$ symmetry is obtained by choosing separable algebra $B \in 2\Vec_G^{\omega}$ to be
\begin{equation}
B = \Vec_K^{\lambda},
\end{equation}
where $K$ is a subgroup of $G$ and $\lambda$ is a 3-cochain on $K$ that satisfies
\begin{equation}
d\lambda = \omega|_K^{-1}.
\label{eq: d lambda}
\end{equation}
The right-hand side is the restriction of $\omega$ to $K$.
The underlying object of $\Vec_K^{\lambda} \in 2\Vec_G^{\omega}$ is the direct sum $\bigoplus_{k \in K} D_2^k$ and the algebra structure on it is given by \eqref{eq: K m} and \eqref{eq: K mu}.
The consistency condition on the associativity 2-isomorphism $\mu$ follows from \eqref{eq: d lambda}.

When $B = \Vec_K^{\lambda}$, possible configurations of the dynamical variables on the lattice can be described as follows:
\begin{itemize}
\item The dynamical variables on the plaquettes are labeled by elements of $G$. These dynamical variables must satisfy
\begin{equation}
g_i^{-1} g_j \in K
\end{equation}
for any adjacent plaquettes $i$ and $j$.
\item There are no dynamical variables on the edges and vertices.
\end{itemize}
The Levin-Wen plaquette operator is trivial due to the equivalence $\End_{2\Vec_G^{\omega}} (D_2^g) \cong \Vec$ for all $g \in G$.
Therefore, the state space is given by the vector space spanned by all possible configurations of the dynamical variables.
The state corresponding to the configuration $\{g_i \mid i \in P\}$ is denoted by $\ket{\{g_i\}}$.
The symmetry operator $U_g$ acts on this state as
\begin{equation}
U_g \ket{\{g_i\}} = \prod_{[ijk] \in V} \omega(g, g_i, g_i^{-1}g_j, g_j^{-1}g_k)^{s_{ijk}} \ket{\{gg_i\}},
\end{equation}
where $s_{ijk}$ is defined by \eqref{eq: sijk}.
As in the case of $2\Vec_G$ symmetry, the state space can be decomposed into a direct sum
\begin{equation}
\mathcal{H} = \bigoplus_{\mu = 1, 2, \cdots, |G/K|} \mathcal{H}^{(\mu)},
\end{equation}
where each sector $\mathcal{H}^{(\mu)}$ is defined by
\begin{equation}
\mathcal{H}^{(\mu)} := \text{Span}\{\ket{g_i} \mid g_i \in g^{(\mu)} K\}.
\end{equation}
Here, $g^{(\mu)}$ is a representative of the left $K$-coset $g^{(\mu)} K$.
We note that the symmetry action permutes the above sectors.

The Hamiltonian is given by
\begin{equation}
H = -\sum_{i \in P} \widehat{\mathsf{h}}_i,
\end{equation}
where $\widehat{\mathsf{h}}_i$ is defined by \eqref{eq: gapped Ham}.
When $B = \Vec_K^{\lambda}$, the action of $\widehat{\mathsf{h}}_i$ can be computed as
\begin{equation}
\widehat{\mathsf{h}}_i ~ \Ket{\adjincludegraphics[valign = c, width = 2cm]{fig/minimal_gapped_G1.pdf}} = \frac{1}{|K|} \sum_{g_5 \in G} \delta_{g_{45} \in K} \frac{\lambda^g_{1245} \lambda^g_{2456} \lambda^g_{4568}}{\lambda^g_{1345} \lambda^g_{3457} \lambda^g_{4578}} \frac{\omega^g_{1245} \omega^g_{2456} \omega^g_{4568}}{\omega^g_{1345} \omega^g_{3457} \omega^g_{4578}} ~ \Ket{\adjincludegraphics[valign = c, width = 2cm]{fig/minimal_gapped_G2.pdf}},
\end{equation}
where $\lambda^g_{ijkl} := \lambda(g_{ij}, g_{jk}, g_{kl})$, $\omega^g_{ijkl} := \omega(g_i, g_{ij}, g_{jk}, g_{kl})$, $g_{ij} := g_i^{-1} g_j$, and $\delta_{g_{ij} \in K}$ is defined by \eqref{eq: g in K}.
The above model can be embedded into a tensor product state space without breaking the symmetry, just as we did in the case of non-anomalous symmetries.

As in the gapped phases with $2\Vec_G$ symmetry, the ground states on an infinite plane are in one-to-one correspondence with left $K$-cosets in $G$.
The ground state labeled by the left $K$-coset $g^{(\mu)} K$ is given by
\begin{equation}
\ket{\text{GS}; \mu} = \prod_{i \in P} \widehat{\mathsf{h}}_i \ket{\{g_i = g^{(\mu)}\}},
\end{equation}
where $\ket{\{g_i = g^{(\mu)}\}}$ is the state where all plaquettes are labeled by $g^{(\mu)}$.
By a direct computation, we find
\begin{equation}
\boxed{
\ket{\text{GS}; \mu} = \sum_{\{k_i \in K\}} \prod_{i \in P} \frac{1}{|K|} \prod_{[ijk] \in V} \omega(g^{(\mu)}, k_i, k_{ij}, k_{jk})^{s_{ijk}} \lambda(k_i, k_{ij}, k_{jk})^{s_{ijk}} \ket{\{g^{(\mu)} k_i\}},
}
\label{eq: minimal GS omega}
\end{equation}
where $k_{ij} := k_i^{-1} k_j$.
The derivation of the above equation will be explained in section~\ref{sec: Non-Minimal Gapped Phases omega}.
The symmetry operators act on the above ground states as
\begin{equation}
U_g \ket{\text{GS}; \mu} = \ket{\text{GS}; \nu},
\end{equation}
where $g \in g^{(\nu)}K(g^{(\mu)})^{-1}$.

\subsubsection{Tensor Network Representation for Minimal Gapped Phases}
The ground state~\eqref{eq: minimal GS omega} can be represented by the following tensor network:
\begin{equation}
\ket{\text{GS}; \mu} = \adjincludegraphics[valign = c, width = 2.5cm]{fig/minimal_G_PEPS.pdf}.
\label{eq: minimal GS PEPS omega}
\end{equation}
The physical leg on each plaquette takes values in $G$, while the virtual bond written in blue takes values in $K$.
The non-zero components of the local tensors in \eqref{eq: minimal GS PEPS omega} are given by
\begin{equation}
\adjincludegraphics[valign = c, width = 2cm]{fig/minimal_G_PEPS_a.pdf} = \frac{1}{|K|} \delta_{k, (g^{(\mu)})^{-1}g},
\end{equation}
\begin{equation}
\adjincludegraphics[valign = c, width = 1.8cm]{fig/minimal_G_PEPS_Asub.pdf} = \omega(g^{(\mu)}, k_i, k_{ij}, k_{jk}) \lambda(k_i, k_{ij}, k_{jk}),
\end{equation}
\begin{equation}
\adjincludegraphics[valign = c, width = 1.8cm]{fig/minimal_G_PEPS_Bsub.pdf} = \omega(g^{(\mu)}, k_i, k_{ij}, k_{jk})^{-1} \lambda(k_i, k_{ij}, k_{jk})^{-1}.
\end{equation}


\subsubsection{Non-Minimal Gapped Phases}
\label{sec: Non-Minimal Gapped Phases omega}
A non-minimal (non-chiral) gapped phase with $2\Vec_G^{\omega}$ symmetry is obtained by choosing the separable algebra $B \in 2\Vec_G^{\omega}$ to be a general $G$-graded $\omega$-twisted unitary fusion category
\begin{equation}
B = \bigoplus_{g \in G} B_g.
\end{equation}
We suppose that $B$ is faithfully graded by a subgroup $K \subset G$.
The non-minimal gapped phase reduces to a minimal gapped phase when $B = \Vec_K^{\lambda}$.

For a general $B$, possible configurations of the dynamical variables on the lattice can be described as follows:
\begin{itemize}
\item The dynamical variable $g_i$ on each plaquette $i$ takes values in $G$. For any pair of adjacent plaquettes $i, j \in P$, we have a constraint
\begin{equation}
g_i^{-1} g_j \in K.
\end{equation}
\item For a given configuration $\{g_i \mid i \in P\}$, the dynamical variable $b_{ij}$ on each edge $[ij]$ takes values in the set of simple objects of $B_{g_{ij}}$, where $g_{ij} := g_i^{-1} g_j$.
\item For a given configuration $\{g_i, b_{ij} \mid i \in P, [ij] \in E\}$, the dynamical variable on each vertex $[ijk]$ takes values in $\Hom_B(b_{ik}, b_{ij} \otimes b_{jk})$ or $\Hom_B(b_{ij} \otimes b_{jk}, b_{ik})$ depending on whether $[ijk]$ is in the $A$-sublattice or $B$-sublattice.
\end{itemize}
Since the Levin-Wen plaquette operator is trivial, the state space is given by the vector space spanned by all possible configurations of the above dynamical variables.
The state corresponding to a configuration $\{g_i, b_{ij}, \beta_{ijk} \mid i \in P,~ [ij] \in E,~ [ijk] \in V\}$ is written as
\begin{equation}
\ket{\{g_i, b_{ij}, \beta_{ijk}\}} = ~ \Ket{\adjincludegraphics[valign = c, width = 3.5cm]{fig/non_minimal_G_state.pdf}}.
\end{equation}
The symmetry operator $U_g$ acts on this state as
\begin{equation}
U_g \ket{g_i, b_{ij}, \beta_{ijk}} = \prod_{[ijk] \in V} \omega(g, g_i, g_i^{-1}g_j, g_j^{-1}g_k)^{s_{ijk}} \ket{\{gg_i, b_{ij}, \beta_{ijk}\}}.
\end{equation}
As in the case of $2\Vec_G$ symmetry, the state space can be decomposed into a direct sum
\begin{equation}
\mathcal{H} = \bigoplus_{\mu = 1, 2, \cdots, |G/K|} \mathcal{H}^{(\mu)},
\end{equation}
where each sector $\mathcal{H}^{(\mu)}$ is defined by
\begin{equation}
\mathcal{H}^{(\mu)} := \text{Span}\{\ket{g_i, b_{ij}, \beta_{ijk}} \mid g_i \in g^{(\mu)}K, ~ b_{ij} \in B_{g_{ij}}, ~ \beta_{ijk} \in \Hom_B(b_{ij} \otimes b_{jk}, b_{ik})\}.
\end{equation}
These sectors are permuted by the symmetry action.

The Hamiltonian is again given by
\begin{equation}
H = - \sum_{i \in P} \widehat{\mathsf{h}}_i,
\end{equation}
where $\widehat{\mathsf{h}}_i$ is defined by \eqref{eq: gapped Ham}.
For a general $B$, the action of $\widehat{\mathsf{h}}_i$ can be computed as
\begin{equation}
\begin{aligned}
&\quad \widehat{\mathsf{h}}_i \Ket{\adjincludegraphics[valign = c, width = 2.5cm]{fig/non_minimal_G_initial.pdf}} \\
&= \sum_{g_5 \in G} \delta_{g_{45} \in K} \sum_{b_{45} \in B_{g_{45}}} \frac{d^b_{45}}{\mathcal{D}_B} \sum_{b_{15}, \cdots, b_{58}} \sum_{\beta_{145}, \cdots, \beta_{458}} \sum_{\beta_{125}, \cdots, \beta_{578}} \sqrt{\frac{d^b_{15} d^b_{56} d^b_{57}}{d^b_{14} d^b_{46} d^b_{47}}} \sqrt{\frac{d^b_{24} d^b_{34} d^b_{48}}{d^b_{25} d^b_{35} d^b_{58}}} \\
&~\quad \frac{\omega^g_{1245} \omega^g_{2456} \omega^g_{4568}}{\omega^g_{1345} \omega^g_{3457} \omega^g_{4578}} F_{1245}^{b; \beta} F_{2456}^{b; \beta} F_{4568}^{b; \beta} \overline{F}_{1345}^{b; \beta} \overline{F}_{3457}^{b; \beta} \overline{F}_{4578}^{b; \beta} \Ket{\adjincludegraphics[valign = c, width = 2.5cm]{fig/non_minimal_G_final.pdf}},
\end{aligned}
\end{equation}
where $\omega^g_{ijkl} := \omega(g_i, g_{ij}, g_{jk}, g_{kl})$.
More concisely, the above Hamiltonian can be expressed as
\begin{equation}
\widehat{\mathsf{h}}_i = \sum_{k \in K} \sum_{b \in B_k} \frac{\dim(b)}{\mathcal{D}_B} \widehat{L}_i^{(b)},
\end{equation}
where the loop operator $\widehat{L}_i^{(b)}$ for $b \in B_k$ is defined by
\begin{equation}
\widehat{L}_i^{(b)} \Ket{\adjincludegraphics[valign = c, width = 2.75cm]{fig/non_minimal_G_initial.pdf}} = \Ket{\adjincludegraphics[valign = c, width = 3cm]{fig/non_minimal_G_loop.pdf}}.
\end{equation}
On the right-hand side, the fusion of the loop and the nearby edges is computed by using the following modified $F$-move
\begin{equation}
\boxed{
\adjincludegraphics[valign = c, width = 2.25cm]{fig/modified_F1.pdf}= \omega^g_{ijkl} \sum_{b_{jl}} \sum_{\beta_{ijl}, \beta_{jkl}} F^{b; \beta}_{ijkl} \adjincludegraphics[valign = c, width = 2.25cm]{fig/modified_F2.pdf},
}
\label{eq: modified F}
\end{equation}
where the 2d regions are labeled by $g_i, g_j, g_k, g_l \in G$.
We note that the modified $F$-symbols $\omega^g_{ijkl} F^{b; \beta}_{ijkl}$ satisfy the ordinary pentagon equation due to the twisted pentagon equation for the $F$-symbols.
The above model can be embedded into a tensor product state space without breaking the symmetry, as in the case of gapped phases with non-anomalous symmetries.

We expect that the ground state of the above model on an infinite plane is unique in each sector $\mathcal{H}^{(\mu)}$.
Thus, the ground states on an infinite plane are in one-to-one correspondence with left $K$-cosets in $G$.
The ground state labeled by the left $K$-coset $g^{(\mu)} K$ is given by
\begin{equation}
\ket{\text{GS}; \mu} = \prod_{i \in P} \widehat{\mathsf{h}}_i \ket{\{g_i = g^{(\mu)}, b_{ij} = \mathds{1}, \beta_{ijk} = \id\}},
\end{equation}
where $g^{(\mu)}$ is a representative of $g^{(\mu)} K$.
The right-hand side is computed in the same way as \eqref{eq: non-minimal GS 2VecG}.
Recalling that the $F$-symbols are modified as in \eqref{eq: modified F}, we find
\begin{equation}
\boxed{
\begin{aligned}
\ket{\text{GS}; \mu} &= \sum_{\{k_i, b_i, b_{ij}, \beta_{ij}, \beta_{ijk}\}} \prod_{i \in P} \frac{1}{\mathcal{D}_B} \prod_{[ijk] \in V} \left(\frac{d^b_{ij} d^b_{jk}}{d^b_{ik}}\right)^{\frac{1}{4}} \\
&\quad \prod_{[ijk] \in V} \omega(g^{(\mu)}, k_i, k_{ij}, k_{jk})^{s_{ijk}} (F_{ijk}^{b; \beta})^{s_{ijk}} \ket{\{g^{(\mu)}k_i, b_{ij}, \beta_{ijk}\}},
\end{aligned}
}
\label{eq: non-minimal GS omega}
\end{equation}
where $k_{ij} := k_i^{-1} k_j$.
The summation on the right-hand side is taken over $k_i \in K$, $b_i \in B_{k_i}$, $b_{ij} \in \overline{b_i} \otimes b_j$, $\beta_{ij} \in \Hom_B(\overline{b_i} \otimes b_j, b_{ij})$, and $\beta_{ijk} \in \Hom_B(b_{ij} \otimes b_{jk}, b_{ik})$.
The above equation reduces to the ground state~\eqref{eq: minimal GS omega} of the minimal gapped phase when $B = \Vec_K^{\lambda}$.
The symmetry operators act on the above ground states as
\begin{equation}
U_g \ket{\text{GS}; \mu} = \ket{\text{GS}; \nu},
\end{equation}
where $g \in g^{(\nu)} K (g^{(\mu)})^{-1}$.

\subsubsection{Tensor Network Representation for Non-Minimal Gapped Phases}
When $B$ is multiplicity-free, the ground state~\eqref{eq: non-minimal GS omega} can be represented by the following tensor network:
\begin{equation}
\ket{\text{GS}; \mu} = \adjincludegraphics[valign = c, width = 3cm]{fig/non_minimal_G_PEPS.pdf}.
\label{eq: non-minimal GS PEPS omega}
\end{equation}
The physical leg on each plaquette takes values in $G$, while the physical leg on each edge takes values in the set of simple objects of $B$.
On the other hand, the blue and orange bonds take values in $K$ and the set of simple objects of $B$, respectively.
The non-zero components of the local tensors in \eqref{eq: non-minimal GS PEPS omega} are given by
\begin{equation}
\adjincludegraphics[valign = c, width = 1.75cm]{fig/non_minimal_G_PEPS_a.pdf} = \frac{1}{\mathcal{D}_B} \delta_{k, (g^{(\mu)})^{-1}g}, \qquad 
\adjincludegraphics[valign = c, width = 1.5cm]{fig/non_minimal_G_PEPS_ephys.pdf} = 1, \qquad
\adjincludegraphics[valign = c, width = 1.5cm]{fig/non_minimal_G_PEPS_evirt.pdf} = \delta_{b \in B_k},
\end{equation}
\begin{equation}
\adjincludegraphics[valign = c, width = 2cm]{fig/non_minimal_G_PEPS_Asub.pdf} = \left(\frac{d^b_{ij} d^b_{jk}}{d^b_{ik}}\right)^{\frac{1}{4}} \omega(g^{(\mu)}, k_i, k_{ij}, k_{jk}) F_{ijk}^b,
\end{equation}
\begin{equation}
\adjincludegraphics[valign = c, width = 2cm]{fig/non_minimal_G_PEPS_Bsub.pdf} = \left(\frac{d^b_{ij} d^b_{jk}}{d^b_{ik}}\right)^{\frac{1}{4}} \omega(g^{(\mu)}, k_i, k_{ij}, k_{jk})^{-1} \overline{F}_{ijk}^b.
\end{equation}


\subsection{Gapped Phases with All-Boson Fusion 2-Category Symmetries}
\label{sec: Gapped phases of the gauged model}
In this subsection, we consider the gapped phases obtained by the generalized gauging of the gapped phases with $2\Vec_G^{\omega}$ symmetry.
We will provide concrete lattice Hamiltonians for these gapped phases and write down their ground states explicitly using tensor networks.

\subsubsection{Minimal Gapped Phases}
\label{sec:MinGappesPh}

Let us first discuss the non-minimal gauging of minimal gapped phases with $2\Vec_G^{\omega}$ symmetry.
A minimal gapped phase is specified by a separable algebra of the form\footnote{A minimal gapped phase of the gauged model generally has topological order, which is in contrast to the minimal gapped phases with $2\Vec_G^{\omega}$ symmetry.}
\begin{equation}
B = \Vec_K^{\lambda} \in 2\Vec_G^{\omega}.
\end{equation}
On the other hand, the generalized gauging is specified by an arbitrary $G$-graded $\omega$-twisted unitary fusion category $A \in 2\Vec_G^{\omega}$.

In the gauged model, possible configurations of the dynamical variables can be described as follows:
\begin{itemize}
\item The dynamical variables on the plaquettes are labeled by the representatives of the connected components of ${}_A (2\Vec_G^{\omega})$, which are given  by
\begin{equation}
M^g = A \square D_2^{g}, \qquad g \in S_{H \backslash G}.
\label{eq: representatives}
\end{equation}
We recall that $S_{H \backslash G}$ denotes the set of representatives of right $H$-cosets in $G$.
A configuration of these dynamical variables is denoted by $\{g_i \mid i \in P\}$, where $g_i \in S_{H \backslash G}$.
\item The dynamical variables on the edges are labeled by simple objects of $A^{\text{rev}}$.
The dynamical variable $a_{ij}$ on edge $[ij]$ must obey the constraint 
\begin{equation}
g_i^{-1} h_{ij} g_j \in K,
\label{eq: plaquette constraint}
\end{equation}
where $h_{ij} \in H$ is the grading of $a_{ij}$, that is, $a_{ij} \in A_{h_{ij}}^{\text{rev}}$. 
This constraint comes from the fact that the vertical surface below edge $[ij]$ is labeled by $D_2^{g_i^{-1}h_{ij}g_j} \in 2\Vec_G^{\omega}$, which needs to be contained in $B = \Vec_K^{\lambda}$.
\item For a given configuration $\{g_i, a_{ij} \mid i \in P, [ij] \in E\}$, the dynamical variable on vertex $[ijk]$ takes values in $\Hom_{A^{\text{rev}}}(a_{ik}, a_{ij} \otimes a_{jk})$ or $\Hom_{A^{\text{rev}}}(a_{ij} \otimes a_{jk}, a_{ik})$ depending on whether $[ijk]$ is in the A-sublattice or $B$-sublattice.
\end{itemize}
A configuration of all dynamical variables on the lattice is denoted by
\begin{equation}
\{g_i, a_{ij}, \alpha_{ijk} \mid i \in P,~ [ij] \in E,~ [ijk] \in V\}.
\end{equation}
The state corresponding to the above configuration is written as
\begin{equation}
\ket{\{g_i, a_{ij}, \alpha_{ijk}\}} = ~\Ket{\adjincludegraphics[valign = c, width = 3.5cm]{fig/gauged_state_rev.pdf}}.
\end{equation}
The state space of the gauged model is then given by
\begin{equation}
\mathcal{H}_{\text{gauged}} = \widehat{\pi}_{\text{LW}} \mathcal{H}^{\prime}_{\text{gauged}},
\label{eq: gauged state space}
\end{equation}
where $\mathcal{H}^{\prime}_{\text{gauged}}$ is the vector space spanned by all possible configurations of the dynamical variables, and $\widehat{\pi}_{\text{LW}} := \prod_{i \in P} \widehat{B}_i$ is the product of the Levin-Wen plaquette operators~\eqref{eq: gauged LW} based on $A_e^{\text{rev}}$.
The state space~\eqref{eq: gauged state space} can be decomposed into the direct sum
\begin{equation}
\mathcal{H}_{\text{gauged}} = \bigoplus_{\mu = 1, 2, \cdots, |H \backslash G / K|} \mathcal{H}_{\text{gauged}}^{(\mu)},
\end{equation}
where each sector $\mathcal{H}_{\text{gauged}}^{(\mu)}$ consists of states such that all plaquettes are labeled by elements of the same $(H, K)$-double coset $Hg^{(\mu)}K$.
Here, $g^{(\mu)} \in G$ is a representative of the double coset $Hg^{(\mu)}K$.

The Hamiltonian of the gauged model is given by
\begin{equation}
H_{\text{gauged}} = - \sum_i \widehat{\mathsf{h}}_i,
\end{equation}
where each term $\widehat{\mathsf{h}}_i$ is defined by \eqref{eq: gapped Ham}.
A direct computation shows that $\widehat{\mathsf{h}}_i$ acts on a state as
\begin{equation}
\begin{aligned}
\widehat{\mathsf{h}}_i \Ket{\adjincludegraphics[valign = c, width = 3cm]{fig/gauged_state_initial_rev.pdf}}
&= \frac{1}{|K|} \sum_{g_5 \in S_{H \backslash G}} \sum_{h_{45} \in H} \delta_{g_{45}^h \in K} \frac{\lambda^{g; h}_{1245} \lambda^{g; h}_{2456} \lambda^{g; h}_{4568}}{\lambda^{g; h}_{1345} \lambda^{g; h}_{3457} \lambda^{g; h}_{4578}} \frac{\Omega^{g; h}_{1345} \Omega^{g; h}_{3457} \Omega^{g; h}_{4578}}{\Omega^{g; h}_{1245} \Omega^{g; h}_{2456} \Omega^{g; h}_{4568}} \\
&\quad \sum_{a_{45} \in A_{h_{45}}^{\text{rev}}} \frac{d^a_{45}}{\mathcal{D}_{A_{h_{45}}}} \sum_{a_{15}, \cdots a_{58}} ~ \sum_{\alpha_{145}, \cdots, \alpha_{458}} ~ \sum_{\alpha_{125}, \cdots, \alpha_{578}}
\overline{F}_{1245}^{a; \alpha} \overline{F}_{2456}^{a; \alpha} \overline{F}_{4568}^{a; \alpha} \\
& \quad F_{1345}^{a; \alpha} F_{3457}^{a; \alpha} F_{4578}^{a; \alpha} \sqrt{\frac{d^a_{15} d^a_{56} d^a_{57}}{d^a_{14} d^a_{46} d^a_{47}}} \sqrt{\frac{d^a_{24} d^a_{34} d^a_{48}}{d^a_{25} d^a_{35} d^a_{58}}} \Ket{\adjincludegraphics[valign = c, width = 3cm]{fig/gauged_state_final_rev.pdf}},
\end{aligned}
\label{eq: gauged minimal phase}
\end{equation}
where $g_{ij}^h := g_i^{-1} h_{ij} g_j$, $\lambda^{g; h}_{ijkl} := \lambda(g_{ij}^h, g_{jk}^h, g_{kl}^h)$, and $\Omega^{g; h}_{ijkl}$ is defined by \eqref{eq: Omega}.
We recall that $g_{ij}^h \in K$ due to the constraint~\eqref{eq: plaquette constraint}.

On an infinite plane, we expect that the Hamiltonian~\eqref{eq: gauged minimal phase} has a unique ground state $\ket{\text{GS}; \mu}$ in each sector $\mathcal{H}_{\text{gauged}}^{(\mu)}$.
The ground state $\ket{\text{GS}; \mu}$ is obtained by applying the projector $\prod_i \widehat{\mathsf{h}}_i$ to a generic state in the same sector.
Concretely, we have
\begin{equation}
\ket{\text{GS}; \mu} = \prod_i \widehat{\mathsf{h}}_i \ket{\{g_i = g^{(\mu)}, a_{ij} = \mathds{1}_A, \alpha_{ijk} = \id_{\mathds{1}_A}\}},
\end{equation}
where $\{g_i = g^{(\mu)}, a_{ij} = \mathds{1}_A, \alpha_{ijk} = \id_{\mathds{1}_A}\}$ denotes the configuration where all plaquettes are labeled by $M^{g^{(\mu)}}$ and all edges and vertices are labeled by the unit object of $A$ and its identity morphism, respectively.
A direct computation shows that $\ket{\text{GS}; \mu}$ can be written explicitly as
\begin{equation}
\label{eq: gauged minimal GS}
\boxed{
\begin{aligned}
\ket{\text{GS}; \mu} 
&= \sum_{\{g_i \in S_{H \backslash G}\}} \sum_{\{k_i \in K\}} \sum_{\{h_i \in H\}} \prod_i \frac{1}{|K|} \delta_{k_i, (g^{(\mu)})^{-1} h_i g_i} \prod_{[ijk]} \lambda(k_i, k_{ij}, k_{jk})^{s_{ijk}} (\overline{\Omega}^{g; h}_{ijk; \mu})^{s_{ijk}}\\
& \quad ~  \sum_{\{a_i \in A_{h_i}^{\text{rev}}\}} \sum_{\{a_{ij}, \alpha_{ij}, \alpha_{ijk}\}} \prod_i \frac{1}{\mathcal{D}_{A_{h_i}}} \prod_{[ijk]} \left( \frac{d^a_{ij} d^a_{jk}}{d^a_{ik}} \right)^{\frac{1}{4}} (\overline{F}_{ijk}^{a; \alpha})^{s_{ijk}} \ket{\{g_i, a_{ij}, \alpha_{ijk}\}},
\end{aligned}
}
\end{equation}
where $k_{ij} := k_i^{-1}k_j$, $h_{ij} := h_i^{-1} h_j$, and $\overline{\Omega}^{g; h}_{ijk; \mu}$ is defined by
\begin{equation}
\boxed{
\overline{\Omega}^{g; h}_{ijk; \mu} := (\Omega^{g; h}_{ijk; \mu})^{-1}, \qquad \Omega^{g; h}_{ijk; \mu} := \frac{\omega(h_i, h_{ij}, h_{jk}, g_k) \omega(h_i, g_i, g^h_{ij}, g^h_{jk})}{\omega(h_i, h_{ij}, g_j, g^h_{jk}) \omega(g^{(\mu)}, (g^{(\mu)})^{-1}h_ig_i, g^h_{ij}, g^h_{jk})}.
}
\label{eq: Omega ijk mu}
\end{equation}
We note that $\Omega^{g; h}_{ijk; \mu}$ reduces to $\Omega^{g; h}_{ijk}$ defined by \eqref{eq: Omega ijk} when $g^{(\mu)} = e$.
The last summation on the right-hand side of \eqref{eq: gauged minimal GS} is taken over $a_{ij} \in \overline{a_i} \otimes a_j$, $\alpha_{ij} \in \Hom_A(\overline{a_i} \otimes a_j, a_{ij})$, and $\alpha_{ijk} \in \Hom_A(a_{ij} \otimes a_{jk}, a_{ik})$.
The derivation of \eqref{eq: gauged minimal GS} will be explained in section~\ref{sec:NonMiniPh}.


