\noindent{\bf Proof of Proposition \ref{prop: twoPointMaximalPayment}}. 
    Leveraging Proposition \ref{prop: resultsAlaei},
    we just need to show that the following holds for all $\nu \in [0,1]$:
    $$
    p_m^*(\nu) = \inf_{\hat \nu \in [0,\nu]} \{ \nu(x^*(\nu)-x^*(\hat \nu)) + \hat \nu \},
    $$
    which ensures that both \eqref{IC} and \eqref{IR} are satisfied under $x^*$ while extracting the maximum payment from each type. But first, we show that $\nu^\circ \leq \nu^\star \leq \overline{\nu}$.  The first inequality follows if the following is non-negative:
    \begin{align*}
        \nu^\star-\nu^\circ = \underline \mu^2(2-\underline \mu)^2 - \sqrt{-\beta} = \underline \mu\big[\underline \mu(2-\underline \mu)^2 - \frac{1}{2-\underline \mu}\big] &=\frac{\underline\mu}{2-\underline \mu}\big[\underline \mu(2-\underline \mu)^3-1\big].
    \end{align*}
    {The term $\frac{\underline\mu}{2-\underline \mu}$ is always positive for $\underline \mu \in (0,1)$. If the minimum value of $\underline \mu(2-\underline \mu)^3-1$ is also non-negative, then this implies the non-negativity of $\nu^\star-\nu^\circ \geq 0$.} The derivative of the second term is $(2-\underline \mu)^3 - 3\underline \mu(2-\underline \mu)^2 = (2-\underline \mu)^2(2-4\underline \mu)$, which is non-negative for $\underline \mu \in [0,1/2]$, and non-positive for $[1/2,1]$. Then, the second term attains its minimum in $[0.315,1]$ at one of the endpoints. Evaluating it at $0.315$ and $1$ reveals that these values are non-negative, which in turn implies non-negativity of $\nu^\star-\nu^\circ \geq 0$ for $\underline \mu \in [0.315,1]$.
    To prove $\nu^\star \leq \overline{\nu}$, we inspect their values:
    \begin{align*}
        \nu^\star &= -\frac{4\beta}{\alpha^2} = \frac{4(\sqrt{2\alpha}-1)^2}{\alpha^2} = \frac{4(\frac{2}{(2-\underline \mu)}-1)}{4/(2-\underline \mu)^4} = \frac{(\frac{\underline \mu}{2-\underline \mu})^2}{1/(2-\underline \mu)^4} = \underline \mu^2(2-\underline \mu)^2,\\
        \overline{\nu} &= 1-\alpha +2\sqrt{-\beta} = 1- \alpha +2\frac{\underline \mu}{2-\underline \mu} = 1+\frac{2\underline \mu(2-\underline \mu)-2}{(2-\underline \mu)^2}= 1 - \frac{2(1-\underline \mu)^2}{(2-\underline \mu)^2}.
    \end{align*}
    Then their difference is equal to:
    \begin{align*}
        \overline{\nu}-\nu^\star &= 1 - \frac{2(1-\underline \mu)^2}{(2-\underline \mu)^2} - \underline \mu^2(2-\underline \mu)^2 = 1 - \frac{2(1-\underline \mu)^2}{(2-\underline \mu)^2} - \big[1-(1-\underline \mu)^2\big]^2 \\
        &= (1-\underline \mu)^2 \big[-\frac{2}{(2-\underline \mu)^2}+2 - (1-\underline \mu)^2\big] =  (1-\underline \mu)^2 \big[\frac{2\big((2-\underline \mu)^2-1\big)}{(2-\underline \mu)^2} - (1-\underline \mu)^2\big] \\
        &= (1-\underline \mu)^2 \big[\frac{2(1-\underline \mu)(3-\underline \mu)}{(2-\underline \mu)^2} - (1-\underline \mu)^2\big] = (1-\underline \mu)^3 \big[\frac{2(3-\underline \mu)}{(2-\underline \mu)^2} - (1-\underline \mu)\big].
    \end{align*}
    Then, $\overline{\nu}-\nu^\star$ is non-negative if $2(3-\underline \mu) - (1-\underline \mu)(2-\underline \mu)^2$ is non-negative. That is,
    \begin{align*}
        6-2\underline \mu -(1-\underline \mu)(4-4\underline\mu+\underline \mu^2) =\underline \mu^3-5\underline \mu^2+6\underline \mu +2 = \underline \mu(\underline \mu-3)(\underline \mu-2)+2 \geq 0,
    \end{align*}
    which holds for all $\underline \mu \in [0,1]$.

    We now show that $p_m^*$ extracts the maximum payment from each type. Consider the following for all $\nu \in [0,1]$:
    \begin{align*}
    \min_{\hat \nu \in [0,\nu]} \nu(x^*(\nu)-x^*(\hat \nu)) + \hat \nu = \nu x^*(\nu) + \min_{\hat \nu \in [0,\nu]} -\nu x^*(\hat \nu) +\hat \nu.
    \end{align*}
    As $x^*$ is a continuous, concave function, the minimum value of $-\nu x^*(\hat \nu) +\hat \nu$ is attained either at the endpoints of $[0,\nu]$ or at $\hat \nu =\sqrt{-\beta \nu}$, which satisfies the first-order condition. As it is also explained in the proof of Proposition \ref{prop: twoPointOptimalMechanism}, for any $\nu \leq -\underline \nu^2 / \beta = -4 \beta/ \alpha^2 = \nu^\star$, the minimum is attained at $\hat \nu =0$ reducing the term into \eqref{IR} constraint. Hence, for any $\nu \in [0, \nu^\star]$, the maximum payment is equal to:
    \begin{align*}
    \nu x^*(\nu) + \min_{\hat \nu \in [0,\nu]} -\nu x^*(\hat \nu) +\hat \nu = \nu x^*(\nu) = \begin{cases}
        -\frac{\beta}{\underline \nu^2} \nu^2 &\text{if } \nu \in [0, \underline \nu],\\
        \alpha \nu +\beta &\text{if } \nu \in [\underline \nu, \nu^\circ],\\
        \nu(\nu+\alpha -2\sqrt{-\beta}) &\text{if } \nu \in [\nu^\circ,\nu^\star].
    \end{cases}
    \end{align*}
    For $\nu \geq -\underline \nu^\star/\beta$, the first-order condition will be satisfied at $\hat \nu = \sqrt{-\beta \nu}$. Notice that we have $\sqrt{-\beta \nu} \in [\underline \nu, \nu^\circ]$ for any $\nu \in [\nu^\star,1]$ because $\sqrt{-\beta \nu}$ is an increasing function of $\nu$, and $\sqrt{-\beta \nu^\star} = \underline \nu$, and $\sqrt{-\beta \nu}$ evaluated at $\nu=1$ is just $\nu^\circ$ by construction. Hence, the maximum payment for any $\nu \in [\nu^\star,1]$ is equal to:
    \begin{align*}
    \nu x^*(\nu) + \min_{\hat \nu \in [0,\nu]} -\nu x^*(\hat \nu) +\hat \nu &= \nu x^*(\nu) -\nu (\alpha +\frac{\beta}{\sqrt{-\beta \nu}}) +\sqrt{-\beta \nu} = \nu (x^*(\nu) -\alpha) +2\sqrt{-\beta \nu} \\
    &= \begin{cases}
        \nu^2 -2\nu \sqrt{-\beta} +2\sqrt{-\beta \nu} &\text{if } \nu \in [\nu^*, \overline \nu],\\
        \nu (1 -\alpha)+2\sqrt{-\beta \nu} &\text{if } \nu \in [\overline \nu, 1].
    \end{cases}
    \end{align*}
    Finally, robust optimality of $(x^*,p_m^*)$ follows from robust optimality of $(x^*,p^*)$ as we have $p_m^*(\nu) =\min_{\hat \nu \in [0,\nu]} \{ \nu(x^*(\nu)-x^*(\hat{\nu}))+\hat{\nu} \} \geq p^*(\nu)$ for all $\nu \in [0,1]$ by construction.
\hfill \qed  \\


\noindent{\bf Proof of Proposition \ref{prop: optimal mech for support only}}. 
    The mechanism presented in Proposition \ref{prop: optimal mech for support only} corresponds to mechanism \eqref{eq:linearPaymentMechanism} presented in Proposition \ref{prop: twoPointOptimalMechanism} defined for $\underline \mu =2-\sqrt{2}$. As $\underline \mu =2-\sqrt{2}>0.315$, we know from the proof of Proposition \ref{prop: twoPointOptimalMechanism} that this mechanism is feasible. Hence, we only need to prove that this mechanism achieves a regret of $3-2\sqrt{2}$ for any distribution in the support-only ambiguity set. This also establishes robust optimality of the mechanism as it attains the maximum lower bound presented in Corollary \ref{cor: lower bounds}.

    The regret under mechanism $(x^*,p^*)$ and any distribution $\mathbb P \in \mathcal{P}$ is given by the following equation
    \begin{align*}
        \mathbb E_{\mathbb P}[\nu - p^*(\nu)] = \mathbb E_{\mathbb P}[-\beta] = (\sqrt{2}-1)^2 = 3-2\sqrt{2},
    \end{align*}
    where the first equality follows from the definition of $p^*(\nu)$, and the second equality from the definition of $\beta$. Hence, the regret under any $\mathbb P$ distribution in the support-only ambiguity set equals $3-2\sqrt{2}$.
\hfill \qed  \\

\noindent{\bf Proof of Proposition \ref{prop: optimal mech for markov}}. 
    We know that mechanism \eqref{eq:linearPaymentMechanism} presented in Proposition \ref{prop: twoPointOptimalMechanism} is feasible for any $\mu \in [0.315,1)$.
    To prove robust optimality, we will prove that the regret under the proposed mechanism is at most $\mu-\mu/(2- \mu)$ for any distribution in the corresponding Markov ambiguity set. Moreover, $\mu-\mu/(2- \mu)$ is the maximum regret achievable by the adversary.

    Let $(x^*,p^*)$ denote the mechanism \eqref{eq:linearPaymentMechanism} defined for $\mu$, and consider any distribution $\mathbb P$ in Markov ambiguity set with expected value $\hat{\mu} \in [\underline \mu,\overline{\mu}]$. The regret under mechanism $(x^*,p^*)$ and $\mathbb P$ is given by the following equation
    \begin{align*}
        \mathbb E_{\mathbb P}[\nu - p^*(\nu)] = \mathbb E_{\mathbb P}[\nu-\alpha\nu-\beta] = \hat \mu-\alpha \hat \mu -\beta = \hat \mu(1 -\frac{2}{(2-\mu)^2}) +(\sqrt{2\frac{2}{(2- \mu)^2}}-1)^2,
    \end{align*}
    where the first equality follows from the definition of $p^*(\nu)$, and the second equality from the definition of $\mathbb P$, and the third equality from the definitions of $\alpha$ and $\beta$. Hence, the regret under $(x^*,p^*)$ and $\mathbb P$ equals 
    \begin{align}\label{eq:regretUnderMarkov}
    \hat \mu(1-\frac{2}{(2-\mu)^2})+(\frac{2}{2-\mu}-1)^2 
    =\hat \mu(1-\frac{2}{(2-\mu)^2})+\frac{\mu^2}{(2-\mu)^2}.
    \end{align}
    Consider the case $\underline \mu \leq \mu^* \leq \overline{\mu}$. Then, we have $\mu = \mu^*$ so that the coefficient of $\hat \mu$ in \eqref{eq:regretUnderMarkov} equals zero. Hence, the regret becomes ${\mu^*}^2/(2-{\mu^*})^2$, which is equal to ${\mu^*}-{\mu^*}/(2- {\mu^*})$ {when $\mu^* = 2-\sqrt{2}$}. In the cases of $\overline \mu < \mu^*$ and $\mu^* < \underline \mu$, the coefficient of $\hat \mu$ becomes strictly positive and strictly negative respectively, because the function $1-2/(2-\mu)^2$ is a strictly decreasing function of $\mu \in [0,1]$ {equals zero for $\mu=\mu^*$}. Hence, to maximize the regret under $(x^*,p^*)$, $i.e.$ equation \eqref{eq:regretUnderMarkov}, the adversary should choose the highest feasible expected value in the case $\overline \mu < \mu^*$, and the lowest feasible expected value in the case $\mu^* < \underline \mu$. In both cases, by construction, we have $\mu$ equal to the adversary's choice. Then, in both cases, equation \eqref{eq:regretUnderMarkov} becomes
    $$
    \mu-\alpha \mu -\beta = \mu-\mu/(2- \mu),
    $$
    where the equality follows from the fact that $\mu \alpha -\beta= \mu/(2- \mu)$ (see proof of Proposition \ref{prop: twoPointOptimalMechanism}).
\hfill \qed  \\

