\end{equation}
He also established an upper bound for the
product of two operators $T,S\in {\mathcal{B}}_{A}({\mathcal{H}
})$ as
\begin{equation}
\omega _{A}^{n}(S^{\sharp _{A}}T)\leq \frac{1}{2} \left\Vert \left( T^{\sharp
_{A}}T\right) ^{n}+\left( S^{\sharp _{A}}S\right) ^{n} \right\Vert _{A} \quad \text{ for
all }n\in 
%TCIMACRO{\U{2115} }%
%BeginExpansion
\mathbb{N}
%EndExpansion
\text{.}  \label{6}
