\end{definition}

We also recall here the commuting $n$-tuple operators.

\begin{definition}
Let $\mathbf{T=}\left( T_{1},...,T_{n}\right) \in {\mathcal{B}}\left( {
\mathcal{H}}\right) ^{n}$ be an $n$-tuple. Then $\mathbf{T}$ is said
to be commuting if $T_{i}T_{j}=T_{j}T_{i}$ for all $i,j=1,...,n$.
\end{definition}


\begin{lemma}
\label{L004}\cite{BA2} Let $\mathbf{T=}\left( T_{1},...,T_{n}\right) \in {%
\mathcal{B}}_{A^{{1}/{2}}}\left( {\mathcal{H}}\right) ^{n}$ be commuting and $A$-normal $n$-tuple. Then 
\begin{equation*}
\left\Vert \mathbf{T}\right\Vert _{A}=\omega _{A}\left( \mathbf{T}\right) 
\text{.}
\end{equation*}
\end{lemma}

\begin{lemma}
\label{L05}\bigskip \cite[Proposition 2.9]{GU1} Let $\ \mathbf{T=}\left(
T_{1},...,T_{n}\right) \in {\mathcal{B}}_{A}\left( {\mathcal{H}}\right) ^{n}$
be an $n$-tuple. Then
\begin{equation*}
\left\Vert \mathbf{T}\right\Vert _{A}=\left\Vert
\sum\limits_{k=1}^{n}T_{k}^{\sharp_A}T_{k}\right\Vert _{A}^{{1}/{2}}\text{.}
\end{equation*}
\end{lemma}


\begin{lemma}
\label{L5}\bigskip Let $\mathbf{T}=\left( T_{1},\cdots ,T_{n}\right) ,\, 
\mathbf{S}=\left( S_{1},\cdots ,S_{n}\right) $ $\in {\mathcal{B}}_{A^{1/2}}\left( {\mathcal{H}}\right) ^{n}$ be two $n$-tuples. Then
\begin{equation*}
\left\Vert \mathbf{TS}\right\Vert _{A}\leq \left\Vert \mathbf{T}\right\Vert
_{A}\left\Vert \mathbf{S}\right\Vert _{A}\text{.}
\end{equation*}
\end{lemma}

\begin{proof}
Let $x\in {\mathcal{H}}$ with $\left\Vert x\right\Vert _{A}=1$. For
all $k=1,2,...,n$, we see that
\begin{equation*}
\left\Vert T_{k}x\right\Vert _{A}\leq \left( \sum\limits_{k=1}^{n}\left\Vert
T_{k}x\right\Vert _{A}^{2}\right) ^{{1}/{2}}\text{.}
\end{equation*}
Taking the supremum over $x\in {\mathcal{H}}$ with $\left\Vert x\right\Vert
_{A}=1$, we get
%\begin{equation*}
$\left\Vert T_{k}\right\Vert _{A}\leq \left\Vert \mathbf{T}\right\Vert _{A}%
\text{ for all }k=1,2,...,n\text{.}$
%\end{equation*}%
Therefore, we have
\begin{eqnarray*}
\left\Vert \mathbf{TS}\right\Vert _{A} &=&\sup\limits_{\left\Vert
x\right\Vert _{A}=1}\left( \sum\limits_{k=1}^{n}\left\Vert
T_{k}S_{k}x\right\Vert _{A}^{2}\right) ^{{1}/{2}} 
\leq \sup\limits_{\left\Vert x\right\Vert _{A}=1}\left(
\sum\limits_{k=1}^{n}\left\Vert T_{k}\right\Vert _{A}^{2}\left\Vert
S_{k}x\right\Vert _{A}^{2}\right) ^{{1}/{2}} \\
&\leq &\sup\limits_{\left\Vert x\right\Vert _{A}=1}\left(
\sum\limits_{k=1}^{n}\left\Vert \mathbf{T}\right\Vert _{A}^{2}\left\Vert
S_{k}x\right\Vert _{A}^{2}\right) ^{{1}/{2}} 
=\left\Vert \mathbf{T}\right\Vert _{A}\sup\limits_{\left\Vert x\right\Vert
_{A}=1}\left( \sum\limits_{k=1}^{n}\left\Vert S_{k}x\right\Vert
_{A}^{2}\right) ^{{1}/{2}} \\
&=&\left\Vert \mathbf{T}\right\Vert _{A}\left\Vert \mathbf{S}\right\Vert _{A}%
\text{.}
\end{eqnarray*}
\end{proof}

\begin{lemma}
\label{L6}\bigskip\ Let $\mathbf{T}=\left( T_{1},\cdots ,T_{n}\right) ,\,
\mathbf{S}=\left( S_{1},\cdots ,S_{n}\right) $ $\in {\mathcal{B}}_{A^{1/2}}\left( {\mathcal{H}}\right) ^{n}$  be two $n$-tuples. Then 
