Hence,%
\begin{equation*}
\max \left\{ \sqrt{\beta }, \, \frac{1}{2}\sqrt{\frac{\alpha +\beta }{n}}
\right\} \left\Vert \mathbf{T}\right\Vert _{A}\leq \left\Vert \mathbf{T}
\right\Vert _{A_{\alpha ,\beta }}\leq \sqrt{\alpha +\beta }\left\Vert 
\mathbf{T}\right\Vert _{A}\text{.}
\end{equation*}
\end{proof}

\begin{remark}
\bigskip By setting $n=1$ and $A=I$ in Theorem \ref{TH1}, we can also obtain \cite[%
Theorem 2.1]{Sain}.
\end{remark}



In the following proposition, we prove that the $\left(\alpha ,\beta \right)$-$A$-Euclidean operator radius is weakly $A$-unitarily invariant.


\begin{proposition}
Let $\mathbf{T}=\left( T_{1},\cdots ,T_{n}\right) \in {\mathcal{B}}_A^{}\left( {\mathcal{H}}\right) ^{n}$ be an $n$-tuple 
and let $U\in {\mathcal{B}}_{A}\left( {\mathcal{H}}\right) $ be an $A$-unitary (i.e., $\left\Vert Ux\right\Vert
_{A}=\left\Vert U^{\sharp _{A}}x\right\Vert _{A}=\left\Vert x\right\Vert
_{A} $ for all $x\in {\mathcal{H}}$).  Then 
\begin{equation*}
\left\Vert U\mathbf{T}U^{\sharp _{A}}\right\Vert _{\alpha ,\beta
}=\left\Vert \mathbf{T}\right\Vert _{\alpha ,\beta }, \quad \text{where  $U\mathbf{T}U^{\sharp _{A}}:=\left( UT_{1}U^{\sharp _{A}},\cdots
,UT_{n}U^{\sharp _{A}}\right) $.}
\end{equation*}
\end{proposition}

\begin{proof}
Since $U$ is an $A$-unitary operator, it follows that 
\begin{eqnarray*}
\left\Vert U\mathbf{T}U^{\sharp _{A}}\right\Vert _{A_{\alpha ,\beta }}
&=&\sup_{\left\Vert x\right\Vert _{A}=1}\left( \sum\limits_{k=1}^{n} \left(\alpha
\left\vert \left\langle UT_{k}U^{\sharp _{A}}x,x\right\rangle
_{A}\right\vert ^{2}+\beta \left\Vert UT_{k}U^{\sharp _{A}}x\right\Vert
_{A}^{2} \right)\right) ^{{1}/{2}} \\
&=&\sup_{\left\Vert x\right\Vert _{A}=1}\left( \sum\limits_{k=1}^{n} \left( \alpha
\left\vert \left\langle T_{k}U^{\sharp _{A}}x,U^{\sharp _{A}}x\right\rangle _{A}\right\vert ^{2}+\beta
\left\Vert UT_{k}U^{\sharp _{A}}x\right\Vert _{A}^{2}\right)\right) ^{{1}/{2}}
\\
&=&\sup_{\left\Vert y\right\Vert _{A}=1}\left( \sum\limits_{k=1}^{n} \left( \alpha
\left\vert \left\langle T_{k}y,y\right\rangle _{A}\right\vert ^{2}+\beta
\left\Vert T_{k}y\right\Vert _{A}^{2}\right)\right) ^{{1}/{2}} 
\quad \text{(setting $y =Ux$)} \\
&\leq&\left\Vert \mathbf{T}\right\Vert _{\alpha ,\beta }.
\end{eqnarray*}
We now show the reverse inequality. 
Since $U$ is an $A$-unitary, we have $U^{\sharp_A}U=P$ and so
\begin{eqnarray*}
    \left\Vert \mathbf{T}\right\Vert _{\alpha ,\beta } &=&\sup_{\left\Vert y\right\Vert _{A}=1}\left( \sum\limits_{k=1}^{n} \left( \alpha
\left\vert \left\langle T_{k}y,y\right\rangle _{A}\right\vert ^{2}+\beta
\left\Vert T_{k}y\right\Vert _{A}^{2}\right)\right) ^{{1}/{2}} \\
&=&\sup_{\left\Vert y\right\Vert _{A}=1}\left( \sum\limits_{k=1}^{n} \left( \alpha
\left\vert \left\langle T_{k}y,y\right\rangle _{A}\right\vert ^{2}+\beta
\left\Vert UT_{k}y\right\Vert _{A}^{2}\right)\right) ^{{1}/{2}} \\
&=&\sup_{\left\Vert Py\right\Vert _{A}=1}\left( \sum\limits_{k=1}^{n} \left( \alpha
\left\vert \left\langle T_{k}Py,Py\right\rangle _{A}\right\vert ^{2}+\beta
\left\Vert UT_{k}Py\right\Vert _{A}^{2}\right)\right) ^{{1}/{2}} \,\, (\text{set } y=Py+x, \, Ax=0) \\
&=&\sup_{\left\Vert Uy\right\Vert _{A}=1}\left( \sum\limits_{k=1}^{n} \left( \alpha
\left\vert \left\langle UT_{k}U^{\sharp_A}Uy,Uy\right\rangle _{A}\right\vert ^{2}+\beta
\left\Vert UT_{k}U^{\sharp_A} Uy\right\Vert _{A}^{2}\right)\right) ^{{1}/{2}}\\
&\leq& \left\Vert U\mathbf{T}U^{\sharp _{A}}\right\Vert _{A_{\alpha ,\beta }}.
\end{eqnarray*}
\end{proof}


Next, we obtain an inequality for the product of two $n$-tuples.

\begin{theorem}
\label{TH2} Let $\mathbf{T}=\left( T_{1},\cdots ,T_{n}\right) ,\,  \mathbf{S=}\left(
S_{1},\cdots ,S_{n}\right) \in {\mathcal{B}}_{A^{{1}/{2}}}\left( {
\mathcal{H}}\right) ^{n}$ and let $\beta \neq 0$. Then
\begin{equation*}
\left\Vert \mathbf{TS}\right\Vert _{A_{\alpha ,\beta }}\leq \min \left\{ 2%
\sqrt{\frac{n}{\beta }},\frac{\sqrt{\alpha +\beta }}{\beta },\frac{4n}{\sqrt{%
\alpha +\beta }}\right\} \left\Vert \mathbf{T}\right\Vert _{A_{\alpha ,\beta
}}\left\Vert \mathbf{S}\right\Vert _{A_{\alpha ,\beta }}\text{.}
\end{equation*}
\end{theorem}

\begin{proof}
Following Theorem \ref{TH1}, and using Lemmas \ref{L5} and \ref{L4}, we have
\begin{eqnarray*}
\left\Vert \mathbf{TS}\right\Vert _{A_{\alpha ,\beta }} \leq \sqrt{\alpha
+\beta }\left\Vert \mathbf{TS}\right\Vert _{A} 
\leq \sqrt{\alpha +\beta }\left\Vert \mathbf{T}\right\Vert _{A}\left\Vert 
\mathbf{S}\right\Vert _{A}
&\leq & 2\sqrt{n}\sqrt{\alpha +\beta }\omega _{A}\left( \mathbf{T}\right)
\left\Vert \mathbf{S}\right\Vert _{A} \\
&\leq & 2\sqrt{\frac{n}{\beta }}\left\Vert \mathbf{T}\right\Vert _{A_{\alpha
,\beta }}\left\Vert \mathbf{S}\right\Vert _{A_{\alpha ,\beta }}\text{.}
\end{eqnarray*}
Since $\sqrt{\beta }\left\Vert \mathbf{T}\right\Vert _{A}\leq \left\Vert 
\mathbf{T}\right\Vert _{A_{\alpha ,\beta }}$ and $\sqrt{\beta }\left\Vert 
\mathbf{S}\right\Vert _{A}\leq \left\Vert \mathbf{S}\right\Vert _{A_{\alpha
,\beta }}$, similarly we also have  
\begin{eqnarray*}
\left\Vert \mathbf{TS}\right\Vert _{A_{\alpha ,\beta }} \leq \sqrt{\alpha
+\beta }\left\Vert \mathbf{TS}\right\Vert _{A} 
\leq \sqrt{\alpha +\beta }\left\Vert \mathbf{T}\right\Vert _{A}\left\Vert 
\mathbf{S}\right\Vert _{A}
\leq \frac{\sqrt{\alpha +\beta }}{\beta }\left\Vert \mathbf{T}\right\Vert
_{A_{\alpha ,\beta }}\left\Vert \mathbf{S}\right\Vert _{A_{\alpha ,\beta }}%
\text{.}
\end{eqnarray*}
Again, since $\left\Vert \mathbf{T}\right\Vert _{A}\leq 2\sqrt{n}\omega
_{A}\left( \mathbf{T}\right) $ and $\left\Vert \mathbf{S}\right\Vert
_{A}\leq 2\sqrt{n}\omega _{A}\left( \mathbf{S}\right) $, we have
\begin{eqnarray*}
\left\Vert \mathbf{TS}\right\Vert _{A_{\alpha ,\beta }} \leq \sqrt{\alpha
+\beta }\left\Vert \mathbf{TS}\right\Vert _{A} 
\leq \sqrt{\alpha +\beta }\left\Vert \mathbf{T}\right\Vert _{A}\left\Vert 
\mathbf{S}\right\Vert _{A} 
&\leq &4n\sqrt{\alpha +\beta }\omega _{A}\left( \mathbf{T}\right) \omega
_{A}\left( \mathbf{S}\right) \\
&\leq &\frac{4n}{\sqrt{\alpha +\beta }}\left\Vert \mathbf{T}\right\Vert
_{A_{\alpha ,\beta }}\left\Vert \mathbf{S}\right\Vert _{A_{\alpha ,\beta }}%
\text{.}
\end{eqnarray*}
Combining above inequalities, we get the desired
inequality.
\end{proof}

\begin{remark}
\bigskip By setting $n=1$ in Theorem \ref{TH2}, we obtain
\begin{equation*}
\left\Vert TS\right\Vert _{A_{\alpha ,\beta }}\leq \min \left\{ 2\sqrt{\frac{%
1}{\beta }},\frac{\sqrt{\alpha +\beta }}{\beta },\frac{4}{\sqrt{\alpha
+\beta }}\right\} \left\Vert T\right\Vert _{A_{\alpha ,\beta }}\left\Vert
S\right\Vert _{A_{\alpha ,\beta }}\text{,}
\end{equation*}
where \begin{equation*}
\left\Vert T\right\Vert _{A_{\alpha,\beta }}:=\sup \left\{  \left( \alpha
\left\vert \left\langle Tx,x\right\rangle _{A}\right\vert ^{2}+\beta \left\Vert Tx\right\Vert _{A}^{2} \right) ^{\frac{1}{%
2}}:x\in {\mathcal{H}}\text{, }\left\Vert x\right\Vert _{A}=1\text{ }%
\right\} \text{.} 
\end{equation*}
From the above inequality, for $A=I$, we get the inequality \cite[Theorem 2.9]{Sain}, namely
\begin{equation*}
\left\Vert TS\right\Vert _{_{\alpha ,\beta }}\leq \min \left\{ 2\sqrt{\frac{1%
}{\beta }},\frac{\sqrt{\alpha +\beta }}{\beta },\frac{4}{\sqrt{\alpha +\beta 
}}\right\} \left\Vert T\right\Vert _{_{\alpha ,\beta }}\left\Vert
S\right\Vert _{_{\alpha ,\beta }}\text{.}
\end{equation*}
\end{remark}


We again obtain inequalities for the product of two $n$-tuples under some assumptions.

\begin{theorem}
Let $\mathbf{T}=\left( T_{1},\cdots ,T_{n}\right) \in {\mathcal{B}}%
_{A}\left( {\mathcal{H}}\right) ^{n}$ and $\mathbf{S=}\left( S_{1},\cdots
,S_{n}\right) \in {\mathcal{B}}_{A^{{1}/{2}}}\left( {\mathcal{H}}\right)
^{n}$. Then the following inequalities hold:

(i) If $\mathbf{TS=ST}$ and $\beta \neq 0$, then 
\begin{equation*}
\left\Vert \mathbf{TS}\right\Vert _{A_{\alpha ,\beta }}\leq \sqrt{\frac{%
4\alpha n}{\left( \alpha +\beta \right) ^{2}}+\frac{1}{\beta }}\left\Vert 
\mathbf{T}\right\Vert _{A_{\alpha ,\beta }}\left\Vert \mathbf{S}\right\Vert
_{A_{\alpha ,\beta }}\text{.}
\end{equation*}

(ii) If $T_{k}$ is an $A$-isometry for each $k=1,2,...,n$, then%
\begin{equation*}
\left\Vert \mathbf{TS}\right\Vert _{A_{\alpha ,\beta }}\leq \sqrt{\frac{%
4\alpha n}{\alpha +\beta }+1}\left\Vert \mathbf{S}\right\Vert _{A_{\alpha
,\beta }}\text{.}
\end{equation*}
\end{theorem}

\begin{proof}
(i) Let $x\in {\mathcal{H}}$ with $\left\Vert x\right\Vert _{A}=1$. Then, we have
\begin{eqnarray*}
\left\Vert \mathbf{TS}\right\Vert _{A_{\alpha ,\beta }}^{2}
&=&\sup_{\left\Vert x\right\Vert _{A}=1}\sum\limits_{k=1}^{n}\left( \alpha
\left\vert \left\langle T_{k}S_{k}x,x\right\rangle _{A}\right\vert
^{2}+\beta \left\Vert T_{k}S_{k}x\right\Vert _{A}^{2}\right) \\
&\leq &\alpha \omega _{A}^{2}\left( \mathbf{TS}\right) +\beta \left\Vert 
\mathbf{TS}\right\Vert _{A}^{2} \\
&\leq &4\alpha n\omega _{A}^{2}\left( \mathbf{T}\right) \omega
_{A}^{2}\left( \mathbf{S}\right) +\beta \left\Vert \mathbf{T}\right\Vert
_{A}^{2}\left\Vert \mathbf{S}\right\Vert _{A}^{2} \quad
\text{(by Lemma \ref{L66})} \\
&\leq &\frac{4\alpha n}{\left( \alpha +\beta \right) ^{2}}\left\Vert \mathbf{%
T}\right\Vert _{A_{\alpha ,\beta }}^{2}\left\Vert \mathbf{S}\right\Vert
_{A_{\alpha ,\beta }}^{2}+\frac{1}{\beta }\left\Vert \mathbf{T}\right\Vert
_{A_{\alpha ,\beta }}^{2}\left\Vert \mathbf{S}\right\Vert _{A_{\alpha ,\beta
}}^{2} \\
&=&\left( \frac{4\alpha n}{\left( \alpha +\beta \right) ^{2}}+\frac{1}{\beta 
}\right) \left\Vert \mathbf{T}\right\Vert _{A_{\alpha ,\beta
}}^{2}\left\Vert \mathbf{S}\right\Vert _{A_{\alpha ,\beta }}^{2}\text{.}
\end{eqnarray*}
(ii) We also have
\begin{eqnarray*}
\left\Vert \mathbf{TS}\right\Vert _{A_{\alpha ,\beta }}^{2}
%&=&\sup_{\left\Vert x\right\Vert _{A}=1}\sum\limits_{k=1}^{n}\left( \alpha \left\vert \left\langle T_{k}S_{k}x,x\right\rangle _{A}\right\vert ^{2}+\beta \left\Vert T_{k}S_{k}x\right\Vert _{A}^{2}\right) \\
&\leq &\alpha \omega _{A}^{2}\left( \mathbf{TS}\right) +\beta \left\Vert 
\mathbf{TS}\right\Vert _{A}^{2} 
\leq \alpha \left\Vert \mathbf{S}\right\Vert _{A}^{2}+\beta \left\Vert 
\mathbf{S}\right\Vert _{A}^{2} \quad
\text{(by Lemma \ref{L7})} \\
&\leq &4\alpha n\omega _{A}^{2}\left( \mathbf{S}\right) +\beta \left\Vert 
\mathbf{S}\right\Vert _{A}^{2} 
\leq \frac{4\alpha n}{\alpha +\beta }\left\Vert \mathbf{S}\right\Vert
_{A_{\alpha ,\beta }}^{2}+\left\Vert \mathbf{S}\right\Vert _{A_{\alpha
,\beta }}^{2}\\ 
&=& \left( \frac{4\alpha n}{\alpha +\beta }+1\right) \left\Vert \mathbf{S}%
\right\Vert _{A_{\alpha ,\beta }}^{2}\text{.}
\end{eqnarray*}
\end{proof}

Next, we obtain a lower bound that
extends \cite[Theorem 2.7]{Sain}.

\begin{theorem}
Let $\mathbf{T}=\left( T_{1},\cdots ,T_{n}\right) \in {\mathcal{B}}%
_{A}\left( {\mathcal{H}}\right) ^{n}$ be an $n$-tuple. Then
\begin{equation*}
\left\Vert \mathbf{T}\right\Vert _{A_{\alpha ,\beta }}\geq \max \left\{ 
\sqrt{\alpha \omega _{A}^{2}\left( \mathbf{T}\right) +\beta m_{A}^{2}\left( 
\mathbf{T}\right) },\sqrt{\alpha c_{A}^{2}\left( 
\mathbf{T}\right) +\beta \left\Vert \mathbf{T}\right\Vert _{A}^{2}}\right\} 
\text{,}
\end{equation*}
where $m_{A}\left(
\mathbf{T}\right)= \inf  \left\{ \left( \sum\limits_{k=1}^{n} \left\langle T_{k}^{\sharp
_{A}}T_{k}x,x\right\rangle _{A} \right)^{1/2}: x\in \mathcal{H},\, \|x\|_A=1  \right\}$.
\end{theorem}

\begin{proof}
Let $x\in {\mathcal{H}}$ with $\left\Vert x\right\Vert _{A}=1$. Then, we have%
\begin{eqnarray*}
\left\Vert \mathbf{T}\right\Vert _{A_{\alpha ,\beta }}^{2} &\geq
&\sum\limits_{k=1}^{n}\left( \alpha \left\vert \left\langle
T_{k}x,x\right\rangle _{A}\right\vert ^{2}+\beta \left\Vert
T_{k}x\right\Vert _{A}^{2}\right) 
=\sum\limits_{k=1}^{n}\alpha \left\vert \left\langle T_{k}x,x\right\rangle
_{A}\right\vert ^{2}+\sum\limits_{k=1}^{n}\beta \left\langle T_{k}^{\sharp
_{A}}T_{k}x,x\right\rangle _{A} \\
&\geq &\alpha \sum\limits_{k=1}^{n}\left\vert \left\langle
T_{k}x,x\right\rangle _{A}\right\vert ^{2}+ \beta m_{A}^2\left(
\mathbf{T}\right).
\end{eqnarray*}
Taking the supremum over $\left\Vert
x\right\Vert =1$, we get
%\begin{equation}
$\left\Vert \mathbf{T}\right\Vert _{A_{\alpha ,\beta }}^{2}\geq \alpha \omega
_{A}^{2}\left( \mathbf{T}\right) +\beta m_{A}^{2}\left( \mathbf{T}\right) \text{.} $ %$ \label{C}
%\end{equation}
Also, we have 
\begin{eqnarray*}
\left\Vert \mathbf{T}\right\Vert _{A_{\alpha ,\beta }}^{2} &\geq
&\sum\limits_{k=1}^{n}\left( \alpha \left\vert \left\langle
T_{k}x,x\right\rangle _{A}\right\vert ^{2}+\beta \left\Vert
T_{k}x\right\Vert _{A}^{2}\right) 
=\alpha \sum\limits_{k=1}^{n}\left\vert \left\langle T_{k}x,x\right\rangle
_{A}\right\vert ^{2}+\beta \sum\limits_{k=1}^{n}\left\Vert T_{k}x\right\Vert
_{A}^{2} \\
&\geq &\alpha c_{A}^{2}\left( \mathbf{T}\right) +\beta
\sum\limits_{k=1}^{n}\left\Vert T_{k}x\right\Vert _{A}^{2}\text{.}
\end{eqnarray*}
Taking the supremum over $\left\Vert
x\right\Vert _{A}=1$, we get
%\begin{equation}
$\left\Vert \mathbf{T}\right\Vert _{A_{\alpha ,\beta }}^{2}\geq \alpha
c_{A}^{2}\left( \mathbf{T}\right) +\beta \left\Vert \mathbf{T}\right\Vert
_{A}^{2}\text{.}$  %$  \label{D}
%\end{equation}
Thus, we conclude 
\begin{equation*}
\left\Vert \mathbf{T}\right\Vert _{A_{\alpha ,\beta }}\geq \max \left\{ 
\sqrt{\alpha \omega _{A}^{2}\left( \mathbf{T}\right) +\beta m_{A}^{2}\left( 
\mathbf{T} \right) },\sqrt{\alpha c_{A}^{2}\left( 
\mathbf{T}\right) +\beta \left\Vert \mathbf{T}\right\Vert _{A}^{2}}\right\} .
\end{equation*}
\end{proof}




Next, using the Cartesian decomposition of an operator, we obtain the following inequality.


\begin{theorem}\label{p--1}
\bigskip Let $\mathbf{T}=\left( T_{1},\cdots ,T_{n}\right) \in {\mathcal{B}}
_{A}\left( {\mathcal{H}}\right) ^{n}$ be a commuting $n$-tuple. Then
\begin{equation*}
\left\Vert \mathbf{T}\right\Vert _{A_{\alpha ,\beta }}^{2}\geq \left\Vert
\sum\limits_{k=1}^{n}\left( \frac{\alpha }{8}T_{k}T_{k}^{\sharp _{A}}+\left( 
\frac{\alpha }{8}+\frac{\beta }{2}\right) T_{k}^{\sharp _{A}}T_{k}\right)
\right\Vert _{A}.
\end{equation*}
\end{theorem}

\begin{proof}
Let $x\in {\mathcal{H}}$ and $\left\Vert x\right\Vert
_{A}=1$. Then, we see that
\begin{eqnarray*}
\left\vert \left\langle T_{k}x,x\right\rangle _{A}\right\vert ^{2}
&=&\left\vert \left\langle T_{k}^{\sharp _{A}}x,x\right\rangle
_{A}\right\vert ^{2} \\
%&=&\left\vert \left\langle \left( \left( \Re _{A}\left( T_{k}\right) \right) ^{\sharp _{A}}-i\left( \Im _{A}\left( T_{k}\right) \right) ^{\sharp _{A}}\right) x,x\right\rangle _{A}\right\vert ^{2} \\
&=&\left\vert \left\langle \left( \Re _{A}\left( T_{k}\right) \right)
^{\sharp _{A}}x,x\right\rangle _{A}\right\vert ^{2}+\left\vert \left\langle
\left( \Im _{A}\left( T_{k}\right) \right) ^{\sharp _{A}}x,x\right\rangle
_{A}\right\vert ^{2} \\
&\geq &\frac{1}{2}\left\vert \left\langle \left( \left( \Re _{A}\left(
T_{k}\right) \right) ^{\sharp _{A}}\pm \left( \Im _{A}\left( T_{k}\right)
\right) ^{\sharp _{A}}\right) x,x\right\rangle _{A}\right\vert ^{2}\text{.}
\end{eqnarray*}
%Taking the supremum over all $x\in {\mathcal{H}}$ with $\left\Vert x\right\Vert _{A}=1$, we get 
Therefore, we have
\begin{eqnarray*}
\left\Vert \mathbf{T}\right\Vert _{A_{\alpha ,\beta }}^{2}
&=&\sup_{\left\Vert x\right\Vert _{A}=1}\sum\limits_{k=1}^{n}\left( \alpha
\left\vert \left\langle T_{k}x,x\right\rangle _{A}\right\vert ^{2}+\beta
\left\Vert T_{k}x\right\Vert _{A}^{2}\right) \\
&\geq &\sup_{\left\Vert x\right\Vert _{A}=1}\sum\limits_{k=1}^{n}\alpha
\left\vert \left\langle T_{k}x,x\right\rangle _{A}\right\vert ^{2} \\
&\geq &\frac{\alpha }{2}\sup_{\left\Vert x\right\Vert
_{A}=1}\sum\limits_{k=1}^{n}\left\vert \left\langle \left( \left( \Re
_{A}\left( T_{k}\right) \right) ^{\sharp _{A}}\pm \left( \Im _{A}\left(
T_{k}\right) \right) ^{\sharp _{A}}\right) x,x\right\rangle _{A}\right\vert
^{2} \\
&=&\frac{\alpha }{2}\omega _{A}^{2}\left( \mathbf{S}\right) \text{,}
\end{eqnarray*}
where $\mathbf{S=}\left( \left( \Re _{A}\left( T_{1}\right) \right) ^{\sharp
_{A}}\pm \left( \Im _{A}\left( T_{1}\right) \right) ^{\sharp
_{A}},...,\left( \Re _{A}\left( T_{n}\right) \right) ^{\sharp _{A}}\pm
\left( \Im _{A}\left( T_{n}\right) \right) ^{\sharp _{A}}\right) $. Since $
\mathbf{T}$ is a commuting $n$-tuple, it can be verified
that $\mathbf{S}$ is also commuting $n$-tuple. Moreover, since $
\left( \left( \Re _{A}\left( T_{k}\right) \right) ^{\sharp _{A}}\right)
^{\sharp _{A}}=\left( \Re _{A}\left( T_{k}\right) \right) ^{\sharp _{A}}$
and $\left( \left( \Im _{A}\left( T_{k}\right) \right) ^{\sharp _{A}}\right)
^{\sharp _{A}}=\left( \Im _{A}\left( T_{k}\right) \right) ^{\sharp _{A}}$, it follows that $S_{k}^{\sharp _{A}}=S_{k}$ for all $k=1,2,...,n$,
where $S_{k}:=\left( \Re _{A}\left( T_{k}\right) \right) ^{\sharp _{A}}\pm
\left( \Im _{A}\left( T_{k}\right) \right) ^{\sharp _{A}}$. This implies
that $\mathbf{S}$ is an $A$-normal commuting $n$-tuple. Therefore,
by using Lemma \ref{L004} and Lemma \ref{L05}, we get 
\begin{equation*}
\omega _{A}\left( \mathbf{S}\right) =\left\Vert S\right\Vert _{A}=\sqrt{%
\left\Vert \sum\limits_{k=1}^{n}S_{k}^{\sharp _{A}}S_{k}\right\Vert _{A}}=%
\sqrt{\left\Vert \sum\limits_{k=1}^{n}S_{k}^{2}\right\Vert _{A}}\text{.}
\end{equation*}
Hence, we get
\begin{eqnarray*}
\left\Vert \mathbf{T}\right\Vert _{A_{\alpha ,\beta }}^{2} &\geq &\frac{%
\alpha }{2}\omega _{A}^{2}\left( \mathbf{S}\right) =\frac{\alpha }{2}%
\left\Vert \sum\limits_{k=1}^{n}S_{k}^{2}\right\Vert _{A} 
=\frac{\alpha }{2}\sup_{\left\Vert x\right\Vert _{A}=1}\left\Vert
\sum\limits_{k=1}^{n}S_{k}^{2}x\right\Vert _{A} \\
&\geq &\frac{\alpha }{2}\sup_{\left\Vert x\right\Vert _{A}=1}\left\langle
\sum\limits_{k=1}^{n}\left( \left( \Re _{A}\left( T_{k}\right) \right)
^{\sharp _{A}}\pm \left( \Im _{A}\left( T_{k}\right) \right) ^{\sharp
_{A}}\right) ^{2}x,x\right\rangle _{A} \\
&\geq &\frac{\alpha }{4}\sup_{\left\Vert x\right\Vert _{A}=1}\left\langle
\sum\limits_{k=1}^{n}\left( \left( \Re _{A}\left( T_{k}\right) \right)
^{\sharp _{A}}+\left( \Im _{A}\left( T_{k}\right) \right) ^{\sharp
_{A}}\right) ^{2}+\left( \left( \Re _{A}\left( T_{k}\right) \right) ^{\sharp
_{A}}-\left( \Im _{A}\left( T_{k}\right) \right) ^{\sharp _{A}}\right)
^{2}x,x\right\rangle _{A} \\
&\geq &\frac{\alpha }{2}\sup_{\left\Vert x\right\Vert _{A}=1}\left\langle
\sum\limits_{k=1}^{n}\left( \left( \left( \Re _{A}\left( T_{k}\right)
\right) ^{\sharp _{A}}\right) ^{2}+\left( \left( \Im _{A}\left( T_{k}\right)
\right) ^{\sharp _{A}}\right) ^{2}\right) x,x\right\rangle _{A}\text{.}
\end{eqnarray*}
Also, we have
\begin{eqnarray*}
\left\Vert \mathbf{T}\right\Vert _{A_{\alpha ,\beta }}^{2} &\geq
&\sup_{\left\Vert x\right\Vert _{A}=1}\sum\limits_{k=1}^{n}\beta \left\Vert
T_{k}x\right\Vert _{A}^{2} 
=\sup_{\left\Vert x\right\Vert _{A}=1}\sum\limits_{k=1}^{n}\left\langle
\beta T^{\sharp _{A}}Tx,x\right\rangle _{A}\text{.}
\end{eqnarray*}
Since
\begin{equation*}
\left( \left( \Re _{A}\left( T_{k}\right) \right) ^{\sharp _{A}}\right)
^{2}+\left( \left( \Im _{A}\left( T_{k}\right) \right) ^{\sharp _{A}}\right)
^{2}=\left( \frac{TT^{\sharp _{A}}+T^{\sharp _{A}}T}{2}\right) ^{\sharp _{A}}%
\text{,}
\end{equation*}
and using the above inequalities, we get 
\begin{eqnarray*}
2\left\Vert \mathbf{T}\right\Vert _{A_{\alpha ,\beta }}^{2} &\geq
&\sup_{\left\Vert x\right\Vert _{A}=1}\left\langle
\sum\limits_{k=1}^{n}\left( \frac{\alpha }{2}\left( \left( \left( \Re
_{A}\left( T_{k}\right) \right) ^{\sharp _{A}}\right) ^{2}+\left( \left( \Im
_{A}\left( T_{k}\right) \right) ^{\sharp _{A}}\right) ^{2}\right) +\beta
T_{k}^{\sharp _{A}}T_{k}\right) x,x\right\rangle _{A} \\
&=&\left\Vert \sum\limits_{k=1}^{n}\left( \frac{\alpha }{2}\left( \left(
\left( \Re _{A}\left( T_{k}\right) \right) ^{\sharp _{A}}\right) ^{2}+\left(
\left( \Im _{A}\left( T_{k}\right) \right) ^{\sharp _{A}}\right) ^{2}\right)
+\beta T_{k}^{\sharp _{A}}T_{k}\right) \right\Vert _{A}\text{.} \\
&=&\left\Vert \sum\limits_{k=1}^{n}\left( \frac{\alpha }{2}\left( \frac{%
TT^{\sharp _{A}}+T^{\sharp _{A}}T}{2}\right) ^{\sharp _{A}}+\beta
T_{k}^{\sharp _{A}}T_{k}\right) \right\Vert _{A} \\
&=&\left\Vert \sum\limits_{k=1}^{n}\left( \frac{\alpha }{2}\left( \frac{%
TT^{\sharp _{A}}+T^{\sharp _{A}}T}{2}\right) ^{\sharp _{A}}+\beta \left(
T_{k}^{\sharp _{A}}T_{k}\right) ^{\sharp _{A}}\right) \right\Vert _{A} \\
&=&\left\Vert \sum\limits_{k=1}^{n}\left( \frac{\alpha }{4}TT^{\sharp
_{A}}+\left( \frac{\alpha }{4}+\beta \right) T^{\sharp _{A}}T_{k}\right)
\right\Vert _{A} \quad 
\text{(using }\left\Vert T\right\Vert _{A} =\left\Vert T^{\sharp
_{A}}\right\Vert _{A}.
\end{eqnarray*}
\end{proof}

Setting $n=1$ in Theorem \ref{p--1}, we get
\begin{corollary}
\label{CL} \bigskip Let $T\in {\mathcal{B}}_{A}\left( {\mathcal{H}}\right) $%
. Then%
\begin{equation*}
\left\Vert T\right\Vert _{A_{\alpha ,\beta }}^{2}\geq \left\Vert \left( 
\frac{\alpha }{8}TT^{\sharp _{A}}+\left( \frac{\alpha }{8}+\frac{\beta }{2}%
\right) T^{\sharp _{A}}T\right) \right\Vert _{A}\text{.}
\end{equation*}
\end{corollary}


\begin{remark}
For $\beta =1-\alpha $ and $0\leq \alpha \leq 1$ in Corollary 
\ref{CL}, we get \cite[Theorem 2.8]{BH1}, namely,
\begin{equation*}
\left\Vert T\right\Vert _{A_{\alpha }}^{2}\geq \left\Vert \left( \frac{%
\alpha }{8}\left( TT^{\sharp _{A}}+T^{\sharp _{A}}T\right) +\frac{1-\alpha }{%
2}T^{\sharp _{A}}T\right) \right\Vert _{A}\text{.}
\end{equation*}
\end{remark}




The next result reads as follows.

\begin{theorem}
\label{TH5}\bigskip Let $\mathbf{T}=\left( T_{1},\cdots ,T_{n}\right) \in {
\mathcal{B}}_{A}\left( {\mathcal{H}}\right) ^{n}$ be an $n$-tuple. Then
\begin{equation*}
\left\Vert \mathbf{T}\right\Vert _{A_{\alpha ,\beta }}^{2}\leq \sqrt{n}
\omega _{A}\left( \alpha \mathbf{T} \mathbf{T}^{\sharp _{A}}+\beta \mathbf{T}
^{\sharp _{A}} \mathbf{T}\right) \text{,} \quad \textit{where } \mathbf{T}^{\sharp _{A}}= \left( T_{1}^{\sharp_A},\cdots ,T_{n}^{\sharp_A}\right).
\end{equation*}
\end{theorem}

\begin{proof}
Let $x\in {\mathcal{H}}$ with $\left\Vert x\right\Vert _{A}=1$. By using the 
$A$-Cauchy-Schwarz inequality, we get%
\begin{eqnarray*}
\left\Vert \mathbf{T}\right\Vert _{A_{\alpha ,\beta }}^{2}
&=&\sup_{\left\Vert x\right\Vert _{A}=1}\sum\limits_{k=1}^{n}\left( \alpha
\left\vert \left\langle T_{k}x,x\right\rangle _{A}\right\vert ^{2}+\beta
\left\Vert T_{k}x\right\Vert _{A}^{2}\right) \\
&=&\sup_{\left\Vert x\right\Vert _{A}=1}\left( \sum\limits_{k=1}^{n}\left(
\alpha \left\vert \left\langle x,T_{k}^{\sharp _{A}}x\right\rangle
_{A}\right\vert ^{2}+\beta \left\Vert T_{k}x\right\Vert _{A}^{2}\right)
\right) \\
&\leq &\sup_{\left\Vert x\right\Vert _{A}=1}\left(
\sum\limits_{k=1}^{n}\left( \alpha \left\Vert T_{k}^{\sharp
_{A}}x\right\Vert _{A}^{2}+\beta \left\Vert T_{k}x\right\Vert
_{A}^{2}\right) \right) \\
&=&\sup_{\left\Vert x\right\Vert _{A}=1}\left( \sum\limits_{k=1}^{n}\left(
\alpha \left\langle T_{k}T_{k}^{\sharp _{A}}x,x\right\rangle _{A}+\beta
\left\langle T_{k}^{\sharp _{A}}T_{k}x,x\right\rangle _{A}\right) \right) \\
&=&\sup_{\left\Vert x\right\Vert _{A}=1}\left(
\sum\limits_{k=1}^{n}\left\langle \left( \alpha T_{k}T_{k}^{\sharp
_{A}}+\beta T_{k}^{\sharp _{A}}T_{k}\right) x,x\right\rangle _{A}\right) \\
&\leq &\sqrt{n}\sup_{\left\Vert x\right\Vert _{A}=1}\left(
\sum\limits_{k=1}^{n}\left\vert \left\langle \left( \alpha
T_{k}T_{k}^{\sharp _{A}}+\beta T_{k}^{\sharp _{A}}T_{k}\right)
x,x\right\rangle _{A}\right\vert ^{2}\right) ^{{1}/{2}} 
\text{(by } \text{Cauchy--Schwarz)} \\
&=&\sqrt{n}\omega _{A}\left( \alpha \mathbf{T}^{\sharp _{A}}\mathbf{T}+\beta 
\mathbf{TT}^{\sharp _{A}}\right) \text{.}
\end{eqnarray*}
\end{proof}


Using Theorem \ref{TH5}, we deduce the following two corollaries.

\begin{corollary}
Let $\mathbf{T}=\left( T_{1},\cdots ,T_{n}\right) \in {\mathcal{B}}%
_{A}\left( {\mathcal{H}}\right) ^{n}$ be an $n$-tuple. Then
\begin{equation*}
\omega _{A}^{2}\left( \mathbf{T}\right) \leq \inf\limits_{\alpha ,\beta }%
\frac{\sqrt{n}}{\alpha +\beta }\omega _{A}\left( \alpha \mathbf{T}^{\sharp
_{A}}\mathbf{T}+\beta \mathbf{TT}^{\sharp _{A}}\right) \text{.}
\end{equation*}
\end{corollary}

\begin{proof}
Using Theorem \ref{TH1} (i), i.e., $\omega _{A}\left( \mathbf{T}\right)
\leq \frac{1}{\sqrt{\alpha +\beta }}\left\Vert \mathbf{T}\right\Vert
_{A_{\alpha ,\beta }}$, we obtain
\begin{equation*}
\omega _{A}^{2}\left( \mathbf{T}\right) \leq \frac{\sqrt{n}}{\alpha +\beta } \omega _{A}\left( \alpha \mathbf{T}^{\sharp _{A}}\mathbf{T}+\beta \mathbf{TT} ^{\sharp _{A}}\right) \text{}
\end{equation*}
and then taking the infimum over $\alpha ,\beta $, we get the desired result.
\end{proof}

Setting $n=1$, we get the $A$-numerical radius bound, which is a refinement of (\ref{2}).

\begin{corollary}
Let $T\in {\mathcal{B}}_{A}\left( {\mathcal{H}}\right) $. Then
\begin{eqnarray*}
\omega _{A}^{2}\left( T\right) &\leq &\inf\limits_{\alpha ,\beta }\frac{1}{
\alpha +\beta }\left\Vert \alpha T^{\sharp _{A}}T+\beta TT^{\sharp
_{A}}\right\Vert _{A} 
\leq \frac{1}{2}\left\Vert T^{\sharp _{A}}T+TT^{\sharp _{A}}\right\Vert
_{A}\text{.}
\end{eqnarray*}
\end{corollary}

 We now obtain an inequality for the new seminorm, and from which we deduce related $A$-Euclidean operator radius inequalities.

\begin{theorem}
\label{TH6}\bigskip\ Let $\mathbf{T}=\left( T_{1},\cdots ,T_{n}\right) \in {%
\mathcal{B}}_{A}\left( {\mathcal{H}}\right) ^{n}$ be an $n$-tuple. Then
\begin{equation*}
\left\Vert \mathbf{T}\right\Vert _{A_{\alpha ,\beta }}^{2}\leq \left\Vert
\sum\limits_{k=1}^{n}\left( \left( \frac{\alpha }{2}+\beta \right)
T_{k}^{\sharp _{A}}T_{k}+\frac{\alpha }{2}T_{k}T_{k}^{\sharp _{A}}\right)
\right\Vert _{A}\text{.}
\end{equation*}
\end{theorem}

\begin{proof}
Let $x\in {\mathcal{H}}$ with $\left\Vert x\right\Vert _{A}=1$. We have%
\begin{eqnarray*}
\left\vert \left\langle T_{k}x,x\right\rangle _{A}\right\vert ^{2}
&=&\left\vert \left\langle T_{k}x,x\right\rangle _{A}\right\vert \left\vert
\left\langle x,T_{k}^{\sharp _{A}}x\right\rangle _{A}\right\vert \\
&\leq &\left\Vert T_{k}x\right\Vert _{A}\left\Vert T_{k}^{\sharp
_{A}}x\right\Vert _{A} \quad
\text{(by the }A\text{-Cauchy-Schwary inequality)} \\
&=&\left\langle T_{k}^{\sharp _{A}}T_{k}x,x\right\rangle _{A}^{\frac{1}{2}%
}\left\langle T_{k}^{\sharp _{A}}T_{k}x,x\right\rangle _{A}^{{1}/{2}} \\
&\leq &\frac{1}{2}\left( \left\langle T_{k}^{\sharp
_{A}}T_{k}x,x\right\rangle _{A}+\left\langle T_{k}T_{k}^{\sharp
_{A}}x,x\right\rangle _{A}\right) \quad
\text{(by AM-GM inequality)} \\
&=&\frac{1}{2}\left\langle \left( T_{k}^{\sharp
_{A}}T_{k}+T_{k}T_{k}^{\sharp _{A}}\right) x,x\right\rangle \text{.}
\end{eqnarray*}
Also, we have
%\begin{eqnarray*}
$\left\Vert T_{k}x\right\Vert _{A}^{2} = \left\langle
T_{k}x,T_{k}x\right\rangle _{A} 
= \left\langle T_{k}^{\sharp _{A}}T_{k}x,x\right\rangle _{A}\text{.}$
%\end{eqnarray*}
Therefore, 
\begin{eqnarray*}
\left\Vert \mathbf{T}\right\Vert _{A_{\alpha ,\beta }}^{2}
&=&\sup_{\left\Vert x\right\Vert _{A}=1}\sum\limits_{k=1}^{n}\left( \alpha
\left\vert \left\langle T_{k}x,x\right\rangle _{A}\right\vert ^{2}+\beta
\left\Vert T_{k}x\right\Vert _{A}^{2}\right) \\
&\leq &\sup_{\left\Vert x\right\Vert _{A}=1}\sum\limits_{k=1}^{n}\left( 
\frac{\alpha }{2}\left\langle \left( T_{k}^{\sharp
_{A}}T_{k}+T_{k}T_{k}^{\sharp _{A}}\right) x,x\right\rangle +\beta
\left\langle T_{k}^{\sharp _{A}}T_{k}x,x\right\rangle \right) \\
&=&\sup_{\left\Vert x\right\Vert _{A}=1}\sum\limits_{k=1}^{n}\left\langle
\left( \left( \frac{\alpha }{2}+\beta \right) T_{k}^{\sharp _{A}}T_{k}+\frac{%
\alpha }{2}T_{k}T_{k}^{\sharp _{A}}\right) x,x\right\rangle _{A} \\
&=&\omega _{A}\left( \sum\limits_{k=1}^{n}\left( \left( \frac{\alpha }{2}%
+\beta \right) T_{k}^{\sharp _{A}}T_{k}+\frac{\alpha }{2}T_{k}T_{k}^{\sharp
_{A}}\right) \right) \\
&=&\left\Vert \sum\limits_{k=1}^{n}\left( \left( \frac{\alpha }{2}+\beta
\right) T_{k}^{\sharp _{A}}T_{k}+\frac{\alpha }{2}T_{k}T_{k}^{\sharp
_{A}}\right) \right\Vert _{A}\text{.}
\end{eqnarray*}
\end{proof}


Using Theorem \ref{TH6}, we deduce a generalization and refinement of \cite[Corollary 3.6]{MOS}.

\begin{corollary}
Let $\mathbf{T}=\left( T_{1},\cdots ,T_{n}\right) \in {\mathcal{B}}
_{A}\left( {\mathcal{H}}\right) ^{n}$ be an $n$-tuple. Then
\begin{eqnarray*}
\omega _{A}\left( \mathbf{T}\right) &\leq &\inf\limits_{\alpha ,\beta }\frac{%
1}{\sqrt{\alpha +\beta }}\left\Vert \sum\limits_{k=1}^{n}\left( \left( \frac{%
\alpha }{2}+\beta \right) T_{k}^{\sharp _{A}}T_{k}+\frac{\alpha }{2}%
T_{k}T_{k}^{\sharp _{A}}\right) \right\Vert _{A}^{{1}/{2}} \\
&\leq &\frac{1}{\sqrt{2}}\left\Vert \sum\limits_{k=1}^{n}\left(
T_{k}^{\sharp _{A}}T_{k}+T_{k}T_{k}^{\sharp _{A}}\right) \right\Vert ^{\frac{%
1}{2}}\text{.}
\end{eqnarray*}
\end{corollary}

\begin{proof} The second inequality follows from the case $\alpha =1,\beta =0$.
Following Theorem \ref{TH1} (i) and Theorem \ref{TH6}, it follows that 
\begin{eqnarray*}
\omega _{A}\left( \mathbf{T}\right) &\leq &\frac{1}{\sqrt{\alpha +\beta} }%
\left\Vert \mathbf{T}\right\Vert _{A_{\alpha ,\beta }} 
\leq \frac{1}{\sqrt{\alpha +\beta} }\left\Vert \sum\limits_{k=1}^{n}\left( \left( 
\frac{\alpha }{2}+\beta \right) T_{k}^{\sharp _{A}}T_{k}+\frac{\alpha }{2}%
T_{k}T_{k}^{\sharp _{A}}\right) \right\Vert _{A}^{{1}/{2}}\text{.}
\end{eqnarray*}
Taking the infimum over all $\alpha ,\beta $, we get 
\begin{equation*}
\omega _{A}\left( \mathbf{T}\right) \leq \inf\limits_{\alpha ,\beta }\frac{1%
}{\sqrt{\alpha +\beta }}\left\Vert \sum\limits_{k=1}^{n}\left( \left( \frac{%
\alpha }{2}+\beta \right) T_{k}^{\sharp _{A}}T_{k}+\frac{\alpha }{2}%
T_{k}T_{k}^{\sharp _{A}}\right) \right\Vert _{A}^{{1}/{2}}\text{.}
\end{equation*}
\end{proof}
\begin{remark}
For $n=1$, we get 
\begin{eqnarray*}
\omega _{A}^{2}\left( T\right) &\leq &\inf\limits_{\alpha ,\beta }\frac{1}{
{\alpha +\beta} }\left\Vert \left( \left( \frac{\alpha }{2}+\beta \right)
T^{\sharp _{A}}T+\frac{\alpha }{2}TT^{\sharp _{A}}\right) \right\Vert _{A} 
\leq \frac{1}{2}\left\Vert T^{\sharp _{A}}T+TT^{\sharp _{A}}\right\Vert
_{A}\text{,}
\end{eqnarray*}
which improves (\ref{2}).
\end{remark}

The next inequality is as follows:

\begin{theorem}
\label{TH7}\bigskip Let $\mathbf{T}=\left( T_{1},\cdots ,T_{n}\right) \in {
\mathcal{B}}_{A}\left( {\mathcal{H}}\right) ^{n}$ be an $n$-tuple. Then
\begin{equation*}
\left\Vert \mathbf{T}\right\Vert _{A_{\alpha ,\beta }}^{2}\leq \sqrt{n}%
\left( \omega _{A}\left( \left( \frac{\alpha }{4}+\beta \right) \mathbf{T}%
^{\sharp _{A}}\mathbf{T}+\frac{\alpha }{4}\mathbf{TT}^{\sharp _{A}}\right) +%
\frac{\alpha }{2}\omega _{A}\left( \mathbf{T}^{2}\right) \right) \text{.}
\end{equation*}
\end{theorem}

\begin{proof}
Let $x\in {\mathcal{H}}$ with $\left\Vert x\right\Vert _{A}=1$. We have 
\begin{eqnarray*}
\left\vert \left\langle T_{k}x,x\right\rangle _{A}\right\vert ^{2}
&=&\left\vert \left\langle T_{k}x,x\right\rangle _{A}\right\vert \left\vert
\left\langle x,T_{k}^{\sharp _{A}}x\right\rangle _{A}\right\vert \\
&\leq &\frac{1}{2}\left( \left\Vert T_{k}x\right\Vert _{A}\left\Vert
T_{k}^{\sharp _{A}}x\right\Vert _{A}+\left\vert \left\langle
T_{k}x,T_{k}^{\sharp _{A}}x\right\rangle _{A}\right\vert \right) \quad
\text{(by Lemma \ref{L1})} \\
&\leq &\frac{1}{4}\left( \left\Vert T_{k}x\right\Vert _{A}^{2}+\left\Vert
T_{k}^{\sharp _{A}}x\right\Vert _{A}^{2}\right) +\frac{1}{2}\left\vert
\left\langle T_{k}^{2}x,x\right\rangle _{A}\right\vert \quad
\text{(by the AM-GM inequality)} \\
&=&\frac{1}{4}\left\langle \left( T_{k}^{\sharp
_{A}}T_{k}+T_{k}T_{k}^{\sharp _{A}}\right) x,x\right\rangle _{A}+\frac{1}{2}%
\left\vert \left\langle T_{k}^{2}x,x\right\rangle _{A}\right\vert \text{.}
\end{eqnarray*}

Therefore, 
\begin{eqnarray*}
&&\sum\limits_{k=1}^{n}\left( \alpha \left\vert \left\langle
T_{k}x,x\right\rangle _{A}\right\vert ^{2}+\beta \left\Vert
T_{k}x\right\Vert _{A}^{2}\right) \\
&\leq &\sum\limits_{k=1}^{n}\left( \left\langle \frac{\alpha }{4}\left(
T_{k}^{\sharp _{A}}T_{k}+T_{k}T_{k}^{\sharp _{A}}\right) x,x\right\rangle
_{A}+\frac{\alpha }{2}\left\vert \left\langle T_{k}^{2}x,x\right\rangle
_{A}\right\vert +\beta \left\langle T_{k}^{\sharp _{A}}T_{k}x,x\right\rangle
_{A}\right) \\
&=&\sum\limits_{k=1}^{n}\left\langle \left( \frac{\alpha }{4}\left(
T_{k}^{\sharp _{A}}T_{k}+T_{k}T_{k}^{\sharp _{A}}\right) +\beta
T_{k}^{\sharp _{A}}T_{k}\right) x,x\right\rangle _{A}+\frac{\alpha }{2}%
\sum\limits_{k=1}^{n}\left\vert \left\langle T_{k}^{2}x,x\right\rangle
_{A}\right\vert \\
&=&\sum\limits_{k=1}^{n}\left\langle \left( \left( \frac{\alpha }{4}+\beta
\right) T_{k}^{\sharp _{A}}T_{k}+\frac{\alpha }{4}T_{k}T_{k}^{\sharp
_{A}}\right) x,x\right\rangle +\frac{\alpha }{2}\sum\limits_{k=1}^{n}\left%
\vert \left\langle T_{k}^{2}x,x\right\rangle \right\vert \\
&\leq &\sqrt{n}\left( \left( \sum\limits_{k=1}^{n}\left\vert \left\langle
\left( \left( \frac{\alpha }{4}+\beta \right) T_{k}^{\sharp _{A}}T_{k}+\frac{%
\alpha }{4}T_{k}T_{k}^{\sharp _{A}}\right) x,x\right\rangle _{A}\right\vert
^{2}\right) ^{{1}/{2}}+\frac{\alpha }{2}\left(
\sum\limits_{k=1}^{n}\left\vert \left\langle T_{k}^{2}x,x\right\rangle
_{A}\right\vert ^{2}\right) ^{{1}/{2}}\right) \\
&&\text{(by the }A\text{-Cauchy-Schwarz inequality)} \\
&\leq &\sqrt{n}\left( \omega _{A}\left( \left( \frac{\alpha }{4}+\beta
\right) \mathbf{T}^{\sharp _{A}}\mathbf{T}+\frac{\alpha }{4}\mathbf{TT}%
^{\sharp _{A}}\right) +\frac{\alpha }{2}\omega _{A}\left( \mathbf{T}%
^{2}\right) \right)\text{.}
\end{eqnarray*}
Taking the supremum over all $x\in {\mathcal{H}}$ with $\left\Vert
x\right\Vert _{A}=1$, we get%
\begin{equation*}
\left\Vert \mathbf{T}\right\Vert _{A_{\alpha ,\beta }}^{2}\leq \sqrt{n}%
\left( \omega _{A}\left( \left( \frac{\alpha }{4}+\beta \right) \mathbf{T}%
^{\sharp _{A}}\mathbf{T}+\frac{\alpha }{4}\mathbf{TT}^{\sharp _{A}}\right) +%
\frac{\alpha }{2}\omega _{A}\left( \mathbf{T}^{2}\right) \right) \text{.}
\end{equation*}
This completes the proof.
\end{proof}

Applying Theorem \ref{TH7}, we derive the following result.

\begin{corollary}
\label{CCC}\bigskip\ Let $\mathbf{T}=\left( T_{1},\cdots ,T_{n}\right) \in {%
\mathcal{B}}_{A}\left( {\mathcal{H}}\right) ^{n}$ be an $n$-tuple. Then
\begin{eqnarray*}
\omega _{A}^{2}\left( \mathbf{T}\right) &\leq &\inf\limits_{\alpha ,\beta }%
\frac{\sqrt{n}}{\alpha +\beta }\left\{ \omega _{A}\left( \left( \frac{\alpha 
}{4}+\beta \right) \mathbf{T}^{\sharp _{A}}\mathbf{T}+\frac{\alpha }{4}%
\mathbf{TT}^{\sharp _{A}}\right) +\left. \frac{\alpha }{2}\omega _{A}\left( 
\mathbf{T}^{2}\right) \right\} \right. \\
&\leq &\sqrt{n}\left( \frac{1}{4}\omega _{A}\left( \mathbf{T}^{\sharp _{A}}%
\mathbf{T}+\mathbf{TT}^{\sharp _{A}}\right) +\frac{1}{2}\omega _{A}\left( 
\mathbf{T}^{2}\right) \right) \text{.}
\end{eqnarray*}
\end{corollary}

\begin{remark}
From Corollary \ref{CCC}, we have 
if $A\mathbf{T}^{2}=0$ (i.e., $AT_{k}^{2}=0$ for all $k=1,\cdots,n$), then
\begin{equation*}
\omega _{A}^{2}\left( \mathbf{T}\right) \leq \frac{\sqrt{n}}{4}\omega
_{A}\left( \mathbf{T}^{\sharp _{A}}\mathbf{T}+\mathbf{TT}^{\sharp
_{A}}\right) \text{.}
\end{equation*}
\end{remark}

For the case $n=1$ in Corollary \ref{CCC}, we get 

\begin{corollary}
\label{CX}\bigskip\ Let $T\in {\mathcal{B}}_{A}\left( {\mathcal{H}}\right) $%
. Then%
\begin{equation*}
\omega _{A}^{2}\left( T\right) \leq \inf\limits_{\alpha ,\beta }\frac{1}{%
\alpha +\beta }\left\{ \left\Vert \left( \frac{\alpha }{4}+\beta \right)
T^{\sharp _{A}}T+\frac{\alpha }{4}TT^{\sharp _{A}}\right\Vert _{A}\right.
+\left. \frac{\alpha }{2}\omega _{A}\left( T^{2}\right) \right\} \text{.}
\end{equation*}
\end{corollary}


\begin{remark}
The inequality in Corollary \ref{CX} refines the
inequality (\ref{4}). Indeed, we have 
\begin{eqnarray*}
\omega _{A}^{2}\left( T\right) &\leq &\inf\limits_{\alpha ,\beta }\frac{1}{%
\alpha +\beta }\left\{ \left\Vert \left( \frac{\alpha }{4}+\beta \right)
T^{\sharp _{A}}T+\frac{\alpha }{4}TT^{\sharp _{A}}\right\Vert _{A}\right.
+\left. \frac{\alpha }{2}\omega _{A}\left( T^{2}\right) \right\} \\
&\leq &\frac{1}{4}\left\Vert T^{\sharp _{A}}T+TT^{\sharp _{A}}\right\Vert
_{A}+\frac{1}{2}\omega _{A}\left( T^{2}\right) \text{.}
\end{eqnarray*}
\end{remark}

Finally, we prove the following inequality for the new seminorm.

\begin{theorem}
\label{TTTT}\bigskip\ Let $\mathbf{T}=\left( T_{1},\cdots ,T_{n}\right) \in {
\mathcal{B}}_{A}\left( {\mathcal{H}}\right) ^{n}$, $\mathbf{S}=\left(
S_{1},\cdots ,S_{n}\right) $ $\in {\mathcal{B}}_{A}\left( {\mathcal{H}}%
\right) ^{n}$. Then
\begin{equation*}
\left\Vert \mathbf{S}^{\sharp _{A}}\mathbf{T}\right\Vert _{A_{\alpha ,\beta
}}^{2}\leq \frac{\alpha }{2}\left\Vert \sum\limits_{k=1}^{n}\left( \left(
T_{k}^{\sharp _{A}}T_{k}\right) ^{2}+\left( S_{k}^{\sharp _{A}}S_{k}\right)
^{2}\right) \right\Vert _{A}+\beta \sum\limits_{k=1}^{n}\left\Vert
S_{k}^{\sharp _{A}}T_{k}\right\Vert _{A}^{2}\text{.}
\end{equation*}
\end{theorem}

\begin{proof}
Let $x\in {\mathcal{H}}$ and $\|x\|_A=1$. Then, we have
\begin{eqnarray*}
\sum\limits_{k=1}^{n}\left\vert \left\langle S_{k}^{\sharp
_{A}}T_{k}x,x\right\rangle _{A}\right\vert ^{2}
&=&\sum\limits_{k=1}^{n}\left\vert \left\langle T_{k}x,S_{k}x\right\rangle
_{A}\right\vert ^{2} \\
&\leq &\sum\limits_{k=1}^{n}\left\Vert T_{k}x\right\Vert _{A}^{2}\left\Vert
S_{k}x\right\Vert _{A}^{2} \quad
\text{(by the }A\text{-Cauchy-Schwarz inequality)} \\
%&=&\sum\limits_{k=1}^{n}\left\langle T_{k}x,T_{k}x\right\rangle _{A}\left\langle S_{k}x,S_{k}x\right\rangle _{A} \\
&=&\sum\limits_{k=1}^{n}\left\langle T_{k}^{\sharp
_{A}}T_{k}x,x\right\rangle _{A}\left\langle S_{k}^{\sharp
_{A}}S_{k}x,x\right\rangle _{A} \\
&\leq &\sum\limits_{k=1}^{n}\frac{1}{2}\left( \left\langle T_{k}^{\sharp
_{A}}T_{k}x,x\right\rangle _{A}^{2}+\left\langle S_{k}^{\sharp
_{A}}S_{k}x,x\right\rangle _{A}^{2}\right) 
\text{(by the AM-GM inequality)} \\
&\leq &\sum\limits_{k=1}^{n}\frac{1}{2}\left( \left\langle \left(
T_{k}^{\sharp _{A}}T_{k}\right) ^{2}x,x\right\rangle +\left\langle \left(
S_{k}^{\sharp _{A}}S_{k}\right) ^{2}x,x\right\rangle _{A}\right) \quad
\text{(by Lemma \ref{L2})} \\
&=&\sum\limits_{k=1}^{n}\frac{1}{2}\left\langle \left( \left( T_{k}^{\sharp
_{A}}T_{k}\right) ^{2}+\left( S_{k}^{\sharp _{A}}S_{k}\right) ^{2}\right)
x,x\right\rangle _{A} \\
&\leq &\frac{1}{2}\left\Vert \sum\limits_{k=1}^{n}\left( \left(
T_{k}^{\sharp _{A}}T_{k}\right) ^{2}+\left( S_{k}^{\sharp _{A}}S_{k}\right)
^{2}\right) \right\Vert _{A}\text{.}
\end{eqnarray*}
We also have $\sum_{k=1}^n \left\Vert
S_{k}^{\sharp _{A}}T_{k}x\right\Vert _{A}^{2}\leq \sum_{k=1}^n  \left\Vert
 S_{k}^{\sharp _{A}}T_{k}\right\Vert_{A}^{2}.$
Therefore,
\begin{eqnarray*}
\sum\limits_{k=1}^{n}\left( \alpha \left\vert \left\langle S_{k}^{\sharp
_{A}}T_{k}x,x\right\rangle _{A}\right\vert ^{2}+\beta \left\Vert
S_{k}^{\sharp _{A}}T_{k}x\right\Vert _{A}^{2}\right) 
\leq \frac{\alpha }{2}\left\Vert \sum\limits_{k=1}^{n}\left( \left(
T_{k}^{\sharp _{A}}T_{k}\right) ^{2}+\left( S_{k}^{\sharp _{A}}S_{k}\right)
^{2}\right) \right\Vert +\beta \sum\limits_{k=1}^{n}\left\Vert S_{k}^{\sharp
_{A}}T_{k}\right\Vert ^{2}\text{.}
\end{eqnarray*}
Taking the supremum over all $x\in {\mathcal{H}}$ with $\left\Vert
x\right\Vert _{A}=1$, we get as desired.
%\begin{equation*}
%\left\Vert \mathbf{S}^{\sharp _{A}}\mathbf{T}\right\Vert _{A_{\alpha ,\beta }}^{2}\leq \frac{\alpha }{2}\left\Vert \sum\limits_{k=1}^{n}\left( \left( T_{k}^{\sharp _{A}}T_{k}\right) ^{2}+\left( S_{k}^{\sharp _{A}}S_{k}\right) ^{2}\right) \right\Vert _{A}+\beta \sum\limits_{k=1}^{n}\left\Vert S_{k}^{\sharp _{A}}T_{k}\right\Vert _{A}^{2}\text{.}
