Applying Theorem \ref{TTTT} and Theorem \ref{TH1} (i), we deduce a bound for the $A$-Euclidean operator radius of the product of two $n$-tuples:

\begin{corollary}
\label{CW} Let $\mathbf{T}=\left( T_{1},\cdots ,T_{n}\right) \in {\mathcal{B}%
}_{A}\left( {\mathcal{H}}\right) ^{n}$, $\mathbf{S}=\left( S_{1},\cdots
,S_{n}\right) $ $\in {\mathcal{B}}_{A}\left( {\mathcal{H}}\right) ^{n}$. Then%
\begin{eqnarray*}
\omega _{A}^{2}\left( \mathbf{S}^{\sharp _{A}}\mathbf{T}\right) &\leq
&\inf_{\alpha ,\beta }\frac{1}{\alpha +\beta }\left\{ \frac{\alpha }{2}%
\left\Vert \sum\limits_{k=1}^{n}\left( \left( T_{k}^{\sharp
_{A}}T_{k}\right) ^{2}+\left( S_{k}^{\sharp _{A}}S_{k}\right) ^{2}\right)
\right\Vert _{A}+\beta \sum\limits_{k=1}^{n}\left\Vert S_{k}^{\sharp
_{A}}T_{k}\right\Vert _{A}^{2}\right\} \\
&\leq &\frac{1}{2}\left\Vert \sum\limits_{k=1}^{n}\left( T_{k}^{\sharp
_{A}}T_{k}\right) ^{2}+\left( S_{k}^{\sharp _{A}}S_{k}\right)
^{2}\right\Vert _{A}\text{.}
\end{eqnarray*}
\end{corollary}


Setting $n=1$ in Theorem \ref{TTTT}, we get

\begin{corollary}
Let $T,S\in {\mathcal{B}}_{A}\left( {\mathcal{H}}\right) $. Then%
\begin{equation*}
\left\Vert S^{\sharp _{A}}T\right\Vert _{A_{\alpha ,\beta }}^{2}\leq \frac{%
\alpha }{2}\left\Vert \left( T^{\sharp _{A}}T\right) ^{2}+\left( S^{\sharp
