\begin{document}

\title{A Weighted Divisor problem and Exponential Sum}

\date{}

\author{Kritika Aggarwal}
\address{Kritika Aggarwal\\ Department of Mathematics\\
Indraprastha Institute of Information Technology IIIT, Delhi\\
Okhla, Phase III, New Delhi-110020, India.} 
\email{kritikaa@iiitd.ac.in}

\author{Debika Banerjee}
\address{Debika Banerjee\\ Department of Mathematics\\
Indraprastha Institute of Information Technology IIIT, Delhi\\
Okhla, Phase III, New Delhi-110020, India.} 
\email{debika@iiitd.ac.in}

\thanks{2020 \textit{Mathematics Subject Classification.} Primary 11N37, 11L07, 11M06. Secondary 33C10.\\
\textit{Keywords and phrases.} Exponential sum, Hurwitz zeta function, Derivative of the Riemann zeta function, Mean square, Bessel functions}


\begin{abstract}
In this paper, we investigate a weighted divisor problem involving the exponential sum of $D_{(1)}(n)$, the $n$th coefficient in the Dirichlet series expansion of $\zeta'(s)^2$. We establish a truncated Vorono\"{i} type formula for the error term of $\sum_{n\leq x}D_{(1)}(n)e(nh/k)$, analogous to the results obtained by Jutila. Utilizing this truncated formula, we derive a mean square estimate of the error term. In addition, we study the associated Riesz sum and the corresponding error term, along with its mean square estimate.
\end{abstract}

\maketitle

\section{Introduction}
For $x>0$, $\alpha\in\mathbb{R}$ and $\{b(n)\}$ be any sequence 
\begin{align}
    M(x,\alpha)=\sum_{n\leq x}b(n)e(n\alpha),\label{generalexpsum}
\end{align}
is a type of exponential sum whose upper bound estimates are often desirable in dealing with analytical problems. These estimates play an important role in the study of distribution properties of arithmetical functions and in bounding error terms in asymptotic formulas. We use the standard notation $e_k(\alpha)=e^{2\pi i\alpha/k}$ and $e(\alpha)=e^{2\pi i\alpha}$. \\

In 1937, Vinogradov investigated the exponential sum $f(x) = \sum_{p \leq x} (\log p)e(p x)$ as the generating function to refine the Hardy-Littlewood circle method, and used his technique for estimating
the exponential sums (refer \cite{VNGR} and \cite{VNGR2} for details). His work extended a 1923 result of Hardy and Littlewood, who had shown that every sufficiently large odd integer can be expressed as the sum of three primes under the assumption of the Generalized Riemann Hypothesis. Vinogradov's breakthrough provided an unconditional proof of this result and had further applications in the famous Waring's problem. Other recent works on exponential sums over primes can be found in \cite{AL} and \cite{VR}.\\
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
