We now deduce an identity for the general sum function $B_a(x,h/k)$ for $a\geq 1$ and its corresponding error term, proof of which can be found in Section \ref{pfofgeneralizationth}.
\begin{thm}\label{Generalizationtheorem}
     Let $a\geq 1$ be an integer. Then for $x>0$ and $k\ll x^{\frac12-\varepsilon}$, we have 
    \begin{multline}\label{B_aformula}
        B_a(x,h/k)=\frac{x^{1+a}}{(1+a)!k}\bigg[\frac{1}{6}\log^3 x+\left(\log k-\frac{1}{2}\sum_{n=1}^{a+1}\frac{1}{n}\right)\log^2 x\\
        +\bigg(\log k\bigg(\log k+2\gamma-2\sum_{n=1}^{a+1}1/n\bigg)+\frac{1}{2}\sum_{n=1}^{a+1}\frac{1}{n^2}+\bigg(((a+1)!)^2-\frac{1}{2}\bigg)\bigg(\sum_{n=1}^{a+1}\frac{1}{n}\bigg)^2-2\gamma_1\bigg)\log x\\
    -2\log^3 k+\log^2 k\bigg(2\gamma-\sum_{n=1}^{a+1}\frac{1}{n}\bigg)+\log k\bigg(\sum_{n=1}^{a+1}\frac{1}{n^2}+\bigg((2((a+1)!)^2-1)\sum_{n=1}^{a+1}\frac{1}{n}-2\gamma\bigg)\sum_{n=1}^{a+1}\frac{1}{n}\bigg)\\
    -\frac{1}{3}\sum_{n=1}^{a+1}\frac{1}{n^3}-\bigg(\frac{1}{2}((a+1)!)^2\bigg(\sum_{n=1}^{a+1}\frac{1}{n^2}+\bigg(\sum_{n=1}^{a+1}\frac{1}{n}\bigg)^2\bigg)-\frac{1}{3}\bigg(\sum_{n=1}^{a+1}\frac{1}{n}\bigg)^2-2\gamma_1\bigg)\sum_{n=1}^{a+1}\frac{1}{n}-4\gamma_2\bigg]\\
    +\sum_{n=0}^{a}\frac{(-1)^n}{n!(a-n)!}F(-n,h/k)x^{a-n}+\Delta_a(x,h/k),
    \end{multline}
    where 
    \begin{align}
        \Delta_a(x,h/k)=&-(k/2\pi)^{a}x^{(1+a)/2}\sum_{n=1}^{\infty}\bigg\{\frac{1}{4}d(n)\log^2 x+\left(\frac{1}{2}d(n)\log n+d_{(0,1)}(n)\right)\log x\\
        &+\left(\frac{1}{4}d(n)\log^2 n+d_{(0,1)}(n)\log n+D_{(1)}(n)\right)\bigg\}n^{-(1+a)/2}\times\\
        &\times \left\{e_k(-n\overline{h})Y_{1+a}(4\pi\sqrt{nx}/k)+(-1)^a(2/\pi)e_k(n\overline{h})K_{1+a}(4\pi\sqrt{nx}/k)\right\}\\
        &+O(k^{a+1+\varepsilon}x^{a/2+\varepsilon}).\label{delta_aformula}
    \end{align}   
    where $Y_n(z)$ and $K_n(z)$ represent the Bessel functions of order $n$ defined in \eqref{Ybessel} and \eqref{Kbessel} respectively.
\end{thm}
