\section{Preliminaries}\label{prelims}
This section contains a series of lemmas which will be used repeatedly in the proofs of the main results. Throughout this paper, we will consider 
 \begin{align}\label{chichi1}\chi(s)=2(2\pi)^{s-1}\Gamma(1-s)\sin (\pi s/2)\hspace{2mm} \text{and}\hspace{2mm}\chi_1(s)=2(2\pi)^{s-1}\Gamma(1-s)\cos (\pi s/2).\end{align}
We shall make repeated use of Stirling's formula for $\Gamma(s)$. The following version is precise enough for our purposes.

\begin{lem}\label{gammaformula}\cite[p. 38, Section 21]{HR}
Let $\delta<\pi$ be a fixed positive number. Then in any fixed strip $A_1\leq\sigma\leq A_2$ with $|arg\hspace{1.5mm}s|\leq \pi-\delta$ and $|t|\geq 1$, we have
\begin{align}\label{gammabigestimate}
\Gamma(s)=\sqrt{2\pi}\hspace{1mm}|t|^{s-1/2}exp\left(-\frac{\pi|t|}{2}-it+\frac{i\pi}{2}(\sigma-1/2)sgn(t)\right)\left(1+O(1/|t|)\right),
\end{align}
and
\begin{align}\label{modgammaestimate}
    |\Gamma(s)|=\sqrt{2\pi}\hspace{1mm}|t|^{\sigma-1/2}e^{-(\pi/2)|t|}(1+O(1/|t|)).
\end{align}
Hence, we have
\begin{align}\label{gammasmallestimate}
    \Gamma(s)=O(e^{-(\pi/2)|t|}|t|^{\sigma-1/2}).
\end{align}
\end{lem}

The following lemma shows the estimate for $\chi(s)$.

\begin{lem}\label{chiestimate}
For $s=\sigma+it$, $|t|\geq1$, and $a\leq\sigma\leq b$ ($a$ and $b$ are arbitrary fixed real numbers), we have
\begin{align}
    \chi(\sigma+it)=\bigg(\frac{|t|}{2\pi}\bigg)^{\frac{1}{2}-\sigma-it}e^{i(t\pm \frac{\pi}{4})}\bigg(1+O\bigg(\frac{1}{|t|}\bigg)\bigg),\label{chi}\\
    \chi^2(\sigma+it)=\bigg(\frac{|t|}{2\pi}\bigg)^{1-2\sigma}e^{iE(t)}\bigg(1+O\bigg(\frac{1}{|t|}\bigg)\bigg),\label{chisquare}
\end{align}
where $E(t)$ is defined as
\begin{align}
   E(t)=
   \begin{cases}
       -2t\log\frac{|t|}{2\pi}+2t+\frac{\pi}{2} & (t>0),\\
       -2t\log\frac{|t|}{2\pi}+2t-\frac{\pi}{2} & (t<0).
   \end{cases}\notag
\end{align}
Moreover assume that $|(\sigma-1)/t|<1$. For the $k$th derivative of $\chi(s)$, we have
\begin{align}
    \chi^{(k)}(\sigma+it)=\chi(\sigma+it)\bigg(-\log\frac{|t|}{2\pi}\bigg)^{k}+O\bigg(|t|^{-\frac{1}{2}-\sigma}(\log |t|)^{k-1}\bigg).\label{chikderivative}
\end{align}
\end{lem}

\begin{proof}
    For the formula \eqref{chi} see [\cite{TM}, p. 78, (4.12.3)]. One can refer [\cite{SG}, p. 133, Lemma 6] for \eqref{chikderivative}.
\end{proof}

Analogous estimates for $\chi_1(s)$ can be given as follows :

\begin{lem}\label{chi1estimate}
For $s=\sigma+it$, $|t|\geq1$, and $a\leq\sigma\leq b$ ($a$ and $b$ are arbitrary fixed real numbers), we have
\begin{align}
    \chi_1(\sigma+it)=\bigg(\frac{|t|}{2\pi}\bigg)^{\frac{1}{2}-\sigma-it}e^{i(t\mp \frac{\pi}{4})}\bigg(1+O\bigg(\frac{1}{|t|}\bigg)\bigg),\label{chi1}\\
    \chi_{1}^2(\sigma+it)=\bigg(\frac{|t|}{2\pi}\bigg)^{1-2\sigma}e^{iE(t)}\bigg(1+O\bigg(\frac{1}{|t|}\bigg)\bigg),\label{chi1square}
\end{align}
where
\begin{align}
   E(t)=
   \begin{cases}
       -2t\log\frac{|t|}{2\pi}+2t-\frac{\pi}{2} & (t>0),\\
       -2t\log\frac{|t|}{2\pi}+2t+\frac{\pi}{2} & (t<0).
   \end{cases}\notag
\end{align}
Moreover assume that $|(\sigma-2)/t|<1$. For the $k$th derivative of $\chi_1(s)$, we have
\begin{align}
    \chi_1^{(k)}(\sigma+it)=\chi_1(\sigma+it)\bigg(-\log\frac{|t|}{2\pi}\bigg)^{k}+O\bigg(|t|^{-\frac{1}{2}-\sigma}(\log |t|)^{k-1}\bigg).\label{chi1kderivative}
\end{align}
\end{lem}

\begin{proof}
    For the formula \eqref{chi1}, use equation \eqref{gammabigestimate}. %and $\cos(\frac{\pi s}{2})=\frac{e^{\frac{i\pi s}{2}}+e^{-\frac{i\pi s}{2}}}{2}$.
    Formula \eqref{chi1kderivative} can be proved using induction in the same way as done for the formula \eqref{chikderivative}.
\end{proof}

The next theorem involves a set of complex integrals which can be nicely represented in terms of the Bessel functions, and will be extensively used in the proofs of the main results. The proof follows directly from the theorem of residues.

\begin{lem}\label{integraltobessel}\cite[Lemma 1.5]{JM}
Let $a$ be a nonnegative integer, $\sigma_1\geq-a/2$, $\sigma_2<-a$, $T>0$, and let $C_a$ be the contour joining the points $\sigma_1-i\infty,\sigma_1-Ti,\sigma_2-Ti,\sigma_2+Ti,\sigma_1+Ti,$ and $\sigma_1+i\infty$ by straight lines. Let $X>0$, then
\begin{align}
    I_1=\frac{1}{2\pi i}\int_{C_a}\Gamma^2(1-s)\cos{\pi s}\hspace{1mm}X^s(s(s+1)\cdots(s+a))^{-1}ds=\pi X^{(1-a)/2}Y_{a+1}(2X^{1/2}),\label{firstintegral}
\end{align}
and
\begin{align}
    I_2=\frac{1}{2\pi i}\int_{C_a}\Gamma^2(1-s)X^s(s(s+1)\cdots(s+a))^{-1}ds=2(-1)^{a+1}X^{(1-a)/2}K_{a+1}(2X^{1/2}),\label{secondintegral}
\end{align}
where $Y_n(z)$ and $K_n(z)$ represent the Bessel functions of nonnegative integral order $n$, which can be given as
\begin{align}
    Y_n(X)=(2/\pi X)^{1/2}\sin\bigg(X-\frac{1}{2}n\pi-\frac{1}{4}\pi\bigg)+O(X^{-3/2}),\label{Ybessel}
\end{align}
and
\begin{align}
    K_n(X)=(\pi/2X)^{1/2}e^{-x}(1+O(X^{-1})).\label{Kbessel}
\end{align}
\end{lem}

The proof of \eqref{Ybessel} and \eqref{Kbessel} above can be found in Watson [\cite{GW}, Sections 7.2, 7.21, 7.23].\\

The following elementary lemma on exponential integrals will be of significant use in the proofs that will follow.

\begin{lem}\label{expintegrallemma}\cite[Lemma 4.3, p. 71]{TM}
Let $F(x)$ and $G(x)$ be real functions in the interval $[a,b]$ where $G(x)$ is continuous and $F(x)$ continuously differentiable. Suppose that $G(x)/F'(x)$ is monotonic and $|F'(x)/G(x)|\geq m>0$. Then
$$\left|\int_a^bG(x)e^{iF(x)}dx\right|\leq 4/m.$$
\end{lem}

The lemmas that follow give the Laurent series expansion of the Dirichlet series $F(s,h/k)$ about its singularity, and the functional equation of $F(s,h/k)$ that will be essentially used to study the allied exponential sum, $B(x,h/k)$.
\begin{lem}\label{Fpole}
    The Dirichlet series $F(s,h/k)$ can be continued analytically to a meromorphic function, which is holomorphic in the whole complex plane up to a quadruple pole at $s=1$, and at $s=1$, has the Laurent expansion
\begin{align}
    F(s,h/k)&=k^{-1}(s-1)^{-4}+2k^{-1}\log k\hspace{1mm}(s-1)^{-3}+k^{-1}(\log^{2}k+2\gamma\log k-2\gamma_1)(s-1)^{-2}\notag\\
    &\quad+2k^{-1}(-\log^{3}k+\gamma\log^{2}k-2\gamma_2)(s-1)^{-1}+\ldots,\label{Flaurent}
\end{align}
where the constants $\gamma_1$ and $\gamma_2$ are defined as follows:
\begin{align}
    \zeta(s)=\frac{1}{s-1}+\gamma+\gamma_1(s-1)+\gamma_2(s-1)^2+\ldots.
\end{align}
\end{lem}

\begin{proof}
We first express the function $F(s,h/k)$ in terms of the Hurwitz zeta-function,
\begin{align}
    \zeta(s,a)=\sum_{n=0}^{\infty}(n+a)^{-s} \hspace{0.8cm} (\sigma>1, 0<a\leq1).
\end{align}
One can observe for $\sigma>1$,
\begin{align}
F(s,h/k)&=\sum_{n=1}^{\infty}\bigg(\sum_{d|n}\log d\hspace{0.1cm}\log(n/d)\bigg)e^{\frac{2\pi inh}{k}}n^{-s}\\
   % &=\sum_{m,n=1}^{\infty}\log m\hspace{0.1cm}\log n\hspace{0.1cm}e_k(mnh)\hspace{0.1cm}(mn)^{-s}\\
    &=\sum_{\alpha,\beta=1}^{k}e_k(\alpha\beta h)\sum_{\substack{m\equiv\alpha(mod\hspace{1mm}k) \\n\equiv\beta(mod\hspace{1mm}k)}}\log m\hspace{1mm}\log n\hspace{1mm}(mn)^{-s}\\
    &=\sum_{\alpha,\beta=1}^{k}e_k(\alpha\beta h)\sum_{\mu,\nu=0}^{\infty}\left(\frac{-\log(\alpha+\mu k)}{(\alpha+\mu k)^s}\right)\left(\frac{-\log(\beta+\nu k)}{(\beta+\nu k)^s}\right)\\
&=k^{-2s}\sum_{\alpha,\beta=1}^{k}e_k(\alpha\beta h)\left[\zeta'(s,\alpha /k)-\log k\hspace{1mm}\zeta(s,\alpha/k)\right]\left[\zeta'(s,\beta/k)-\log k\hspace{1mm}\zeta(s,\beta/k)\right],
\end{align}
so that
\begin{align}
F(s,h/k)=\bigg(k^{-2s}&\sum_{\alpha,\beta=1}^{k}e_k(\alpha\beta h)\left[\zeta'(s,\alpha /k)\hspace{1mm}\zeta'(s,\beta/k)-2\log k\hspace{1mm}\zeta(s,\alpha/k)\hspace{1mm}\zeta'(s,\beta/k)\right]\bigg)\notag\\
    &+\log^2 k \hspace{1mm}E(s,h/k),\label{Fexp}
\end{align}
where $E(s,h/k)$ is as defined in \eqref{E(sh/k)defn}, which can also be expressed as
\begin{align}
E(s,h/k)=k^{-2s}\sum_{\alpha,\beta=1}^{k}e_k(\alpha\beta h)\zeta(s,\alpha/k)\zeta(s,\beta/k),\label{Eexp}
\end{align}
(refer [\cite{JM}, eq. (1.1.5)]). This holds first for $\sigma>1$. But $\zeta(s,a)$ can be continued analytically to a meromorphic function having a simple pole with residue 1 at $s=1$ \cite[p. 37]{TM}, and from this it can be easily deduced that $\zeta'(s,a)$ has an analytic continuation with a  pole of order $2$ having residue $0$ at $s=1$. We also notice that $E(s,h/k)$ has an analytic continuation to a meromorphic function with a double pole at $s=1$ as its only singularity \cite[Lemma 1.1]{JM}. Therefore, by equation \eqref{Fexp} we can conclude that $F(s,h/k)$ an analytic continuation, with its only possible pole of order at most $4$, at $s=1$.
\par Next, to study the behavior of $F(s,h/k)$ near $s=1$, we compare it with the function $G(s,h/k)$ which is defined as
\begin{align}
    G(s,h/k)&=\log^2 k\hspace{1mm}E(s,h/k)-2k^{-2s}\log k\hspace{1mm}\zeta'(s)\sum_{\alpha,\beta=1}^{k}e_k(\alpha\beta h)\zeta(s,\alpha/k)\notag\\
    &\hspace{4cm}+k^{-2s}\zeta'(s)\sum_{\alpha,\beta=1}^{k}e_k(\alpha\beta h)\zeta'(s,\alpha/k)\notag\\
    &=\log^2 k\hspace{1mm}E(s,h/k)-2k^{1-2s}\log k\hspace{1mm}\zeta(s)\zeta'(s)+k^{1-2s}(\zeta'(s))^2,\label{compfunc}
\end{align}
where the second step follows from the fact that
\begin{align}
    \sum_{\alpha,\beta=1}^{k}e_k(\alpha\beta h)\zeta(s,\alpha/k)=k\hspace{0.5mm}\zeta(s) \ \ \mbox{and}\ \ \sum_{\alpha,\beta=1}^{k}e_k(\alpha\beta h)\zeta'(s,\alpha/k)=k\hspace{0.5mm}\zeta'(s),
\end{align}
%and  \begin{align}
 %   \sum_{\alpha,\beta=1}^{k}e_k(\alpha\beta h)\zeta'(s,\alpha/k)=k\hspace{0.5mm}\zeta'(s).
%\end{align}
By equation \eqref{Fexp}, one can see
\begin{align}
 F(s,h/k)-G(s,h/k)=   -2k&^{-2s}\log k\sum_{\beta=1}^{k}\left[\sum_{\alpha=1}^{k}e_k(\alpha\beta h)\zeta(s,\alpha/k)\right](\zeta'(s,\beta/k)-\zeta'(s))\notag\\
    &+k^{-2s}\sum_{\beta=1}^{k}\left[\sum_{\alpha=1}^{k}e_k(\alpha\beta h)\zeta'(s,\alpha/k)\right](\zeta'(s,\beta/k)-\zeta'(s)).\label{diff}
\end{align}
Here, the factor $\zeta'(s,\beta/k)-\zeta'(s)$ is holomorphic at $s=1$ for all $\beta$, and vanishes at $\beta=k$. Moreover, the sum with respect to $\alpha$ is also holomorphic at $s=1$ for $\beta\neq k$, thus the difference of $F(s,h/k)$ and $G(s,h/k)$ is holomorphic at $s=1$. Hence $F(s,h/k)$ and $G(s,h/k)$ have the same principal part, which is equal to that given in \eqref{Flaurent}.
\end{proof}
\begin{lem}\label{funceq}
The function $F(s,h/k)$ satisfies the relation
\begin{align}
k^{2s-1}  F(s,h/k)
&= \mathcal{A}_0(s) F(1-s,-\overline{h}/k)+  \mathcal{B}_0(s) F(1-s,\overline{h}/k) \notag\\
&+ \left(-\mathcal{A}_0^{\prime}(s)+2\mathcal{A}_0(s) \log k \right) F_0(1-s,-\overline{h}/k)\notag\\
&+ \left(-\mathcal{B}_0^{\prime}(s)+2\mathcal{B}_0(s) \log k \right) F_0(1-s,\overline{h}/k)\notag\\
&+\left(\mathcal{A}_1(s)-\log k \mathcal{A}_0^{\prime}(s)
    +\log^2 k \mathcal{A}_0(s) \right)E(1-s,-\overline{h}/k) \notag\\
    & +\left(\mathcal{B}_1(s)-\log k\mathcal{B}_0^{\prime}(s)
    +\log^2 k \mathcal{B}_0(s) \right)E(1-s,\overline{h}/k),\label{funceqexp}
\end{align}
where $\mathcal{A}_i(s)=\frac{(\chi^{(i)}(s))^2}{2}-\frac{(\chi_1^{(i)}(s))^2}{2}$, $\mathcal{B}_i(s)=\frac{(\chi^{(i)}(s))^2}{2}+\frac{(\chi_1^{(i)}(s))^2}{2}$,
\begin{align}
    F_0(s,h/k)&=\sum_{n=1}^{\infty}d_{(0,1)}(n)e(nh/k)n^{-s}\hspace{2mm},\hspace{2mm}(\sigma>1),\\
    &=-\sum_{m,n=1}^{\infty}e_k(mnh)\log m (mn)^{-s}.
\end{align}
Also, we note that
\begin{align}\label{F(0)bound}
    F(0,h/k)\ll k\log^3 k.
\end{align}
\end{lem}

