    &+\frac{2\log k}{k}\alpha\log\Gamma(\beta/k)-\log{(2\pi k)}\log\Gamma(\beta/k)+\frac{\log^2 k}{k^2}\alpha\beta\bigg].\label{F(0)exp2}
\end{align}
To estimate the double sums on the right, note that if $1\leq \alpha\leq k-1$ and $\beta$ runs over an arbitrary interval, then using \cite[Theorem 2.1, p. 7]{VC}
\begin{align}
    \left|\sum_{\beta}e_k(\alpha \beta h)\right|\ll ||\alpha h/k||^{-1}.\label{e_kpartialsumbound}
\end{align}
Thus, by repeated use of partial summation,
\begin{align}
    \left|\sum_{\alpha=1}^{k-1}\sum_{\beta=1}^{k}e_k(\alpha\beta h)\log\Gamma(\alpha/k)\log\Gamma(\beta/k)\right|&\ll \log k\sum_{\alpha=1}^{k-1}\log\Gamma(\alpha/k)\hspace{1mm}||\alpha h/k||^{-1}
    \ll k\log^3 k.\label{F(0)firstsum}
\end{align}
Similarly, we can have
\begin{align}
\left|\sum_{\alpha=1}^{k}\sum_{\beta=1}^{k}e_k(\alpha\beta h)\alpha\log\Gamma(\beta/k)\right|&\leq\left|\sum_{\alpha=1}^{k-1}\alpha\sum_{\beta=1}^{k}e_k(\alpha\beta h)\log\Gamma(\beta/k)\right|+k\left|\sum_{\beta=1}^{k}\log\Gamma(\beta/k)\right|\notag\\
    &\ll \log k\sum_{\alpha=1}^{k-1}\alpha||\alpha h/k||^{-1}+k(k+\log k)\notag\\
    &\ll k^2 \log k.\label{F(0)secondsum}
\end{align}
Also, the bounds
\begin{align}\label{F(0)thirdsum}
\left|\sum_{\alpha=1}^{k}\sum_{\beta=1}^{k}e_k(\alpha\beta h)\log\Gamma(\beta/k)\right|\ll k\log k,
\end{align}
and
\begin{align}\label{F(0)fourthsum}
\left|\sum_{\alpha=1}^{k}\sum_{\beta=1}^{k}e_k(\alpha\beta h)\alpha\beta\right|\ll k^3
\end{align}
can be obtained similarly. Thus, \eqref{F(0)bound}  follows from \eqref{F(0)exp2}-\eqref{F(0)fourthsum}.
