\section{Proof of Theorem \ref{Delta0meansqtheorem}}\label{pfofmeansq1}
For $T\ll k$, we trivially have
\begin{align}\label{meansq2}
        \int_1^T|\Delta(x,h/k)|^2dx\ll k^2\log^6k \hspace{1mm} T,
    \end{align}
    by \eqref{B_0formula} and \eqref{F(0)bound}. It is then sufficient to prove the formula  for $k\leq T$,
    \begin{align}\label{meansq1}
\int_T^{2T}|\Delta(x,h/k)|^2dx=\mathcal{H}(T)+O(k^2T^{1+\varepsilon})+O(k^{3/2}T^{5/4+\varepsilon})
\end{align}
where $\mathcal{H}(T)$ is given by
\begin{align}
\mathcal{H}(T)&=
\frac{kx^{3/2}}{6\pi^2}\sum_{n=1}^{\infty}\frac{1}{n^{3/2}}\bigg[\frac{1}{16}d^2(n)\sum_{i=0}^{4}\left(-\frac{2}{3}\right)^{i}{}^4P_i(\log x)^{4-i}\notag\\
  & +\frac{1}{2}d(n)f_1(n)\sum_{i=0}^{3}\left(-\frac{2}{3}\right)^{i}{}^3P_i\hspace{1mm}(\log x)^{3-i} \notag \\
    &+\frac{1}{2}(d(n)f_2(n)+f_1^2(n))\sum_{i=0}^{2}\left(-\frac{2}{3}\right)^{i}{}^2P_i\hspace{1mm}(\log x)^{2-i} \notag\\
    &+2f_1(n)f_2(n)\sum_{i=0}^{1}\left(-\frac{2}{3}\right)^{i}{}^1P_i\hspace{1mm}(\log x)^{1-i}+f_2^2(n)\bigg]\bigg|_T^{2T}\label{meansq11},
    \end{align}
    since we can substitute $T$ by $X/2$, $X/2^2$, $\cdots$, and \eqref{meansquareestimate} then follows easily from \eqref{meansq2} and \eqref{meansq1}.
    To prove \eqref{meansq1}, let $T\leq x\leq 2T$ and choose $N=T$ in \eqref{errorformula}, which can be written as
    \begin{align}\label{meansq3}
    \Delta(x,h/k)=S(x,h/k)+O(kx^\varepsilon).
    \end{align}
    Squaring out $|S(x,h/k)|^2$, we obtain
    \begin{align}\label{meansq4}
\int_T^{2T}|S(x,h/k)|^2dx=S_0+O(k\left(|S_{1}|+|S_2|\right)),
    \end{align}
    where
    \begin{align}
    S_0=\frac{k}{4\pi^2}\sum_{n\leq T}n^{-3/2}\int_T^{2T}&x^{1/2}\bigg[\frac{1}{16}d^2(n)\log^4x+\frac{1}{2}d(n)f_1(n)\log^3x \notag \\
    &+\frac{1}{2}\left(d(n)f_2(n)+f_1^2(n)\right)\log^2x+2f_1(n)f_2(n)\log x+f_2^2(n)\bigg]dx, \label{S0}
    \end{align}
    \begin{align}
        S_1=\underset{\substack{n,m\leq T\\ m\neq n}}{\sum}(m&n)^{-3/4}\int_T^{2T}x^{1/2}e(2(\sqrt{m}-\sqrt{n})\sqrt{x}/k)\bigg[\frac{1}{16}d(n)d(m)\log^4x+\frac{1}{2}d(n)f_1(m)\log^3x\\
        &+\left(\frac{1}{2}d(n)f_2(m)+f_1(n)f_1(m)\right)\log^2x+2f_1(n)f_2(m)\log x+f_2(n)f_2(m)\bigg]dx,
    \end{align}
    and
    \begin{align}
        S_2=\sum_{m,n\leq T}(m&n)^{-3/4}\int_T^{2T}x^{1/2}e(2(\sqrt{m}+\sqrt{n})\sqrt{x}/k)\bigg[\frac{1}{16}d(n)d(m)\log^4x+\frac{1}{2}d(n)f_1(m)\log^3x\\
        &+\left(\frac{1}{2}d(n)f_2(m)+f_1(n)f_1(m)\right)\log^2x+2f_1(n)f_2(m)\log x+f_2(n)f_2(m)\bigg]dx,
    \end{align}
    $f_1(n)$ and $f_2(n)$ are as given in \eqref{f1f2exp}. To establish the necessary bounds for $S_1$ and $S_2$, we first deduce the following lemma.
    \begin{lem}\label{meansqlem1}
        Let $a(n)$, $b(n)$ be arithmetical functions $\ll n^{\varepsilon}$ for all $n \geq n_0$ and $\varepsilon>0$. Then for $0\leq i\leq 4$, $i\in\mathbb{Z}$ and $T\geq 1$, we have
        \begin{align}
            \underset{\substack{n,m\leq T\\ m\neq n}}{\sum}a(m)b(n)(mn)^{-3/4}\int_T^{2T}x^{1/2}e(2(\sqrt{m}\pm\sqrt{n})\sqrt{x}/k)\log^i x\hspace{0.5mm}dx\ll kT^{1+\varepsilon}.\label{meansqlemineq}
        \end{align}
    \end{lem}
    \begin{proof}
    Using Lemma \eqref{expintegrallemma},
        \begin{align}
           \int_T^{2T}x^{1/2}e(2(\sqrt{m}\pm\sqrt{n})\sqrt{x}/k)\log^i x\hspace{0.5mm}dx\ll kT|\sqrt{n}\pm\sqrt{m}|^{-1}\log^i x.
        \end{align}
        Thus, the expression in \eqref{meansqlemineq} is
        \begin{align}
         %   &\ll \underset{\substack{n,m\leq T\\ m< n}}{\sum}a(m)b(n)(mn)^{-3/4}\int_T^{2T}x^{1/2}e(2(\sqrt{m}\pm\sqrt{n})\sqrt{x}/k)\log^i x\hspace{0.5mm}dx\\
            &\ll k\hspace{0.5mm}T^{1+\varepsilon}\underset{\substack{n,m\leq T\\ m< n}}{\sum}m^{-3/4}n^{-1/4}(n\pm m)^{-1}\notag\\
           &\ll k\hspace{0.5mm}T^{1+\varepsilon}\sum_{m\leq T}m^{-1}\ll k\hspace{0.5mm}T^{1+\varepsilon}.
        \end{align}
    \end{proof} 
    Next, simplifying the expression for $S_0$
  in \eqref{S0}, we obtain
\begin{align} \label{Po}
S_0 = \mathcal{H}(T),
\end{align}
where $\mathcal{H}(T)$ is defined in \eqref{meansq11}.
We now apply Lemma \eqref{meansqlem1} to obtain the bounds
\begin{align}
 S_1\ll kT^{1+\varepsilon}\  \ \mbox{and}  \ \  S_2\ll kT^{1+\varepsilon}.
\end{align}
Using these estimates, together with equations \eqref{Po}, \eqref{meansq3}, and \eqref{meansq4}, and applying the Cauchy–Schwarz inequality, we prove  \eqref{meansq1}.
\par Hence combining \eqref{meansq2} with \eqref{meansq1}, and taking into account $k\ll X^{\frac12-\varepsilon}$ we conclude the proof.
