\section{Proof of Theorem \ref{Generalizationtheorem}}\label{pfofgeneralizationth}
    Let $\varepsilon>0$ be arbitrarily small. By a well-known summation formula [\cite{AI}, equation (A.14), p. 487], we have for any $c>1$,
    \begin{align}
        B_a(x,h/k)=\frac{1}{2\pi i}\int_{(c)}F(s,h/k)x^{s+a}(s(s+1)\cdots (s+a))^{-1}ds.\label{Baperron}
    \end{align}
   We take $a\geq 1$ and deform the path of integration to a broken contour 
 $C_a$ passing through $-a/2+\varepsilon-i\infty$, $-a/2+\varepsilon-iT$, $-a-1/2-iT$, $-a-1/2+iT$, $-a/2+\varepsilon+iT$ and $-a/2+\varepsilon+i\infty$. Since $a\geq1$, we may choose 
$\varepsilon>0$ small enough such that $-a/2+\varepsilon<0$. Noting that $F(s,h/k)$ has a singularity at $s=1$, we define an auxiliary function as done in \eqref{auxfunc}. Then these two functions have the same order of magnitude in the region $|t|\geq 1$, $-a/2+\varepsilon\leq \sigma\leq c$. To estimate the auxiliary function on the line $\sigma=-a/2+\varepsilon$, we apply the functional equation \eqref{altfunceq}.
  \par  Using the Phragm\'{e}n-Lindel\"{o}f principle [\cite{HR}, (33.4)], we obtain that the integrand is 
    $$\ll |t|^{-\varepsilon} \hspace{2mm}\text{for} \hspace{2mm}|t|\geq 1\hspace{2mm} \text{and}\hspace{1mm} -a/2+\varepsilon\leq \sigma\leq c.$$ Thus the integral vanishes as $|t|\rightarrow \infty$. Choose $T=\frac{C_0\sqrt{x}}{k}$ to be sufficiently large, where $C_0>0$ is some constant. Then by Cauchy's residue theorem,
\begin{align}
    B_a(x,h/k)&=\left(\underset{s=-a}{Res}+\cdots+\right.\left.\underset{s=1}{Res}\right)F(s,h/k)x^{s+a}(s(s+1)\cdots(s+a))^{-1}\notag \\
    &+\underbrace{\frac{1}{2\pi i}\int_{C_a}F(s,h/k)x^{s+a}(s(s+1)\cdots(s+a))^{-1}ds}_{\mathcal{S}_a(x)}. \label{B_acauchyth}
\end{align}
    Note that the residue at $s=1$ gives the initial terms in \eqref{B_aformula}, and the sum of other residues equals
\begin{align}\sum_{i=0}^{a}\frac{(-1)^i}{i!(a-i)!}F(-i,h/k)x^{a-i}.\end{align}
    We now express $F(s,h/k)$ in $\mathcal{S}_a(x)$ in \eqref{B_acauchyth} using the functional equation \eqref{funceqexp} to obtain
    \begin{align}
\mathcal{S}_a(x)=&kx^a\Bigg[\sum_{n=1}^{\infty}\frac{d(n)}{2n}\left(e_k(n\overline{h})+e_k(-n\overline{h})\right)\frac{1}{2\pi i}\int_{C_a}(\chi'(s))^2\left(\frac{nx}{k^2}\right)^s (s(s+1)\cdots(s+a))^{-1}ds\notag\\
    &+\sum_{n=1}^{\infty}\frac{d(n)}{2n}\left(e_k(n\overline{h})-e_k(-n\overline{h})\right)\frac{1}{2\pi i}\int_{C_a}(\chi_1'(s))^2\left(\frac{nx}{k^2}\right)^s (s(s+1)\cdots(s+a))^{-1}ds\notag\\
    &-\sum_{n=1}^{\infty}\frac{(d(n)\log k+d_{(0,1)}(n))}{n}\left(e_k(n\overline{h})+e_k(-n\overline{h})\right)\times\\
    &\hspace{4cm}\times\frac{1}{2\pi i}\int_{C_a}\chi(s)\chi'(s)\left(\frac{nx}{k^2}\right)^s (s(s+1)\cdots(s+a))^{-1}ds\notag\\
&-\sum_{n=1}^{\infty}\frac{(d(n)\log k+d_{(0,1)}(n))}{n}\left(e_k(n\overline{h})-e_k(-n\overline{h})\right)\times\\
    &\hspace{4cm}\times\frac{1}{2\pi i}\int_{C_a}\chi_1(s)\chi_1'(s)\left(\frac{nx}{k^2}\right)^s (s(s+1)\cdots(s+a))^{-1}ds\notag\\
&+\sum_{n=1}^{\infty}\frac{(d(n)\log^2 k+2d_{(0,1)}(n)\log k+D_{(1)}(n))}{2n}\left(e_k(n\overline{h})+e_k(-n\overline{h})\right)\times\\
&\hspace{4cm}\times\frac{1}{2\pi i}\int_{C_a}(\chi(s))^2\left(\frac{nx}{k^2}\right)^s(s(s+1)\cdots(s+a))^{-1} ds\notag\\
    &+\sum_{n=1}^{\infty}\frac{(d(n)\log^2 k+2d_{(0,1)}(n)\log k+D_{(1)}(n))}{2n}\left(e_k(n\overline{h})-e_k(-n\overline{h})\right)\times\\
&\hspace{4cm}\times\frac{1}{2\pi i}\int_{C_a}(\chi_1(s))^2\left(\frac{nx}{k^2}\right)^s(s(s+1)\cdots(s+a))^{-1} ds\Bigg].\label{S_aformula}
    \end{align}
     %Since the integrals are similar over both the intervals $[-a/2+1/2+\theta+iT, -a/2+1/2+\theta+i\infty]$ and $[-a/2+1/2+\theta-i\infty, -a/2+1/2+\theta-iT]$, we consider only the first case.\\
Since $a\geq 1$ the above expression is valid in the region $\Re(s)\leq -a/2+\varepsilon<0$. 
\par For $X_n=\frac{nx}{k^2}$, let us consider
     \begin{align}
        F_1(X_n)&=\frac{1}{2\pi i}\int_{C_a}(\chi(s))^2X_n^s(s(s+1)\cdots(s+a))^{-1} ds\\
        &=\frac{1}{2\pi^2}\bigg[\underbrace{\frac{1}{2\pi i}\int_{C_a}\Gamma^2(1-s)(4\pi^2X_n)^{s}(s(s+1)\cdots(s+a))^{-1}ds}_{\mathcal{H}_1(X_n)}\\
        &\hspace{1cm}-\underbrace{\frac{1}{2\pi i}\int_{C_a}\Gamma^2(1-s)\cos(\pi s)(4\pi^2X_n)^{s}(s(s+1)\cdots(s+a))^{-1}ds}_{\mathcal{H}_2(X_n)}\bigg],\label{F11}
    \end{align}
    where the second equality above holds by \eqref{chichi1}. Next we observe that
    \begin{align}
        F_2(X_n)&=\frac{1}{2\pi i}\int_{C_a}\chi(s)\chi'(s)X_n^s (s(s+1)\cdots(s+a))^{-1}ds \\
     &=\frac{1}{4\pi i}\int_{C_a}(\chi^2(s)'X_n^s (s(s+1)\cdots(s+a))^{-1}ds.\label{F21}
    \end{align}
    Using integration by parts,
\begin{align}
    F_2(X_n)=&\frac{\log X_n}{4\pi^2}\bigg[\frac{1}{2\pi i}\int_{C_a}\Gamma^2(1-s)\cos(\pi s)(4\pi^2X_n)^{s}(s(s+1)\cdots(s+a))^{-1}ds\\
    &-\frac{1}{2\pi i}\int_{C_a}\Gamma^2(1-s)(4\pi^2X_n)^{s}(s(s+1)\cdots(s+a))^{-1}ds\bigg]+O(X_n^{-a/2+1/2+\theta}T^{-1-2\theta})\notag\\
    &=\frac{\log X_n}{4\pi^2}\bigg [\mathcal{H}_2(X_n)-\mathcal{H}_1(X_n)\bigg]+O(X_n^{-a/2+\varepsilon}T^{-2\varepsilon})\label{F22}
\end{align}
where the error terms in \eqref{F22} comes by estimating the integrals of the type
\begin{align}\label{Error type}
    \int_{T}^{\infty}X_n^{-a/2+\varepsilon}|t|^{-1-\epsilon}dt\ll X_n^{-a/2+\varepsilon}T^{-\varepsilon}.
\end{align}
It remains to investigate $F_3(X_n)$. Again a simple calculation shows 
    \begin{align}
        F_3(X_n)&=\frac{1}{2\pi i}\int_{C_a}(\chi'(s))^2X_n^s (s(s+1)\cdots(s+a))^{-1}ds\\
        &=\underbrace{\frac{1}{2\pi i}\int_{C_a}(\chi(s)\chi'(s))'X_n^s (s(s+1)\cdots(s+a))^{-1}ds}_{\mathcal{J}_1(X_n)}\\
        &-\underbrace{\frac{1}{2\pi i}\int_{C_a}\chi(s)\chi''(s)X_n^s (s(s+1)\cdots(s+a))^{-1}ds}_{\mathcal{J}_2(X_n)}.\label{F31}
    \end{align}
    Using integration by parts in the first integral on right hand side of \eqref{F31}, we have
    \begin{align}
       \mathcal{J}_1(X_n)
        &=-(\log X_n)F_2(X_n)+O(X_n^{-a/2+\varepsilon}T^{-\varepsilon}),\label{F32}
    \end{align}
    where error term in expression  \eqref{F32} arises from estimating integrals of the type 
    \begin{align}
        \int_T^{\infty}X_n^{-a/2+\varepsilon}|t|^{-1-2\varepsilon}\log|t|dt\ll X_n^{-a/2+\varepsilon}T^{-\varepsilon}.
    \end{align}
    Using Lemma \eqref{chiestimate},
    \begin{align}
\mathcal{J}_2(X_n)=\int_{C_a}\llap{=\hspace{9.3pt}}\left(\frac{|t|}{2\pi}\right)^{1-2\sigma}\left(-\log\frac{|t|}{2\pi}\right)^2e^{iE(t)}X_n^{s}(s(s+1)\cdots(s+a))^{-1}ds+O(X_n^{-a/2+\varepsilon}T^{-\varepsilon}),\label{F32.5}
    \end{align}
    taking the integral over $[-a-1/2-iT_0,-a-1/2+iT_0]$ also in the error term above, for sufficiently large fixed $T_0<T$. Also note that the integral in \eqref{F32.5} over the horizontal segments of $C_a$ is
    \begin{align}
        \ll\int_{-a-1/2}^{-a/2+\varepsilon}T^{-a-2\sigma}\log^2T\hspace{1mm}X_n^{\sigma}d\sigma\ll X_n^{-a/2+\varepsilon}T^{-\varepsilon}.\label{F32.6}
    \end{align}
    Next, over the interval $T\leq |t|\leq \infty$ and $\sigma=-a/2+\varepsilon$, $\frac{d}{dt}\left(\frac{e^{iE(t)}}{2i}\right)=\left(-\log \frac{|t|}{2\pi}\right)e^{iE(t)}$. Hence, using integration by parts, the integral on the right hand side of \eqref{F32.5} equals
    \begin{align}
        \frac{\log X_n}{2i}\int_{T}^{\infty}\left(\frac{|t|}{2\pi}\right)^{1+a-2\varepsilon}\left(-\log\frac{|t|}{2\pi}\right)e^{iE(t)\hspace{1mm}}X_n^{s}&(s(s+1)\cdots(s+a)^{-1}ds+O(X_n^{-a/2+\varepsilon}T^{-\varepsilon}).
    \end{align}
    Again using integration by parts on the above integral, we get
    \begin{align}
        &\left(\int_{-a/2+\varepsilon-i\infty}^{-a/2+\varepsilon-iT}+\int_{-a/2+\varepsilon+iT}^{-a/2+\varepsilon+i\infty}\right)\chi(s)\chi''(s)X_n^s(s(s+1)\cdots(s+a))^{-1}ds\\
        &=\frac{1}{4}\log^2 X_n \left(\int_{-\infty}^{-T}+\int_{T}^{\infty}\right)\left(\frac{|t|}{2\pi}\right)^{1+a-2\varepsilon}e^{iE(t)}(1+O(1/t))\hspace{1mm}X_n^{s}(s(s+1)\cdots(s+a))^{-1}ds\\
        &\hspace{7cm}+O(X_n^{-a/2+\varepsilon}T^{-\varepsilon}(1+\log X_n+\log^2 X_n)).\label{F33}
    \end{align}
    Similarly, we can obtain
    \begin{align}
        &\left(\int_{-a-1/2-iT}^{-a-1/2-iT_0}+\int_{-a-1/2+iT_0}^{-a-1/2+iT}\right)\chi(s)\chi''(s)X_n^s(s(s+1)\cdots(s+a))^{-1}ds\\
        &=\frac{1}{4}\log^2 X_n \left(\int_{-T}^{-T_0}+\int_{T_0}^{T}\right)\left(\frac{|t|}{2\pi}\right)^{2a+2}e^{iE(t)}(1+O(1/t))\hspace{1mm}X_n^{s}(s(s+1)\cdots(s+a))^{-1}ds\\
        &\hspace{6cm}+O(X_n^{-a-1/2}T^{a+1+\varepsilon}(1+\log X_n+\log^2 X_n)).\label{F34}
    \end{align}
    Combining \eqref{F32.6}, \eqref{F33} and \eqref{F34} together with \eqref{F32.5} gives
    \begin{align}
        \mathcal{J}_2(X_n)=\frac{1}{4}\log^2{X_n}F_1(X_n)+O(X_n^{-a/2+\varepsilon}T^{-\varepsilon}(1+\log X_n+\log^2 X_n)).\label{J2final}
    \end{align}
    By \eqref{F31}, \eqref{F32} and \eqref{J2final},
    \begin{align}
        F_3(X_n)=-\frac{1}{4}\log^2 X_nF_1(X_n)-&\log X_nF_2(X_n)+O(X_n^{-a/2+\varepsilon}T^{-\varepsilon}(1+\log X_n+\log^2 X_n)).
\end{align}
Next employing \eqref{F11} and \eqref{F22} in the above expression and simplifying,  we obtain
       \begin{align} 
   F_3(X_n) &=\frac{1}{8\pi^2} \log^2 X_n(\mathcal{H}_1(X_n)-\mathcal{H}_2(X_n))+O(X_n^{-a/2+\varepsilon}T^{-\varepsilon}(1+\log X_n+\log^2 X_n)). \label{99}
    \end{align}
    Similarly, we may evaluate the integrals involving $\chi_1^2(s)$, $\chi_1\chi_1'(s)$ and $(\chi_1'(s))^2$ in \eqref{S_aformula}. Now employing the above facts together with \eqref{F11}, \eqref{F22} and \eqref{99} in \eqref{S_aformula}, we get
    \begin{align}
        \mathcal{S}_a(x)&=\frac{kx^a}{4\pi^2}\Bigg[\sum_{n=1}^{\infty}\frac{d(n)}{4n}\left(e_k(n\overline{h})+e_k(-n\overline{h})\right)\log^2\left(\frac{nx}{k^2}\right)\left\{\mathcal{H}_1\left(\frac{nx}{k^2}\right)-\mathcal{H}_2\left(\frac{nx}{k^2}\right)\right\}\\
    &+\sum_{n=1}^{\infty}\frac{d(n)}{4n}\left(e_k(n\overline{h})-e_k(-n\overline{h})\right)\log^2\left(\frac{nx}{k^2}\right)\left\{\mathcal{H}_1\left(\frac{nx}{k^2}\right)+\mathcal{H}_2\left(\frac{nx}{k^2}\right)\right\}\notag\\
    &+\sum_{n=1}^{\infty}\frac{(d(n)\log k+d_{(0,1)}(n))}{n}\left(e_k(n\overline{h})+e_k(-n\overline{h})\right)\log\left(\frac{nx}{k^2}\right)\left\{\mathcal{H}_1\left(\frac{nx}{k^2}\right)-\mathcal{H}_2\left(\frac{nx}{k^2}\right)\right\}\notag\\
&+\sum_{n=1}^{\infty}\frac{(d(n)\log k+d_{(0,1)}(n))}{n}\left(e_k(n\overline{h})-e_k(-n\overline{h})\right)\log\left(\frac{nx}{k^2}\right)\left\{\mathcal{H}_1\left(\frac{nx}{k^2}\right)+\mathcal{H}_2\left(\frac{nx}{k^2}\right)\right\}\notag\\
&+\sum_{n=1}^{\infty}\frac{(d(n)\log^2 k+2d_{(0,1)}(n)\log k+D_{(1)}(n))}{n}\left(e_k(n\overline{h})+e_k(-n\overline{h})\right)\left\{\mathcal{H}_1\left(\frac{nx}{k^2}\right)-\mathcal{H}_2\left(\frac{nx}{k^2}\right)\right\}\notag\\
    &+\sum_{n=1}^{\infty}\frac{(d(n)\log^2 k+2d_{(0,1)}(n)\log k+D_{(1)}(n))}{n}\left(e_k(n\overline{h})-e_k(-n\overline{h})\right)\left\{\mathcal{H}_1\left(\frac{nx}{k^2}\right)+\mathcal{H}_2\left(\frac{nx}{k^2}\right)\right\}\Bigg]\\
    &+O(k^{a+1+\varepsilon}x^{a/2+\varepsilon}).\label{S_aformula2}
    \end{align}
     Note that $\mathcal{H}_1\left(\frac{nx}{k^2}\right)$ and $\mathcal{H}_2\left(\frac{nx}{k^2}\right)$ are of the type $I_1$ and $I_2$ in Lemma \eqref{integraltobessel}. Utilizing  \eqref{firstintegral}, \eqref{secondintegral} in \eqref{S_aformula2} and then substituting the resultant expression in \eqref{B_acauchyth}, we can conclude \eqref{delta_aformula} for $a\geq 1$.\\
    %Next we differentiate both sides of \eqref{B_aformula} with respect to $x$. 
    \iffalse
    By the definition \eqref{Rieszdefn} we have 
    \begin{align}\label{B_a'exp}
        B_a'(x,h/k)=B_{a-1}(x,h/k),
    \end{align}
and the main terms in the right hand side of \eqref{B_aformula} are differentiable with respect to $x$  for $a\geq 1$, and consequently by \eqref{B_aformula},
    \begin{align}\label{delta_a'exp}
        \Delta_a'(x,h/k)=\Delta_{a-1}(x,h/k).
    \end{align}
    Upon differentiating the right hand side of \eqref{delta_aformula}, the resulting expression equals the expression of \eqref{delta_aformula} with $a$ replaced by $a-1$. This can be verified using the identities 
    \begin{align}
        (x^nK_n(x))'=-x^nK_{n-1}(x)
    \end{align}
    and 
    \begin{align}
        (x^n Y_n(x))'=x^nY_{n-1}(x).
    \end{align}
    Hence, \eqref{delta_aformula} shares the property \eqref{delta_a'exp}.
    By \eqref{Kbessel} and \eqref{Ybessel}, the series in \eqref{delta_aformula} converges absolutely for $a\geq 1$. Moreover, the convergence is uniform in any interval $[x_1,x_2]\subset (0,\infty)$, which justifies the differentiation term by term for $a\geq 2$. This argument proves \eqref{B_aformula} and \eqref{delta_aformula} for $a=1$ also.
