%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Proof of Theorem \ref{Deltaameansqformula}}\label{pfofmeansq2}
The proof is similar to that of Theorem \eqref{Delta0meansqtheorem}.\\
We first establish a bound for $F(-n,h/k)$ for $0\leq n\leq a$, $a\in\mathbb{Z}$. By \eqref{Fexp},
\begin{align}
    F(-n,h/k)=k^{2n}\sum_{\alpha,\beta=1}^ke_k(\alpha\beta h)\big[&\zeta'(-n,\alpha/k)\zeta'(-n,\beta/k)-2\log k\hspace{1mm}\zeta(-n,\alpha/k)\zeta'(-n,\beta/k)\\
    &+\log^2 k\hspace{1mm}\zeta(-n,\alpha/k)\zeta(-n,\beta/k)\big]. 
\end{align}
Using \eqref{e_kpartialsumbound}, \eqref{zetaexp}, \eqref{zeta'exp} and properties of the Gamma function, we obtain
\begin{align}
    F(-n,h/k)\ll k^{2n+1}\log^3 k
\end{align}
by employing partial summation. Thus, if $T\ll k^2$, then by \eqref{B_aformula} we have 
$$\Delta_a(x,h/k)\ll k^{2a+1}\log^3 k .$$
Hence, for $T\ll k^2$, we trivially have
\begin{align}
    \int_T^{2T}|\Delta_a(x,h/k)|^2dx\ll k^{4a+2}\log^6k\hspace{1mm}T.\label{deltaameansq1}
\end{align}
Next, for $k^2<T$, let $T\leq x\leq 2T$, then formula \eqref{delta_aformula} can be written as 
\begin{align}
    \Delta_a(x,h/k)=U(x,h/k)+O(k^{a+1+\varepsilon}\hspace{0.5mm}x^{a/2+\varepsilon}),\label{deltaameansq2}
\end{align}
where
\begin{align}
    U(x,h/k)=\pi^{-\frac{1}{2}}(k/2\pi)^{a+\frac{1}{2}}x^{\frac{a}{2}+\frac{1}{4}}&\sum_{n=1}^{\infty}\Bigg\{\frac{1}{4}d(n)\log^2 x+\left(\frac{1}{2}d(n)\log n+d_{(0,1)}(n)\right)\log x\\
        &\hspace{0.5cm}+\left(\frac{1}{4}d(n)\log^2 n+d_{(0,1)}(n)\log n+D_{(1)}(n)\right)\Bigg\}\times\notag\\
        &\times n^{-\left(\frac{a}{2}+\frac{3}{4}\right)} e_k(-n\overline{h})\cos(4\pi\sqrt{nx}/k-\pi/4-\pi a/2).
\end{align}
Squaring $|U(x,h/k)|^2$ and integrating term by term, we obtain
\begin{align}
    \int_T^{2T}|U(x,h/k)|^2dx=U_0+O(k^{2a+1}(|U_1|+|U_2|)),\label{deltaameansq3}
\end{align}
where
\begin{align}
    U_0=\frac{1}{2\pi}(k/2\pi)^{2a+1}&\sum_{n=1}^{\infty}n^{-(a+3/2)}\int_T^{2T}x^{a+1/2}\bigg[\frac{1}{16}d^2(n)\log^4x+\frac{1}{2}d(n)f_1(n)\log^3x\\
    &+\frac{1}{2}\left(d(n)f_2(n)+f_1^2(n)\right)\log^2x+2f_1(n)f_2(n)\log x+f_2^2(n)\bigg]dx,
\end{align}
\begin{align}
    U_1&=\sum_{m,n=1 \atop{m\neq n}}^{\infty}(mn)^{-\left(\frac{a}{2}+\frac{3}{4}\right)}\int_T^{2T}x^{a+1/2}e(2(\sqrt{m}-\sqrt{n})\sqrt{x}/k)\times\\
        &\hspace{3.5cm}\times\bigg\{\frac{1}{16}d(n)d(m)\log^4x+\frac{1}{2}d(n)f_1(m)\log^3x\\
        &\hspace{1cm}+\left(\frac{1}{2}d(n)f_2(m)+f_1(n)f_1(m)\right)\log^2x+2f_1(n)f_2(m)\log x+f_2(n)f_2(m)\bigg\}dx,
\end{align}
\begin{align}
    U_2&=\sum_{m,n=1}^{\infty}(mn)^{-\left(\frac{a}{2}+\frac{3}{4}\right)}\int_T^{2T}x^{a+1/2}e(2(\sqrt{m}+\sqrt{n})\sqrt{x}/k)\times\\
        &\hspace{3.5cm}\times\bigg\{\frac{1}{16}d(n)d(m)\log^4x+\frac{1}{2}d(n)f_1(m)\log^3x\\
        &\hspace{1cm}+\left(\frac{1}{2}d(n)f_2(m)+f_1(n)f_1(m)\right)\log^2x+2f_1(n)f_2(m)\log x+f_2(n)f_2(m)\bigg\}dx,
\end{align}
where $f_1(n)$ and $f_2(n)$ are same as defined in \eqref{f1f2exp}. We now use the following lemma to establish bounds on $U_1$ and $U_2$.
\begin{lem}\label{meansqlem2}
        Let $a(n)$, $b(n)$ be arithmetical functions $\ll n^{\varepsilon}$ for all $\varepsilon>0$. Then for $0\leq j\leq 4$, $j\in\mathbb{Z}$ and $T\geq 1$, we have
        \begin{align}
            \sum_{m,n=1 \atop{m\neq n}}^{\infty}a(m)b(n)(mn)^{-\left(\frac{a}{2}+\frac{3}{4}\right)}\int_T^{2T}x^{a+1/2}e(2(\sqrt{m}\pm \sqrt{n})\sqrt{x}/k)\log^jx\ll k\hspace{0.5mm}T^{a+1+\varepsilon}.\label{meansqlemineq2}
        \end{align}
    \end{lem}
    \begin{proof}
    Using Lemma \eqref{expintegrallemma},
        \begin{align}
           \int_T^{2T}x^{a+1/2}e(2(\sqrt{m}\pm\sqrt{n})\sqrt{x}/k)\log^j x\hspace{0.5mm}dx\ll kT^{a+1}|\sqrt{n}\pm\sqrt{m}|^{-1}\log^j x.\label{meansqineq2}
        \end{align}
        Thus, the expression in \eqref{meansqlemineq2} is
        \begin{align}
          %  &\ll \sum_{m,n=1 \atop{m<n}}^{\infty}a(m)b(n)(mn)^{-\left(\frac{a}{2}+\frac{3}{4}\right)}\int_T^{2T}x^{a+1/2}e(2(\sqrt{m}\pm \sqrt{n})\sqrt{x}/k)\log^jx\\
            &\ll k\hspace{0.5mm}T^{a+1+\varepsilon}\sum_{m,n=1 \atop{m<n}}^{\infty}m^{-\left(\frac{a}{2}+\frac{3}{4}\right)}n^{-\left(\frac{a}{2}+\frac{1}{4}\right)}(n\pm m)^{-1}\ll k\hspace{0.5mm}T^{a+1+\varepsilon}\sum_{m=1}^{\infty}m^{-(a+1)}\ll k\hspace{0.5mm}T^{a+1+\varepsilon}.
        \end{align}
    \end{proof}
Using Lemma \eqref{meansqlem2}, we have $U_1\ll kT^{a+1+\varepsilon}$ and $U_2\ll kT^{a+1+\varepsilon}$, and integrating the sum $U_0$ term by term using integration by parts, \eqref{deltaameansq3} gives
\begin{align}
&\int_T^{2T}|U(x,h/k)|^2dx=\frac{1}{2\pi (a+3/2)}(k/2\pi)^{2a+1}x^{a+3/2}\sum_{n=1}^{\infty}n^{-(a+3/2)}\times\\
&\times\bigg[\frac{1}{16}d^2(n)\sum_{i=0}^{4}\left(\frac{-1}{a+3/2}\right)^{i}\frac{4!}{(4-i)!}\hspace{0.5mm}\log^{4-i}x+\frac{1}{2}d(n)f_1(n)\sum_{i=0}^{3}\left(\frac{-1}{a+3/2}\right)^{i}\frac{3!}{(3-i)!}\hspace{0.5mm}\log^{3-i}x\\
&\hspace{1cm}+\frac{1}{2}\left(d(n)f_2(n)+f_1^2(n)\right)\sum_{i=0}^{2}\left(\frac{-1}{a+3/2}\right)^{i}\frac{2!}{(2-i)!}\hspace{0.5mm}\log^{2-i}x\\
&\hspace{1cm}+2f_1(n)f_2(n)\sum_{i=0}^{1}\left(\frac{-1}{a+3/2}\right)^{i}\frac{1!}{(1-i)!}\hspace{0.5mm}\log^{1-i}x+f_2^{2}(n)\bigg]\Bigg|_{T}^{2T}+O(k^{2a+2}T^{a+1+\varepsilon}).
\end{align}
This along with \eqref{deltaameansq2} and Cauchy's inequality gives
\begin{align}
    \int_T^{2T}|\Delta_a(x,h/k)|^2dx=k^{2a+1}p(x,n)\bigg|_T^{2T}+O(k^{2a+2}T^{a+1+\varepsilon})+O(k^{2a+\frac{3}{2}}T^{a+\frac{5}{4}+\varepsilon}),\label{deltaameansq4}
\end{align}
where
\begin{align}
    p(x,n)=\frac{1}{a+3/2}(2\pi)^{-2a-2}x^{a+3/2}&\sum_{n=1}^{\infty}n^{-(a+3/2)}\bigg[\frac{1}{16}d^2(n)\sum_{i=0}^{4}\left(\frac{-1}{a+3/2}\right)^{i}\frac{4!}{(4-i)!}\hspace{0.5mm}\log^{4-i}x\\
    &\hspace{1.3cm}+\frac{1}{2}d(n)f_1(n)\sum_{i=0}^{3}\left(\frac{-1}{a+3/2}\right)^{i}\frac{3!}{(3-i)!}\hspace{0.5mm}\log^{3-i}x\\
&+\frac{1}{2}\left(d(n)f_2(n)+f_1^2(n)\right)\sum_{i=0}^{2}\left(\frac{-1}{a+3/2}\right)^{i}\frac{2!}{(2-i)!}\hspace{0.5mm}\log^{2-i}x\\
&+2f_1(n)f_2(n)\sum_{i=0}^{1}\left(\frac{-1}{a+3/2}\right)^{i}\frac{1!}{(1-i)!}\hspace{0.5mm}\log^{1-i}x+f_2^{2}(n)\bigg],
\end{align}
for $k^2< T$. Hence combining \eqref{deltaameansq1} and \eqref{deltaameansq4} and noting $k\ll X^{\frac12-\varepsilon}$,  we deduce \eqref{deltaameansqestimate}.
