\subsection{Objective Function and Nash Equilibrium}

Combining the additional cost $C$ with the impact cost~\eqref{eq:OWcost} and the value~\eqref{eq:markToMarket} of the terminal inventory, trader $i$ has the following objective function if we fix the actions $\boldsymbol{X}^{-i}=(X^{1},\dots,X^{i-1},X^{i+1},\dots,X^{N})$ of the other players.

\begin{definition}\label{de:objective}
  Given a profile $\boldsymbol{X}=(X^{1},\dots,X^{N})$ of admissible strategies, the objective of trader $i$ is to minimize
\begin{align}\label{eqn:orig.obj} J(X^{i};&\boldsymbol{X}^{-i})
=\mathbb{E}\left[\int_0^T S_{t-} dX_t^{i}+\frac{G(0)}{2}\sum_{t\in[0,T]} \Delta S_t \Delta X_t ^{i} +(X_{0-}^iP_{0-}-X_TP_T)+C(X^{i})\right].
\end{align}
%
%
%
%
%
\end{definition} 

The next proposition uses the martingale property of the unaffected price and provides a more explicit formula for the objective function.

\begin{proposition}\label{prop:obj.func.rep}
    Given a profile $\boldsymbol{X}=(X^{1},\dots,X^{N})$ of admissible strategies, the objective function $J(X^{i};\boldsymbol{X}^{-i})$ can be expressed as
    \begin{align}\label{eqn:obj.impact.rep}
    J(X^{i};\boldsymbol{X}^{-i})&=\mathbb{E}\left[\int_0^T I_{t-} dX_t^{i}+\frac{G(0)}{2}\sum_{t\in[0,T]}  \Delta I_t \Delta X_t ^{i}+C(X^{i})\right]\\
    &=\mathbb{E}\Bigg[\frac{1}{2}\int_0^T\!\!\int_0^T G(|t-s|)dX_s^{i} dX_t^{i} + \int_0^T\!\!\int_0^{t-} G(t-s) \sum_{j\not=i}dX_s^{j} dX_t^{i} \nonumber \\
    &\quad \quad \quad \quad + \frac{G(0)}{2}\sum_{j\not=i}\sum_{t\in[0,T]} \Delta X_t^{j}\Delta X_t ^{i} +C(X^{i})\Bigg].\label{eqn:obj.schied.rep}
\end{align}
In particular, $J(X^{i};\boldsymbol{X}^{-i})<\infty$ as soon as $\mathbb{E}[C(X^i)]<\infty$.
\end{proposition}

Finally, the definition of Nash equilibrium is the usual one.

\begin{definition} \label{def:nash.equilibrium}
  A profile $\boldsymbol{X}=(X^{1},\dots,X^{N})$ of admissible strategies is a \emph{Nash equilibrium} if $J(X^{i};\boldsymbol{X}^{-i})<\infty$ and
\begin{align*}%
      J(Z^i;\boldsymbol{X}^{-i})\geq J(X^{i};\boldsymbol{X}^{-i})
    \end{align*} 
for all admissible strategies $Z^i$ of trader~$i$, for all $i=1,\dots,N$. %
\end{definition}
