\begin{notation}\label{notation:projections}
  For brevity, the (dual) predictable projection onto the market filtration $\mathbb{F}^M$ will be denoted by ${\rm p}$, whereas the (dual) predictable projection onto trader $i$'s filtration $\mathbb{F}^i$ will be denoted by ${\rm p}^i$,
  \[
    {\rm p}:={\rm p}^{\mathbb{F}^M}, \qquad {\rm p}^i := {\rm p}^{\mathbb{F}^i}.
  \]
\end{notation}

The next two propositions characterize the projections of an admissible strategy of some agent to (a) the market filtration $\mathbb{F}^M$ and (b) the filtration of another agent. In either case, projecting amounts to integrating out the idiosyncratic randomization (see \cref{notation:marginal.expectations}).


\begin{proposition}\label{prop:pred.is.exp}
    Fix $i\in\{1,\dots,N\}$ and let $Z$ be a c\`adl\`ag $\mathbb{F}^i$-predictable process of bounded variation. Then, up to evanescence,
    \[{}^{\rm p}\! Z = Z^{\rm p} = \tilde{\mathbb{E}}[Z].\footnote{In fact, the bounded variation is used only for the dual predictable projection. The identity ${}^{\rm p}\!Z = \tilde{\mathbb{E}}[Z]$ holds for arbitrary bounded $\mathbb{F}^i$-predictable processes~$Z$.}\]
\end{proposition}


%
\begin{proposition}
    \label{prop:pred.proj.private.info}
    Fix $i,j\in\{1,\dots,N\}$ with $i\not=j$ and let $Z$ be a c\`adl\`ag $\mathbb{F}^j$-predictable process of bounded variation. Then, up to evanescence,
    \[{}^{{\rm p}^i}\! Z = {}^{\rm p}\! Z = \tilde{\mathbb{E}}[Z].\]
\end{proposition}




\section{Non-Existence of Randomized Equilibria}\label{se:no.randomized}

\Cref{prop:pred.is.exp} shows that the projection of a (possibly) randomized admissible strategy~$X^i$ onto the  market filtration is given by~$\tilde{\mathbb{E}}[X^i]$. We record that this de-randomized strategy is again admissible.

\begin{lemma}
    \label{lem:exp.admissible}
    %
     Let $X^i$ be an admissible strategy for player $i$. Then $\tilde{\mathbb{E}}[X^i]$ is a non-randomized admissible strategy for player $i$.
\end{lemma}


Our first proposition shows that an agent is invariant between facing (possibly) randomized strategies of the competitors or their de-randomized projections. More formally, when fixing the strategy profile $\boldsymbol{X}^{-i}$ of the competitors, the expected performance of any strategy $X^i$ against $\boldsymbol{X}^{-i}$ is the same as its performance against the projection $\tilde{\mathbb{E}}[\boldsymbol{X}^{-i}]$ of their strategies onto the market information. %

\begin{proposition}\label{prop:reduced.rep.obj}
    For any admissible strategy profile $\boldsymbol{X}$ and any $i\in\{1,\dots, N\}$, the objective function $J$ satisfies
    \begin{align*}J(X^i;\boldsymbol{X}^{-i}) %
     %
     =J(X^i;\tilde{\mathbb{E}}[\boldsymbol{X}^{-i}]).
    \end{align*}
    %
    %
    %
    %
    %
    %
    %
    %
    %
    %
\end{proposition}



