%
%
%
%
%
%
%

Finally, we prove the analogue for projecting onto the filtration of another agent.

\begin{proof}[Proof of \cref{prop:pred.proj.private.info}]
By \cref{prop:pred.is.exp}, %
$\tilde{\mathbb{E}}[Z]$ is an $\mathbb{F}^M$-predictable process. In particular, $\tilde{\mathbb{E}}[Z]$ is predictable in the filtration~$\mathbb{F}^i\supset \mathbb{F}^M$ and it suffices to check that
    \[\mathds{1}_{\{\tau < \infty\}}\tilde{\mathbb{E}}[Z_t]|_{t=\tau}=\mathbb{E}[\mathds{1}_{\{\tau < \infty\}}Z_\tau\,\vert\mathcal{F}^i_{\tau-}]\]
    for all $\mathbb{F}^i$-predictable times $\tau$. 
    %
    By construction of $\mathbb{F}^i$ and $\mathbb{F}^j$ we almost surely have 
    \[
    \tau(\omega^{\noll},\tilde{\omega})=\bar{\tau}(\omega^{\noll}, \tilde{\omega}_{i}), \qquad  \mathds{1}_{\{t < \infty\}}Z_{t}(\omega^{\noll},\tilde{\omega})=\bar{Z}(t,\omega^{\noll},\tilde{\omega}_{j})
    \]
    for some measurable functions $\bar{\tau},\bar{Z}$. Hence $\mathds{1}_{\{\tau < \infty\}}Z_\tau$ is the composition
    \[
      (\mathds{1}_{\{\tau < \infty\}}Z_\tau)(\omega^{\noll},\tilde{\omega})= \bar{Z}(\bar{\tau}(\omega^{\noll},\tilde{\omega}_{i}),\omega^{\noll}, \tilde{\omega}_{j})
    \]
    and by the product form of $\mathbb{P}$,
		\begin{align*}
      \mathbb{E}[\mathds{1}_{\{\tau < \infty\}}Z_\tau\,\vert\mathcal{F}^i_{\infty}] (\omega^{\noll},\tilde{\omega})
      &= \int \bar{Z}(\bar{\tau}(\omega^{\noll},\tilde{\omega}_{i}),\omega^{\noll},\tilde{\omega}_{j})
      \tilde{\mathbb{P}}_{j}(d\tilde{\omega}_{j}) \\
      &= \big(\mathds{1}_{\{\tau < \infty\}} \tilde{\mathbb{E}}[Z_t]|_{t=\tau}\big) (\omega^{\noll},\tilde{\omega}).
		\end{align*} 
		As we already know that the right hand side is measurable with respect to $\mathcal{F}^i_{\tau-}\subset \mathcal{F}^i_{\infty}$, the claim follows by the tower property of conditional expectation. 
%
%
%
%
%
%
%
%
%
%
%
%
\end{proof}


\subsection{Proofs for \cref{se:no.randomized} (De-Randomization)}\label{se:proofs.no.randomized}

\subsubsection{Admissibility of $\tilde{\mathbb{E}}[X]$ (\Cref{lem:exp.admissible})}


In what follows we denote by $TV(X;[a,b])$ the total variation of the path $t\mapsto X_t$ on $[a,b]$. Our first result is straightforward.

\begin{lemma}\label{lem:TV.ineq} 
$TV(\tilde{\mathbb{E}}[X];[a,b])\leq \tilde{\mathbb{E}}[TV(X;[a,b])]$ for any $0\leq a\leq b\leq \infty$
\end{lemma}

\begin{proof}
    For any partition $\Pi=\{t_0,\dots,t_n\}$ of $[a,b]$,
\begin{align*}
    \sum_{i=0}^{n-1}|\tilde{\mathbb{E}}[X_{t_{i+1}}]-\tilde{\mathbb{E}}[X_{t_i}]|&\leq \tilde{\mathbb{E}}\left[\sum_{i=0}^{n-1}|X_{t_{i+1}}-X_{t_i}|\right]\leq \tilde{\mathbb{E}}[TV(X;[a,b])].
\end{align*}
Taking the supremum over partitions $\Pi$ yields the claim.
\end{proof}

\begin{proof}[Proof of \Cref{lem:exp.admissible}]
As $\tilde{\mathbb{E}}[X^i]={}^{\rm p}X^i$ (cf.\ \cref{prop:pred.is.exp}), it is non-randomized and $\mathbb{F}^M$-predictable, hence $\mathbb{F}^i$-predictable. Using \cref{lem:TV.ineq}, it is then straightforward to verify the conditions of \cref{def:admissible.X}. %
\end{proof}
