\subsubsection{Proof of \cref{prop:reduced.rep.obj}}



\begin{proof}[Proof of \cref{prop:reduced.rep.obj}]
    We first note a trivial case of~\eqref{eq:dual.predictable.proj.properties}: 
    if the process $Z$ in  \cref{thm:dual.pred.proj} is itself $\mathbb{G}$-predictable, clearly $Z^{\rm p^\mathbb{G}}=Z$, and then~\eqref{eq:dual.predictable.proj.properties} includes the identity
    \[\mathbb{E}\left[\int_0^\infty\xi_s dZ_s\right]=\mathbb{E}\left[\int_0^\infty {}^{\rm p^{\mathbb{G}}}\xi_s dZ_s\right].\]

    Consider \eqref{eqn:obj.schied.rep} and more specifically the terms that depend on $\boldsymbol{X}^{-i}$. Denoting those by $J^{-i}(X^i;\boldsymbol{X}^{-i})$, applying \cref{thm:dual.pred.proj}, and using the $\mathbb{F}^i$-predictability of $X^i$ as just noted,
\begin{align*}
    J^{-i}(X^i;\boldsymbol{X}^{-i})
    &:=\mathbb{E}\Bigg[\int_0^T\!\!\int_0^{t-} G(t-s) \sum_{j\not=i}dX_s^{j} dX_t^{i} + \frac{G(0)}{2}\sum_{j\not=i}\sum_{t\in[0,T]} \Delta X_t^{j}\Delta X_t ^{i}\Bigg]\\
    &=\mathbb{E}\Bigg[\int_0^T\leftindex^{\;{\rm p}^i\!\!\!}{\left(\int_0^{t-}G(t-s)\sum_{j\not=i}dX_s^{j}\right)}dX_t^{i} + \frac{G(0)}{2}\sum_{j\not=i}\sum_{t\in[0,T]} \leftindex^{{\rm p}^i}(\Delta X_t^{j})\Delta X_t ^{i}\Bigg].
\end{align*}
 (To apply \cref{thm:dual.pred.proj}, note that the sum is a special case of an integral, $\sum_{t\in[0,T]} \Delta X_t^{j}\Delta X_t ^{i}= \int_0^T \Delta X_t^{j} dX_t ^{i}$.) 
Applying \cref{prop:pred.proj.private.info} we then get 
\begin{align}\mathbb{E}&\Bigg[\int_0^T\leftindex^{\;{\rm p}^i\!\!\!}{\left(\int_0^{t-} G(t-s) \sum_{j\not=i}dX_s^{j}\right)}dX_t^{i} + \frac{G(0)}{2}\sum_{j\not=i}\sum_{t\in[0,T]} \leftindex^{{\rm p}^i}(\Delta X_t^{j})\Delta X_t ^{i}\Bigg] \nonumber\\
&=\mathbb{E}\Bigg[\int_0^T\leftindex^{\;{\rm p}\!\!\!}{\left(\int_0^{t-} G(t-s)\sum_{j\not=i}dX_s^{j}\right)}dX_t^{i} + \frac{G(0)}{2}\sum_{j\not=i}\sum_{t\in[0,T]} \leftindex^{{\rm p}}(\Delta X_t^{j})\Delta X_t ^{i}\Bigg] \nonumber\\
&=\mathbb{E}\Bigg[\int_0^T\leftindex^{\;{\rm p}\!\!\!}{\left(\int_0^{t-} G(t-s) \sum_{j\not=i}dX_s^{j}\right)}dX_t^{i} + \frac{G(0)}{2}\sum_{j\not=i}\sum_{t\in[0,T]} \Delta ((X_t^{j})^{\rm p})\Delta X_t ^{i}\Bigg],\label{eqn:intermediate.eqn.pred.proj.obj}
\end{align}
where the last equality used the general fact that $\leftindex^{{\rm p}}(\Delta A)=\Delta (A^{\rm p})$ for any c\`adl\`ag adapted process $A$ with integrable variation (see \cite[3.21, p.\,33]{JacodShiryaev.03}). Denote the first integrand in~\eqref{eqn:intermediate.eqn.pred.proj.obj} by
\[I_t^{-i}:=\int_0^{t-} G(t-s) \sum_{j\not=i}dX_s^{j}. \]%
From \cref{prop:pred.is.exp} we know that ${}^{\rm p}I_t^{-i} = \tilde{\mathbb{E}}[I_t^{-i}]$ and we show below that 
\begin{align}\label{eq:proof.reduced.rep.obj}
    \tilde{\mathbb{E}}[I_t^{-i}] &=
    \int_0^{t-} G(t-s)\sum_{j\not=i} d\tilde{\mathbb{E}}[X^j_s].
\end{align}
Next, we substitute these identities into the first term of \eqref{eqn:intermediate.eqn.pred.proj.obj}.
%
Using also that $(X^j)^{\rm p} = \tilde{\mathbb{E}}[X^j]$ by \cref{prop:pred.is.exp} to rewrite the second term of of \eqref{eqn:intermediate.eqn.pred.proj.obj}, we get
%
\begin{align*}
    J^{-i}(X^i;\boldsymbol{X}^{-i})
    %
    &=\mathbb{E}\Bigg[\int_0^T\!\!\int_0^{t-} G(t-s) \sum_{j\not=i}d\tilde{\mathbb{E}}[X_s^{j}] dX_t^{i} + \frac{G(0)}{2}\sum_{j\not=i}\sum_{t\in[0,T]} \Delta \tilde{\mathbb{E}}[X^j_s]\Delta X_t ^{i}\Bigg].
\end{align*}
Comparing with \eqref{eqn:obj.schied.rep} we see that the right hand side equals $J^{-i}(X^i;\tilde{\mathbb{E}}[\boldsymbol{X}^{-i}])$, thus establishing that $J(X^i;\boldsymbol{X}^{-i})=J(X^i;\tilde{\mathbb{E}}[\boldsymbol{X}^{-i}])$.

It remains to show~\eqref{eq:proof.reduced.rep.obj}. This is clear for $t=0$ so we may focus on $t>0$. Recall that~$G$ is continuous on $[0,T]$. Suppose for a moment that $G$ is even continuously differentiable. Then integrating by parts gives
\begin{align*}
    %
    \int_0^r G(r-s)\sum_{j\not=i} dX^{j}_s
    %
    %
    = G(0) \sum_{j\not=i} X^j_r - G(r) \sum_{j\not=i} X^j_{0-} +\int_0^r G'(r-s) \sum_{j\not=i} X^j_s  ds.
    %
\end{align*}
Taking expectations, applying Fubini's theorem, and reversing the integration by parts yields
\begin{align}
    \tilde{\mathbb{E}}\left[\int_0^r G(r-s)\sum_{j\not=i} dX^{j}_s\right] &=G(0) \sum_{j\not=i} \tilde{\mathbb{E}}[X^j_r] - G(r) \sum_{j\not=i} \tilde{\mathbb{E}}[X^j_{0-}] +\int_0^r G'(r-s) \sum_{j\not=i}\tilde{\mathbb{E}}[X^j_s]  ds \nonumber\\
    &=\int_0^r G(r-s)\sum_{j\not=i} d\tilde{\mathbb{E}}[X^j_s]. \label{eq:for.proof.reduced.rep.obj}
\end{align}
In fact, these steps hold for any continuously differentiable function~$G$. The general continuous kernel $G$ can be approximated uniformly on~$[0,T]$ with continuously differentiable functions, hence it follows that~\eqref{eq:for.proof.reduced.rep.obj} also holds for the general kernel~$G$. The claim~\eqref{eq:proof.reduced.rep.obj} now follows by taking the limit $r\uparrow t$ and using that~$G$ is continuous and bounded.
