\subsubsection{Proof of \cref{le:C.no.randomized.holds.for.quadratic}}

Next, we show that the quadratic costs of \cref{ex:costsC} satisfy the Jensen-type inequality of \cref{as:C.no.randomized}.

\begin{proof}[Proof of \cref{le:C.no.randomized.holds.for.quadratic}]
    If $\mathbb{E}\left[C(X)\right]=\infty$, the conclusion is immediate. 
    We therefore fix an admissible strategy $X$ for some trader $i$ with $\mathbb{E}\left[C(X)\right]<\infty$.
    %
    Observe that by Fubini's theorem, %
    \begin{equation}\mathbb{E}\left[C(X)\right]
    %
    = \int_{\Omega^{\noll}}\tilde{\mathbb{E}}[C(X)]d\mathbb{P}^{\noll}=\int_{\Omega^{\noll}}\int_{\tilde{\Omega}}\tilde{\mathbb{E}}[C(X)]d\tilde{\mathbb{P}}d\mathbb{P}^{\noll}=\mathbb{E}\left[\tilde{\mathbb{E}}[C(X)]\right].\label{eqn:C.init.equality}
    \end{equation}
    Invoking Fubini's theorem once again with a pointwise application of Jensen's inequality on the quadratic function $z\mapsto z^2$ for $z\in\mathbb{R}$,
\begin{align}\mathbb{E}\left[\tilde{\mathbb{E}}[C(X)]\right]&=
		\mathbb{E}\left[\tilde{\mathbb{E}}\left[\frac{\varepsilon}{2}\int_0^T (\dot{X}_t)^2dt
		%
		+\frac{1}{2}\sum_{t\in[0,T]} \vartheta_t(\Delta X_t)^2
		+\frac{\varphi}{2} (X_T)^2\right]\right]\nonumber\\
        &\geq \mathbb{E}\left[\frac{\varepsilon}{2}\int_0^T \left(\tilde{\mathbb{E}}\left[\dot{X}_t\right]\right)^2dt
		%
		+\tilde{\mathbb{E}}\left[\frac{1}{2}\sum_{t\in[0,T]} \vartheta_t\left(\Delta X_t\right)^2\right]
		+\frac{\varphi}{2} \left(\tilde{\mathbb{E}}\left[X_T\right]\right)^2\right].%
  %
		%
		%
		%
        \label{eqn:C.pt.1}
\end{align}
With a view towards the first term, we next argue that if $\varepsilon>0$, then $\frac{d}{dt}\tilde{\mathbb{E}}\left[X_t\right]=\tilde{\mathbb{E}}[\dot{X}_t]$ $dt\otimes d\mathbb{P}$ almost surely. 
Indeed, if $\varepsilon>0$, then by the definition in \cref{ex:costsC} and $\mathbb{E}\left[C(X)\right]<\infty$ we know that $X$ is absolutely continuous. 
Thus, given the initial value $\tilde{\mathbb{E}}[X_{0}]=X_{0} = x^i\in\mathbb{R}$,
\[\tilde{\mathbb{E}}[X_t] = x^i+ \tilde{\mathbb{E}}\left[\int_0^t \dot{X}_sds\right]. \]
Since $X$ is admissible, it has $\mathbb{P}$-essentially bounded variation and in particular
%
$\int_0^t |\dot{X}_s|ds$ is uniformly bounded. Thus, we may apply Fubini's theorem to obtain
%
$\tilde{\mathbb{E}}[X_t] = x^i+\int_0^t \tilde{\mathbb{E}} [\dot{X}_s]ds$. In other words, $\tilde{\mathbb{E}}[X_t]$ is absolutely continuous with derivative $\frac{d}{dt}\tilde{\mathbb{E}}\left[X_t\right]=\tilde{\mathbb{E}}\left[\dot{X}_t\right]$ $dt\otimes d\mathbb{P}$ almost surely, and we have
\begin{equation}\label{eqn:C.pt.1.firstTerm}
    \mathbb{E}\left[\tilde{\mathbb{E}}\left[\frac{\varepsilon}{2}\int_0^T (\dot{X}_t)^2dt \right]\right]
    \geq\mathbb{E}\left[\frac{\varepsilon}{2}\int_0^T \left(\frac{d}{dt}\tilde{\mathbb{E}}\left[X_t\right]\right)^2dt \right].
\end{equation}


It remains to treat the second term in~\eqref{eqn:C.pt.1}. By \cref{thm:dual.pred.proj} and the identity $X^{\rm p}=\tilde{\mathbb{E}}[X]$ from \cref{prop:pred.is.exp},
\begin{align*}0&\leq \mathbb{E}\left[
		\frac{1}{2}\sum_{t\in[0,T]} \vartheta_t\left(\Delta X_t^{i}-\Delta \tilde{\mathbb{E}}[X_t^{i}]\right)^2\right]\\
        &=\mathbb{E}\left[\frac{1}{2}\sum_{t\in[0,T]} \vartheta_t\left((\Delta X_t)^2-2\Delta X_t\Delta \tilde{\mathbb{E}}[X_t]+(\Delta \tilde{\mathbb{E}}[X_t])^2\right)\right]\\
         %
        &=\mathbb{E}\left[\frac{1}{2}\sum_{t\in[0,T]} \vartheta_t(\Delta X_t)^2-\frac{1}{2}\sum_{t\in[0,T]} \vartheta_t(\Delta \tilde{\mathbb{E}}[X_t])^2\right] \\
        &\quad +\mathbb{E}\left[\sum_{t\in[0,T]} \vartheta_t(\Delta \tilde{\mathbb{E}}[X_t])^2-\sum_{t\in[0,T]} \vartheta_t\Delta X_t\Delta \tilde{\mathbb{E}}[X_t]\right]\\
        &=\mathbb{E}\left[\frac{1}{2}\sum_{t\in[0,T]} \vartheta_t(\Delta X_t)^2-\frac{1}{2}\sum_{t\in[0,T]} \vartheta_t(\Delta \tilde{\mathbb{E}}[X_t])^2\right] \\
        & \quad +\mathbb{E}\left[\sum_{t\in[0,T]} \vartheta_t(\Delta \tilde{\mathbb{E}}[X_t])^2-\sum_{t\in[0,T]} \vartheta_t\Delta X_t^{\rm p}\Delta \tilde{\mathbb{E}}[X_t]\right]\\
        &=\mathbb{E}\left[\frac{1}{2}\sum_{t\in[0,T]} \vartheta_t(\Delta X_t)^2-\frac{1}{2}\sum_{t\in[0,T]} \vartheta_t(\Delta \tilde{\mathbb{E}}[X_t])^2\right].
\end{align*}
By rearranging we conclude that
\begin{equation}\label{eqn:C.pt.2}\mathbb{E}\left[\tilde{\mathbb{E}}\left[\frac{1}{2}\sum_{t\in[0,T]} \vartheta_t(\Delta X_t)^2\right]\right]=\mathbb{E}\left[\frac{1}{2}\sum_{t\in[0,T]} \vartheta_t(\Delta X_t)^2\right] \geq \mathbb{E}\left[\frac{1}{2}\sum_{t\in[0,T]} \vartheta_t(\Delta \tilde{\mathbb{E}}[X_t])^2\right].
\end{equation}
Combining \cref{eqn:C.init.equality,eqn:C.pt.1.firstTerm,eqn:C.pt.1,eqn:C.pt.2} completes the proof.
\end{proof}

\subsubsection{Proof of \cref{thm:non.existence.random.eq}}

We first prove the following technical lemma.

\begin{lemma}\label{lem:jensen.ineq.precursor}
    For any %
    kernel $G$ satisfying \cref{as:kernel} and any admissible strategy~$X$,
    \begin{align*}
    \mathbb{E}&\left[\frac{1}{2}\int_0^\infty\!\!\int_0^\infty G(|t-s|) d(X_s-\tilde{\mathbb{E}}[X_s]) d(X_t-\tilde{\mathbb{E}}[X_t]) \right]\\
    &\quad \quad \quad \quad \quad =\mathbb{E}\left[\frac{1}{2}\int_0^\infty\!\!\int_0^\infty G(|t-s|) dX_sdX_t -\frac{1}{2}\int_0^\infty\!\!\int_0^\infty G( |t-s|)d\tilde{\mathbb{E}}[X_s] d\tilde{\mathbb{E}}[X_t]\right].
\end{align*}
\end{lemma}

\begin{proof}
    Since $X$ and $\tilde{\mathbb{E}}[X]$ are constant after $T$ it suffices to check the equality for upper limit of integration $T$. We have

    \begin{align}
    \mathbb{E}\bigg[\frac{1}{2}\int_0^T\!\!\int_0^T& G(|t-s|) d(X_s^{i}-\tilde{\mathbb{E}}[X_s^i]) d(X_t^{i}-\tilde{\mathbb{E}}[X_t^i]) \bigg]\nonumber\\
    &=\mathbb{E}\bigg[\frac{1}{2}\int_0^T\!\!\int_0^T G(|t-s|) dX_s^{i}dX_t^{i} +\frac{1}{2}\int_0^T\!\!\int_0^T G(|t-s|)d\tilde{\mathbb{E}}[X_s^i] d\tilde{\mathbb{E}}[X_t^i] \nonumber\\
    &\quad \quad \quad -\int_0^T\!\!\int_0^T G(|t-s|)d\tilde{\mathbb{E}}[X_s^i]dX_t^i \bigg]\nonumber\\
    &=\mathbb{E}\bigg[\frac{1}{2}\int_0^T\!\!\int_0^T G(|t-s|) dX_s^{i}dX_t^{i} -\frac{1}{2}\int_0^T\!\!\int_0^T G(|t-s|)d\tilde{\mathbb{E}}[X_s^i] d\tilde{\mathbb{E}}[X_t^i] \nonumber\\
    &\quad \quad \quad +\int_0^T\!\!\int_0^T G(|t-s|)d\tilde{\mathbb{E}}[X_s^i] d\tilde{\mathbb{E}}[X_t^i] -\int_0^T\!\!\int_0^T G(|t-s|)d\tilde{\mathbb{E}}[X_s^i]dX_t^i \bigg].\label{eqn:intermediate.calc.non.exist.1}
\end{align}
Next, note that for arbitrary Lebesgue--Stieltjes integrators $M,N$ we have
\begin{align*}
    \int_0^T\!\!\int_0^{t-} &G(t-s) dM_sdN_t \\
    & = \frac{1}{2}\int_0^T\!\!\int_0^{t-} G(t-s)dM_sdN_t+ \frac{1}{2}\int_0^T\!\!\int_0^{t-} G(t-s) dM_sdN_t\\
    &=\frac{1}{2}\int_0^T\!\!\int_0^{t-} G(t-s) dM_sdN_t+ \frac{1}{2}\int_0^T\!\!\int_s^{T} G(t-s) dN_tdM_s-\frac{G(0)}{2}\sum_{t\in[0,T]}\Delta M _t\Delta N_t\\
    &=\frac{1}{2}\int_0^T\!\!\int_0^{t-} G(t-s) dM_sdN_t+ \frac{1}{2}\int_0^T\!\!\int_t^T G(s-t) dM_sdN_t -\frac{G(0)}{2}\sum_{t\in[0,T]}\Delta M _t\Delta N_t \\
    &\quad \quad +\frac{1}{2}\int_0^T\!\!\int_t^{T} G(s-t) dN_sdM_t - \frac{1}{2}\int_0^T\!\!\int_t^T G(s-t)dM_sdN_t \\
    %
    %
    %
    %
    &=\frac{1}{2}\int_0^T\!\!\int_0^{T} G(|t-s|) dM_sdN_t-\frac{G(0)}{2}\sum_{t\in[0,T]}\Delta M _t\Delta N_t\\
    &\quad \quad +\frac{1}{2}\int_0^T\!\!\int_0^{t-} G(t-s) dM_sdN_t - \frac{1}{2}\int_0^T\!\!\int_0^{t-} G(t-s) dN_sdM_t.
\end{align*}
Rearranging, this leads to the identity
\begin{align} 
\frac{1}{2}\int_0^T\!\!\int_0^{T} G(|t-s|) dM_sdN_t&= \int_0^T\!\!\int_0^{t-} G(t-s) dM_sdN_t+\frac{G(0)}{2}\sum_{t\in[0,T]}\Delta M _t\Delta N_t \label{eqn:int.identity}\\
&\quad +\frac{1}{2}\int_0^T\!\!\int_0^{t-} G(t-s) dN_sdM_t -\frac{1}{2}\int_0^T\!\!\int_0^{t-} G(t-s)dM_sdN_t.\nonumber
\end{align}
In particular, if $M\equiv N$,
\begin{align} 
\frac{1}{2}\int_0^T\!\!\int_0^{T} G(|t-s|) dM_sdM_t= \int_0^T\!\!\int_0^{t-} G(t-s) dM_sdM_t+\frac{G(0)}{2}\sum_{t\in[0,T]}\Delta M _t\Delta M_t.\label{eqn:int.identity.2}
\end{align}
Using \eqref{eqn:int.identity} with $M_s=\tilde{\mathbb{E}}[X_s^i]$ and $N_t=X_t^i$ and then applying \cref{thm:dual.pred.proj} yields
\begin{align*}
    \mathbb{E}\Bigg[\int_0^T\!\!\int_0^T &G(|t-s|) d\tilde{\mathbb{E}}[X_s^i]dX_t^i\Bigg]\\
    &=\mathbb{E}\Bigg[2\int_0^T\!\!\int_0^{t-} G(t-s) d\tilde{\mathbb{E}}[X_s^i]dX_t^i+G(0)\sum_{t\in[0,T]}\Delta \tilde{\mathbb{E}}[X_t^i]\Delta X_t^i\\
    &\quad \quad + \int_0^T\!\!\int_0^{t-} G(t-s) dX_s^id\tilde{\mathbb{E}}[X_t^i] -\int_0^T\!\!\int_0^{t-} G(t-s) d\tilde{\mathbb{E}}[X_s^i]dX_t^i\Bigg]\\
    &=\mathbb{E}\Bigg[2\int_0^T\!\!\int_0^{t-} G(t-s) d\tilde{\mathbb{E}}[X_s^i]d(X_t^i)^{\rm p}+G(0)\sum_{t\in[0,T]}\Delta \tilde{\mathbb{E}}[X_t^i]\Delta (X_t^i)^{\rm p}\\
    &\quad \quad + \int_0^T\leftindex^{\;\rm p\!\!\!}{\left(\int_0^{t-} G(t-s) dX_s^i\right)}d\tilde{\mathbb{E}}[X_t^i] -\int_0^T\!\!\int_0^{t-} G(t-s) d\tilde{\mathbb{E}}[X_s^i]d(X_t^i)^{\rm p}\Bigg]\\
    &=\mathbb{E}\Bigg[2\int_0^T\!\!\int_0^{t-} G(t-s) d\tilde{\mathbb{E}}[X_s^i]d\tilde{\mathbb{E}}[X_t^i]+G(0)\sum_{t\in[0,T]}\left(\Delta \tilde{\mathbb{E}}[X_t^i]\right)^2\\
    &\quad \quad + \int_0^T\leftindex^{\;\rm p\!\!\!}{\left(\int_0^{t-} G(t-s) dX_s^i\right)}d\tilde{\mathbb{E}}[X_t^i] -\int_0^T\!\!\int_0^{t-} G(t-s) d\tilde{\mathbb{E}}[X_s^i]d\tilde{\mathbb{E}}[X_t^i]\Bigg].
\end{align*}
As seen in the proof of \cref{prop:reduced.rep.obj},
\[\leftindex^{\;\rm p\!\!\!}{\left(\int_0^{t-} G(t-s) dX_s^i\right)} = \int_0^{t-} G(t-s) d\tilde{\mathbb{E}}[X_s^i].\]
Substituting this, simplifying, and applying \eqref{eqn:int.identity.2} with $M_s=\tilde{\mathbb{E}}[X_s^i]$,
\begin{align}
    \mathbb{E}\Bigg[\int_0^T\!\!\int_0^T &G(|t-s|)d\tilde{\mathbb{E}}[X_s^i]dX_t^i\Bigg]\nonumber\\&=\mathbb{E}\Bigg[2\int_0^T\!\!\int_0^{t-} G(t-s) d\tilde{\mathbb{E}}[X_s^i]d\tilde{\mathbb{E}}[X_t^i]+G(0)\sum_{t\in[0,T]}\left(\Delta \tilde{\mathbb{E}}[X_t^i]\right)^2\nonumber\\
    &\quad \quad + \int_0^T\!\!\int_0^{t-} G(t-s) d\tilde{\mathbb{E}}[X^i_s]d\tilde{\mathbb{E}}[X_t^i] -\int_0^T\!\!\int_0^{t-} G(t-s)d\tilde{\mathbb{E}}[X_s^i]d\tilde{\mathbb{E}}[X_t^i]\Bigg]\nonumber\\
    &=\mathbb{E}\Bigg[2\int_0^T\!\!\int_0^{t-} G(t-s) d\tilde{\mathbb{E}}[X_s^i]d\tilde{\mathbb{E}}[X_t^i]+G(0)\sum_{t\in[0,T]}\left(\Delta \tilde{\mathbb{E}}[X_t^i]\right)^2\Bigg]\nonumber\\
    &=\mathbb{E}\left[\int_0^T\!\!\int_0^T G(|t-s|)d\tilde{\mathbb{E}}[X_s^i]d\tilde{\mathbb{E}}[X_t^i]\right].\label{eqn:intermediate.calc.non.exist.2}
\end{align}
Substituting \eqref{eqn:intermediate.calc.non.exist.2} into \eqref{eqn:intermediate.calc.non.exist.1} and simplifying completes the proof.
%
%
%
%
%
\end{proof}

Next, we prove the main result.

\begin{proof}[Proof of \cref{thm:non.existence.random.eq}]
%
%
%
%
%
%
%
Using \cref{prop:reduced.rep.obj} and~\eqref{eqn:obj.schied.rep} and the definition of the dual predictable projection in \cref{thm:dual.pred.proj},
\begin{align}
J(X^i;\boldsymbol{X}^{-i}) 
&=J(X^i;\tilde{\mathbb{E}}[\boldsymbol{X}^{-i}]) \nonumber \\
&=\mathbb{E}\Bigg[\frac{1}{2}\int_0^T\!\!\int_0^T G(|t-s|) dX_s^{i} dX_t^i + \int_0^T\!\!\int_0^{t-} G(t-s) \sum_{j\not=i}d\tilde{\mathbb{E}}[X_s^{j}] d(X_t^{i})^{\rm p} \nonumber \\
        &\quad \quad \quad \quad + \frac{G(0)}{2}\sum_{j\not=i}\sum_{t\in[0,T]} \Delta \tilde{\mathbb{E}}[X_t^{j}]\Delta(X_t^{i})^{\rm p} +C(X^{i})\Bigg]\nonumber\\
        &=\mathbb{E}\Bigg[\frac{1}{2}\int_0^T\!\!\int_0^T G(|t-s|) dX_s^{i} dX^i_t + \int_0^T\!\!\int_0^{t-} G(t-s)\sum_{j\not=i}d\tilde{\mathbb{E}}[X_s^{j}] d\tilde{\mathbb{E}}[X^i_t] \nonumber \\
        &\quad \quad \quad \quad + \frac{G(0)}{2}\sum_{j\not=i}\sum_{t\in[0,T]} \Delta \tilde{\mathbb{E}}[X_t^{j}]\Delta \tilde{\mathbb{E}}[X^i_t] +C(X^{i})\Bigg],\label{eqn:obj.rep.non.exist.pf}
    \end{align}
where the last equality used, similarly as in the proof of \cref{prop:reduced.rep.obj}, that $\leftindex^{{\rm p}}X^i=(X^i)^{\rm p} = \tilde{\mathbb{E}}[X^i]$ by \cref{prop:pred.is.exp} and the rule $\leftindex^{{\rm p}}(\Delta A)=\Delta (A^{\rm p})$. 

By our assumption, $X^i$ cannot be equal to $\tilde{\mathbb{E}}[X^i]$ up to evanescence. As $x^i=X^i_{0-} = \tilde{\mathbb{E}}[X^i_{0-}]$, this implies that the random measure $d(X_\cdot^{i}-\tilde{\mathbb{E}}[X_\cdot^i])$ is non-zero with positive probability. Recalling that~$G$ is strict positive definite and invoking \cref{lem:jensen.ineq.precursor}, it follows that

\begin{align*}
    0<\mathbb{E}&\left[\frac{1}{2}\int_0^T\!\!\int_0^T G(|t-s|) d(X_s-\tilde{\mathbb{E}}[X_s]) d(X_t-\tilde{\mathbb{E}}[X_t]) \right]\\
    &\quad \quad \quad \quad \quad =\mathbb{E}\left[\frac{1}{2}\int_0^T\!\!\int_0^T G(|t-s|) dX_sdX_t -\frac{1}{2}\int_0^T\!\!\int_0^T G( |t-s|)d\tilde{\mathbb{E}}[X_s] d\tilde{\mathbb{E}}[X_t]\right]
\end{align*}
