%
which after rearranging states that
\[\mathbb{E}\left[\int_0^T\!\!\int_0^T G(|t-s|) dX_s^{i}dX_t^{i}\right]>\mathbb{E}\left[\int_0^T\!\!\int_0^T G(|t-s|)d\tilde{\mathbb{E}}[X_s^i] d\tilde{\mathbb{E}}[X_t^i]\right].\]
Combining this with \eqref{eqn:obj.rep.non.exist.pf}, we obtain
\begin{align*}J(X^i;\boldsymbol{X}^{-i}) &>\mathbb{E}\Bigg[\frac{1}{2}\int_0^T\!\!\int_0^T G( |t-s|) d\tilde{\mathbb{E}}[X_s^i] d\tilde{\mathbb{E}}[X^i_t] + \int_0^T\!\!\int_0^{t-} G(t-s) \sum_{j\not=i}d\tilde{\mathbb{E}}[X_s^{j}] d\tilde{\mathbb{E}}[X^i_t] \nonumber \\
        &\quad \quad \quad \quad + \frac{G(0)}{2}\sum_{j\not=i}\sum_{t\in[0,T]} \Delta \tilde{\mathbb{E}}[X_t^{j}]\Delta \tilde{\mathbb{E}}[X^i_t] + C(X^{i})\Bigg ].
