\subsection{Proofs for \cref{se:uniqueness} (Uniqueness)}\label{se:proofs.uniqueness}
%

The first step towards uniqueness of Nash equilibria is to ensure that the traders' objectives are convex in their controls. (In fact, the proof of our main result below only uses the assertion of convexity, not the strict convexity provided in the lemma.)

\begin{lemma}\label{lem:strict.convex}
    For any admissible $\boldsymbol{X}^{-i}$,  the objective $J(\,\cdot\,; \boldsymbol{X}^{-i})$ is strictly\footnote{An extended real-valued convex function $F$ is called strictly convex if it is strictly convex on its domain
$\mathrm{dom}(F)=\{h:F(h)<\infty\}$.} convex in its first argument.
\end{lemma}

The proof is analogous to the proof in \cite[Lemma 4.7]{SchiedStrehleZhang.17} for the exponential kernel and a quadratic cost $C$. We include it for completeness and to clarify that it relies only on the convexity of the cost~$C$ and the strict positive definiteness of the kernel~$G$. 


\begin{proof}
    Let $Y^0$ and $Y^1$ be distinct admissible strategies for trader $i$ with $\mathbb{E}[C(Y^0)]<\infty$ and $\mathbb{E}[C(Y^1)]<\infty$. Fix any admissible strategy profile $\boldsymbol{X}^{-i}$ of the other traders. For any $\alpha\in(0,1)$ define
    \[Y^\alpha:=\alpha Y^1+(1-\alpha) Y^0\]
    so that by the convexity of $C$,
    \begin{align*}
    J(Y^\alpha;\boldsymbol{X}^{-i})&\leq \mathbb{E}\Bigg[\frac{1}{2}\int_0^T\!\!\int_0^T G(|t-s|)dY^\alpha_s dY^\alpha_t + \int_0^T\!\!\int_0^{t-} G(t-s) \sum_{j\not=i}dX_s^{j} dY^\alpha_t \nonumber \\
    &\quad \quad \quad \quad + \frac{G(0)}{2}\sum_{j\not=i}\sum_{t\in[0,T]} \Delta X_t^{j}\Delta Y^\alpha_t +\alpha C(Y^1) + (1-\alpha) C(Y^0)\Bigg].
    \end{align*}
    Observe that the middle two terms are linear in $\alpha$, so to show strict convexity of $J(\cdot;\boldsymbol{X}^{-i})$ it suffices to show
    \begin{align}H(Y^\alpha):=\mathbb{E}\left[\int_0^T\!\!\int_0^T G(|t-s|)dY^\alpha_s dY^\alpha_t\right]&<\alpha\mathbb{E}\left[\int_0^T\!\!\int_0^T G(|t-s|)dY^1_s dY^1_t\right]\label{eqn:suff.cond.convexity}\\
    &\quad \quad +(1-\alpha)\mathbb{E}\left[\int_0^T\!\!\int_0^T G(|t-s|)dY^0_s dY^0_t\right].\nonumber
    \end{align}
    Expanding the left hand side of \eqref{eqn:suff.cond.convexity},
    \begin{align}
        H(Y^\alpha)&=\alpha^2\mathbb{E}\left[\int_0^T\!\!\int_0^T G(|t-s|)dY^1_t dY^1_t\right]+(1-\alpha)^2\mathbb{E}\left[\int_0^T\!\!\int_0^T G(|t-s|)dY^0_s dY^0_t\right]\nonumber\\
        &\quad \quad +2\alpha(1-\alpha) \mathbb{E}\left[\int_0^T\!\!\int_0^T G(|t-s|)dY^1_s dY^0_t\right].\label{eqn:pf.convexity.1}
    \end{align}
    At the same time, by the strict positive definiteness of $G$,
    \begin{align}
    0&<\alpha(1-\alpha)\mathbb{E}\left[\int_0^T\!\!\int_0^T G(|t-s|)d(Y^1_s-Y^0_s) d(Y^1_t-Y^0_t)\right]\nonumber\\
    &=\alpha(1-\alpha)\mathbb{E}\left[\int_0^T\!\!\int_0^T G(|t-s|)dY^1_s dY^1_t\right]+\alpha(1-\alpha)\mathbb{E}\left[\int_0^T\!\!\int_0^T G(|t-s|)dY^0_s dY^0_t\right]\nonumber\\
    &\quad \quad -2\alpha(1-\alpha)\mathbb{E}\left[\int_0^T\!\!\int_0^T G(|t-s|)dY^1_s dY^0_t\right]. \label{eqn:pf.convexity.2}
    \end{align}
    Combining \eqref{eqn:pf.convexity.1} and \eqref{eqn:pf.convexity.2} we obtain
    \begin{align*}
        H(Y^\alpha) &< (\alpha^2+\alpha(1-\alpha))\mathbb{E}\left[\int_0^T\!\!\int_0^T G(|t-s|)dY^1_t dY^1_t\right]\\
        &\quad \quad +((1-\alpha)^2+\alpha(1-\alpha))\mathbb{E}\left[\int_0^T\!\!\int_0^T G(|t-s|)dY^0_s dY^0_t\right].
    \end{align*}
    Simplifying the coefficients recovers \eqref{eqn:suff.cond.convexity} and completes the proof.
\end{proof}

\begin{proof}[Proof of \cref{thm:nash.eq.unique}]
Let $\boldsymbol{X}^0$ and $\boldsymbol{X}^1$ be distinct equilibria. Define
    \[\boldsymbol{X}^\alpha = \alpha \boldsymbol{X}^1 +(1-\alpha)\boldsymbol{X}^0, \ \ \ \alpha\in(0,1), \]
and
\begin{equation*}V(\alpha) = \sum_{i=1}^N\left(J(X^{\alpha,i};\boldsymbol{X}^{0,-i})+J(X^{1-\alpha,i};\boldsymbol{X}^{1,-i})\right).\end{equation*}
It follows from \cref{lem:strict.convex} is that $V$ is strictly convex. Moreover, the Nash equilibrium property implies that
\begin{equation}\label{eqn:min.V}V(\alpha)\geq \sum_{i=1}^N \left(J(X^{0,i};\boldsymbol{X}^{0,-i})+J(X^{1,i};\boldsymbol{X}^{1,-i}) \right)=V(0).
\end{equation}

Next, we will show that the right derivative at zero satisfies $\dot{V}(0+)<0$. This will be  a contradiction to \eqref{eqn:min.V} as it implies that $0$ is not in the subdifferential of $V$ at $\alpha=0$ which, in turn, implies that $V(0)$ is not a minimum.

We treat separately the four terms in the expression~\eqref{eqn:obj.schied.rep} for $J$ and their corresponding terms in~$V$. Let 
\begin{align*}F_1^i(\alpha) &= \mathbb{E}\left[\frac{1}{2}\int_0^T\!\!\int_0^T G(|t-s|) dX_s^{\alpha,i} dX_t^{\alpha, i}+\frac{1}{2}\int_0^T\!\!\int_0^T G(|t-s|) dX_s^{1-\alpha,i} dX_t^{1-\alpha, i}\right].
\end{align*}
Substituting the explicit form of $\boldsymbol{X}^\alpha,\boldsymbol{X}^{1-\alpha}$ and using the linearity of integration with respect to scalar multiplication, we see that $F_1^i(\alpha)$ is quadratic in~$\alpha$. Differentiating at $\alpha=0$,
\begin{align*}
    \dot{F}^i_1(0) &=-\mathbb{E}\left[\int_0^T\!\!\int_0^T G(|t-s|) d(X_s^{1,i} -X_s^{0, i})d(X_t^{1,i} -X_t^{0, i})\right]
\end{align*}
and thus
\begin{equation} \label{eqn:J1.sum} \sum_{i=1}^N\dot{F}^i_1(0)=-\mathbb{E}\left[\sum_{i=1}^N\int_0^T\!\!\int_0^T G( |t-s|) d(X_s^{1,i} -X_s^{0, i})d(X_t^{1,i} -X_t^{0, i})\right].
\end{equation}
Similarly, let
\begin{align*}
    F_2^i(\alpha) &=  \mathbb{E}\left[\int_0^T\!\!\int_0^{t-} G(t-s)\sum_{j\not=i}dX_s^{0,j} dX_t^{\alpha, i}+ \int_0^T\!\!\int_0^{t-} G(t-s) \sum_{j\not=i}dX_s^{1,j} dX_t^{1-\alpha, i}\right],
\end{align*}
which is a linear function of $\alpha$. Differentiating gives
\begin{align*}\dot{F}_2^i(\alpha) &= \mathbb{E}\Bigg[\int_0^T\!\!\int_0^{t-} G(t-s) \sum_{j\not=i}dX_s^{0,j} d(X^{1,i}-X^{0,i})\\
&\quad\quad\quad - \int_0^T\!\!\int_0^{t-} G(t-s)\sum_{j\not=i}dX_s^{1,j} d(X^{1,i}- X^{0,i})\Bigg]\\
&=- \mathbb{E}\left[\int_0^T\!\!\int_0^{t-} G(t-s) \sum_{j\not=i}d(X_s^{1,j} - X_s^{0,j})d(X^{1,i}_t- X^{0,i}_t)\right],
\end{align*}
which is constant in $\alpha$. Summing over~$i$ yields

\begin{align*}\sum_{i=1}^N\dot{F}_2^i(0)&= - \mathbb{E}\left[\sum_{i=1}^N\sum_{j\not=i}\int_0^T\!\!\int_0^{t-} G(t-s) d(X_s^{1,j} - X_s^{0,j}) d(X^{1,i}_t- X^{0,i}_t)\right]\\
&= \mathbb{E}\Bigg[-\frac{1}{2} \sum_{i=1}^N\sum_{j\not=i}\int_0^T\!\!\int_0^{t-} G(t-s) d(X_s^{1,j} - X_s^{0,j}) d(X^{1,i}_t- X^{0,i}_t)\\
& \quad\quad\quad -\frac{1}{2} \sum_{i=1}^N\sum_{j\not=i}\int_0^T\int_{s+}^T G(t-s)  d(X^{1,i}_t- X^{0,i}_t) d(X_s^{1,j} - X_s^{0,j})\Bigg]\\
&= \mathbb{E}\Bigg[-\frac{1}{2} \sum_{i=1}^N\sum_{j\not=i}\int_0^T\!\!\int_0^T G(|t-s|) d(X_s^{1,j} - X_s^{0,j}) d(X^{1,i}_t- X^{0,i}_t)\\
&\quad\quad\quad +\frac{G(0)}{2}\sum_{i=1}^N\sum_{j\not=i}\sum_{t\in[0,T]}\Delta(X_t^{1,j} - X_t^{0,j})\Delta(X_t^{1,i} - X_t^{0,i})\Bigg].
\end{align*}
As $G$ is positive definite (in fact, here we only use semi-definiteness),
\[-\sum_{i}\sum_{j\not=i}\int_0^T\!\!\int_0^TG(|t-s|)dM_s^jdM_t^i\leq \sum_{i}\int_0^T\!\!\int_0^TG(|t-s|)dM_s^idM_t^i\] for arbitrary Lebesgue--Stieltjes integrators $M^i$. Applying this,
\begin{align}\label{eqn:J2.sum.bd}
\sum_{i=1}^N\dot{F}_2^i(0)&\leq  \mathbb{E}\Bigg[\frac{1}{2} \sum_{i=1}^N\int_0^T\!\!\int_0^T G(|t-s|) d(X_s^{1,i} - X_s^{0,i}) d(X^{1,i}_t- X^{0,i}_t)\\
&\quad\quad\quad +\frac{G(0)}{2}\sum_{i=1}^N\sum_{j\not=i}\sum_{t\in[0,T]}\Delta(X_t^{1,j} - X_t^{0,j})\Delta(X_t^{1,i} - X_t^{0,i})\Bigg].\nonumber
\end{align}
Turning to the jump terms, let
\begin{align*}F_3^i(\alpha)&=\mathbb{E}\left[\frac{G(0)}{2}\sum_{j\not=i}\sum_{t\in[0,T]} \Delta X_t ^{\alpha, i} \Delta X_t^{0,j}+\frac{G(0)}{2}\sum_{j\not=i}\sum_{t\in[0,T]} \Delta X_t ^{1-\alpha, i} \Delta X_t^{1,j}\right].
\end{align*}
This is once again linear in $\alpha$ and differentiating gives
\begin{align*}\dot{F}_3^i(\alpha)&=\mathbb{E}\left[-\frac{G(0)}{2}\sum_{j\not=i}\sum_{t\in[0,T]} \Delta ( X_t^{0,i}-X_t ^{1, i})\Delta X_t^{0,j}+\frac{G(0)}{2}\sum_{j\not=i}\sum_{t\in[0,T]} \Delta (X_t^{0,i}-X_t ^{1, i}) \Delta X_t^{1,j}\right].
\end{align*}
Collecting terms and summing over $i$,
\begin{equation}\label{eqn:J3.sum.bd}\sum_{i=1}^N\dot{F}_3^i(0)=-\mathbb{E}\left[\frac{G(0)}{2}\sum_{i=1}^N\sum_{j\not=i}\sum_{t\in[0,T]} \Delta (X_t^{1,i}-X_t^{0, i})\Delta  (X_t^{1,j}-X_t^{0,j})\right].
%
%
\end{equation}


Lastly, we treat the terms arising from the cost $C$. %
Let
\begin{align*}F_4^i(\alpha) &=\mathbb{E}\left[C(X^{\alpha,i})+C(X^{1-\alpha,i})\right].
%
\end{align*}
%
%
%
%
%
By construction, $[0,1]\ni\alpha \mapsto F_4^i(\alpha)$ is a finite convex function  and so its right derivative exists at $0$ (we allow for the possibility that $\dot{F_4^i}(0+)=-\infty$). Moreover, $F_4^i(\alpha)$ is symmetric about $\alpha=1/2$  which together with convexity implies that $\alpha=1/2$ is a minimum. Hence, $0\in\partial F_4^i(1/2)$ where $\partial F_4^i(\alpha)$ denotes the subgradient set at $\alpha$. 
%
%
By convexity of $F_4^i$ and the definition of the subgradient, $\dot{F_4^i}(0+)\leq y$ for any $y\in \partial F_4^i(1/2)$. Taking $y=0$ and summing over $i$ we conclude
%
\begin{align}\sum_{i=1}^N\dot{F}_4^i(0+)
%
\leq 0. \label{eqn:J4.sum.bd}
\end{align}

Aggregating the above expressions we recover
\[V(\alpha) = \sum_{i=1}^N \left(F_1^i(\alpha)+F_2^i(\alpha)+F_3^i(\alpha)+F_4^i(\alpha)\right)\]
and obtain its right derivative at $0$,
\begin{align*}\dot{V}(0+) &= \sum_{i=1}^N \left(\dot{F}_1^i(0)+\dot{F}_2^i(0)+\dot{F}_3^i(0)+\dot{F}_4^i(0+)\right)\\
&\leq -\mathbb{E}\left[\frac{1}{2}\sum_{i=1}^N\int_0^T\!\!\int_0^T G(|t-s|) d(X_s^{1,i} -X_s^{0, i})d(X_t^{1,i} -X_t^{0, i})\right]<0.
\end{align*}
Here the first inequality follows from \cref{eqn:J1.sum,eqn:J2.sum.bd,eqn:J3.sum.bd,eqn:J4.sum.bd} whereas the last inequality holds as $G$ is strictly positive definite and $\boldsymbol{X}^0\not=\boldsymbol{X}^1$. As mentioned above, $\dot{V}(0+)<0$ is a contradiction and completes the proof.
\end{proof}

\subsection{Proofs for Section \ref{se:singular} (Singular Kernels)}\label{se:proofs.singular}

In this subsection, we extend our results to the case of a singular kernel, where ``singular kernel'' will refer to a function~$G$ satisfying \cref{as:singular.kernel}. Apart from technical verifications, the extension is based on the fact that a singular kernel admits a monotone approximation by kernels satisfying \cref{as:kernel}; cf.\ \cref{rk:kernel.approx}.


%

\subsubsection{Proof of \cref{le:singular.posdef}}

\begin{proof}[Proof of \cref{le:singular.posdef}]
  We need to show that
  \[
  \int_0^T\!\!\int_0^T G(|t-s|) dX_s dX_t >0
  \]
  whenever $X:[0,T]\to \mathbb{R}$ is a c\`adl\`ag function of finite variation that is not constant and satisfies $\int_0^T\!\!\int_0^T G(|t-s|) d|X|_s d|X|_t<\infty$. 
%
  By \cite[Proposition~4.5]{GatheralSchiedSlynko.12}, the double integral admits a representation of the form
  \begin{equation}\label{eq:singular.fourier}
  \int_0^T\!\!\int_0^T G(|t-s|) dX_s dX_t=\int|\widehat X(z)|^{2} \mu(dz).
  \end{equation}
  As $X$ has finite variation, the Fourier--Stieltjes transform~$\widehat X(z)=\int_0^Te^{itz}dX_t$ is a continuous function that does not vanish identically as soon as~$X$ is not constant. Moreover, \cite[Lemma~4.2]{GatheralSchiedSlynko.12} gives an expression for the positive Radon measure~$\mu$ from which we see that~$\mu$ has full support. As a consequence, the right hand side of \eqref{eq:singular.fourier} is strictly positive.
\end{proof}

\subsubsection{Objective Function (\cref{prop:singular.obj.func.rep})}

We first record a simple lemma for later of reference. Recall \cref{def:admissible.X.singular} of admissibility.

\begin{lemma}\label{lem:cross.term.integrable}
    For a profile $\boldsymbol{X}=(X^{1},\dots,X^{N})$ of admissible strategies and $i,j\in\{1,\dots,N\}$, \begin{align*}\mathbb{E}&\left[\int_0^\infty\!\!\int_0^\infty G(|t-s|) d|X^j|_sd|X^i|_t\right]\\
    &\quad \quad \quad \quad \quad \leq \frac{1}{2}\mathbb{E}\left[\int_0^\infty\!\!\int_0^\infty G(|t-s|) \left(d|X^i|_sd|X^i|_t+d|X^j|_sd|X^j|_t\right)\right]<\infty.
    \end{align*}
\end{lemma}

\begin{proof}
Using the positive definiteness of $G$,
\begin{align*}0&\leq \mathbb{E}\left[\int_0^\infty\!\!\int_0^\infty G(|t-s|) d(|X^i|_s-|X^j|_s)d(|X^i|_t-|X^j|_t)\right]\\
&=\mathbb{E}\left[\int_0^\infty\!\!\int_0^\infty G(|t-s|) \left(d|X^i|_sd|X^i|_t+d|X^j|_sd|X^j|_t-2d|X^i|_sd|X^j|_t\right)\right].
\end{align*}
Rearranging and applying the admissibility of $X^i$ and $X^j$ yields the claim.
%
%
%
\end{proof}

\begin{proof}[Proof of \cref{prop:singular.obj.func.rep}]
  Recalling the absence of jumps in the present setting (\cref{rk:no.jumps}), the proof follows the same lines as the one of \cref{prop:obj.func.rep}; we merely indicate where additional justifications are needed. 
%
  First, to justify the application of Fubini's theorem below~\eqref{eqn:obj.intermediate.rep}, we observe that 
\begin{align*}\left|\int_0^T\!\!\int_0^{t-} G(t-s) \sum_{j=1}^NdX_s^{j} dX_t^{i}\right|&\leq \int_0^\infty\!\!\int_0^{\infty} G(|t-s|) \sum_{j=1}^Nd|X^{j}|_sd|X^{i}|_t
\end{align*}
where the right hand side is integrable and therefore almost surely finite by \cref{lem:cross.term.integrable}. 
%
  Second, to argue $|J(X^{i};\boldsymbol{X}^{-i})|<\infty$ at the end of the proof, note that \eqref{eqn:singular.obj.schied.rep} gives
\begin{align*}
    &|J(X^{i};\boldsymbol{X}^{-i})|\\
    &\leq \mathbb{E}\Bigg[\frac{1}{2}\int_0^\infty\!\!\int_0^\infty G(|t-s|)d|X^{i}|_s d|X^{i}|_t + \int_0^\infty\!\!\int_0^{\infty} G(|t-s|) \sum_{j\not=i}d|X^{j}|_s d|X^{i}|_t +C(X^{i})\Bigg]%
    %
\end{align*}
  which is finite by admissibility, \cref{lem:cross.term.integrable} and our assumption that $\mathbb{E}[C(X^{i})]<\infty$.
\end{proof}

\subsubsection{Extension of \cref{lem:exp.admissible}}\label{se:ext.adm}

Let $X$ be an admissible strategy for the singular kernel~$G$ (\cref{def:admissible.X.singular}). To extend \cref{lem:exp.admissible} to the case where~$G$ is singular, it suffices to show that $\tilde{\mathbb{E}}[X]$ satisfies the integrability condition \eqref{eq:admissible.integrability}. 

Clearly the processes $t\mapsto TV(X;[0,t])$, $t\mapsto TV(\tilde{\mathbb{E}}[X];[0,t])$ and $t\mapsto \tilde{\mathbb{E}}[TV(X;[0,t])]$ are c\`adl\`ag, increasing, and essentially bounded. (As $X$ is continuous in the present setting, these processes are even continuous.) %
As above, we write $d|X|_t$ to denote integration with respect to the total variation of $X$ and $d|\tilde{\mathbb{E}}[X]|_t$ to denote integration with respect to the total variation of $\tilde{\mathbb{E}}[X]$. Similarly, we write $d\tilde{\mathbb{E}}[|X|_t]$ to denote integration with respect to the measure induced by $t\mapsto \tilde{\mathbb{E}}[TV(X;[0,t])]$.

\begin{lemma}\label{lem:TV.meas.ineq} If $G$ is a kernel satisfying \cref{as:kernel},
    \begin{align*}
    \mathbb{E}\left[\int_0^\infty\!\!\int_0^\infty G(|t-s|)d| \tilde{\mathbb{E}}[X]|_s d | \tilde{\mathbb{E}}[X]|_t\right]&\leq \mathbb{E}\left[\int_0^\infty\!\!\int_0^\infty G(|t-s|)d \tilde{\mathbb{E}}[|X|_s] d  \tilde{\mathbb{E}}[|X|_t]\right]\\%\label{eq:TV.part.1}
    &\leq \mathbb{E}\left[\int_0^\infty\!\!\int_0^\infty G(|t-s|)d|X|_s d |X|_t\right].
    \end{align*}
%
%
%
%
\end{lemma}

\begin{proof}
By \cref{lem:TV.ineq} the non-negative measures corresponding to $TV(\tilde{\mathbb{E}}[X];[0,t])$ and $\tilde{\mathbb{E}}[TV(X;[0,t])]$ are ordered.\footnote{In the pointwise sense: two  measures $\mu,\nu$ are called ordered if $\mu(A)\leq\nu(A)$ for every Borel set $A$.} Therefore, as $G$ is non-negative,
\[\int_0^\infty\!\!\int_0^\infty G(|t-s|)d| \tilde{\mathbb{E}}[X]|_s d | \tilde{\mathbb{E}}[X]|_t\leq \int_0^\infty\!\!\int_0^\infty G(|t-s|)d \tilde{\mathbb{E}}[|X|_s] d  \tilde{\mathbb{E}}[|X|_t],\]
from which the first claim follows by taking expectations. For the second inequality we use the positive definiteness of the kernel and apply \cref{lem:jensen.ineq.precursor} to the admissible process $t\mapsto TV(X;[0,t])$, 
    \begin{align*}
    0 &\leq \mathbb{E}\left[\int_0^\infty\!\!\int_0^\infty G(|t-s|) d(|X|_s-\tilde{\mathbb{E}}[|X|_s]) d(|X|_t-\tilde{\mathbb{E}}[|X|_t])\right]\\
    & \quad \quad \quad \quad =\mathbb{E}\left[\int_0^\infty\!\!\int_0^\infty G(|t-s|) d|X|_sd|X|_t -\int_0^\infty\!\!\int_0^\infty G( |t-s|)d\tilde{\mathbb{E}}[|X|_s] d\tilde{\mathbb{E}}[|X|_t]\right].
\end{align*}
Rearranging completes the proof.
%
%
%
%
%
%
%
%
\end{proof}


