We are now in a position to prove that \eqref{eq:admissible.integrability} holds for $\tilde{\mathbb{E}}[X^i]$.

\begin{lemma}\label{le:exp.G.int} If $X$ is admissible for the singular kernel $G$, then
    \begin{align*}\mathbb{E}\left[\int_0^\infty\!\!\int_0^\infty G(|t-s|)d|\tilde{\mathbb{E}}[X]|_s d |\tilde{\mathbb{E}}[X]|_t\right]&\leq \mathbb{E}\left[\int_0^\infty\!\!\int_0^\infty G(|t-s|)d|X|_s d |X|_t\right]<\infty
    \end{align*}
and therefore $\tilde{\mathbb{E}}[X^i]$ is admissible; i.e., \cref{lem:exp.admissible} holds for the singular kernel $G$.
\end{lemma}

\begin{proof}
    %
    %
    %
    As seen in \cref{rk:kernel.approx}, the singular kernel $G$ can be approximated by a sequence of kernels $G^n\uparrow G$ satisfying \cref{as:kernel}. By the monotonicity of the sequence and the non-negativity of the integrating measures,
    \begin{align*}0\leq \int_0^\infty\!\!\int_0^\infty G^n(|t-s|)d| \tilde{\mathbb{E}}[X]|_s d | \tilde{\mathbb{E}}[X]|_t&\leq \int_0^\infty\!\!\int_0^\infty G^{n+1}(|t-s|)d| \tilde{\mathbb{E}}[X]|_s d | \tilde{\mathbb{E}}[X]|_t, \ \ \ \forall n\geq1.
    %
    \end{align*}
    Given that $X$ is admissible for $G$, by  applying \cref{lem:TV.meas.ineq} for each $G^n$ we have
    \begin{align*}\mathbb{E}\left[\int_0^\infty\!\!\int_0^\infty G^n(|t-s|)d|\tilde{\mathbb{E}}[X]|_s d |\tilde{\mathbb{E}}[X]|_t\right]&\leq \mathbb{E}\left[\int_0^\infty\!\!\int_0^\infty G^n(|t-s|)d|X|_s d |X|_t\right]\\
    &\leq \mathbb{E}\left[\int_0^\infty\!\!\int_0^\infty G(|t-s|)d|X|_s d |X|_t\right]<\infty.    \end{align*}
    Using that $G^n\uparrow G$ for $d|\tilde{\mathbb{E}}[X]|\otimes d|\tilde{\mathbb{E}}[X]|$ almost every $(s,t)$, almost surely, we have by monotone convergence that
    \begin{align*}\mathbb{E}\left[\int_0^\infty\!\!\int_0^\infty G(|t-s|)d|\tilde{\mathbb{E}}[X]|_s d |\tilde{\mathbb{E}}[X]|_t\right]&\leq \mathbb{E}\left[\int_0^\infty\!\!\int_0^\infty G(|t-s|)d|X|_s d |X|_t\right]<\infty. \qedhere
    \end{align*}
    %
\end{proof}

%
%
%
%

%

\subsubsection{Extension of \cref{prop:reduced.rep.obj}}\label{se:ext.proj}

The following stability property of the objective with respect to monotone approximation of~$G$ will be used to extend \cref{prop:reduced.rep.obj} to the singular case. When there are several kernels under consideration, we write $J_G$ for the objective function with kernel~$G$.

\begin{proposition}\label{prop:G.consistency}
    Let $\boldsymbol{X}$ be an admissible strategy profile for the singular kernel $G$ and let $(G^n)_{n\geq1}$ be a sequence of kernels satisfying \cref{as:kernel} with $G^n\uparrow G$. Then
    \[\lim_{n\to\infty}J_{G^n}(X^i;\boldsymbol{X}^{-i})=J_G(X^i;\boldsymbol{X}^{-i}).\]
\end{proposition}
%

\begin{proof}
    As  $\boldsymbol{X}$ is admissible for $G$, it has no jumps and the objective is given by~\eqref{eqn:singular.obj.schied.rep}. Consider $J_{G^n}(X^i;\boldsymbol{X}^{-i})$ as given by~\eqref{eqn:singular.obj.schied.rep} with $G^n$, we want to take the limit and obtain the same expression with~$G$ instead of $G^n$. Indeed, by \cref{lem:cross.term.integrable},
\begin{align*}
    \frac{1}{2}\int_0^T\!\!\int_0^T G(|t-s|)d|X^{i}|_s d|X^{i}|_t + \int_0^T\!\!\int_0^{T} G(|t-s|) \sum_{j\not=i}d|X^{j}|_s d|X^{i}|_t
\end{align*}
is integrable. As $0\leq G^n \leq G$ and $G^n\to G$ pointwise, dominated convergence yields the claim.
\end{proof}

