Using this stability result, we readily obtain the extension of \cref{prop:reduced.rep.obj}.

\begin{proposition}\label{prop:ext.proj}
    %
    %
    %
    %
    %
    %
    \Cref{prop:reduced.rep.obj} holds for the singular kernel $G$.
    %
    %
    %
    %
\end{proposition}

\begin{proof}
Given an admissible strategy profile $\boldsymbol{X}$ for the singular kernel $G$, we need to show that $J_G(X^i;\boldsymbol{X}^{-i})=J_G(X^i;\tilde{\mathbb{E}}[\boldsymbol{X}^{-i}])$. Define the approximating sequence $G^n\uparrow G$ as in \cref{rk:kernel.approx}. We apply \cref{prop:G.consistency} to the strategies $X^i,\boldsymbol{X}^{-i}$ and $\tilde{\mathbb{E}}[\boldsymbol{X}^{-i}]$ which are admissible for $G$ by \cref{le:exp.G.int}: using \cref{prop:reduced.rep.obj} for each $G^n$, we obtain
\[J_G(X^i;\boldsymbol{X}^{-i})=\lim_{n\to\infty}J_{G_n}(X^i;\boldsymbol{X}^{-i})=\lim_{n\to\infty}J_{G_n}(X^i;\tilde{\mathbb{E}}[\boldsymbol{X}^{-i}])=J_{G}(X^i;\tilde{\mathbb{E}}[\boldsymbol{X}^{-i}]). \qedhere\]
\end{proof}

\subsubsection{Extension of \cref{thm:non.existence.random.eq}}\label{se:ext.non.exist}

The extension of \cref{thm:non.existence.random.eq} does not follow from the stability result alone (which would only give a non-strict inequality). Instead, we appeal once again to strict positive definiteness.

\begin{proposition}\label{prop:ext.non.exist}
    \Cref{thm:non.existence.random.eq} holds for the singular kernel $G$.
\end{proposition}

\begin{proof}
   In view of~\eqref{eqn:singular.obj.schied.rep}, it suffices to show two (in)equalities,
   \begin{align}\label{eq:proof.ext.non.exist.1}
   \mathbb{E}\left[\int_0^T\!\!\int_0^{t-} G(t-s)\sum_{j\not=i}d\tilde{\mathbb{E}}[X_s^{j}] dX^i_t\right]=\mathbb{E}\left[\int_0^T\!\!\int_0^{t-} G(t-s)\sum_{j\not=i}d\tilde{\mathbb{E}}[X_s^{j}] d\tilde{\mathbb{E}}[X^i_t] \right]
   \end{align}
   and
   \begin{align}\label{eq:proof.ext.non.exist.2}
   \mathbb{E}\left[\frac{1}{2}\int_0^T\!\!\int_0^T G(|t-s|) dX_s^{i} dX^i_t\right]>\mathbb{E}\left[\frac{1}{2}\int_0^T\!\!\int_0^T G(|t-s|) d\tilde{\mathbb{E}}[X_s^{i}] d\tilde{\mathbb{E}}[X^i_t]\right].
   \end{align}
   Define again the approximating sequence $G^n\uparrow G$ as in \cref{rk:kernel.approx}. Then \eqref{eq:proof.ext.non.exist.1} holds with $G^n$ instead of $G$, and since $X^i,X^j$  satisfy the admissibility condition~\eqref{eq:admissible.integrability}, we can repeat the same argument as in \cref{prop:G.consistency} to apply dominated convergence and deduce \eqref{eq:proof.ext.non.exist.1} for~$G$. To prove~\eqref{eq:proof.ext.non.exist.2}, we first argue that the equality
   \begin{align}\label{eq:proof.ext.non.exist.3}
    \mathbb{E}&\left[\frac{1}{2}\int_0^\infty\!\!\int_0^\infty G(|t-s|) d(X^i_s-\tilde{\mathbb{E}}[X^i_s]) d(X^i_t-\tilde{\mathbb{E}}[X^i_t]) \right] \\
    &\quad \quad \quad \quad \quad =\mathbb{E}\left[\frac{1}{2}\int_0^\infty\!\!\int_0^\infty G(|t-s|) dX^i_sdX^i_t -\frac{1}{2}\int_0^\infty\!\!\int_0^\infty G( |t-s|)d\tilde{\mathbb{E}}[X^i_s] d\tilde{\mathbb{E}}[X^i_t]\right] \nonumber
\end{align}
from \cref{lem:jensen.ineq.precursor} extends to singular~$G$. Indeed, \eqref{eq:proof.ext.non.exist.3} holds for each $G^n$ by \cref{lem:jensen.ineq.precursor}, and given that $X^i$ and $\tilde{\mathbb{E}}[X^i]$ satisfy \eqref{eq:admissible.integrability}, dominated convergence then yields \eqref{eq:proof.ext.non.exist.3} for $G$. As $G$ is strictly positive definite (\cref{le:singular.posdef}), our assumption that $X^i-\tilde{\mathbb{E}[X^i]}$ is not identically zero yields
\begin{align*}
    0<\mathbb{E}&\left[\frac{1}{2}\int_0^\infty\!\!\int_0^\infty G(|t-s|) d(X^i_s-\tilde{\mathbb{E}}[X^i_s]) d(X^i_t-\tilde{\mathbb{E}}[X^i_t]) \right].
    %
    %
\end{align*}
Applying~\eqref{eq:proof.ext.non.exist.3} and rearranging gives the desired inequality~\eqref{eq:proof.ext.non.exist.2}.
\end{proof}

