\section{Details of Reinforcement Learning and TD3 algorithm}\label{ec:details of RL}
Reinforcement learning (RL) is a framework to teach machines to make decisions based on rewards received from an environment. In model-based RL, an agent interacts with an environment modeled as a Markov decision process (MDP), denoted as $M=\{\mathcal{S}, \mathcal{A}, \mathbb{P}, r, \gamma\}$. Here, $\mathcal{S}$ is the set of possible states in the environment. A particular state $s \in S$ represents the current conditions of the system, such as the current holdings of all equities and market information. $\mathcal{A}$ is the set of feasible actions, which represent the decisions that the agent can make. In finance, an action $a \in \mathcal{A}$ could correspond to buying or selling a certain amount of a particular asset.

The transition probability $\mathbb{P}(\boldsymbol{s}^{'} |\boldsymbol{s}, \boldsymbol{a})$ represents the probability of transitioning to a new state $\boldsymbol{s}'$ when taking action $\boldsymbol{a}$ in the current state $\boldsymbol{s}$. After taking action $\boldsymbol{a}_{t}$ in the $t$-th step, the agent receives a reward $r_t$ based on the path tuple $(\boldsymbol{s}_{t}, \boldsymbol{a}_{t}, \boldsymbol{s}_{t+1})$, where $r_{t}=r\left(\boldsymbol{s}_{t}, \boldsymbol{a}_{t}, \boldsymbol{s}_{t+1}\right)$. The discount factor $\gamma$ balances the importance of immediate and future rewards. In RL, the cumulative reward is the discounted sum of the rewards of each step over a period $T$ (which can be infinite): $\sum_{t=1}^{T} \gamma^{t-1} r_{t}$. The objective of RL is to learn a policy $\pi$ that maximizes the expected cumulative reward in the MDP framework.
\subsection{Bellman Equation and Bellman Optimality}

Given a fixed policy $\pi$, we can determine the state transition dynamics:
\begin{equation}
    \mathbb{P}^\pi(\boldsymbol{s}'|\boldsymbol{s}) = \int_{\boldsymbol{a}\in\mathcal{A}(\boldsymbol{s})}\pi(\boldsymbol{a}|\boldsymbol{s}) \mathbb{P}(\boldsymbol{s}'|\boldsymbol{s},\boldsymbol{a}) \mathrm{d}  \boldsymbol{a}.
\end{equation}
With the state transition dynamics $\mathbb{P}^\pi(\boldsymbol{s}'|\boldsymbol{s})$, we can calculate the probability of any trajectory $\boldsymbol{\tau}^\pi(\boldsymbol{s}_0,\boldsymbol{a}_0,\boldsymbol{s}_1\cdots,\boldsymbol{s_T})$. By taking the expectation over all trajectories, we can estimate the expected sum of discounted future returns. We define the value function $V^{\pi}_t(\boldsymbol{s}): \Pi\times S\times [T]\rightarrow\mathbb{R}$ as the expected cumulative discounted return when visiting state $\boldsymbol{s}$ at time $t\leq T$:
\begin{equation}
V^{\pi}_t(\boldsymbol{s})=\mathbb{E}_{\boldsymbol{\tau}^\pi}\left[\sum_{k=t}^{T} \gamma^{k-t} r_{k}  \mid \boldsymbol{s}_{t}=\boldsymbol{s}\right].
\end{equation}
For example, if we take $\gamma=\frac{1}{1+\delta_f}$ as the discount rate for the value function, the value function may represent the net present value (NPV) of the portfolio at time $t$. 
For notation simplicity, we abbreviate $\mathbb{E}_{\boldsymbol{\tau}^{\pi}}$ as $\mathbb{E}_{\pi}$ for the rest of the paper.
% With the transitions and rewards, we can derive the following value function
% \begin{equation}
%     V^{\pi}_t(\boldsymbol{s})=\mathbb{E}_{\pi}\left[\sum_{k=t}^{T} (\frac{1}{1+\delta_f})^{k-t} \left[\left(b_{t+k+1}+\boldsymbol{1}^\top\boldsymbol{x}_{t+k+1} \right)-\left(b_{t+k}+\boldsymbol{1}^\top\boldsymbol{x}_{t+k}\right)\right]\mid \boldsymbol{s}_{t}=\boldsymbol{s} \right].
% \end{equation}

To account for the stochasticity of the policy  $\pi(\boldsymbol{a}|\boldsymbol{s})$, we introduce the state-action value function $Q_t^\pi(s_t,a_t):\Pi\times\mathcal{S}\times\mathcal{A}(s)\times[T]\rightarrow \mathbb{R}$. This function allows us to estimate the expected value from taking a specific action $\boldsymbol{a}_t$ in state $\boldsymbol{s}_t$ at time $t$ under policy $\pi$. We have
\begin{align}\label{eq:Q from V}
Q_t^\pi(\boldsymbol{s}_t,\boldsymbol{a}_t)&=\mathbb{E}_{\boldsymbol{s}_{t+1}\sim \mathbb{P}^\pi(\boldsymbol{s}'|\boldsymbol{s})}\left[r\left(\boldsymbol{s}_{t}, \boldsymbol{a}_{t}, \boldsymbol{s}_{t+1}\right)+\frac{1}{1+\delta_f}V_{t+1}^\pi(\boldsymbol{s}_{t+1})\right].
\end{align}
This state-action function $Q^\pi$ and state value function $V^\pi$ can be derived from each other through equation (\ref{eq:Q from V}) and 
\begin{equation}
    V_t(\boldsymbol{s}_t) = \int_{\boldsymbol{a}\in \mathcal{A}(\boldsymbol{s}_t)} \pi(\boldsymbol{a}_t|\boldsymbol{s}_t)\mathbb{P}(\boldsymbol{s}_{t+1}|\boldsymbol{s}_t,\boldsymbol{a}_t)Q^\pi(\boldsymbol{s}_t,\boldsymbol{a}_t) \text{d}\boldsymbol{a}_t = \mathbb{E}_\pi\left[Q^\pi(\boldsymbol{s}_t,\boldsymbol{a}_t)\right].
\end{equation}

The aim of reinforcement learning (RL) is to find the optimal policy $\pi^\star(\boldsymbol{a}|\boldsymbol{s})$ that maximizes the expected value function for any $\boldsymbol{s}$, which can be represented as follows: $\forall \boldsymbol{s}$ and $\boldsymbol{a}$, 
\begin{equation}
\pi^{\star}=\arg \max _{\pi \in \Pi} V^{\pi}(\boldsymbol{s})=\arg \max _{\pi \in \Pi} Q^{\pi}(\boldsymbol{s}, \boldsymbol{a}).
\end{equation}
In portfolio management, the optimal policy $\pi^\star$ can be interpreted as the agent's strategy for making purchase-sell decisions for each asset in the portfolio to maximize the expected net present value of their portfolio when observing the market state. The Bellman Optimality Equation \citep{sutton1998introduction} guarantees the existence of such an optimal policy:
\begin{proposition}[Bellman Optimality]
Let $\Pi$ denote the set of all non-stationary and randomized policies, and assume an infinite time horizon. Define:
$$
\begin{aligned}
V^{\star}(s) :=\sup _{\pi \in \Pi} V^\pi(s), \quad Q^{\star}(s, a) :=\sup _{\pi \in \Pi} Q^\pi(s, a) .
\end{aligned}
$$
There exists a stationary policy $\pi^\star$ such that for all $s \in \mathcal{S}$ and $a \in \mathcal{A}$,
$$
\begin{aligned}
V^{\pi^\star(s)} =V^{\star}(s),\quad Q^{\pi^\star}(s, a) =Q^{\star}(s, a) .
\end{aligned}
$$
The optimal value function satisfies 
\begin{equation}\label{eq:Bellman Eq}
Q_t^{\pi^\star}(\boldsymbol{s}_t,\boldsymbol{a}_t)=\mathbb{E}_{\boldsymbol{s}_{t+1}\sim \mathbb{P}^{\pi^\star}(\boldsymbol{s}'|\boldsymbol{s})}\left[r\left(\boldsymbol{s}_{t}, \boldsymbol{a}_{t}, \boldsymbol{s}_{t+1}\right)+\frac{1}{1+\delta_f} \left[\max_{\boldsymbol{a}_{t+1}\in \mathcal{A}(\boldsymbol{s}_{t+1})} Q_t^{\pi^\star}(\boldsymbol{s}_{t+1},\boldsymbol{a}_{t+1})\right]\right].
\end{equation}
\end{proposition}


The Bellman optimality equation demonstrates the existence of optimal policies and provides a approach to find $\pi^{\star}$ by finding the optimal value functions $Q^{\pi^{\star}}(\boldsymbol{s}, \boldsymbol{a})$ or $V^{\pi^{\star}}(\boldsymbol{s})$. Equation (\ref{eq:Bellman Eq}) is particularly useful in practice since it allows us to easily derive and evaluate policy without modeling transition dynamics, and can handle both discrete and continuous action spaces. This approach is especially important in financial market settings, where transition dynamics are difficult to capture and decisions are continuous.

The concept of modeling the value function directly, rather than attempting to estimate the transition dynamics $\mathbb{P}(\boldsymbol{s}'|\boldsymbol{s},\boldsymbol{a})$ forms the basis of  \textit{model-free} RL algorithms \citep{silver2014ddpg, silver2016mastering, fujimoto2018td3}. These algorithms use various function types and techniques to approximate the value function induced by a given policy, and seek to identify the value function that satisfies the equilibrium in equation \eqref{eq:Bellman Eq}. Our framework also employs model-free RL algorithms as the agents, given the difficulty of directly modeling the transition dynamics in financial markets.

\begin{lemma}\label{Bellman equation}
(Bellman Equation) If the state space and action space is discrete and finite, for a fixed policy $\pi$, we have the following recursive relation for the state value function $V^{\pi}(\boldsymbol{s})$ and the state-action value function $Q^{\pi}(\boldsymbol{s}, \boldsymbol{a})$
\begin{equation}
\begin{aligned}
V^{\pi}(\boldsymbol{s}) &=\sum_{\boldsymbol{a} \in \mathcal{A}(\boldsymbol{s})} \pi(\boldsymbol{a}|\boldsymbol{s}) \sum_{\boldsymbol{s}' \in \mathcal{S}} \mathbb{P}(\boldsymbol{s}'|\boldsymbol{s},\boldsymbol{a})\left[r(\boldsymbol{s, \boldsymbol{a}, \boldsymbol{s}')}+\gamma V^{\pi}\left(\boldsymbol{s}'\right)\right]=\sum_{\boldsymbol{a} \in \mathcal{A}(\boldsymbol{s})} \pi(\boldsymbol{a} \mid \boldsymbol{s}) Q^{\pi}(\boldsymbol{s}, \boldsymbol{a}).
\end{aligned}
\end{equation}
Similarly, we can also express the $Q(\boldsymbol{s}, \boldsymbol{a})$ as:
\begin{equation}
\begin{aligned}
Q^{\pi}(\boldsymbol{s}, \boldsymbol{a}) =\sum_{\boldsymbol{s}'\in\mathcal{S}} \mathbb{P}(\boldsymbol{s}'|\boldsymbol{s},\boldsymbol{a}) r_{t}(\boldsymbol{s}, \boldsymbol{a}, \boldsymbol{s}')+\gamma \sum_{\boldsymbol{s}' \in S} \mathbb{P}(\boldsymbol{s}'|\boldsymbol{s},\boldsymbol{a})V^{\pi}\left(\boldsymbol{s}'\right)
\end{aligned}
\end{equation}
\end{lemma}

\proof{Proof: }
To show a brief proof of the Bellman equation, we start with the definition of the state value function $V^{\pi}(\boldsymbol{s})$ and the state-action value function $Q^{\pi}(\boldsymbol{s}, \boldsymbol{a})$ under a fixed policy $\pi$:
\begin{align*}
V^{\pi}(\boldsymbol{s}) &= \mathbb{E}_{\pi}\left[\sum_{t=0}^{\infty} \gamma^t r_{t+1} \mid  \boldsymbol{s}_0 =  \boldsymbol{s}\right] \\
Q^{\pi}( \boldsymbol{s},  \boldsymbol{a}) &= \mathbb{E}_{\pi}\left[\sum_{t=0}^{\infty} \gamma^t r_{t+1} \mid \boldsymbol{s}_0 =  \boldsymbol{s},  \boldsymbol{a}_0 =  \boldsymbol{a}\right],
\end{align*}
where $r_{t+1}$ is the reward obtained at time $t+1$ and $\gamma$ is the discount factor.

Now, we can use the law of total expectation to expand these expressions as follows:
\begin{align*}
V^{\pi}(\boldsymbol{s}) &= \mathbb{E}_{\pi}\left[\sum_{t=0}^{\infty} \gamma^t r_{t+1} \mid \boldsymbol{s}_0 = \boldsymbol{s}\right] \\
&= \sum_{\boldsymbol{a} \in \mathcal{A}(\boldsymbol{s})} \pi(\boldsymbol{a}|\boldsymbol{s}) \mathbb{E}_{\pi}\left[\sum_{t=0}^{\infty} \gamma^t r_{t+1} \mid \boldsymbol{s}_0 = \boldsymbol{s}, \boldsymbol{a}_0 = \boldsymbol{a}\right] \\
&= \sum_{\boldsymbol{a} \in \mathcal{A}(s)} \pi(\boldsymbol{a}|\boldsymbol{s}) Q^{\pi}(s, a),
\end{align*}
where $\mathcal{A}(\boldsymbol{s})$ is the set of actions available in state $\boldsymbol{s}$.
Similarly, we can expand $Q^{\pi}(\boldsymbol{s}, \boldsymbol{a})$ as follows:
\begin{align*}
Q^{\pi}(\boldsymbol{s}, \boldsymbol{a}) &= \mathbb{E}_{\pi}\left[\sum_{t=0}^{\infty} \gamma^t r_{t+1} \mid \boldsymbol{s}_0 = \boldsymbol{s}, \boldsymbol{a}_0 = \boldsymbol{a}\right] \\
&= \mathbb{E}_{\pi}\left[r_{1} + \sum_{t=1}^{\infty} \gamma^t r_{t+1} \mid \boldsymbol{s}_0 = \boldsymbol{s}, \boldsymbol{a}_0 = \boldsymbol{a}\right] \\
&=\sum_{\boldsymbol{s}'\in\mathcal{S}} \mathbb{P}(\boldsymbol{s}'|\boldsymbol{s},\boldsymbol{a}) r_{t}(\boldsymbol{s}, \boldsymbol{a}) + \gamma \sum_{\boldsymbol{s}' \in S} \mathbb{P}(\boldsymbol{s}'|\boldsymbol{s},\boldsymbol{a})\mathbb{E}_{\pi}\left[\sum_{t=0}^{\infty} \gamma^t r_{t+2} \mid \boldsymbol{s}_1 = \boldsymbol{s}', \boldsymbol{a}1 = \boldsymbol{a}'\right] \\
&= \sum_{\boldsymbol{s}' \in S} \mathbb{P}(\boldsymbol{s}'|\boldsymbol{s},\boldsymbol{a}) r_{t}(\boldsymbol{s}, \boldsymbol{a}) + \gamma \sum_{\boldsymbol{s}' \in S} \mathbb{P}(\boldsymbol{s}'|\boldsymbol{s},\boldsymbol{a}) V^{\pi}(\boldsymbol{s}'),
\end{align*}
where $\boldsymbol{a}'$ is an action chosen by the policy $\pi$ in state $\boldsymbol{s}'$.

Therefore, we have proved the Bellman equation for the state value function $V^{\pi}(\boldsymbol{s})$ and the state-action value function $Q^{\pi}(\boldsymbol{s}, \boldsymbol{a})$ under a fixed policy $\pi$. \Halmos
\endproof

For small-scale problems, such as a tabular MDP, if a model $M=\{\mathcal{S}, \mathcal{A}, \mathbb{P}, r, \gamma\}$ is provided, we can directly compute the value function $V^{\pi}$ and the action-value function $Q^{\pi}$ based on the transition probabilities and expected reward dynamics. However,  for larger problems with continuous state and action spaces, such as those encountered in finance settings, it is not feasible to visit each state and compute the value function directly. Therefore, we need to approximate the $Q$ and $V$ functions using function approximation techniques, such as deep neural networks. Despite the continuous nature of the state and action spaces, the Bellman equation can still be used to derive the optimal policy. This is known as the continuous Bellman equation, and it has been shown to be useful in finance applications (see Lemma \ref{continuous Bellman equation}).
\begin{lemma}\label{continuous Bellman equation}
(Continuous Bellman Equation) For a fixed policy $\pi$, we have the following recursive relation for the value function:
\begin{equation}
V^{\pi}(s)=\int_{\alpha \in A(s)} \pi(a|s) \int_{s^{\prime} \in S} \mathbb{P}(s'|s,a) \left[\boldsymbol{r}(\boldsymbol{s}, \boldsymbol{a},\boldsymbol{s}^{\prime})+\gamma V^{\pi}\left(s^{\prime}\right)\right] \text{d} \boldsymbol{s}^{\prime} \text{d} \boldsymbol{a}
\end{equation}
\end{lemma}

Another property of MDP and reinforcement learning is the Bellman optimality equation \citep{sutton1998introduction}. This proposition proves the existence of the optimal policy and the optimal value function. Formally, the Bellman optimality equation can be written as follows.
\begin{proposition}
(Bellman Optimality Equation) \citep{sutton1998introduction} There exists an optimal policy $\pi^{\star}$,
allowing the maximization of $V$-type and $Q$-type value functions at the same time. Formally written, we have that:
\begin{equation}
\pi^{\star}=\arg \max _{\pi \in \Pi} V^{\pi}(s)=\arg \max _{\pi \in \Pi} Q^{\pi}(s, a).
\end{equation}
\end{proposition}

\proof{Proof:}
To briefly show that there exists an optimal policy $\pi^{\star}$ that maximizes both the state value function $V^{\pi}(s)$ and the state-action value function $Q^{\pi}(s,a)$, we first define the optimal value functions $V^{\star}(s)$ and $Q^{\star}(s,a)$ as:
\begin{align*}
V^{\star}(\boldsymbol{s}) &= \max_{\pi \in \Pi} V^{\pi}(\boldsymbol{s}) \\
Q^{\star}(\boldsymbol{s}, \boldsymbol{a}) &= \max_{\pi \in \Pi} Q^{\pi}(\boldsymbol{s}, \boldsymbol{a}),
\end{align*}
where $\Pi$ is the set of all policies.

Now, we want to show that there exists a policy $\pi^{\star}$ that achieves the optimal value functions $V^{\star}(\boldsymbol{s})$ and $Q^{\star}(\boldsymbol{s},\boldsymbol{a})$ simutaneously.
We first prove that if $\pi'$ is a policy that achieves $V^{\star}(s)$, then it also achieves $Q^{\star}(\boldsymbol{s},\boldsymbol{a})$ for all $a \in \mathcal{A}(\boldsymbol{s})$, where $\mathcal{A}(\boldsymbol{s})$ is the set of actions available in state $\boldsymbol{s}$.

Assume that $\pi'$ achieves $V^{\star}(s)$, i.e., $V^{\pi'}(s) = V^{\star}(s)$. Then, we have:
\begin{equation}
\begin{aligned}
Q^{\pi'}(\boldsymbol{s}, \boldsymbol{a}) &= \sum_{\boldsymbol{s}' \in \mathcal{S}} \mathbb{P}(\boldsymbol{s}'| \boldsymbol{s},\boldsymbol{a}) [r(\boldsymbol{s}, \boldsymbol{a}, \boldsymbol{s}') + \gamma V^{\pi'}(\boldsymbol{s}')] \\
&\leq \sum_{s' \in S} \mathbb{P}(\boldsymbol{s}'| \boldsymbol{s},\boldsymbol{a})  [r(\boldsymbol{s}, \boldsymbol{a}, \boldsymbol{s}') + \gamma V^{\star}(\boldsymbol{s}')] \\
&= \max_{\pi \in \Pi} \sum_{s' \in S} \mathbb{P}(\boldsymbol{s}'| \boldsymbol{s},\boldsymbol{a})  [r(\boldsymbol{s}, \boldsymbol{a}, \boldsymbol{s}') + \gamma V^{\pi}(\boldsymbol{s}')] \\
&= Q^{\star}(\boldsymbol{s}, \boldsymbol{a})
\end{aligned}
\end{equation}
where we used the fact that $\pi'$ achieves $V^{\star}(\boldsymbol{s})$, and hence $V^{\pi'}(\boldsymbol{s}) \leq V^{\star}(\boldsymbol{s})$, and the maximization over policy space $\Pi$.
Similarly, we can show that if $\pi'$ is a policy that achieves $Q^{\star}(\boldsymbol{s},\boldsymbol{a})$, then it also achieves $V^{\star}(\boldsymbol{s})$. 
\Halmos
\endproof

This equation also indicates the following relations under optimal policy $\pi^{\star}$:
\begin{equation}\label{eq:Bellman optimality}
\begin{aligned}
&V^{\pi^{\star}}(\boldsymbol{s})=\max _{\boldsymbol{a} \in \mathcal{A}(\boldsymbol{s})}\left( \sum_{\boldsymbol{s}^{\prime}\in\mathcal{S}}\mathbb{P}(\boldsymbol{s}'| \boldsymbol{s},\boldsymbol{a}) r(\boldsymbol{s}, \boldsymbol{a},\boldsymbol{s}')+\gamma \sum_{\boldsymbol{s}^{\prime} \in \mathcal{S}} \mathbb{P}(\boldsymbol{s}'| \boldsymbol{s},\boldsymbol{a}) V^{\pi^{\star}}\left(\boldsymbol{s}'\right)\right) \\
&Q^{\pi^{\star}}(\boldsymbol{s}, \boldsymbol{a})=\sum_{\boldsymbol{s}^{\prime}\in\mathcal{S}}\mathbb{P}(\boldsymbol{s}'| \boldsymbol{s},\boldsymbol{a}) r(\boldsymbol{s}, \boldsymbol{a},\boldsymbol{s}')+\gamma \sum_{\boldsymbol{s}^{\prime} \in \mathcal{S}} \mathbb{P}(\boldsymbol{s}'| \boldsymbol{s},\boldsymbol{a}) \max _{\boldsymbol{a}^{\prime} \in \mathcal{A}(\boldsymbol{s}')} Q^{\pi^{\star}}\left(\boldsymbol{s}^{\prime}, \boldsymbol{a}^{\prime}\right) .
\end{aligned}
\end{equation}

Bellman optimality equation shows the existence of the optimal strategy. It also provides us with a way to find the optimal $\pi^{\star}$ by finding the optimal value functions $Q^{\pi^{\star}}(\boldsymbol{s}, \boldsymbol{a})$ or $V^{\pi^{\star}}(\boldsymbol{s})$. Since the aim of RL is to find the optimal policy $\pi^\star$ achieving the optimal value function, we can directly approximate the optimal value function bypassing modeling the transition $\mathbb{P}$.
The intuition of modeling the value function directly, rather than attempting to estimate the transition dynamics $\mathbb{P}(\boldsymbol{s}'|\boldsymbol{s},\boldsymbol{a})$ forms the basis of  \textit{model-free} RL algorithms \citep{silver2014ddpg, silver2016mastering, fujimoto2018td3}. These algorithms use various function types and techniques to approximate the value function induced by a given policy with the aim to achieve the equilibrium in Equaition \eqref{eq:Bellman optimality}. Our framework also employs model-free RL algorithms as the agents, given the difficulty of directly modeling the transition dynamics in financial markets. In the next section we will present the Twin Delayed Deep Deterministic Policy Gradient (TD3), which use neural networks to approximate the value function and policy.

\subsection{Twin Delayed Deep Deterministic Policy Gradient (TD3)}\label{ec:td3}
In this part we present the exact steps in deploying TD3 algorithm on the embedded states and the approaches to training a TD3 agent. The pseudo-code for TD3 algorithm based on the dynamic embedding is presented in Algorithm \ref{alg: TD3}.

As mentioned in the main body, the TD3 algorithm deploys two critic networks $Q_{\nu_1},Q_{\nu_2}: \mathcal{Z}\times\mathcal{A}\rightarrow\mathbb{R}$ to estimate the state-action value function, and use an actor network $\pi_\iota: \mathcal{S}\rightarrow\mathcal{A}$ to generate the best action. Each step we take action according to $\pi_\iota(\boldsymbol{z_s})$, and evaluate the action based on the value function $Q_{\nu}$. The target networks $Q_{\nu'_1},Q_{\nu'_2},\pi_\iota'$ are used for stable updates of the parameters of the original network, which we will discuss later.

The Twin Delayed Deep Deterministic policy gradient (TD3) algorithm builds upon the Deep Deterministic Policy Gradient (DDPG) algorithm \citep{lillicrap2015continuous}. TD3 addresses issues such as overestimation bias and learning instability by incorporating improvements in the form of \textit{double Q-learning}, \textit{delayed policy updates}, and \textit{target policy smoothing}.

\subsubsection*{Double Q-learning.}
In the TD3 algorithm, double Q-learning is employed to mitigate the overestimation bias that may arise from using a single critic network. Overestimation can lead to suboptimal policies and slower convergence. TD3 incorporates two separate critic networks, $Q_{\nu_1}$ and $Q_{\nu_2}$, to independently learn the Q-values. During the update process, the algorithm takes the minimum of the two critics' predictions ($\min_{i}Q_{\nu_i}$), which reduces overestimation bias. This technique is inspired by Double Q-learning, and it helps improve the stability of the learning process.

\subsubsection*{Delayed Policy Updates.}
TD3 introduces delayed policy updates to further enhance the stability of training. In this approach, the actor network is updated less frequently compared to the critic networks. As shown in the steps :\textit{Update actor network} and \textit{Smoothly update three target network} in Algorithm \ref{alg: TD3}, we only update the actor network every $d$ step. By delaying the policy updates, the actor has access to more accurate Q-value estimates, which results from the additional critic network updates. This, in turn, leads to more stable policy improvements and prevents premature convergence to suboptimal policies.

\subsubsection*{Target Policy Smoothing.}
Target policy smoothing is a technique introduced in TD3 to address the exploitation of unrealistic Q-value estimates due to the inherent function approximation errors in neural networks. This method involves adding a small amount of noise $\varepsilon$ (in Step 2 in Algorithm \ref{alg: TD3}) to the target action during the critic update step, effectively smoothing the target policy. By incorporating noise into the target actions, the algorithm learns to generalize better across different states and actions, reducing the chance of overfitting to specific scenarios.

Together, these three improvements enable the TD3 algorithm to exhibit superior performance and stability compared to the DDPG algorithm. The incorporation of double Q-learning, delayed policy updates, and target policy smoothing helps to mitigate overestimation bias and learning instability, leading to more reliable and efficient reinforcement learning.

Throughout the training process, TD3 alternates between learning the actor and critic networks using experience replay and soft updates to the target networks. This iterative procedure allows TD3 to achieve superior performance and stability compared to its predecessor, DDPG.
\begin{algorithm}[htbp]
    \caption{TD3 algorithm with dynamic embedding}
    \label{alg: TD3}
    \SetAlgoLined
\KwIn{Initialize critic networks $Q_{\nu_{1}}, Q_{\nu_{2}}$, and actor network $\pi_{\iota}$ with parameters $\nu_{1}, \nu_{2}, \iota$; initialize target networks $\nu_{1}^{\prime} \leftarrow \nu_{1}, \nu_{2}^{\prime} \leftarrow \nu_{2}, \iota^{\prime} \leftarrow \iota$; initialize buffer $\mathcal{B}$; set action noise variance $\sigma^2$ and maximum noise level $c$; initialize the pre-trained encoder $\Gamma_\phi$; set frequency of delayed policy update $d$ and frequency of dynamic update |U|}
    \For{$t=1$ to $T$}{
\textbf{Take action}: receive states $\boldsymbol{s}$, encode it with $\Gamma_\phi$ into $\boldsymbol{z_s}$, select action with exploration noise $\boldsymbol{a} \sim \pi_{\phi}(\boldsymbol{z_s})+\epsilon$, $\epsilon \sim \mathcal{N}(0, \sigma^2I)$, observe reward $r$ and new state $\boldsymbol{s^{\prime}}$; and store transition tuple $\left(\boldsymbol{s}, \boldsymbol{a}, r, \boldsymbol{s^{\prime}}\right)$ in $\mathcal{B}$;\\
\textbf{Update critic networks}: sample mini-batch of $b$ transitions $\{\left(\boldsymbol{s}_i, \boldsymbol{a}_i, r_i, \boldsymbol{s^{\prime}}_i\right)\}_{i=1}^{b}$ from $\mathcal{B}$ and encode the corresponding latent state $\left\{\boldsymbol{z_{s_i}}\right\}_{i=1}^b$ with $\Gamma_\phi$;\\
    recalculate the target optimal action under the current policy network
    $$\tilde{\boldsymbol{a}}_i \leftarrow \pi_{\iota^{\prime}}\left(\boldsymbol{z_{s_i}}(\boldsymbol{s^{\prime}})\right)+\epsilon, \quad \epsilon \sim \operatorname{clip}(\mathcal{N}(0, \sigma^2I),-c\boldsymbol{1}, c\boldsymbol{1}),$$ and the target value:
    $y_i \leftarrow r_i +\gamma \min _{i=1,2} Q_{\nu_{i}^{\prime}}\left(\boldsymbol{s^{\prime}}, \tilde{\boldsymbol{a}}\right)$; and update parameter of critic networks: $$\nu_{i} \leftarrow \operatorname{argmin}_{\nu_{i}} b^{-1} \sum\left(y_i-Q_{\nu_{i}}(\boldsymbol{z_{s_i}}, \boldsymbol{a})\right)^{2}.$$ 
\If {$t = 0 \  (\bmod \ d) $}{
\textbf{Update actor network} parameter through:
$$\iota =\iota-\alpha_\iota \left.b^{-1} \sum \nabla_{\boldsymbol{a}} Q_{\nu_{1}}(\boldsymbol{z_s}, \boldsymbol{a})\right|_{\boldsymbol{a}=\pi_{\iota}(\boldsymbol{z_s})} \nabla_{\iota} \pi_{\iota}(\boldsymbol{z_s}).$$
\textbf{Smoothly update target network} parameters: 
\begin{align*}
   \nu_{i}^{\prime} & \leftarrow \tau \nu_{i}+(1-\tau) \nu_{i}^{\prime}, \\
   \iota^{\prime} & \leftarrow \tau \iota+(1-\tau) \iota^{\prime}.
\end{align*}
}
\If{$t = 0 \ (\bmod \ |U|)$}{\textbf{Update the encoder} $\Gamma_\phi$ with online meta-learning.}}
  \end{algorithm}



\section{Details on Generative Autoencoders}\label{ec:autoencoders}
Generative autoencoders aim to simulate the real-world data generation process of a random variable by learning the joint distribution of all variables related to its generation. 
% We can tackle the generation process through the point of optimal transport according to \cite{bousquet2017optimal} and \cite{Martin2017WGAN}.

\subsection{Generative Autoencoders}
We begin by introducing the concept and use of generative encoders. Considering two random variables $X$ and $Y$ in a  compact set $
\mathcal{X}$, we aim to learn the joint distribution of two random variables $X\in\mathcal{X}$ and $Y\in\mathcal{X}$ through a latent variable $Z\in \mathcal{Z}$ that supports the conditional independence of $X$ and $Y$, such that $(Y \bot X) \mid Z$. Most work using generative models focuses on regenerating $X\in \mathcal{X}$ through the latent variable $Z\in\mathcal{Z}$, or what is known as \textit{self-regeneration} ($X\xrightarrow{\text{encoder}} Z \xrightarrow{\text{decoder}}X$). The step $X\xrightarrow{\text{encoder}} Z$ is usually called encoding and $Z\xrightarrow{encoder} X$ is usually called decoding. 

We describe the generative encoders with a probabilistic model. For $X,Y \in \mathcal{X}$ and $Z\in\mathcal{Z}$, we assume $X \sim P_{X}$ and $Y \sim P_{Y}$, and for $Z\in P_{Z}$.
We use $\mathcal{P}_{X,Y}:=\mathcal{P}\left(X \sim P_{X}, Y \sim P_{Y}\right)$ to denote the set of all joint distributions of $(X, Y)$ with marginal distributions $P_{X}$ and $P_{Y}$. 
%The subscript $G$ in $P_{G}$ represents the generative model, which is typically represented by a deep neural network. 
Similarly, for a pair $(X,Z)$, we have for joint distribution $\mathcal{P}_{X,Z}:=\mathcal{P}\left(X \sim P_{X}, Z \sim P_{Z}\right)$, where $P_{Z}$ is the prior distribution over the latent variable $\mathcal{Z}$. 
In the context of generative tasks, we define a cost function $\mathcal{C}(X, Y): \mathcal{X} \times \mathcal{X} \rightarrow \mathcal{R}_{+}$, which measures the difference or regeneration loss between the input data $X$ and the generated data $Y$. The objective is to minimize the transport cost
\begin{equation} \label{equation: transportation loss}
W_{\mathcal{C}}(P_X, P_Y):=\inf _{P_{X,Y} \in \mathcal{P}_{X,Y}}\mathbb{E}_{(X, Y) \sim P_{X,Y}} [\mathcal{C}(X, Y)].
\end{equation}

%The set of all $(X, Y, Z)$ joint distributions is denoted by $\mathcal{P}_{X, Y, Z}$, with $X \sim P_{X},(Y, Z) \sim P_{Y, Z}$, and $(Y \bot X) \mid Z$. Additionally, we use the notation $\mathcal{P}_{X, Y}$ and $\mathcal{P}_{X, Z}$ to denote the sets of marginal distributions on $(X, Y)$ and $(X, Z)$ induced by the distribution $\mathcal{P}_{X, Y, Z}$. 




Our setting, as mentioned in the main body of the paper, is modified into
\begin{equation}\label{eq:ec transition equation}
\boldsymbol{s} \xrightarrow[\text{encode}]{\Gamma_\phi} \boldsymbol{\boldsymbol{z_s}} \xrightarrow[\text{\text{decode with }} \boldsymbol{a}\in\mathcal{A}(s)]{G_\theta} \boldsymbol{s^\prime},
\end{equation}
where each notation represents:
\begin{itemize}
\item Encoder $\Gamma_\phi(\boldsymbol{z_s}|\boldsymbol{s})$: maps the state $\boldsymbol{s}$ to its latent representation $z_s$,  parameterized by $\phi$;
\item Decoder $G_\theta(\boldsymbol{s}'|\boldsymbol{z_s}, \boldsymbol{a})$: maps the  latent state $\boldsymbol{z_s}$ and action $\boldsymbol{a}$ back to the predicted next state $\boldsymbol{\hat{s}}'$, parameterized by $\theta$.
\end{itemize}
With the encoder and decoder, we reconstruct the next state through
\begin{equation}
    \mathbb{P}'_{\theta,\phi}(\boldsymbol{\hat{s}}|\boldsymbol{s},\boldsymbol{a})= \int_{z_s\in\mathcal{Z}} G_\theta(\boldsymbol{s}'|\boldsymbol{z_s}, \boldsymbol{a})\Gamma_\phi(\boldsymbol{z_s}|s)\text{d}\boldsymbol{z_s}.
\end{equation}
Similar to conventional autoencoders, we hope that for any given $(\boldsymbol{s},\boldsymbol{a})$, the reconstructed distribution $\mathbb{P}'_{\theta,\phi}$ of next state $\boldsymbol{s}$ is close to the real distribution $\mathbb{P}_{\theta,\phi}$.
Thus we modify \eqref{equation: transportation loss} to minimize the transport cost between the reconstructed transition probability and the exact transition probability under given $(\boldsymbol{s},\boldsymbol{a})$. We use $\mathcal{P}_{\boldsymbol{\hat{s}},\boldsymbol{s}}:= \mathcal{P}(\boldsymbol{s}'\sim \mathbb{P}(\cdot|\boldsymbol{s},\boldsymbol{a}),\boldsymbol{\hat{s}}'\sim \mathbb{P}'_{\theta,\phi}(\cdot|\boldsymbol{s},\boldsymbol{a}))$ denote all distribution of $(\boldsymbol{\hat{s}}',\boldsymbol{s}')$ with marginal distribution of $\mathbb{P}$ and $\mathbb{P}'_{\theta,\phi}$, thus we have:
\begin{equation} \label{equation: transition transportation loss}
W_{\mathcal{C}}(\mathbb{P}'_{\theta,\phi}, \mathbb{P}):=\inf _{P_{\boldsymbol{\hat{s}},\boldsymbol{s}} \in \mathcal{P}_{\boldsymbol{\hat{s}},\boldsymbol{s}}}\mathbb{E}_{\boldsymbol{\hat{s}},\boldsymbol{s} \sim P_{\boldsymbol{\hat{s}},\boldsymbol{s}}} [\mathcal{C}(\boldsymbol{\hat{s}},\boldsymbol{s})].
\end{equation}
In our framework, the decoder $G_\theta(\cdot|\boldsymbol{z_s},\boldsymbol{a})$ for next state is constructed through two steps, where the $\boldsymbol{z_s}$ is sampled from a fixed distribution $P_{\boldsymbol{z}}$ on the latent space $\mathcal{Z}$, and then $\boldsymbol{z_s}$ is mapped to the next state $\hat{\boldsymbol{s}'}\in\mathcal{S}$, leading to 
\begin{equation}
\mathbb{P}_\theta'(\boldsymbol{s}'|\boldsymbol{s},\boldsymbol{a})=\int_{\mathcal{Z}} G_\theta(\boldsymbol{s}'|\boldsymbol{z_s},\boldsymbol{a})p_z(\boldsymbol{z_s})\text{d}\boldsymbol{z_s}.
\end{equation}
There is a special case that the decoder is a deterministic decoder, which indicates the $G_\theta(\cdot|\boldsymbol{s},\boldsymbol{a})$ is Dirac distribution. For simplicity, in deterministic decoder case, we write the decoder as $\boldsymbol{s}'=f_{G_\theta}(\boldsymbol{s},\boldsymbol{a})$, which deterministically maps the state-action pair $(\boldsymbol{s},\boldsymbol{a})$ to the next state $\boldsymbol{s}'$.

Then we have the marginal distribution of $\boldsymbol{z_s}$ under given $\boldsymbol{s}$ from the state encoder $\mathbb{P}_\phi(\boldsymbol{z_s})=\Gamma_\phi(\boldsymbol{z_s}|\boldsymbol{s})$, which is assumed to match the known prior $P_z$ for any given $\boldsymbol{s}$.
\begin{proposition}\label{prop:encode-decode}
With given current state-action pair $(\boldsymbol{s},\boldsymbol{a})$, for $G_\theta$ as defined above with deterministic $G_\theta(\boldsymbol{s}'\mid\boldsymbol{z_s},\boldsymbol{a})$ and any function $f_{G_\theta}(\boldsymbol{z_s},\boldsymbol{a}): \mathcal{Z}\times\mathcal{A} \rightarrow \mathcal{S}$, we sample $\boldsymbol{z_s}$ from $\Gamma_\phi(\boldsymbol{z_s}|\boldsymbol{s})$ and then  
$\boldsymbol{\hat{s}}'$ from $G_\theta(\boldsymbol{z_s},\boldsymbol{a})$. Comparing the estimated next state $\boldsymbol{\hat{s}}'$ and the exact next state $\boldsymbol{s}'$,
we have 
\begin{equation}
\inf _{P \in \mathcal{P}\left(\boldsymbol{s}' \sim \mathbb{P}, \boldsymbol{\hat{s}}'\sim \mathbb{P}'_{\phi,\theta}\right)} \mathbb{E}_{(\boldsymbol{s}', \boldsymbol{\hat{s}}') \sim P}[\mathcal{C}(\boldsymbol{s}', \boldsymbol{\hat{s}}')]=\inf _{\Gamma_\phi(\cdot|\boldsymbol{s})=P_Z} \mathbb{E}_{\mathbb{P}_{\boldsymbol{s}'}} \mathbb{E}_{\Gamma_\phi(\boldsymbol{z_s} \mid \boldsymbol{s})}[\mathcal{C}(\boldsymbol{s}', f_{G_\theta}(\boldsymbol{z_s},\boldsymbol{a}))].
\end{equation}
\end{proposition}

\textit{Proof:}  
Since the $G_\theta(\boldsymbol{\hat{s}}'|\boldsymbol{z_s},\boldsymbol{a})$ is a deterministic mapping, for any subset $S$ in $\mathcal{S}$, we have $\mathbb{E}\left[\mathbb{I}_{[\boldsymbol{\hat{s}}'\in S]}|\boldsymbol{s}',\boldsymbol{a},\boldsymbol{z_s}\right] = \mathbb{E}\left[\mathbb{I}_{[\boldsymbol{\hat{s}}'\in S]}|\boldsymbol{a},\boldsymbol{z_s}\right]$, which implies the independence of 
$\boldsymbol{\hat{s}}'$ and $ \boldsymbol{s}'$ given $(\boldsymbol{z_s},\boldsymbol{a})$. 

The tower rule of expectation, and the conditional independence property of $\mathcal{P}_{\boldsymbol{s}', \boldsymbol{\hat{s}}', \boldsymbol{z_s}}$ with given $(\boldsymbol{s},\boldsymbol{a})$, we have that 
\begin{equation}
\begin{aligned}
W_\mathcal{C}\left(\mathbb{P}'_{\theta,\phi}, \mathbb{P}\right) & =\inf _{P \in \mathcal{P}_{\boldsymbol{s}',\boldsymbol{z_s},\boldsymbol{\hat{s}}'}}\mathbb{E}_{P(\boldsymbol{s}',\boldsymbol{z_s},\boldsymbol{\hat{s}}'|\boldsymbol{s},\boldsymbol{a}) }[\mathcal{C}(\boldsymbol{s}', \boldsymbol{\hat{s}}')] \\
& =\inf _{P \in \mathcal{P}_{\boldsymbol{s}',\boldsymbol{z_s},\boldsymbol{\hat{s}}'}} \mathbb{E}_{\Gamma_\phi{(\boldsymbol{z_s}|\boldsymbol{s})}} \mathbb{E}_{\boldsymbol{s}' \sim P(\boldsymbol{s}' \mid \boldsymbol{s},\boldsymbol{a})} \mathbb{E}_{\boldsymbol{\hat{s}}' \sim G_\theta(\boldsymbol{\hat{s}}'  \mid \boldsymbol{z_s},\boldsymbol{a})}[\mathcal{C}(\boldsymbol{s}, \boldsymbol{\hat{s}}')] \\
& =\inf _{P \in \mathcal{P}_{\boldsymbol{s}',\boldsymbol{z_s},\boldsymbol{\hat{s}}'}} \mathbb{E}_{\Gamma_\phi{(\boldsymbol{z_s}|\boldsymbol{s})}} \mathbb{E}_{\boldsymbol{s}' \sim P(\boldsymbol{s}' \mid \boldsymbol{s},\boldsymbol{a})}[\mathcal{C}(\boldsymbol{s}', f_{G_\theta}(\boldsymbol{z_s},\boldsymbol{a}))] \\
& =\inf _{P_{\boldsymbol{s}', \boldsymbol{z_s}} \in \mathcal{P}_{\boldsymbol{s}', \boldsymbol{z_s}}} \mathbb{E}_{(\boldsymbol{s}', \boldsymbol{z_s}) \sim P_{\boldsymbol{s}', \boldsymbol{z_s}}}[\mathcal{C}(\boldsymbol{s}', f_{G_\theta}(\boldsymbol{z_s},\boldsymbol{a}))] \\
& = \inf_{\Gamma_\phi(\cdot|\boldsymbol{s})=P_Z}  \mathbb{E}_{\mathbb{P}_{\boldsymbol{s}'}} \mathbb{E}_{\Gamma_\phi(\boldsymbol{z_s} \mid \boldsymbol{s})}[\mathcal{C}(\boldsymbol{s}', f_{G_\theta}(\boldsymbol{z_s},\boldsymbol{a}))].
\end{aligned}
\end{equation}
It remains to notice that $\mathcal{P}_{\boldsymbol{s}', \boldsymbol{z_s}}=\mathcal{P}\left(\boldsymbol{s}' \sim \mathbb{P}(\cdot|\boldsymbol{s},\boldsymbol{a}), \boldsymbol{z_s} \sim P_Z\right)$.
\begin{corollary}\label{coro: random decoder}
With given current state-action pair $(\boldsymbol{s},\boldsymbol{a})$, for $G_\theta$ as defined above with random decoder $G_\theta(\boldsymbol{s}'\mid\boldsymbol{z_s},\boldsymbol{a})$, if the mean value function $f_{G_\theta}(\boldsymbol{z_s},\boldsymbol{a}): \mathcal{Z}\times\mathcal{A} \rightarrow \mathcal{S}$, we sample $\boldsymbol{z_s}$ from $\Gamma_\phi(\boldsymbol{z_s}|\boldsymbol{s})$ and then  
$\boldsymbol{\hat{s}}'$ from $G_\theta(\boldsymbol{z_s},\boldsymbol{a})$. If adopting the squared loss distance $\mathcal{C}(\boldsymbol{s}',\boldsymbol{\hat{s}}')=\|\boldsymbol{s}'-\boldsymbol{\hat{s}}'\|_2^2$ and assuming the variance associated with prior $P_Z$ as $\{\sigma_i^2\}_{i=1}^{\dim(\mathcal{Z})}$, we have that
\begin{equation}
\inf _{P \in \mathcal{P}\left(\boldsymbol{s}' \sim \mathbb{P}, \boldsymbol{\hat{s}}'\sim \mathbb{P}'_{\phi,\theta}\right)} \mathbb{E}_{(\boldsymbol{s}', \boldsymbol{\hat{s}}') \sim P}[\mathcal{C}(\boldsymbol{s}', \boldsymbol{\hat{s}}')]=
\sum_{i=1}^{\dim(\mathcal{Z})}\sigma_i^2+ \inf _{\Gamma_\phi(\cdot|\boldsymbol{s})=P_Z} \mathbb{E}_{\mathbb{P}_{\boldsymbol{s}'}} \mathbb{E}_{\Gamma_\phi(\boldsymbol{z_s} \mid \boldsymbol{s})}[\|\boldsymbol{s}'-f_{G_\theta}(\boldsymbol{z_s},a)\|_2^2].
\end{equation}
\end{corollary}

\textit{Proof:} With squared distance, we can rewrite the \ref{equation: transition transportation loss} as
\begin{equation}
\begin{aligned}
W_\mathcal{C}\left(\mathbb{P}'_{\theta,\phi}, \mathbb{P}\right) & =\inf _{P \in \mathcal{P}_{\boldsymbol{s}',\boldsymbol{z_s},\boldsymbol{\hat{s}}'}}\mathbb{E}_{P(\boldsymbol{s}',\boldsymbol{z_s},\boldsymbol{\hat{s}}'|\boldsymbol{s},\boldsymbol{a}) }[\|\boldsymbol{s}'-\boldsymbol{\hat{s}}'\|_2^2] \\
&= \inf _{P \in \mathcal{P}_{\boldsymbol{s}',\boldsymbol{z_s},\boldsymbol{\hat{s}}'}}\mathbb{E}_{P(\boldsymbol{s}',\boldsymbol{z_s},\boldsymbol{\hat{s}}'|\boldsymbol{s},\boldsymbol{a}) }[\|\boldsymbol{s}'-f_{G_\theta}(\boldsymbol{a},\boldsymbol{z_s})+f_{G_\theta}(\boldsymbol{a},\boldsymbol{z_s})-\boldsymbol{\hat{s}}'\|_2^2]\\
& = \inf _{P \in \mathcal{P}_{\boldsymbol{s}',\boldsymbol{z_s},\boldsymbol{\hat{s}}'}}\mathbb{E}_{P(\boldsymbol{s}',\boldsymbol{z_s},\boldsymbol{\hat{s}}'|\boldsymbol{s},\boldsymbol{a}) }[\|\boldsymbol{s}'-f_{G_\theta}(\boldsymbol{a},\boldsymbol{z_s})\|_2^2+2\left<\boldsymbol{s}'-f_{G_\theta},f_{G_\theta}-\boldsymbol{\hat{s}}'\right>]+\sum_{i=1}^{\dim(\mathcal{Z})}\sigma_i^2\\
& = \sum_{i=1}^{\dim(\mathcal{Z})}\sigma_i^2+ \inf _{\Gamma_\phi(\cdot|\boldsymbol{s})=P_Z} \mathbb{E}_{\mathbb{P}_{\boldsymbol{s}'}} \mathbb{E}_{\Gamma_\phi(\boldsymbol{z_s} \mid \boldsymbol{s})}[\|\boldsymbol{s}'-f_{G_\theta}(\boldsymbol{z_s},a)\|_2^2],
\end{aligned}
\end{equation}
which concludes the proof.
\Halmos
\endproof

Proposition \ref{prop:encode-decode} and Corollary \ref{coro: random decoder} allow us to find the optimal encoder-decoder if the encoder $\Gamma_\phi(\cdot|\boldsymbol{s})$ can map the raw states into a known prior $P_Z$. In order to find a numerical solution, we can relax the constraint $\Gamma_\phi = P_Z$ by adding a penalty term and minimize the loss function:
