\inf_{\theta,\phi} \mathcal{L}_{\theta,\phi}= \inf_{\Gamma_\phi(\cdot|\boldsymbol{s}),f_{G_\theta}}  \mathbb{E}_{\mathbb{P}_{\boldsymbol{s}'}} \mathbb{E}_{\Gamma_\phi(\boldsymbol{z_s} \mid \boldsymbol{s})}[\mathcal{C}(\boldsymbol{s}', f_{G_\theta}(\boldsymbol{z_s},\boldsymbol{a}))] + \lambda \text{Dist} (\Gamma_\phi(\cdot|\boldsymbol{s}),P_Z),
