\subsection{Different Generative Models and Loss Functions}
Well-known generative models include generative adversarial network (GAN), Wasserstein GAN, variational autoencoder, and Wasserstein autoencoder. The encoder parts in all of them can be fitted in our framework as the embedding.
% Using the techniques in \S \ref{sec: optimization approach}, we can derive the loss functions of these auto-encoders. 

\textbf{Wasserstein autoencoder (WAE)} \citep{tolstikhin2018wasserstein} WAE applies the direct adaption on Equation \eqref{eq:relaxed WAE}, which optimizes on the loss function with relaxed the constraints on $\Gamma_\theta(\boldsymbol{z_s}|\boldsymbol{s})$ by adding a penalty to the objective:
\begin{equation}
\mathcal{L}_{\mathrm{WAE}}(\theta,\phi)= \mathbb{E}_{\mathbb{P}_{\boldsymbol{s}'}} \mathbb{E}_{\Gamma_\phi(\boldsymbol{z_s} \mid \boldsymbol{s})}[\mathcal{C}(\boldsymbol{s}', f_{G_\theta}(\boldsymbol{z_s},\boldsymbol{a}))] + \lambda \text{Dist} (\Gamma_\phi(\cdot|\boldsymbol{s}),P_Z).
\end{equation}
Considering using the MMD as the discrepancy metric, we provide a numerical algorithm to minimize the loss function. The algorithm is presented in \ref{alg:WAE}.


\RestyleAlgo{ruled}
\begin{algorithm}[htbp]
  \caption{Training WAE}
  \label{alg:WAE}
  \SetAlgoLined
  \KwIn{Regularization coefficient $\lambda>0$, characteristic kernel $k$, prior $P_Z$, training set $\mathcal{B}$.}
  Initialize encoder $\Gamma_{\phi}$, decoder $G_{\theta}$\;
  \While{$(\phi, \theta)$ not converged}{
    Sample batch $\{(\boldsymbol{s},\boldsymbol{a},\boldsymbol{s^\prime})_i\}_{i=1}^n$ from $\mathcal{B}$\;
    Sample $\{\boldsymbol{z}_1, \ldots, \boldsymbol{z}_n\}$ from $P_Z$\;
    Sample $\{\boldsymbol{\tilde{z}}_i\}_{i=1}^n$ where $\boldsymbol{\tilde{z}}_i \sim \Gamma_{\phi}(\cdot|\boldsymbol{s}_i)$\;
    Compute loss:
    \begin{equation}
    \begin{aligned}
    \mathcal{L} = \frac{1}{n} \sum_{i=1}^n c\left(\boldsymbol{s^\prime_i}, G_{\theta}(\boldsymbol{\tilde{z}_i}, \boldsymbol{a_i})\right) 
    + \frac{\lambda}{n(n-1)} \sum_{\ell \neq j} \left[k(\boldsymbol{z_\ell}, \boldsymbol{z_j}) + k(\boldsymbol{\tilde{z}_\ell}, \boldsymbol{\tilde{z}_j})\right] 
    - \frac{2\lambda}{n^2} \sum_{\ell, j} k(\boldsymbol{z_\ell}, \boldsymbol{\tilde{z}_j})
    \end{aligned}
    \end{equation}
    Update $\Gamma_{\phi}$ and $G_{\theta}$ by backpropagating $\mathcal{L}$\;
  }
\end{algorithm}


\textbf{Generative adversarial network (GAN).} \citep{goodfellow2014generative} With given $(\boldsymbol{s},\boldsymbol{a})$, GAN trys to minimizes the 
\begin{equation}
\mathcal{L}_{\mathrm{GAN}}\left(\phi,\theta\right)=\sup _{T \in \mathcal{T}} \mathbb{E}_{\boldsymbol{s}' \sim \mathbb{P}(\cdot|\boldsymbol{s},\boldsymbol{a})}[\log T(\boldsymbol{s}')]+\mathbb{E}_{z_s' \sim \Gamma_\phi(\boldsymbol{z_s}|\boldsymbol{s})}[\log (1-T(f_{G_\theta}(\boldsymbol{z_s},\boldsymbol{a})))]
\end{equation}
with respect to a deterministic generator $f_{G_\theta}(\boldsymbol{z_s},\boldsymbol{a}): \mathcal{Z}\times\mathcal{A} \rightarrow \mathcal{S}$, where $\mathcal{T}$ is any non-parametric class of choice.

\textbf{Wasserstein GAN (WGAN)} \citep{Martin2017WGAN} The WGAN minimizes 
\begin{equation}\label{WGAN}
\mathcal{L}_{\mathrm{WGAN}}\left(\phi,\theta\right)=\sup _{T \in \mathcal{W}} \mathbb{E}_{\boldsymbol{s}' \sim \mathbb{P}(\cdot|\boldsymbol{s},\boldsymbol{a})}[T(\boldsymbol{s}')]-\mathbb{E}_{z_s' \sim \Gamma_\phi(\boldsymbol{z_s}|\boldsymbol{s})}[ T(f_{G_\theta}(\boldsymbol{z_s},\boldsymbol{a}))],
\end{equation}
where $\mathcal{W}$ is any subset of $1$-Lipschitz functions on $\mathcal{S}$. 

\textbf{Variational autoencoder (VAE)} \citep{Kingma2014AutoEncodingVB} With given $(\boldsymbol{s},\boldsymbol{a})$ tries to minimize the loss $\mathcal{L}_{\mathrm{VAE}}$
\begin{equation}
\mathcal{L}_{\mathrm{VAE}}\left(\phi,\theta\right)=\inf _{\Gamma_\phi(\boldsymbol{z_s} \mid \boldsymbol{s}) \in \Gamma} D_{\mathrm{KL}}\left(\Gamma_\phi(\boldsymbol{z_s} \mid \boldsymbol{s}), P_{Z}\right)-\mathbb{E}_{\Gamma_\phi(\boldsymbol{z_s} \mid \boldsymbol{s})}\left[\log {G}_\theta(\boldsymbol{\hat{s}}' \mid \boldsymbol{z_s},\boldsymbol{a})\right]
\end{equation}
where the $\Gamma$ is a known family of distribution. Here we provide a sample approach to train VAE in Algorithm \ref{alg:VAE}.


\RestyleAlgo{ruled}
\begin{algorithm}[htbp]
    \caption{Training $\beta-$VAE (with $\beta=1$)}
    \label{alg:VAE}
    \SetAlgoLined
     \KwIn{Characteristic positive-definite kernel $k$.
Initialize the parameters of the encoder $\Gamma_{\phi}$, decoder $G_{\theta}$, collected dataset (memory buffer) $\mathcal{D}=\{(\boldsymbol{s},\boldsymbol{a},\boldsymbol{s^\prime})_i\}^N_{i=1}$.}
    \While{$(\phi, \theta)$ not converged}{Sample $\left\{(\boldsymbol{s},\boldsymbol{a},\boldsymbol{s^\prime})_1, \ldots, (\boldsymbol{s},\boldsymbol{a},\boldsymbol{s^\prime})_n\right\}$ from $\mathcal{D}$;\\
      \ForEach{$i=1, \ldots, n$}{
Sample $\boldsymbol{\tilde{z}}_{i}$ from $\Gamma_{\phi}\left(Z \mid \boldsymbol{s_{i}}\right)$; \\
Sample $\boldsymbol{\hat{s}'_{i}}$ from $G_{\theta}\left(\boldsymbol{\tilde{z}}_{i},\boldsymbol{a_i}\right)$; \\
Update $Q_{\phi}$ and $G_{\theta}$ by backward propagating the loss with SGD:
$$\frac{1}{n} \sum_{i=1}^{n} \left\|\boldsymbol{s^\prime_{i}}- \hat{\boldsymbol{s}}'\right\|^2_2+\frac{1}{2} \sum_{j=1}^{\dim(\mathcal{Z})}\left(1+\log \left(\left(\sigma_{j}\right)^{2}\right)-\left(\mu_{j}\right)^{2}-\left(\sigma_{j}\right)^{2}\right),$$
where the  $\sigma_j$ and $\mu_j$ represent the j-th element in $\boldsymbol{\mu}$ and $\boldsymbol{\sigma}$.}}
\end{algorithm}



