\begin{equation}\label{eq: IR bounds}
Q^{U}\left(\boldsymbol{s_{0}}, \boldsymbol{a_{0}}\right) =\mathbf{E}\left[\max_{ \boldsymbol{a} } \left\{\sum _ { t = 0 } ^ { \infty } \left(\gamma^{t} r\left(\boldsymbol{s_{t}}, \boldsymbol{a_{t}}\right)-\varrho_{t}^{\pi_{\varphi}}\left(\boldsymbol{s_{t}}, \boldsymbol{a_{t}}, \boldsymbol{w_{t+1}} \mid \varphi\right)\right)\right\}\right], \label{eq:upper_bound}
\end{equation}
where $\pi_{\varphi}$ is a greedy policy with respect to $\varphi$, i.e., $\pi_{\varphi}(\boldsymbol{s}) = \arg\max_{\boldsymbol{a}} \phi(\boldsymbol{s}, \boldsymbol{a})$. Then, $Q^{U}\left(\boldsymbol{s_{0}}, \boldsymbol{a_{0}}\right) $ is an upper bound of the optimal solution $Q^{*}\left(\boldsymbol{s_{0}}, \boldsymbol{a_{0}}\right)$, i.e.,
