In the remainder of the article, we address the following problems: How to determine a reasonable forest structure for covariate grouping? Given the forest structure, how to identify homogeneous components and estimate coefficient scores? In Section~\ref{s3}, we construct the forest structure based on the grouping path derived from the grouping pursuit problem, and in Section~\ref{filt-fPLS}, we address the second problem by developing a filtrated functional partial least squares approach.

\subsection{Filtrated Functional Partial Least Squares (filt-fPLS)}
\label{filt-fPLS}
To identify the homogeneous components and estimate the coefficient scores, we developed a filtrated functional partial least squares method. 
To facilitate understanding of the proposed filt-fPLS algorithm, we begin with a simple illustrative case. 
In the ordinary grouped model \eqref{grouped_model}, if $X_{1n}(t),\ldots,X_{pn}(t)\in \mathcal{K}_1$ (i.e., all covariates belong to a single group $\mathcal{K}_1$), then we can estimate the model using the classical functional partial least squares approach (see \citet{delaigle2012methodology}), where $\sum_{j\in\mathcal{K}_1}X_{jn}(t)$ is treated as the covariate. The first step is to maximize $\mbox{cov}(y_n,\sum_{j\in\mathcal{K}_1}\langle X_{jn},\psi\rangle)$ over $\psi(t)$, subject to the constraint $\|\psi\|=1$. This is followed by a projection step, and the two steps are then repeated iteratively. In the filtrated grouped model \eqref{filt-group}, however, the grouping structure varies across dimensions. As a result, the maximization and projection steps are iteratively performed under different grouping configurations. The core principle of filt-fPLS is that the extracted homogeneous components should exhibit strong explanatory power for the response variable. We detail the algorithmic procedure below.

%Since the grouping structure varies across dimensions in the filtrated grouped model \eqref{filt-group}, the two steps—maximization and projection—are repeated under different grouping configurations. The core philosophy of filt-fPLS is that the homogeneous components should exhibit strong explanatory power for the response variable. We discuss the algorithm details below. %To achieve this, the method is designed to efficiently capture the association between the response and the covariates using a small number of homogeneous components.

%For simplicity in notation, we assume that the response and covariates are all of mean zero and then omit the intercept. 
%We denote the groups in layer $d$ by $\{\mathcal{K}_{d,i}\colon i=1,\ldots,m_d\}$, where $m_d$ is the total number of groups in the $d$-th layer.  
When $d=1$, we first find the filt-fPLS basis for each group as follows, 
$$\psi_{1,i}(t)\overset{\vartriangle}=\arg\max_{\|\psi\|=1}\mbox{cov}\left\{y_n,\left\langle\sum_{j\in\mathcal{K}_{1,i}}X_{jn},\psi\right\rangle\right\}=\frac{\mbox{cov}\{y_n,\sum_{j\in \mathcal{K}_{1,i}}X_{jn}\}}{\|\mbox{cov}\{y_n,\sum_{j\in \mathcal{K}_{1,i}}X_{jn}\}\|}(t),$$
where $i=1,\ldots,m_1$. 
The $m_1$ first-layer homogeneous components are obtained as $\zeta_{n1}^{(i)}=\sum_{j\in \mathcal{K}_{1,i}}\int X_{jn}\psi_{1,i}$ for $i=1,\ldots,m_1$, and then estimate the associated coefficient scores: %associated with the homogeneous components using the least squares method as follows:
$$\hat{a}_{1,i}=\arg\min_{\{a_{1,i}\colon i=1,\ldots,m_1\}}\mbox{E}\left\{y_n-\sum_{i=1}^{m_1}a_{1,i}\zeta_{n1}^{(i)}\right\}^2.$$
%Equivalently, $\hat{b}_1^{(c_{j,1})}=\hat{a}_{1,i}$, if $j\in\mathcal{K}_{1,i}$. 
For $d\ge2$, given $\{\psi_{d-1,i}(t)\colon i=1,\ldots,m_{d-1}\}$, the filt-fPLS basis for group $\mathcal{K}_{d,i}$ is %obtained as
$$\psi_{d,i}(t)\overset{\vartriangle}=\arg\max_{\|\psi\|=1}\mbox{cov}\left\{y_n^{[d]},\left\langle\sum_{j\in \mathcal{K}_{d,i}}X^{[d]}_{jn},\psi\right\rangle\right\}=\frac{\mbox{cov}\{y_n^{[d]},\sum_{j\in \mathcal{K}_{d,i}}X^{[d]}_{jn}\}}{\|\mbox{cov}\{y_n^{[d]},\sum_{j\in \mathcal{K}_{d,i}}X^{[d]}_{jn}\}\|}(t).$$
Let $\zeta_{nd}^{(i)}=\sum_{j\in \mathcal{K}_{d,i}}\int X^{[d]}_{jn}\psi_{d,i}$, then obtain the associated coefficient scores %in the $d$-th layer 
as follows%using the least squares method
$$\hat{a}_{d,i}=\arg\min\limits_{\{a_{d,i}\colon i=1,\ldots,m_d\}}\mbox{E}\left\{y^{[d]}_n-\sum_{i=1}^{m_d}a_{d,i}\zeta_{nd}^{(i)}\right\}^2,$$
where 
\begin{align*}
X^{[d]}_{jn}(t)&=X^{[d-1]}_{jn}(t)-\sum_{i=1}^{m_{d-1}}\zeta_{n,d-1}^{(i)}\phi_{d-1,i}(t),\\
\phi_{d,i}(t)&= \arg\min_{\{\delta_i(t)\colon i\ge1\}}\mbox{E}\left\|X^{[d]}_{jn}(t)-\sum_{i=1}^{m_{d}}\zeta_{nd}^{(i)}\delta_i(t)\right\|^2,\\
y_n^{[d]}&=y_n^{[d-1]}-\sum_{i=1}^{m_{d-1}}\zeta_{n,d-1}^{(i)}\hat{a}_{d-1,i},
\end{align*}
Particularly $X_{jn}^{[1]}(t)=X_{jn}(t)$, $y_n^{[1]}=y_n$.

It can be shown that under the forest structure, the homogeneous components across different layers are orthogonal (i.e., $\sum_{n\ge1}\zeta_{nd}^{(i)}\zeta_{nd'}^{(i')}=0$ for $d\ne d'$ and $i,i'\ge1$). In practical applications, the unknown covariances and expectations are replaced by their empirical counterparts, as discussed in Algorithm~\ref{al1}.

\begin{algorithm}[ht]
 \caption{Filtrated functional partial least squares algorithm}
  \begin{algorithmic}[1]
     \State {Set $d=1$, $X_{jn}^{[1]}(t)=X_{jn}(t)$, and $y_n^{[1]}=y_n$.}
    \While{\texttt{the ending criterion (discussed in Section \ref{s3.3}) is not met}}
   \State {For $i=1,\ldots,m_d$, estimate $\psi_{d,i}(t)$ by 
$$\hat{\psi}_{d,i}(t)=\sum_{n=1}^N\sum_{j\in \mathcal{K}_{d,i}}y_{n}^{[d]}X_{jn}^{[d]}(t)\bigg/\left\|\sum_{n=1}^N\sum_{j\in \mathcal{K}_{d,i}}y_{n}^{[d]}X_{jn}^{[d]}\right\|.$$}
  \State  {Set $\zeta_{nd}^{(i)}=\sum_{j\in \mathcal{K}_{d,i}}\langle X_{jn}^{[d]},\hat{\psi}_{d,i}\rangle$ and estimate the coefficient scores by least squares
\begin{align*}
\hat{a}_{d,i}&=\arg\min_{\{a_{d,i}\colon i=1,\ldots,m_d\}}\sum_{n=1}^N\left\{y_n^{[d]}-\sum_{i=1}^{m_d}a_{d,i}\zeta_{nd}^{(i)}\right\}^2.
\end{align*}}
   \State  {Obtain the residuals
\begin{align*}
X_{jn}^{[d+1]}(t)&=X_{jn}^{[d]}(t)-\sum_{i=1}^{m_d}\zeta_{nd}^{(i)}\hat{\phi}_{d,i}(t),\\
\hat{\phi}_{d,i}(t)&= \arg\min_{\{\delta(t)\colon i\ge1\}}\sum_{n=1}^N\left\|X_{jn}^{[d]}(t)-\sum_{i=1}^{m_d}\zeta_{nd}^{(i)}\delta_i(t)\right\|^2,\\
y_n^{[d+1]}&=y_n^{[d]}-\sum_{i=1}^{m_d}\hat{a}_{d,i}\zeta_{nd}^{(i)}.
\end{align*}}
\State{$d=d+1$}
\EndWhile
  \end{algorithmic}
  \label{al1}
\end{algorithm}

\section{Forest Structure Construction}
\label{s3}
The construction of the forest structure is based on the grouping path $\mathcal{P}$ derived from the ordinary grouping pursuit problem. Specifically, this involves identifying $\mathcal{K}_1, \ldots,\mathcal{K}_m$ in model \eqref{grouped_model} by solving a regularized optimization problem over a sequence of increasing penalty parameters (see e.g., \citet{shen2010grouping}), and $\mathcal{P}$ encompasses all distinct grouping structures identified across different penalty parameters. Based on the grouping path, we first find a sequence of candidate grouping structures from which the forest structure is constructed.  
For the candidate grouping structures, it is required that the groups in each layer are nested within those of the preceding layer, as any non-nested grouping structures would complicate the construction of the forest structure. One challenge is that the grouping structures along the grouping path may not be nested as $\lambda$ increases, due to the occurrence of group splitting. %To ensure that the selected grouping structures remain nested from the last layer to the first,
Thus, it is crucial to carefully select the candidate grouping structures from the grouping path. %used to construct the forest structure. 

In the following, we discuss the identification of grouping path in Section \ref{s3.1}, the selection of candidate grouping structures in Section \ref{selection}, and the construction of the forest structure in Section \ref{s3.3}.



\subsection{Grouping Path}
\label{s3.1}
The grouping pursuit problem is formulated by optimizing the objective function:
\begin{equation*}
\label{loss}
S(\bm{\beta}(t),\lambda)=\frac{1}{2}\sum_{n=1}^N\left(y_n-\sum_{j=1}^p\langle X_{jn},\beta_j\rangle\right)^2+\sum_{i<j}J_{\lambda}(\|\beta_i-\beta_j\|),
\end{equation*}
where $\bm{\beta}(t)=\{\beta_{j}(t)\colon 1\le j\le p\}$, and $J_{\lambda}(\cdot)$ is some concave penalty, such as the SCAD penalty (see \citet{fan2001variable}) and the MCP (see \citet{zhang2010nearly}). 
As $\lambda$ increases, covariates tend to be clustered into fewer groups, although sometimes grouping splitting may occur. The sequence of grouping structures that emerge as the regularization parameter $\lambda$ increases defines the {\it grouping path} $\mathcal{P}$. 

Suppose that for some orthonormal basis functions $\{\nu_d(t)\colon d\ge1\}$, the following basis representations hold: $X_{jn}(t)=\sum_{d\ge1}\xi_{jn,d}\nu_d(t)$ and $\beta_j(t)=\sum_{d\ge1}b_{jd}\nu_d(t)$. 
%We first discuss how to solve \eqref{loss} and discuss how to select the forest structure based on the grouping path in Section \ref{selection} and \ref{s3.3}.
Since $S(\bm{\beta}(t),\lambda)$ involves elements of infinite dimensions, we minimize the following truncated version over $\{b_{jd}\colon d=1,\ldots,D,\ j\ge1\}$ with some sufficiently large $D\ge1$, %to obtain the estimates $\{\hat{b}_{jd}\colon d=1,\ldots,D,\ j\ge1\}$:
\begin{equation}
\label{trun-obj}
S_D(\bm{\beta}(t),\lambda)=\frac{1}{2}\sum_{n=1}^N\left(y_n-\sum_{j=1}^p\bm{\xi}^{\top}_{jn}\bm{B}_{j}\right)^2+\sum\limits_{i<j}J_\lambda(\|\bm{M}_{ij}\|),
\end{equation}
where $\bm{\xi}_{jn}=(\xi_{jn,1},\ldots,\xi_{jn,D})^{\top}$, $\bm{B}_j=(b_{j1},\ldots,b_{jD})^{\top}$ and $\bm{M}_{ij}=\bm{B}_i-\bm{B}_j$. We use the ADMM algorithm to solve \eqref{trun-obj}. Let $\bm{B}=\{\bm{B}_j\colon j=1,\ldots,p\}$, $\bm{M}=\{\bm{M}_{ij}\colon i<j\}$, and
$$H_1(\bm{B})=\frac{1}{2}\sum_{n=1}^N\left(y_n-\sum_{j=1}^p\bm{\xi}^{\top}_{jn}\bm{B}_{j}\right)^2,\qquad H_2(\bm{M})=\sum_{i<j}J_{\lambda}(\|\bm{M}_{ij}\|),$$
%, and $\bm{M}=\{\bm{M}_{ij}\colon 1\le i<j\le p\}$, 
then the unconstrained optimization problem is equivalent to the following constrained optimization problem
\begin{align}
\label{loss2}
&H(\bm{B},\bm{M})=H_1(\bm{B})+H_2(\bm{M}),\ \mbox{subject to}\ \bm{M}_{ij}=\bm{B}_i-\bm{B}_j,\ 1\le i<j\le p.
\end{align}
%Notationally, let $F(\bm{B},\bm{M})=\bm{0}$ comprises all the constraints in \eqref{loss2}.
By the ADMM algorithm, the regularized estimates of $\bm{B},\bm{M}$ can be obtained by minimizing the augmented Lagrangian function
\begin{align*}
L_{\theta}(\bm{B},\bm{M},\bm{u})&=H(\bm{B},\bm{M})+\sum_{i<j}\bm{u}^{\top}_{ij}(\bm{B}_i-\bm{B}_j-\bm{M}_{ij})+\frac{\theta}{2}\sum_{i<j}\|\bm{B}_i-\bm{B}_j-\bm{M}_{ij}\|^2
\end{align*}
over $\bm{B}$ and $\bm{M}$. Given $\bm{B}$ and multipliers $\bm{u}=\{u_{ij,dd'},i<j,d<d'\}$, we update $\bm{M}$ by minimizing $L_{\theta}(\bm{B},\bm{M},\bm{u})$ over $\bm{M}$, and the optimization problem is equivalent to minimizing the following function over $\bm{M}$,
\begin{equation}
\label{M}
\frac{\theta}{2}\sum_{i<j}\|\bm{M}_{ij}-(\bm{B}_i-\bm{B}_j)-\theta^{-1}\bm{u}_{ij}\|^2+\sum_{i<j}J_{\lambda}(\|\bm{M}_{ij}\|).
\end{equation}
%for $i<j$. %Let $\bm{a}_{ij}=(\bm{B}_i-\bm{B}_j)+\theta^{-1}\bm{u}_{ij}$. 
