%\frac{\bm{a}_{ij}\left(1-\frac{\lambda}{\theta\|\bm{a}_{ij}\|}\right)_+}{1-\frac{1}{\gamma\theta}},& &\mbox{if }\|\bm{a}_{ij}\|\le\gamma\lambda.\\
%\bm{a}_{ij},& &\mbox{if }\|\bm{a}_{ij}\|>\gamma\lambda.
%\end{array}
%\right.
%\end{equation}
%For the SCAD penalty, the solution is
