%\frac{\bm{a}_{ij}\left(1-\frac{\gamma\lambda}{\theta(\gamma-1)\|\bm{a}_{ij}\|}\right)_+}{1-\frac{1}{\theta(\gamma-1)}},& &\mbox{if }\lambda\left(1+\frac{1}{\theta}\right)<\|\bm{a}_{ij}\|\le\gamma\lambda.\\
%\bm{a}_{ij},& &\mbox{if }\|\bm{a}_{ij}\|>\gamma\lambda.
