For $j=1,\ldots,p$, define
$\bm{\Xi}_j=\left(\bm{\xi}_{1j},\ldots,\bm{\xi}_{N}\right)^{\top}$, $\bm{\Xi}=(\bm{\Xi}_1|\ldots|\bm{\Xi}_p)$. %The augmented Lagrangian function is 
%\begin{align*}
%L_{D,\theta}(\bm{B},\bm{M},\bm{u})&=\frac{1}{2}\|\bm{y}-\bm{\Xi}\bm{B}\|^2+\bm{u}^{\top}F(\bm{M},\bm{B})+\frac{\theta}{2}\|F(\bm{M},\bm{B})\|^2\\
%&=\frac{1}{2}\|\bm{y}-\bm{\Xi}\bm{B}\|^2+\frac{\theta}{2}\|\bm{\Delta}\bm{B}-\bm{M}+\theta^{-1}\bm{u}\|^2+\mbox{const.}
%\end{align*}
The minimizer of $\bm{B}$ given $\bm{M}$ and $\bm{u}$ of the augmented Lagrangian function is
\begin{equation}
\label{B}
\bm{B}=(\bm{\Xi}^{\top}\bm{\Xi}+\theta\bm{\Delta}^{\top}\bm{\Delta})^{-1}(\bm{\Xi}^{\top}\bm{y}+\theta\bm{\Delta}^{\top}(\bm{M}-\theta^{-1}\bm{u})).
\end{equation}
Here, $\bm{\Delta}=(\bm{\Delta}_{ij},i<j)$ represents the matrix formed by concatenating the row blocks $\bm{\Delta}_{ij}$, and $\bm{\Delta}_{ij}=(\cdots\bm{0},\bm{I},\bm{0},\cdots,\bm{0},-\bm{I},\bm{0}\cdots)$ is a $d\times pd$ matrix where $\bm{I}$ is the $d\times d$ identity matrix. We summarize the above discussion in Algorithm \ref{al2}. 
\begin{algorithm}[ht]
 \caption{The ADMM algorithm for grouping pursuit}
  \begin{algorithmic}[1]
   \State {Initialize estimates $\bm{B}^{(0)}$ (e.g., {ordinary least squares estimate of $\bm{B}$}) and set $\bm{u}^{(0)}=\bm{0}$.}
  \While{{convergence criterion is not met}}
  \State  {Given $\bm{B}^{(m)}$ and $\bm{u}^{(m)}$, calculate $\bm{M}^{(m+1)}$ by minimizing \eqref{M} over $\bm{M}$.}%using \eqref{MCP} and \eqref{SCAD}.}
   \State  {Given $\bm{M}^{(m+1)}$ and $\bm{u}^{(m)}$, calculate $\bm{B}^{(m+1)}$ using \eqref{B}.}
   \State {Update the multipliers $u^{(m+1)}_{ij,dd'}=u^{(m)}_{ij,dd'}+\theta\{b^{(m+1)}_{id}-b^{(m+1)}_{jd}-M^{(m+1)}_{ij,d}\}$.}
  \EndWhile
  \State \Return {$\bm{B}^{(m+1)}$.}
  \end{algorithmic}
  \label{al2}
\end{algorithm}

