	\centering
	\includegraphics[width=9 cm]{figure1.pdf}
	\caption{ \textbf{Time courses of the cancer cell concentration $T(t)$ with different values of $a$.}  Here, we set $(s_e, s_n)=(1.5, 4)$, and the other parameter values are the same as those in Table \ref{tab:table1}. }
	\label{fig:fig0}
\end{figure}

Similar to Theorems \ref{thm2.a}, \ref{thm2.b}, and \ref{thm2.2}, we explore the dynamics of the model equation \eqref{eq:model_1} when there are no effector T cells $(s_e = 0)$ or no naive T cells $(s_n = 0)$. 

\begin{theorem}
\label{thm2.aaa}
Considering the equation \eqref{eq:model_1}, we have the following conclusions:
\begin{enumerate}
\item[\rm{(i)}] If $s_e = s_n = 0$, the equation \eqref{eq:model_1} has two equilibria $(0, 0, 0)$ and $(\dfrac{1}{b}, 0, 0)$. Furthermore, the steady state $(0, 0, 0)$ is a locally unstable saddle point, while the state $(\dfrac{1}{b}, 0, 0)$ is globally asymptotically stable within the domain $\Omega$.
\item[\rm{(ii)}] If $s_e =0$ and $s_n > 0$, the equation \eqref{eq:model_1} has a locally unstable tumor-free equilibrium at $(0, 0, \dfrac{s_n}{d_n})$, along with at least one positive equilibrium.
\item[\rm{(iii)}] If $s_e >0$ and $s_n = 0$, the system \eqref{eq:model_1} has a tumor-free equilibrium at $(0, \dfrac{s_e}{d_e}, 0)$. If $a>\dfrac{\gamma_c s_e}{d_e}$, there exists at least one equilibrium of type $(T^*, E^*, 0)$ where $T^*, E^* > 0$. Conversely, if $a < \dfrac{\gamma_c s_e}{d_e}$, the tumor-free equilibrium is locally asymptotically stable, whereas if $a > \dfrac{\gamma_c s_e}{d_e}$, the tumor-free equilibrium becmes unstable.
\end{enumerate}
\end{theorem}

\begin{proof} We only give the proof for the globally asymptotically stable equilibrium $(\dfrac{1}{b}, 0, 0)$ in part \rm{(i)}. The other parts can be proved analogously to Theorems \ref{thm2.a}, \ref{thm2.b}, and \ref{thm2.2}. 

To prove (i), it is sufficient to verify the global attractiveness and the local stability of the equilibrium $(\dfrac{1}{b}, 0, 0)$.

When $s_e = s_n = 0$, equation \eqref{eq:model_1} can be written as
\begin{equation}
\label{eq:model_1_n}
\left\{
\begin{aligned}
\dfrac{{\rm d} T}{{\rm d} t}& =  a T ( 1 - b T) - \gamma_c E T,\\
\dfrac{{\rm d} E}{{\rm d} t}& =  - d_e E + \alpha_n k_n N \Big(  \dfrac{T}{ T + g } \Big)  - \gamma_e E T,   \\
\dfrac{{\rm d} N}{{\rm d} t}& =  - d_n N - k_n N \Big(  \dfrac{T}{ T + g } \Big).
\end{aligned}
\right.
\end{equation} 
The Jacobian matrix around the equilibrium $(\dfrac{1}{b}, 0, 0)$ is given by
\begin{equation}
\label{eq:j2}
J_1 = \left( 
\begin{array}{ccc}
-a    & - \dfrac{\gamma_c}{b}   & 0 \\
0  &  -d_e - \dfrac{\gamma_e}{b} ~~ & \dfrac{ \alpha_n k_n }{ 1 + b g } \\
0 & 0  &  -d_n - \dfrac{ k_n  }{ 1 + b g } 
\end{array}
\right).
\end{equation}
The three eigenvalues of the matrix $J_1$ are $-a$, $-d_e - \dfrac{\gamma_e}{b}$, and $-d_n - \dfrac{ k_n  }{ 1 + b g }$. Hence, the equilibrium $(\dfrac{1}{b}, 0, 0)$ is asymptotically stable.

Next, we verify the global attractiveness. From the third equation of \eqref{eq:model_1_n} and $d_n > 0$, there exists a finite time $t_3 >0$ such that
\begin{equation}
\label{eq:model_1_n_1}
N(t) < \dfrac{\epsilon}{ \alpha_n k_n }
\end{equation} 
for any $\epsilon >0$ and $t \geq t_3$. Thus, from the second equation of \eqref{eq:model_1_n}, 
\begin{equation}
\label{eq:model_1_n_2}
	\dfrac{{\rm d} E}{{\rm d} t} < - d_e E + \epsilon \Big(  \dfrac{T}{ T + g } \Big) - \gamma_e E T < - d_e E + \epsilon,
	\end{equation} 
	we have
	\begin{equation}
	\limsup_{\substack t \rightarrow \infty} E(t) \leq \dfrac{\epsilon}{d_e}.
	\end{equation}
	Hence, for any $\epsilon_1 > 0$, there exists $t_4 \geq t_3$ such that
	\begin{equation}
	\label{eq:model_1_n_3}
	E(t) < \dfrac{\epsilon + \epsilon_1}{ d_e }
	\end{equation} 
	for any $t \geq t_4$. Since $\epsilon >0$ and $\epsilon_1 >0$ are sufficiently small, we can choose $\epsilon$ and $\epsilon_1 $ such that $\gamma_c (\epsilon + \epsilon_1  ) < d_e$, namely, $\dfrac{\gamma_c (\epsilon + \epsilon_1  )  }{ d_e}< 1$. Hence, 
	\begin{equation}
	\label{eq:model_1_n_4}
	\dfrac{{\rm d} T}{{\rm d} t} \geq a T( 1 -bT) - \dfrac{\gamma_c (\epsilon + \epsilon_1  )  }{ d_e} T = aT \Big(  1- \dfrac{\gamma_c (\epsilon + \epsilon_1  )  }{ d_e} - bT \Big).
	\end{equation} 
	Applying the comparison principle, we have
	\begin{equation}
	\liminf_{\substack t \rightarrow \infty} T(t) \geq \dfrac{1}{b} \Big(  1- \dfrac{\gamma_c (\epsilon + \epsilon_1  )  }{ d_e} \Big).
	\end{equation}
	Since both $\epsilon >0$ and $\epsilon_1 >0$ are sufficiently small, we have
	\begin{equation}
	\liminf_{\substack t \rightarrow \infty} T(t) \geq \dfrac{1}{b}.
	\end{equation}
	From \eqref{eq:T_ub}, we have $T(t) \rightarrow \dfrac{1}{b}$ as $t \rightarrow \infty$. Hence, $(\dfrac{1}{b}, 0, 0)$ is globally attractive in $\Omega$.
\end{proof}

\begin{remark}
\label{rem:2}
From Theorem \ref{thm2.aaa} (i), any trajectory with initial conditions $T(0) > 0$, $E(0) >0$, and $N(0) > 0$ will move towards a state with cancer cells when there is no immune cell injection, i.e., $s_e = s_n = 0$. 
\end{remark}

From Theorem \ref{thm2.2}, if $a < \dfrac{ \gamma_c s_e}{d_e + \gamma_e/b}$, the cancer cell population will approach zero as time progresses. However, the time to achieve a given positive threshold is interesting in estimating the process of cancer evolution. This issue is discussed below.

\subsection{The first time the cancer cell population reaches a given level}
Here, we investigate the time at which the concentration of cancer cells reaches a specified level, given the initial conditions $T(0)=x$, $E(0)=y$, and $N(0)=z$. We define $\tau$ as the first time $T(t)$ equals a given positive value $\epsilon$. Namely, 
\begin{equation}
\label{eq:ft_1}
\tau( x, y, z) := \inf \{ t>0 \mid T(t)=\epsilon \}
\end{equation}
for $x, y, z \geq 0$. Here, $T(t)$, $E(t)$, and $N(t)$ represent the solutions of equation \eqref{eq:model_1} with the initial condition \\ $(T(0), E(0), N(0)) = (x, y, z)$. We may also write the solutions as $T(t, x, y, z)$, $E(t, x, y, z)$, and $N(t, x, y, z)$ in order to specify the initial conditions.

\begin{theorem}
\label{thm2.first}
Consider the equation \eqref{eq:model_1}, let $T(t)$, $E(t)$, and $N(t)$ be the solution of \eqref{eq:model_1} with initial condition $(T(0), E(0), N(0))=(x, y, z)$. If $a < \dfrac{\gamma_c s_e}{d_e + \gamma_e/b}$, for any $\epsilon \in (0, x)$, the function $\tau$ defined in \eqref{eq:ft_1} satisfies the following properties:
\begin{enumerate}
\item[\rm{(i)}] $\tau$ is continuous on $[\epsilon, +\infty) \times [\dfrac{s_e}{d_e + \gamma_e/b}, +\infty) \times [0, +\infty)$ and is smooth in $\Omega_1 = (\epsilon, +\infty) \times (\dfrac{s_e}{d_e + \gamma_e/b}, +\infty) \times (0, +\infty)$.
\item[\rm{(ii)}] $\tau$ satisfies the following partial differential equation:
\begin{equation}
\label{eq:ft_2}
\left\{
\begin{aligned}
&f_1(x, y, z ) \partial_{x} \tau + f_2(x, y, z ) \partial_{y} \tau + f_3(x, y, z )\partial_{z} \tau =  1, \quad (x, y, z ) \in \Omega_1, \\
&\tau(\epsilon, y, z ) =  0,   \quad ( y, z ) \in  [ \dfrac{s_e}{d_e + \gamma_e/b}, +\infty) \times [0, +\infty),
\end{aligned}
\right.
\end{equation}
where 
\begin{eqnarray*}
f_1(x, y, z ) &=& a x ( 1 - b x) - \gamma_c x y,\\
f_2(x, y, z ) &=& s_e - d_e y +
\alpha_n k_n z \Big(  \dfrac{x}{ x + g } \Big)  - \gamma_e x y,\\
f_3(x, y, z ) &=& s_n - d_n z - k_n z \Big(  \dfrac{x}{ x + g } \Big).
\end{eqnarray*}
\end{enumerate}
\end{theorem}

\begin{proof} The proof below follows the idea of Theorem 1.1 in Hynd et al. \citep{Hynd2022}.

(i). For a given $\epsilon > 0$, Theorem \ref{thm2.2} implies that there exists a finite time $t_5$ such that cancer cell concentration reaches $\epsilon$ at $t = t_5$, i.e., 
\begin{equation}
\label{eq:ft_3}
	T(t_5)=\epsilon.
\end{equation}

Let $(x^k, y^k, z^k)$ be a sequence so that $(x^k, y^k, z^k ) \rightarrow (x, y, z)$ as $k \rightarrow \infty$ and $x ^k \geq \epsilon$, $y ^k \geq \dfrac{s_e}{ d_e + \gamma_e/b}$, $z ^k \geq 0$. There exists a subsequence $\tau(x^{k_j}, y^{k_j}, z^{k_j})$ such that 
\begin{equation}
\label{eq:ft_4}
\tau_1= \liminf_{\substack k \rightarrow \infty} \tau(x^k, y^k, z^k ) =\lim_{\substack j \rightarrow \infty} \tau(x^{k_j}, y^{k_j}, z^{k_j}).
\end{equation}
From the definition of $\epsilon$,
\begin{equation}
\label{eq:ft_5}
T( \tau(x^k, y^k, z^k ),x^k, y^k, z^k )  =\epsilon 
\end{equation}
for any $k \in \mathbb{N}$. Because of the continuity of $T$, we have
\begin{equation}
\label{eq:ft_6}
T( \tau_1, x, y, z ) =\epsilon.
\end{equation}
For any $(x, y, z) \in [\epsilon, +\infty) \times [\dfrac{s_e}{d_e + \gamma_e/b}, +\infty) \times [0, +\infty)$, we have $x \geq \epsilon$. Hence,
\begin{equation}
\label{eq:ft_7}
\tau(x, y, z) \leq \tau_1 =\liminf_{\substack k \rightarrow \infty} \tau(x^k, y^k, z^k ) .
\end{equation}
There also exists another subsequence $\tau(x^{k_l}, y^{k_l}, z^{k_l} )$ such that 
\begin{equation}
\label{eq:ft_8}
\tau_2= \limsup_{\substack k \rightarrow \infty} \tau(x^k, y^k, z^k ) =\lim_{\substack l \rightarrow \infty} \tau(x^{k_l}, y^{k_l}, z^{k_l}).
\end{equation}
Since $y \geq \dfrac{s_e}{ d_e + \gamma_e/b}$, it follows from \eqref{eq:E0_low} that 
\begin{equation}
\label{eq:ft_9}
E(t) \geq \dfrac{s_e}{ d_e + \gamma_e/b}
\end{equation}
for all $t \geq 0$, which yields 
\begin{equation}
\label{eq:ft_10}
\dfrac{{\rm d} T }{{\rm d} t} <0
\end{equation}
for $0 \leq t \leq \tau_2$ and $x \geq \epsilon$. Thus 
\begin{equation}
\label{eq:ft_120}
\tau(x, y, z) = \tau_2 = \limsup_{\substack k \rightarrow \infty} \tau(x^k, y^k, z^k ).
\end{equation}
Therefore, \eqref{eq:ft_7} and \eqref{eq:ft_120} together give
\begin{equation}
\label{eq:ft_11}
\tau = \lim_{\substack k \rightarrow \infty} \tau(x^k, y^k, z^k ).
\end{equation}
Thus, $\tau$ is continuous on $[\epsilon, +\infty) \times [\dfrac{s_e}{d_e + \gamma_e/b}, +\infty) \times [0, +\infty)$. 

Let $x>\epsilon$, $y>\dfrac{s_e}{ d_e + \gamma_e/b}$, and $z>0$. From \eqref{eq:E0_low}, we have $E(t)>\dfrac{s_e}{ d_e + \gamma_e/b}$ for $\forall t \geq 0$. In addition, it follows from \eqref{eq:cancer_1} that $E(t)>0$ for $\forall t \geq 0$. Thus, noticing that $T(\tau, x, y, z) = \epsilon$, from the first equation of \eqref{eq:model_1}, and $a < \dfrac{\gamma_c s_e}{ d_e + \gamma_e/b} $, we have
\begin{equation}
\label{eq:thm_fta}
\dfrac{ {\rm d} T(\tau, x, y, z) }{ {\rm d} t} < ( a- \gamma_c E) T < \Big(  \dfrac{\gamma_c s_e}{ d_e + \gamma_e/b} - \dfrac{ \gamma_c s_e}{d_e + \gamma_e/b}  \Big) T =0.
\end{equation}
Since $T$ is smooth in a neighborhood of $( \tau, x, y, z)$, the implicit function theorem implies that $\tau$ is smooth in a neighborhood of $( x, y, z)$. Thus, $\tau$ is smooth in $\Omega_1$.

(ii).  We denote $T(t), E(t), N(t)$ as the solutions of system \eqref{eq:model_1} with initial conditions $T(0)=x> \epsilon$, $E(0)=y > \dfrac{s_e}{d_e + \gamma_e/b}$, and $N(0)=z>0$. For any $t \in ( 0, \tau(x, y, z ) )$, since the equation \eqref{eq:model_1} is an autonomous system, it is easy to obtain
\begin{equation}
\label{eq:ft_12}
\begin{aligned}
\tau(T(t), E(t), N(t) ) & = \inf\{ \tau_1 >0 \mid T(t+\tau_1)= \epsilon\} \\
& = \inf\{ \tau_1 >0 \mid T(t+\tau_1)= \epsilon ~  \mathrm{and} ~ \tau_1 > 0 \} \\
& = \inf\{ s-t \mid T(s)= \epsilon ~ \mathrm{and} ~ s > t \} \\
& = \inf\{ s \mid T(s)= \epsilon ~ \mathrm{and} ~ s > t \} - t \\
& = \inf\{ s  > t\mid T(s)= \epsilon \} - t \\
& = \tau(x, y, z) - t .
\end{aligned}
\end{equation}
Thus, we have
\begin{equation}
\label{eq:ft_13}
\begin{aligned}
\dfrac{ \tau(T(t), E(t), N(t) ) - \tau(x, y, z )}{t} = - 1 .
\end{aligned}
\end{equation}
Letting $t \rightarrow 0$, we have
\begin{equation}
\label{eq:ft_14}
\begin{aligned}
-1 &= \dfrac{{\rm d} }{{\rm d} t}  \tau(T(t), E(t), N(t) ) \Big\vert_{t=0}  \\
& = [ f_1(T, E, N ) \partial_{T} \tau + f_2(T, E, N) \partial_{E} \tau + f_3(T, E, N )\partial_{N} \tau ]\Big\vert_{t=0}  \\
& = f_1(x, y, z) \partial_{x} \tau + f_2(x, y, z) \partial_{y} \tau + f_3(x, y, z)\partial_{z} \tau.
\end{aligned}
\end{equation}

We show that $\tau(x, y, z)$ satisfies the boundary condition of equation \eqref{eq:ft_2}. Suppose that a function $\tau_*(x, y, z)$ satisfies \eqref{eq:ft_2}. Then, for $ 0< t< \tau(x, y, z ) $, we have
\begin{equation}
\label{eq:ft_15}
\begin{aligned}
 \dfrac{{\rm d} }{{\rm d} t}  \tau_*(T(t), E(t), N(t) ) =  f_1(T, E, N ) \partial_{T} \tau_* + f_2(T, E, N) \partial_{E} \tau_* + f_3(T, E, N )\partial_{N} \tau_*  =-1.
\end{aligned}
\end{equation}
Integrating both sides of equation \eqref{eq:ft_15} from $ t =0$ to $t = \tau(x, y, z ) $, we obtain
\begin{equation}
\label{eq:ft_16}
\tau_*( T(\tau(x, y, z ) ), E(\tau(x, y, z ) ) , N(\tau(x, y, z ) )  ) - \tau_*(x, y, z )  =  -\tau(x, y, z ) .
\end{equation}
Since  $T(\tau(x, y, z ) ) = \epsilon$, $E(\tau(x, y, z ) ) \geq \dfrac{s_e}{d_e + \gamma_e/b}$, and $\tau_*( \epsilon, E(\tau(x, y, z) ) , N(\tau(x, y, z ) )  ) =0$, $\tau_*(x, y, z ) = \tau(x, y, z ) $. This proves the theorem.
\end{proof}

From the proof, the equation \eqref{eq:ft_2} has a unique solution, which gives the function $\tau(x, y, z)$. According to the theory of the first-order partial differential equation (PDE), if we can find three independent prime integrals of the characteristic equation of the PDE \eqref{eq:ft_2}, i.e., the following equation:
\begin{equation}
\label{eq:ft_aa}
\begin{aligned}
\dfrac{ {\rm d} x }{  f_1(x, y, z) } = \dfrac{ {\rm d} y }{ f_2(x, y, z) } = \dfrac{ {\rm d} z }{ f_3(x, y, z) } = \dfrac{ {\rm d} \tau }{  1 },
\end{aligned}
\end{equation}
we can then obtain the solution of \eqref{eq:ft_2}. Unfortunately, since the coefficients of the PDE \eqref{eq:ft_2} are coupled and complex, it is not easy to obtain the expression of the solution for \eqref{eq:ft_2}. This study investigates the numerical approximation of $\tau$ in the section \ref{sec:sec1}.

\begin{remark}
\label{rem:3}
Theorem \ref{thm2.first} shows the first time at which the concentration of cancer cells $T$ reaches a given threshold. This result is significant for clinical applications for predicting the critical time point $\tau$, and the cancer cell concentration will remain at a low level when $t > \tau$.
\end{remark}

Furthermore, the following theorem gives an upper bound on the time point $\tau$.
\begin{theorem}
\label{thm2c}
If $a < \dfrac{\gamma_c s_e}{d_e + \gamma_e/b}$, for any $x \geq \epsilon > 0$, $y \geq \dfrac{s_e}{d_e + \gamma_e/b}$ and $z \geq 0$, we have
\begin{equation}
\label{eq:ft_17}
\begin{aligned}
\tau(x, y, z ) \leq \dfrac{ \ln \dfrac{x}{\epsilon} } {\dfrac{\gamma_c s_e}{d_e + \gamma_e/b} -a + a b \epsilon }.
\end{aligned}
\end{equation}
\end{theorem}
\begin{proof} Let $(T(t), E(t), N(t))$ be the solution of equation \eqref{eq:model_1} with initial value $(x, y, z)$. From the first equation of \eqref{eq:model_1}, we have
$$
T(t) = x {\mathrm e}^{ \int_{ 0}^{t} \big( a ( 1- bT(s)) - \gamma_c E(s)  \big) {\rm d} s},
$$
which gives
\begin{equation*}
\epsilon = x {\mathrm e}^{ \int_{ 0}^{\tau(x,y,z)} \big( a ( 1- bT(s)) - \gamma_c E(s)  \big) {\rm d} s}.
\end{equation*}
We then have
\begin{equation}
\label{eq:ft_18}
\int_{ 0}^{\tau(x,y,z)} \big( \gamma_c E(s) -a + a bT(s)  \big) {\rm d} s = \ln \dfrac{x}{\epsilon}.
\end{equation}
From \eqref{eq:ft_9} and \eqref{eq:ft_18}, 
\begin{equation}
\label{eq:ft_19}
\int_{ 0}^{\tau(x,y,z)} \left( \dfrac{\gamma_c s_e}{d_e + \gamma_e/b} -a + a bT(s) \right) {\rm d} s \leq \ln \dfrac{x}{\epsilon}.
\end{equation}
Noting that $T(s) \geq \epsilon$ for $0 \leq s \leq \tau(x,y,z)$, we obtain
\begin{equation}
\label{eq:ft_20}
\int_{ 0}^{\tau(x,y,z)} \left( \dfrac{\gamma_c s_e}{d_e + \gamma_e/b} -a + a b \epsilon  \right) {\rm d} s \leq \int_{ 0}^{\tau(x,y,z)} \left( \dfrac{\gamma_c s_e}{d_e + \gamma_e/b} -a + a bT(s)  \right) {\rm d} s \leq \ln \dfrac{x}{\epsilon}.
\end{equation}
Since $a < \dfrac{\gamma_c s_e}{d_e + \gamma_e/b}$ and $\dfrac{\gamma_c s_e}{d_e + \gamma_e/b} -a + a b \epsilon > 0$, it follows from \eqref{eq:ft_20} that 
\begin{equation*}
\tau(x,y,z) \Big( \dfrac{\gamma_c s_e}{d_e + \gamma_e/b} -a + a b \epsilon  \Big)  \leq  \ln \dfrac{x}{\epsilon},
\end{equation*}
which implies \eqref{eq:ft_17}. The proof is complete.
\end{proof} 

\subsection{Numetical analysis}
\subsubsection{Method}
In this section, we perform numerical simulations to further explore the stability of the steady states. Unless otherwise specified, the default parameter values used in the simulations are listed in Table \ref{tab:table1}. Additionally, based on equations \eqref{eq:ps_1}, \eqref{eq:ps_2}, and \eqref{eq:ps_4}, the values of $E^*$ and $N^*$ for each equilibrium $(T^*, E^*, N^*)$ of equation \eqref{eq:model_1} can be uniquely determined by the value of $T^*$. Therefore, in the discussions that follow, we present the two-dimensional phase portraits in the $(T, E)$-plane rather than the three-dimensional $(T, E, N)$-space. 


