\begin{lema}Let $L \geqslant 2$ and $o$ an element in $\overline{\mathbb{L}}$, satisfying $[n^{2}] \leqslant  o \leqslant \sup \mathbb{P}$, there exists a homeomorphism $B_{L,o}: \mathbb{H}^{2} \rightarrow \mathbb{H}^{2}$ and an ideal closed polygon $\Gamma$ with $L$ sides, satisfying:

\begin{enumerate}
    \item If $\hat{B}_{L,o}: \hat{\mathbb{H}}^{2} \rightarrow \hat{\mathbb{H}}^{2}$ is the extension of $B_{L,o}$ to the one-point compactification of $\mathbb{H}^{2}$, then $o(\hat{B}_{L,o}) = o(\hat{B}_{L,o}, \overline{\Gamma}) = o$.
    \item $\Omega(\hat{B}_{L,o}) = \{\infty\}$, where $\{\infty\} =\hat{\mathbb{H}}^{2} - \mathbb{H}^{2}$.
    \item $\Gamma$ and each $\Gamma_{i}$ are invariant sets, where $\Gamma_{1},\dots, \Gamma_{L}$ are the closure of the connected components of $\mathbb{H}^{2} - \Gamma$ in $\mathbb{H}^{2}$.
    \item For each $i \in \{1,\dots,L\}$, the map $B_{L,o}|_{\Gamma_{i}}$ is a translation, and all directions of translations are oriented counter-clockwise.
    \item There exists an invariant closed set $C \subseteq \Gamma$ by the map  $B_{L,o}$, with closure $\overline{C}$ in $\hat{\mathbb{H}}^{2}$ such that $\overline{C}$ does not intersect the sides of $\Gamma$ and $o(\hat{B}_{L,o}|_{\overline{C}}) = o$.
