    \underset{k=k_n^*}{\rm Res\ }\mu^{(2)}(\zeta,t;k)&=\lim_{k\to k_n^*}\mu^{(2)}(\zeta,t;k)\begin{pmatrix}
    \mathbf{0}_{2\times2} & -[\delta_{2}^{-1}(k_n)C_n\delta_{1}^{-1}(k_n)]^\dag T^{2}(k_n^*)\e^{-2\ii t\theta} \\
    \mathbf{0}_{2\times2} & \mathbf{0}_{2\times2}
    \end{pmatrix},\label{3.44}\\
    \underset{k=-k_n}{\rm Res\ }\mu^{(2)}(\zeta,t;k)&=\lim_{k\to -k_n}\mu^{(2)}(\zeta,t;k)\begin{pmatrix}
    \mathbf{0}_{2\times2} & \sigma_2[\delta_{2}^{-1}(k_n)C_n\delta_{1}^{-1}(k_n)]^{\texttt{T}}\sigma_2T^{2}(-k_n)\e^{-2\ii t\theta} \\
    \mathbf{0}_{2\times2} & \mathbf{0}_{2\times2}
    \end{pmatrix}.\label{3.45}
    \end{align}

    For $n\in\Delta_{k_0}^-$,
    \begin{align}
    \underset{k=k_n}{\rm Res\ }\mu^{(2)}(\zeta,t;k)&=\lim_{k\to k_n}\mu^{(2)}(\zeta,t;k)\begin{pmatrix}
    \mathbf{0}_{2\times2} &  \delta_1(k_n)C_n^{-1}\delta_2(k_n)
(1/T)'(k_n)^{-2}\e^{-2\ii t\theta}\\
    \mathbf{0}_{2\times2}& \mathbf{0}_{2\times2}
    \end{pmatrix},\label{3.46}\\
    \underset{k=-k_n^*}{\rm Res\ }\mu^{(2)}(\zeta,t;k)&=\lim_{k\to -k^*_n}\mu^{(2)}(\zeta,t;k)\begin{pmatrix}
    \mathbf{0}_{2\times2} & -\sigma_2[\delta_1(k_n)C_n^{-1}\delta_2(k_n)]^*\sigma_2(1/T)'(-k_n^*)^{-2}\e^{-2\ii t\theta}\\
