  \hfil
\subfigure[]{\includegraphics[width=3.0in]{Fig3-2-eps-converted-to.pdf}}
\caption{The contour $\Upsilon$, (a) Re$k_n>0$, (b) Re$k_n=0$. $J^{(out)}$ decays exponentially on red contours.}\label{fig3}
