To facilitate the analysis, it is more convenient to transform the residue conditions at the poles into jump conditions. We begin with some notations.
Let $\Upsilon_n$ be a small circle centered at $k_n$ for each $n$ with sufficiently small radius such that it lies inside the upper half plane and is disjoint from all other circles. We assume the small circles around $k_n$ and $-k_n^*$ are oriented clockwise and around $k^*_n$ and $-k_n$ are oriented counterclockwise, see Figure \ref{fig3}. Denote
\be
\Upsilon\doteq\left(\bigcup_{n=1}^N\pm\Upsilon_n\right)
\cup\left(\bigcup_{n=1}^N\pm\Upsilon_n^*\right).
\ee
By doing so, we will replace the residue conditions \eqref{3.42}-\eqref{3.49} of the RH problem with Schwarz invariant jump conditions across closed contours.
\subsubsection{The outer RH model }
We now establish the outer model RH problem for $\mu^{(out)}$.
\begin{rhp}\label{rh3.3}
Find a $4\times4$ matrix-valued function $\mu^{(out)}(\zeta,t;k)$ on $\bfC\setminus\Upsilon$ with the following properties:
\begin{itemize}
\item Analyticity: $\mu^{(out)}(\zeta,t;k)$ is analytic in $\bfC\setminus\Upsilon$.
\item Jump condition: The jump relation of the continuous boundary values $\mu^{out}_\pm$ on $\Upsilon$ is
    \be
    \mu^{(out)}_+(\zeta,t;k)=\mu^{(out)}_-(\zeta,t;k)J^{(out)}(\zeta,t;k),
    \ee
    where
\begin{align}
J^{(out)}=
\left\{
\begin{aligned}
&\begin{pmatrix}
\mathbb{I}_{2\times2} &  \mathbf{0}_{2\times2}\\
\delta_{2}^{-1}(k_n)C_n\delta_{1}^{-1}(k_n)\frac{T^{-2}(k_n)}{k-k_n}\e^{2\ii t\theta(k_n)} & \mathbb{I}_{2\times2}
\end{pmatrix},\  k\in\Upsilon_n, \ n\in\Delta_{k_0}^+,\\
&\begin{pmatrix}
\mathbb{I}_{2\times2} &  \mathbf{0}_{2\times2}\\
-\sigma_2[\delta_{2}^{-1}(k_n)C_n\delta_{1}^{-1}(k_n)]^*\sigma_2
\frac{T^{-2}(-k^*_n)}{k+k_n^*}\e^{2\ii t\theta(-k^*_n)} & \mathbb{I}_{2\times2}
\end{pmatrix},\  k\in-\Upsilon^*_n, \ n\in\Delta_{k_0}^+,\\
&\begin{pmatrix}
\mathbb{I}_{2\times2} & [\delta_{2}^{-1}(k_n)C_n\delta_{1}^{-1}(k_n)]^\dag \frac{T^{2}(k_n^*)}{k-k_n^*}\e^{-2\ii t\theta(k_n^*)} \\
\mathbf{0}_{2\times2} & \mathbb{I}_{2\times2}
    \end{pmatrix},\  k\in\Upsilon^*_n, \ n\in\Delta_{k_0}^+,\\
&\begin{pmatrix}
    \mathbb{I}_{2\times2} & \sigma_2[\delta_{2}^{-1}(k_n)C_n\delta_{1}^{-1}(k_n)]^{\texttt{T}}\sigma_2
    \frac{T^{2}(-k_n)}{k+k_n}\e^{-2\ii t\theta(-k_n)} \\
    \mathbf{0}_{2\times2} & \mathbb{I}_{2\times2}
    \end{pmatrix},\  k\in-\Upsilon_n, \ n\in\Delta_{k_0}^+, \\
&\begin{pmatrix}
    \mathbb{I}_{2\times2} &  \delta_1(k_n)C_n^{-1}\delta_2(k_n)
\frac{(1/T)'(k_n)^{-2}}{k-k_n}\e^{-2\ii t\theta(k_n)}\\
    \mathbf{0}_{2\times2}& \mathbb{I}_{2\times2}
    \end{pmatrix},\  k\in\Upsilon_n,\ n\in\Delta_{k_0}^-,\\
& \begin{pmatrix}
    \mathbb{I}_{2\times2} & -\sigma_2[\delta_1(k_n)C_n^{-1}\delta_2(k_n)]^*\sigma_2
    \frac{(1/T)'(-k_n^*)^{-2}}{k+k_n^*}\e^{-2\ii t\theta(-k_n^*)}\\
     \mathbf{0}_{2\times2}& \mathbb{I}_{2\times2}
    \end{pmatrix}, \ k\in-\Upsilon^*_n,\ n\in\Delta_{k_0}^-,\\
&\begin{pmatrix}
    \mathbb{I}_{2\times2} & \mathbf{0}_{2\times2} \\
    [\delta_1(k_n)C_n^{-1}\delta_2(k_n)]^\dag
\frac{T'(k_n^*)^{-2}}{k-k_n^*}\e^{2\ii t\theta(k_n^*)} & \mathbb{I}_{2\times2}
    \end{pmatrix}, \  k\in\Upsilon_n^*,\ n\in\Delta_{k_0}^-,\\
&\begin{pmatrix}
    \mathbb{I}_{2\times2} & \mathbf{0}_{2\times2}\\
    -\sigma_2[\delta_1(k_n)C_n^{-1}\delta_2(k_n)]^{\texttt{T}}\sigma_2
    \frac{T'(-k_n)^{-2}}{k+k_n}\e^{2\ii t\theta(-k_n)}  & \mathbb{I}_{2\times2}
    \end{pmatrix},\  k\in-\Upsilon_n,\ n\in\Delta_{k_0}^-.
\end{aligned}
\right.
\end{align}
\item Normalization: $\mu^{(out)}(\zeta,t;k)\to\mathbb{I}_{4\times4}$, as $k\to\infty$.
\end{itemize}
\end{rhp}

From the signature table Figure \ref{fig1}, we observe that along the characteristic line $\zeta=vt$ where $v=-1/(4|k_n|^2)$, by choosing the radius of each element of $\Upsilon$ small enough, we have for $k\in\Upsilon\setminus(\pm\Upsilon_n\cup\pm\Upsilon_n^*)$
\be\label{3.64}
|J^{(out)}-\mathbb{I}_{4\times4}|\leq c\e^{-ct},\quad t\to\infty.
\ee
\begin{proposition}\label{prop3.2}
There exists a $4\times4$ matrix-valued function $E_*(\zeta,t;k)$ with
\be
E_*(\zeta,t;k)=\mathbb{I}_{4\times4}+O(\e^{-ct})
\ee
such that
\be
\mu^{(out)}(\zeta,t;k)=E_*(\zeta,t;k)\mu^{(out)}_*(\zeta,t;k),
\ee
where $\mu^{(out)}_*(\zeta,t;k)$ solves the RH problem:
\begin{rhp}\label{rh3.4}
Find a $4\times4$ matrix-valued function $\mu_*^{(out)}(\zeta,t;k)$ on $\bfC\setminus(\pm\Upsilon_n\cup\pm\Upsilon_n^*)$ with the following properties:
\begin{itemize}
\item Analyticity: $\mu^{(out)}(\zeta,t;k)$ is analytic for $k\in\bfC\setminus(\pm\Upsilon_n\cup\pm\Upsilon_n^*)$ with continuous boundary values $\mu_{*\pm}^{(out)}$.
\item Jump condition: On $\pm\Upsilon_n\cup\pm\Upsilon_n^*$, we have jump relation
    \be
    \mu_{*+}^{(out)}(\zeta,t;k)=\mu_{*-}^{(out)}(\zeta,t;k)J_*^{(out)}(\zeta,t;k),
    \ee
    where
\begin{align}
J^{(out)}_*=
\left\{
\begin{aligned}
&\begin{pmatrix}
\mathbb{I}_{2\times2} &  \mathbf{0}_{2\times2}\\
\delta_{2}^{-1}(k_n)C_n\delta_{1}^{-1}(k_n)\frac{T^{-2}(k_n)}{k-k_n}\e^{2\ii t\theta(k_n)} & \mathbb{I}_{2\times2}
\end{pmatrix},\  k\in\Upsilon_n,\\
&\begin{pmatrix}
\mathbb{I}_{2\times2} &  \mathbf{0}_{2\times2}\\
-\sigma_2[\delta_{2}^{-1}(k_n)C_n\delta_{1}^{-1}(k_n)]^*\sigma_2
\frac{T^{-2}(-k^*_n)}{k+k_n^*}\e^{2\ii t\theta(-k^*_n)} & \mathbb{I}_{2\times2}
\end{pmatrix},\  k\in-\Upsilon^*_n,\\
&\begin{pmatrix}
\mathbb{I}_{2\times2} & [\delta_{2}^{-1}(k_n)C_n\delta_{1}^{-1}(k_n)]^\dag \frac{T^{2}(k_n^*)}{k-k_n^*}\e^{-2\ii t\theta(k_n^*)} \\
\mathbf{0}_{2\times2} & \mathbb{I}_{2\times2}
    \end{pmatrix},\  k\in\Upsilon^*_n,\\
&\begin{pmatrix}
    \mathbb{I}_{2\times2} & \sigma_2[\delta_{2}^{-1}(k_n)C_n\delta_{1}^{-1}(k_n)]^{\texttt{T}}\sigma_2
    \frac{T^{2}(-k_n)}{k+k_n}\e^{-2\ii t\theta(-k_n)} \\
    \mathbf{0}_{2\times2} & \mathbb{I}_{2\times2}
    \end{pmatrix},\  k\in-\Upsilon_n.
\end{aligned}
\right.
\end{align}
\item Normalization: $\mu_*^{(out)}(\zeta,t;k)\to\mathbb{I}_{4\times4}$, as $k\to\infty$.
\end{itemize}
\end{rhp}
\end{proposition}
\begin{proof}
The solvability of the RH problem \ref{rh3.4} follows from the Schwarz invariant condition of the jump matrices \cite{ZX1989}. Moreover, it is easy to see that on $\Upsilon\setminus(\pm\Upsilon_n\cup\pm\Upsilon_n^*)$, $E_*$ satisfies the following jump condition:
\be
E_{*+}=E_{*-}\left(\mu_*^{(out)}J^{(out)}[\mu_*^{(out)}]^{-1}\right),
\ee
Using \eqref{3.64}, the conclusion follows from solving a small norm RH problem (see the solution to RH problem \ref{rhp3.8} for detail).
\end{proof}
We now study the solution to RH problem \ref{rh3.4}. Using the Plemelj formula and Cauchy Residue theorem, if Re$k_n>0$, the solution of this RH problem is given by
\begin{align}
\mu_{*L}^{(cb)}(k)=&\begin{pmatrix}\mathbb{I}_{2\times2}\\ \mathbf{0}_{2\times2}\end{pmatrix}
+\mu_{*R}^{(cb)}(k_n)\delta_{2}^{-1}(k_n)C_n\delta_{1}^{-1}(k_n)
\frac{T^{-2}(k_n)}{k-k_n}\e^{2\ii t\theta(k_n)}\\
&-\mu_{*R}^{(cb)}(-k_n^*)
\sigma_2[\delta_{2}^{-1}(k_n)C_n\delta_{1}^{-1}(k_n)]^*\sigma_2
\frac{T^{-2}(-k^*_n)}{k+k^*_n}\e^{2\ii t\theta(-k_n^*)},\nn\\
\mu_{*R}^{(cb)}(k)=&\begin{pmatrix}\mathbf{0}_{2\times2}\\ \mathbb{I}_{2\times2} \end{pmatrix}-\mu_{*L}^{(cb)}(k_n^*)[\delta_{2}^{-1}(k_n)C_n\delta_{1}^{-1}(k_n)]^\dag
\frac{T^{2}(k^*_n)}{k-k^*_n}\e^{-2\ii t\theta(k^*_n)}\label{3.71}\\
&+\mu_{*L}^{(cb)}(-k_n)\sigma_2[\delta_{2}^{-1}(k_n)
C_n\delta_{1}^{-1}(k_n)]^{\texttt{T}}\sigma_2
\frac{T^{2}(-k_n)}{k+k_n}\e^{-2\ii t\theta(-k_n)}.\nn
\end{align}
Then, we have a closed system:
\begin{align}
\mu_{*UL}^{(cb)}(k_n^*)=&\mathbb{I}_{2\times2}+\mu_{*UR}^{(cb)}(k_n)
\delta_{2}^{-1}(k_n)C_n\delta_{1}^{-1}(k_n)\frac{T^{-2}(k_n)}{k_n^*-k_n}\e^{2\ii t\theta(k_n)}\label{3.72}\\
&-\mu_{*UR}^{(cb)}(-k_n^*)\sigma_2[\delta_{2}^{-1}(k_n)C_n\delta_{1}^{-1}(k_n)]^*\sigma_2
\frac{T^{-2}(-k^*_n)}{k_n^*+k^*_n}\e^{2\ii t\theta(-k^*_n)},\nn\\
\mu_{*UL}^{(cb)}(-k_n)=&\mathbb{I}_{2\times2}+\mu_{*UR}^{(cb)}(k_n)
\delta_{2}^{-1}(k_n)C_n\delta_{1}^{-1}(k_n)\frac{T^{-2}(k_n)}{-k_n-k_n}\e^{2\ii t\theta(k_n)}\label{3.73}\\
&-\mu_{*UR}^{(cb)}(-k_n^*)\sigma_2[\delta_{2}^{-1}(k_n)C_n\delta_{1}^{-1}(k_n)]^*\sigma_2
\frac{T^{-2}(-k^*_n)}{-k_n+k^*_n}\e^{2\ii t\theta(-k^*_n)},\nn\\
\mu_{*UR}^{(cb)}(k_n)=&-\mu_{*UL}^{(cb)}(k_n^*)
[\delta_{2}^{-1}(k_n)C_n\delta_{1}^{-1}(k_n)]^\dag\frac{T^{2}(k^*_n)}{k_n-k^*_n}\e^{-2\ii t\theta(k_n^*)}\label{3.74}\\
&+\mu_{*UL}^{(cb)}(-k_n)\sigma_2[\delta_{2}^{-1}(k_n)C_n\delta_{1}^{-1}(k_n)]^{\texttt{T}}\sigma_2
\frac{T^{2}(-k_n)}{k_n+k_n}\e^{-2\ii t\theta(-k_n)},\nn\\
\mu_{*UR}^{(cb)}(-k_n^*)=&-\mu_{*UL}^{(out)}(k_n^*)
[\delta_{2}^{-1}(k_n)C_n\delta_{1}^{-1}(k_n)]^\dag\frac{T^{2}(k^*_n)}{-k^*_n-k^*_n}\e^{-2\ii t\theta(k_n^*)}\label{3.75}\\
&+\mu_{*UL}^{(cb)}(-k_n)\sigma_2[\delta_{2}^{-1}(k_n)C_n\delta_{1}^{-1}(k_n)]^{\texttt{T}}\sigma_2
\frac{T^{2}(-k_n)}{-k_n^*+k_n}\e^{-2\ii t\theta(-k_n)}.\nn
\end{align}
Substituting Equations \eqref{3.74}, \eqref{3.75} into \eqref{3.72} and \eqref{3.73}, we can obtain $\mu_{*UL}^{(cb)}(k_n^*)$ and $\mu_{*UL}^{(cb)}(-k_n)$. Then, by reconstruction formulae \eqref{2.50} and \eqref{2.51}, as well as \eqref{3.71}, we can find the composite breather solution
\begin{align}
\begin{pmatrix} q_{1n}^{(cb)}(\zeta,t) & q_{2n}^{(cb)}(\zeta,t)\end{pmatrix}=&\ii\begin{pmatrix}
\left([\mu_*^{(cb)}(0)]^{-1}
\mu_{*1}^{(cb)}\right)_{13}
& \left([\mu_*^{(cb)}(0)]^{-1}
\mu_{*1}^{(cb)}\right)_{14}\end{pmatrix},\label{eq3.77cb}\\
x-\zeta(x,t)=& \ii \left[\left([\mu_*^{(cb)}(0)]^{-1}
\mu_{*1}^{(cb)}\right)_{11}-1\right],
\end{align}
where we expand
\be
\mu_{*}^{(cb)}(k)=\mu_*^{(cb)}(0)+\mu_{*1}^{(cb)}k+O(k^2),\ \text{as} \ k\to0.
\ee
\begin{remark}
We do not give explicit expressions for the composite breather solution because they could not be simplified enough to be instructive. In \cite{LSL-IST}, for a specific choice of the discrete eigenvalue and the norming constant matrix, the magnitudes of  $q_1^{(cb)}(\zeta,t)$ and $q_2^{(cb)}(\zeta,t)$ are shown graphically. We also note that the explicit expression for a composite breather associated with the discrete eigenvalue $k_1$ is given by Equation (173) in \cite{CGP} through Darboux transformations. Moreover, we know that the speed of this composite breather is $-1/(4|k_1|^2)$.
\end{remark}
If Re$k_n=0$, that is, $k_n=-k_n^*=\ii\nu_n$, the solution of RH problem \ref{rh3.4} in this case can be expressed by
\begin{align}
\mu_{*L}^{(sol)}(k)=&\begin{pmatrix}\mathbb{I}_{2\times2}\\ \mathbf{0}_{2\times2}\end{pmatrix}
+\mu_{*R}^{(sol)}(k_n)\delta_{2}^{-1}(k_n)C_n\delta_{1}^{-1}(k_n)
\frac{T^{-2}(k_n)}{k-k_n}\e^{2\ii t\theta(k_n)},\\
\mu_{*R}^{(sol)}(k)=&\begin{pmatrix}\mathbf{0}_{2\times2}\\ \mathbb{I}_{2\times2} \end{pmatrix}-\mu_{*L}^{(sol)}(k_n^*)[\delta_{2}^{-1}(k_n)C_n\delta_{1}^{-1}(k_n)]^\dag
\frac{T^{2}(k^*_n)}{k-k^*_n}\e^{-2\ii t\theta(k^*_n)}.
\end{align}
Thus, we have
\begin{align}
\mu_{*UL}^{(sol)}(k_n^*)=&\mathbb{I}_{2\times2}+\mu_{*UR}^{(sol)}(k_n)
\delta_{2}^{-1}(k_n)C_n\delta_{1}^{-1}(k_n)\frac{T^{-2}(k_n)}{k_n^*-k_n}\e^{2\ii t\theta(k_n)},\label{3.76}\\
\mu_{*UR}^{(sol)}(k_n)=&-\mu_{*UL}^{(sol)}(k_n^*)
[\delta_{2}^{-1}(k_n)C_n\delta_{1}^{-1}(k_n)]^\dag\frac{T^{2}(k^*_n)}{k_n-k^*_n}\e^{-2\ii t\theta(k_n^*)}.\label{3.77}
\end{align}
By substituting \eqref{3.77} into \eqref{3.76} to find $\mu_{*UL}^{(sol)}(k_n^*)$,  as $k\to0$, expanding $\mu_{*}^{(sol)}(k)=\mu_*^{(sol)}(0)+\mu_{*1}^{(sol)}k+O(k^2)$,
and using \eqref{2.50} and \eqref{2.51}, we obtain the so-called self-symmetric soliton solution:
\begin{align}\label{3.78}
&\begin{pmatrix} q_{1n}^{(sol)}(\zeta,t) & q_{2n}^{(sol)}(\zeta,t)\end{pmatrix}=\ii\begin{pmatrix}
\left([\mu_*^{(sol)}(0)]^{-1}
\mu_{*1}^{(sol)}\right)_{13}
& \left([\mu_*^{(sol)}(0)]^{-1}
\mu_{*1}^{(sol)}\right)_{14}\end{pmatrix}\\
&\qquad\qquad\qquad\qquad\quad \quad\,\,\,\
=-\frac{1}{k_n}\text{sech}\left[\zeta_1(\zeta,t)
-x_0\right]\frac{\mathbf{g}^*}{|\mathbf{g}|},\nn\\
&x=\zeta+\frac{2}{\nu_n^2}\frac{1}{1+\e^{2(\zeta_1-x_0)}},\quad \zeta_1(\zeta,t)=2\nu_n\left(\zeta+\frac{t}{4\nu_n^2}\right),\quad
x_0=\log\frac{|\mathbf{g}|}{2\nu_n},\nn
\end{align}
with
\be
\mathbf{g}=\begin{pmatrix}\alpha_n\\ \beta_n\end{pmatrix},\quad\begin{pmatrix}\alpha_n&\beta_n^*\\ \beta_n&-\alpha_n^*\end{pmatrix}\doteq\delta_{2}^{-1}(k_n)C_n\delta_{1}^{-1}(k_n)T^{-2}(k_n).
\ee
\subsubsection{Local RH models near phase points}
From the Proposition \ref{prop3.1}, $J^{(2)}-\mathbb{I}_{4\times4}$ in the neighborhood $U_{\pm k_0}$ of $\pm k_0$ does not have a uniformly decay as $t\to\infty$. Moreover, $1-\chi(k)=1$ for $k\in U_{\pm k_0}$. Thus, we can establish the model RH problems for $\mu^{(\pm k_0)}$ in $U_{\pm k_0}$, which are the local models near the critical points $\pm k_0$. Denote $\Gamma^{\epsilon1}\doteq\cup_{l=1}^4\Gamma_l\cap U_{ k_0}=\cup_{l=1}^4\Gamma_l^\epsilon,$ $\Gamma^{\epsilon2}\doteq\cup_{l=5}^8\Gamma_l\cap U_{-k_0}=\cup_{l=5}^8\Gamma_l^\epsilon,$ see Figure \ref{fig4}.
\begin{figure}[htbp]
 \centering
 \includegraphics[width=3in]{Fig4-eps-converted-to.pdf}
  \caption{The contours $\Gamma^{\epsilon1}\cup\Gamma^{\epsilon2}$ in the complex $k$-plane.}\label{fig4}
\end{figure}
\begin{rhp}\label{rhp3.5}
Find a $4\times4$ matrix-valued function $\mu^{(k_0)}(\zeta,t;k)$ on  $\bfC\setminus\Gamma^{\epsilon1}$ with the following properties:
\begin{itemize}
\item Analyticity: $\mu^{(k_0)}(\zeta,t;k)$ is analytical in $\bfC\setminus\Gamma^{\epsilon1}$.

\item Jump condition: For $k\in\Gamma^{\epsilon1}$, the continuous boundary values $\mu^{(ccSP)}_\pm$ satisfy the jump relation
\be
\mu^{(k_0)}_+(\zeta,t;k)=\mu^{(k_0)}_-(\zeta,t;k)J^{(k_0)}(\zeta,t;k),
\ee
where the jump matrix $J^{(k_0)}(\zeta,t;k)$ is expressed by
\begin{align*}
J^{(k_0)}=
\left\{
\begin{aligned}
&\begin{pmatrix}
\mathbb{I}_{2\times2} & \delta_{1}(k)\left(\mathbb{I}_{2\times2}+\rho^\dag(k_0) \rho(k_0)\right)^{-1}\rho^\dag(k_0)\delta_{2}(k)T^2(k_0)\e^{-2\ii t\theta(k)}\\
\mathbf{0}_{2\times2} & \mathbb{I}_{2\times2}
\end{pmatrix},\quad k\in\Gamma_1^\epsilon,\\
&\begin{pmatrix}
\mathbb{I}_{2\times2} & \mathbf{0}_{2\times2}\\
\delta_{2}^{-1}(k)\rho(k_0)\delta_{1}^{-1}(k)T^{-2}(k_0)\e^{2\ii t\theta(k)} & \mathbb{I}_{2\times2}
\end{pmatrix},\quad\,    k\in\Gamma_2^\epsilon,\\
&\begin{pmatrix}
\mathbb{I}_{2\times2} & \delta_{1}(k)\rho^\dag(k_0)\delta_{2}(k)T^2(k_0)\e^{-2\ii t\theta(k)}\\
\mathbf{0}_{2\times2} & \mathbb{I}_{2\times2}
\end{pmatrix},\qquad k\in\Gamma_3^\epsilon,\\
&\begin{pmatrix}
\mathbb{I}_{2\times2} & \mathbf{0}_{2\times2}\\
\delta_{2}^{-1}(k)\rho(k_0)\left(\mathbb{I}_{2\times2}+\rho^\dag(k_0) \rho(k_0)\right)^{-1}\delta_{1}^{-1}(k)T^{-2}(k_0)\e^{2\ii t\theta(k)} & \mathbb{I}_{2\times2}
\end{pmatrix}, \,\,\ k\in\Gamma_4^\epsilon.
\end{aligned}
\right.
\end{align*}
\item Normalization: $\mu^{(k_0)}(\zeta,t;k)\to\mathbb{I}_{4\times4}$, as $k\to\infty$.
\end{itemize}
\end{rhp}
\begin{rhp}\label{rhp3.6}
Find a $4\times4$ matrix-valued function $\mu^{(-k_0)}(\zeta,t;k)$ on  $\bfC\setminus\Gamma^{\epsilon2}$ with the following properties:
\begin{itemize}
\item Analyticity: $\mu^{(-k_0)}(\zeta,t;k)$ is analytical in $\bfC\setminus\Gamma^{\epsilon2}$.

\item Jump condition: For $k\in\Gamma^{\epsilon2}$, the continuous boundary values $\mu^{(-k_0)}_\pm$ satisfy the jump relation
\be
\mu^{(-k_0)}_+(\zeta,t;k)=\mu^{(-k_0)}_-(\zeta,t;k)J^{(-k_0)}(\zeta,t;k),
\ee
where the jump matrix $J^{(-k_0)}(\zeta,t;k)$ is expressed by
\begin{align*}
J^{(-k_0)}=
\left\{
\begin{aligned}
&\begin{pmatrix}
\mathbb{I}_{2\times2} &\mathbf{0}_{2\times2}\\
-\delta_{2}^{-1}(k)\rho(-k_0)\delta_{1}^{-1}(k)T^{-2}(-k_0)\e^{2\ii t\theta(k)} & \mathbb{I}_{2\times2}
\end{pmatrix},\quad k\in\Gamma_5^\epsilon,\\
&\begin{pmatrix}
\mathbb{I}_{2\times2} & \delta_{1}(k)\left(\mathbb{I}_{2\times2}+\rho^\dag(-k_0) \rho(-k_0)\right)^{-1}\rho^\dag(-k_0)\delta_{2}(k)T^2(-k_0)\e^{-2\ii t\theta(k)}\\
\mathbf{0}_{2\times2} & \mathbb{I}_{2\times2}
\end{pmatrix},\,\,\ k\in\Gamma_6^\epsilon,\\
&\begin{pmatrix}
\mathbb{I}_{2\times2} &\mathbf{0}_{2\times2}\\
\delta_{2}^{-1}(k)\rho(-k_0)\left(\mathbb{I}_{2\times2}+\rho^\dag(-k_0) \rho(-k_0)\right)^{-1}\delta_{1}^{-1}(k)T^{-2}(-k_0)\e^{2\ii t\theta(k)} & \mathbb{I}_{2\times2}
\end{pmatrix},\, k\in\Gamma_7^\epsilon,\\
&\begin{pmatrix}
\mathbb{I}_{2\times2} & -\delta_{1}(k)\rho^\dag(-k_0)\delta_{2}(k)T^2(-k_0)\e^{-2\ii t\theta(k)}\\
\mathbf{0}_{2\times2} & \mathbb{I}_{2\times2}
\end{pmatrix},\quad\,\,\,\,  k\in\Gamma_8^\epsilon.
\end{aligned}
\right.
\end{align*}
\item Normalization: $\mu^{(-k_0)}(\zeta,t;k)\to\mathbb{I}_{4\times4}$, as $k\to\infty$.
\end{itemize}
\end{rhp}
We now study the solution of RH problems \ref{rhp3.5} and \ref{rhp3.6}. We will take the RH problem \ref{rhp3.5} as an example and others can be handled in the same way.

Based on the Beals--Coifman theory \cite{BC}, we decompose
$J^{(k_0)}=(\mathbb{I}_{4\times4}-w_-^{(k_0)})^{-1}(\mathbb{I}_{4\times4}+w_+^{(k_0)}),$ and let $w^{(k_0)}=w_+^{(k_0)}+w_-^{(k_0)}$. Our first step is to extend the contour $\Gamma^{\epsilon1}$ to the contour
\begin{align}
\hat{\Gamma}^{\epsilon1}\doteq\{k\in\bfC|k=k_0+k_0\alpha\e^{\pm\frac{\ii\pi}{4}},-\infty<\alpha<\infty\},\nn
\end{align}
and define $\hat{w}^{(k_0)}$ on $\hat{\Gamma}^{\epsilon1}$ through
\berr
\hat{w}^{(k_0)}=\left\{
\begin{aligned}
&w^{(k_0)},\quad k\in\Gamma^{\epsilon1}\subset\hat{\Gamma}^{\epsilon1},\\
&\mathbf{0}_{4\times4},\quad\ k\in\hat{\Gamma}^{\epsilon1}\setminus\Gamma^{\epsilon1}.
\end{aligned}
\right.
\eerr


It is first noted that the functions $\delta_1(k)$ and $\delta_2(k)$ respectively satisfy the $2\times2$ matrix RH problems \eqref{3.3} and \eqref{3.4}, and hence they can not be solved in explicit form. However, by taking the determinants, they are transformed into a same scalar RH problem as follows. Set $\delta(k)=\det[\delta_j(k)]$, we then get
\be\label{3.81}
\left\{
\begin{aligned}
\delta_{+}(k)&=\left(1+\text{tr}[\rho(k)\rho^\dag(k)]
+\det[\rho(k)\rho^\dag(k)]\right)\delta_{-}(k),\quad  |k|>k_0,\\
&=\delta_{-}(k),\qquad\qquad\qquad\qquad\qquad\qquad\qquad\quad\qquad |k|<k_0,\\
\delta(k)&\to1,\qquad\qquad\qquad\qquad\qquad\qquad\qquad\quad\qquad\qquad k\to\infty.
\end{aligned}
\right.
\ee
By the Plemelj formula, we find
\begin{align}\label{3.82}
\delta(k)=&\exp\left\{\frac{1}{2\pi\ii}\left(\int_{-\infty}^{-k_0}+\int_{k_0}^{\infty}\right)
\frac{\ln\left(1+\text{tr}[\rho(s)\rho^\dag(s)]+\det[\rho(s)\rho^\dag(s)]\right)}{s-k}\dd s\right\}\\
=&\left(\frac{k-k_0}{k+k_0}\right)^{-\ii\nu(k_0)}\e^{\chi_{k_0}(k)},
\end{align}
where
\begin{align}
\nu(k_0)&=-\frac{1}{2\pi}\ln\left(1+\text{tr}[\rho(k_0)\rho^\dag(k_0)]
+\det[\rho(k_0)\rho^\dag(k_0)]\right),\label{3.84}\\
\chi_{k_0}(k)&=\frac{1}{2\pi\ii}\left(\int_{-\infty}^{-k_0}+\int_{k_0}^{\infty}\right)
\ln\left(\frac{1+\text{tr}[\rho(s)\rho^\dag(s)]+\det[\rho(s)\rho^\dag(s)]}{1+\text{tr}[\rho(k_0)\rho^\dag(k_0)]
+\det[\rho(k_0)\rho^\dag(k_0)]}\right)\dd s,\label{3.85}
\end{align}
and hence $\delta(k)$, $\delta^{-1}(k)$ are uniformly bounded. Therefore, we can write
\begin{align}\label{3.86}
&\delta_{1}(k)\rho^\dag(k_0)\delta_{2}(k)\e^{-2\ii t\theta(k)}=\delta_{1}(k)\rho^\dag(k_0)\left(\delta_{2}(k)-\delta(k) \mathbb{I}_{2\times2}\right)\e^{-2\ii t\theta(k)}\\
&+(\delta_1(k)-\delta(k) \mathbb{I}_{2\times2})\rho^\dag(k_0)\delta(k)\e^{-2\ii t\theta(k)}+\rho^\dag(k_0)\delta^2(k)\e^{-2\ii t\theta(k)}.\nn
\end{align}
Expanding $\ii t\theta(k)$, we obtain
\be
\ii t\theta(k)=\frac{t}{2\ii k_0}+\frac{t}{4\ii k_0^3}(k-k_0)^2+\frac{\ii t}{4s^4}(k-k_0)^3,\quad s\ \text{lies\ between}\ k_0\ \text{and}\ k.
\ee
We thus define the following scaling transformation
\be
\mathcal{N}: f(k)\to(\mathcal{N}f)(k)=f\left(\frac{z}{\sqrt{k_0^{-3}t}}+k_0\right),
\ee
which acts on $\delta(k)\e^{-\ii t\theta(k)}$ and gives
\be
(\mathcal{N}\delta\e^{-\ii t\theta})(k)=\delta_{k_0}^0\delta_{k_0}^1(z),
\ee
where
\begin{align}
\delta_{k_0}^0=&\e^{\chi_{k_0}(k_0)-\frac{t}{2\ii k_0}}(4k_0^{-1}t)^{\frac{\ii\nu(k_0)}{2}},\label{deltak0}\\
\delta_{k_0}^1(z)=&z^{-\ii\nu(k_0)}\exp\left\{\frac{\ii z^2}{4}\left(1-\frac{ z}{s^4k_0^{-9/2}t^{1/2}}\right)\right\}\\
&\times\left(\frac{2k_0}{z/\sqrt{k_0^{-3}t}+2k_0}\right)^{-\ii\nu(k_0)}
\e^{\chi_{k_0}([z/\sqrt{k_0^{-3}t}]+k_0)-\chi_{k_0}(k_0)}.\nn
\end{align}
Set $\tilde{w}^{(k_0)}=\mathcal{N}\hat{w}^{(k_0)}$. \begin{figure}[htbp]
  \centering
  \includegraphics[width=3in]{Fig5-eps-converted-to.pdf}
  \caption{The oriented contour $\tilde{\Gamma}^{(k_0)}$.}\label{fig5}
\end{figure}
Let $\tilde{\Gamma}^{(k_0)}$ denote the contour $\{z\in\bfC|z=\alpha\e^{\pm\frac{\ii\pi}{4}},-\infty<\alpha<\infty\}$ centered at original point and oriented to the origin as shown in Figure \ref{fig5}.
We next let $J^{(X)}(\rho(k_0);z)=(\mathbb{I}_{4\times4}-w_-^{(X)})^{-1}(\mathbb{I}_{4\times4}+w_+^{(X)})$, where
\begin{align}
w^{(X)}=&w^{(X)}_+=\left\{
\begin{aligned}
&\begin{pmatrix}
\mathbf{0}_{2\times2} & \left(\mathbb{I}_{2\times2}+\rho^\dag(k_0) \rho(k_0)\right)^{-1}\rho^\dag(k_0)(\delta_{k_0}^0)^2T^2(k_0)z^{-2\ii\nu(k_0)}\e^{\frac{\ii z^2}{2}}\\
\mathbf{0}_{2\times2}& \mathbf{0}_{2\times2}
\end{pmatrix},\ z\in \tilde{\Gamma}_1,\\
&\begin{pmatrix}
\mathbf{0}_{2\times2} & \rho^\dag(k_0)(\delta_{k_0}^0)^2T^2(k_0)z^{-2\ii\nu(k_0)}\e^{\frac{\ii z^2}{2}}\\
 \mathbf{0}_{2\times2}& \mathbf{0}_{2\times2}
\end{pmatrix},\ z\in\tilde{\Gamma}_3,
\end{aligned}
\right.\label{WX+}\\
w^{(X)}=&w^{(X)}_-=\left\{
\begin{aligned}
&\begin{pmatrix}
\mathbf{0}_{2\times2} & \mathbf{0}_{2\times2}\\
\rho(k_0)(\delta_{k_0}^0)^{-2}T^{-2}(k_0)z^{2\ii\nu(k_0)}\e^{-\frac{\ii z^2}{2}} & \mathbf{0}_{2\times2}
\end{pmatrix},\, z\in\tilde{\Gamma}_2,\\
&\begin{pmatrix}
\mathbf{0}_{2\times2} & \mathbf{0}_{2\times2}\\
\rho(k_0)\left(\mathbb{I}_{2\times2}+\rho^\dag(k_0) \rho(k_0)\right)^{-1}(\delta_{k_0}^0)^{-2}T^{-2}(k_0)z^{2\ii\nu(k_0)}\e^{-\frac{\ii z^2}{2}} & \mathbf{0}_{2\times2}
\end{pmatrix},\ z\in\tilde{\Gamma}_4.
\end{aligned}
\right.\label{WX-}
\end{align}
Then, we have the following estimates on the rate of convergence.
\begin{proposition}\label{prop3.3}
For $z\in\{z\in\bfC|z=\sqrt{k^{-1}_0t}\alpha\e^{\frac{\pi\ii}{4}},
-\epsilon\leq\alpha\leq\epsilon\}$, as $t\to\infty$, we have the following estimations
\begin{align}
\left|[\delta_{k_0}^1(z)]^2-z^{-2\ii\nu(k_0)}\e^{\frac{\ii z^2}{2}}\right|&\leq c\frac{\ln t}{\sqrt{t}},\label{3.92}\\
\left|\left(\mathcal{N}\left(\delta_{2}-\delta \mathbb{I}_{2\times2}\right)\e^{-2\ii t\theta}\right)(k)\right|&\leq ct^{-1},\label{3.93}\\
\left|\left(\mathcal{N}(\delta_1-\delta\mathbb{I}_{2\times2})\e^{-2\ii t\theta}\right)(k)\right|&\leq ct^{-1}.\label{3.94}
\end{align}
\end{proposition}
\begin{proof}
See the Appendix \ref{secA}.
\end{proof}
Introduce the Cauchy operator $\mathcal{C}_\pm$ on $\Gamma$ as follows
\be
(\mathcal{C}_\pm f)(k)=\int_{\Gamma}\frac{f(s)}{s-k_\pm}\frac{\dd s}{2\pi\ii},\quad k\in\Gamma,~f\in L^2(\Gamma).
\ee
Define the operator $\mathcal{C}_{w}f\doteq\mathcal{C}_+(fw_-)+\mathcal{C}_-(fw_+)$.
\begin{lemma}\label{lem2.6}
As $t\rightarrow\infty$, $(1-\mathcal{C}_{w^{(X)}})^{-1}:L^2(\tilde{\Gamma}^{(k_0)})\rightarrow L^2(\tilde{\Gamma}^{(k_0)})$ exists and is uniformly bounded:
\berr
\left\|(1-\mathcal{C}_{w^{X}})^{-1}\right\|_{L^2(\tilde{\Gamma}^{(k_0)})}\leq c,
\eerr
and hence,
\berr
\left\|(1-\mathcal{C}_{\tilde{w}^{(k_0)}})^{-1}\right\|_{L^2(\tilde{\Gamma}^{(k_0)})}\leq c.
\eerr
\end{lemma}
\begin{proof}
See \cite{CL2021,PD} and references therein.
\end{proof}
A simple change of variables argument shows that
$\mathcal{C}_{\hat{w}^{(k_0)}}=\mathcal{N}^{-1}\mathcal{C}_{\tilde{w}^{(k_0)}}\mathcal{N}.$ Then, we can get
\begin{align}\label{3.99}
&\int_{\Gamma^{\epsilon1}}\left(((1-\mathcal{C}_{w^{(k_0)}})^{-1}\mathbb{I}_{4\times4})
w^{(k_0)}\right)(s)\dd s=\int_{\hat{\Gamma}^{\epsilon1}}\left(((1-\mathcal{C}_{\hat{w}^{(k_0)}})^{-1}
\mathbb{I}_{4\times4})\hat{w}^{(k_0)}\right)(s)\dd s\\
&=\int_{\hat{\Gamma}^{\epsilon1}}(\mathcal{N}^{-1}(1-\mathcal{C}_{\tilde{w}^{(k_0)}})^{-1}
\mathcal{N}\mathbb{I}_{4\times4})(s)
\hat{w}^{(k_0)}(s)\dd s\nn\\
&=\int_{\hat{\Gamma}^{\epsilon1}}((1-\mathcal{C}_{\tilde{w}^{(k_0)}})^{-1}
\mathbb{I}_{4\times4})\left((s-k_0)\sqrt{k_0^{-3}t}\right)
(\mathcal{N}\hat{w}^{(k_0)})\left((s-k_0)\sqrt{k^{-3}_0t}\right)\dd s\nn\\
&=\frac{1}{\sqrt{k_0^{-3}t}}
\int_{\tilde{\Gamma}^{(k_0)}}\left(((1-\mathcal{C}_{\tilde{w}^{(k_0)}})^{-1}
\mathbb{I}_{4\times4})\tilde{w}^{(k_0)}\right)(s)\dd s\nn\\
&=\frac{1}{\sqrt{k_0^{-3}t}}\int_{\tilde{\Gamma}^{(k_0)}}
\left(((1-\mathcal{C}_{w^{(X)}})^{-1}\mathbb{I}_{4\times4})w^{(X)}\right)(s)\dd s+O\left(\frac{\ln t}{t}\right).\nn
\end{align}
For $z\in\bfC\setminus\tilde{\Gamma}^{(k_0)}$, let
\be\label{3.100}
\mu^{(X)}(\rho(k_0);z)=\mathbb{I}_{4\times4}
+\frac{1}{2\pi\ii}\int_{\tilde{\Gamma}^{(k_0)}}
\frac{\left(((1-\mathcal{C}_{w^{(X)}})^{-1}\mathbb{I}_{4\times4})w^{(X)}\right)(s)}{s-z}
\dd s,
\ee
then $\mu^{(X)}(\rho(k_0);z)$ solves the following RH problem:
\begin{rhp}\label{rhp3.7}
Find a $4\times4$ matrix-valued function $\mu^{(X)}(\rho(k_0);z)$ with the following properties:
\begin{itemize}
\item Analyticity: $\mu^{(X)}(\rho(k_0);z)$ is analytic for $z\in\bfC\setminus\tilde{\Gamma}^{(k_0)}$ and continuous on $\tilde{\Gamma}^{(k_0)}$.

\item Jump condition: The continuous boundary values $\mu^{(X)}_\pm(\rho(k_0);z)$ satisfy the following jump relation
\bea
\mu^{(X)}_+(\rho(k_0);z)=\mu^{(X)}_-(\rho(k_0);z)J^{(X)}(\rho(k_0);z),\quad z\in\tilde{\Gamma}^{(k_0)}.
\eea

\item Normalization: $\mu^{(X)}(\rho(k_0);z)\rightarrow\mathbb{I}_{4\times4},$ as $z\rightarrow\infty.$
\end{itemize}
\end{rhp}
The solution of the RH problem for $\mu^{(X)}$ can be expressed based on the PC model, see Appendix \ref{secB}, that is,
\begin{align}
\mu^{(X)}(\rho(k_0);z)=\left(\delta_{k_0}^0T(k_0)\right)^{\Sigma_3}
\mu^{(PC)}\left(\rho(k_0);z\right)\left(\delta_{k_0}^0T(k_0)\right)^{-\Sigma_3}.
\end{align}
Then, in the large $z$ expansion
\be
\mu^{(X)}(\rho(k_0);z)=\mathbb{I}_{4\times4}+\frac{\mu_1^{(X)}}{z}+O(z^{-2}),\quad z\rightarrow\infty,
\ee
then it follows from \eqref{3.100} and \eqref{B.4} that
\begin{align}
\mu_1^{(X)}=&-\frac{1}{2\pi\ii}\int_{\tilde{\Gamma}^{(k_0)}}
\left(((1-\mathcal{C}_{w^{(X)}})^{-1}\mathbb{I}_{4\times4})w^{(X)}\right)(s)\dd s\\
=&\left(\delta_{k_0}^0T(k_0)\right)^{\Sigma_3}
\mu_1^{(PC)}(\rho(k_0))\left(\delta_{k_0}^0T(k_0)\right)^{-\Sigma_3}.\nn
\end{align}
Thus, with $z=\sqrt{k_0^{-3}t}(k-k_0)$, by \eqref{3.99}, the solution of $\mu^{(k_0)}(\zeta,t;k)$ to RH problem \ref{rhp3.5} admits the following expansion:
\be\label{3.105}
\mu^{(k_0)}(\zeta,t;k)=\mathbb{I}_{4\times4}
+\frac{\mu^{(k_0)}_1(\zeta,t)}{\sqrt{k_0^{-3}t}(k-k_0)}+O\left(\frac{\ln t}{t}\right),\quad t\rightarrow\infty,
\ee
with
\begin{align}
\mu^{(k_0)}_1(\zeta,t)=&\begin{pmatrix}\mathbf{0}_{2\times2}&
\ii(\delta_{k_0}^0)^2T^2(k_0)\beta^{(k_0)}\\ -\ii(\delta_{k_0}^0)^{-2}T^{-2}(k_0)\left(\beta^{(k_0)}\right)^\dag
&\mathbf{0}_{2\times2}\end{pmatrix},\label{muk0}\\
\beta^{(k_0)}=&\frac{
\sqrt{2\pi}\e^{\frac{3\ii\pi}{4}-\frac{\pi\nu(k_0)}{2}}}
{\Gamma(\ii\nu(k_0))\det[\rho(k_0)]}\begin{pmatrix}
\rho_{22}(k_0) & -\rho_{12}(k_0)\\ -\rho_{21}(k_0) & \rho_{11}(k_0)
\end{pmatrix}.\label{betak0}
\end{align}

For the RH problem \ref{rhp3.6}, proceeding the calculation in the same way, we conclude that the solution $\mu^{(-k_0)}(\zeta,t;k)$ satisfies the following asymptotic behavior
\be\label{3.108}
\mu^{(-k_0)}(\zeta,t;k)
=\mathbb{I}_{4\times4}+\frac{\mu_{1}^{(-k_0)}(\zeta,t)}{\sqrt{k_0^{-3}t}(k+k_0)}+O\left(\frac{\ln t}{t}\right),
\ee
where
\begin{align}
\mu^{(-k_0)}_1(\zeta,t)=&\begin{pmatrix}\mathbf{0}_{2\times2}&
-\ii(\delta_{-k_0}^0)^2T^2(-k_0)\beta^{(-k_0)}\\ \ii(\delta_{-k_0}^0)^{-2}T^{-2}(-k_0)\left(\beta^{(-k_0)}\right)^\dag
&\mathbf{0}_{2\times2}\end{pmatrix},\label{mu-k0}\\
\beta^{(-k_0)}&=\frac{
\sqrt{2\pi}\e^{\frac{\ii\pi}{4}-\frac{\pi\nu(k_0)}{2}}}
{\Gamma(-\ii\nu(k_0))\det[\rho(-k_0)]}\begin{pmatrix}
\rho_{22}(-k_0) & -\rho_{12}(-k_0)\\ -\rho_{21}(-k_0) & \rho_{11}(-k_0)
\end{pmatrix},\label{beta-k0}\\
\delta_{-k_0}^0&=\e^{\chi_{k_0}(-k_0)+\frac{t}{2\ii k_0}}(4k_0^{-1}t)^{-\frac{\ii\nu(k_0)}{2}}.\label{3.117}
\end{align}
\subsubsection{Small norm RH problem for error function}\label{sec3.4.3}
Now, we consider the error function $E(k)$. Assume the boundaries of $U_{\pm k_0}$ are oriented counterclockwise. Denote $$\Gamma^{(E)}=\partial U_{\pm k_0}\cup(\Gamma\setminus U_{\pm k_0}).$$ From the definition \eqref{3.60}, we know that $E(k)$ satisfies the following $4\times4$ matrix RH problem.

\begin{rhp}\label{rhp3.8}
Find a $4\times4$ matrix-valued function $E(k)$ with the following properties:
\begin{itemize}
\item Analyticity: $E(k)$ is analytic in $\bfC\setminus\Gamma^{(E)}$.

\item Jump condition: The continuous boundary values $E_\pm(k)$ on $\Gamma^{(E)}$ satisfy the following jump relation
\be
E_+(k)=E_-(k)J^{(E)}(k),
\ee
where the jump matrix is given by
\be
J^{(E)}(k)=\left\{\begin{aligned}
&\mu^{(out)}(\zeta,t;k)J^{(2)}(\zeta,t;k)[\mu^{(out)}(\zeta,t;k)]^{-1},\qquad k\in\Gamma\setminus U_{\pm k_0},\\
&\mu^{(out)}(\zeta,t;k)\mu^{(\pm k_0)}(\zeta,t;k)[\mu^{(out)}(\zeta,t;k)]^{-1},\quad k\in\partial U_{\pm k_0}.
\end{aligned}
\right.
\ee
\item Normalization: $E(k)\rightarrow\mathbb{I}_{4\times4},$ as $k\rightarrow\infty.$
\end{itemize}
\end{rhp}
By Proposition \ref{pro2.5} and \ref{prop3.1}, we have the estimate
\be\label{3.112}
\left|J^{(E)}(k)-\mathbb{I}_{4\times4}\right|\leq c\e^{-\frac{\sqrt{2}t|k\mp k_0|}{4}(k_0^{-2}-|k|^{-2})}\leq c\e^{-\frac{\sqrt{2}t\epsilon}{16k_0}},\ \text{for}\ k\in\Gamma\setminus U_{\pm k_0}.
\ee
For $k\in\partial U_{\pm k_0}$, by \eqref{3.105} and \eqref{3.108}, one can get
\be\label{3.113}
\left|J^{(E)}(k)-\mathbb{I}_{4\times4}\right|=\left|\mu^{(out)}(\zeta,t;k)(\mu^{(\pm k_0)}(\zeta,t;k)-\mathbb{I}_{4\times4})[\mu^{(out)}(\zeta,t;k)]^{-1}\right|\leq ct^{-1/2}.
\ee
The existence and uniqueness of solution to RH problem \ref{rhp3.8} follows from the theory of small-norm RH problems. In fact, let $w^{(E)}=J^{(E)}-\mathbb{I}_{4\times4}$ and $\mathcal{C}_{w^{(E)}}f\doteq\mathcal{C}_-(fw^{(E)})$, where we have chosen, for simplicity, $w^{(E)}_+=w^{(E)}$ and $w^{(E)}_-=\mathbf{0}_{4\times4}$. Then the solution of the RH problem \ref{rhp3.8} can be given by
\be\label{3.116}
E(k)=\mathbb{I}_{4\times4}+
\frac{1}{2\pi\ii}\int_{\Gamma^{(E)}}\frac{(\mu^{(E)}w^{(E)})(s)}{s-k}\dd s,
\ee
where the $4\times4$ matrix-valued function $\mu^{(E)}(x,t;k)$ defined by $\mu^{(E)}=\mathbb{I}_{4\times4}+\mathcal{C}_{w^{(E)}}\mu^{(E)}.$
By \eqref{3.112} and \eqref{3.113}, we find
\be
\|\mathcal{C}_{w^{(E)}}\|_{\mathcal{B}(L^2(\Gamma^{(E)}))}\leq c\|w^{(E)}\|_{L^\infty(\Gamma^{(E)})}\leq ct^{-1/2},
\ee
where $\mathcal{B}(L^2(\Gamma^{(E)}))$ denotes the bounded linear operators $L^2(\Gamma^{(E)})\rightarrow L^2(\Gamma^{(E)})$. Hence, the resolvent operator $(1-\mathcal{C}_{w^{(E)}})^{-1}$ is existent and thus of both $\mu^{(E)}$ and $E$.
Moreover, using the Neumann series, the function $\mu^{(E)}(k)$ satisfies
\be
\|\mu^{(E)}(k)-\mathbb{I}_{4\times4}\|_{L^2(\Gamma^{(E)})}=O(t^{-1/2}),\quad t\rightarrow\infty.
\ee
Now, it can be explained that the definition of $\mu^{(RHP)}$ in \eqref{3.60} is reasonable.

In order to reconstruct the solution of system \eqref{ccSPE}, we need the asymptotic behavior of $E(k)$ as $k\to0$. It follows from \eqref{3.116} that, as $k\to0$
\begin{align}
E(k)=E(0)+E_1k+O(k^2),
\end{align}
where
\begin{align}
E(0)=&\mathbb{I}_{4\times4}+
\frac{1}{2\pi\ii}\int_{\Gamma^{(E)}}\frac{(\mu^{(E)}w^{(E)})(s)}{s}\dd s,\\
E_1=&
\frac{1}{2\pi\ii}\int_{\Gamma^{(E)}}\frac{(\mu^{(E)}w^{(E)})(s)}{s^2}\dd s.
\end{align}
Then, the large time asymptotic behavior of $E(0)$ and $E_1$ can be derived as
\begin{align}\label{3.126}
E(0)-\mathbb{I}_{4\times4}=&
\frac{1}{2\pi\ii}\int_{\Gamma^{(E)}}\frac{(\mu^{(E)}w^{(E)})(s)}{s}\dd s\\
=&\frac{1}{2\pi\ii}\int_{\Gamma^{(E)}}\frac{(\mu^{(E)}(s)-\mathbb{I}_{4\times4})w^{(E)}(s)}{s}\dd s+\frac{1}{2\pi\ii}\int_{\Gamma^{(E)}}\frac{w^{(E)}(s)}{s}\dd s\nn\\
=&\frac{1}{2\pi\ii}\int_{\partial U_{\pm k_0}}\frac{w^{(E)}(s)}{s}\dd s+O(\|\mu^{(E)}-\mathbb{I}_{4\times4}\|_{L^2(\Gamma^{(E)})}\|w^{(E)}\|_{L^\infty(\Gamma^{(E)})})\nn\\
&+O(\|s^{-1}\|_{L^2(\Gamma\setminus U_{\pm k_0})}\|w^{(E)}\|_{L^2(\Gamma\setminus U_{\pm k_0})})\nn\\
=&\frac{1}{2\pi\ii}\int_{\partial U_{\pm k_0}}\frac{\mu^{(out)}(s)(\mu^{(\pm k_0)}(s)-\mathbb{I}_{4\times4})[\mu^{(out)}(s)]^{-1}}{s}\dd s+O(t^{-1})\nn\\
=&t^{-1/2}\mathcal{E}_0+O(t^{-1}\ln t),\nn
\end{align}
and
\begin{align}\label{eq3.127}
E_1=
\frac{1}{2\pi\ii}\int_{\Gamma^{(E)}}\frac{(\mu^{(E)}w^{(E)})(s)}{s^2}\dd s=t^{-1/2}\mathcal{E}_1+O(t^{-1}\ln t).
\end{align}
where
\begin{align}
\mathcal{E}_0=&\sqrt{k_0}\left(\mu^{(out)}(\zeta,t;k_0)\mu_1^{( k_0)}(\zeta,t)[\mu^{(out)}(\zeta,t;k_0)]^{-1}\right.\\
&+\left.\mu^{(out)}(\zeta,t;-k_0)\mu_1^{( -k_0)}(\zeta,t)[\mu^{(out)}(\zeta,t;-k_0)]^{-1}\right),\nn\\
\mathcal{E}_1=&\frac{1}{\sqrt{k_0}}\left(\mu^{(out)}(\zeta,t;k_0)\mu_1^{( k_0)}(\zeta,t)[\mu^{(out)}(\zeta,t;k_0)]^{-1}\right.\label{eq3.128e1}\\
&+\left.\mu^{(out)}(\zeta,t;-k_0)\mu_1^{( -k_0)}(\zeta,t)[\mu^{(out)}(\zeta,t;-k_0)]^{-1}\right).\nn
\end{align}
\subsection{Analysis on the $\bar{\partial}$-problem}\label{sec3.5}
Next, we investigate the existence and long-time asymptotics of \(\mu_{3}(\zeta,t;k)\). The associated pure \(\bar{\partial}\)-problem \ref{dbar1} is equivalent to the corresponding integral equation
\begin{equation}\label{3.119}
	\mu^{(3)}(k) = \mathbb{I}_{4\times4} - \frac{1}{\pi}\iint\limits_{\mathbb{C}}\frac{\mu^{(3)}(s)w^{(3)}(s)}{s-k}\text{d}m(s),
\end{equation}
where \(m(s)\) represents the Lebesgue measure on \(\mathbb{C}\). We define $ C_k$ as the left Cauchy-Green integral operator,
\begin{equation}\label{3.120}
	C_k[f](k) = -\frac{1}{\pi}\iint\limits_{\mathbb{C}}\frac{f(s)w^{(3)}(s)}{s-k}\text{d}m(s).
\end{equation}
Thus, the Equation \eqref{3.119} can be rewritten as
\begin{equation}\label{3.121}
	(1-C_k)\mu^{(3)}(k) = \mathbb{I}_{4\times 4}.
\end{equation}
According to formula \eqref{3.121}, the solution $\mu^{(3)}(k)$ exists if and only if the inverse operator \((1-C_k)^{-1}\) exists. Therefore, our goal is to prove that the operator \((1-C_k)\) is invertible. To achieve this, we first present the following proposition.
\begin{proposition}
As $t\to\infty$, the norm of the integral operator $C_k$ decays to zero, specifically,
	\begin{equation}
	\| C_k\|_{L^{\infty}\to L^{\infty}} = O(t^{-1/6}),
	\end{equation}
which implies \((1-C_k)^{-1}\)exists.
\end{proposition}
\begin{proof}
	 Assume that $f\in L^{\infty}(\Omega_1)$, with $s = u + \ii v$ and $ k= x+\ii y$. Then, according to \eqref{3.120}, we have
	\begin{align}
		|C_k[f](k)| &\leq \|f(k)\|_{L^{\infty}}\frac{1}{\pi}\iint\limits_{\mathbb{C}}\frac{|w^{(3)}(s)|}{|s-k|}\text{d}m(s) \nn \\
		&\leq c\iint\limits_{\mathbb{C}}\frac{|\bar{\partial}R^{(2)}(s)|}{|s-k|}\text{d}m(s).
	\end{align}
Thus, it remains to estimate the above integral. For $\bar{\partial}R^{(2)}(s)$ is a piece-wise function, we focus specifically on the case where the matrix function is supported in region $\Omega_1$, as the other cases can be proved similarly. From \eqref{3.34} and \eqref{3.51}, it follows that
\begin{equation}
	\iint\limits_{\Omega_1}\frac{|\bar{\partial}R^{(2)}(s)|}{|s-k|}\text{d}m(s)\leq I_1 + I_2 + I_3,
\end{equation}
where
\begin{align}
	 I_1 =& \int_{0}^{+\infty}\int_{k_0 + v}^{+\infty}\frac{|\bar{\partial}\chi(s)|\e^{\frac{vt}{2(u^2+v^2)}}}{\sqrt{(u-x)^2+(v-y)^2}}
\text{d}u\e^{2tv\hat{\zeta}}\text{d}v, \\
	  I_2 =& \int_{0}^{+\infty}\int_{k_0 + v}^{+\infty}\frac{|\rho'(u)|\e^{\frac{vt}{2(u^2+v^2)}}}{\sqrt{(u-x)^2+(v-y)^2}}
\text{d}u\e^{2tv\hat{\zeta}}\text{d}v, \\
	\label{3.127}  I_3 =& \int_{0}^{+\infty}\int_{k_0 + v}^{+\infty}\frac{\left((u-k_0)^2+v^2\right)^{-1/4}\e^{\frac{vt}{2(u^2+v^2)}}}
{\sqrt{(u-x)^2+(v-y)^2}}\text{d}u\e^{2tv\hat{\zeta}}\text{d}v.
\end{align}
In the subsequent calculations, we will make use of the inequality
\begin{equation}\label{3.128}
	\left\|\frac{1}{s-k}\right\|^2_{L^2(k_0,+\infty)} = \int_{k_0}^{+\infty}\frac{1}{|v-y|}\left[\left(\frac{u-x}{v-y}\right)^2+1\right]^{-1} \text{d}\left(\frac{u-x}{|v-y|}\right)\leq \frac{\pi}{|v-y|}.
\end{equation}
Given that \(\frac{vt}{2(u^2+v^2)}\) is monotonically decreasing with respect to \(u\), so \(I_1\) admits the following estimates
\begin{align}
	I_1 & \leq \int_0^{+\infty}\left\||s-k|^{-1}\right\|_{L^2\left(k_0,+\infty\right)}\left\|\bar{\partial} \chi(s)\right\|_{L^2\left(k_0,+\infty\right)} \e^{\frac{v t}{2\left(k_0^2+v^2\right)}} \e^{2 t v \hat{\zeta}} \text{d} v \label{3.129}\\
	& \leq c\int_0^{+\infty}|v-y|^{-1 / 2} \exp \left(-\frac{vt}{2}\left(\frac{1}{k_0^2}-\frac{1}{k_0^2+v^2}\right)\right) \text{d} v \nn\\
	& =c\int_0^y(y-v)^{-1 / 2} \exp \left(-\frac{vt}{2}\left(\frac{1}{k_0^2}-\frac{1}{k_0^2+v^2}\right)\right) \text{d} v \nn\\
	& +c\int_{y}^{+\infty}(v-y)^{-1 / 2}\exp \left(-\frac{vt}{2}\left(\frac{1}{k_0^2}-\frac{1}{k_0^2+v^2}\right)\right) \text{d} v.\nn
\end{align}
Since $e^{-z}\leq cz^{-1/6}$ for all $z>0 $, the first integral can then be estimated by
\begin{align}
	 &\int_0^y(y-v)^{-1 / 2} \exp \left(-\frac{vt}{2}\left(\frac{1}{k_0^2}-\frac{1}{k_0^2+v^2}\right)\right) \text{d} v  \label{3.130}\\
	 &\leq c\int_{0}^{y}(y-v)^{-1 / 2}v^{-1/2}t^{-1/6}\text{d}v \leq ct^{-1/6}.\nn
\end{align}
In addition, considering the remaining integral and letting $w = v-y$, we have
\begin{align}
	&\int_{y}^{+\infty}(v-y)^{-1 / 2}\exp \left(-\frac{vt}{2}\left(\frac{1}{k_0^2}-\frac{1}{k_0^2+v^2}\right)\right) \text{d} v  \label{3.131}\\
	&= \int_{y}^{+\infty}(v-y)^{-1 / 2}\exp\left(-\frac{vt}{2}\left(\frac{v^2}{k_0^2(v^2+k_0^2)}\right)\right) \text{d} v \nn\\
	&\leq \int_{y}^{+\infty}(v-y)^{-1 / 2}\exp\left(-\frac{vty^2}{2k_0^2(y^2+k_0^2)}\right) \text{d} v \nn\\
	&\leq \int_{0}^{+\infty}w^{-1/2}\exp\left(-\frac{wty^2}{2k_0^2(y^2+k_0^2)}\right)\text{d}w \exp\left(-\frac{ty^3}{2k_0^2(y^2+k_0^2)}\right)\leq ct^{-1/2}.\nn
\end{align}
Inserting \eqref{3.130} and \eqref{3.131} into \eqref{3.129} yields
\begin{equation}\label{3.132}
	I_1\leq ct^{-1/6}.
\end{equation}
$I_2$ satisfies the same estimate as \eqref{3.132}, and for $I_3$, we first obtain
\begin{align}
	&\left\| \left((u-k_0)^2+v^2\right)^{-1/4}\right\|_{L^{p}(k_0,+\infty)} \label{3.133} \\
	&=\left\{\int_{k_0}^{+\infty}\left[(u-k_0)^2+v^2\right]^{-p/4}\text{d} u\right\}^{1/p}\nn\\
	&= \left\{\int_{k_0}^{+\infty}\left[\left(\frac{u-k_0}{v}\right)^2+1 \right]^{-p/4}\text{d}\left(\frac{u-k_0}{v}\right)\right\}^{1/p}v^{1/p-1/2} \nn\\
	&\leq cv^{1/p-1/2},\nn
\end{align}
and
\begin{align}
	\left\| \frac{1}{|s-k|}\right\|_{L^q(k_0,+\infty)} &= \left\{\int_{k_0}^{+\infty}\left[\left(\frac{u-x}{v-y}\right)^2+1\right]^{-q/2} \text{d}\left(\frac{u-x}{|v-y|}\right)\right\}^{1/q}|v-y|^{1/q-1}\label{3.134} \\
	&\leq c|v-y|^{1/q-1},\nn
\end{align}
where $ p>2$ and $\frac{1}{p}+\frac{1}{q} = 1$. By examining \eqref{3.127}, we arrive that
\begin{align}
	I_3 &\leq\int_{0}^{+\infty} \left\||s-k|^{-1}\right\|_{L^q\left(k_0,+\infty\right)}\left\| \left((u-k_0)^2+v^2\right)^{-1/4}\right\|_{L^{p}(k_0,+\infty)} \e^{\frac{v t}{2\left(k_0^2+v^2\right)}} \e^{2 t v \hat{\zeta}} \text{d} v  \\
	&\leq \int_{0}^{+\infty}v^{1/p-1/2}|v-y|^{1/q-1}\exp \left(-\frac{vt}{2}\left(\frac{1}{k_0^2}-\frac{1}{k_0^2+v^2}\right)\right) \text{d}v \nn \\
	&=\int_{0}^{y}v^{1/p-1/2}(y-v)^{1/q-1}\exp \left(-\frac{vt}{2}\left(\frac{1}{k_0^2}-\frac{1}{k_0^2+v^2}\right)\right) \text{d}v \nn \\
	&+\int_{y}^{+\infty}v^{1/p-1/2}(v-y)^{1/q-1}\exp \left(-\frac{vt}{2}\left(\frac{1}{k_0^2}-\frac{1}{k_0^2+v^2}\right)\right) \text{d}v.\nn
\end{align}
The first integral can then be estimated by
	\begin{align}
		&\int_{0}^{y}v^{1/p-1/2}(y-v)^{1/q-1}\exp \left(-\frac{vt}{2}\left(\frac{1}{k_0^2}-\frac{1}{k_0^2+v^2}\right)\right) \text{d}v \\
		&\leq c\int_{0}^{y}v^{1/p-1}(y-v)^{1/q-1} t^{-1/6} \text{d}v \leq ct^{-1/6}.\nn
	\end{align}
Moreover, considering the remaining integral with $w = v-y$, we have
\begin{align}
	&\int_{y}^{+\infty}v^{1/p-1/2}(v-y)^{1/q-1}\exp \left(-\frac{vt}{2}\left(\frac{1}{k_0^2}-\frac{1}{k_0^2+v^2}\right)\right) \text{d}v  \\
	&\leq \int_{0}^{+\infty}(w+y)^{1/p-1/2}w^{1/q-1}\exp\left(-\frac{wty^2}{2k_0^2(y^2+k_0^2)}\right)\text{d}w \exp\left(-\frac{ty^3}{2k_0^2(y^2+k_0^2)}\right) \nn \\
	&\leq c\int_{0}^{+\infty}w^{-1/2}\exp\left(-\frac{wty^2}{2k_0^2(y^2+k_0^2)}\right)\text{d}w \leq ct^{-1/2}.\nn
\end{align}
Finally, we obtain
\begin{equation}
	I_3\leq ct^{-1/6}.
\end{equation}
Collecting the above results, the proof of the proposition is thus completed.

\end{proof}
Next, to achieve the final goal of reconstructing the potential $(q_1(x,t)\quad q_2(x,t))$ as $t\to\infty$, we need to analyze the asymptotic expansion of $\mu^{(3)}(\zeta,t;k)$ as $k\to 0$. We expand the $\mu^{(3)}(\zeta,t;k)$ as
\begin{equation}
	\mu^{(3)}(\zeta,t;k) = \mathbb{I}_{4\times 4} + \mu^{(3)}_0(\zeta,t)+\mu^{(3)}_1(\zeta,t)k + O(k^2),\quad k\to 0,
\end{equation}
where
\begin{align}
\label{3.140}	\mu^{(3)}_0(\zeta,t) &= -\frac{1}{\pi}\iint\limits_{\mathbb{C}}\frac{\mu^{(3)}(s)w^{(3)}(s)}{s}\text{d}m(s), \\
	\label{3.141}\mu^{(3)}_1(\zeta,t)&=-\frac{1}{\pi}\iint\limits_{\mathbb{C}}\frac{\mu^{(3)}(s)w^{(3)}(s)}{s^2}\text{d}m(s).
\end{align}
Then, $\mu^{(3)}_0(\zeta,t)$ and $\mu^{(3)}_1(\zeta,t)$ satisfy the following properties.
\begin{proposition}\label{pro3.5}
	As $t\to\infty$, the following estimate holds for $\mu^{(3)}(\zeta,t;0)$, that is,
	\begin{equation}
		\|\mu^{(3)}(\zeta,t;0)-\mathbb{I}_{4\times 4}\| = \|\mu^{(3)}_0(\zeta,t)\| \leq ct^{-1}.
	\end{equation}
\end{proposition}
\begin{proof}
	We first consider the case $k\in\Omega_1$, and the proofs for the other cases follow analogously. Applying \eqref{3.34} and \eqref{3.140}, and taking into account the boundedness of $\mu^{(3)}(k)$ and $\mu^{(RHP)}(k)$, we drive
\begin{align}
	\|\mu^{(3)}_0(\zeta,t)\| &\leq \frac{1}{\pi}\iint\limits_{\Omega_1}\frac{|\mu^{(3)}(s)\mu^{(RHP)}(s)\bar{\partial}
		\mathcal{R}^{(2)}(s)[\mu^{(RHP)}(s)]^{-1}|}{|s|}\text{d}m(s) \\
		&\leq c\int_{0}^{+\infty}\int_{k_0+v}^{+\infty}\frac{|\bar{\partial}R_1(s)|
\e^{\frac{vt}{2(u^2+v^2)}}}{(u^2+v^2)^{1/2}}\e^{2tv\hat{\zeta}}\text{d}u\text{d}v \nn\\
		&\leq c(I_4+I_5+I_6),\nn
\end{align}
where $s= u+\ii v$, and
\begin{align}
	I_4 =& \int_{0}^{+\infty}\int_{k_0 + v}^{+\infty}\frac{|\bar{\partial}\chi(s)|\e^{\frac{vt}{2(u^2+v^2)}}}{(u^2+v^2)^{1/2}}
\text{d}u\e^{2tv\hat{\zeta}}\text{d}v, \\
	I_5 =& \int_{0}^{+\infty}\int_{k_0 + v}^{+\infty}\frac{|\rho'(u)|\e^{\frac{vt}{2(u^2+v^2)}}}{(u^2+v^2)^{1/2}}
\text{d}u\e^{2tv\hat{\zeta}}\text{d}v, \\
  I_6 =& \int_{0}^{+\infty}\int_{k_0 + v}^{+\infty}\frac{\left((u-k_0)^2+v^2\right)^{-1/4}
  \e^{\frac{vt}{2(u^2+v^2)}}}{(u^2+v^2)^{1/2}}\text{d}u\e^{2tv\hat{\zeta}}\text{d}v.
\end{align}
To facilitate the estimation, we split $I_4$ into two parts
\begin{equation}
	I_4=\int_{0}^{k_0}\int_{k_0 + v}^{+\infty}\frac{|\bar{\partial}\chi(s)|\e^{\frac{vt}{2(u^2+v^2)}}}{(u^2+v^2)^{1/2}}
\text{d}u\e^{2tv\hat{\zeta}}\text{d}v +\int_{k_0}^{+\infty}\int_{k_0 + v}^{+\infty}\frac{|\bar{\partial}\chi(s)|\e^{\frac{vt}{2(u^2+v^2)}}}
{(u^2+v^2)^{1/2}}\text{d}u\e^{2tv\hat{\zeta}}\text{d}v.
	\end{equation}
	For the first integral, we have
\begin{align}
		&\int_{0}^{k_0}\int_{k_0 + v}^{+\infty}\frac{|\bar{\partial}\chi(s)|\e^{\frac{vt}{2(u^2+v^2)}}}{(u^2+v^2)^{1/2}}
\text{d}u\e^{2tv\hat{\zeta}}\text{d}v  \\
		& \leq c\int_0^{k_0}\left(\left(v+k_0\right)^2+v^2\right)^{-1 / 2}\exp\left(-\frac{vt}{2}\left(\frac{1}{k_0^2}-\frac{1}{(v+k_0)^2+v^2}\right)\right)
\text{d}v \nn\\
		&\leq c\int_0^{k_0}\left(\left(v+k_0\right)^2+v^2\right)^{-1 / 2}\exp\left(\frac{vt}{2((v+k_0)^2+v^2)}\right)\text{d}v \nn\\
		&\leq c\int_{0}^{k_0}\exp\left(\frac{vt}{2k_0^2}\right)\text{d}v
		\leq ct^{-1}.\nn
\end{align}
	For the last integral, by applying \eqref{3.128} with $y=0$, we obtain
\begin{align}
	&\int_{k_0}^{+\infty}\int_{k_0 + v}^{+\infty}\frac{|\bar{\partial}\chi(s)|\e^{\frac{vt}{2(u^2+v^2)}}}{(u^2+v^2)^{1/2}}
\text{d}u\e^{2tv\hat{\zeta}}\text{d}v \\
	&\leq \int_{k_0}^{+\infty}\left\||s|^{-1}\right\|_{L^2}\left\|\bar{\partial} \chi(s)\right\|_{L^2}\exp\left(-\frac{vt}{2}\left(\frac{1}{k_0^2}-\frac{1}{(v+k_0)^2+v^2}\right)\right) \text{d}v \nn\\
	&\leq c\int_{k_0}^{+\infty} v^{-1/2}\exp\left(-\frac{2tv}{5k_0^2}\right)\text{d}v \nn\\
	&\leq c\int_{k_0}^{+\infty}\exp\left(-\frac{2tv}{5k_0^2}\right)\text{d}v \leq ct^{-1}.\nn
\end{align}
	A similar estimate for $I_5$ can be obtained in the same manner.
	As with $I_4$, we split $I_6$ into two parts to facilitate the estimation
	\begin{align}
		I_6 &= \int_{0}^{k_0}\int_{k_0 + v}^{+\infty}\frac{\left((u-k_0)^2+v^2\right)^{-1/4}\e^{\frac{vt}{2(u^2+v^2)}}}
{(u^2+v^2)^{1/2}}\text{d}u\e^{2tv\hat{\zeta}}\text{d}v\\
		&+\int_{k_0}^{+\infty}\int_{k_0 + v}^{+\infty}\frac{\left((u-k_0)^2+v^2\right)^{-1/4}
\e^{\frac{vt}{2(u^2+v^2)}}}{(u^2+v^2)^{1/2}}\text{d}u\e^{2tv\hat{\zeta}}\text{d}v. \nn
	\end{align}
	Given that
	\begin{align}
		&\left\|(u^2+v^2)^{-1/2}\exp\left(\frac{vt}{2(u^2+v^2)}\right)\right\|_{L^4(k_0+v,+\infty)} \\
		&= \left\{\int_{k_0+v}^{+\infty}(u^2+v^2)^{-2}\exp\left(\frac{2vt}{u^2+v^2}\right)
\text{d}u\right\}^{1/4} \nn \\
		&= \left\{\int_{k_0+v}^{+\infty}(-4t)^{-1}v^{-1}u^{-1}
\left[\exp\left(\frac{2vt}{u^2+v^2}\right)\right]'\text{d}u\right\}^{1/4} \nn\\
		&\leq ct^{-1/4}v^{-1/4}\left(\exp\left(\frac{vt}{2((k_0+v)^2+v^2)}\right)+1\right).\nn
	\end{align}
	An estimate for the first integral can be given by combining \eqref{3.133}
	\begin{align}
	&\int_{0}^{k_0}\int_{k_0 + v}^{+\infty}\frac{\left((u-k_0)^2+v^2\right)^{-1/4}\e^{\frac{vt}{2(u^2+v^2)}}}
{(u^2+v^2)^{1/2}}\text{d}u\e^{2tv\hat{\zeta}}\text{d}v	 \\
	&\leq \int_{0}^{k_0}\left\|\left((u-k_0)^2+v^2\right)^{-1/4}\right\|_{L^{4/3}}
\left\|(u^2+v^2)^{-1/2}\exp\left(\frac{vt}{2(u^2+v^2)}\right)\right\|_{L^4}
\e^{2tv\hat{\zeta}}\text{d}v\nn\\
	&\leq ct^{-1/4}\int_{0}^{k_0}v^{3/4-1/2}v^{-1/4}
\left(\exp\left(\frac{vt}{2((k_0+v)^2+v^2)}\right)+1\right)\e^{-\frac{vt}{2k_0^2}}\text{d}v \nn\\
	&\leq ct^{-1/4}\int_{0}^{k_0}\exp\left(-\frac{vt}{2k_0^2}\right)\text{d}v \leq ct^{-5/4}.\nn
	\end{align}
	Let $p>2$ satisfy $\frac{1}{p}+\frac{1}{q}=1$. Then, by applying \eqref{3.133} and \eqref{3.134}, we estimate the second integral as follows:
	\begin{align}
		&\int_{k_0}^{+\infty}\int_{k_0 + v}^{+\infty}\frac{\left((u-k_0)^2+v^2\right)^{-1/4}\e^{\frac{vt}{2(u^2+v^2)}}}
{(u^2+v^2)^{1/2}}\text{d}u\e^{2tv\hat{\zeta}}\text{d}v \\
		&\leq \int_{k_0}^{+\infty} \left\||s|^{-1}\right\|_{L^q}\left\| \left((u-k_0)^2+v^2\right)^{-1/4}\right\|_{L^{p}} \exp\left(-\frac{vt}{2}\left(\frac{1}{k_0^2}-\frac{1}{(v+k_0)^2+v^2}\right)\right) \text{d} v \nn\\
		&\leq c\int_{k_0}^{+\infty} v^{-1/2}\exp\left(-\frac{2tv}{5k_0^2}\right)\text{d}v \nn \\
		&\leq c\int_{k_0}^{+\infty}\exp\left(-\frac{2tv}{5k_0^2}\right)\text{d}v  \leq ct^{-1}.\nn
	\end{align}
	Therefore, we obtain we conclude that
	\begin{equation}
		I_6\leq ct^{-1}.
	\end{equation}
 In summary, based on the above analysis, we complete the proof of the proposition.
\end{proof}
 \begin{proposition}\label{prop3.6}
 	As $t\to\infty$, the following estimate for $\mu^{(3)}_1(\zeta,t)$ holds:
 \begin{equation}
 	\|\mu^{(3)}_1(\zeta,t)\|\leq ct^{-1}.
 \end{equation}
 \end{proposition}
 \begin{proof}
 	We focus on estimating the integral over $\Omega_1$, as the estimates for the other regions are similar. Similar to the previous proposition, we set $s= u+iv$. By applying \eqref{3.34}, \eqref{3.51} and \eqref{3.141}, we derive the following result
 	\begin{align}
 		\|\mu_1^{(3)}(\zeta,t)\| &\leq \frac{1}{\pi}\iint\limits_{\Omega_1}\frac{|\mu^{(3)}(s)\mu^{(RHP)}(s)\bar{\partial}
 			\mathcal{R}^{(2)}(s)[\mu^{(RHP)}(s)]^{-1}|}{|s|^2}\text{d}m(s) \nn \\
 			&\leq c\int_{0}^{+\infty}\int_{k_0+v}^{+\infty}\frac{|\bar{\partial}R_1(s)|\e^{\frac{vt}{2(u^2+v^2)}}}{u^2+v^2}\e^{2tv\zeta}\text{d}u\text{d}v \nn\\
 			&\leq c(I_7+I_8+I_9),
 	\end{align}
 	where
 	\begin{align}
 			I_7 =& \int_{0}^{+\infty}\int_{k_0 + v}^{+\infty}\frac{|\bar{\partial}\chi(s)|\e^{\frac{vt}{2(u^2+v^2)}}}{u^2+v^2}
 \text{d}u\e^{2tv\hat{\zeta}}\text{d}v, \\
 		I_8 =& \int_{0}^{+\infty}\int_{k_0 + v}^{+\infty}\frac{|\rho'(u)|\e^{\frac{vt}{2(u^2+v^2)}}}{u^2+v^2}
 \text{d}u\e^{2tv\hat{\zeta}}\text{d}v, \\
 		I_9 =& \int_{0}^{+\infty}\int_{k_0 + v}^{+\infty}\frac{\left((u-k_0)^2+v^2\right)^{-1/4}
 \e^{\frac{vt}{2(u^2+v^2)}}}{u^2+v^2}\text{d}u\e^{2tv\hat{\zeta}}\text{d}v.
 	\end{align}
 	Observe that for all $s\in\Omega_1$, it holds that
 	\begin{equation}
 		(u^2+v^2)^{-1/2}\leq \frac{1}{k_0}.
 	\end{equation}
 	Consequently, we obtain
 	\begin{equation}
 		I_j\leq \frac{1}{k_0}I_{j-3}, \quad \text{for}\ j= 7,8,9.
 	\end{equation}
 	Hence, the conclusion readily follows from Proposition \ref{pro3.5}.


 \end{proof}


\subsection{Long-time asymptotics for the ccSPE}\label{sec3.6}
We now put together our previous results and formulate the long-time asymptotic formula of $\begin{pmatrix}q_1(x,t)&q_2(x,t)\end{pmatrix}$ in region $\hat{\zeta}<-\varepsilon$. Undoing all transformations carried out previously, we have
\be
\breve{\mu}(\zeta,t;k)=\mu^{(3)}(\zeta,t;k)E(k)\mu^{(out)}(\zeta,t;k)
[\mathcal{R}^{(2)}(k)]^{-1}[T(k)]^{\Sigma_3}[\tilde{\Delta}(k)]^{-1},\quad k\in\bfC\setminus U_{\pm k_0}.
\ee
Moreover, by \eqref{3.6} and \eqref{3.8}, as $k\to0$, we have
\begin{align}
[\tilde{\Delta}(k)]^{-1}=\tilde{\Delta}_0+\tilde{\Delta}_1k+O(k^2),\
T(k)=T(0)(1+T_1k)+O(k^2),\end{align}
where
\begin{align}
\tilde{\Delta}_0=&\begin{pmatrix} \delta_{10} & \mathbf{0}_{2\times2}\\
\mathbf{0}_{2\times2} & \delta_{20}^{-1}\end{pmatrix},\
\tilde{\Delta}_1=\begin{pmatrix} \delta_{11} & \mathbf{0}_{2\times2}\\
\mathbf{0}_{2\times2} & -\delta_{20}^{-1}\delta_{21}\delta_{20}^{-1}\end{pmatrix},\\
T_1=&-4\ii\sum_{\substack{\text{Re}k_n\neq0,\text{Im}k_n>0\\n\in\Delta_{k_0}^-}}
\frac{\text{Im}k_n}{|k_n|^2}
-2\ii\sum_{\substack{\text{Re}k_n=0,\text{Im}k_n>0\\n\in\Delta_{k_0}^-}}
\frac{\text{Im}k_n}{|k_n|^2},
\end{align}
with $\delta_{10}$, $\delta_{11}$, $\delta_{20}$ and $\delta_{21}$ are $2\times2$ constant matrices independent of $k$.
We take $k\to0$ along the imaginary axis such that $\mathcal{R}^{(2)}(k)=\mathbb{I}_{4\times4}$. Expanding $\mu_{*}^{(out)}(\zeta,t;k)=\mu_*^{(out)}(\zeta,t;0)+\mu_{*1}^{(out)}(\zeta,t)k+O(k^2)$, it follows from \eqref{3.126}, \eqref{eq3.127}, Propositions \ref{pro3.5} and \ref{prop3.6} that
\begin{align}
&\lim_{k\to0}\frac{\left[\breve{\mu}^{-1}(\zeta,t;0)\breve{\mu}(\zeta,t;k)\right]_{UR}}{k}\\
=&
\left[\tilde{\Delta}_0^{-1}[T(0)]^{-\Sigma_3}[\mu^{(out)}_*(\zeta,t;0)]^{-1}
\mu^{(out)}_{*1}(\zeta,t)[T(0)]^{\Sigma_3}\tilde{\Delta}_0\right.\nn\\
&+t^{-1/2}\left.\tilde{\Delta}_0^{-1}[T(0)]^{-\Sigma_3}[\mu^{(out)}_*(\zeta,t;0)]^{-1}
\mathcal{E}_1\mu^{(out)}_*(\zeta,t;0)[T(0)]^{\Sigma_3}\tilde{\Delta}_0\right]_{UR}+O(t^{-1}\ln t).\nn
\end{align}
By the first symmetry in \eqref{3.5}, we find $\delta_{j0}^{-1}=\delta_{j0}^\dag$ for $j=1,2$. And hence, we can express
\be\label{3.180}
\delta_{j0}=\begin{pmatrix} a_j & b_j\\ -b_j^*\e^{\ii\phi_j} & a_j^*\e^{\ii\phi_j}\end{pmatrix},
\ee
where $a_j$, $b_j$ are complex constant, $\det[\delta_{j0}]=\e^{\ii\phi_j}$, $\phi_j=\arg\det[\delta_{j0}]$. Thus, by \eqref{eq3.77cb} and \eqref{3.78}, the $(1,3)$ and $(1,4)$-entries of $\tilde{\Delta}_0^{-1}[T(0)]^{-\Sigma_3}\ii[\mu^{(out)}_*(\zeta,t;0)]^{-1}
\mu^{(out)}_{*1}(\zeta,t)[T(0)]^{\Sigma_3}\tilde{\Delta}_0$ can be respectively written as
\begin{align}
\label{3.181}\tilde{q}_{1n}^{(\ell)}(\zeta,t)\doteq\left(\cdot\right)_{13}
=&T^{-2}(0)\left(\left(a_1^*q_{1n}^{(\ell)}(\zeta,t)
+b_1\e^{-\ii\phi_1}[q_{2n}^{(\ell)}(\zeta,t)]^*\right)a_2^*\right.\\
&+\left.\left(a_1^*q_{2n}^{(\ell)}(\zeta,t)
-b_1\e^{-\ii\phi_1}[q_{1n}^{(\ell)}(\zeta,t)]^*\right)b_2^*\right),\nn\\
\label{3.182}\tilde{q}_{2n}^{(\ell)}(\zeta,t)\doteq\left(\cdot\right)_{14}
=&T^{-2}(0)\left(\left(a_1^*q_{1n}^{(\ell)}(\zeta,t)
+b_1\e^{-\ii\phi_1}[q_{2n}^{(\ell)}(\zeta,t)]^*\right)(-b_2\e^{-\ii\phi_2})\right.\\
&+\left.\left(a_1^*q_{2n}^{(\ell)}(\zeta,t)
-b_1\e^{-\ii\phi_1}[q_{1n}^{(\ell)}(\zeta,t)]^*\right)a_2\e^{-\ii\phi_2}\right),\quad \ell=cb, sol.\nn
\end{align}
Finally, together with reconstruction formulae \eqref{2.50}-\eqref{2.51}, we arrive at the asymptotic result \eqref{1.4} described in Theorem \ref{th1.1}.

If $\zeta/t=v$ with $v<0$ but $v\neq v_n$ for all $n=1,\cdots,N$, then the solution $\mu^{(RHP)}$ of the RH problem \ref{rh3.2} should take the following form
\be
\mu^{(RHP)}(\zeta,t;k)=\left\{\begin{aligned}
&E(k),\qquad\qquad\qquad\,\,\, k\in\bfC\setminus U_{\pm k_0},\\
&E(k)\mu^{(k_0)}(\zeta,t;k),\quad\,\,\ k\in U_{k_0},\\
&E(k)\mu^{(-k_0)}(\zeta,t;k),\quad k\in U_{-k_0}.
\end{aligned}
\right.
\ee
Thus, we have
\begin{align}
Q=\lim_{k\to0}\frac{\left[\breve{\mu}^{-1}(\zeta,t;0)\breve{\mu}(\zeta,t;k)\right]_{UR}}{k}
=\frac{T^{-2}(0)}{\sqrt{tk_0}}\left[\tilde{\Delta}_0^{-1}\left(\mu_1^{( k_0)}(\zeta,t)+\mu_1^{( -k_0)}(\zeta,t)\right)\tilde{\Delta}_0\right]_{UR}.
\end{align}
By \eqref{muk0} and \eqref{mu-k0}, we find the conclusion \eqref{1.8} presented in Theorem \ref{th1.1}.
\section{Asymptotics in range $\hat{\zeta}>\varepsilon$}\label{sec4}
We now turn to the study of the asymptotic behavior when $\hat{\zeta}>\varepsilon$. Our starting point is RH problem \ref{rhp2.1}. In this case, there is no stationary point, and we only need the following decomposition for the jump matrix $\breve{J}$ on the $\bfR$:
\be\label{4.1}
\breve{J}=\begin{pmatrix} \mathbb{I}_{2\times2} & \rho^\dag(k)\e^{-2\ii t\theta}\\[4pt]
\mathbf{0}_{2\times2} &\mathbb{I}_{2\times2}\end{pmatrix}\begin{pmatrix} \mathbb{I}_{2\times2} & \mathbf{0}_{2\times2}\\[4pt]
\rho(k)\e^{2\ii t\theta} &\mathbb{I}_{2\times2}\end{pmatrix}.
\ee
Since all the pole conditions have desired decay properties, and hence, following the same argument of Proposition \ref{prop3.2}, we have
\be\label{4.2}
\breve{\mu}(\zeta,t;k)=\left(\mathbb{I}_{4\times4}+O(\e^{-ct})\right)
\mu^{(1)}(\zeta,t;k),
\ee
where $\mu^{(1)}(\zeta,t;k)$ satisfies the following RH problem.
\begin{rhp}\label{rhp4.1}
Find a $4\times4$ matrix-valued function $\mu^{(1)}(\zeta,t;k)$ with the following properties:
\begin{itemize}
\item Analyticity: $\mu^{(1)}(\zeta,t;k)$ is analytic in $\bfC\setminus\bfR$.

\item Jump condition: The continuous boundary values of $\mu^{(1)}$ on $\bfR$ satisfy the jump relation
\be
\mu^{(1)}_+(\zeta,t;k)=\mu^{(1)}_-(\zeta,t;k)J^{(1)}(\zeta,t;k),
\ee
where the jump matrix is given by
\be
J^{(1)}(\zeta,t;k)=\begin{pmatrix} \mathbb{I}_{2\times2} & \rho^\dag(k)\e^{-2\ii t\theta}\\[4pt]
\mathbf{0}_{2\times2} &\mathbb{I}_{2\times2}\end{pmatrix}\begin{pmatrix} \mathbb{I}_{2\times2} & \mathbf{0}_{2\times2}\\[4pt]
\rho(k)\e^{2\ii t\theta} &\mathbb{I}_{2\times2}\end{pmatrix}.
\ee
\item Normalization: $\mu^{(1)}(\zeta,t;k)\rightarrow\mathbb{I}_{4\times4},$ as $k\rightarrow\infty.$
\end{itemize}
\end{rhp}
We open the contours at $k=0$ and define several regions and lines as shown in Figure \ref{fig6}, where
\berr
\Xi=\bigcup_{l=1}^4\Xi_l,\quad \Xi_l=\e^{\frac{(l-1)\ii\pi}{2}+\frac{\ii\pi}{4}}\alpha,\quad l=1,2,3,4,\ 0\leq\alpha<\infty.
\eerr
\begin{figure}[htbp]
  \centering
  \includegraphics[width=3in]{Fig6-eps-converted-to.pdf}
  \caption{The signature of Im$\theta$ in the case $\hat{\zeta}>\varepsilon$ and the jump lines $\Xi_l$.}\label{fig6}
\end{figure}
Now, we open the jump line at $k=0$ to make a continuous extension, and the first step is to introduce several new functions.
\begin{lemma}\label{lem4.1}
Define functions $R_j:\bar{\Omega}_j\mapsto\bfC$, $j=1,2,3,4$ with boundary values satisfying
\begin{align}
R_1(k)&=\left\{
\begin{aligned}
&-\rho(k),\quad k>0,\\
&-\rho(0),\quad k\in\Xi_1,
\end{aligned}
\right.\quad
R_2(k)=\left\{
\begin{aligned}
&-\rho(k),\quad k<0,\\
&-\rho(0),\quad k\in\Xi_2,
\end{aligned}
\right.\label{4.5}\\
R_3(k)&=\left\{
\begin{aligned}
&\rho^\dag(k),\quad k<0,\\
&\rho^\dag(0),\quad k\in\Xi_3,
\end{aligned}
\right.\quad
R_4(k)=\left\{
\begin{aligned}
&\rho^\dag(k),\quad k>0,\\
&\rho^\dag(0), \quad k\in\Xi_4.
\end{aligned}
\right.
\end{align}
Moreover, $R_j$ admit estimates
\be\label{4.7}
|\bar{\partial}R_j(k)|\leq c_1|\rho'(\text{Re}k)|+c_2|k|^{-1/2},
\ee
for positive constants $c_1$ and $c_2$ depended on $\|\rho\|_{H^1(\bfR)}$.
\end{lemma}
\begin{proof}
We only prove the lemma for $R_1$ on $\bar{\Omega}_1$. Let $k=s\e^{\ii\phi}$. Define the interpolation
\begin{align}
R_1(z)=-\rho(0)+\left[-\rho(\text{Re} k)+\rho(0)\right]\cos(2\phi).
\end{align}
 Then we find
\begin{align}
\bar{\partial}R_4(z)=-\frac{1}{2}\rho'(\text{Re}k)\cos(2\phi)-
\frac{\ii}{2}\e^{\ii\phi}\frac{-\rho(\text{Re}k)+\rho(0)}
{|k|}\sin(2\phi).
\end{align}
A basic estimate shows that \eqref{4.7} holds.
\end{proof}
Now we introduce a $4\times4$ matrix function by the following transformation
\be\label{4.10}
\mu^{(2)}(\zeta,t;k)=\mu^{(1)}(\zeta,t;k)\mathcal{R}^{(2)}(k),
\ee
where
\be
\mathcal{R}^{(2)}(k)=\left\{
\begin{aligned}
&\begin{pmatrix}
\mathbb{I}_{2\times2} & \mathbf{0}_{2\times2}\\
R_j(k)\e^{2\ii t\theta(k)} & \mathbb{I}_{2\times2}
\end{pmatrix},\,\,\  k\in\Omega_j,\,j=1,2,\\
&\begin{pmatrix}
\mathbb{I}_{2\times2} & R_j(k)\e^{-2\ii t\theta(k)}\\
\mathbf{0}_{2\times2} & \mathbb{I}_{2\times2}
\end{pmatrix},\,  k\in\Omega_j,\,j=3,4,\\
&\mathbb{I}_{4\times4},\qquad\qquad\qquad\quad\quad\,\,\,\ \text{elsewhere}.
\end{aligned}
\right.
\ee
Then $\mu^{(2)}(\zeta,t;k)$ is the solution of a mixed $\bar{\partial}$-RH problem as follows:
\begin{dbarrhp}\label{rhp4.1}
Find a $4\times4$ matrix-valued function $\mu^{(2)}(\zeta,t;k)$ with the following properties:
\begin{itemize}
\item Analyticity: $\mu^{(2)}(\zeta,t;k)$ is continuous with sectionally continuous first partial derivatives in $\bfC\setminus\Xi$.

\item Jump condition: The continuous boundary values $\mu^{(2)}(\zeta,t;k)$ satisfy
$\mu^{(2)}_+(\zeta,t;k)=\mu^{(2)}_-(\zeta,t;k)J^{(2)}(\zeta,t;k)$ across $\Xi$ with
\be\label{3.25}
J^{(2)}(\zeta,t;k)=\left\{
\begin{aligned}
&\begin{pmatrix}
\mathbb{I}_{2\times2} & \mathbf{0}_{2\times2}\\
\rho(0)\e^{2\ii t\theta} & \mathbb{I}_{2\times2}
\end{pmatrix},\qquad k\in \Xi_1\cup\Xi_2,\\
&\begin{pmatrix}
\mathbb{I}_{2\times2} & \rho^\dag(0)\e^{-2\ii t\theta}\\
\mathbf{0}_{2\times2} &\mathbb{I}_{2\times2}
\end{pmatrix},\quad k\in\Xi_3\cup\Xi_4.
\end{aligned}
\right.
\ee

\item $\bar{\partial}$-Derivative: For $k\in\bfC\setminus \Xi$, we have
\be
\bar{\partial}\mu^{(2)}(\zeta,t;k)=\mu^{(2)}(\zeta,t;k)\bar{\partial}\mathcal{R}^{(2)}(k).
\ee

\item Normalization: As $k\rightarrow\infty$,  $\mu^{(2)}(\zeta,t;k)\rightarrow\mathbb{I}_{4\times4}.$
\end{itemize}
\end{dbarrhp}
Denote $\mu^{(0)}(\zeta,t;k)$ be the solution of the RH problem by dropping the $\bar{\partial}$ component, namely, letting $\bar{\partial}\mathcal{R}^{(2)}\equiv0$ in $\bar{\partial}$-Riemann--Hilbert problem \ref{rhp4.1}. We then have
\be\label{4.14}
\mu^{(0)}(\zeta,t;k)=\mathbb{I}_{4\times4}+O(\e^{-ct}),\quad t\to\infty.
\ee
Now we introduce
\be\label{4.15}
\mu^{(3)}(\zeta,t;k)=\mu^{(2)}(\zeta,t;k)[\mu^{(0)}(\zeta,t;k)]^{-1},
\ee
then we get the following pure $\bar{\partial}$-problem for $\mu^{(3)}(\zeta,t;k)$.
\begin{dbar}\label{dbar4.1}
Find a $4\times4$ matrix-valued function $\mu^{(3)}(\zeta,t;k)$ with the following properties:
\begin{itemize}
\item Analyticity: $\mu^{(3)}(\zeta,t;k)$ is continuous with sectionally continuous first partial derivatives in $\bfC\setminus\Xi$.

\item $\bar{\partial}$-Derivative: For $z\in\bfC\setminus\Xi$, we have
\be
\bar{\partial}\mu^{(3)}(\zeta,t;k)=\mu^{(3)}(\zeta,t;k)w^{(3)}(\zeta,t;k),
\ee
where
\be
w^{(3)}(\zeta,t;k)=\mu^{(0)}(\zeta,t;k)\bar{\partial}
\mathcal{R}^{(2)}(z)[\mu^{(0)}(\zeta,t;k)]^{-1}.
\ee

\item Normalization: As $k\rightarrow\infty$, $\mu^{(3)}(\zeta,t;k)\rightarrow\mathbb{I}_{4\times4}.$
\end{itemize}
\end{dbar}
We now proceed as in the previous section and study the integral equation related to the $\bar{\partial}$-problem \ref{dbar4.1}
\be
\mu^{(3)}(\zeta,t;k)=\mathbb{I}_{4\times4}
-\frac{1}{\pi}\iint\limits_{\bfC}\frac{(\mu^{(3)}w^{(3)})(\zeta,t;s)}{s-k}\dd m(s).
\ee
Writing $s=u+\ii v$ and $k=\alpha+\ii\beta$, then region $D_1$ corresponds to $u\geq v\geq0$ and
\begin{align}
\text{Re}(2\ii t\theta(s))=-2tv\left(\hat{\zeta}+\frac{1}{4(u^2+v^2)}\right)\leq-\frac{vt}{2(u^2+v^2)}.
\end{align}
We estimate
\be
\iint\limits_{D_1}\frac{|w^{(3)}(s)|}{|s-k|}\dd m(s)\leq c(I_1+I_2),
\ee
where
\begin{align}
I_1=&\int_0^\infty\int_{v}^\infty\frac{1}{|s-k|}
\left|\rho'(\text{Re}s)\right|e^{-\frac{vt}{2(u^2+v^2)}}\dd u\dd v,\nn\\
I_2=&\int_0^\infty\int_{v}^\infty\frac{1}{|s-k|}\frac{1}{|u+\ii v|^{1/2}}e^{-\frac{vt}{2(u^2+v^2)}}\dd u\dd v.\nn
\end{align}
It follows from the estimates in Subsection \ref{sec3.5} that $|I_1|,|I_2|\leq ct^{-1/6}.$
This proves that
\be
\iint\limits_{D_1}\frac{|w^{(3)}(s)|}{|s-z|}\dd m(s)\leq ct^{-1/6},
\ee
which yields the following result.
\begin{proposition}
As $t\to\infty$, the norm of the integral operator $C_k$ given in \eqref{3.120} decays to zero:
\be
\|C_k\|_{L^\infty\rightarrow L^\infty}\leq ct^{-1/6},
\ee
which yields the existence of operator $(1-C_k)^{-1}$, and hence $\mu^{(3)}(\zeta,t;k)$.
\end{proposition}

We now consider the asymptotic expansion of $\mu^{(3)}(\zeta,t;k)$ at $k=0$
\be
\mu^{(3)}(\zeta,t;k)=\mathbb{I}_{4\times4}+\mu_0^{(3)}(\zeta,t)+\mu_1^{(3)}(\zeta,t)k+O(k^2),
\ee
where
\begin{align}
\mu_0^{(3)}(\zeta,t)=&-\frac{1}{\pi}\iint\limits_{\bfC}\frac{(\mu^{(3)}w^{(3)})(s)}{s}\dd m(s),\\
\mu_1^{(3)}(\zeta,t)=&-\frac{1}{\pi}\iint\limits_{\bfC}\frac{(\mu^{(3)}w^{(3)})(s)}{s^2}\dd m(s).
\end{align}
\begin{proposition}
As $t\to\infty$, $\mu_0^{(3)}(\zeta,t)$ and $\mu_1^{(3)}(\zeta,t)$ admit the following estimate
\be
|\mu_0^{(3)}(\zeta,t)|\leq ct^{-1},\quad |\mu_1^{(3)}(\zeta,t)|\leq ct^{-1}.
\ee
\end{proposition}

Inverting the sequence of transformations \eqref{4.2}, \eqref{4.10}, \eqref{4.14} and \eqref{4.15}, using \eqref{2.50} and \eqref{2.51} and taking $k\rightarrow0$ vertically, we have as $t\to\infty$
\begin{align}
q_1(x,t)&=q_1(\zeta(x,t),t)=O(t^{-1}),\\
q_2(x,t)&=q_2(\zeta(x,t),t)=O(t^{-1}),
\end{align}
and
\be
x=\zeta(x,t)+O(t^{-1}).
\ee




