\appendix
\section{Proof of Proposition \ref{prop3.3}}\label{secA}
\begin{proof}
We first prove \eqref{3.92}. For a fixed small number $\beta$ with $0<2\beta<1$, we write
\begin{align*}\label{B.1}
&[\delta_{k_0}^1(z)]^2-z^{-2\ii\nu(k_0)}\e^{\frac{\ii z^2}{2}}\\
=&\e^{\ii\beta z^2}\Bigg\{z^{-2\ii\nu(k_0)}\exp\left\{\frac{\ii(1-2\beta) z^2}{2}\left(1-\frac{z}{(1-2\beta)s^4k_0^{-9/2}t^{1/2}}\right)\right\}
\left(\frac{2k_0}{z/\sqrt{k_0^{-3}t}+2k_0}\right)^{-2\ii\nu(k_0)}\\
&\times\e^{2[\chi_{k_0}([z/\sqrt{k_0^{-3}t}]+k_0)-\chi_{k_0}(k_0)]}-z^{-2\ii\nu(k_0)}\e^{\frac{\ii(1-2\beta) z^2}{2}}\Bigg\}\nn\\
=&\e^{\frac{\ii\beta z^2}{2}}(I+II+III),
\end{align*}
where
\begin{align}
I=&\e^{\frac{\ii\beta z^2}{2}}z^{-2\ii\nu(k_0)}\left[
\exp\left\{\frac{\ii(1-2\beta)z^2}{2}\left(1-\frac{z}{(1-2\beta)s^4k_0^{-9/2}t^{1/2}}\right)
\right\}-\e^{\frac{\ii(1-2\beta) z^2}{2}}\right],\nn\\
II=&\e^{\frac{\ii\beta z^2}{2}}z^{-2\ii\nu(k_0)}
\exp\left\{\frac{\ii(1-2\beta)z^2}{2}\left(1-\frac{z}{(1-2\beta)s^4k_0^{-9/2}t^{1/2}}\right)
\right\}\nn\\
&\times\left[\left(\frac{2k_0}{z/\sqrt{k_0^{-3}t}+2k_0}\right)^{-2\ii\nu(k_0)}-1\right],\nn\\
III=&\e^{\frac{\ii\beta z^2}{2}}z^{-2\ii\nu(k_0)}
\exp\left\{\frac{\ii(1-2\beta)z^2}{2}\left(1-\frac{z}{(1-2\beta)s^4k_0^{-9/2}t^{1/2}}\right)
\right\}\left(\frac{2k_0}{z/\sqrt{k_0^{-3}t}+2k_0}\right)^{-2\ii\nu(k_0)}\nn\\
&\times\left[\e^{2[\chi_{k_0}([z/\sqrt{k_0^{-3}t}]+k_0)-\chi_{k_0}(k_0)]}-1\right].\nn
\end{align}
Obviously, $|z^{-2\ii\nu(k_0)}|=\e^{2\nu(k_0)\arg z}$ and $|[2k_0/(z/\sqrt{k_0^{-3}t}+2k_0)]^{-2\ii\nu(k_0)}|
=\e^{2\nu(k_0)\arg(1+\alpha\e^{\pi\ii/4}/2)},$ thus they are bounded. Moreover,
$\e^{\frac{\ii(1-2\beta)z^2}{2}(1-z/((1-2\beta)s^4k_0^{-9/2}t^{1/2}))}$ is bounded as \berr
\text{Re}[1-z/((1-2\beta)s^4k_0^{-9/2}t^{1/2})]
=1-k_0^4\alpha\frac{\text{Re}s^4+\text{Im}s^4}{(1-2\beta)\sqrt{2}|s|^4}
\geq1-\frac{k_0^4\epsilon}{(1-2\beta)}>0
\eerr
for $\beta$ sufficiently small.
On the other hand, we have
\begin{align}
|I|\leq&c\left|\e^{\frac{\ii\beta z^2}{2}}\right|\left|\exp\left\{\frac{\ii(1-2\beta)z^2}{2}\left(1-\frac{ z}{(1-2\beta)s^4k_0^{-9/2}t^{1/2}}\right)\right\}-\e^{\frac{\ii (1-2\beta)z^2}{2}}\right|\\
\leq&c\left|\e^{\frac{\ii\beta z^2}{2}}\right|\sup_{0\leq \eta\leq1}\left|\frac{\dd}{\dd\eta}
\exp\left\{\frac{\ii z^2}{2}\left(1-\frac{\eta z}{s^4k_0^{-9/2}t^{1/2}}\right)\right\}\right|\leq\left|\e^{\frac{\ii\beta z^2}{2}}z^3\right|\frac{c}{\sqrt{t}}\leq\frac{c}{\sqrt{t}},\nn\\
|II|\leq&c\left|\e^{\frac{\ii\beta z^2}{2}}\right|\left|\left(\frac{2k_0}{z/\sqrt{k_0^{-3}t}+2k_0}\right)^{-2\ii\nu(k_0)}-1\right|
=c\left|\e^{\frac{\ii\beta z^2}{2}}\int_1^{1+\frac{z}{\sqrt{4k_0^{-1}t}}}2\ii\nu(k_0)\zeta^{2\ii\nu(k_0)-1}\dd\zeta\right|\\
\leq&c\left|\e^{\frac{\ii\beta z^2}{2}}z\right|\sup\left\{|\zeta^{2\ii\nu(k_0)-1}|:\zeta=1+\frac{\varsigma z}{\sqrt{4k_0^{-1}t}},0\leq \varsigma\leq1\right\}\leq \frac{c}{\sqrt{t}}.\nn
\end{align}
Next, we consider
\begin{align}
&\left|\e^{\frac{\ii\beta z^2}{2}}\right|\left|\e^{2[\chi_{k_0}([z/\sqrt{k_0^{-3}t}]+k_0)-\chi_{k_0}(k_0)]}-1\right|\\
\leq& c\sup_{0\leq\varsigma\leq1}\left|
\e^{2\varsigma[\chi_{k_0}([z/\sqrt{k_0^{-3}t}]+k_0)-\chi_{k_0}(k_0)]}\right|
\left|2\e^{\frac{\ii\beta z^2}{2}}\left[\chi_{k_0}\left(\frac{z}{\sqrt{k_0^{-3}t}}+k_0\right)
-\chi_{k_0}(k_0)\right]\right|.\nn
\end{align}
It follows from \eqref{3.85} that
\begin{align}
\chi_{k_0}(k)=-\frac{1}{2\pi\ii}\left(\int_{-\infty}^{-k_0}+\int_{k_0}^{\infty}\right)
\ln(k-s)\dd\ln(1+\text{tr}[\rho(s)\rho^\dag(s)]+\det[\rho(s)\rho^\dag(s)]).\nn
\end{align}
Denote $g(s)=\partial_s\ln(1+\text{tr}[\rho(k_0s)\rho^\dag(k_0s)]+\det[\rho(k_0s)\rho^\dag(k_0s)])$, then, we find
\begin{align}
&-2\pi\ii\left(\chi_{k_0}\left(\frac{z}{\sqrt{k_0^{-3}t}}+k_0\right)-\chi_{k_0}(k_0)\right)\\
=&\int_{-\infty}^{-k_0}\ln\left(\frac{\frac{z}{\sqrt{k_0^{-3}t}}+k_0-s}{k_0-s}\right)
\dd\ln(1+\text{tr}[\rho(s)\rho^\dag(s)]+\det[\rho(s)\rho^\dag(s)])\nn\\
&+\int^{\infty}_{k_0}\ln\left(\frac{\frac{z}{\sqrt{k_0^{-3}t}}+k_0-s}{k_0-s}\right)
\dd\ln(1+\text{tr}[\rho(s)\rho^\dag(s)]+\det[\rho(s)\rho^\dag(s)])\nn\\
=&\int_{-\infty}^{-1}\ln\left(1+\frac{\frac{z}{\sqrt{k_0^{-3}t}}}{1-s}\right)
\dd\ln(1+\text{tr}[\rho(k_0s)\rho^\dag(k_0s)]+\det[\rho(k_0s)\rho^\dag(k_0s)])\nn\\
&+\int^{\infty}_{1}\ln\left(1-\frac{\frac{z}{\sqrt{k_0^{-3}t}}}{s-1}\right)
\dd\ln(1+\text{tr}[\rho(k_0s)\rho^\dag(k_0s)]+\det[\rho(k_0s)\rho^\dag(k_0s)])\nn\\
=&\left[\int_{-\infty}^{-1}(g(s)-g(1))\ln\left(1+\frac{\frac{z}{\sqrt{k_0^{-3}t}}}{1-s}\right)
\dd s+\int^{\infty}_{1}(g(s)-g(1))\ln\left(1-\frac{\frac{z}{\sqrt{k_0^{-3}t}}}{s-1}\right)
\dd s\right]\nn\\
&+\left[\int_{-\infty}^{-1}g(1)\ln\left(1+\frac{\frac{z}{\sqrt{k_0^{-3}t}}}{1-s}\right)\dd s+\int^{\infty}_{1}g(1)\ln\left(1-\frac{\frac{z}{\sqrt{k_0^{-3}t}}}{s-1}\right)\dd s\right]=
III_1+III_2.\nn
\end{align}
Using the Lipschitz condition, $|\ln(1+a)|\leq|a|$, we have
\begin{align}
\left|\e^{\frac{\ii\beta z^2}{2}}III_1\right|\leq c\left|\e^{\frac{\ii\beta z^2}{2}}\frac{z}{\sqrt{k_0^{-3}t}}\right|
\left(\int_{-\infty}^{-1}+\int_1^\infty\right)\left|\frac{g(s)-g(1)}{s-1}\right|\dd s\leq\frac{c}{\sqrt{t}},
\end{align}
since $g(s)$ is rapidly decay as $s\rightarrow\infty$.
Moreover, we have
\begin{align}
III_2=&\int_0^2g(1)\ln\left(1-\frac{z}{\sqrt{k_0^{-3}t}s}\right)\dd s+\int_2^\infty g(1)\ln\left(1-\frac{z^2}{k_0^{-3}t s^2}\right)\dd s\nn\\
=&\left(\int_0^1+\int_1^2\right)g(1)\ln\left(1-\frac{z}{\sqrt{k_0^{-3}t}s}\right)\dd s+\int_2^\infty g(1)\ln\left(1-\frac{z^2}{k_0^{-3}t s^2}\right)\dd s\nn\\
=&III_{2,1}+III_{2,2}+III_{2,3}.\nn
\end{align}
Thus, we have
\begin{align}
\left|\e^{\frac{\ii\beta z^2 }{2}}III_{2,2}\right|&\leq c\left|\e^{\frac{\ii\beta z^2}{2}}\frac{z}{\sqrt{k_0^{-3}t}}\right|\leq\frac{c}{\sqrt{t}},\\
\left|\e^{\frac{\ii\beta z^2}{2}}III_{2,3}\right|&\leq c\left|\e^{\frac{\ii\beta z^2}{2}}\frac{z^2}{k_0^{-3}t}\right|\leq\frac{c}{t}.
\end{align}
On the other hand, we have
\begin{align}
III_{2,1}=g(1)\left(1-\frac{z}{\sqrt{k_0^{-3}t}}\right)
\ln\left(1-\frac{z}{\sqrt{k_0^{-3}t}}\right)
+g(1)\frac{z}{\sqrt{k_0^{-3}t}}\ln\left(\frac{-z}{\sqrt{k_0^{-3}t}}\right).\nn
\end{align}
Thus,
\begin{align}
\left|\e^{\frac{\ii\beta z^2 }{2}}III_{2,1}\right|\leq&\frac{c\left|\e^{\frac{\ii\beta z^2 }{2}}z\right|}{\sqrt{k_0^{-3}t}}
\left(1-\frac{|z|}{\sqrt{k_0^{-3}t}}\right)+\frac{c\left|\e^{\frac{\ii\beta z^2}{2}}z\ln z\right|}{\sqrt{k_0^{-3}t}}+c\left|\e^{\frac{\ii\beta z^2}{2}}z\right|\frac{\ln\left(\sqrt{k_0^{-3}t}\right)}
{\sqrt{k_0^{-3}t}}
\leq c\frac{\ln t}{\sqrt{t}}.
\end{align}
Therefore, we prove that
\begin{align}
|III|\leq c\frac{\ln t}{\sqrt{t}}.
\end{align}

We now focus on the proof of case \eqref{3.93}, the case \eqref{3.94} is similar. Denote \be
\tilde{\delta}_1(k)=\left(\delta_{2}(k)-\delta(k) \mathbb{I}_{2\times2}\right)\e^{-2\ii t\theta(k)}.
\ee
It then follows from \eqref{3.4} and \eqref{3.81} that $\tilde{\delta}_1(k)$ satisfies
\begin{align}
\left\{
\begin{aligned}
\tilde{\delta}_{1+}(k)&=\left(1+\text{tr}[\rho(k)\rho^\dag(k)]
+\det[\rho(k)\rho^\dag(k)]\right)\tilde{\delta}_{1-}(k)+f(k)\e^{-2\ii t\theta(k)},\quad  |k|>k_0,\\
&=\tilde{\delta}_{1-}(k),\qquad\qquad\qquad\qquad\quad\quad\quad\,\
\qquad\qquad\qquad\qquad\qquad\qquad |k|<k_0,\\
\tilde{\delta}_1(k)&\to\mathbf{0}_{2\times2},\qquad\qquad\qquad\qquad\
\qquad\qquad\qquad\qquad\quad\qquad\qquad\qquad\quad k\to\infty,
\end{aligned}
\right.
\end{align}
where
\be\label{A.12}
f(k)=\left[\rho(k)\rho^\dag(k)-\left(\text{tr}[\rho(k)\rho^\dag(k)]
+\det[\rho(k)\rho^\dag(k)]\right)\mathbb{I}_{2\times2}\right]\delta_{2-}(k).
\ee
In terms of Plemelj formula, the function $\tilde{\delta}_1(k)$ can be represented as follows:
\begin{equation}
\left\{
\begin{aligned}
\tilde{\delta}_1(k)&=X(k)\int_{\bfR\setminus[-k_0,k_0]}
\frac{\e^{-2\ii t\theta(s)}f(s)}{X_+(s)(s-k)}\dd s,\\
X(k)&=\exp\left\{{\frac{1}{2\pi \ii}\int_{\bfR\setminus[-k_0,k_0]}\frac{\ln\left(1+\text{tr}[\rho(s)\rho^\dag(s)]
+\det[\rho(s)\rho^\dag(s)]\right)}{s-k}\dd s }\right\}.
\end{aligned}
\right.
\end{equation}
Note that $\delta_{2-}(k)$ is only continuous on $\mathbb{R}$. Thus, we denote
\be
\tilde{f}(k)=\rho(k)\rho^\dag(k)-\left(\text{tr}[\rho(k)\rho^\dag(k)]
+\det[\rho(k)\rho^\dag(k)]\right)\mathbb{I}_{2\times2}.
\ee
By the analytic decomposition method for scattering data in \cite{PD}, we conclude that $\tilde{f}(k)$ can be decomposed into $\tilde{f}(k)=\tilde{f}_1(k)+\tilde{f}_2(k)+\tilde{f}_3(k)$, where $\tilde{f}_1(k)$ is only defined on $\bfR$, $\tilde{f}_2(k)$ has an analytic continuation to $L_t$
\begin{align*}
L_t:=&L_{t1}\cup L_{t2}=\left\{k\in\bfC|k=k_0+\frac{1}{t}+k_0\alpha\e^{\frac{\pi\ii}{4}},
0<\alpha<\infty\right\}\\
&\cup\left\{k\in\bfC|k=-k_0-\frac{1}{t}+k_0\alpha\e^{\frac{\pi\ii}{4}},
-\infty<\alpha<0\right\},
\end{align*}
and $\tilde{f}_3(k)$ is rational function. Moreover, we have
\begin{align}
\left|\e^{-2\ii t\theta(k)}\tilde{f}_1(k)\right|\leq& \frac{c}{(1+|k|^2)t^l},\quad k\in\bfR,\\
\left|\e^{-2\ii t\theta(k)}\tilde{f}_2(k)\right|\leq& \frac{c}{(1+|k|^2)t^l},\quad k\in L_t,\\
\left|\tilde{f}_3(k)\right|\leq& \frac{c}{1+|k|^5},
\end{align}
for arbitrary natural number $l$. Thus, for $z\in\{z\in\bfC|z=\sqrt{k^{-1}_0t}\alpha\e^{\frac{\pi\ii}{4}},
-\epsilon\leq\alpha\leq\epsilon\}$, we find
\begin{align}
\left(\mathcal{N}\tilde{\delta}_1\right)(k)\leq&cX\left(\frac{z}{\sqrt{k_0^{-3}t}}+k_0\right)
\left(\int_{-k_0-\frac{1}{t}}^{-k_0}+\int_{k_0}^{k_0+\frac{1}{t}}\right)
\frac{\e^{-2\ii t\theta(s)}\tilde{f}(s)}{X_+(s)\left(s-\frac{z}{\sqrt{k_0^{-3}t}}-k_0\right)}\dd s\\
&+cX\left(\frac{z}{\sqrt{k_0^{-3}t}}+k_0\right)
\left(\int^{-k_0-\frac{1}{t}}_{-\infty}+\int^{\infty}_{k_0+\frac{1}{t}}\right)
\frac{\e^{-2\ii t\theta(s)}\tilde{f}_1(s)}{X_+(s)\left(s-\frac{z}{\sqrt{k_0^{-3}t}}-k_0\right)}\dd s\nn\\
&+cX\left(\frac{z}{\sqrt{k_0^{-3}t}}+k_0\right)
\left(\int^{-k_0-\frac{1}{t}}_{-\infty}+\int^{\infty}_{k_0+\frac{1}{t}}\right)
\frac{\e^{-2\ii t\theta(s)}\tilde{f}_2(s)}{X_+(s)\left(s-\frac{z}{\sqrt{k_0^{-3}t}}-k_0\right)}\dd s\nn\\
&+cX\left(\frac{z}{\sqrt{k_0^{-3}t}}+k_0\right)
\left(\int^{-k_0-\frac{1}{t}}_{-\infty}+\int^{\infty}_{k_0+\frac{1}{t}}\right)
\frac{\e^{-2\ii t\theta(s)}\tilde{f}_3(s)}{X_+(s)\left(s-\frac{z}{\sqrt{k_0^{-3}t}}-k_0\right)}\dd s,\nn\\
:=&B_1+B_2+B_3+B_4.\nn
\end{align}
Then, it follows form \cite{GLL-JDE} that
\be
|B_1|\leq ct^{-1},\ |B_2|\leq ct^{-l+1},\ |B_3|\leq ct^{-l+1},\ |B_4|\leq ct^{-1}.
\ee
\end{proof}

\section{The parabolic cylinder model RH problem}\label{secB}
\begin{figure}[htbp]
  \centering
  \includegraphics[width=3in]{Fig7-eps-converted-to.pdf}
  \caption{The contour $X=X_1\cup X_2\cup X_3\cup X_4$.}\label{fig7}
\end{figure}

Define the contour $X=X_1\cup X_2\cup X_3\cup X_4\subset\bfC$, where
\be\label{B.1}
\begin{aligned}
X_1&=\{\kappa\e^{\frac{\ii\pi}{4}}|0\leq \kappa<\infty\},\,\,\,\,\ X_2=\{\kappa\e^{\frac{3\ii\pi}{4}}|0\leq\kappa<\infty\},\\
X_3&=\{\kappa\e^{-\frac{3\ii\pi}{4}}|0\leq \kappa<\infty\},\, X_4=\{\kappa\e^{-\frac{\ii\pi}{4}}|0\leq\kappa<\infty\},
\end{aligned}
\ee
and oriented as in Figure \ref{fig7}. For a $2\times2$ complex-valued matrix $q$, define the function $\nu$ by $\nu(q)=-\frac{1}{2\pi}\ln(1+\text{tr}[qq^\dag]+\det[qq^\dag ])$. We consider the following parabolic cylinder model RH problem.
\begin{rhp}\label{rhB.1}
Find a $4\times4$ matrix-valued function $\mu^{(PC)}(q;z)$ on $\bfC\setminus X$ with the following properties:
\begin{itemize}
\item
 Analyticity: $\mu^{(PC)}(q;z)$ is analytic for $z\in\bfC\setminus X$ and extends continuously to $X$.
\item Jump condition:  The jump relation of the continuous boundary values $\mu^{(PC)}_\pm$ on $X$ is
\be\label{B.2}
\mu^{(PC)}_+(q;z)=\mu^{(PC)}_-(q;z)J^{(PC)}(q;z),\quad z\in X,
\ee
where
\be\label{B.3}
J^{(PC)}(q;z)=\left\{
\begin{aligned}
&\begin{pmatrix}
\mathbb{I}_{2\times2} & (\mathbb{I}_{2\times2}+q^\dag q)^{-1}q^\dag\e^{\frac{\ii z^2}{2}}z^{-2\ii\nu(q)}\\
\textbf{0}_{2\times2} & \mathbb{I}_{2\times2}
\end{pmatrix}, \,\ z\in X_1,\\
&\begin{pmatrix}
\mathbb{I}_{2\times2} & \textbf{0}_{2\times2}\\
q\e^{-\frac{\ii z^2}{2}}z^{2\ii\nu(q)} & \mathbb{I}_{2\times2}
\end{pmatrix},\qquad\qquad\qquad\quad\,\ z\in X_2,\\
&\begin{pmatrix}
\mathbb{I}_{2\times2} & q^\dag\e^{\frac{\ii z^2}{2}}z^{-2\ii\nu(q)}\\
\textbf{0}_{2\times2} & \mathbb{I}_{2\times2}
\end{pmatrix},\qquad\qquad\qquad\,\,\,\,\ z\in X_3,\\
&\begin{pmatrix}
\mathbb{I}_{2\times2} & \textbf{0}_{2\times2}\\
q(\mathbb{I}_{2\times2}+q^\dag q)^{-1}\e^{-\frac{\ii z^2}{2}}z^{2\ii\nu(q)} & \mathbb{I}_{2\times2}
\end{pmatrix},\quad z\in X_4.
\end{aligned}
\right.
\ee
\item Normalization: $\mu^{(PC)}(q;z)\rightarrow \mathbb{I}_{4\times4}$, as $z\rightarrow\infty$.
\end{itemize}
\end{rhp}
\begin{theorem}\label{thB.1}
The RH problem \ref{rhB.1} has a unique solution $\mu^{(PC)}(q;z)$ for each $2\times2$ matrix $q$, and this solution satisfies
\be\label{B.4}
\mu^{(PC)}(q;z)=\mathbb{I}_{4\times4}+\frac{\mu^{(PC)}_1(q)}{z}+O\left(z^{-2}\right),\quad z\rightarrow\infty,
\ee
where
\be\label{B.5}
\begin{aligned}
&\mu^{(PC)}_1(q)=\begin{pmatrix}\mathbf{0}_{2\times2}&\ii\beta^{(PC)}\\ -\ii\left(\beta^{(PC)}\right)^\dag&\mathbf{0}_{2\times2}\end{pmatrix},\\
&\beta^{(PC)}=\frac{\sqrt{2\pi}\e^{\frac{3\ii\pi}{4}-\frac{\pi\nu(q)}{2}}}
{\Gamma(\ii\nu(q))\det q}\begin{pmatrix}
q_{22} & -q_{12}\\ -q_{21} &  q_{11}
\end{pmatrix},
\end{aligned}
\ee
where $\Gamma(\cdot)$ denotes the standard Gamma function.
\end{theorem}
\begin{proof}
In this part, we address the model RH problem for $\mu^{(PC)}(q;z)$ and derive an explicit expression for $\mu^{(PC)}_1(q)$ in terms of the standard parabolic cylinder functions. To begin with, we introduce the following transformation
\begin{equation}\label{b.6}
	\Psi(z) = \mu^{(PC)}(z)z^{-\ii\nu\Sigma_3}\e^{\frac{\ii z}{4}\Sigma_3},
\end{equation}
which implies that
\begin{equation}
	\Psi_+(z) = \Psi_-(z)G(q),\quad G(q) = \e^{-\frac{\ii z}{4}\hat{\Sigma}_3}z^{\ii\nu\hat{\Sigma}_3}J^{(PC)}(q;z).
\end{equation}
Since the jump matrix $G(q)$ is independent of $z$ along each ray, it follows that
\begin{equation}
	\frac{\text{d}\Psi_+(z)}{\text{d}z} = \frac{\text{d}\Psi_-(z)}{\text{d}z}G(q).
\end{equation}
In addition, by applying the transformation \eqref{b.6} and extending $\mu^{(PC)}(q;z)$ as given in \eqref{B.4}, we get
\begin{equation}
	\frac{\text{d}\Psi(z)}{\text{d}z}\Psi^{-1}(z) =  \frac{\ii}{2}z\Sigma_3 + \frac{\ii}{2}[\mu_1^{(PC)},\Sigma_3] +O(z^{-1}).
\end{equation}
According to Liouville's theorem, we conclude that
\begin{equation}\label{b.10}
	\frac{\text{d}\Psi(z)}{\text{d}z} -\frac{\ii}{2}z\Sigma_3\Psi(z) = \beta\Psi(z),
\end{equation}
where
\begin{equation}
	\beta = \frac{\ii}{2}[\mu_1^{(PC)},\Sigma_3] = \begin{pmatrix}
		\mathbf{0}_{2\times 2} & \beta_{12} \\
		\beta_{21} &\mathbf{0}_{2\times 2}
	\end{pmatrix}.
\end{equation}
In particular, we get
\begin{equation}
	(\mu_1^{(PC)})_{12} = \ii\beta_{12},\quad (\mu_1^{(PC)})_{21} = -\ii\beta_{21}.
\end{equation}
Meanwhile, notice that $\mu^{(PC)}(q,z)$ satisfies the symmetry relation
\begin{equation}
	\Sigma_3\left[\mu^{(PC)}(z^*)\right]^{\dagger}\Sigma_3 = \left[\mu^{(PC)}(z)\right]^{-1},
\end{equation}
which further yields that
\begin{equation}
	\beta_{12} = \beta_{21}^{\dagger}.
\end{equation}

Now, we rewrite $\Psi(z)$ as a block matrix
\begin{equation*}
\Psi(z) = 	\begin{pmatrix}
		\Psi_{11}(z) & \Psi_{12}(z) \\
		\Psi_{21}(z) & \Psi_{22}(z)
	\end{pmatrix},
\end{equation*}
where $\Psi_{ij}, i, j=1,2$ are all $2\times 2$ matrices. In view of \eqref{b.10}, we arrive at
\begin{gather}
\label{b.15}	\frac{\text{d}^2\Psi_{11}(z)}{\text{d}z^2}+\left(\left(-\frac{\ii}{2}+\frac{z^2}{4}\right)\mathbb{I}_{2\times 2}-\beta_{12}\beta_{21}\right)\Psi_{11} = 0, \\
	\label{b.16}	\beta_{12}\Psi_{21}(z) = \frac{\text{d}\Psi_{11}(z)}{\text{d}z}-\frac{\ii}{2}z\Psi_{11}(z), \\
\label{b.17}	\frac{\text{d}^2\beta_{12}\Psi_{22}(z)}{\text{d}z^2}+\left(\left(\frac{\ii}{2}+\frac{z^2}{4}\right)\mathbb{I}_{2\times 2}-\beta_{12}\beta_{21}\right)\beta_{12}\Psi_{22}(z) = 0, \\
	\label{b.18}	\Psi_{12} = (\beta_{12}\beta_{21})^{-1}\left(\frac{\text{d}\beta_{12}\Psi_{22}(z)}{\text{d}z} +\frac{\ii}{2}z\beta_{12}\Psi_{22}(z)\right).
\end{gather}
Given that $\beta_{12}$ and $\beta_{21}$  are constant $2\times 2$ matrices independent of $z$, we express them as follows:
\begin{equation*}
	\beta_{12} = \begin{pmatrix}
		A & B \\
		C & D
	\end{pmatrix},\quad
	\beta_{12}\beta_{21} = \begin{pmatrix}
		\tilde{A} & \tilde{B} \\
		\tilde{C} & \tilde{D}
	\end{pmatrix}.
\end{equation*}
Set $\Psi_{11} = (\Psi_{11}^{ij})_{2\times 2}, i,j=1,2$. By examining the (1,1) entry and (2,1) entry of \eqref{b.15}, we obtain
\begin{equation}
	\begin{aligned}
		\frac{\text{d}^2\Psi_{11}^{(11)}(z)}{\text{d}z^2}+\left(-\frac{\ii}{2}+\frac{z^2}{4}\right)\Psi_{11}^{(11)}(z) -\tilde{A}\Psi_{11}^{(11)}(z) -\tilde{B}\Psi_{11}^{(21)}(z) = 0, \\
		\frac{\text{d}^2\Psi_{11}^{(21)}(z)}{\text{d}z^2}+\left(-\frac{\ii}{2}+\frac{z^2}{4}\right)\Psi_{21}^{(11)}(z) -\tilde{C}\Psi_{11}^{(11)}(z) -\tilde{D}\Psi_{11}^{(21)}(z) = 0.
	\end{aligned}
\end{equation}
Let $s$ be a constant satisfying $\tilde{B}\tilde{C}= (s-\tilde{D})(s-\tilde{A})$. Then, a straightforward computation yields
\begin{equation}\label{b.20}
	\frac{\text{d}^2\left[\tilde{C}\Psi_{11}^{(11)}(z)+(s-\tilde{A})\Psi_{11}^{(21)}(z)\right]}{\text{d}z^2}+\left(-\frac{\ii}{2}+\frac{z^2}{4}-s\right)\left[\tilde{C}\Psi_{11}^{(11)}(z)+(s-\tilde{A})\Psi_{11}^{(21)}(z)\right]=0.
\end{equation}
 By substituting variables, \eqref{b.20} can be transformed into the well known Weber equation:
 \begin{equation}
 	\frac{\text{d}^2g(\xi)}{\text{d}\xi^2}+\left(a+\frac{1}{2}-\frac{\xi^2}{4}\right)g(\xi) = 0,
 \end{equation}
which has two linear independent solutions $D_a(\xi)$ and $D_a(-\xi)$. Therefore, there exists two constants $c_1$ and $c_2$ such that
\begin{equation}
	g(\xi) = c_1D_a(\xi)+c_2D_a(-\xi),
\end{equation}
where $D_a(\cdot)$ is the standard parabolic cylinder function. Then, letting $a=-\ii s$ and $\xi = \e^{-\frac{\pi\ii}{4}}z$, \eqref{b.20} can be rewritten as
\begin{equation}\label{b.23}
	\tilde{C}\Psi_{11}^{(11)}(z)+(s-\tilde{A})\Psi_{11}^{(21)}(z) = c_1D_a(\e^{-\frac{\pi\ii}{4}}z) +c_2D_a(\e^{\frac{3\pi\ii}{4}}z).
\end{equation}
 Furthermore, by \cite{ET1927}, as $\xi\to\infty$,
 \begin{equation}\label{b.24}
 		D_a(\xi)=\begin{cases}
 		\xi^a\e^{-\frac{\xi^2}{4}}(1+O(\xi^{-2})),&|\arg \xi|<\frac{3\pi}{4},\\
 		\xi^a\e^{-\frac{\xi^2}{4}}(1+O(\xi^{-2}))
 		-\frac{\sqrt{2\pi}}{\Gamma(-a)}\e^{a\pi \ii}\xi^{-a-1}\e^{\frac{\xi^2}{4}}(1+O(\xi^{-2})),&\frac{\pi}{4}<\arg \xi< \frac{5\pi}{4},\\
 		\xi^a\e^{-\frac{\xi^2}{4}}(1+O(\xi^{-2}))
 		-\frac{\sqrt{2\pi}}{\Gamma(-a)}\e^{-a\pi \ii}\xi^{-a-1}\e^{\frac{\xi^2}{4}}(1+O(\xi^{-2})),&-\frac{5\pi}{4} <\arg \xi<-\frac{\pi}{4}.
 	\end{cases}
 \end{equation}
Note that as $z\to\infty$,
\begin{equation}\label{b.25}
	\Psi_{11}(z)\to z^{-\ii\nu}\e^{\frac{\ii z^2}{4}}\mathbb{I}_{2\times 2}, \quad \Psi_{22}(z)\to z^{\ii\nu}\e^{-\frac{\ii z^2}{4}}\mathbb{I}_{2\times 2}.
\end{equation}
Based on the asymptotic expansion given in \eqref{b.25} and the expressions in \eqref{b.23} and \eqref{b.24}, along the line $z = \sigma\e^{\frac{\pi\ii}{4}}$ with $\sigma > 0$, we can deduce that $c_1 = \tilde{C}z^{-\ii\nu-a}\e^{\frac{a\pi\ii}{4}}$ and $c_2 = 0$. Moreover, it is evident that $\Psi_{11}^{(11)}(z)$ and $\Psi_{11}^{(21)}(z)$ both satisfy the asymptotic expansion \eqref{b.25}, indicating that they are linearly independent. Consequently, it follows from \eqref{b.23} that $s$ must be unique. By the definition of
 $s$, we obtain $\tilde{C} = \tilde{B} = 0$. Thus, $\beta_{12}\beta_{21}= \text{diag}\{\tilde{A},\tilde{D}\}$, and \eqref{b.15} simplifies accordingly
 \begin{equation}
 	\frac{\text{d}^2}{\text{d}z^2}\begin{pmatrix}
 		\Psi_{11}^{(11)} & \Psi_{11}^{(12)}\\
 		\Psi_{11}^{(21)} & \Psi_{11}^{(22)}
  		 	\end{pmatrix}
  	+\left(-\frac{\ii}{2}+\frac{z^2}{4}\right)\begin{pmatrix}
  		\Psi_{11}^{(11)} & \Psi_{11}^{(12)}\\
  		\Psi_{11}^{(21)} & \Psi_{11}^{(22)}
  	\end{pmatrix}
  	-\begin{pmatrix}
  			\tilde{A}\Psi_{11}^{(11)} & \tilde{A}\Psi_{11}^{(12)}\\
  		\tilde{D}\Psi_{11}^{(21)} & \tilde{D}\Psi_{11}^{(22)}
  	\end{pmatrix}= 0.
 \end{equation}
Since $\Psi_{11}^{(11)},\Psi_{11}^{(12)}$ and $\Psi_{11}^{(21)},\Psi_{11}^{(22)}$ satisfy the same differential equation, by setting
\begin{equation}
	a_1 = -\ii\tilde{A},\quad a_2 = -\ii\tilde{D},
\end{equation}
similar to \eqref{b.23}, $\Psi_{11}^{(11)}$ and $\Psi_{11}^{(22)}$ can be expressed linearly in terms of
$D_{a_1}(\e^{-\frac{\pi\ii}{4}}z),D_{a_1}(\e^{\frac{3\pi\ii}{4}}z)$ and $D_{a_2}(\e^{-\frac{\pi\ii}{4}}z),D_{a_2}(\e^{\frac{3\pi\ii}{4}}z)$. On the other hand, in view of \eqref{b.25}, we obtain
\begin{equation}
	\Psi_{11}^{(12)}(z)\to 0,\quad \Psi_{11}^{(21)}(z)\to 0,\quad z\to\infty.
\end{equation}
Hence, form \eqref{b.15} and \eqref{b.17}, we have
\begin{equation}
	\begin{aligned}
		\Psi_{11}^{(11)}(z) &= c_1^{(1)}D_{a_1}(\e^{-\frac{\pi\ii}{4}}z)+ c_2^{(1)}D_{a_1}(\e^{\frac{3\pi\ii}{4}}z), \\
		\Psi_{11}^{(22)}(z) &= c_1^{(2)}D_{a_1}(\e^{-\frac{\pi\ii}{4}}z)+ c_2^{(2)}D_{a_1}(\e^{\frac{3\pi\ii}{4}}z), \\
		\tilde{A}\Psi_{22}^{(11)}(z) &= c_1^{(3)}D_{a_1}(\e^{\frac{\pi\ii}{4}}z)+ c_2^{(3)}D_{a_1}(\e^{-\frac{3\pi\ii}{4}}z),\\
		\tilde{A}\Psi_{22}^{(22)}(z) &= c_1^{(4)}D_{a_1}(\e^{\frac{\pi\ii}{4}}z)+ c_2^{(4)}D_{a_1}(\e^{-\frac{3\pi\ii}{4}}z),
	\end{aligned}
\end{equation}
where $c_1^{(j)}$ and $c_2^{(j)}\ (j=1,2,3,4)$ are constants. Then, for $\arg z\in(\frac{3\pi}{4},\frac{5\pi}{4})$, we find that
\begin{equation}
	\begin{aligned}
		\Psi_{11}^{(11)}(z) &= \Psi_{11}^{(22)}(z) = \e^{-\frac{3\pi\nu}{4}}D_{a_1}(\e^{\frac{3\pi\ii}{4}}z),\quad a_1 = a_2 = -\ii\nu,\\
		\Psi_{22}^{(11)}(z) &= \Psi_{22}^{(22)}(z) = \e^{-\frac{3\pi\nu}{4}}D_{-a_1}(\e^{-\frac{3\pi\ii}{4}}z).
	\end{aligned}
\end{equation}
 From \eqref{b.16}, \eqref{b.18} and the properties of $D_a(\cdot)$
 \begin{equation}
 	\frac{\text{d}D_a(\xi)}{\text{d}\xi} + \frac{\xi}{2}D_a(\xi)- aD_{a-1}(\xi) = 0,
 \end{equation}
 we can infer that
\begin{align}
	\beta_{12}\Psi_{21}(z) &= \e^{\frac{3\pi}{4}(\ii-\nu)}a_1D_{a_1-1}(\e^{\frac{3\pi\ii}{4}}z)\mathbb{I}_{2\times 2}, \\
	\Psi_{12}(z) &=\beta_{12}\e^{-\frac{\pi}{4}(\ii+3\nu)}D_{-a_1-1}(\e^{-\frac{3\pi\ii}{4}}z).
\end{align}
 %Accordingly, for $\arg z\in (\frac{\pi}{4},\frac{3\pi}{4})$, we have
%\begin{align}
 	%\Psi_{11}(z) &= \e^{\frac{\pi\nu}{4}}D_{a_1}(\e^{-\frac{\pi\ii}{4}}z)\mathbb{I}_{2\times 2},\\
 %	\Psi_{22}(z) &= \e^{-\frac{3\pi\nu}{4}}D_{-a_1}(\e^{-\frac{3\pi\ii}{4}}z)\mathbb{I}_{2\times 2},\\
 %	\beta_{12}\Psi_{21}(z) &= \e^{\frac{\pi}{4}(\nu- i)}a_1D_{a_1-1}(\e^{-\frac{\pi\ii}{4}}z)\mathbb{I}_{2\times 2}, \\
 %	\Psi_{12}(z) &= \beta_{12}\e^{-\frac{\pi}{4}(\ii+3\nu)}D_{-a_1-1}(\e^{-\frac{3\pi\ii}{4}}z).
 %\end{align}
Denote
\begin{equation}\label{b.34}
	\tilde{\Psi}(z) =\begin{pmatrix}
		\Psi_{11}(z) & \Psi_{12}(z) \\
		\beta_{12}\Psi_{21}(z) & \Psi_{22}(z)
	\end{pmatrix}.
\end{equation}
Therefore, by a similar computation, it is easy to get
\begin{equation}\label{b.35}
	\tilde{\Psi}(z)= \begin{cases}
		\begin{pmatrix}
			\e^{-\frac{3\pi\nu}{4}}D_{a_1}(\e^{\frac{3\pi\ii}{4}}z)\mathbb{I}_{2\times2} & \beta_{12}\e^{-\frac{\pi}{4}(\ii+3\nu)}D_{-a_1-1}(\e^{-\frac{3\pi\ii}{4}}z) \\
			 \e^{\frac{3\pi}{4}(\ii-\nu)}a_1D_{a_1-1}(\e^{\frac{3\pi\ii}{4}}z)\mathbb{I}_{2\times 2}& \e^{-\frac{3\pi\nu}{4}}D_{-a_1}(\e^{-\frac{3\pi\ii}{4}}z)\mathbb{I}_{2\times 2}
		\end{pmatrix},\quad &\arg z\in(\frac{3\pi}{4},\frac{5\pi}{4}), \\
		\begin{pmatrix}
			\e^{\frac{\pi\nu}{4}}D_{a_1}(\e^{-\frac{\pi\ii}{4}}z)\mathbb{I}_{2\times 2} & \beta_{12}\e^{-\frac{\pi}{4}(\ii+3\nu)}D_{-a_1-1}(\e^{-\frac{3\pi\ii}{4}}z) \\
			\e^{\frac{\pi}{4}(\nu- i)}a_1D_{a_1-1}(\e^{-\frac{\pi\ii}{4}}z)\mathbb{I}_{2\times 2} &\e^{-\frac{3\pi\nu}{4}}D_{-a_1}(\e^{-\frac{3\pi\ii}{4}}z)\mathbb{I}_{2\times 2}
		\end{pmatrix},\quad &\arg z\in (\frac{\pi}{4},\frac{3\pi}{4}),\\

		\begin{pmatrix}
			\e^{\frac{\pi\nu}{4}}D_{a_1}(\e^{-\frac{\pi\ii}{4}}z)\mathbb{I}_{2\times 2} & \beta_{12}\e^{\frac{\pi}{4}(3\ii+\nu)}D_{-a_1}(\e^{\frac{\pi\ii}{4}}z) \\
				\e^{\frac{\pi}{4}(\nu- i)}a_1D_{a_1-1}(\e^{-\frac{\pi\ii}{4}}z)\mathbb{I}_{2\times 2} &  \e^{\frac{\pi\nu}{4}}D_{-a_1-1}(\e^{\frac{\pi\ii}{4}}z)\mathbb{I}_{2\times 2}
		\end{pmatrix},\quad &\arg z\in(-\frac{\pi}{4},\frac{\pi}{4}),\\

		\begin{pmatrix}
			\e^{-\frac{3\pi\nu}{4}}D_{a_1}(\e^{\frac{3\pi\ii}{4}}z)\mathbb{I}_{2\times2} & \beta_{12}\e^{\frac{\pi}{4}(3\ii+\nu)}D_{-a_1}(\e^{\frac{\pi\ii}{4}}z) \\
			\e^{\frac{3\pi}{4}(\ii-\nu)}a_1D_{a_1-1}(\e^{\frac{3\pi\ii}{4}}z)\mathbb{I}_{2\times 2} &\e^{\frac{\pi\nu}{4}}D_{-a_1-1}(\e^{\frac{\pi\ii}{4}}z)\mathbb{I}_{2\times 2}
		\end{pmatrix},\quad &\arg z\in (-\frac{3\pi}{4},-\frac{\pi}{4}).
	\end{cases}
\end{equation}

 Along the ray $\arg z = \frac{3\pi}{4}$, we know that
 \begin{equation}
 	\Psi_+(z) = \Psi_-(z)\begin{pmatrix}
 		\mathbb{I}_{2\times2} & \textbf{0}_{2\times2}\\
 		q & \mathbb{I}_{2\times2}
 	\end{pmatrix}.
 \end{equation}
From \eqref{b.34} and \eqref{b.35}, we deduce that the (2,1) entry of the above RH problem satisfies
\begin{equation}\label{b.37}
	\e^{\frac{\pi}{4}(\nu- i)}a_1D_{a_1-1}(\e^{-\frac{\pi\ii}{4}}z)\mathbb{I}_{2\times 2} = \e^{\frac{3\pi}{4}(\ii-\nu)}a_1D_{a_1-1}(\e^{\frac{3\pi\ii}{4}}z)\mathbb{I}_{2\times 2} +\beta_{12}\e^{-\frac{3\pi\nu}{4}}D_{-a_1}(\e^{-\frac{3\pi\ii}{4}}z)q
\end{equation}
Meanwhile, from \cite{ET1927}, it follows that
\begin{equation}\label{b.38}
		D_a(z)=\frac{\Gamma(a+1)}{\sqrt{2\pi}}\left[\e^{\frac{a\pi \ii}{2}}D_{-a-1}(\ii z)+\e^{-\frac{a\pi \ii}{2}}D_{-a-1}(-\ii z)\right].
\end{equation}
Therefore,
\begin{equation}\label{b.39}
	D_{-a_1}(\e^{-\frac{3\pi\ii}{4}})=\frac{\Gamma(-a_1+1)}{\sqrt{2\pi}}\left[\e^{-\frac{a_1\pi \ii}{2}}D_{a_1-1}(\e^{-\frac{\pi\ii}{4}}z)+\e^{\frac{a_1\pi \ii}{2}}D_{a_1-1}(\e^{\frac{3\pi\ii}{4}} z)\right]
\end{equation}
By comparing the coefficients in \eqref{b.37} and \eqref{b.39}, we get
\begin{equation}
	\beta_{12} =\frac{\sqrt{2\pi}\e^{\frac{3\pi\ii}{4}-\frac{\pi\nu}{2}}}
	{\Gamma(\ii\nu)\det q}\begin{pmatrix}
		q_{22} & -q_{12}\\ -q_{21} &  q_{11}
	\end{pmatrix},
\end{equation}
which is related to \eqref{B.5} by setting $\beta^{(PC)} = \beta_{12}$.

\end{proof}



