%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{The fully discrete scheme}
 Based on the random variable $\bz$ sampling methodology detailed in Section \ref{sec3.2}, the approximation of the trajectory $\{\tX_{t_i}\}$ in Section \ref{sec3.3} and the sparse grid interpolation outlined in Section \ref{sec3.1} , we are now well-positioned to develop the fully discrete scheme for the semi-linear PIDEs. 
To this end, we use the trapezoidal rule to approximate the integral of \eqref{FKi} and employ an implicit-explicit technique for the nonlinear term, namely, $u^i(t_{i}, \tX_{t_i})$ in \eqref{FKi} is replaced by $u^{i-1}_\ast(\tX_{t_i})$.
As a consequence,  the numerical solution of \eqref{FKi} (denoted by $u_\ast^i(\bx)$) at time grid $t_i$ reads
\begin{equation}\label{uapp1}
\begin{split}
u_\ast^{i}(\bx)= \;&
 \mathbb{E}_{\tX_{t_{i-1}}=\bx}\Big[ u_\ast^{i-1}(\tX_{t_{i}} ) \mathbb{I}_{\tau_{i}>t_{i}} +g(t_{i},\tX_{t_{i}} )\mathbb{I}_{\tau_{i}\leq t_{i}}\Big] \\&+ \mathbb{E}_{\tX_{t_{i-1}}=\bx}\Big[(\tau_{i}\land t_{i} -t_{i-1})f(u_\ast^{i-1}(\tX_{t_{i}}))\Big].
\end{split}
\end{equation}
\begin{remark}{\em 
Indeed, the above approximation scheme can be interpreted as a stochastic discretization of the following continuous equation
\begin{equation}
\label{bpi}
\begin{cases}
\partial_{t}u^i(t,\bx) - \mathcal{L}u^i(\bx,t)  =f(u^{i-1}(\bx,t)),\;&(\bx,t) \in\Omega\times\mathcal{T}_i,\\[4pt]
u(\bx,t_{i-1}) =u^{i-1}_\ast(\bx),\quad &\bx\in  \Omega,\\[4pt]
u(\bx,t) = g(\bx,t),\;&(\bx,t) \in\Omega^{c}\times[t_{i-1},t_{i}],
\end{cases}
\end{equation}
On the other hand, we recall the first order implicit-explicit scheme for time discretization of semilinear parabolic equations:
\begin{equation*}
\frac{u^{i}-u^{i-1}}{\Delta t}-\mathcal{L}u^{i}=f(u^{i-1}).
\end{equation*}
We observe that it shares a common characteristic with \eqref{bpi}, namely that the nonlinear term is treated explicitly, while the linear term is treated implicitly. This similarity underscores why the proposed method is termed as an implicit-explicit scheme. 
}
\end{remark}
The discrete scheme \eqref{uapp1} is fundamentally characterized by the explicit treatment of the nonlinear term, offering the advantage of avoiding iterative procedures typically required to address nonlinearities (see, e.g., \cite{yang2023}). Nevertheless, this approach requires prior knowledge of the numerical solution at the previous time step $t_{i-1}$ for any arbitrary location $\tX_{t_i}$, as $\tX_{t_i}$ is stochastically generated. However, in practice, the numerical solution at the previous time step $t_{i-1}$ is only available at the grid points, i.e., $\{u^{i-1}_\ast(\bx_\ell)\}$. 
Hence, at each time interval $\mathcal{T}_{i}$, it is essential to compute the numerical solution at the grid points $\{\bx_\ell\}_{\ell=1}^{N_s}$, after which the interpolation function based on the sparse grid $\Is[u^{i-1}_{\ast}]$ can be constructed. This interpolation function serves as the initial value function for the subsequent time step. By leveraging the properties of sparse grids, this approach significantly reduces computational complexity. Building on this setup, we can formulate a Monte Carlo procedure that utilizes random samples as
\begin{equation}
\label{Sii}
\begin{split}
S_{j}(t_{i},\bx)=& \mathcal{I}_S^d[u^{i-1}_{\ast}](\tX_{t_{i},j} )\mathbb{I}_{\tau_{i}>t_{i}}  +  g(t_{i},\tX_{t_{i},j})\mathbb{I}_{\tau_{i}\leq t_{i}} +(\tau_{i}\land t_{i} -t_{i-1})f(\mathcal{I}_S^d[u^{i-1}_{\ast}](\tX_{t_{i},j})).
\end{split}
 \end{equation}
where the index $j$ represents the $j$-th experiment. By applying the law of large numbers, the numerical solutions can be obtained by the following fully discretized scheme
  \begin{equation}\begin{split}
  \label{ui}
u_\ast^{i}(\bx) &=\lim_{M\rightarrow\infty}\frac{1}{M}\sum_{j=1}^{M}S_{j}(t_{i},\bx)
\\&=\lim_{M\rightarrow\infty}\frac{1}{M}\sum_{j=1}^{M}\Big[\Is[u^{i-1}_{\ast}](\tX_{t_{i},j} )\mathbb{I}_{\tau_{i}>t_{i}} \\&\;\;\quad
 +  g(t_{i},\tX_{t_{i},j})\mathbb{I}_{\tau_{i}\leq t_{i}} +(\tau_{i}\land t_{i} -t_{i-1})f(\Is[u^{i-1}_{\ast}](\tX_{t_{i},j}))\Big],
\end{split} \end{equation}
where $M$ represents the total number of experiments. This approach ensures the convergence to the exact solution by performing sufficient independent simulations of the stochastic process. As the number of simulated paths increases, the numerical results progressively approximate the expected value, thereby improving the accuracy and reliability of the numerical solutions. Notably, parallel computing can be utilized in practical implementations to enhance efficiency by simultaneously handling simulation paths and spatial grid points. Finally, we summarize the above derivations into the implicit-explicit Monte Carlo algorithm presented in {\bf Algorithm 1}. 



%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

 \begin{algorithm}
\caption{The implicit-explicit sparse Monte Carlo method for \eqref{mainprob}.}  \label{alg:Framwork}
\begin{algorithmic}[1]
\Require $\{\bx_\ell\}_{\ell=1}^{N_s}$: the set of sparse grid; $M$: the number of simulation paths; $\Delta t$: time step size.  \;\; 
\Ensure the numerical solution $\{u^N_\ast(\bx_\ell)\}_{\ell=1}^{N_s}$ at the terminal time.
\For{$i=1:N$}
\For{$\ell=1:N_{s}$ ({\bf in parallel})}
\For{$j=1:M$ ({\bf in parallel})}
  \State Set $\tX_{t_{i-1},j}:=\tX_{t_{i-1},j}^\ell=\bx_{\ell}$;
   \State Randomly generate a number $N_{\Delta t}$. 
\If{$\mathbb{P}(N_{\Delta t} = 0)$}
        \State Compute $\tX_{t_{i},j} = \bx_{\ell}  + \mu(t_{i-1}, \bx_\ell)\Delta t+ \sigma(t_{i-1}, \bx_\ell) W_{\Delta t} $;
\Else
        \State Simulate random variables $ \{\bz_k\}_{k=1}^{N_{\Delta t}} $ using Lemma \ref{lemker1}-\ref{lemker3}.
        \State Compute $\tX_{t_{i},j} = \bx_{\ell}  + \mu(t_{i-1}, \bx_\ell)\Delta t+ \sigma(t_{i-1},\bx_\ell) W_{\Delta t}+\sum_{k=1}^{N_{\Delta t}}c(t_{i-1},\bx_\ell,\bz_k)$;
\EndIf
\If{$\tX_{t_{i},j}\in \Omega$}

            \State Compute $S_{j}(t_{i},\bx_{\ell})=\Is[u^{i-1}_{\ast}](\tX_{t_{i},j} )+\Delta t f\big(\Is[u^{i-1}_{\ast}](\tX_{t_{i},j})\big)$;
\Else
            \State Compute $S_{j}(t_{i},\bx_{\ell})= g(t_{i},\tX_{t_{i,j}}) +\Delta t f\big(\Is[u^{i-1}_{\ast}](\tX_{t_{i},j})\big)$;
 \EndIf

\EndFor : in $j$
\State Compute $u_\ast^{i}(\bx_{\ell})\approx\frac{1}{M}\sum_{j=1}^{M}S_{j}(t_{i},\bx_{\ell})$;  
\EndFor : in $\ell$
  \State Using the numerical solution $\{ u_\ast^{i}(\bx_{\ell})\}_{\ell=1}^{N_{s}}$ to compute the interpolation function $\Is[u_\ast^{i}](\cdot)$; 
   \EndFor : in $i$  
\end{algorithmic}
\end{algorithm}

