 \section{Error estimates.}
 In this section, we derive the rigorous error estimates for the proposed fully discrete explicit-implicit Monte Carlo method based on the sparse grid, where we focus on the bounded domain case with homogeneous global boundary conditions, i.e., $g(t,\bx) = 0$, as the method can be easily extended to inhomogeneous boundary conditions.  It should be noted that we do not consider the error arising from the stochastic discretization, i.e., the error between $\{\tX_{t_i}\}$ and $\{X_{t_i}\}$. In fact, incorporating this error into the analysis would make it excessively complex, far beyond the scope of this paper, and would distract from the main topic; please refer to a similar situation in \cite{yang2023}.
Furthermore, in the subsequent analysis, we assume that the nonlinear function $f(u)$ satisfies the following Lipschitz condition:
\begin{equation}\label{Lipscond}
|f(u_1)-f(u_2)| \leq L|u_1-u_2|, \quad L > 0,
\end{equation}
as well as the following two additional assumptions:

\noindent{\bf Assumption 1}: Let $\mu,\sigma,c \in C^{1}$, for any $t\in[0,T]$, assume that the drift coefficient $\mu$ satisfies a one-sided Lipschitz condition,  the that both diffusion coefficient $\sigma$ and jump coefficient $c$ satisfy global Lipschitz conditions: 
\begin{eqnarray}
\label{cond1}
 &&\langle \bx-\by, \mu(\cdot,\bx)- \mu(\cdot, \by)  \rangle  \leq C_{\mu}|\bx-\by|^{2}, \quad \text{for\; all}\;\; \bx,\by\in\R^{d},\\
 \label{cond2}
&&|\sigma(\cdot, \bx) - \sigma(\cdot, \by)|\leq C_{\sigma}|\bx-\by|^{2} , \quad \text{for\; all} \;\;\bx,\by\in\R^{d}, \\
\label{cond3}
&&|c(\cdot, \cdot,\bz_{1}) - c(\cdot, \cdot,\bz_{2})|\leq C_{c}|\bz_{1}-\bz_{2}|^{2} , \quad \text{for \; all} \;\;\bz_{1},\bz_{2}\in\R^{d}.
\end{eqnarray}
\noindent{\bf Assumption 2 (Uniform Ellipticity)}: 
There exist constants $0<\upsilon\leq\kappa<\infty$, such that for all $\bx\in \R^d$,
\begin{equation}
\label{cond4}
\upsilon^2\mathbb{I}_d\preceq \sigma(\bx,\cdot) \sigma(\bx,\cdot)^{\top} \preceq \kappa^2 \mathbb{I}_d \Longleftrightarrow \upsilon^2 |\bs{\xi}|^2\leq \bs{\xi}^\top (\sigma \sigma^\top) \bs{\xi} \leq \kappa^2 |\bs{\xi}|^2,
\end{equation}
for any $ \bs{\xi} \in \R^d \setminus \{\mathbf{0}\}$.

\medskip

Let $e^i(\bx)=u(\bx,t_i)-u^i_\ast(\bx)$, $i=0,\cdots,N$. Then, we have the following Lemma. 
\begin{lemma}\label{lmmdecom} {\em Let $u(t_i,\bx)$ and $u_\ast^i(\bx)$ be the solution of  \eqref{FKi} and \eqref{ui} at time grid $t_{i}$, respectively. 
Then it holds that
\begin{equation} 
\label{mainerr}
\|e^{i}\|_{\L2(\Omega)}= \|u(t_i,\cdot)-u_\ast^{i}\|_{\L2(\Omega)}\leq B^{i}_{1} + B^{i}_{2}+B^{i}_{3} +B^{i}_{4} + B^{i}_{5} +B^{i}_{6} ,
 \end{equation}
where 
\begin{equation}
\label{EI}\begin{split}
&B^{i}_{1}= \Big\|   \mathbb{E}_{\bx}\Big[ u^{i-1}(\tX_{t_{i}}) \mathbb{I}_{\tau_{i}>t_{i}}   -\Is[u^{i-1}_{\ast}](\tX_{t_{i}}) \mathbb{I}_{\tau_{i}>t_{i}}   \Big] \Big\|_{\L2(\Omega)}, \\
&B^{i}_{2}= \Big\|  \mathbb{E}_{\bx}\Big[\Is[u^{i-1}_{\ast}](\tX_{t_{i}}) \mathbb{I}_{\tau_{i}>t_{i}}  + g(\tau_{i},\tX_{\tau_{i}}) \mathbb{I}_{\tau_{i}\leq t_{i}}   \Big]   \\
&\quad- \frac{1}{M}\sum_{j=1}^{M}\Big[\Is[u^{i-1}_{\ast}](\tX_{t_{i},j} )\mathbb{I}_{\tau_{i}>t_{i}}  +  g(t_{i},\tX_{t_{i,j}})\mathbb{I}_{\tau_{i}\leq t_{i}}\Big]  \Big\|_{\L2(\Omega)}, \\
&B^{i}_{3}= \Big\| \mathbb{E}_{\bx}\Big[   \int_{t_{i-1}}^{t_{i} \land \tau_{i}} f( u(s,\tX_{s}))\,\d s  - \int_{t_{i-1}}^{t_{i}\land \tau_{i}}f( u^{i-1}(\tX_{s}))\,\d s   \Big] \Big\|_{\L2(\Omega)},\\
&B^{i}_{4}=\Big\| \mathbb{E}_{\bx}\Big[ \int_{t_{i-1}}^{t_{i}\land \tau_{i}}f( u^{i-1}(\tX_{s}))\,\d s  \Big]  -\mathbb{E}_{\bx}\Big[(\tau_{i}\land t_{i} - t_{i-1})f(u^{i-1}(\tX_{t_{i}}))\Big]   \Big\|_{\L2(\Omega)}, \\
&B^{i}_{5}= \Big\| \mathbb{E}_{\bx}\Big[(\tau_{i}\land t_{i} - t_{i-1})f(u^{i-1}(\tX_{t_{i}}))\Big] -\mathbb{E}_{\bx}\Big[(\tau_{i}\land t_{i} - t_{i-1})f(\Is[u^{i-1}_{\ast}](\tX_{t_{i}})) \Big] \Big\|_{\L2(\Omega)},\\
&B^{i}_{6}= \Big\|\mathbb{E}_{\bx}\Big[(\tau_{i}\land t_{i} - t_{i-1})f(\Is[u^{i-1}_{\ast}](\tX_{t_{i}}))\Big]-  \frac{1}{M}\sum_{j=1}^{M}(\tau_{i}\land t_{i} - t_{i-1})f(\Is[u^{i-1}_{\ast}](\tX_{t_{i},j}) ) \Big\|_{\L2(\Omega)},
\end{split}\end{equation}
with $\mathbb{E}_{\bx}$ shorthand for $\mathbb{E}_{\tX_{t_{i-1}}=\bx}$, and the initial $\tX_{t_{i-1},j}=\bx.$}
\end{lemma}
\vspace{-20pt}
\begin{proof}
By comparing the exact solution \eqref{FKi}, with $X_{t_i}$ replaced by $\tX_{t_i}$, and the numerical solution \eqref{ui} at the time grid $t_i$, then the error function is given by their difference:
\begin{eqnarray*}
%\label{ei}
&&\|e^{i}\|_{\L2(\Omega)}=\Big\|u^i(\cdot)  -  \frac{1}{M}\sum_{j=1}^{M}S_{j}(t_{i},\cdot)\Big\|_{\L2(\Omega)}\nonumber \\
&&= \Big\|   \mathbb{E}_{\bx}\Big[ u^{i-1}(t_{i-1},\tX_{t_{i}}) \mathbb{I}_{\tau_{i}>t_{i}}  + g(\tau_{i},\tX_{\tau_{i}}) \mathbb{I}_{\tau_{i}\leq t_{i}}    +  \int_{t_{i-1}}^{t_{i} \land \tau_{i}} f( u(s,\tX_{s}))\,\d s  \Big] \nonumber  \\
&&\quad- \frac{1}{M}\sum_{j=1}^{M}\Big[\Is[u^{i-1}_{\ast}](\tX_{t_{i},j} )\mathbb{I}_{\tau_{i}>t_{i}}  +  g(t_{i},\tX_{t_{i,j}})\mathbb{I}_{\tau_{i}\leq t_{i}} +(\tau_{i}\land t_{i} -t_{i-1})[f(\Is[u^{i-1}_{\ast}])] \Big]  \Big\|_{\L2(\Omega)}\\
%%%%%%
&&\leq\Big\|\mathbb{E}_{\bx}\Big[ u^{i-1}(t_{i-1},\tX_{t_{i}}) \mathbb{I}_{\tau_{i}>t_{i}}  + g(\tau_{i},\tX_{\tau_{i}}) \mathbb{I}_{\tau_{i}\leq t_{i}}   \Big]   \nonumber\\
&&\quad- \frac{1}{M}\sum_{j=1}^{M}\Big[\Is[u^{i-1}_{\ast}](\tX_{t_{i},j} )\mathbb{I}_{\tau_{i}>t_{i}}  +  g(t_{i},\tX_{t_{i,j}})\mathbb{I}_{\tau_{i}\leq t_{i}}  \Big]  \Big\|_{\L2(\Omega)}  \nonumber  \\
 &&\quad+\Big\|  \mathbb{E}_{\bx}\Big[   \int_{t_{i-1}}^{t_{i} \land \tau_{i}} f(u(s,\tX_{s}))\,\d s  \Big]   -  \frac{1}{M}(\tau_{i}\land t_{i} -t_{i-1})\sum_{j=1}^{M}f(\Is[u^{i-1}_{\ast}])   \Big\|_{\L2(\Omega)}.\nonumber
\end{eqnarray*}
Next, we add the following three auxiliary terms in the above equation
\begin{equation*}\begin{split}
&\mathbb{E}_{\bx}\Big[ \int_{t_{i-1}}^{t_{i}\land \tau_{i}}f( u^{i-1}(\tX_{s}))\,\d s \Big] ,\;\;\;
\mathbb{E}_{\bx}\Big[(\tau_{i}\land t_{i} - t_{i-1})f(u^{i-1}(\tX_{t_{i}}))\Big],\\&\mathbb{E}_{\bx}\Big[(\tau_{i}\land t_{i} - t_{i-1})f(\Is[u^{i-1}_{\ast}](\tX_{t_{i}}))\Big],
\end{split}\end{equation*}
to obtain the desired result. This ends the proof.
\end{proof}


 Next, we estimate the bound of the six terms $\{B^{i}_j\}_{j=1}^6$ one by one as follows.
\begin{lemma}\label{lemB1} {\em
Let $u(t_{i-1},\bx)$ and $u_\ast^{i-1}(\bx)$ be the solution of \eqref{pi} and \eqref{ui} at time grid $t_{i-1}$, respectively.  Assume that $u_t\in L^\infty(I;L^2(\Omega))$, $\sigma$ satisfy the conditions of \eqref{cond2}and \eqref{cond4}, and $\kappa\ge (\Delta t)^{-1/2}$, then it holds that
\begin{equation}\label{boundB1}
B^{i}_{1}\leq  \| e^{i-1}\|_{\L2(\Omega)}. % +C_{d,k} N_s^{-k} (\log(N_s))^{(k+2)(d-1)+1}\Delta t  ,
\end{equation}}
%where $C$ is a positive constant independent of $u$ and $\Delta t$, $C_n$ be a positive constant depends only on $n$ and the upper bound of the second derivative of $u$, $ N_s$ represents the number of points on the sparse grid.}
\end{lemma}
\vspace{-20pt} 
\begin{proof}
Since the expectation term in $B^{i}_{1}$ is conditioned on $\tX_{t_{i-1}}=\bx$ and the process $\tX_{t}$ has independent and stationary increment, it follows that $\tX_{t_{i-1}}| \tX_{t_{i-2}}=\bx$ and $\tX_{t_{i}}| \tX_{t_{i-1}}=\bx$ have the same distribution for fixed time step size $\Delta t$. Hence, we find from \eqref{EI} that 
\begin{eqnarray}\label{B1proof1}
%\begin{split}
&& B^{i}_{1}= \Big\|   \mathbb{E}_{\tX_{t_{i-1}}=\bx}\Big[ u^{i-1}(t_{i-1},\tX_{t_{i}}) \mathbb{I}_{\tau_{i}>t_{i}}   -\Is[u^{i-1}_{\ast}](\tX_{t_{i}}) \mathbb{I}_{\tau_{i}>t_{i}}   \Big] \Big\|_{\L2(\Omega)}\nonumber\\
 &&\hspace{15pt}= \Big\|   \mathbb{E}_{\tX_{t_{i-2}}=\bx}\Big[ u^{i-1}(t_{i-1},\tX_{t_{i-1}}) \mathbb{I}_{\tau_{i-1}>t_{i-1}}   -\Is[u^{i-1}_{\ast}](\tX_{t_{i-1}}) \mathbb{I}_{\tau_{i-1}>t_{i-1}}   \Big] \Big\|_{\L2(\Omega)}\nonumber\\
 &&\hspace{15pt}=  \Big\|   \mathbb{E}_{\tX_{t_{i-2}}=\bx}\Big[ u^{i-1}(t_{i-1},\tX_{t_{i-1}})  -\Is[u^{i-1}_{\ast}](\tX_{t_{i-1}})\Big |  \tau_{i}>t_{i}\Big]  \Big\|_{\L2(\Omega)}\nonumber\\
 &&\hspace{15pt}\leq \Big\|   \mathbb{E}_{\tX_{t_{i-2}}=\bx}\Big[ u^{i-1}(t_{i-1},\tX_{t_{i-1}})  -\Is[u^{i-1}_{\ast}](\tX_{t_{i-1}}) \Big]  \Big\|_{\L2(\Omega)}\\
 &&\hspace{15pt}=\Big\|  \mathbb{P}(N_{\Delta t}=0) \mathbb{E}_{\tX_{t_{i-2}}=\bx}\Big[ u^{i-1}(t_{i-1},\tX_{t_{i-1}})  -\Is[u^{i-1}_{\ast}](\tX_{t_{i-1}}) \Big]  \nonumber\\
 &&\hspace{15pt}\quad+  \sum_{k=1}^{\infty}\mathbb{P}(N_{\Delta t}=k) \mathbb{E}_{\tX_{t_{i-2}}=\bx}\Big[ u^{i-1}(t_{i-1},\tX_{t_{i-1}})  -\Is[u^{i-1}_{\ast}](\tX_{t_{i-1}}) \Big]  \Big\|_{\L2(\Omega)} \nonumber\\
 &&\hspace{15pt}\leq B^{i}_{1,1}+B^{i}_{1,2},\nonumber
%  \end{split}
\end{eqnarray}
where 
\begin{equation}\label{B11B12} 
\begin{split}
&B^{i}_{1,1}=\Big\|  \mathbb{P}(N_{\Delta t}=0) \mathbb{E}_{\tX_{t_{i-2}}=\bx}\Big[ u^{i-1}(t_{i-1},\tX_{t_{i-1}})  -\Is[u^{i-1}_{\ast}](\tX_{t_{i-1}}) \big| N_{\Delta t}=0\Big]  \Big\|_{\L2(\Omega)} , \\
    &B^{i}_{1,2}=\Big\|  \sum_{k=1}^{\infty}\mathbb{P}(N_{\Delta t}=k)  \mathbb{E}_{\tX_{t_{i-2}}=\bx}\Big[ u^{i-1}(t_{i-1},\tX_{t_{i-1}})  -\Is[u^{i-1}_{\ast}](\tX_{t_{i-1}})  \big| N_{\Delta t}=k\Big]  \Big\|_{\L2(\Omega)}.
    \end{split}
\end{equation}

We first prove the bound for $B^{i}_{1,1}$ with the case $N_{\Delta t} = 0$, in which the process is driven by Brownian motion without jumps. Thus, the governing equation does not involve any nonlocal operators. Under the assumptions of uniform ellipticity and bounded drift, the transition probability density $p_{\Delta t}(\bx, \by)$ satisfies the following estimate (cf. \cite[p.\,895]{Aronson1967})
\begin{equation*}
   p_{\Delta t}(\bx,\by) \leq  C_e(\Delta t)^{-d/2} e^{-\frac{|\by-\bx|^2}{C_d\Delta t}},
\end{equation*}
where the positive constants $C_e,C_d$ depend on the ellipticity constant and the upper bound of the drift term. From the Gaussian-type upper bound and the substitution $\xi = \bx - \by$, we obtain that


\begin{equation}\label{intdensity}
\begin{split}
\int_{\R^d} \Big( p_{\Delta t}(\bx,\by) \Big)^{2}\,\d\by 
&\leq   C_e^2(\Delta t)^{-d} \int_{\R^{d}} e^{-\frac{2|\bx-\by|^2}{C_d \Delta t}}\,\d\by  \\
&\leq C_e^2(\Delta t)^{-d} \int_{\R^{d}} e^{-\frac{2\bs{\xi}^{2}}{C_d \Delta t}}\,\d\bs{\xi} 
\\&\leq C_e^2(\Delta t)^{-d} \Big(\frac{C_d \Delta t}{2}\Big)^{d/2} \int_{\R^{d}} e^{-\bs{\eta}^{2}}\,\d\bs{\eta}
\\&=C_e^2\Big(\frac{\pi C_d}{2\Delta t}\Big)^{d/2}.
\end{split}
\end{equation}
%According to the assumptions, $\sigma$ is a uniformly positive definite diffusion coefficient matrix; that is, there exists an ellipticity constant $\kappa > 0$ such that $\sigma \sigma^{\top} \leq \kappa^2 \mathbb{I}$.
According to the assumptions \eqref{cond4}, if the ellipticity constant $\kappa$ satisfies $\kappa \geq (\Delta t)^{-1/2}$, then by choosing the constants as $C_d = 4/\kappa,$ $C_e^2 = \frac{1}{(2\pi \kappa)^{d/2}},$  we obtain the estimate $\int_{\mathbb{R}^{n}} \big(p_{\Delta t}(\bx,\by)\big)^{2}\,d\by \leq 1.$
Thus, we derive from Cauchy-Schwarz inequality, \eqref{B11B12}, and \eqref{intdensity} that
\begin{equation}
\label{EuQ}
\begin{split}
& \mathbb{E}_{\tX_{t_{i-2}}=\bx}\Big[ u^{i-1}(t_{i-1},\tX_{t_{i-1}})  -\Is[u^{i-1}_{\ast}](\tX_{t_{i-1}})  \big| N_{\Delta t}=0\Big]  \\
&= \int_{\R^{d}} \big( u^{i-1}(t_{i-1},\by)  -\Is[u^{i-1}_{\ast}](\by) \big)p_{\Delta t}(\bx,\by)\,\d\by \\
 & \leq  \Big(  \int_{\R^{d}} \big( u^{i-1}(t_{i-1},\by)  -\Is[u^{i-1}_{\ast}](\by) \big)^{2}\,\d\by   \Big)^{1/2} \cdot\Big(  \int_{\R^{d}} \big( p_{\Delta t}(\bx,\by) \big)^{2}\,\d\by  \Big)^{1/2}
 \\&\leq \Big(  \int_{\R^{d}} \big( u^{i-1}(t_{i-1},\by)  -\Is[u^{i-1}_{\ast}](\by) \big)^{2}\,\d\by   \Big)^{1/2}.
\end{split}
\end{equation}
Thanks to \eqref{B11B12}, \eqref{EuQ}, and  the fact that $\mathbb{P}(N_{\Delta t}=0) = 1-e^{-\lambda \Delta t}<1$, we find that
\begin{equation}
\label{B11}
\begin{split}
B^{i}_{1,1} 
&\leq \Big(\int_{\Omega}  \mathbb{E}_{\bx}\Big[ u^{i-1}(t_{i-1},\tX_{t_{i-1}})  -\Is[u^{i-1}_{\ast}](\tX_{t_{i-1}}) \Big]^2  \,\d\bx\Big)^{1/2}\\
&\leq\Big(\int_{\Omega}  \Big(  \int_{\R^{d}} \big( u^{i-1}(t_{i-1},\by)  -\Is[u^{i-1}_{\ast}](\by) \big)^{2}\,\d\by \Big)  
\Big)^{1/2} 
\leq  \| e^{i-1}\|_{L^2(\Omega)}.
\end{split}
\end{equation}
Moreover, it is easy to verify that the probability of the Poisson process $N_{\Delta t}$ having $k$ jumps within the interval $[t_{i-1}, t_{i}]$, as given in \eqref{PNk}, behaves as 
$$\sum_{k=1}^{\infty} \mathbb{P}(N_{\Delta t} = k) = \mathcal{O}(\Delta t),$$
which, together with \eqref{B11B12}, implies that
\begin{equation}
\label{B12}
\begin{split}
B^{i}_{1,2}&=\Big\| \sum_{k=1}^{\infty}\mathbb{P}(N_{\Delta t}=k)  \mathbb{E}_{\bx}\Big[ u^{i-1}(t_{i-1},\tX_{t_{i-1}})  -\Is[u^{i-1}_{\ast}](\tX_{t_{i-1}})  \big| N_{\Delta t}=k\Big]  \Big\|_{L^2(\Omega)} \\
&\leq \sum_{k=1}^{\infty}\mathbb{P}(N_{\Delta t}=k)  \Big\| \mathbb{E}_{\bx}\Big[ u^{i-1}(t_{i-1},\tX_{t_{i-1}})  -\Is[u^{i-1}_{\ast}](\tX_{t_{i-1}})  \big| N_{\Delta t}=k\Big]  \Big\|_{L^2(\Omega)}
\\&\leq \Delta t  \| e^{i-1}\|_{L^2(\Omega)}.
\end{split}
\end{equation}
A combination of the above results leads to the desired result.
\end{proof}

\begin{lemma}
\label{lemB3} {\em
Let $u(\bx,t_{i-1})$ be the solution of \eqref{mainprob} at time grid $t_{i-1}$.  
We assume that $u_{t}\in L^\infty(\mathcal{T}_i;L^2(\Omega))$ and $f(\cdot)$ fulfills the Lipschitz condition \eqref{Lipscond}. Then, it holds that

 \begin{equation}
 \label{bounB3}
 B^{i}_{3}\leq C (\Delta t)^2\|u_t\|_{L^\infty(\mathcal{T}_i;L^2(\Omega))},
 \end{equation}
where $C$ is a positive constant independent of $\Delta t$ and $u$.}
\end{lemma}
\vspace{-20pt}
\begin{proof}
Since the expectation is taken in $ L^2(\Omega) $, we can leverage linearity and additivity to rewrite $ B^i_3 $ as:
\[
B^{i}_3 = \Big\| \mathbb{E}_{\tX_{t_{i-1}}=\bx}\Big[ \int_{t_{i-1}}^{t_{i} \land \tau_{i}} \Big( f(  u(s, \tX_{s})) - f( u^{i-1}(t_{i}, \tX_{s})) \Big) \, \mathrm{d}s \Big] \Big\|_{L^2(\Omega)}.
\]
Using the mean-value Theorem and Cauchy-Schwarz inequality, we find that
\begin{eqnarray}
\label{Schwarzineq}
&&B^{i}_{3}
\leq\Big\| \mathbb{E}_{\tX_{t_{i-1}}=\bx}\Big[ \int_{t_{i-1}}^{t_{i} \land \tau_{i}} \Big( f(  u(s, \tX_{s})) - f( u^{i-1}(t_{i}, \tX_{s})) \Big) \, \mathrm{d}s \Big] \Big\|_{L^2(\Omega)}.\nonumber\\
&&\quad\leq L\Big\| \mathbb{E}_{\tX_{t_{i-1}}=\bx}\Big[  \int_{t_{i-1}}^{t_{i}\land \tau_{i}} \big|u(s, \tX_{s}) - u^{i-1}(t_{i}, \tX_{s})|\,\d s\Big]\Big\| _{L^2(\Omega)} \nonumber\\
&&\quad\leq L\|u_t\|_{L^\infty(\mathcal{T}_i;L^2(\Omega))}\Big\| \mathbb{E}_{\tX_{t_{i-1}}=\bx}\Big[ \int_{t_{i-1}}^{t_{i}\land \tau_{i}}(s-t_{i-1})\, \d s\Big]\Big\| _{L^2(\Omega)} \\
&&\quad\leq L\|u_t\|_{L^\infty(\mathcal{T}_i;L^2(\Omega))}\Big\| \mathbb{E}\Big[ (t_{i}\land \tau_{i}-t_{i-1})^2\Big]\Big\| _{L^2(\Omega)}\nonumber
\\&&\quad\leq C_{L}(\Delta t)^2\|u_t\|_{L^\infty(\mathcal{T}_i;L^2(\Omega))},\nonumber
\end{eqnarray}
which yields the error bound.
\end{proof}


 \begin{lemma}\label{lemB4} {\em 
Assume that $f(\cdot)$ satisfies the Lipschitz condition \eqref{Lipscond}, and $\mu,\sigma,c$ satisfy the conditions \eqref{cond1}-\eqref{cond3}, $\nabla^2 u\in L^\infty(I;\Omega)$, then we have
\begin{equation}
\label{boundB4}
B^{i}_{4}\leq C(\Delta t )^{2},
\end{equation}
where constant $C$ depends on upper bounds of $\mu$, $\sigma$, $c$, $f$ and their derivatives of $u$.}
\end{lemma}
\vspace{-20pt}
\begin{proof}
We derive from \eqref{EI}  and the Lipschitz condition \eqref{Lipscond} that
\begin{equation}\label{B4err}
\begin{split}
B^{i}_{4}&=\Big\| \mathbb{E}_{\bx}\Big[ \int_{t_{i-1}}^{t_{i}\land \tau_{i}}f( u^{i-1}(\tX_{s}))\,\d s  \Big]  -\mathbb{E}[\tau_{i}\land t_{i} - t_{i-1}]f(u^{i-1}(\tX_{t_{i}}))   \Big\|_{L^2(\Omega)}\\
&  \leq \Big\| \mathbb{E}_{\bx}\Big[ \int_{t_{i-1}}^{t_i \land \tau_i} \Big|f(u^{i-1}(\tX_s)) -f(u^{i-1}(\tX_{t_{i}}))  \Big|\,\d s  \Big] \Big\|_{L^2(\Omega)}
\\&\leq L \Big\| \mathbb{E}_{\bx}\Big[ \int_{t_{i-1}}^{t_i \land \tau_i} \big|u^{i-1}(\tX_s) -u^{i-1}(\tX_{t_{i}})  \big|\,\d s  \Big] \Big\|_{L^2(\Omega)}.
\end{split}
\end{equation}
For any $u^{i-1} \in C^2$, the variations of $u^{i-1}(\tX_s)$ can be expanded as 
\begin{equation}
\label{deltaui1}
u^{i-1}(\tX_{t_{i}}) = u^{i-1}(\tX_{s}) + \nabla u^{i-1}(\tX_{s}) \cdot (\tX_{t_{i}} -\tX_{s}) + \frac{1}{2} (\tX_{t_{i}} - \tX_{s})^\top \nabla^2 u^{i-1}(\xi) (\tX_{t_{i}} -\tX_{s}),
\end{equation}
where $ \xi \in [\tX_s, \tX_{t_i} ]$. On the other hand, the dynamics of stochastic process $\tX_t$ satisfies 
\begin{equation}
\label{XtiXs}
\tX_{t_i} -\tX_s =  \mu(s , \tX_{s} ) (t_{i}-s) + \sigma(s, \tX_{s} ) (W_{s} -W_{t_{i}}) + \sum_{k=1}^{N_{\Delta t}}c(t,\tX_{s},\bz_{k}).
\end{equation}
Since $\mu$ and $\sigma$ are assumed to be bounded, the increment of $\mu(s, \tX_{s})$ over a small time interval $[s,t_{i}]$ is of order $\mathcal{O}(t_{i} - s)$, and $\sigma(s, \tX_{s})(W_{t_{i}} - W_{s})$, where $(W_{t_{i}} - W_{s}) \sim \mathcal{N}(0, t_{i} - s)$, is of order $\mathcal{O}(\sqrt{t_{i} - s})$. Similarly, it is readily verified that the term $\sum_{k=1}^{N_{\Delta t}} c(t, X_{s}, \bz_{k})$ is of order $\mathcal{O}(t_{i} - s)$.

Substituting \eqref{XtiXs} into \eqref{deltaui1} and combining it with \eqref{B4err}, we obtain that
\begin{equation*}
\begin{split}
B_{4}^{i}  
& \leq L\Big\| \mathbb{E}_{\bx}\Big[ \int_{t_{i-1}}^{t_i \land \tau_i} \Big| \nabla u^{i-1}(\tX_{s}) \cdot (\tX_{t_{i}} - \tX_{s}) + \frac{1}{2} (\tX_{t_{i}} - \tX_{s})^\top \nabla^2 u^{i-1}(\xi) (\tX_{t_{i}} - \tX_{s}) \Big|\,\d s  \Big] \Big\|_{L^2(\Omega)} \\
&\leq L\Big\| \mathbb{E}_{\bx}\Big[ \int_{t_{i-1}}^{t_i \land \tau_i} | \nabla u^{i-1}(\tX_{s}) \cdot (\tX_{t_{i}} - \tX_{s})  |\,\d s  \Big] \Big\|_{L^2(\Omega)} \\
&\quad +L\Big\| \mathbb{E}_{\bx}\Big[ \int_{t_{i-1}}^{t_i \land \tau_i} \Big|\frac{1}{2} (\tX_{t_{i}} - \tX_{s})^\top \nabla^2 u^{i-1}(\xi) (\tX_{t_{i}} - \tX_{s}) \Big|\,\d s  \Big] \Big\|_{L^2(\Omega)} \\
&\leq L \Big\| \mathbb{E}_{\bx}\Big[ \int_{t_{i-1}}^{t_i \land \tau_i} |\nabla u^{i-1}(\tX_{s}) |\cdot\Big|  \mu(s ,  \tX_{s} ) (t_{i}-s) 
\\&\quad\quad+ \sigma(s,  \tX_{s} ) (W_{s} -W_{t_{i}}) + \sum_{k=1}^{N_{\Delta t}}c(t,\tX_{s},\bz_{k})\Big|\,\d s  \Big] \Big\|_{L^2(\Omega)} \\
&\quad +L\Big\| \mathbb{E}_{\bx}\Big[ \int_{t_{i-1}}^{t_i \land \tau_i} \Big|\frac{1}{2} (\tX_{t_{i}} -  X_{s})^\top \nabla^2 u^{i-1}(\xi) (\tX_{t_{i}} -  X_{s}) \Big|\,\d s  \Big] \Big\|_{L^2(\Omega)}.
\end{split}
\end{equation*}
Due to the martingale property of the Brownian motion, we have 
$$\mathbb{E}_{\bx}\Big[ \int_{t_{i-1}}^{t_i \land \tau_i}  \sigma(s,   X_{s} ) (W_{s} -W_{t_{i}}) \d s \Big] =0.$$
Moreover, the probability of the Poisson process $N_t$ experiencing $k$ jumps is characterized by \eqref{PNk}, and its upper bound is given by
$$\sum_{k=1}^{\infty} \mathbb{P}(N_{\Delta t} = k) = \mathcal{O}(\Delta t),$$ which implies 
$$L\Big\| \mathbb{E}_{\bx}\Big[ \int_{t_{i-1}}^{t_i \land \tau_i}|\nabla u^{i-1}( X_{s}) |\cdot \Big|  \mu(s ,   X_{s} ) (t_{i}-s) + \sum_{k=1}^{N_{\Delta t}}c(t, X_{s},\bz_{k})\Big|\,\d s  \Big] \Big\|_{L^2(\Omega)} \leq C(\Delta t)^{2}.$$
Similarly, we have  
\begin{equation}
    \mathbb{E}_{\bx}\Big[ \int_{t_{i-1}}^{t_i \land \tau_i} \Big|\frac{1}{2} ( X_{t_{i}} -  X_{s})^\top \nabla^2 u^{i-1}(\xi) ( X_{t_{i}} -  X_{s}) \Big|\,\d s  \Big] \leq C(\Delta t)^2,
\end{equation}
which establishes the error bound.
\end{proof}




\begin{lemma}
\label{lemB5} {\em
 Let $u(\bx,t_{i-1})$ and $u_\ast^{i-1}(\bx)$ be the solution of \eqref{mainprob} and \eqref{ui} at time grid $t_{i-1}$, respectively.
Assume that $f(\cdot)$ satisfies the Lipschitz condition \eqref{Lipscond}, $\sigma$ satisfy the conditions of \eqref{cond2}and \eqref{cond4}, and $\kappa\ge (\Delta t)^{-1/2}$, then  
\begin{equation}
\label{boundB5}
\begin{split}
B^{i}_{5} \leq   C\Delta t\|e^{i-1}\|_{L^2(\Omega)},
\end{split}
\end{equation}
where the positive constant $C$ is indedepent of $u$ and $\Delta t$.}
\end{lemma}\vspace{-20pt}
\begin{proof}
We derive from the Lipschitz condition, Cauchy-Schwarz inequality, \eqref{intdensity}, and \eqref{EI}  that
\begin{equation*}
\begin{split}
B^{i}_{5}
&=\Big\| \mathbb{E}_{\tX_{t_{i-1}}=\bx}\Big[(\tau_{i}\land t_{i} - t_{i-1})\big( f(u^{i-1}(\tX_{t_{i}}))  -f(\Is[u^{i-1}_{\ast}](\tX_{t_{i}})) \big) \Big] \Big\|_{L^2(\Omega)}
\\&=\Big(\int_{\Omega}\mathbb{E}_{\tX_{t_{i-1}}=\bx}\Big[(\tau_{i}\land t_{i} - t_{i-1})\big( f(u^{i-1}(\tX_{t_{i}}))  -f(\Is[u^{i-1}_{\ast}](\tX_{t_{i}})) \big) \Big]^2\,\d\bx\Big)^{\frac12} 
\\&\leq C \Delta t \Big(\int_{\Omega}  \Big(  \int_{\R^{d}} \big( u^{i-1}(t_{i-1},\by)  -\Is[u^{i-1}_{\ast}](\by) \big)^{2}\,\d\by \Big)  \cdot\Big(  \int_{\R^{d}} \Big( p_{\Delta t}(\bx,\by) \Big)^{2}\,\d\by  \Big)  \d\bx \Big)^{1/2}
\\&\leq C \Delta t\Big(\int_{\Omega} \int_{\R^{d}} \big( u^{i-1}(t_{i-1},\by)  -\Is[u^{i-1}_{\ast}](\by) \big)^{2} \,\d\by\d\bx \Big)^{1/2} 
\\&\leq C \Delta t\|e^{i-1}\|_{L^2(\Omega)}. 
\end{split}
\end{equation*}
 This ends the proof.
\end{proof}


With the above analysis, the error bound $\|e^N\|_{L^{2}(\Omega)}$ can be easily derived as below.
\begin{theorem}
\label{EN}
Let $u(\bx,t_i)$ and $u^i_\ast(\bx)$ be the solutions of \eqref{mainprob} and \eqref{ui}, respectively. Assume that $\nabla^2 u\in L^\infty(I;\Omega),$ $u_t\in L^\infty(I;L^2(\Omega))$, $f(\cdot)$ fulfills the Lipschitz condition \eqref{Lipscond} and $\mu,\sigma,c$ satisfy the conditions \eqref{cond1}-\eqref{cond4},  and $\kappa\ge (\Delta t)^{-1/2}$, then there holds 
\begin{equation}\begin{split}
\label{eN}
\|u(\cdot,T)-u^N_\ast\|_{L^2(\Omega)}\leq  CM^{-1/2} +C\Delta t\|u_t\|_{L^\infty(0,T;L^2(\Omega))}+C\Delta t,
\end{split}\end{equation}
where $C$ is a positive constant independent of $\Delta t$ and $M$.
\end{theorem}\vspace{-20pt}
\begin{proof}
For $g(\bx,t)=0$, we only need to consider the case with $\tau_{i}>t_{i}$, it is obvious that 
\begin{equation*}
\begin{split}
B^{i}_{2}  \leq\Big\|  \mathbb{E}_{\bx}\Big[\Is[u^{i-1}_{\ast}](\tX_{t_{i}}) \mathbb{I}_{\tau_{i}>t_{i}}    \Big] - \frac{1}{M}\sum_{j=1}^{M}\Big[\Is[u^{i-1}_{\ast}](\tX_{t_{i},j} )\mathbb{I}_{\tau_{i}>t_{i}}   \Big]  \Big\|_{L^2(\Omega)}\leq  CM^{-1/2}. 
\end{split}
\end{equation*}
Similarly, we have
\begin{equation*}
\begin{split}
B^{i}_{6}= \Big\|\mathbb{E}[\tau_{i}\land t_{i} - t_{i-1}]f(\Is[u^{i-1}_{\ast}](\tX_{t_{i}}))-  \frac{1}{M}\sum_{j=1}^{M}(\tau_{i}\land t_{i} - t_{i-1})f(\Is[u^{i-1}_{\ast}])(\tX_{t_{i},j})  \Big\|_{L^2(\Omega)} \leq CM^{-1/2}.
\end{split}
\end{equation*}
By \eqref{mainerr}, and Lemma \ref{lemB1}-Lemma\ref{lemB5}, we deduce that
\begin{equation}\label{eijk}
\begin{split}
\|e^{i}\|_{L^2(\Omega)} \leq  \| e^{i-1}\|_{L^2(\Omega)} +C M^{-1/2}+C (\Delta t)^2\|u_t\|_{L^\infty(\mathcal{T}_i;L^2(\Omega))}+C(\Delta t )^{2}.
\end{split}
\end{equation}
Summing \eqref{eijk} from $i=1$ to $i=N$ and using the fact that $\|e^{0}\|_{L^2(\Omega)}=0$, we can easily obtain the desired results \eqref{eN}. 
\end{proof}
