     \begin{exa}  
 Next, we consider a problem on a 100-dimensional cubic domain $\Omega= [-1,1]^{100}\subset\R^{100}$ to further validate the applicability of the algorithm developed in this paper for high-dimensional problems. To do this, we will consider the following problem.
 \begin{equation}
\begin{cases}
\partial_{t}u(t,\bx) -\mathcal{L}[u](t,\bx)  =f(u),\;&(t,\bx) \in (0,T]\times \Omega,\\[4pt]
u(t,\bx) = g(t,\bx),\;&(t,\bx) \in (0,T]\times \Omega_{v},\\[4pt]
u(0,\bx) =u_{0}(\bx),\quad &\bx\in  \Omega \cup \Omega_{v}.
\end{cases}
\end{equation}
The the non-divergence form operator $\mathcal{L}$ in the above equation is defined by
\begin{eqnarray}
\mathcal{L}[u](t,\bx)  =& \frac 1 2 \text{\rm Trace} \big( \sigma(t,\bx) \sigma(t,\bx)^{\top} \text{\rm Hess}_{\bx}u(t,\bx) \big) + \langle  \mu(t,\bx), \nabla_{\bx}u(t,\bx) \rangle_{\R^{n}},
\end{eqnarray}
where
\begin{equation*}
 \begin{split}
&\mu(t,\bx) = [\mu(t,x_{1}),\cdots, \mu(t,x_{n})],\;\;   \mu(t,x_{i}) =  \frac{\sin(t)}{1+t^{2}}e^{-x_{i}^{2}},\\
&\sigma(t,\bx) = e^{-5t}\begin{pmatrix}
  \cos(x_{1} + x_{2}) &\cdots&0&0 \\
  %0 & \sin^{2}(\pi\bx_{2}) &0&0\\
 \vdots&  \ddots& \vdots&\vdots\\[6pt]
 0&\cdots& \cos(x_{n-1} + x_{n}) &0\\[6pt]
  0&\cdots& 0&\sin(x_{n})
\end{pmatrix},\\
&\varphi(\bz) =0, \;\;c(t,\bx,\bz) =0,
 \end{split}
 \end{equation*}
 it has the following exact solutions:
 \begin{equation}\label{exactsolu1}
 u(t,\bx) =  \cos(t^{2})e^{-|\bx|^{2}},\;\;\;(t,\bx)\in [0,\infty)\times\Omega,
 \end{equation}
which determines the initial condition $u^{0}(\bx)$,  the nonlinear forcing term $f(u)$ is given by
\begin{equation*}
 \begin{split}
&f(t,\bx,u) = -2t\sin(t^{2})e^{-|\bx|^{2}} + \cos(2t)\sum_{i=1}^{100} 2x_{i}e^{-x_{i}^{2}}\mu(t,x_{i})- \cos(2t)\sum_{i=1}^{100} (4x^{2}_{i}-2)e^{-x_{i}^{2}}\sigma(t,\bx_{i})^{2} /2\\
