\section{Performance Analysis}
We now present the performance of the proposed transmission shaping. 
As described earlier, given previous bits, $y_k^{(x_j)}$'s are independent binomial RVs i.e. $y_k^{(x_j)}\sim \Binom(x_j,h_{k-j+1})$. Hence, the distribution of $y_k$ given as
\begin{align}
y_k=\sum\nolimits_{j=1}^{(M+1)N} y_k^{(x_j)}+n_k
\end{align}
is complicated. However, under assumption of large $x_j$ and small $h_j$, binomial can be distributed well by Poisson distribution. Applying the fact that sum of Poisson RVs is also Poisson, $y_k$ turns out to be Poisson RV with mean $ \sum\nolimits_{j=1}^{(M+1)N} x_j h_{k-j+1}+\lambda_k$. Hence, given current and previous bits, $\vrx$ is a Poisson random vector with mean  
\begin{align*}
\mu_b=H_\Si \vX_b+\sum\nolimits_{\ell=1}^{M} H_{\Ii_\ell} \vX_{b[t-\ell]} + \lambda \mathbf{1} 
%\stackrel{\Delta}{=}\expect{\mathbf{y}|b[0]=b} =\underbrace{\vphantom{\sum_d^f}H_\Si \vX_b}_{\vY_{b\Si}} + \underbrace{\sum_{\ell=1}^{M} H_{\Ii_\ell} \vX_{b[t-\ell]} }_{\vY_{\Ii}}+ \lambda \mathbf{1} %\\
%\text{where } \lambda \mathbf{1} = [\lambda, \lambda, \ldots, \lambda]^T.
\end{align*}
with each element independently distributed as Poisson. 

\subsection{Optimal ML decoder}
As stated earlier, the optimal ML decoding rule is to decode 1 when $\vrx\in D(1)$ with 
%\begin{align*}
$D(1)=\{p(\mathbf{y}|b[0]=1)>p(\mathbf{y}|b[0]=0)\}$
%\end{align*}
where $p(\mathbf{y}|b[0]=b)$ denotes the likelihood of $\vrx$ for two values of bits. Assuming that the ISI term deviates only by small amount based on previous bit $b[\ell]$, we can approximate $\vrx |b[0]$ as Poisson with mean 
\begin{align*}
\mu_b=H_\Si \vX_b+\frac12 \sum\nolimits_{\ell=1}^{M} H_{\Ii_\ell} (\vX_{1}+\vX_{0}) + \lambda \mathbf{1} .
\end{align*}
This means that 
\begin{align}
p(\mathbf{y}|b[0]=b)=\prod_{k=1}^N \exp(-\mu_{bk}) \frac{\mu_{bk}^{\erx_k}}{\erx_k!}\label{eq:y_dist}
\end{align}
where $\mu_{bk}$ is the $k$th element of $\mu_b$. Applying the decoding rule, we get the following result.

\begin{theorem}\label{thm:opt_dec}
Under Poisson channel approximation, the ML
decoding region for bit 1  is
given as
\begin{align}
D(1)=\left\{ \vrx: \sum a_k \erx_k >c
\right\}
\end{align}
with $a_k=\ln\left(\frac{\mu_{1k}}{\mu_{0k}}\right)$  and $c=\mathbf{1}^\trsp 
 (\mu_{1}-\mu_{0})$.
\end{theorem}


\begin{IEEEproof}
Under ML decoding, the bit is decoded as 1 if
\begin{align*}
p(\mathbf{y}|b[0]=1)>p(\mathbf{y}|b[0]=0).
\end{align*}
Using \eqref{eq:y_dist}, the above is equivalent to
\begin{align*}
\prod_{k=1}^N \exp(-\mu_{1k}) \frac{\mu_{1k}^{\erx_k}}{\erx_k!}
>
\prod_{k=1}^N \exp(-\mu_{0k}) \frac{\mu_{0k}^{\erx_k}}{\erx_k!}.
\end{align*}
Applying logarithm on both sides, we have
\begin{align*}
\sum_{k=1}^N -\mu_{1k}+{\erx_k} \ln \mu_{1k} >
\sum_{k=1}^N -\mu_{0k}+{\erx_k} \ln \mu_{0k} .
\end{align*}
Simplifying it, we get the desired result.
\end{IEEEproof}


Note that $ \mu_{1}-\mu_{0}=H_\Si (\vX_1-\vX_0)$. It is important to note that all samples are not weighted equally in the decoder. 


