\begin{overpic}%[grid,tics=10] 
{LSdiagram}
\footnotesize
\put(151, 54){$(+1)$}
\put(151, 67){$(s_1)$}
\put(151, 79){$(s_2)$}
\put(151, 91){$(s_3)$}
\put(347, 49){$(+1)$}
\put(347, 61){$(+1)$}
\put(347, 73){$(-1/r_1)$}
