\maketitle

\begin{abstract}
\noindent \textit{Abstract.} We investigate several relations between cardinal characteristics of the continuum related with the asymptotic density of the natural numbers and some known cardinal invariants. Specifically, we study the cardinals of the form $\mathfrak{s}_X$, $\mathfrak{r}_X$ and $\mathfrak{dd}_{X,Y}$ introduced in \cite{FARKAS_KLAUSNER_LISCHKA_2023} and \cite{brech2024densitycardinals}, answering some questions raised in these papers. In particular, we prove that $\mathfrak{s}_0=$ cov$(\mathcal{M})$ and $\mathfrak{r}_0=$ non$(\mathcal{M})$. We also show that $\mathfrak{dd}_{\{r\}, \textsf{all}}=\mathfrak{dd}_{\{1/2\}, \textsf{all}}$ for all $r\in (0,1)$, and we provide a proof of Con($\mathfrak{dd}_{(0,1),\{0,1\}}^{\textsf{rel}}<$ non$(\mathcal{N})$) and Con($\mathfrak{dd}_{\textsf{all},\textsf{all}}^{\textsf{rel}}<$ non$(\mathcal{N})$).

\hspace{2mm}

\noindent \textit{Key words and phrases:} cardinal characteristics of the continuum, asymptotic density, rearrangement, splitting number, reaping number, density number

\hspace{1mm}

\noindent \textit{2020 Mathematics Subject Classification:} 03E17, 03E35

\end{abstract}




\section{Introduction}

Given a subset $A$ of $\omega$, the \textit{lower density} of $A$ is 
\[
\underline{d}(A):= \liminf_{n \to \infty} \frac{|A\cap n|}{n},
\]
and the \textit{upper density} of $A$ is 
\[
\overline{d}(A):= \limsup_{n \to \infty} \frac{|A\cap n|}{n}
\]
We say that $A$ has density $r\in[0,1]$ if $d(A):=\lim_{n \to \infty} \frac{|A \cap n|}{n}=r$. Lately, many cardinal invariants have been defined using this notion of asymptotic density, particularly to create variants of the splitting or reaping number (see \cite{Brendle_2023}), or to answer the question of how
many permutations are necessary to alter the density of infinite-coinfinite sets (see \cite{brech2024densitycardinals}). In this paper, we provide several new results about these cardinals and its relations with known cardinal characteristics. First, let us recall main definitions. Say $d(A)=$ \textsf{osc} if $\underline{d}(A)< \overline{d}(A)$. Define \textsf{all}:= $[0,1]\cup \{\textsf{osc}\}$. 

\begin{defn}\label{density cardinals}
Assume $X,Y \subseteq$ \textsf{all} are such that $X\neq \emptyset$ and for all $x\in X$ there is $y \in Y$ with $x\neq y$. The \textit{$(X,Y)$-density number} $\mathfrak{dd}_{X,Y}$ is the smallest cardinality of a family $\Pi\subseteq$ Sym$(\omega)$ such that for every infinite-coinfinite set $A\subseteq \omega$ with $d(A)\in X$ there is $\pi \in \Pi$ such that $d(\pi[A])\in Y$ and $d(\pi[A])\neq d(A)$. 
\end{defn}

In \cite{brech2024densitycardinals}, they give many upper and lower bounds for these cardinals and prove that $\mathfrak{dd}_{[0,1],\textsf{all}}=$ non$(\mathcal{M})$, where non$(\mathcal{M})$ stands for the uniformity of the ideal of the meager sets. However, it is still an open problem if one cardinal of the form $\mathfrak{dd}_{X,Y}$ is consistently different from a known cardinal characteristic. We found that there is a relation with other cardinals defined using relative density. 

\begin{defn}
Let $A$ and $B$ be subsets of $\omega$. Define the \textit{lower relative density of $A$ in $B$}
\[
\underline{d}_B(A)= \liminf_{n\to\infty} \frac{|A\cap B \cap n|}{|B\cap n|}
\]
and the \textit{upper relative density of $A$ in $B$}
\[
\overline{d}_B(A)= \limsup_{n\to\infty} \frac{|A\cap B \cap n|}{|B\cap n|}
\]
If $\underline{d}_B(A)=\overline{d}_B(A)$, the common value $d_B(A)$ is the \textit{relative density of $A$ in $B$}. Say $d_B(A)=$ \textsf{osc} if $\underline{d}_B(A)<\overline{d}_B(A)$.
\end{defn}

\begin{defn}\label{Xreaping}
Let $X$ be a nonempty subset of \textsf{all}. The \textit{$X$-reaping number} $\mathfrak{r}_X$ is the smallest cardinality of a family $\mathcal{R} \subseteq [\omega]^\omega$ such that for all $r\in X$ and for all infinite-coinfinite subsets $S$ of $\omega$ there is $R\in \mathcal{R}$ such that $d_R(S)\neq r$. 
\end{defn}

In figure \ref{Main relations}, we present the most important relations between these cardinals established in this paper. Note that $\mathfrak{r}_{\{1/2\}}$ is the $1/2$-reaping number $\mathfrak{r}_{1/2}$ presented in \cite{Brendle_2023}, so to keep this notation, we just write $\mathfrak{r}_{\rho}$ when $X=\{\rho\}$. In any case, Farkas, Klausner and Lischka prove $\mathfrak{r}_\rho=\mathfrak{r}_{1/2}$ for all $\rho\in(0,1)$ (see \cite[Theorem 5.3]{FARKAS_KLAUSNER_LISCHKA_2023}). There is a similar behavior with the density numbers. In Section \ref{section 1}, we prove $\mathfrak{dd}_{\{1/2\},\textsf{all}}=\mathfrak{dd}_{\{r\},\textsf{all}}$ for all $r\in(0,1)$ giving an answer to \cite[Conjecture 40]{brech2024densitycardinals}.


