\section{An invariant two-variable series}
\label{sec:qtseries}

Here we define a three-variable series and show that it is an invariant of closed plumbed $3$-manifolds. We also show that the series is invariant under the action of the Weyl group, thus proving Theorem \ref{thm:qtseriesinvarianceintroreduced}.


\subsection{The Kostant collection}
\label{sec:K}
Consider the formal series
\begin{equation}
\label{eq:Wz}
K(z):= \prod_{\alpha\in \Delta^+}\left(\sum_{i\geq 0} z^{-(2i+1)\alpha} \right).
\end{equation}
Here $z^\alpha$ for a root $\alpha$ is a multi-index monomial defined as
\begin{equation}
\label{eq:zpowers}
z^\alpha :=\prod_{i=1}^r z_i^{\langle \alpha^\vee, \lambda_i\rangle}
\end{equation}
with $\alpha^\vee:=\frac{2}{\langle \alpha, \alpha\rangle}\alpha$ being the coroot of $\alpha$ and
$\lambda_1,\dots,\lambda_r$ being the fundamental weights. Hence $K(z)\in \mathbb{Z}\left\llbracket z_1^{- 1}, \dots, z_r^{- 1}\right\rrbracket$, the ring of formal series in variables $z_1^{- 1}, \dots, z_r^{- 1}$.

Expanding, one has
\[
K(z) = \sum_{\alpha\in Q} k(\alpha)\, z^{-2\rho-2\alpha}
\]
where $k(\alpha)$ is the \textit{Kostant partition function} defined as
\begin{equation}
\label{eq:Kostant}
k(\alpha):= 
\begin{array}{l}
\mbox{number of ways to represent $\alpha$} \\ 
\mbox{as a sum of positive roots.}
\end{array}
\end{equation}
A key property of the series $K(z)$ is the identity
\begin{equation}
\label{eq:P2}
\left(\sum_{w\in W} (-1)^{\ell(w)}\, z^{2w(\rho)}\right)K(z) =1.
\end{equation}
When $Q=A_1$, this follows from a direct computation, and for arbitrary $Q$ this follows from the $A_1$-case and the Weyl denominator formula
\begin{equation}
\label{eq:Weyldenomformula}
\sum_{w\in W} (-1)^{\ell(w)}\, z^{2w(\rho)} = \prod_{\alpha \in\Delta^+} \left( z^\alpha - z^{-\alpha} \right).
\end{equation}

More generally, for $x\in W$, define the \textit{Weyl twist} of $K(z)$ by $x$ as
\begin{equation}
\label{eq:Ktwist}
K_x(z) = (-1)^{\ell(x)}\sum_{\alpha\in Q} k(\alpha)\, z^{-x(2\rho+2\alpha)}.
\end{equation}
For $x\in W$, consider the following collection of series
\begin{equation}
\label{eq:Kxn}
K_{x,n}(z):=
\left\{
\begin{array}{ll}
\left(\sum\limits_{w\in W} (-1)^{\ell(w)}\, z^{2w(\rho)}\right)^2 & \mbox{if $n=0$,}\\[12pt]
\sum\limits_{w\in W} (-1)^{\ell(w)}\, z^{2w(\rho)} & \mbox{if $n=1$,}\\[12pt]
1 & \mbox{if $n=2$,}\\[12pt]
\left(K_x(z)\right)^{n-2} & \mbox{if $n\geq 3$.}
\end{array}
\right.
\end{equation}
We will refer to this as the \textit{Kostant collection}.
The series $K_{x,n}(z)$ for $n\in\{0,1,2\}$ does not depend on $x$.



\subsection{The $q$-series}
Let $\Gamma$ be a plumbing tree, and let $M:=M(\Gamma)$ be the $3$-man\-i\-fold obtained by plumbing along $\Gamma$. After a sequence of Neumann moves, one can assume that $\Gamma$ is reduced. Consider a tuple
\begin{equation}
\label{eq:tau}
\tau=\left(Q, a, \xi\right)
\end{equation}
with
\begin{enumerate}[(i)]
\item $Q$ a root lattice;
\item $a \in {\delta} +2Q^{s}$ a representative of a $\mathrm{Spin}^c$-structure
$[a] \in \mathrm{Spin}^c_Q(M)$ as in \eqref{spinc-isomorphism}, with $s=|V(\Gamma)|$;
\item $\xi \in \Xi$ a Weyl assignment on $\Gamma$ as in \S\ref{sec:Weylassignments}.
\end{enumerate}
Define the series 
\[
\mathsf{Y}_\tau\left(q\right) = \mathsf{Y}_\tau\left(M(\Gamma);q\right) 
\]
as
\[
\mathsf{Y}_\tau\left(q \right):= 
(-1)^{|\Delta^+| \,\pi}
q^{\frac{1}{2}(3\sigma-\mathrm{tr}\,B)\langle \rho, \rho \rangle} \sum_{\ell\in a + 2BQ^s}
c_{\Gamma, \xi} (\ell)
\,q^{-\frac{1}{8}\langle \ell, \ell\rangle}
\]
where 
\begin{align}
\label{eq:cgammaxi}
c_{\Gamma, \xi}(\ell) := \prod_{v\in V(\Gamma)} \left[ K_{\xi_v,\deg v}(z_v) \right]_{\ell_v} \in \mathbb{Z}.
\end{align}
The operator $[\,\,]_\alpha$ assigns to a series in $z$ the coefficient of the monomial $z^\alpha$. 
Lastly, $\ell_v\in Q$ denotes the $v$-component of $\ell\in Q^s= Q^{V(\Gamma)}$ for $v\in V(\Gamma)$.

\smallskip

The series $\mathsf{Y}_\tau\left(q\right)$ is not always well defined. In fact, if the framing matrix $B$ is negative definite (or more generally, weakly negative definite, as in \cite[Def.~4.3]{gukov2021two}), 
then the series $\mathsf{Y}_\tau\left(q\right)$ exists and one has
\[
\mathsf{Y}_\tau\left(q\right)
\in q^{\frac{1}{2}(3\sigma-\mathrm{tr}\,B)\langle \rho, \rho \rangle -\frac{1}{8} \langle a, a \rangle} \,\mathbb{Z} 
\left(\! \left(q^{\frac{1}{2}}\right)\!\right).
\]
Indeed, in those cases, the exponents of $q$ are bounded below, and there are only finitely many $\ell$ that contribute to each power of $q$. (See also \cite[Lemma 3.2]{MT1}.) One uses that $\langle \ell, \ell \rangle = \langle a, a \rangle + 4\mathbb{Z}$ for $\ell\in a+2BQ^s$ to conclude that the powers of $q$ are half-integers, up to an overall rational shift.

A similar statement holds if $B$ is positive definite (or weakly positive definite), and in this case one replaces $q$ with $q^{-1}$, that is, $\mathsf{Y}_\tau\left(q\right)$ is Laurent in $q^{-\frac{1}{2}}$, up to an overall factor given by a rational power of $q$.

However, for an arbitrary invertible framing matrix $B$, the values $\langle \ell, \ell \rangle$ in the exponent of $q$ may not be bounded above nor below, and there might be infinitely many $\ell$ that contribute to the same value $\langle \ell, \ell \rangle$.
To overcome this issue, we introduce a new variable $u$.



\subsection{The $(q,t)$-series}
For  a reduced plumbing tree $\Gamma$ with invertible framing matrix and for $\tau=\left(Q, a, \xi\right)$ as in \eqref{eq:tau}, define the series 
\[
\mathsf{Y}_\tau\left(q,t\right) = \mathsf{Y}_\tau\left(M(\Gamma);q,t\right) 
\]
as
\[
\mathsf{Y}_\tau\left(q,t \right):= 
(-1)^{|\Delta^+| \,\pi}
q^{\frac{1}{2}(3\sigma-\mathrm{tr}\,B)\langle \rho, \rho \rangle} \sum_{\ell\in a + 2BQ^s}
c_{\Gamma, \xi} (\ell)
\,t^{\xi^{-1}(\ell)}
\,q^{-\frac{1}{8}\langle \ell, \ell\rangle}
\]
with $c_{\Gamma, \xi} (\ell)$ as in \eqref{eq:cgammaxi} 
and
\begin{equation}
\label{eq:exp_t}
\xi^{-1}(\ell): = \sum_{v} \xi^{-1}_v\left(\ell_v\right) \in Q.
\end{equation}
Thus $t^{\xi^{-1}(\ell)}$ is a multi-index monomial in variables $t_1,\dots, t_r$ as in \eqref{eq:zpowers}.


\begin{lemma}
\label{lem:Yqtring}
For the series $\mathsf{Y}_\tau\left(q,t \right)$, the exponents of $t$ are bounded above, and there are only finitely many $\ell$ that contribute to each power of $t$. 
Thus $\mathsf{Y}_\tau\left(q, t\right)$ exists for all reduced plumbing trees having invertible framing matrix and is an element of  the following ring:
\[
\mathsf{Y}_\tau\left(q, t\right)
\in q^{\frac{1}{2}(3\sigma-\mathrm{tr}\,B)\langle \rho, \rho \rangle -\frac{1}{8} \langle a, a \rangle} \mathbb{Z}
 \left[q^{\pm \frac{1}{2}}\right]
\left(\! \left( t_1^{-1}, \dots, t_r^{-1} \right)\!\right).
\]
\end{lemma}

\begin{proof}
We analyze the definition in \eqref{eq:Kxn} and consider the cases when 
\begin{equation}
\label{eq:Kxnneq0}
\left[ K_{x,\deg v}(z_v) \right]_{\ell_v}\neq 0.
\end{equation}
For a vertex $v$ with $\deg v\leq 2$, there are only finitely many $\ell_v$ such that \eqref{eq:Kxnneq0} holds.
Instead for a vertex $v$ with $\deg v\geq 3$, if \eqref{eq:Kxnneq0} holds,
then necessarily $x^{-1}\left(\ell_v\right)$ is a sum of negative roots.
The statement follows.
\end{proof}

It may not be possible to evaluate the series $\mathsf{Y}_\tau\left(q,t\right)$ at $t=1$ (i.e., $t_1=\dots= t_r=1$),
as this might result in infinitely many contribution to a given monomial in~$q$. However, one has from the definition:

\begin{lemma}
If the series $\mathsf{Y}_\tau\left(q,t \right)$ can be evaluated at $t=1$, then one has 
$\mathsf{Y}_\tau\left(q,1 \right)=\mathsf{Y}_\tau\left(q\right)$.
\end{lemma}

While the series $\mathsf{Y}_\tau\left(q, t\right)$ is expressed in terms of a  plumbing presentation $\Gamma$ for $M$,  we show:

\begin{theorem}
\label{thm:qtseries}
Any two reduced plumbing trees for $M$ related by a sequence of the five Neumann moves $(A\pm), (B\pm), (C)$ yield the same series $\mathsf{Y}_\tau\left(q, t\right)$.
\end{theorem}



\subsection{Proof of invariance}
First we  prove the invariance of the $(q,t)$-series with respect to the action of the Weyl group and then prove Theorem~\ref{thm:qtseries}.

\begin{remark}
\begin{enumerate}[(i)]
\item In the arguments below, we apply various identities from \cite{MT1} concerning the coefficients $c_{\Gamma, \xi}(\ell)$ from \eqref{eq:cgammaxi}. For this, we emphasize that, despite some apparent differences in the definition, these  
$c_{\Gamma,\xi}(\ell)$ are equivalent to the ones from \cite{MT1}. Indeed, the difference stems from the fact that the Weyl assignments defined here are more general than the ones used in \cite{MT1}, as their values on vertices of degree $0$ and $1$ can  possibly be arbitrary here --- see Remark \ref{rmk:Wass}. However, $K_{x,\deg v}(z)$ is independent of $x$ for $\deg v\leq 2$, as in \cite{MT1}. Hence, the coefficients $c_{\Gamma, \xi}(\ell)$ from \eqref{eq:cgammaxi} are not affected by the change of the definition of Weyl assignments.

\item The extra flexibility of the present Weyl assignments on vertices of degree $0$ and $1$ plays a role in the exponents of the variable $t$. 
\end{enumerate}
\end{remark}

\begin{theorem}
\label{thm:Winvqtseries}
For $\ell\in \delta +2Q^s$, one has
\[
c_{\Gamma, \xi} (\ell) = c_{\Gamma, w(\xi) } (w(\ell))
 \qquad \mbox{for  $w\in W$}.
\]
This implies Theorem \ref{thm:qtseriesinvarianceintroreduced}(ii).
\end{theorem}

\begin{proof}
By the definition \eqref{eq:Kxn}, one has
\[
\left[K_{x,n}(z)\right]_{\ell} = (-1)^{\ell(w)n} \left[K_{wx,n}(z)\right]_{w(\ell)}.
\]
Multiplying over all vertices and using the fact that the sum of the degree of the vertices is even,
the first part of the statement follows.

Since $\xi^{-1}(\ell) = (w(\xi))^{-1}(w(\ell))$ and $\langle \ell, \ell\rangle = \langle w(\ell), w(\ell)\rangle$,
one has
\begin{align*}
c_{\Gamma, \xi} (\ell)
\,t^{\xi^{-1}(\ell)} 
\,q^{-\frac{1}{8}\langle \ell, \ell\rangle}
= c_{\Gamma, w\xi } (w(\ell))
\,t^{(w(\xi))^{-1}(w(\ell))}
\,q^{-\frac{1}{8}\langle w(\ell), w(\ell)\rangle}
\end{align*}
 for  $w\in W$.
Hence the statement.
\end{proof}

We now proceed to prove Theorem \ref{thm:qtseries}.

\begin{proof}[Proof of Theorem \ref{thm:qtseries}]
We argue that the series is invariant under each of the five Neumann moves between two reduced plumbing trees.
For each move, let $\Gamma$ be the bottom plumbing tree with framing matrix $B$
and $\Gamma_\circ$ the top plumbing tree with framing matrix $B_\circ$. The number of vertices of $\Gamma$ and $\Gamma_\circ$ will be denoted by $s$ and $s_\circ$, and the number of positive eigenvalues of $B$ and $B_\circ$ will be denoted by $\pi$ and $\pi_\circ$.

For each move, we first observe how the factor in front of the sum in the series
\begin{equation}
\label{eq:frontfactor}
(-1)^{|\Delta^+| \,\pi}
q^{\frac{1}{2}(3\sigma-\mathrm{tr}\,B)\langle \rho, \rho \rangle}
\end{equation}
changes. 
We then define an injective map
\[
R\colon Q^s \rightarrow Q^{s_\circ}
\]
inducing an isomorphism of $\spinc$-structures on $M(\Gamma)$ and $M(\Gamma_\circ)$ and an isomorphism
\[
S\colon \Xi \rightarrow \Xi_\circ
\]
of Weyl assignments for $\Gamma$ and $\Gamma_\circ$.
Thus for a tuple $\tau=(Q,a,\xi)$ for $\Gamma$, we prove
\[
\mathsf{Y}_\tau \left( M(\Gamma); q,t\right) = \mathsf{Y}_{\tau_\circ} \left( M(\Gamma_\circ); q,t\right)
\]
where $\tau_\circ=(Q, R(a),S(\xi))$.
For this, we argue that the contribution of each representative $\ell$ of the $\spinc$-structure $[a]$ to the series for $\Gamma$ 
matches a sum of contributions to the series for $\Gamma_\circ$.

\bigskip

\noindent \textit{Step (A$-$).} 
As shown in \cite[Proof of Thm 3.3]{MT1}, the factor \eqref{eq:frontfactor} in front of the sum in the series is invariant. 
The map $R$ for this move~is
\begin{equation*}
R\colon Q^s \rightarrow Q^{s+1}, \qquad
(a_1, a_2)\mapsto (a_1, 0,  a_2)
\end{equation*}
where the subtuple $a_1$ corresponds to the vertices of $\Gamma$ consisting of the vertex weighted by $m_1$ and all vertices on its left, and likewise $a_2$  corresponds to the vertex weighted by $m_2$ and all vertices on its right.
To define the map $S$, note that a Weyl assignment $\xi$ on $\Gamma$ uniquely determines a Weyl assignment $\xi_\circ$ on $\Gamma_\circ$ since the added vertex in $\Gamma_\circ$ has degree $2$ and all Weyl assignments assign $1_W$ to such a vertex.

From \cite[(4.3)]{MT1}, we have that
\begin{equation*}
c_{\Gamma, \xi}(\ell) \,
q^{-\frac{1}{8}\langle \ell, \ell\rangle} =
c_{\Gamma_\circ, \xi_\circ}(R(\ell))\,
q^{-\frac{1}{8}\langle R(\ell), R(\ell)\rangle}.
\end{equation*}

Moreover, since $\Gamma$ and $\Gamma_\circ$ differ only at a single degree-$2$ vertex and the corresponding component of $R(\ell)$ is $0$ by definition, one has
\[
\xi^{-1}_\circ (R(\ell)) = \xi^{-1}(\ell)  +1_w (0)= \xi^{-1}(\ell),
\]
where $\xi^{-1}_\circ=S(\xi^{-1})$, hence the exponents of $t$ match as well. 

\bigskip

\noindent \textit{Step (A$+$).} 
In this case,  the power of $q$ in the factor \eqref{eq:frontfactor} in front of the sum in the series is invariant. 
The function $R$ for this move is
\begin{equation*}
R\colon Q^s \rightarrow Q^{s+1}, \qquad
(a_1, a_2)\mapsto (a_1, 0, -a_2)
\end{equation*}
with notation as in the previous move.
The map $S$ is $\xi\mapsto\xi_\circ$ where
for a vertex $v$ with $\deg v \neq 2$, one has
\begin{equation*}
\xi_\circ \colon v \mapsto \left\{
\begin{array}{ll}
\xi_v & \mbox{if $v$ is on the left of the added vertex,}\\[0.5pt]
\iota \xi_v & \mbox{if $v$ is on the right of the added vertex} 
\end{array}
\right.
\end{equation*}
where $\iota$ is as in \eqref{eq:iota}.

From \cite[(4.8)]{MT1} one has that
\begin{equation*}
(-1)^{|\Delta^+|\pi}\, c_{\Gamma, \xi}(\ell) \,
q^{-\frac{1}{8}\langle \ell, \ell\rangle} =
(-1)^{|\Delta^+|\pi_\circ} \,c_{\Gamma_\circ, \xi_\circ}(R(\ell))\,
q^{-\frac{1}{8}\langle R(\ell), R(\ell)\rangle}.
\end{equation*}
As before  $\Gamma$ and $\Gamma_\circ$ differ only at a single degree-$2$ vertex.
Now, one has
\begin{align*}
\xi^{-1}_\circ(R(\ell)) 
&= \sum_{v\;\text{left} } \xi^{-1}_{\circ, v} \left(R(\ell)_v\right) +\sum_{v\;\text{right} } \xi^{-1}_{\circ, v} \left(R(\ell)_v \right)\\
&= \sum_{v\;\text{left} } \xi^{-1}_{v} \left(\ell_v \right)+\sum_{v\;\text{right} } \iota\xi^{-1}_{v}\left(-\ell_v\right) \\
&=\xi^{-1}(\ell),
\end{align*}
since $\iota\xi^{-1}_v\left(-\ell_v\right)  =\xi^{-1}_v\left(\ell_v\right)$ by linearity.
Thus the exponents of $t$ match. 

\bigskip

\noindent \textit{Step (B$-$).} 
Now the factor \eqref{eq:frontfactor} in front of the sum in the series for $\Gamma_\circ$ contains an extra factor $q^{-\frac{1}{2}\langle \rho, \rho\rangle}$.
The trees $\Gamma$ and $\Gamma_\circ$ differ only at a single leaf $v_0$ adjacent to a vertex $v_1$. 
For $w\in W$, consider the map from \cite[(4.9)]{MT1}
\begin{equation*}
R_w\colon Q^s \rightarrow Q^{s+1}, \qquad
(a_\sharp, a_1)\mapsto (a_\sharp, a_1+2w(\rho),  - 2 w(\rho)),
\end{equation*} 
where $a_1$ corresponds to the vertex $v_1$ of $\Gamma$, and $a_\sharp$ corresponds to all other vertices of $\Gamma$.
For the isomorphism between $\spinc$-structures, we use the map induced by $R:=R_{w}$ with $w=1_W$.

The condition \eqref{eq:forcingbridgescondition} implies that the map $S$ is given by $\xi\mapsto\xi_\circ$ where $\xi_\circ$ assigns $\xi_{v_0} =  \xi_{v_1}$ at $v_0$ and agrees with $\xi$ at all other vertices.

From \cite[(4.12)]{MT1}, we have
\begin{equation*}
c_{\Gamma, \xi}(\ell) \, q^{-\frac{1}{8}\langle \ell, \ell\rangle}
= 
q^{-\frac{1}{2}\langle \rho,\rho\rangle}
\sum_{w\in W}c_{\Gamma_\circ, \xi_\circ}(R_w(\ell))\,
q^{-\frac{1}{8}\langle R_w(\ell), R_w(\ell)\rangle}.
\end{equation*}
In the computation of the exponent of $t$, the vertices $v_0$ and $v_1$ contribute
\[
	\xi^{-1}_{v_1}\left(\ell_1 +2w(\rho)\right) + \xi^{-1}_{v_0}\left(-2w(\rho)\right) =\xi^{-1}_{v_1}\left(\ell_1 +2w(\rho) -2w(\rho)\right) =\xi^{-1}_{v_1}\left(\ell_1\right).
\]
Hence $\xi^{-1}_\circ\left(R_w(\ell)\right) =\xi^{-1}\left(\ell\right)$ for all $w\in W$. 

\bigskip

\noindent \textit{Step (B$+$).} 
The factor \eqref{eq:frontfactor} in front of the sum in the series for $\Gamma_\circ$ has an extra factor $(-1)^{|\Delta^+|}q^{\frac{1}{2}\langle \rho, \rho\rangle}$.
As with the previous move, $\Gamma$ and $\Gamma_\circ$ differ only at a single leaf $v_0$ adjacent to a common vertex $v_1$. 
For $w\in W$, consider the map from \cite[(4.13)]{MT1} 
\begin{equation*}
R_w\colon Q^s \rightarrow Q^{s+1}, \qquad
(a_\sharp, a_1)\mapsto (a_\sharp, a_1+2w(\rho),  2 w(\rho)).
\end{equation*}
As before, $R=R_{w}$ with $w=1_W$.
By \eqref{eq:forcingbridgescondition}, the map $S$ is given by $\xi\mapsto\xi_\circ$ where $\xi_\circ$ assigns 
$\xi_{v_0}  = \iota\xi_{v_1}$  at $v_0$ and agrees with $\xi$ at all other vertices.

From \cite[(4.16)]{MT1}, we have
\begin{align*}
&(-1)^{|\Delta^+|\, \pi}
c_{\Gamma, \xi}(\ell) \, q^{-\frac{1}{8}\langle \ell, \ell\rangle}\\
&= 
(-1)^{|\Delta^+|\, \pi_\circ}
q^{\frac{1}{2}\langle \rho,\rho\rangle}
\sum_{w\in W}c_{\Gamma_\circ, \xi_\circ}(R_w(\ell))\,
q^{-\frac{1}{8}\langle R_w(\ell), R_w(\ell)\rangle}.
\end{align*}
Moreover,
\[
	\xi^{-1}_{v_1}\left(\ell_1 +2w(\rho)\right) + \xi^{-1}_{v_0}\left(2w(\rho)\right) =\xi^{-1}_{v_1}\left(\ell_1 +2w(\rho) - 2 w(\rho)\right) =\xi^{-1}_{v_1}\left(\ell_1\right)
\]
since $\iota\xi^{-1}_{v_1}\left(2w(\rho)\right) = \xi^{-1}_{v_1}\left(-2w(\rho)\right)$ by linearity. Hence $\xi^{-1}_\circ\left(R_w(\ell)\right) =\xi^{-1}\left(\ell\right)$ for all $w\in W$. 

\bigskip

\noindent \textit{Step (C).} 
The factor \eqref{eq:frontfactor}  in front of the sum in the series for $\Gamma_\circ$ has an extra factor $(-1)^{|\Delta^+|}$.
Let $v_0$ be the vertex of $\Gamma$ with weight $m_1+m_2$, and let $v_1, v'_0, v_2$ be the vertices of $\Gamma_\circ$ with weights  $m_1, 0$, and $m_2$, respectively.
For $a\in Q^s$, write $a=(a_\sharp, a_0, a_\flat)$, where the entry $a_0$ corresponds to $v_0$, the subtuple $a_\sharp$ corresponds to all vertices on the left of $v_0$, and the subtuple $a_\flat$ to all vertices on the right of $v_0$.
For $\beta\in Q$, consider the map from \cite[(1.8)]{MT1}
\[
R_\beta\colon Q^s \rightarrow Q^{s+2}, \qquad
(a_\sharp, a_0, a_\flat)\mapsto (a_\sharp, a_0+\beta,0,\beta, -a_\flat)
\]
where the entries $a_0 + \beta, 0$, and $\beta$ correspond to the vertices $v_1, v'_0, v_2$ in $\Gamma_\circ$.
For $\beta=\beta_0$ defined as in \cite[(1.9)]{MT1}, the map $R=R_\beta$ induces an isomorphism of $\spinc$-structures.

The map $S$ is defined as $\xi\mapsto\xi_\circ$ such that, 
for a vertex $v$ with $\deg v \neq 2$, one has
\begin{equation*}
\xi_\circ \colon v \mapsto \left\{
\begin{array}{ll}
\xi_v & \mbox{if $v<v_1$,}\\[0.5pt]
\iota\xi_v & \mbox{if $v>v_2$.} 
\end{array}
\right.
\end{equation*}
Here $v<v'$ if $v$ is on the left of $v'$.
Moreover, define
\[
\xi_\circ \left( v_1\right) := \xi\left( v_0\right) \qquad\mbox{and} \qquad
\xi_\circ \left( v_2\right) := \iota\xi\left( v_0\right).
\]

From \cite[(4.22)]{MT1}, one has
\[
(-1)^{|\Delta^+|\, \pi}
c_{\Gamma,\xi}(\ell) 
q^{-\frac{1}{8}\langle \ell, \ell\rangle}=  
(-1)^{|\Delta^+|\, \pi_\circ} \sum_{\beta\in \beta_0+2Q}c_{\Gamma_\circ,\xi_\circ}(R_\beta(\ell))
q^{-\frac{1}{8}\langle R_w(\ell), R_w(\ell)\rangle}.
\]
Furthermore, for each $\beta$, one has
\begin{align*}
\xi^{-1}_\circ\left(R_\beta(\ell)\right) 
&= \sum_{v<v_1} \xi^{-1}_{\circ, v} \left(\ell_v \right)
+\xi^{-1}_{\circ, {v_1}}\left(\ell_0+\beta\right)
+\xi^{-1}_{\circ, {v_2}}\left(\beta\right)
+\sum_{v>v_2} \xi^{-1}_{\circ, v} \left( -\ell_v\right) \\
&= \sum_{v<v_1} \xi^{-1}_{v} \left(\ell_v \right)
+\xi^{-1}_{v_1}\left(\ell_0+\beta\right)
+\iota\xi^{-1}_{v_1}\left( \beta \right)
+\sum_{v>v_2} \iota\xi^{-1}_{v} \left(-\ell_v\right) \\
&= \sum_{v<v_0} \xi^{-1}_{v} \left(\ell_v \right)+ \xi^{-1}_{v_0}\left(\ell_{v_0}\right) +\sum_{v>v_0} \xi^{-1}_{v}\left(\ell_v\right) \\
&=\xi^{-1}(\ell),
\end{align*}
since $\iota\xi^{-1}_v(-\ell_v)  =\xi^{-1}_v(\ell_v)$ by linearity.
Thus $\xi^{-1}_\circ(R_\beta(\ell)) =\xi^{-1}(\ell)$ for all $\beta\in Q$. 

\smallskip

This concludes the proof of the statement.
\end{proof}





