\section{A gluing formula}
\label{sec:gluingformula}

We consider here a closed oriented 3-manifold $M$ obtained by gluing two plumbed knot complements and show how to obtain the $(q,t)$-series of $M$ from the $(q,t,z)$-series of the knot complements via a gluing formula.
We use notation as in \S\S\ref{sec:gluing}--\ref{subsec:spinc-gluing}.

Assume $M=M(\Gamma)$ is obtained by gluing a pair of plumbed knot complements  
\[
\left(M^\pm, \partial M^\pm\right)=M\left(\Gamma^\pm, v^\pm_0\right) 
\] 
along their boundaries. 
Assume that $\Gamma$ and $\Gamma^\pm$ are reduced and have invertible framing matrices.
Consider a tuple $\tau=(Q,a,\xi)$ for $M$ as in \eqref{eq:tau}. Starting from $a$, select
representatives
\[
{a}^+\in \widehat{\delta}^+ +2Q^{m} \qquad\mbox{and}\qquad {a}^-\in \widehat{\delta}^- +2Q^{n}
\]
of relative $\mathrm{Spin}^c$-structures $[a^\pm] \in \mathrm{Spin}^c_Q\left(M^\pm, \partial M^\pm\right)$ as in \eqref{eq:idspincgluing} 
such that \mbox{$a=a^+ \ast a^-$.} 
This condition implies that the isomorphism of $\mathrm{Spin}^c$-structures in \eqref{eq:spinciso} identifies $[a]$ with the orbit of $[a^+]\oplus[a^-]$ under the action of 
\[
H_1(\partial M^+;Q)\cong Q\langle\lambda, \mu\rangle.
\] 
Starting from $\xi$, define $\xi^\pm$ to be the Weyl assignments on $\Gamma^\pm$ given by restricting $\xi$.

\begin{theorem}
\label{thm:gluing}
One has
\begin{align}
\label{eq:gluid}
\mathsf{Y}_\tau\left(M; q, t\right) = 
(-1)^\triangle q^\square  
\sum_{\gamma \in Q}
 \left[\mathsf{Y}^+_{\gamma}(z)  \, \mathsf{Y}^-_{\gamma}(z)  \right]_0
\end{align}
where
\begin{align}
\begin{split}
\label{eq:trianglesquare}
	\triangle &:= |\Delta^+| \left( \pi(B)- \pi(B^+) -\pi(B^-) \right),\\
	\square &:= \frac{3}{2}\left(\sigma(B) - \sigma(B^+) - \sigma(B^-) \right)\langle \rho, \rho \rangle\\
	&\qquad-\frac{1}{8}\langle a,a\rangle +\frac{1}{8}\langle a^+, a^+\rangle +\frac{1}{8}\langle a^-, a^-\rangle,\\
	\mathsf{Y}^{\pm}_{\gamma}(z)&:= \mathsf{Y}_{\tau^\pm}\left(M^\pm; q, t, z\right),
\end{split}
\end{align}
with tuples
\[
\tau^\pm = \tau^\pm(\gamma) := \left(Q, b^\pm, \xi^\pm \right) \qquad \mbox{for $\gamma\in Q$,}
\]
and
\begin{align}
\label{eq:bpm}
b^+ =b^+(\gamma)&:= a^+ + 2 \gamma B^+_m, &
b^-=b^-(\gamma)&:=a^- + 2 \gamma B^-_1.
\end{align}
\end{theorem}


\begin{remark}
\label{rmk:orbitla}
The orbit of $[a^+]\oplus[a^-]$ under the action of $Q\langle\lambda\rangle$ from \eqref{eq:lamuaction} is
\begin{align*}
&Q\langle\lambda\rangle \left([a^+]\oplus[a^-]\right)\\
&=\left\{ [b^+]\oplus[b^-] : b^+= b^+(\gamma) \mbox{ and } b^-=b^-(\gamma) \mbox{ for some }\gamma\in Q\right\}.
\end{align*}
Hence, under the isomorphism \eqref{eq:spinciso}, all $[b^+]\oplus[b^-]$ for $\gamma \in Q$ are identified with the same $\spinc$-structure $[a]$ on $M$.
Indeed, the isomorphism \eqref{eq:spinciso} maps $[b^+]\oplus[b^-]$ to the class of
\[
b^+ \ast b^- = a^+ \ast a^- + 2\gamma\left(B^+_m \ast B^-_1 \right) \qquad \mbox{for $\gamma\in Q$}. 
\]
As $B^+_{m} \ast B^-_1 = B_{m}$, one has 
\[
b^+ \ast b^- \equiv a^+ \ast a^- \mbox{ mod }2Q\langle B_1, \dots, B_{s} \rangle.
\]
Hence, all $b^+ \ast b^-$ for $\gamma \in Q$ represent the same class $[a]$ on $M$.
\end{remark}


\begin{lemma}
\begin{enumerate}[(i)]

\item The quantity $\square$ is independent of the choice of representatives of $\mathrm{Spin}^c$-structures $a^\pm\in[a^\pm]$ and $a\in [a]$ subject to the constraint $a=a^+\ast a^-$, and so is the rest of the right-hand side of \eqref{eq:gluid}.

\item Moreover, $\square$ is invariant under the action of $Q\langle\lambda\rangle$ on $[a^+]\oplus[a^-]$, and so is the rest of the right-hand side of \eqref{eq:gluid}.

\item While $\square$ is not invariant under the action of $Q\langle\mu\rangle$ on $[a^+]\oplus[a^-]$, the whole right-hand side of \eqref{eq:gluid} is.
\end{enumerate}
\end{lemma}

\begin{proof}
For (i), consider $c^\pm \in \left[a^\pm\right]$, that is,
\begin{align*}
c^+ &= a^+ + 2 B^+ v^+ \qquad \mbox{for some $v^+\in Q^{m-1}\times \{0\}$,}\\
c^- &= a^- + 2 B^- v^- \qquad \mbox{for some $v^-\in \{0\}\times Q^{n-1}$.}
\end{align*}
Let $c:=c^+ \ast c^-$. Then  $c = a + 2B\left( v^+ \ast v^- \right)$, hence $c\in [a]$.
To verify the statement about $\square$ it is enough verify that
\[
\langle a,a\rangle -\langle a^+, a^+\rangle -\langle a^-, a^-\rangle
=\langle c,c\rangle -\langle c^+, c^+\rangle -\langle c^-, c^-\rangle.
\]
Expanding, one has
\begin{align}
\begin{split}
\label{eq:expaacc}
\langle c,c\rangle &= \langle a,a\rangle + 4 a^T \left(  v^+ \ast v^- \right) + 4 \left( v^+ \ast v^-\right)^T B \left( v^+ \ast v^-\right),\\
\langle c^\pm,c^\pm\rangle &= \langle a^\pm,a^\pm\rangle + 4 \left(a^\pm\right)^T  v^\pm + 4 \left( v^\pm\right)^T B^\pm v^\pm.
\end{split}
\end{align}
The statement follows from the identities
\begin{align*}
a^T \left(  v^+ \ast v^- \right) &= \left(a^+\right)^T  v^+ +  \left(a^-\right)^T  v^-,\\
\left( v^+ \ast v^-\right)^T B \left( v^+ \ast v^-\right) &= \left( v^+\right)^T B^+ v^+ + \left( v^-\right)^T B^- v^-
\end{align*}
which hold by linearity.

\smallskip

For (ii), consider $b^\pm$ in the orbit of $[a^+]\oplus[a^-]$ under the action of $Q\langle\lambda\rangle$, that is, $b^\pm = b^\pm (\gamma)$ for some $\gamma\in Q$ as in \eqref{eq:bpm}, see Remark \ref{rmk:orbitla}.
Let $b:=b^+\ast b^-$. Then $b=a+2\gamma B_m$.
To verify the statement about $\square$, it is enough verify that
\[
\langle a,a\rangle -\langle a^+, a^+\rangle -\langle a^-, a^-\rangle
=\langle b,b\rangle -\langle b^+, b^+\rangle -\langle b^-, b^-\rangle.
\]
Write 
\begin{align*}
b^+ &= a^+ +2\gamma B^+ e_m, &
b^- &= a^- +2\gamma B^- e_1, &
b &= a +2\gamma B e_m,
\end{align*}
where $e_i$ is the $i$-th standard basis element in the appropriate vector space.
Expanding as in \eqref{eq:expaacc}, the statement follows from the identities

\begin{align*}
a^T e_m &= \left(a^+\right)^T e_m +  \left(a^-\right)^T  e_1,\\
e_m^T B  e_m &= e_m^T B^+ e_m + e_1^T B^- e_1
\end{align*}
which hold by definition of the operation $\ast$ in \eqref{ast} and \eqref{eq:Bast}.

\smallskip

For (iii), consider $d^\pm$ in the orbit of $[a^+]\oplus[a^-]$ under the action of $Q\langle\mu\rangle$, that is,
$d^+ = a^+ + 2\delta e_m$ and $d^- = a^- -2\delta e_1$ for some $\delta\in Q$.
One has $d^+ \ast d^- = a$. A direct computation as in parts (i)-(ii) shows that 
\[
\langle a^+, a^+\rangle +\langle a^-, a^-\rangle \neq
\langle d^+, d^+\rangle +\langle d^-, d^-\rangle
\]
hence $\square$ is not invariant under the action of $Q\langle\mu\rangle$.
One can directly check the invariance of the whole right-hand side of \eqref{eq:gluid}. This will also follow from the proof of Theorem \ref{thm:gluing} below.
\end{proof}



\begin{proof}[Proof of Theorem \ref{thm:gluing}]
On each side of the identity \eqref{eq:gluid}, the series is obtained as a sum of contributions indexed by the representatives of the $\spinc$-structure. First, we give a bijection between these representatives, and then we argue that the corresponding contributions coincide.

The set of representatives of the $\spinc$-structure on the left-hand side is $a+2Q\langle B_1, \dots, B_{s} \rangle$. Select 
 such an element
\[
\ell = a+2Bv \qquad\mbox{for some } v\in Q^s.
\]
On the right-hand side, the set of representatives of the $\spinc$-structure is
indexed by $\gamma\in Q$ and representatives of the classes $[b^+]$ and $[b^-]$, that is, the set of representatives is
\[
\bigcup_{\gamma\in Q} \left( a^+ + 2 \gamma B^+_m + 2Q\langle B^+_1, \dots, B^+_{m-1} \rangle \right)\times 
\left( a^- + 2 \gamma B^-_1 + 2Q\langle B^-_2, \dots, B^-_{n} \rangle \right).
\]
We assign to $\ell$ an element of this set as follows.
Write $v=\left(v_1, \dots, v_s \right)$, and let $\gamma:=v_m$  be the $m$-th coordinate of $v$.
Define 
\begin{align}
\label{eq:vpm}
v^+ &:=\left(v_1, \dots, v_{m-1}, \gamma\right), & 
v^- &:=\left(\gamma, v_{m+1}, \dots, v^-_s\right).
\end{align}
One has
$v=v^+\ast v^- -\gamma e_m$ where $e_m$ is the $m$-th standard basis element, that is,
\begin{equation}
\label{eq:vvplusvminus}
v= \left( v^+_1, \dots, v^+_{m-1}, \gamma, v^-_2, \dots, v^-_n \right).
\end{equation}
Define 
\[
\ell^\pm:=a^\pm +2B^\pm v^\pm \in \left[b^\pm \right].
\]
This gives a map $\ell \mapsto (\gamma, \ell^+, \ell^-)$. 
One has $\ell =\ell^+ \ast \ell^-$. This follows from
\[
\ell^+\ast \ell^- = a^+ \ast a^- + 2 B^+ v^+ \ast B^-v^- = a + 2Bv = \ell.
\]
Vice versa, the map  
\[
(\gamma,\ell^+, \ell^-)\mapsto\ell:=\ell^+ \ast \ell^-
\]
is clearly the desired inverse.

Next, we compare the exponents of $q$. Since $\ell=a+2Bv$, one has
\begin{align}
\langle \ell, \ell\rangle &= \langle a, a\rangle + 4 \langle a, Bv\rangle + 4\langle Bv, Bv\rangle\nonumber\\
\label{eq:ellell}
&= \langle a, a\rangle + 4 a^T v + 4v^T Bv.
\end{align}
Similarly, since $\ell^\pm=a^\pm+2B^\pm v^\pm$, one has
\[
\langle \ell^\pm, \ell^\pm\rangle = \langle a^\pm, a^\pm\rangle + 4 \left(a^\pm\right)^T v^\pm + 4\left(v^\pm\right)^T B^\pm v^\pm.
\]
Since $a=a^+\ast a^-$ and using \eqref{eq:vvplusvminus}, one directly verifies that
\begin{equation}
\label{eq:astdotprop}
a^T v = \left(a^+\right)^T v^+ + \left(a^-\right)^T v^-.
\end{equation}
Similarly, using \eqref{eq:Bast}, one has
\begin{equation}
\label{eq:astBdotprop}
v^T Bv = \left(v^+\right)^T B^+ v^+ + \left(v^-\right)^T B^- v^-.
\end{equation}
Replacing \eqref{eq:astdotprop} and \eqref{eq:astBdotprop} in \eqref{eq:ellell} and simplifying, one obtains
\[
\langle \ell, \ell\rangle = \langle a,a\rangle - \langle a^+, a^+\rangle - \langle a^-, a^-\rangle + \langle \ell^+, \ell^+\rangle + \langle \ell^-, \ell^-\rangle.
\]
This together with the fact that $\mathrm{tr} \, B=\mathrm{tr} \, B^+ + \mathrm{tr} \, B^-$ implies that the exponent of $q$ for the contribution given by $\ell$ to the left-hand side matches the exponent of $q$ for the contribution given by $(\gamma, \ell^+, \ell^-)$ to the right-hand~side.

The matching of the exponents of $t$ is equivalent to the identity
\[
\xi^{-1}(\ell) = (\xi^+)^{-1}(\ell^+) + (\xi^-)^{-1}(\ell^-)
\]
which follows from $\ell=\ell^+\ast\ell^-$ and the fact that $\xi$ and $\xi^\pm$ all have equal value at the vertex $v_0$.
The matching of the exponents of $u$ follows similarly.

Finally, we compare the coefficients of the two sides. 
From the definition \eqref{eq:Kxn}, one has
\[
K_{\xi(v_0),\delta_0}(z) = K_{\xi(v_0),1+\delta^+_0}(z)\, K_{\xi(v_0),1+\delta^-_0}(z)
\]
where $\delta^\pm_0$ is the degree of $v^\pm_0$ in $\Gamma^\pm$ and $\delta_0 = \delta^+_0 + \delta^-_0$ is the degree of $v_0$ in $\Gamma$. 
Since $\ell= \ell^+ \ast \ell^-$, one has $\ell_0 = \ell_0^+ + \ell_0^-$, where $\ell_0$ is the component of $\ell$ corresponding to $v_0$, and similarly $\ell_0^\pm$ is the component of $\ell^\pm$ corresponding to $v_0^\pm$.
This implies
\begin{equation}
\label{eq:PwlPplusPminus}
\left[ K_{\xi(v_0),\delta_0}(z) \right]_{\ell_0} = \left[ z^{-\ell^+_0}K_{\xi(v_0),1+\delta^+_0}(z) \, z^{-\ell^-_0}K_{\xi(v_0),1+\delta^-_0}(z) \right]_0.
\end{equation}
The contribution given by vertices $v\neq v_0$ to the two sides equals
\[
\prod_{v\neq v_0} \left[ K_{\xi_v,\deg v}(z_v) \right]_{\ell_v}.
\]
Multiplying this on both sides of \eqref{eq:PwlPplusPminus} 
yields the equality of the coefficients 
\[
c_{\Gamma, \xi} (\ell) = \left[c_{\Gamma^+, \xi^+, v_0} (\ell^+) \, c_{\Gamma^-, \xi^-, v_0} (\ell^-) \right]_0
\]
on the two sides of the identity, 
hence the statement.
\end{proof}

