Neumann showed that two plumbed $3$-manifolds obtained from two forests $F_1$ and $F_2$ admit an orientation-preserving diffeomorphism if and only if $F_1$ and $F_2$ are related by a sequence of the moves from Figure \ref{fig:Neumann}
together with the splitting move ($\mathrm{D}_{e,u}$) in Figure \ref{fig:splitting} \cite{neumann2006invariant}.
There the weight $e$ is an arbitrary integer and $u\geq 1$. 
For $u\geq 2$, this move relates a tree with a disjoint union of trees $\Gamma_1, \dots, \Gamma_u$.

For $Q=A_1$, Ri showed that his $(q,t)$-series is not invariant under the splitting move \cite{ri2023refined}.
Here, we make explicit how our $(q,t)$-series in the case of arbitrary root lattices varies under the splitting move.

By Remark \ref{rmk:Du>=3} at the end of this section, it is enough to consider the case $u=2$.
Let $\Gamma_\circ$ be the plumbing tree on the left-hand side in Figure \ref{fig:splitting}. 
We show that the $(q,t)$-series for $\Gamma_\circ$ decomposes as a sum of product of certain restrictions of the $(q,t)$-series for $\Gamma_1$ and $\Gamma_2$ times an additional $(q,t)$-series. 

Let $v_0$ and $v_e$ be the vertices of $\Gamma_\circ$ weighted by $0$ and $e$, respectively. For $i\in\{1,2\}$, let $v^i_{*}$ be the vertex of $\Gamma_i$ incident to $v_e$ in $\Gamma_\circ$. The degree of $v^i_{*}$ in $\Gamma_\circ$ is one more than  its degree in $\Gamma_i$.

After possibly applying the Neumann move (A$-$) to $\Gamma_\circ$ along the edge incident to $v_e$ and $v^i_*$  and correspondingly the Neumann move (B$-$) to $\Gamma_i$, we can assume without loss of generality that $v^i_*$ has degree $1$ in $\Gamma_i$ and thus degree $2$ in $\Gamma_\circ$. Assume that $\Gamma_1$ and $\Gamma_2$ have invertible framing matrices. Then necessarily $\Gamma_\circ$ has invertible framing matrix as well --- see the following \eqref{eq:sigmasplitting}.
Also, assume that $\Gamma_\circ$, $\Gamma_1$ and $\Gamma_2$ are reduced.

Let $\tau_\circ=(Q, a^\circ, \xi_\circ)$ be a tuple for $\Gamma_\circ$ as in \eqref{eq:tau}.
Write $a^\circ$ as 
\[
a^\circ =\left(a^\circ_0, a^\circ_e, a^1_*-2\rho, a^1_\sharp,  a^2_*-2\rho, a^2_\sharp  \right).
\]
Here the  entry $a^\circ_0$ corresponds to $v_0$, the entry $a^\circ_e$ to $v_e$, the entries $a^i_*-2\rho$ to $v^i_{*}$, and the subtuple $a^i_\sharp$ to the remaining vertices of $\Gamma_i$. The map
\[
a^\circ \mapsto \left( a^1,  a^2\right)
\quad \mbox{with}\quad
a^i:=\left( a^i_*, a^i_\sharp \right)
\]
induces as isomorphism of the spaces of $\spinc$-structures 
\[
\spinc_Q\left(\Gamma_\circ\right)
\rightarrow 
\spinc_Q\left(\Gamma_1\right)\times \spinc_Q\left(\Gamma_2\right) 
\qquad 
\left[a^\circ\right] \mapsto
 \left[\left(a^1, a^2\right)\right]  .
\]

Next, we focus on the Weyl assignments.  
The Weyl assignment $\xi_\circ$ on $\Gamma_\circ$ uniquely determines Weyl assignments $\xi_ i$ on $\Gamma_i$ such that 
$\xi_\circ$ and $\xi_i$ have the same values on the vertices of $\Gamma_i$ other than $v^i_*$ for $i\in\{1,2\}$.
Since $v^i_*$ has degree $2$ in $\Gamma_\circ$, one has necessarily $\xi_\circ(v^i_*)=1_W$. On the other hand, $\xi_i(v^i_*)$ 
equals the value of $\xi_i$ on the vertex incident to $v^i_*$ in $\Gamma_i$ by \eqref{eq:forcingbridgescondition}.
Define $\tau_i:=(Q, a^i, \xi_i)$ for $i\in\{1,2\}$.

Next, for $w\in W$ and a plumbing tree $\Gamma$ whose vertices are ordered so that the first vertex is a leaf,
 define a restricted $(q,t)$-series for $\Gamma$ as
\[
\mathsf{Y}^w_{\tau}\left(\Gamma; q,t\right) :=
(-1)^{|\Delta^+| \,\pi}
q^{\frac{1}{2}(3\sigma-\mathrm{tr}\,B)\langle \rho, \rho \rangle} \sum_{\ell\in R^w}
c_{\Gamma, \xi} (\ell)
\,t^{\xi^{-1}(\ell)}
\,q^{-\frac{1}{8}\langle \ell, \ell\rangle}
\]
where
\[
R^w:=\left(a + 2BQ^s\right) \cap \left(\{2w(\rho)\}\times Q^{s-1}\right).
\]
In other words, 
the series $\mathsf{Y}^w_{\tau}\left(\Gamma; q,t\right)$ is obtained by restricting the sum in the series
$\mathsf{Y}_{\tau}\left(\Gamma; q,t\right)$ over only those $\ell\in a + 2BQ^s$ whose first entry (which corresponds to a leaf) is fixed equal to $2w(\rho)$. 

By definition, one has
\[
\mathsf{Y}_{\tau}\left(\Gamma; q,t\right) 
= \sum_{w\in W}
\mathsf{Y}^w_{\tau}\left(\Gamma; q,t\right).
\]
The various series $\mathsf{Y}^w_{\tau}\left(\Gamma; q,t\right)$ are not separately invariant under the Neumann moves from Figure \ref{fig:Neumann}.
We  use the restricted series in the following statement about the splitting move:

\begin{theorem}
\label{thm:Du2}
One has
\begin{align*}
\mathsf{Y}_{\tau_\circ}\left(\Gamma_\circ; q,t\right) 
=\,\,&
\sum_{w\in W}
\mathsf{Y}^w_{\tau_1}\left(\Gamma_1; q,t\right) \mathsf{Y}^w_{\tau_2}\left(\Gamma_2; q,t\right) \\
& \qquad 
\sum_{\alpha\in Q}
(-1)^{\ell(w)} k(\alpha)
\,q^{-\langle w(\rho), \rho + \alpha\rangle}
\,t^{d}
\end{align*}
where 
\begin{eqnarray*}
d&:=& -2\left(\xi_\circ(v_0)\right)^{-1}\xi_\circ(v_e)\,w(\rho)
-(2\rho+2\alpha)\\
&&- 2\left( \xi_1\left(v^1_*\right)\right)^{-1} \xi_\circ(v_e)\,w(\rho)
- 2\left( \xi_2\left(v^2_*\right)\right)^{-1} \xi_\circ(v_e)\,w(\rho).
\end{eqnarray*}
\end{theorem}

\begin{proof}
Let $x:=\xi_\circ(v_e)$. After replacing $w$ with $x^{-1}w$ and using the identities $\ell(x^{-1})=\ell(x)$ and $\langle x^{-1}w(\rho), 2\rho + 2\alpha\rangle = \langle w(\rho), x(2\rho + 2\alpha)\rangle$,
the statement is equivalent to
\begin{align}
\begin{split}
\label{eq:Du22}
\mathsf{Y}_{\tau_\circ}\left(\Gamma_\circ; q,t\right) 
=\,\,&
\sum_{w\in W}
\mathsf{Y}^w_{\tau_1}\left(\Gamma_1; q,t\right) \mathsf{Y}^w_{\tau_2}\left(\Gamma_2; q,t\right) \\
& \qquad 
\sum_{\alpha\in Q}
(-1)^{\ell(xw)} \, k(\alpha)
\,q^{-\langle w(\rho), x(\rho + \alpha)\rangle}
\,t^{d'}
\end{split}
\end{align}
where
\begin{align}
\begin{split}
\label{eq:d'}
d' :=&\,\, -2\left(\xi_\circ(v_0)\right)^{-1}w(\rho)
-(2\rho+2\alpha)\\
&- 2\left( \xi_1\left(v^1_*\right)\right)^{-1} w(\rho)
- 2\left( \xi_2\left(v^2_*\right)\right)^{-1} w(\rho).
\end{split}
\end{align}
We prove this version of the statement.

Let $B_\circ$ be the plumbing matrix for $\Gamma_\circ$ and $B_i$ for $\Gamma_i$ with $i\in\{1,2\}$.
A direct computation yields
\begin{align}
\begin{split}
\label{eq:sigmasplitting}
\pi\left( B_\circ\right) &= 1 + \pi\left( B_1\right) + \pi\left( B_2\right), \\
\sigma\left( B_\circ\right) &= \sigma\left( B_1\right) + \sigma\left( B_2\right),\\
\mathrm{tr}\left( B_\circ\right) &= e+ \mathrm{tr}\left( B_1\right) + \mathrm{tr}\left( B_2\right).
\end{split}
\end{align}
It follows that the factor in front of the sum in the series \eqref{eq:frontfactor} for $\Gamma_\circ$ has an extra factor 
with respect to the product of the analogous factors for $\Gamma_1$ and $\Gamma_2$
equal to
\begin{equation}
\label{eq:frontfactorRseries}
(-1)^{|\Delta^+|} \, q^{-\frac{1}{2}e \langle \rho, \rho \rangle}.
\end{equation}

For $i\in\{1,2\}$, the sum in the restricted $(q,t)$-series for $\Gamma_i$
is indexed by elements 
\[
\ell^i=\left( 2w(\rho), \ell^i_\sharp \right), 
\]
where $2w(\rho)$ is the entry corresponding to $v^i_{*}$, and $\ell^i_\sharp$ is the subtuple corresponding to the other vertices of $\Gamma_i$. 

For $w\in W$, $\alpha\in Q$, and
a pair of such $\ell^1$ and $\ell^2$, consider the tuple indexing the sum in the $(q,t)$-series for $\Gamma_\circ$ given by
\[
\ell^\circ =\left(-2w(\rho), -x(2\rho+2\alpha), 0, \ell^1_\sharp,  0, \ell^2_\sharp  \right).
\]
Here the  entry $-2w(\rho)$ corresponds to $v_0$, the entry $-x(2\rho+2\alpha)$ to $v_e$, the entries $0$ to $v^i_{*}$, and the subtuple $\ell^i_\sharp$ to the remaining vertices of $\Gamma_i$. Vice versa, the tuple $\ell^\circ$ uniquely determines $\left(w, \alpha, \ell^1, \ell^2\right)$, hence one has a bijection
\[
\ell^\circ \longleftrightarrow \left(w, \alpha, \ell^1, \ell^2 \right).
\]
In order to prove the statement, it suffices to verify that the contribution of $\ell^\circ$ to the left-hand side of \eqref{thm:Du2} equals the contribution of $\left(w, \alpha, \ell^1, \ell^2 \right)$ to its right-hand side. 
As the contribution to the  left-hand side of \eqref{thm:Du2} indexed by an element $\ell$ not of type $\ell^\circ$ vanishes, i.e., $c_{\Gamma_\circ, \xi_\circ} (\ell)=0$ in this case, this will conclude the proof.

\medskip

First, we verify the exponents of $q$.
Writing
\[
B^{-1}_1=\left(
\begin{array}{ccc}
a_{11} & \dots & a_{1n}\\
\vdots & \ddots & \vdots\\
a_{n 1} & \dots & a_{nn}
\end{array}
\right)
\quad\mbox{and}\quad
B^{-1}_2=\left(
\begin{array}{ccc}
b_{11} & \dots & b_{1m}\\
\vdots & \ddots & \vdots\\
b_{m 1} & \dots & b_{mm}
\end{array}
\right),
\]
a direct block matrix computation as in \cite[(5.4)]{ri2023refined} shows that 
\[
B^{-1}_\circ=\left(
\begin{array}{cccccccc}
a_{11}+b_{11}-e & 1 & -a_{11}& \dots & -a_{1n}& -b_{11}& \dots & -b_{1m}\\
1 & 0 & 0 & \dots &0&0&\dots& 0\\
-a_{1 1} & 0 & a_{11} & \dots & a_{1n} & 0 & \dots & 0\\
\vdots & \vdots & \vdots & \ddots & \vdots & \vdots & \ddots & \vdots\\
-a_{n 1} & 0 & a_{n1} & \dots & a_{nn} & 0 & \dots & 0\\
-b_{1 1} & 0 & 0 & \dots & 0& b_{11} & \dots & b_{1m} \\
\vdots & \vdots & \vdots & \ddots & \vdots & \vdots & \ddots & \vdots\\
-b_{m 1} & 0 & 0 & \dots & 0& b_{m1} & \dots & b_{mm} 
\end{array}
\right).
\]
This implies that
\[
\langle \ell^\circ, \ell^\circ\rangle = \langle \ell^1, \ell^1\rangle + \langle \ell^2, \ell^2\rangle -4e\, \langle \rho, \rho\rangle +4\langle w(\rho), x(2\rho+2\alpha)\rangle.
\]
After multiplying by $-\frac{1}{8}$ and considering the power of $q$ from \eqref{eq:frontfactorRseries}, it follows that the power of $q$ contributed by $\ell^\circ$ to the left-hand side of \eqref{eq:Du22} equals the power of $q$ contributed by $\left(w, \alpha, \ell^1, \ell^2 \right)$ to its right-hand side.

\medskip

Next, we verify the exponent of $t$. Starting from the left-hand side, the entries of $\ell^\circ$ corresponding to $v_0$ and $v_e$ contribute the following summand to the exponent of $t$:
\begin{align*}
&-2\left(\xi_\circ(v_0)\right)^{-1}w(\rho) -\left(\xi_\circ(v_e)\right)^{-1} x(2\rho+2\alpha) \\
&= -2\left(\xi_\circ(v_0)\right)^{-1}w(\rho) -(2\rho+2\alpha).
\end{align*}
Since the entries of $\ell^\circ$ corresponding to $v^1_*$ and $v^2_*$ are zero, they do not contribute to the exponent of $t$. 
On the right-hand side, since the entries of $\ell^1$ and $\ell^2$ corresponding to $v^1_*$ and $v^2_*$ are equal to $2w(\rho)$, these
 entries contribute the following summand to the exponent of $t$:
\[
2\left( \xi_1\left(v^1_*\right)\right)^{-1} w(\rho)
+2\left( \xi_2\left(v^2_*\right)\right)^{-1} w(\rho).
\]
Adding the contributions of the vertices of $\Gamma_i$ other than $v^i_*$ for $i\in\{1,2\}$ and taking into account the exponent $d'$ from \eqref{eq:d'}, 
it follows that the power of $t$ contributed by $\ell^\circ$ to the left-hand side of \eqref{eq:Du22} equals the power of $t$ contributed by $\left(w, \alpha, \ell^1, \ell^2 \right)$ to its right-hand side.

\medskip

Finally, we verify the equality of the coefficients. 
Start from the coefficient $c_{\Gamma_\circ, \xi_\circ} (\ell_\circ)$ computed as in \eqref{eq:cgammaxi}.
The entry of $\ell^\circ$ corresponding to $v_0$ contributes the factor $(-1)^{\ell(\iota w)}$. 
A simple consequence of the Weyl denominator formula yields 
\[
(-1)^{\ell(\iota w)}=(-1)^{|\Delta^+|}\,(-1)^{\ell(w)} \qquad \mbox{for $w\in W$}
\]
where $\iota$ is as in \eqref{eq:iota} --- this indeed follows by comparing the coefficients of $z^{2\iota w(\rho)}$ on the two sides of  \eqref{eq:Weyldenomformula}.
Moreover, since $K_{x,3}(z)$ is as in \eqref{eq:Ktwist}, the entry of $\ell^\circ$ corresponding to $v_e$ contributes the factor $(-1)^{\ell(x)}\, k(\alpha)$. Multiplying these two quantities, we obtain that the entries of $\ell^\circ$ corresponding to $v_0$ and $v_e$ contribute the factor
\[
(-1)^{|\Delta^+|}\,(-1)^{\ell(xw)} \, k(\alpha).
\]
The entries of $\ell^\circ$ corresponding to $v^1_*$ and $v^2_*$ are both zero and contribute factors of $1$. Correspondingly, the entry of $\ell^i$  equal to $2w(\rho)$ contributes the factor $(-1)^{\ell(w)}$ to $c_{\Gamma_i, \xi_i} (\ell^i)$. Multiplying by the entries corresponding to the vertices of $\Gamma_i$ other than $v^i_*$ for $i\in\{1,2\}$, yields 
\[
(-1)^{|\Delta^+|} \, c_{\Gamma_\circ, \xi_\circ} (\ell^\circ) = (-1)^{\ell(xw)} k(\alpha) \, c_{\Gamma_1, \xi_1} (\ell^1) \, c_{\Gamma_2, \xi_2} (\ell^2).
\]
Taking into account the factor contributed by \eqref{eq:frontfactorRseries}, it follows that 
 $\ell^\circ$ contributes the same $(q,t)$-monomial to the left-hand side of \eqref{eq:Du22} as  $\left(w, \alpha, \ell^1, \ell^2 \right)$ to its right-hand side. Hence the statement.
\end{proof}


\begin{remark}
\label{rmk:Du>=3}
When $u=1$, the Neumann move ($\mathrm{D}_{e,u}$) follows from the other five Neumann moves amongst trees. Indeed, when $e=0$, the move ($\mathrm{D}_{0,1}$) follows from move (C). When $e>0$, the move ($\mathrm{D}_{e,1}$) follows by applying the moves (A$-$), (B$-$), and then ($\mathrm{D}_{e-1,1}$). When $e<0$, the move ($\mathrm{D}_{e,1}$) follows by applying the moves (A$+$), (B$+$), and then ($\mathrm{D}_{e+1,1}$). Thus the move ($\mathrm{D}_{e,1}$) follows by induction on $e$.

Also, we remark that the case $u\geq 3$ follows by induction on the case $u=2$ and the other Neumann moves amongst trees. 
Hence the emphasis on the $u=2$ case here.
\end{remark}


